comms.text:
@1 אִלֵין פִּתְגָמַיָא דִי מַלִיל מֹשֶׁה עִם כָּל יִשְׂרָאֵל בְּעִבְרָא דְיַרְדְנָא אוֹכַח יָתְהוֹן עַל דְחָבוּ בְמַדְבְּרָא וְעַל דְאַרְגִיזוּ בְמֵישְׁרָא לָקֳבֵל יַם סוּף בְּפָארָן אִתַּפָּלוּ עַל מַנָא וּבַחֲצֵרוֹת אַרְגִיזוּ עַל בִּשְׂרָא וְעַל דַעֲבָדוּ עֵגַל דִדְהָב:
@2 מַהֲלַךְ חָד עֲשַׂר יוֹמִין מֵחוֹרֵב אוֹרַח טּוּרָא דְשֵׂעִיר עַד רְקַם גֵיאָה:
@3 וַהֲוָה בְּאַרְבְּעִין שְׁנִין בְּחַד עֲשַׂר יַרְחָא בְּחַד לְיַרְחָא מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקִיד יְיָ יָתֵהּ לְוָתְהוֹן:
@4 בָּתַר דִמְחָא יָת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דְיָתֵב בְּחֶשְׁבּוֹן וְיָת עוֹג מַלְכָּא דְמַתְנָן דְיָתֵב בְּעַשְׁתָּרוֹת בְּאֶדְרֶעִי:
@5 בְּעִבְרָא דְיַרְדְנָא בְּאַרְעָא דְמוֹאָב שָׁרֵי מֹשֶׁה פָּרֵשׁ יָת אוּלְפַן אוֹרַיְתָא הָדָא לְמֵימָר:
@6 יְיָ אֱלָהָנָא מַלִיל עִמָנָא בְּחוֹרֵב לְמֵימָר סַגִי לְכוֹן דִיתֶבְתּוּן בְּטוּרָא הָדֵין:
@7 אִתְפְּנוּ וְטוּלוּ לְכוֹן וְעוּלוּ לְטּוּרָא דֶאֱמוֹרָאָה וּלְכָל מָגִירוֹהִי בְּמֵישְׁרַיָא בְטוּרָא וּבִשְׁפֶלְתָּא וּבִדְרוֹמָא וּבִסְפַר יַמָא אַרְעָא דִכְנַעֲנָאָה וְלִבְנָן עַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@8 חֲזֵי דִיהָבִית קֳדָמֵיכוֹן יָת אַרְעָא עוּלוּ וְאַחֲסִינוּ יָת אַרְעָא דִי קַיַם יְיָ לַאֲבָהָתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן בַּתְרֵיהוֹן:
@9 וַאֲמָרִית לְכוֹן בְּעִדָנָא הַהִיא לְמֵימָר לֵית אֲנָא יָכִיל בִּלְחוֹדִי לְסוֹבָרָא יָתְכוֹן:
@10 יְיָ אֱלָהָכוֹן אַסְגֵי יָתְכוֹן וְהָא אִיתֵיכוֹן יוֹמָא דֵין כְּכוֹכְבֵי שְׁמַיָא לִסְגֵי:
@11 יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יוֹסֵף עֲלֵיכוֹן כְּוָתְכוֹן אֲלַף זִמְנִין וִיבָרֵךְ יָתְכוֹן כְּמָא דִי מַלִיל לְכוֹן:
@12 אֶכְדֵין אֵסוֹבַר בִּלְחוֹדִי טָרְחֲכוֹן וְעִסְקֵיכוֹן וְדִינְכוֹן:
@13 הָבוּ לְכוֹן גֻבְרִין חַכִּימִין וְסוּכְלְתָנוּן וּמַדְעָן לְשִׁבְטֵיכוֹן וֶאֱמַנִנוּן רֵישִׁין עֲלֵיכוֹן:
@14 וַאֲתֶבְתּוּן יָתִי וַאֲמַרְתּוּן תַּקִין פִּתְגָמָא דִי מַלֶלְתָּא לְמֶעְבָּד:
@15 וּדְבָרִית יָת רֵישֵׁי שִׁבְטֵיכוֹן גֻבְרִין חַכִּימִין וּמַדְעָן וּמַנֵתִי יָתְהוֹן רֵישִׁין עֲלֵיכוֹן רַבָּנֵי אַלְפִין וְרַבָּנֵי מָאוָתָא וְרַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא וְסָרְכִין לְשִׁבְטֵיכוֹן:
@16 וּפַקֵדִית יָת דַיָנֵיכוֹן בְּעִדָנָא הַהִיא לְמֵימָר שְׁמָעוּ בֵּין אַחֵיכוֹן וּתְדוּנוּן קוּשְׁטָא בֵּין גַבְרָא וּבֵין אֲחוּהִי וּבֵין גִיוֹרֵהּ:
@17 לָא תִשְׁתְּמוֹדְעוּן אַפִּין בְּדִינָא מִלֵי זְעֵירָא כְרַבָּא תִּשְׁמְעוּן לָא תִדְחֲלוּן מִן קֳדָם גַבְרָא אֲרֵי דִינָא דַיְיָ הוּא וּפִתְגָמָא דִי יִקְשֵׁי מִנְכוֹן תְּקָרְבוּן לְוָתִי וְאֶשְׁמְעִנֵהּ:
@18 וּפַקֵדִית יָתְכוֹן בְּעִדָנָא הַהִיא יָת כָּל פִּתְגָמַיָא דִי תַעְבְּדוּן:
@19 וּנְטַלְנָא מֵחוֹרֵב וְהַלִיכְנָא יָת כָּל מַדְבְּרָא רַבָּא וּדְחִילָא הַהוּא דִי חֲזֵיתוּן אוֹרַח טוּרָא דֶאֱמוֹרָאָה כְּמָא דִי פַקִיד יְיָ אֱלָהָנָא יָתָנָא וַאֲתֵינָא עַד רְקַם גֵיאָה:
@20 וַאֲמָרִית לְכוֹן אֲתֵיתוּן עַד טוּרָא דֶאֱמוֹרָאָה דַיְיָ אֱלָהָנָא יָהֵיב לָנָא:
@21 חֲזֵי יְהַב יְיָ אֱלָהָךְ קֳדָמָךְ יָת אַרְעָא סַק אַחֲסֵין כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ לָא תִדְחַל וְלָא תִתְּבָּר:
@22 וּקְרֶבְתּוּן לְוָתִי כֻּלְכוֹן וַאֲמַרְתּוּן נִשְׁלַח גֻבְרִין קֳדָמָנָא וִיאַלְלוּן לָנָא יָת אַרְעָא וִיתִיבוּן יָתָנָא פִּתְגָמָא יָת אָרְחָא דִי נִסֵק בַּהּ וְיָת קִרְוַיָא דִי נֵעוֹל לְהֵן:
@23 וּשְׁפַר בְּעֵינַי פִּתְגָמָא וּדְבָרִית מִנְכוֹן תְּרֵין עֲשַׂר גֻבְרִין גַבְרָא חַד לְשִׁבְטָא:
@24 וְאִתְפְּנִיוּ וּסְלִיקוּ לְטוּרָא וַאֲתוֹ עַד נַחֲלָא דְאַתְכָּלָא וְאַלִילוּ יָתַהּ:
@25 וּנְסִיבוּ בִידֵיהוֹן מֵאִבָּא דְאַרְעָא וְאַחִיתוּ לָנָא וַאֲתִיבוּ יָתָנָא פִּתְגָמָא וַאֲמָרוּ טָבָא אַרְעָא דַיְיָ אֱלָהָנָא יָהֵיב לָנָא:
@26 וְלָא אֲבִיתוּן לְמִסַק וְסָרֶבְתּוּן עַל מֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@27 וְאִתְרַעַמְתּוּן בְּמַשְׁכְּנֵיכוֹן וַאֲמַרְתּוּן בִּדְסָנֵי יְיָ יָתָנָא אַפְּקָנָא מֵאַרְעָא דְמִצְרָיִם לְמִמְסַר יָתָנָא בִּידָא דֶאֱמוֹרָאָה לְשֵׁיצָיוּתָנָא:
@28 לְאָן אֲנַחְנָא סָלְקִין אֲחָנָא תְבָרוּ יָת לִבָּנָא לְמֵימַר עַם רַב וְתַקִיף מִנָנָא קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא וְאַף בְּנֵי גִבָּרָאֵי חֲזֵינָא תַמָן:
@29 וַאֲמָרִית לְכוֹן לָא תִתָּבְרוּן וְלָא תִדְחֲלוּן מִנְהוֹן:
@30 יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן הוּא יְגִיחַ לְכוֹן כְּכֹל דִי עֲבַד עִמְכוֹן בְּמִצְרַיִם לְעֵינֵיכוֹן:
@31 וּבְמַדְבְּרָא דִי חֲזֵיתָא דִי סוֹבְרָךְ יְיָ אֱלָהָךְ כְּמָא דִי מִסוֹבַר גַבְרָא יָת בְּרֵהּ בְּכָל אָרְחָא דִי הַלֶכְתּוּן עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@32 וּבְפִתְגָמָא הָדֵין לֵיתֵיכוֹן מְהֵימְנִין בְּמֵ ימְ רָא דַיְיָ אֱלָהֲכוֹן:
@33 דִי מְדַבֵּר קֳדָמֵיכוֹן בְּאָרְחָא לְאַתְקְנָאָה לְכוֹן אֲתַר בֵּית מֵישְׁרִי לְאַשְׁרָיוּתְכוֹן בְּעַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא לְאַחֲזָיוּתְכוֹן בְּאָרְחָא דִי תְהָכוּן בַּהּ וּבְעַמוּדָא דַעֲנָנָא בִּימָמָא:
@34 וּשְׁמִיעַ קֳדָם יְיָ יָת קַל פִּתְגָמֵיכוֹן וּרְגֵז וְקַיַם לְמֵימָר:
@35 אִם יֶחֱזֵי גְבַר בְּגֻבְרַיָא הָאִלֵין דָרָא בִישָׁא הָדֵין יָת אַרְעָא טַבְתָא דִי קַיֵמִית לְמִתַּן לַאֲבָהָתְכוֹן:
@36 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה הוּא יֶחְזִנַהּ וְלֵהּ אֶתֵּן יָת אַרְעָא דִי דְרַךְ בַּהּ וְלִבְנוֹהִי חֲלַף דִי אַשְׁלִים בָּתַר דַחַלְתָּא דַיְיָ:
@37 אַף עֲלַי הֲוָה רְגַז מִן קֳדָם יְיָ בְּדִילְכוֹן לְמֵימָר אַף אַתְּ לָא תֵיעוֹל תַּמָן:
@38 יְהוֹשֻׁעַ בַּר נוּן דְקָאֵים קֳדָמָךְ הוּא יֵיעוֹל תַּמָן יָתֵהּ תַּקֵף אֲרֵי הוּא יַחְסְנִנַהּ לְיִשְׂרָאֵל:
@39 וְטַפְלְכוֹן דִי אֲמַרְתּוּן לְבִזָא יְהוֹן וּבְנֵיכוֹן דִי לָא יְדָעוּ יוֹמָא דֵין טַב וּבִישׁ אִנוּן יַעֲלוּן לְתַמָן וּלְהוֹן אֶתְּנִנַהּ וְאִנוּן יֵירְתֻנַהּ:
@40 וְאַתּוּן אִתְפְּנִיוּ לְכוֹן וְטוּלוּ לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף:
@41 וַאֲתֶבְתּוּן וַאֲמַרְתּוּן לִי חַבְנָא קֳדָם יְיָ אֲנַחְנָא נִיסַק וּנְגִיחַ קְרָב כְּכֹל דִי פַקְדָנָא יְיָ אֱלָהָנָא וְזָרֶזְתּוּן גְבַר יָת מָנֵי קְרָבֵהּ וְשָׁרֵיתוּן לְמֵיסַק לְטּוּרָא:
@42 וַאֲמַר יְיָ לִי אֱמַר לְהוֹן לָא תִסְקוּן וְלָא תְגִחוּן קְרָב אֲרֵי לֵית שְׁכִינְתִּי שָׁרְיָא בֵינֵיכוֹן וְלָא תִּתָּבְרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@43 וּמַלֵלִית עִמְכוֹן וְלָא קַבֶּלְתּוּן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ וְאַרְשַׁעְתּוּן וּסְלֶקְתּוּן לְטוּרָא:
@44 וּנְפַק אֱמֹרָאָה דְיָתֵב בְּטוּרָא הַהוּא לְקַדָמוּתְכוֹן וּרְדָפוּ יָתְכוֹן כְּמָא דִי נַתְּזָן דַבַּרְיָתָא וּטְרָדוּ יָתְכוֹן בְּשֵׂעִיר עַד חָרְמָה:
@45 וְתַבְתּוּן וּבְכִיתוּן קֳדָם יְיָ וְלָא קַבִּיל יְיָ צְלוֹתְכוֹן וְלָא אַצֵית לְמִלֵיכוֹן:
@46 וִיתֶבְתּוּן בִּרְקָם יוֹמִין סַגִיאִין כְּיוֹמַיָא דִי יְתֶבְתּוּן:
@47 וְאִתְפְּנֵינָא וּנְטַלְנָא לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף כְּמָא דִי מַלִיל יְיָ עִמִי וְאַקֵפְנָא יָת טוּרָא דְשֵׂעִיר יוֹמִין סַגִיאִין:
@48 וַאֲמַר יְיָ לִי לְמֵימָר:
@49 סַגִי לְכוֹן דְאַקֶפְתּוּן יָת טוּרָא הָדֵין אִתְפְּנִיוּ לְכוֹן צִפּוּנָא:
@50 וְיָת עַמָא פַּקֵד לְמֵימַר אַתּוּן עָבְרִין בִּתְחוּם אֲחוּכוֹן בְּנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר וְיִדְחֲלוּן מִנְכוֹן וְתִסְתַּמְרוּן לַחֲדָא:
@51 לָא תִתְגָרוּן בְּהוֹן אֲרֵי לָא אֶתֵּן לְכוֹן מֵאַרְעֲהוֹן עַד מִדְרַךְ פַּרְסַת רִגְלָא אֲרֵי יְרֻתָּא לְעֵשָׂו יְהָבִית יָת טוּרָא דְשֵׂעִיר:
@52 עִבּוּרָא תִזְבְּנוּן מִנְהוֹן בְּכַסְפָּא וְתֵיכְלוּן וְאַף מַיָא תִּכְרוּן מִנְהוֹן בְּכַסְפָּא וְתִשְׁתּוּן:
@53 אֲרֵי יְיָ אֱלָהָךְ בֵּרְכָךְ בְּכָל עֹבַד יְדָךְ סַפֶּק לָךְ צָרְכָּךְ בְּמֶהָכָךְ יָת מַדְבְּרָא רַבָּא הָדֵין דְנַן אַרְבְּעִין שְׁנִין מֵימְרָא דַיְיָ אֱלָהָךְ בְּסַעֲדָךְ לָא מְנַעְתָּא מִדָעַם:
@54 וַעֲבַרְנָא מִלְוַת אֲחוּנָא בְנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר מֵאוֹרַח מֵישְׁרָא מֵאֵילַת וּמֶעְצְיוֹן גָבֶר וְאִתְפְּנֵינָא וַעֲבַרְנָא אוֹרַח מַדְבְּרָא דְמוֹאָב:
@55 וַאֲמַר יְיָ לִי לָא תְצוּר עַל מוֹאַבָאֵי וְלָא תִתְגָרֵי לְמֶעְבַּד עִמְהוֹן קְרָב אֲרֵי לָא אֶתֵּן לָךְ מֵאַרְעֵהּ יְרֻתָּא אֲרֵי לִבְנֵי לוֹט יְהָבִית יָת לְחָיָת יְרֻתָּא:
@56 אֵימְתָנֵי מִלְקַדְמִין יְתִיבוּ בַהּ עַם רַב וְסַגִי וְתַקִיף כְּגִבָּרַיָא:
@57 גִבָּרִין מִתְחַשְׁבִין אַף אִנוּן כְּגִבָּרַיָא וּמוֹאַבָאֵי קְרַן לְהוֹן אֵימְתָנֵי:
@58 וּבְשֵׂעִיר יְתִיבוּ חֹרָאֵי מִלְקַדְמִין וּבְנֵי עֵשָׂו תָּרֵכֻנוּן וְשֵׁצָיֻנוּן מִקֳדָמֵיהוֹן וִיתִיבוּ בְּאַתְרֵהוֹן כְּמָא דִי עֲבַד יִשְׂרָאֵל לְאַרְעָא יְרֻתָּתֵהּ דִיהַב יְיָ לְהוֹן:
@59 כְּעַן קוּמוּ וְעִבָרוּ לְכוֹן יָת נַחֲלָא דְזָרֶד וַעֲבַרְנָא יָת נַחֲלָא דְזָרֶד:
@60 וְיוֹמַיָא דִי הַלֶכְנָא מֵרְקַם גֵיאָה עַד דִי עֲבַרְנָא יָת נַחֲלָא דְזֶרֶד תְּלָתִין וְתַמְנֵי שְׁנִין עַד דְסַף כָּל דָרָא גֻבְרֵי מְגִיחֵי קְרָבָא מִגוֹ מַשְׁרִיתָא כְּמָא דִי קַיִים יְיָ לְהוֹן:
@61 וְאַף מָחָא מִן קֳדָם יְיָ הֲוַת בְּהוֹן לְשֵׁצָיוּתְהוֹן מִגוֹ מַשְׁרִיתָא עַד דִשְׁלִימוּ:
@62 וַהֲוָה כַּד שְׁלִימוּ כָּל גֻבְרֵי מְגִיחֵי קְרָבָא לִמְמַת מִגוֹ עַמָא:
@63 וּמַלִיל יְיָ עִמִי לְמֵימָר:
@64 אַתְּ עָבֵר יוֹמָא דֵין יָת תְּחוּם מוֹאָב יָת לְחָיָת:
@65 וְתִקְרַב לָקֳבֵל בְּנֵי עַמוֹן לָא תְצוּר עֲלֵיהוֹן וְלָא תִתְגָרֵי לְמֶעְבַּד עִמְהוֹן קְרָב אֲרֵי לָא אֶתֵּן מֵאַרְעָא בְנֵי עַמוֹן לָךְ יְרֻתָּא אֲרֵי לִבְנֵי לוֹט יְהָבִיתַּהּ יְרֻתָּא:
@66 אַרְעָא גִבָּרַיָא מִתְחַשְׁבָא אַף הִיא גִבָּרִין יָתִיבוּ בַהּ מִלְקַדְמִין וְעַמוֹנָאֵי קְרַן לְהוֹן חֻשְׁבָּנֵי:
@67 עַם רַב וְסַגִי וְתַקִיף כְּגִבְּרַיָא וְשֵׁצִנוּן יְיָ מִקֳדָמֵ יהוֹן וְתָרֵכֻנוּן וִיתִיבוּ בְאַתְרֵיהוֹן:
@68 כְּמָא דִי עֲבַד לִבְנֵי עֵשָׂו דְיָתְבוּן בְּשֵׂעִיר דִי שֵׁצֵי יָת חוֹרָאֵי מִקֳדָמֵיהוֹן וְתָרֵכִנוּן וִיתִיבוּ בְאַתְרֵיהוֹן עַד יוֹמָא הָדֵין:
@69 וְעַוָאֵי דְיָתְבִין בִּדְפִיחַ עַד עַזָה קַפּוּטְּקָאֵי דִנְפָקוּ מִקַפּוּטְקַיָא שֵׁצָיוּנוּן וִיתִיבוּ בְאַתְרֵיהוֹן:
@70 קוּמוּ טוּלוּ וְעִבָרוּ יָת נַחֲלָא דְאַרְנוֹן חֲזִי דִמְסָרִית בִּידָךְ יָת סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן אֱמוֹרָאָה וְיָת אַרְעֵהּ שְׁרֵי לְתָרָכוּתֵהּ וְאִתְגָרֵי לְמֶעְבַּד עִמֵהּ קְרָבָא:
@71 יוֹמָא הָדֵין אֱשָׁרֵי לְמִתַּן זְעֻתָּךְ וְדַחַלְתָּךְ עַל אַפֵּי עַמְמַיָא דִי תְחוֹת כָּל שְׁמַיָא דִי יִשְׁמְעוּן שִׁמְעָךְ וִיזוּעוּן וְיִדְחֲלוּן מִן קֳדָמָךְ:
@72 וּשְׁלָחִית אִזְגַדִין מִמַדְבְּרָא דִקְדֵמוֹת לְוָת סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן פִתְגָמֵי שְׁלָמָא לְמֵימָר:
@73 אֵעִבַר בְּאַרְעָךְ בְּאָרְחָא בְּאָרְחָא אֵזֵל לָא אֶסְטֵי יַמִינָא וּשְׂמָאלָא:
@74 עִבוּרָא בְּכַסְפָּא תְּזַבֶּן לִי וְאֵיכוּל וּמַיָא בְּכַסְפָּא תִּתֶּן לִי וְאֶשְׁתֵּי לְחוֹד אֵעִבַר בְּרַגְלָי:
@75 כְּמָא דִי עֲבָדוּ לִי בְּנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר וּמוֹאָבָאֵי דְיָתְבִין בִּלְחָיָת עַד דְאֵעִבַר יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָנָא יָהֵב לָנָא:
@76 וְלָא אָבֵי סִיחֹן מַלְכָּא דְחֶשְׁבּוֹן לְמִשְׁבְּקָנָא לְמֶעְבַּר בִּתְחוּמֵהּ אֲרֵי אַקְשִׁי יְיָ אֱלָהָךְ יָת רוּחֵהּ וְתַקִיף יָת לִבֵּהּ בְּדִיל לְמִמְסְרֵהּ בִּידָךְ כְּיוֹמָא הָדֵין:
@77 וַאֲמַר יְיָ לִי חֲזֵי שָׁרֵיתִי לְמִמְסַר קֳדָמָךְ יָת סִיחֹן וְיָת אַרְעֵהּ שְׁרֵי לְתָרָכוּתֵהּ לְמֵירַת יָת אַרְעֵהּ:
@78 וּנְפַק סִיחֹן לְקַדָמוּתָנָא הוּא וְכָל עַמֵהּ לַאֲגָחָא קְרָבָא לְיָהַץ:
@79 וּמָסְרֵהּ יְיָ אֱלָהָנָא קֳדָמָנָא וּמְחֵנָא יָתֵהּ וְיָת בְּנוֹהִי וְיָת כָּל עַמֵהּ:
@80 וּכְבַשְׁנָא יָת כָּל קִרְווֹהִי בְּעִדָנָא הַהִיא וְגַמַרְנָא יָת כָּל קִרְוֵי גֻבְרַיָא וּנְשַׁיָא וְטַפְלָא לָא אַשְׁאַרְנָא מְשֵׁזִבִ:
@81 לְחוֹד בְּעִירָא בַּזָנָא לָנָא וַעֲדִי קִרְוַיָא דִי כְבַשְׁנָא:
@82 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְקַרְתָּא דִי בְנַחֲלָא וְעַד גִלְעָד לָא הֲוַת קַרְתָּא דִי תְקֵפַת מִנָנָא יָת כֹּלָא מְסַר יְיָ אֱלָהָנָא קֳדָמָנָא:
@83 לְחוֹד לְאַרְעָא בְנֵי עַמוֹן לָא קְרֶבְתָּא כָּל כֵּיף נַחֲלָא יוּבְקָא וְקִרְוֵי טוּרָא וְכֹל דִי פַקִיד יְיָ אֱלָהָנָא:
@84 וְאִתְפְּנֵינָא וּסְלֶקְנָא אֹרַח דְמַתְנָן וּנְפַק עוֹג מַלְכָּא דְמַתְנָן לְקַדָמוּתָנָא הוּא וְכָל עַמֵהּ לַאֲגָחָא קְרָבָא אֶדְרֶעִי:
@85 וַאֲמַר יְיָ לִי לָא תִדְחַל מִנֵיהּ אֲרֵי בִידָךְ מְסָרִית יָתֵהּ וְיָת כָּל עַמֵהּ וְיָת אַרְעֵהּ ותַעְבֶּד לֵהּ כְּמָא דִי עֲבַדְתָּא לְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן:
@86 וּמְסַר יְיָ אֱלָהָנָא בִּידָנָא אַף יָת עוֹג מַלְכָּא דְמַתְנָן וְיָת כֹּל עַמֵהּ וּמְחִנוֹהִי עַד דְלָא אִשְׁתָּאַר לֵהּ מְשֵׁזֵב:
@87 וּכְבַשְׁנָא יָת כָּל קִרְווֹהִי בְּעִדָנָא הַהִיא לָא הֲוַת קַרְתָּא דִי לָא נְסִבְנָא מִנְהוֹן שִׁתִּין קִרְוִין כָּל בֵּית פָּלָךְ טְרָכוֹנָא מַלְכוּתָא דְעוֹג בְּמַתְנָן:
@88 כָּל אִלֵין קִרְוִין כְּרִיכָן מַקְפָן שׁוּר רָם דִילְהֶן דָשִׁין וְעַבְּרִין בַּר מִקִרְוֵי פַּצְחַיָא סַגִי לַחֲדָא:
@89 וְגַמַרְנָא יָתְהוֹן כְּמָא דִי עֲבַדְנָא לְסִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן גַמַר כָּל קִרְוֵי גֻבְרַיָא נְשַׁיָא וְטַפְלָא:
@90 וְכָל בְּעִירָא וַעֲדִי קִרְוַיָא בַּזָנָא לָנָא:
@91 וּנְסִבְנָא בְּעִדָנָא הַהִיא יָת אַרְעָא מִיַד תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִנַחֲלָא דְאַרְנֹן עַד טוּרָא דְחֶרְמוֹן:
@92 צִידֹנָאֵי קְרָאָן לְחֶרְמוֹן סִרְיֹן וֶאֱמֹרָאֵי קְרָאָן לֵהּ טוּר תַּלְגָא:
@93 כֹּל קִרְוֵי מֵישְׁרָא וְכָל גִלְעָד וְכָל מַתְנָן עַד סַלְכָה וְאֶדְרֶעִי קִרְוֵי מַלְכוּתָא דְעוֹג בְּמַתְנָן:
@94 אֲרֵי לְחוֹד עוֹג מַלְכָּא דְמַתְנָן אִשְׁתָּאַר מִשְׁאָר גִבָּרַיָא הָא עַרְסֵהּ עַרְסָא דְפַרְזְלָא הֲלָא הִיא בְּרַבַּת בְּנֵי עַמוֹן תְּשַׁע אַמִין אָרְכַּהּ וְאַרְבַּע אַמִין פְּתָיַהּ בְּאַמַת מְלַךְ:
@95 וְיָת אַרְעָא הָדָא יְרִיתְנָא בְּעִדָנָא הַהִיא מֵעֲרֹעֵר דִי עַל נַחֲלָא דְאַרְנֹן וּפַלְגוּת טּוּרָא דְגִלְעָד וְקִרְווֹהִי יְהָבִית לְשִׁבְטָא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד:
@96 וּשְׁאָר גִלְעָד וְכָל מַתְנָן מַלְכוּתָא דְעוֹג יְהָבִית לְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה כֹּל בֵּית פָּלַךְ טְרָכוֹנָא לְכָל מַתְנָן הַהוּא מִתְקְרֵי אַרְעָא גִבָּרַיָא:
@97 יָאִיר בַּר מְנַשֶׁה נְסִיב יָת כָּל בֵּית פְּלַךְ טְרָכוֹנָא עַד תְּחוּם גְשׁוּרָאָה וְאַפְקֵירוֹס וּקְרָא יָתְהוֹן עַל שְׁמֵהּ יָת מַתְנָן כַּפְרָנֵי יָאִיר עַד יוֹמָא הָדֵין:
@98 וּלְמָכִיר יְהָבִית יָת גִלְעָד:
@99 וּלְשִׁבְטָא דִרְאוּבֵן וּלְשִׁבְטָּא דְגָד יְהָּבִית מִן גִלְעָד וְעַד נַחֲלָא דְאַרְנֹן גוֹ נַחֲלָא וּתְחוּם וְעַד יוּבְקָא דְנַחֲלָא תְּחוּם בְּנֵי עַמוֹן:
@100 וּמֵישְׁרָא וְיַרְדְנָא וּתְחוּמֵהּ מִגֵנוֹסַר וְעַד יַמָא דְמֵישְׁרָא יַמָא דְמִלְחָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא מָדִינְחָא:
@101 וּפַקֵדִית יָתְכוֹן בְּעִדָנָא הַהִיא לְמֵימָר יְיָ אֱלָהֲכוֹן יְהַב לְכוֹן יָת אַרְעָא הָדָא לְמֵירְתַהּ מְזָרְזִין תַּעְבְּרוּן קֳדָם אֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל כָּל מְזָרְזֵי חֵילָא:
@102 לְחוֹד נְשֵׁיכוֹן וְטַפְלְכוֹן וּבְעִירְכוֹן יְדַעְנָא אֲרֵי בְעִיר סַגִי לְכוֹן יֵתְבוּן בְּקִרְוֵיכוֹן דִי יְהָבִית לְכוֹן:
@103 עַד דִי יְנִיחַ יְיָ לַאֲחֵיכוֹן כְּוָתְכוֹן וְיֵרְתוּן אַף אִנוּן יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְהוֹן בְּעִבְרָא דְיַרְדְנָא וּתְתוּבוּן גְבַר לִירֻתְּתֵהּ דִי יְהָבִית לְכוֹן:
@104 וְיָת יְהוֹשׁוּעַ פַּקֵדִית בְּעִדָנָא הַהִיא לְמֵימָר עֵינָיךְ חֲזָאָן יָת כָּל דִי עֲבַד יְיָ אֱלָהֲכוֹן לִתְרֵין מַלְכַיָא הָאִלֵין כֵּן יַעְבֵּד יְיָ לְכָל מַלְכְּוָתָא דִי אַתְּ עָבֵר לְתַמָן:
@105 לָא תִדְחֲלוּן מִנְהוֹן אֲרֵי יְיָ אֱלָהָכוֹן מֵימְרֵהּ מְגִיחַ לְכוֹן: ססס:
@106 וְצַלֵיתִי קֳדָם יְיָ בְּעִדָנָא הַהִיא לְמֵימָר:
@107 יְיָ אֱלֹהִים אַתְּ שָׁרֵיתָא לְאַחֲזָאָה יָת עַבְדָךְ יָת רְבוּתָךְ וְיָת יְדָךְ תַּקֶפְתָּא דִי אַתְּ הוּא אֱלָהָא דִשְׁכִנְתָּךְ בִּשְׁמַיָא מִלְעֵלָא וְשַׁלִיט בְּאַרְעָא וְלֵית דְיַעְבֵּד כְּעוֹבְדָיךְ וּכְגִבָּרְתָּךְ:
@108 אֵעִבַר כְּעַן וְאֶחֱזֵי יָת אַרְעָא טַבְתָא דִּי בְּעִבְרָא דְיַרְדְנָא טוּרָא טָּבָא הָדֵין וּבֵית מַקְדָשָׁא:
@109 וַהֲוָה רְגַז מִן קֳדָם יְיָ עֲלַי בְּדִילְכוֹן וְלָא קַבִּיל מִנִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסֵף לְמַלָלָא קֳדָמַי עוֹד בְּפִתְגָמָא הָדֵין:
@110 סַק לְרֵישׁ רָמָתָא וּזְקוֹף עֵינָיךְ לְמַעֲרָבָא וּלְצִפּוּנָא וְלִדְרוֹמָא וּלְמָדִינְחָא וַחֲזֵי בְעֵינָיךְ אֲרֵי לָא תְעִבַר יָת יַרְדְנָא הָדֵין:
@111 וּפַקֵד יָת יְהוֹשֻׁעַ וְתַקֶפְהִי וְאַלֶמְהִי אֲרֵי הוּא יֵעִבַר קֳדָם עַמָא הָדֵין וְהוּא יַחְסֵן יָתְהוֹן יָת אַרְעָא דִי תֶחֱזֵי:
@112 וִיתֵבְנָא בְחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר:
@113 וּכְעַן יִשְׂרָאֵל שְׁמַע לִקְיָמַיָא וּלְדִינַיָא דִי אֲנָא מְאַלֵף יָתְכוֹן לְמֶעְבַּד בְּדִיל דְתֵיחוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יָהֵב לְכוֹן:
@114 לָא תוֹסְפוּן עַל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן וְלָא תִמְנְעוּן מִנֵהּ לְמִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן:
@115 עֵינֵיכוֹן חָזָן יָת דִי עֲבַד יְיָ בְּבַעַל פְּעוֹר אֲרֵי כָּל גַבְרָא דִי אֲזַל בָּתַר בַּעַל פְּעוֹר שֵׁצְיֵהּ יְיָ אֱלָהָךְ מִבֵּינָךְ:
@116 וְאַתּוּן דְאַדְבֶּקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהֲכוֹן קַיָמִין כֻּלְכוֹן יוֹמָא דֵין:
@117 חֲזוֹ דְאַלֵפִית יָתְכוֹן קְיָמַיָא וְדִינַיָא כְּמָא דִי פַקְדַנִי יְיָ אֱלָהָי לְמֶעְבַּד כֵּן בְּגוֹ אַרְעָא דִי אַתּוּן עַלִין תַּמָן לְמֵירְתַהּ:
@118 וְתִטְרוּן וְתַעְבְּדוּן אֲרֵי הִיא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְעֵינֵי עַמְמַיָא דִי יִשְׁמְעוּן יָת כָּל קְיָמַיָא הָאִלֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין:
@119 אֲרֵי מָן עַם רַב דִי לֵהּ אֱלָהָא קָרִיב לֵהּ לְקַבָּלָא צְלוֹתֵהּ בְּעִדַן עַקְתֵהּ כַּייָ אֱלָהָנָא בְּכָל עִדָן דַאֲנַחְנָא מְצַלִין קֳדָמוֹהִי:
@120 וּמָן עַם רַב דִי לֵהּ קְיָמִין וְדִינִין קַשִׁיטִין כְּכֹל אוֹרַיְתָא הָדָא דִי אֲנָא יָהֵב קֳדָמֵכוֹן יוֹמָא דֵין:
@121 לְחוֹד אִסְתַּמַר לָךְ וְטַר נַפְשָׁךְ לַחֲדָא דִילְמָא תִנְשֵׁי יָת פִּתְגָמַיָא דִי חֲזוֹ עֵינָיִךְ וְדִילְמָא יְעִדוּן מִלִבָּךְ כֹּל יוֹמֵי חַיָיךְ וּתְהוֹדְעִנוּן לִבְנָיךְ וְלִבְנֵי בְנָיִךְ:
@122 יוֹמָא דִי קַמְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב כַּד אֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יָת עַמָא וְאַשְׁמְעִנוּן יָת פִּתְגָמָי דִי יֵלְפוּן לְמִדְחַל קֳדָמַי כָּל יוֹמַיָא דִי אִנוּן קַיָמִין עַל אַרְעָא וְיָת בְּנֵיהוֹן יְאַלְפוּן:
@123 וּקְרֶבְתּוּן וְקַמְתּוּן בְּשִׁפּוֹלֵי טוּרָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וַאֲמִיטְתָא:
@124 וּמַלִיל יְיָ עִמְכוֹן מִגוֹ אֶשְׁתָא קַל פִּתְגָמִין אַתּוּן שָׁמְעִין וּדְמוּת לֵיתֵיכוֹן חָזָן אֱלָהֵן קָלָא:
@125 וְחַוִי לְכוֹן יָת קְיָמֵהּ דִי פַקִיד יָתְכוֹן לְמֶעְבַּד עַשְׂרָא פִּתְגָמִין וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא:
@126 וְיָתִי פַּקִיד יְיָ בְּעִדְנָא הַהִיא לְאַלָפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעְבָּדְכוֹן יָתְהוֹן בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@127 וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרֵי לָא חֲזֵיתוּן כָּל דְמוּת בְּיוֹמָא דִי מַלִיל יְיָ עִמְכוֹן בְּחֹרֵב מִגוֹ אֶשָׁתָא:
@128 דִילְמָא תְּחַבְּלוּן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כָּל צוּרָא דְמוּת דְכַר אוֹ נֻקְבָא:
@129 דְמוּת כָּל בְּעִירָא דִי בְאַרְעָא דְמוּת כָּל צִפַּר גַדְפָא דִי פָּרַח בַּאֲוֵר רְקִיע שְׁמַיָא:
@130 דְמוּת כָּל רִחֲשָׁא דִי בְאַרְעָא דְמוּת כָּל נוּנֵי דִי בְמַיָא מִלְרַע לְאַרְעָא:
@131 וְדִילְמָא תִזְקוֹף עֵינָיךְ לִשְׁמַיָא וְתֶחֱזֵי יָת שִׁמְשָׁא וְיָת סִיהֲרָא וְיָת כּוֹכְבַיָא כֹּל חֵילֵי שְׁמַיָא וְתִטְעֵי וְתִסְגוּד לְהוֹן וְתִפְלְחִנוּן דִי זַמִין יְיָ אֱלָהָךְ יָתְהוֹן לְכֹל עַמְמַיָא תְּחוֹת כָּל שְׁמַיָא:
@132 וְיָתְכוֹן קָרִיב יְיָ לְדַחַלְתֵּהּ וְאַפֵּק יָתְכוֹן מִכּוּרָא דְפַרְזְלָא מִמִצְרָיִם לְמֶהֱוֵי לֵהּ לְעַמָא אַחֲסָנָא כְּיוֹמָא הָדֵין:
@133 וּמִן קֳדָם יְיָ הֲוָה רְגַז עֲלַי עַל פִּתְגָמֵיכוֹן וְקַיִים בְּדִיל דְלָא לְמֵעֲבַר יָת יַרְדְנָא וּבְדִיל דְלָא לְמֵיעַל לְאַרְעָא טָבָא דִי יְיָ אֱלָהָךְ יָהֵבּ לָךְ אַחֲסָנָא:
@134 אֲרֵי אֲנָא מָאִית בְּאַרְעָא הָדָא לֵית אֲנָא עָבֵר יָת יַרְדְנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יָת אַרְעָא טָבָא הָדָא:
@135 אִסְתַּמָרוּ לְכוֹן דִילְמָא תִתְנְשׁוּן יָת קְיָמָא דַיְיָ אֱלָהֲכוֹן דִי גְזַר עִמְכוֹן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כֹּלָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@136 אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא אֵל קַנָא:
@137 אֲרֵי תוֹלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן וְתַעְבְּדוּן צֶלֶם דְמוּת כֹּלָא וְתַעְבְּדוּן דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְאַרְגָזָא קֳדָמוֹהִי:
@138 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא אֲרֵי מֵיבַד תֵּיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא לְתַמָן לְמֵירְתַהּ לָא תוֹרְכוּן יוֹמִין עֲלַהּ אֲרֵי אִשְׁתְּצָאָה תִּשְׁתֵּצוּן:
@139 וִיבַדַר יְיָ יָתְכוֹן בְּעַמְמַיָא וְתִשְׁתָּאֲרוּן עַם דְמִנְיָן בְּעַמְמַיָא דִי יְדַבַּר יְיָ יָתְכוֹן לְתַמָן:
@140 וְתִפְלְחוּן תַּמָן לְעַמְמַיָא פָלְּחֵי טַעֲוָתָא עֹבַד יְדֵי אֱנָשָׁא אָעָא וְאַבְנָא דִי לָא יֶחֱזוּן וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין:
@141 וְתִתְבְּעוּן מִתַּמָן יָת דַחֲלְתָּא דַייָ אֱלָהָךְ וְתִשְׁכָּח אֲרֵי תִבְעֵי מִן קֳדָמוֹהִי בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@142 כַּד יֵיעוֹק לָךְ וְיַשְׁכְּחֻנָךְ כֹּל פִּתְגָמַיָא הָאִלֵין בְּסוֹף יוֹמַיָא וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ:
@143 אֲרֵי אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָךְ לָא יִשְׁבְּקִנָךְ וְלָא יְחַבְּלִנָךְ וְלָא יִתִּנְשֵׁי יָת קְיָמָא דַאֲבָהָתָךְ דִי קַיִים לְהוֹן:
@144 אֲרֵי שְׁאֵל כְּעַן לְיוֹמַיָא קַדְמָאֵי דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִי בְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָפֵי שְׁמַיָא וְעַד סְיָפֵי שְׁמַיָא הַהֲוָה כְּפִתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע כְּוָתֵהּ:
@145 הַשְׁמַע עַמָא קַל מֵימְרָא דַיְיָ מְמַלֵל מִגוֹ אֶשָׁתָא כְּמָא דִי שְׁמַעַתְּ אַתְּ וְיִתְקַיָם:
@146 אוֹ נִסִין דִי עֲבַד יְיָ לְאִתְגַלָאָה לְמִפְרַק לֵהּ עַם מִגוֹ עַם בְּנִסִין בְּאָתִין וּבְמוֹפְתִין וּבִקְרָבָא וּבִידָא תַקִיפָא וּבִדְרָעָא מְרָמָא וּבְחֶזְוָנִין רַבְרְבִין כְּכֹל דִי עֲבַד לְכוֹן יְיָ אֱלָהֲכוֹן בְּמִצְרַיִם לְעֵינָיךְ:
@147 אַתְּ אִתְחֲזֵיתָא לְמִדַע אֲרֵי יְיָ הוּא אֱלֹהִים לֵית עוֹד בַּר מִנֵהּ:
@148 מִן שְׁמַיָא אַשְׁמְעָךְ יָת קָל מֵימְרֵהּ לְאַלָפוּתָךְ וְעַל אַרְעָא אַחְזְיָךְ יָת אֶשָׁתֵהּ רַבְּתָא וּפִתְגָמוֹהִי שְׁמַעַתְּ מִגוֹ אֶשָׁתָא:
@149 וָחֳלַף אֲרֵי רְחִים יָת אֲבָהָתָךְ וְאִתִּרְעֵי בִּבְנוֹהִי בַּתְרוֹהִי וְאַפְּקָךְ בְּמֵימְרֵהּ בְּחֵילֵהּ רַבָּא מִמִצְרָיִם:
@150 לְתָרָכָא עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ מִן קֳדָמָךְ לְאָעָלוּתָךְ לְמִתַּן לָךְ יָת אַרְעֲהוֹן אַחֲסָנָא כְּיוֹמָא הָדֵין:
@151 וְתִדַע יוֹמָא דֵין וּתְתוּב לְלִבָּךְ אֲרֵי יְיָ הוּא אֱלָהָא דִשְׁכִנְתֵּהּ בִּשְׁמַיָא מִ לְעֵלָא וְשַׁלִיט עַל אַרְעָא מִלְרָע לֵית עוֹד:
@152 וְתִטַר יָת קְיָמוֹהִי וְיָת פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין דִי יֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ וּבְדִיל דְתוֹרִיךְ יוֹמִין עַל אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ כָּל יוֹמַיָא:
@153 בְּכֵן יַפְרֵשׁ מֹשֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@154 לְמֵעִירוֹק תַּמָן קָטוֹלָא דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵי וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקַמוֹהִי וְיֵעִרוֹק לְחַד מִן קִרְוַיָא הָאִלֵין וְיִתְקַיָם:
@155 יָת בֶּצֶר בְּמַדְבְּרָא בְּאַרְעָא מֵישְׁרָא לְשִׁבְטָּא דִרְאוּבֵן וְיָת רָאמוֹת בַּגִלְעָד לְשִׁבְטָא דְגָד וְיָת גוֹלָן בְּמַתְנָן לְשִׁבְטָא דִמְנַשֶׁה:
@156 וְדָא אוֹרַיְתָא דִי סַדַר מֹשֶׁה קֳדָם בְּנֵי יִשְׂרָאֵל:
@157 אִלֵין סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@158 בְּעִבְרָא דְיַרְדְנָא בְּחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר בְּאַרְעָא דְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן דִי מְחָא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@159 וִירִיתוּ יָת אַרְעֵהּ וְיָת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@160 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְעַד טוּרָא דְשִׂיאֹן הוּא חֶרְמוֹן:
@161 וְכָל מֵישְׁרָא עִבְרָא דְיַרְדְנָא לְמָדִינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא:
@162 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן שְׁמַע יִשְׂרָאֵל יָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְמַלֵל קֳדָמֵיכוֹן יוֹמָא דֵין וְתַלְפוּן יָתְהוֹן וְתִטְרוּן לְמֶעְבָּדְהוֹן:
@163 יְיָ אֱלָהָנָא גְזַר עִמָנָא קְיָם בְּחֹרֵב:
@164 לָא עִם אֲבְהָתָנָא גְזַר יְיָ יָת קְיָמָא הָדָא אֶלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כֻּלָנָא קַיָמִין:
@165 מַמְלָל עִם מַמְלָל מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא:
@166 אֲנָא הֲוֵיתִי קָאֵם בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִדָנָא הַהִיא לְחַוָאָה לְכוֹן יָת פִּתְגָמָא דַיְיָ אֲרֵי דְחֶלְתּוּן מִקֳדָם אֵשָׁתָא וְלָא סְלֶקְתּוּן בְּטוּרָא לְמֵימָר:
@167 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּקְתָּךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עֲבְדוּתָא:
@168 לָא יְהֵא לָךְ אֱלָהּ אָחָרָן בַּר מִנִי:
@169 לָא תַעְבֵּד לָךְ צֶלֶם כָּל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@170 לָא תִסְגוּד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשַׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵּי בָּתַר אֲבָהָתְהוֹן:
@171 וְעָבֵד טֵּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְּרֵי פִקוֹדָי:
@172 לָא תֵימֵי בִּשְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יְזַכֵּי יְיָ יָת דִי יֵמֵי בִשְׁמֵהּ לְשִׁקְרָא:
@173 טַר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@174 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@175 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עֲבִידָא אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְתוֹרָךְ וַחֲמָרָךְ וְכָל בְּעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ בְּדִיל דִי יְנוּחַ עַבְדָךְ וְאַמְתָךְ כְּוָתָךְ:
@176 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וְאַפְּקָךְ יְיָ אֱלָהָךְ מִתַּמָן בִּידָא תַקִיפָא וּבִדְרָעָא מְרָמְמָא עַל כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעְבַּד יָת יוֹמָא דְשַׁבְּתָא:
@177 יַקַר יָת אֲבוּךְ וְיָת אִמָךְ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ וּבְדִיל דְיֵיטַב לָךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@178 לָא תִקְטוֹל נְפָשׁ וְלָא תְגוּף וְלָא תִגְנוֹב (נַפְשָׁא) וְלָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@179 וְלָא תַחְמֵד אִתַּת חַבְרָךְ וְלָא תֵרוֹג בֵּית חַבְרָךְ חַקְלֵהּ וְעַבְדֵהּ וְאַמְתֵהּ תּוֹרֵה וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@180 יָת פִּתְגָמַיָא הָאִלֵין מַלִיל יְיָ עִם כָּל קְהָלְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא עֲנָנָא וַאֲמִיטְתָא קָל רַב וְלָא פְסַק וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהָבִנָן לִי:
@181 וַהֲוָה כַּד שְׁמַעֲכוֹן יָת קָלָא מִגוֹ חֲשׁוֹכָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא וְקָרֶבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְסָבֵיכוֹן:
@182 וַאֲמַרְתּוּן הָא אַחְזְיָנָא יְיָ אֱלָהָנָא יָת יְקָרֵהּ וְיָת רְבוּתֵהּ וְיָת קָל מֵימְרֵהּ שְׁמַעְנָא מִגוֹ אֶשָׁתָא יוֹמָא הָדֵין חֲזֵינָא אֲרֵי יְמַלֵל יְיָ עִם אֲנָשָׁא וְיִתְקַיָם:
@183 וּכְעַן לְמָא נְמוּת אֲרֵי תֵיכְלִנָנָא אֶשָׁתָא רַבְּתָא הָדָא אִם מוֹסְפִין אֲנַחְנָא לְמִשְׁמַע יָת קָל מֵימְרָא דַייָ אֱלָהָנָא עוֹד וּמָיְתִין אֲנַחְנָא:
@184 אֲרֵי מָן כָּל בִּשְׂרָא דִי שְׁמַע קָל מֵימְרָא דַיְיָ קַיָמָא מְמַלֵל מִגוֹ אֶשָׁתָא כְּוָתָנָא וְאִתְקַיָם:
@185 קְרַב אַתְּ וּשְׁמַע יָת כָּל דִי יֵימַר יְיָ אֱלָהָנָא וְאַתְּ תְּמַלֵל עִמָנָא יָת כָּל דִי מַלֵל יְיָ אֱלָהָנָא עִמָךְ וּנְקַבֵּל וְנַעְבֵּד:
@186 וּשְׁמִיעַ קֳדָם יְיָ יָת קָל פִּתְגָמֵיכוֹן בְּמַלָלוּתְכוֹן עִמִי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יָת קָל פִּתְגָמֵי עַמָא הָדֵין דִי מַלִילוּ עִמָךְ אַתְקִינוּ כָּל דִי מַלִילוּ:
@187 לְוַי דִי יְהֵי לִבָּא הָדֵין לְהוֹן לְמִדְחַל קֳדָמַי וּלְמִטַר יָת כָּל פִּקוּדַי כָּל יוֹמַיָא בְּדִיל דִיֵיטַב לְהוֹן וְלִבְנֵיהוֹן לְעָלָם:
@188 אִזֵל אֱמַר לְהוֹן תּוּבוּ לְכוֹן לְמַשְׁכְּנֵיכוֹן:
@189 וְאַתְּ הָכָא קִים קֳדָמַי וֶאֱמַלֵל עִמָךְ יָת כָּלּ תַּפְקֶדְתָּא וּקְיָמַיָא וְדִינַיָא דִי תַלְפִנוּן וְיַעְבְּדוּן בְּאַרְעָא דִי אֲנָא יָהֵב לְהוֹן לְמֵירְתַהּ:
@190 וְתִטְרוּן לְמֶעְבַּד כְּמָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן לָא תִסְטוּן יַמִינָא וּשְׂמָאלָא:
@191 בְּכָל אָרְחָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן תְּהָכוּן בְּדִיל דְתֵיחוּן וְיֵיטַב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דִי תֵירְתוּן:
@192 וְדָא תַפְקֶדְתָּא קְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהֲכוֹן לְאַלָפָא יָתְכוֹן לְמֶעְבַּד בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@193 בְּדִיל דְתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִטַר יָת כָּל קְיָמוֹהִי וּפִקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ אַתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָיךְ וּבְדִיל דְיוֹרְכוּן יוֹמָיךְ:
@194 וּתְקַבֵּל יִשְׂרָאֵל וְתִטַר לְמֶעְבַּד דִי יֵיטַב לָךְ וְדִי תִסְגוּן לַחֲדָא כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@195 שְׁמַע יִשְׂרָאֵל יְיָ אֱלָהָנָא יְיָ חָד:
@196 וְתִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ וּבְכָל נִכְסָךְ:
@197 וִיהוֹן פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין עַל לִבָּךְ:
@198 וּתְתָנִנוּן לִבְנָיךְ וּתְמַלֵל בְּהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@199 וְתִקְטְרִנוּן לְאָת עַל יְדָךְ וִיהוֹן לִתְפִלִין בֵּין עֵינָיךְ:
@200 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@201 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לָךְ קִרְוִין רַבְרְבָן וְטָבָן דִי לָא בְנֵיתָא:
@202 וּבָתִּין מְלָן כָּל טוּב דִי לָא מְלֵיתָא וְגֻבִּין פְּסִילָן דִי לָא פְּסַלְתָּא כַּרְמִין וְזֵיתִין דִי לָא נְצֶבְתָּא וְתֵיכוּל וְתִשְׂבָּע:
@203 אִסְתַּמַר לָךְ דִילְמָא תִנְשֵׁי יָת (דַחַלְתָּא דַ) יְיָ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@204 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִּפְלָח וּבִשְׁמֵהּ תְּקַיַם:
@205 לָא תְהָכוּן בָּתַר טַעֲוַת עַמְמַיָא מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן:
@206 אֲרֵי אֵל קַנָא יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ דִילְמָא יִתְקֵף רָגְזָא דַיְיָ אֱלָהָךְ בָּךְ וִישֵׁצָךְ מֵעַל אַפֵּי אַרְעָא:
@207 לָא תְנַסוּן קֳדָם יְיָ אֱלָהֲכוֹן כְּמָא דִי נַסֵתוּן בְנִסֵיתָא:
@208 מִטַּר תִּטְרוּן יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן וּסְהֶדְוָתֵהּ וּקְיָמוֹהִי דִי פַקְדָךְ:
@209 וְתַעְבֵּד דְכָשַׁר וּדְתַקֵן קֳדָם יְיָ בְּדִיל דְיֵיטַב לָךְ וְתֵעוּל וְתֵירַת יָת אַרְעָא טַבְתָא דִי קַיִים יְיָ לַאֲבָהָתָךְ:
@210 לְמִתְּבַר יָת כָּל בַּעֲלֵי דְבָבָךְ מֵקָדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@211 אֲרֵי יִשְׁאֲלִנָךְ בְּרָךְ מְחָר לְמֵימָר מָא סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהָנָא יָתְכוֹן:
@212 וְתֵימַר לִבְרָךְ עַבְדִין הֲוֵינָא לְפַרְעֹה בְּמִצְרָיִם וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא:
@213 וִיהַב יְיָ אָתִין וּמוֹפְתִין רַבְרְבִין וּבִישִׁין בְּמִצְרַיִם בְּפַרְעֹה וּבְכָל אֱנַשׁ בֵּיתֵהּ לְעֵינָנָא:
@214 וְיָתָנָא אַפֵּק מִתַּמָן בְּדִיל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יָת אַרְעָא דִי קַיִים לַאֲבָהָתָנָא:
@215 וּפַּקְדָנָא יְיָ לְמֶעְבַּד יָת כָּל קְיָמַיָא הָאִלֵין לְמִדְחַל יָת יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָמוּתָנָא כְּיוֹמָא הָדֵין:
@216 וְזָכוּתָא תְּהֵא לָנָא אֲרֵי נִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא כְּמָא דִי פַקְדָנָא:
@217 אֲרֵי יְעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ וִיתָרֵךְ עַמְמִין סַגִיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגָשָׁאֵי וֶאֱמֹרָאֵי וּכְנַעֲנָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי שִׁבְעָא עַמְמִין סַגִיאִין וְתַקִיפִין מִנָךְ:
@218 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וְתִמְחִנוּן גַמָרָא תְגַמַר יָתְהוֹן לָא תִגְזַר לְהוֹן קְיָם וְלָא תְרַחַם עֲלֵיהוֹן:
@219 וְלָא תִתְחַתַּן בְּהוֹן בְּרַתָּךְ לָא תִתֵּן לִבְרֵהּ וּבְרַתֵּהּ לָא תִסַב לִבְרָךְ:
@220 אֲרֵי יַטְעֲיַן יָת בְּרָךְ מִבָּתַר פָּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקֵף רָגְזָא דַיְיָ בְּכוֹן וִישֵׁצָךְ בִּפְרִיעַ:
@221 אֲרֵי אִם כְּדֵין תַּעַבְּדוּן לְהוֹן אֱגוֹרֵיהוֹן תְּתָרְעוּן וְקָמָתְהוֹן תְּתַבְּרוּן וַאֲשֵׁרֵיהוֹן תְּקוֹצְצוּן וְצַלְמֵי טַּעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא:
@222 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ בָּךְ אִתִּרְעֵי יְיָ אֱלָהָךְ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכֹּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@223 לָא מִדְסַגִיאִין אַתּוּן מִכָּל עַמְמַיָא צָבֵי יְיָ בְּכוֹן וְאִתִּרְעֵי בְכוֹן אֲרֵי אַתּוּן זְעֵרִין מִכָּל עַמְמַיָא:
@224 אֲרֵי מִדְרַחַם יְיָ יָתְכוֹן וּמִדִנְטַר יָת קְיָמָא דִי קַיִים לַאֲבָהָתְכוֹן אַפֵּיק יְיָ יָתְכוֹן בִּידָא תַקִיפָא וּפָרְקָךְ מִבֵּית עַבְדוּתָא מִידָא דְפַרְעֹה מַלְכָּא דְמִצְרָיִם:
@225 וְתִדַע אֲרֵי יְיָ אֱלָהָךְ הוּא אֱלֹהִים אֱלָהָא מְהֵימְנָא נָטֵר קְיָמָא וְחִסְדָא לְרַחֲמוֹהִי וּלְנָטְרֵי פִקוֹדוֹהִי לְאַלְפֵי דָרִין:
@226 וּמְשַׁלֵם לְסָנְאוֹהִי טָבָן דִי אִנוּן עָבְדִין קֳדָמוֹהִי בְּחַיֵיהוֹן לְאוֹבָדֵיהוֹן לָא מְאַחַר עֹבַד טָב לְסָנְאוֹהִי טַבְוָן דִי אִנוּן עָבְדִין קָדָמוֹהִי בְּחַיֵיהוֹן מְשַׁלֵם לְהוֹן:
@227 וְתִטַר יָת תַּפְקֶדְתָּא וְיָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבָּדְהוֹן: פפפ:
@228 וִיהֵי חֳלַף דִי תְקַבְּלוּן יָת דִינַיָא הָאִלֵין וְתִטְרוּן וְתַעְבְּדוּן יָתְהוֹן וְיִטַר יְיָ אֱלָהָךְ לָךְ יָת קְיָמָא וְיָת חִסְדָא דִי קַיִים לַאֲבָהָתָךְ:
@229 וְיִרְחֲמִנָךְ וִיבָרֵכִנָךְ וְיַסְגִינָךְ וִיבָרֵךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַל אַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@230 בְּרִיךְ תְּהֵי מִכָּל עַמְמַיָא לָא יְהֵי בָךְ עֲקַר וְעַקְרָא וּבִבְעִירָךְ:
@231 וְיֶעְדֵי יְיָ מִנָךְ כָּל מַרְעִין וְכָל מַכְתְּשֵׁי מִצְרַיִם בִּישַׁיָא דִי יְדַעַתְּ לָא יְשַׁוִּנוּן בָּךְ וְיִתְּנִנוּן בְּכָל סָנְאָךְ:
@232 וּתְגַמַר יָת כָּל עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לָא תְחוּס עֵינָךְ עֲלֵיהוֹן וְלָא תִפְלַח יָת טַּעֲוָתְהוֹן אֲרֵי לְתַקְלָא הוּא לָךְ:
@233 דִילְמָא תֵימַר בְּלִבָּךְ סַגִיאִין עַמְמַיָא הָאִלֵין מִנִי אֶכְדֵין אִכּוּל לְתָרָכוּתְהוֹן:
@234 לָא תִדְחַל מִנְהוֹן מִדְכַּר תִּדְכַּר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְפַרְעֹה וּלְכָל מִצְרָיִם:
@235 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ וְאָתַיָא וּמוֹפְתַיָא וִידָא תַקֶפְתָּא וּדְרָעָא מְרָמְמָא דִי אַפְּקָךְ יְיָ אֱלָהָךְ כֵּן יַעְבֵּד יְיָ אֱלָהָךְ לְכָל עַמְמַיָא דִי אַתְּ דָחֵל מִקֳדָמֵיהוֹן:
@236 וְאַף יָת עֲרָעִיתָא יְגָרֵי יְיָ אֱלָהָךְ בְּהוֹן עַד דְיֵבַדוּן דְאִשְׁתָּאָרוּ וּדְאִטַמָרוּ מֵקֳדָמָךְ:
@237 לָא תִתְּבַר מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ אֱלָהָא רַבָּא וּדְחִילָא:
@238 וִיתָרַךְ יְיָ אֱלָהָךְ יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ זְעֵר זְעֵר לָא תִכּוּל לְשֵׁצָי וּתְהוֹן בִּפְרִי עַ דִי לְמָא תִסְגֵּי עֲלָךְ חֵיוַת בָּרָא:
@239 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וִישַׁגֵשִׁנוּן שִׁגוּשׁ רַב עַד דְיִשְׁתֵּצוּן:
@240 וְיִמְסַר מַלְכֵיהוֹן בִּידָךְ וְתוֹבַד יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא לָא יִתְעַתַּד אֱנַשׁ קֳדָמָךְ עַד דִתְשֵׁיצֵי יָתְהוֹן:
@241 צַלְמֵי טַעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא לָא תַחְמֵד כַּסְפָּא וְדַהֲבָא דִי עֲלֵיהוֹן וְתִסַב לָךְ דִילְמָא תִּתָּקַל בֵּהּ אֲרֵי מְרָחָקָא דַיְיָ אֱלָהָךְ הוּא:
@242 וְלָא תָעֵל דִמְרָחָק לְבֵיתָךְ וּתְהֵי חֶרְמָא כְּוָתֵהּ שַׁקָצָא תְשַׁקְצִנֵהּ וְרַחָקָא תְּרַחֲקִנֵהּ אֲרֵי חֶרְמָה הוּא:
@243 כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין תִּטְרוּן לְמֶעְבָּד בְּדִיל דְתֵיחוּן וְתִסְגוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן:
@244 וְתִדְכַּר יָת כָּל אָרְחָא דִי דַבְּרָךְ יְיָ אֱלָהָךְ דְנַן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא בְּדִיל לְעַנָיוּתָךְ לְנַסָיוּתָךְ לְמִדַע יָת דִי בְלִבָּךְ הֲתִטַר פִּקוּדוֹהִי אִם לָא:
@245 וְעַנְיָךְ וְאַכְפָּנָךְ וְאוֹכָלָךְ יָת מַנָא דִי לָא יְדַעְתְּ וְלָא יָדְעוּן אֲבָהָתָיךְ בְּדִיל לְאוֹדָעוּתָךְ אֲרֵי לָא עַל לַחְמָא בִלְחוֹדוֹהִי מִתְקַיַם אֱנָשָׁא אֲרֵי עַל כָּל אַפָּקוּת מֵימְרָא דַיְיָ יִתְקַיַם אֱנָשָׁא:
@246 כְּסוּתָךְ לָא אִבְלִיאַת מִנָךְ וּמְסָנָךְ לָא יְחֵפוּ דְנַן אַרְבְּעִין שְׁנִין:
@247 וְתִדַע עִם לִבָּךְ אֲרֵי כְּמָא דִי מְאַלֵף גַבְרָא יָת בְּרֵהּ יְיָ אֱלָהָךְ מְאַלֵף לָךְ:
@248 וְתִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחַן דְתַקְנָן קֳדָמוֹהִי וּלְמִדְחַל יָתֵהּ:
@249 אֲרֵי יְיָ אֱלָהָךְ מַעֲלָךְ לְאַרְעָא טַבְתָא אַרְעָא נָגְדָא נַחֲלִין דְמַיִין מַבּוּעֵי עֵינַוָן וּתְהוֹמִין נָפְקִין בְּבִקְעָן וּבְטוּרִין:
@250 אַרְעָא חִטִּין וְסַעֲרִין וְגוּפְנִין וּתְאֵנִין וְרִמוֹנִין אַרְעָא דְזֵיתָהָא עָבְדִין מִשְׁחָא וְהִיא עָבְדָא דְבָשׁ:
@251 אַרְעָא דִי לָא בְעִצוּרִין (נ''א בְמִסְכֵּנוּ) תֵּיכוּל בַּהּ לַחֲמָא לָא תֶחְסַר כָּל מִדַעַם בַּהּ אַרְעָא דִי אַבְנָהָא פַרְזְלָא וּמִטוּרָהָא תִּפְסוּל נְחָשָׁא:
@252 וְתֵיכוּל וְתִשְׂבַּע וּתְבָרַךְ יָת יְיָ אֱלָהָךְ עַל אַרְעָא טַבְתָא דִיהַב לָךְ:
@253 אִסְתַּמַר לָךְ דִילְמָא תִתְנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ בְּדִיל דְלָא לְמִטַר פִּקּוֹדוֹהִי וְדִינוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@254 דִילְמָא תֵיכוּל וְתִשְׂבַּע וּבָתִּין שַׁפִּירִין תִּבְנֵי וְתֵיתֵב:
@255 וְתוֹרָךְ וְעָנָךְ יִסְגוּן וְכַסְפָּא וְדַהֲבָא יִסְגֵא לָךְ וְכֹל דִי לָךְ יִסְגֵא:
@256 וִירִים לִבָּךְ וְתִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@257 דְדַבְּרָךְ בְּמַדְבְּרָא רַבָּא וּדְחִילָא אֲתַר חֵיוָן קָלָן וְעַקְרַבִּין וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא דְאַפֵּק לָךְ מַיָא מִטִּנָרָא תַּקִיפָא:
@258 דְאוֹכָלָךְ מַנָא בְּמַדְבְּרָא דִי לָא יָדְעוּן אֲבָהָתָךְ בְּדִיל לְעַנָיוּתָךְ וּבְדִיל לְנַסָיוּתָךְ לְאוֹטָבָא לָךְ בְּסוֹפָךְ:
@259 וְתֵימַר בְּלִבָּךְ חֵילִי וּתְקֵף יְדִי קְנוֹ לִי יָת נִכְסַיָא הָאִלֵין:
@260 וְתִדְכַּר יָת יְיָ אֱלָהָךְ אֲרֵי הוּא יָהֵב לָךְ עֵצָה לְמִקְנֵי נִכְסִין בְּדִיל לְקַיָמָא יָת קְיָמֵהּ דִי קַיִים לְאֲבָהָתָךְ כְּיוֹמָא הָדֵין:
@261 וִיהֵי אִם מִנְשָׁאָה תִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְהַךְ בָּתַר טַעְוַת עַמְמַיָא וְתִפְלְחִנוּן וְתִסְגוּד לְהוֹן אַסְהֵדִית בְּכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן:
@262 כְּעַמְמַיָא דִי יְיָ מֹאבִיד מִקֳדָמֵיכוֹן כֵּן תֵּיבְדוּן חֳלַף דְלָא קַבֶּלְתּוּן בְּמֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@263 שְׁמַע יִשְׂרָאֵל אַתְּ עָבֵר יוֹמָא דֵין יָת יַרְדְנָא לְמֵיעַל לְמֵירַת עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא:
@264 עַם רַב וְתַקִיף בְּנֵי גִבָּרַיָא דִי אַתְּ יְדַעַתְּ וְאַתְּ שְׁמַעְתְּ מָן יִכּוּל לְמֵיקַם קֳדָם בְּנֵי גִבָּרַיָא:
@265 וְתִדַע יוֹמָא דֵין אֲרֵי יְיָ אֱלָהָךְ הוּא דְעֲבַר קֳדָמָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא יְשֵׁצִנוּן וְהוּא יְתָרֵכִנוּן קֳדָ מָךְ וּתְתָרֵ כִנוּן וְתוֹבְדִנוּן בִּפְרִיעַ כְּמָא דִי מַלִיל יְיָ לָךְ:
@266 לָא תֵימַר בְּלִבָּךְ בִּדְיִתְּבַר יְיָ אֱלָהָךְ יָתְהוֹן מִקֳדָמָךְ לְמֵימַר בְּזָכוּתִי אַעֲלַנִי יְיָ לְמֵירַת יָת אַרְעָא הָדָא וּבְחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ מְתָרֶכְהוֹן מֵקֳדָמָךְ:
@267 לָא בְזָכוּתָךְ וּבְקַשִׁיטּוּת לִבָּךְ אַתְּ עָלֵל לְמֵירַת יָת אַרְעֲהוֹן אֲרֵי בְּחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ אֱלָהָךְ מתָרֶכְהוֹן מִקָדָמָךְ וּבְדִיל לַאֲקָמָא יָת פִּתְגָמָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@268 וְתִדַע אֲרֵי לָא בְזָכוּתָךְ יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעָא טַבְתָא הָדָא לְמֵירְתַהּ אֲרֵי עַם קְשֵׁי קְדַל אַתְּ:
@269 הֱוֵי דְכִיר לָא תִנְשֵׁי יָת דִי אַרְגֶזְתָּא קֳדָם יְיָ אֱלָהָךְ בְּמַדְבְּרָא לְמִן יוֹמָא דִי נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ:
@270 וּבְחוֹרֵב אַרְגֶזְתּוּן קֳדָם יְיָ וַהֲוָה רְגַז מִן קֳדָם יְיָ בְּכוֹן לְשֵׁיצָאָה יַתְכוֹן:
@271 בְּמִסְקִי לְטוּרָא לְמִסַב לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא דִי גְזַר יְיָ עִמְכוֹן וִיתֵבִית בְּטוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחֲמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי:
@272 וִיהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ וַעֲלֵיהוֹן כְּכָל פִּתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא בְּיוֹמָא דִקְהָלָא:
@273 וַהֲוָה מִסוֹף אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן יְהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא:
@274 וַאֲמַר יְיָ לִי קוּם חוּת בִּפְרִיעַ מִכָּא אֲרֵי חַבִּיל עַמָךְ דִי אַפֶּקְתָּא מִמִצְרָיִם סָטוּ בִּפְרִיעַ מִן אָרְחָא דִי פַקֶדְתִּנוּן עֲבָדוּ לְהוֹן מַתְּכָא:
@275 וַאֲמַר יְיָ לִי לְמֵימָר גְלֵי קֳדָמַי יָת עַמָא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא:
@276 אַנַח בָּעוּתָךְ מִקֳדָמַי וֶאֱשֵׁצִנוּן וְאֶמְחֵי יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא וְאֶעְבֵּד יָתָךְ לְעַם תַּקִיף וְסַגִי מִנְהוֹן:
@277 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְטּוּרָא בָּעֵר בְּאֶשָׁתָא וּתְרֵין לוּחֵי קְיָמָא עַל תַּרְתֵּין יְדָי:
@278 וַחֲזֵיתִי וְהָא חַבְתּוּן קֳדָם יְיָ אֱלָהֲכוֹן עֲבַדְתּוּן לְכוֹן עֵגֶל מַתְּכָא סְטֵיתוּן בִּפְרִיעַ מִן אָרְחָא דִי פַקִיד יְיָ יָתְכוֹן:
@279 וַאֲחָדִית בִּתְרֵין לוּחַיָא וּרְמִיתִנוּן מֵעַל תַּרְתֵּין יְדָי וּתְבַרְתִּנוּן לְעֵינֵיכוֹן:
@280 וְאִשְׁתַּטָחִית קֳדָם יְיָ כְּקַדְמֵיתָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחְמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי עַל כָּל חוֹבֵיכוֹן דִי חַבְתּוּן לְמֶעְבַּד דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי:
@281 אֲרֵי דְחֵלִית מִקָדָם רָגְזָא וְחֵמְתָא דִי רְגַז יְיָ עֲלֵיכוֹן לְשֵׁצָאָה יָתְכוֹן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהִיא:
@282 וְעַל אַהֲרֹן הֲוָה רְגַז מִן קֳדָם יְיָ לַחֲדָא לְשֵׁצָיוּתֵהּ וְצַלֵיתִי אַף עַל אַהֲרֹן בְּעִדָנָא הַהִיא:
@283 וְיָת חוֹבָתְכוֹן דִי עֲבַדְתּוּן יָת עֶגְלָא נְסֵבִית וְאוֹקֵדִית יָתֵהּ בְּנוּרָא וְשָׁפִית יָתֵהּ בְּשׁוּפִינָא יָאוּת עַד דִי הֲוָה דַקִיק לְעַפְרָא וּרְמֵת יָת עַפְרֵהּ לְנַחֲלָא דְנָחֵת מִן טוּרָא:
@284 וּבִדְלֶקְתָּא וּבְנִסֵתָא וּבְקִבְרֵי דִמְשַׁאֲלֵי מַרְגְזִין הֲוֵיתוּן קֳדָם יְיָ:
@285 וְכַד שְׁלַח יְיָ יָתְכוֹן מֵרְקַם גֵיאָה לְמֵימַר סְקוֹ וְאַחֲסִינוּ יָת אַרְעָא דִי יְהָבִית לְכוֹן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ אֱלָהֲכוֹן וְלָא הֵימַנְתּוּן לֵהּ וְלָא קַבֶּלְתּוּן לְמֵימְרֵהּ:
@286 מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ מִיוֹמָא דִידָעִית יָתְכוֹן:
@287 וְאִשְׁתַּטָחִית קֳדָם יְיָ יָת אַרְבְּעִין יְמָמִין וְיָת אַרְבְּעִין לֵילָוָן דִי אִשְׁתַּטָחִית אֲרֵי אֲמַר יְיָ לְשֵׁצָאָה יָתְכוֹן:
@288 וְצַלֵיתִי קֳדָם יְיָ וַאֲמָרִית יְיָ אֱלֹהִים לָא תְחַבֵּל עַמָךְ וְאַחֲסַנְתָּךְ דִי פְרַקְתָּא בְּתָקְפָּךְ דִי אַפֶּקְתָּא מִמִצְרַיִם בִּידָא תַקִיפָא:
@289 אִדְכַר לְעַבְדָיךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לָא תִתְפְּנֵי לְקַשְׁיוּת עַמָא הָדֵין וּלְחוֹבֵיהוֹן וְלַחֲטָאֵיהוֹן:
@290 דִילְמָא יֵימְרוּן דָיְרֵי אַרְעָא דִי אַפֶּקְתָּנָא מִתַּמָן מִדְלֵית יוּכְלָא דַיְיָ לְאָעָלוּתְהוֹן לְאַרְעָא דִי מַלִיל לְהוֹן וּמִדְסָנֵי יָתְהוֹן אַפֵּקִנוּן לְקַטָלוּתְהוֹן בְּמַדְבְּרָא:
@291 וְאִנוּן עַמָךְ וְאַחֲסַנְתָּךְ דִי אַפֶּקְתָּא בְּחֵילָךְ רַבָּא וּבִדְרָעָךְ מְרָמְמָא:
@292 בְּעִדָנָא הַהִיא אֲמַר יְיָ לִי פְּסַל לָךְ תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְסַק לָקֳדָמַי לְטּוּרָא וְתַעְבֵּד לָךְ אֲרוֹנָא דְאָעָא:
@293 וְאֶכְתּוֹב עַל לוּחַיָא יָת פִּתְגָמַיָא דִי הֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּא וּתְשַׁוִנוּן בַּאֲרוֹנָא:
@294 וַעֲבָדִית אֲרוֹנָא דְאָעֵי שִׁטִּין וּפְסָלִית תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וּסְלֵקִית לְטוּרָא וּתְרֵין לוּחַיָא בִּידִי:
@295 וּכְתַב עַל לוּחַיָא כִּכְתָבָא קַדְמָאָה יָת עַשְׂרָא פִתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשְׁתָא בְּיוֹמָא דִקְהָלָא וִיהָבִנוּן יְיָ לִי:
@296 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְשַׁוֵיתִי יָת לוּחַיָא בַּאֲרוֹנָא דִי עֲבָדִית וַהֲווֹ תַמָן כְּמָא דִי פַקְדַנִי יְיָ:
@297 וּבְנֵי יִשְׂרָאֵל נְטָלוּ מִבְּאֵרוֹת בְּנֵי יַעֲקָן לְמוֹסֵרָה תַּמָן מִית אַהֲרֹן וְאִתְקְבַר תַּמָן וְשַׁמֵשׁ אֶלְעָזָר בְּרֵהּ תְּחוֹתוֹהִי:
@298 מִתַּמָן נְטָּלוּ לְגֻדְגֹד וּמִן גֻדְגֹד לְיָטְבָת אַרְעָא נָגְדָא נַחֲלִין דְמַיִין:
@299 בְּעִדָנָא הַהִיא אַפְרֵשׁ יְיָ יָת שִׁבְטָּא דְלֵוִי לְמִטַל יָת אֲרוֹן קְיָמָא דַיְיָ לְמֵיקַם קֳדָם יְיָ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִשְׁמֵהּ עַד יוֹמָא הָדֵין:
@300 עַל כֵּן לָא הֲּוָה לְלֵוִי חֳלָק וְאַחֲסָנָא עִם אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל יְיָ אֱלָהָךְ לֵהּ:
@301 וַאֲנָא הֲוֵיתִי קָאֵם בְּטוּרָא כְּיוֹמִין קַדְמָאִין אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהוּא לָא אָבֵי יְיָ לְחַבָּלוּתָךְ:
@302 וַאֲמַר יְיָ לִי קוּם זִיל לְמִטוּל קֳדָם עַמָא וְיֵעֲלוּן וְיֵרְתוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן לְמִתַּן לְהוֹן:
@303 וּכְעַן יִשְׂרָאֵל מָה יְיָ אֱלָהָךְ תָּבַע מִנָךְ אֱלָהֵן לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ לִמְהַךְ בְּכָל אָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִרְחַם יָתֵהּ וּלְמִפְלַח קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@304 לְמִטַר יָת פִּקוֹדַיָא דַיְיָ וְיָת קְיָמוֹהִי דַאֲנָא מְפַקְדָךְ יוֹמָא דֵין לִדְיֵיטַב לָךְ:
@305 הָא דַיְיָ אֱלָהָךְ שְׁמַיָא וּשְׁמֵי שְׁמַיָא אַרְעָא וְכָל דִי בַהּ:
@306 לְחוֹד בַּאֲבָהָתָךְ צָבֵי יְיָ לְמִרְחַם יָתְהוֹן וְאִתִּרְעֵי בִּבְנֵיהוֹן בַּתְרֵיהוֹן בְּכוֹן מִכָּל עַמְמַיָא כְּיוֹמָא הָדֵין:
@307 וְתֶעְדוּן יָת טַפְשׁוּת לִבְּכוֹן וּקְדָלְכוֹן לָא תַקְשׁוּן עוֹד:
@308 אֲרֵי יְיָ אֱלָהֲכוֹן הוּא אֱלָהָא דַיָנִין וּמָרֵי מַלְכִין אֱלָהָא רַבָּא גִבָּרָא וּדְחִילָא דִי לֵית קֳדָמוֹהִי מִסַב אַפִּין וְאַף לָא לְקַבָּלָא שָׁחְדָא:
@309 עָבֵד דִין יִתַּם וְאַרְמְלָא וְרָחֵם גִיוֹרָא לְמִתַּן לֵהּ מְזוֹנָא וּכְסוּ:
@310 וְתִרְחֲמוּן יָת גִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@311 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִפְלָח וּלְדַחַלְתֵּהּ תִּקְרַב וּבִשְׁמֵהּ תְּקַיַם:
@312 הוּא תֻשְׁבַּחְתָּךְ וְהוּא אֱלָהָךְ דַעֲבַד עִמָךְ יָת רַבְרְבָתָא וְיָת חֲסִינָתָא הָאִלֵין דִי חֲזוֹ עֵינָיךְ:
@313 בְּשַׁבְעִין נַפְשָׁן נְחָתוּ אֲבָהָתָךְ לְמִצְרָיִם וּכְעַן שַׁוְיָךְ יְיָ אֱלָהָךְ כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי:
@314 וְתִרְחַם יָת יְיָ אֱלָהָךְ וְתִטַּר מַטְרַת מֵימְרֵהּ וּקְיָמוֹהִי וְדִינוֹהִי וּפִקוֹדוֹהִי כָּל יוֹמַיָא:
@315 וְתִדְעוּן יוֹמָא דֵין אֲרֵי לָא יָת בְּנֵיכוֹן דִי לָא יְדָעוּ וְדִי לָא חֲזוֹ יָת אֻלְפָנָא דַיְיָ אֱלָהֲכוֹן יָת רְבוּתֵהּ יָת יְדֵהּ תַּקִיפָא וּדְרָעֵהּ מְרָמְמָא:
@316 וְיָת אַתְוָתֵהּ וְיָת עוֹבָדוֹהִי דִי עֲבַד בְּגוֹ מִצְרָיִם לְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּלְכָל אַרְעֵהּ:
@317 וְדִי עֲבַד לְמַשִׁרְיַת מִצְרַיִם לְסוּסְוָתֵהּ וְלִרְתִיכוֹהִי דִי אַטִיף יָת מֵי יַמָא דְסוּף עַל אַפֵּיהוֹן בְּמִרְדָפְהוֹן בַּתְרֵיכוֹן וְאוֹבָדִנוּן יְיָ עַד יוֹמָא הָדֵין:
@318 וְדִי עֲבַד לְכוֹן בְּמַדְבְּרָא עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@319 וְדִי עֲבַד לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב בַּר רְאוּבֵן דִי פְתָחַת אַרְעָא יָת פּוּמַהּ וּבְלָעָתְנוּן וְיָת אֱנַשׁ בָּתֵּיהוֹן וְיָת מַשְׁכְּנֵיהוֹן וְיָת כָּל יְקוּמָא דִי עִמְהוֹן בְּגוֹ כָּל יִשְׂרָאֵל:
@320 אֲרֵי עֵינֵיכוֹן חֲזָאָן יָת כָּל עוֹבָדָא דַיְיָ רַבָּא דִי עֲבָד:
@321 וְתִטְרוּן יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין בְּדִיל דְתִתְקְפוּן וְתֵעֲלוּן וְתֵירְתוּן יָת אַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@322 וּבְדִיל דְתוֹרְכוּן יוֹמִין עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@323 אֲרֵי אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ לָא כְאַרְעָא דְמִצְרַיִם הִיא דִי נְפַקְתּוּן מִתַּמָן דִי תִזְרַע יָת זַרְעָךְ וּמַשְׁקַת לֵהּ בְּרַגְלָךְ כְּגִנְתָא יַרְקָא:
@324 וְאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ אֲרַע טוּרִין וּבִקְעָן לִּמְטַּר שְׁמַיָא תִּשְׁתֵּי מַיָא:
@325 אַרְעָא דַיְיָ אֱלָהָךְ תָּבַע יָתַהּ תְּדִירָא עֵינֵי דַיְיָ אֱלָהָךְ בַּהּ מֵרֵישָׁא דְשַׁתָּא וְעַד סוֹפָא דְשַׁתָּא:
@326 וִיהֵי אִם קַבָּלָא תְקַבְּלוּן לְפִקוּדַי דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן וּלְמִפְלַח קֳדָמוֹהִי בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@327 וְאֶתֵּן מְטַר אַרְעֲכוֹן בְּעִדָנֵהּ בַּכִּיר וְלַקִישׁ וְתִכְנוֹשׁ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ:
@328 וְאֶתֵּן עִשְׂבָּא בְחַקְלָךְ לִבְעִירָךְ וְתֵיכוּל וְתִשְׂבָּע:
@329 אִסְתַּמָרוּ לְכוֹן דִילְמָא יִטְעוּן לִבְּכוֹן וְתִסְטוּן וְתִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְתִסְגְדוּן לְהוֹן:
@330 וְיִתְקוֹף רָגְזָא דַיְיָ בְּכוֹן וְיֵחוֹד יָת שְׁמַיָא וְלָא יְהֵי מִטְרָא וְאַרְעָא לָא תִתֵּן יָת עֲלַלְתַּהּ וְתֵיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא טַבְתָא דַיְיָ יָהֵב לְכוֹן:
@331 וּתְשַׁווּן יָת פִּתְגָמַי אִלֵין עַל לִבְּכוֹן וְעַל נַפְשְׁכוֹן וְתִקְטְרוּן יָתְהוֹן לְאָת עַל יֶדְכוֹן וִיהוֹן לִתְפִלִין בֵּין עֵינֵיכוֹן:
@332 וְתַלְפוּן יָתְהוֹן יָת בְּנֵיכוֹן לְמַלָלָא בְהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@333 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@334 בְּדִיל דְיִסְגוּן יוֹמֵיכוֹן וְיוֹמֵי בְנֵיכוֹן עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן כְּיוֹמֵי שְׁמַיָא עַל אַרְעָא:
@335 אֲרֵי אִם מִטַר תִּטְרוּן יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקֵד יָתְכוֹן לְמֶעְבְּדַהּ לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן לִמְהַךְ בְּכָל אָרְחָן דְתַקְנָן קֳדָמוֹהִי וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ:
@336 וִיתָרֵךְ יְיָ יָת כָּל עַמְמַיָא הָאִלֵין מִקֳדָמֵיכוֹן וְתֵירְתוּן עַמְמִין רַבְרְבִין וְתַקִיפִין מִנְכוֹן:
@337 כָּל אַתְרָא דִי תִדְרוֹךְ פַּרְסַת רַגְלְכוֹן בֵּהּ דִלְכוֹן יְהֵי מִן מַדְבְּרָא וְלִבְנָן מִן נַהֲרָא נְהַר פְּרָת וְעַד יַמָא מַעַרְבָא יְהֵי תְחוּמְכוֹן:
@338 לָא יִתְעַתַּד אֱנָשׁ קֳדָמֵיכוֹן דַחֲלָתְכוֹן וְאֵימָתְכוֹן יִתֵּן יְיָ אֱלָהֲכוֹן עַל אַפֵּי כָל אַרְעָא דִי תִדְרְכוּן בַּהּ כְּמָה דִי מַלִיל לְכוֹן: ססס:
@339 חֲזֵי דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין בִּרְכָן וּלְוָטִין:
@340 יָת בִּרְכָן דִי תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֳלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@341 וּלְוָטִין אִם לָא תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֱלָהֲכוֹן וְתִסְטוּן מִן אָרְחָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@342 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל תַּמָן לְמֵירְתַהּ וְתִתֵּן יָת מְבָרְכַיָא עַל טוּרָא דִגְרִזִין וְיָת מְלַטְטַיָא עַל טוּרָא דְעֵיבָל:
@343 הֲלָא אִנוּן בְּעִבְרָא דְיַרְדְנָא אֲחוֹרֵי אֹרַח מַעֲלָנֵי שִׁמְשָׁא בְּאַרְעָא כְּנַעְנָאָה דְיָתֵב בְּמֵישְׁרָא לָקֳבֵל גִלְגְלָא בִּסְטַר מֵישְׁרֵי מֹרֶה:
@344 אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְמֵעַל לְמֵירַת יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְכוֹן וְתֵירְתוּן יָתַהּ וְתֵיתְבוּן בַּהּ:
@345 וְתִטְרוּן לְמֶעְבַּד יָת כָּל קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין:
@346 אִלֵין קְיָמַיָא וְדִינַיָא דִי תִטְרוּן לְמֶעְבַּד בְּאַרְעָא דִיהַב יְיָ אֱלָהָא דַאֲבְהָתָךְ לָךְ לְמֵירְתַהּ כָּל יוֹמַיָא דִי אַתּוּן קַיָמִין עַל אַרְעָא:
@347 אַבָּדָא תְאַבְּדוּן יָת כָּל אַתְרַיָא דִי פְלָחוּ תַמָן עַמְמַיָא דִי אַתּוּן יָרְתִין יָתְהוֹן יָת טַעֲוָתְהוֹן עַל טוּרַיָא רָמַיָא וְעַל רָמָתָא וּתְחוֹת כָּל אִילַן עַבּוֹף:
@348 וּתְתָרְעוּן יָת אֱגוֹרֵיהוֹן וּתְתַבְּרוּן יָת קָמָתְהוֹן וַאֲשֵׁרֵיהוֹן תּוֹקְדוּן בְּנוּרָא וְצַלְמֵי טַעֲוָתְהוֹן תְּקוֹצְצוּן וְתוֹבְדוּן יָת שִׁמְהוֹן מִן אַ:תרָא הַהוּא:
@349 לָא תַעְבְּדוּן כֵּן קֳדָם יְיָ אֱלָהָכוֹן:
@350 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן מִכָּל שִׁבְטֵּיכוֹן לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְבֵית שְׁכִנְתֵּהּ תִּתְבְּעוּן וְתֵיתוּן לְתַמָן:
@351 וְתַיְתוּן לְתַמָן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְיָת מַעְשְׂרָתֵיכוֹן וְיָת אַפְרָשׁוּת יֶדְכוֹן וְנִדְרֵיכוֹן וְנִדְבָתֵיכוֹן וּבְכוֹרֵי תוֹרְכוֹן וְעָנְכוֹן:
@352 וְתֵיכְלוּן תַּמָן קֳדָם יְיָ אֱלָהֲכוֹן וְתֶחֱדוּן בְכֹל אוֹשָׁטוּת יֶדְכוֹן אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן דִי בָרְכָךְ יְיָ אֱלָהָךְ:
@353 לָא תַעְבְּדוּן כְּכֹל דִי אֲנַחְנָא עָבְדִין הָכָא יוֹמָא דֵין גְבַר כָּל מָן דְכָשַׁר קֳדָמוֹהִי:
@354 אֲרֵי לָא אֲתֵיתוּן עַד כְּעָן לְבֵית נְיָחָא וּלְאַחֲסָנָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@355 וְתַעְבְּרוּן יָת יַרְדְנָא וְתֵיתְבוּן בְּאַרְעָא דַיְיָ אֱלָהֲכוֹן מַחְסֵן יָתְכוֹן וִינִיחַ לְכוֹן מִכָּל בַּעֲלֵי דְבָבֵיכוֹן מִסְחוֹר סְחוֹר וְתֵיתְבוּן לְרָחְצָן:
@356 וִיהֵי אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן בֵּהּ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְתַמָן תַּיְתוּן יָת כָּל דִי אֲנָא מְפַקֵד יָתְכוֹן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן מַעְשְׂרָתֵיכוֹן וְאַפְרָשׁוּת יֶדְכוֹן וְכֹל שְׁפַר נִדְרֵיכוֹן דִי תִדְרוּן קֳדָם יְיָ:
@357 וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְלֵוָאָה דִי בְקִרְוֵיכוֹן אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמְכוֹן:
@358 אִסְתַּמַר לָךְ דִילְמָא תַסֵק עֲלָוָתָךְ בְּכָל אַתְרָא דִי תֶחֱזֵי:
@359 אֶלָהֵן בְּאַתְרָא דִי יִתִּרְעֵי יְיָ בְּחַד מִן שִׁבְטָיךְ תַּמָן תַּסֵק עֲלָוָתָךְ וְתַמָן תַּעְבֵּד כֹּל דִי אֲנָא מְפַקְדָךְ:
@360 לְחוֹד בְּכָל רְעוּת נַפְשָׁךְ תִּכּוֹס וְתֵיכוּל בִּשְׂרָא כְּבִרְכְּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ בְּכָל קִרְוָיךְ מְסָאָבָא וְדַכְיָא יֵכְלֻנֵהּ כִּבְשַׂר טַבְיָא וְאַיְלָא:
@361 לְחוֹד דְמָא לָא תֵיכְלוּן עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@362 לֵית לָךְ רְשׁוּ לְמֵיכַל בְּקִרְוָיךְ מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ וְכָל נִדְרָךְ דִי תִדַר וְנִדְבָתָיךְ וְאַפְרָשׁוּת יְדָךְ:
@363 אֱלָהֵן קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ בְּכָל אוֹשָׁטּוּת יְדָךְ:
@364 אִסְתַּמַר לָךְ דִילְמָא תִשְׁבּוֹק יָת לֵוָאֵי כָּל יוֹמָיךְ עַל אַרְעָךְ:
@365 אֲרֵי יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי מַלִיל לָךְ וְתֵימַר אֵיכוּל בִּשְׂרָא אֲרֵי תִתִּרְעֵי נַפְשָׁךְ לְמֵיכַל בִּשְׂרָא בְּכָל רְעוּת נַפְשָׁךְ תֵּיכוּל בִּשְׂרָא:
@366 אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן וְתִכּוֹס מִתּוֹרָךְ וּמֵעָנָךְ דִי יְהַב יְיָ לָךְ כְּמָא דִי פַּקֵדִתָּךְ וְתֵיכוּל בְּקִרְוָיךְ בְּכֹל רְעוּת נַפְשָׁךְ:
@367 בְּרַם כְּמָא דִי מִתְאֲכֵל בְּשַׂר טַבְיָא וְאַיְלָא כֵּן תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא יֵכְלִנֵהּ:
@368 לְחוֹד תְּקֵף בְּדִיל דְלָא לְמֵיכַל דְּמָא אֲרֵי דְמָא הוּא נַפְשָׁא וְלָא תֵיכוּל נַפְשָׁא עִם בִּשְׂרָא:
@369 לָא תֵּיכְלִנֵהּ עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@370 לָא תֵּיכְלִנֵהּ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ אֲרֵי תַעְבֵּד דְכָשָׁר קֳדָם יְיָ:
@371 לְחוֹד מַעְשַׂר קוּדְשָׁיךְ דִיהוֹן לָךְ וְנִדְרָךְ תִּטוֹל וְתֵיתֵי לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@372 וְתַעְבֵּד עֲלָוָתָךְ בִּשְׂרָא וּדְמָא עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וְדַם נִכְסַת קוּדְשָׁיךְ יִתָּשַׁד עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וּבִשְׂרָא תֵּיכוּל:
@373 טַר וּתְקַבֵּל יָת כָּל פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ עַד עֳלָם אֲרֵי תַעְבֵּד דְתָקֵן וּדְכָשַׁר קֳדָם יְיָ אֱלָהָךְ:
@374 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי אַתְּ עָלֵל לְתַמָן לְתָרָכָא יָתְהוֹן מִקֳדָמָךְ וְתֵירַת יָתְהוֹן וְתֵיתַב בְּאַרְעֲהוֹן:
@375 אִסְתַּמַר לָךְ דִילְמָא תִתָּקַל בַּתְרֵיהוֹן בָּתַר דְיִשְׁתֵּצוּן מִקֳדָמָךְ וְדִילְמָא תִתְבַּע לְטַעֲוָתְהוֹן לְמֵימַר אֶכְדֵין פָּלְחִין עַמְמַיָא הָאִלֵין יָת טַעֲוָתְהוֹן וְאֶעְבֵּד כֵּן אַף אֲנָא:
@376 לָא תַעְבֵּד כֵּן קֳדָם יְיָ אֱלָהָךְ אֲרֵי כָּל דִמְרָחָק קֳדָם יְיָ דִי סָנֵי עֲבָדוּ לְטַעֲוָתְהוֹן אֲרֵי אַף יָת בְּנֵיהוֹן וְיָת בְּנָתֵיהוֹן מוֹקְדִין בְּנוּרָא לְטַּעֲוָתְהוֹן:
@377 יָת כָּל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן יָתֵהּ תִּטְרוּן לְמֶעְבָּד לָא תוֹסְפוּן עֲלוֹהִי וְלָא תִמְנְעוּן מִנֵהּ:
@378 אֲרֵי יְקוּם בֵּינָךְ נְבִיָא אוֹ חָלֵם חֶלְמָא וְיִתֶּן לָךְ אָת אוֹ מוֹפְתָא:
@379 וְיֵיתֵי אָתָא וּמוֹפְתָא דִי מַלִיל עִמָךְ לְמֵימָר נְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתָּנוּן וְנִפְלְחִנוּן:
@380 לָא תְקַבֵּל לְפִתְגָמֵי נְבִיָא הַהוּא אוֹ לְחָלֵם חֶלְמָא הַהוּא אֲרֵי מְנַסֵי יְיָ אֱלָהֲכוֹן יָתְכוֹן לְמִדַע הַאִיתֵיכוֹן רָחֲמִין יָת יְיָ אֱלָהֲכוֹן בְכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@381 בָּתַר דַחַלְתָּא דַיְיָ אֱלָהֲכוֹן תְהָכוּן וְיָתֵהּ תִּדְחֲלוּן וְיָת פִּקוּדוֹהִי תִטְּרוּן וּלְמֵימְרֵהּ תְּקַבְּלוּן וְקָדָמוֹהִי תִפְלְחוּן וּבְדַחַלְתֵּהּ תִּתְקָרְבוּן:
@382 וּנְבִיָא הַהוּא אוֹ חָלֵם חֶלְמָא הַהוּא יִתְקְטֵּל אֲרֵי מַלִיל סַטְיָא עַל יְיָ אֱלָהֲכוֹן דִי אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם וּדְפָרְקָךְ מִבֵּית עַבְדוּתָא לְאַטְעֲיוּתָךְ מִן אָרְחָא דִי פַקְדָךְ יְיָ אֱלָהָךְ לִמְהַךְ בַּהּ וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@383 אֲרֵי יְמַלְכִנָךְ אֲחוּךְ בַּר אִמָךְ אוֹ בְרָךְ אוֹ בְרַתָּךְ אוֹ אִתַּת קְיָמָךְ אוֹ חַבְרָךְ דִי כְנַפְשָׁךְ בְּסִתְרָא לְמֵימַר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ:
@384 מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן דִקְרִיבִין לָךְ אוֹ דִרְחִיקִין מִנָךְ מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא:
@385 לָא תֵיבֵי לֵהּ וְלָא תְקַבֵּל מִנֵהּ וְלָא תְחוּס עֵינָךְ עֲלוֹהִי וְלָא תְרַחַם וְלָא תְכַסֵי עֲלוֹהִי:
@386 אֲרֵי מִקְטַל תִּקְטְּלִנֵהּ יְדָךְ תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְבַתְרֵיתָא:
@387 וְתִרְגְמִנֵהּ בְּאַבְנַיָא וִימוּת אֲרֵי בָעָא לְאַטְעֲיוּתָךְ מִדַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@388 וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@389 אֲרֵי תִשְׁמַע בְּחַד מִקִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמִתַּב תַּמָן לְמֵימָר:
@390 נְפָקוּ גֻבְרִין בְּנֵי רִשְׁעָא מִבֵּינָךְ וְאַטְעָיוּ יָת יָתְבֵי קַרְתְּהוֹן לְמֵימָר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@391 וְתִתְבַּע וְתִבְדוֹק וְתִשְׁאַל יָאוּת וְהָא קֻשְׁטָּא כֵּוַן פִּתְגָמָא אִתְעֲבִידָא תּוֹעֶבְתָּא הָדָא בֵּינָךְ:
@392 מִמְחָא תִמְחֵי יָת יָתְבֵי קַרְתָּא הַהִיא לְפִתְגַם דְחָרֶב גַמַר יָתַהּ וְיָת כָּל דִי בַהּ וְיָת בְּעִירַהּ לְפִתְגַם דְחָרֶב:
@393 וְיָת כָּל עֲדָאַהּ תִּכְנוֹשׁ לְגוֹ פְתָיַהּ וְתוֹקֵד בְּנוּרָא יָת קַרְתָּא וְיָת כָּל עֲדָאַהּ גְמִיר קֳדָם יְיָ אֱלָהָךְ וּתְהֵי תֵּל חָרִיב לְעָלָם לָא תִתְבְּנֵי עוֹד:
@394 וְלָא יִדְבַּק בִּידָךְ מִדַעַם מִן חֶרְמָא בְּדִיל דִיתוּב יְיָ מִתְּקוֹף רוּגְזֵהּ וִיהַב לָךְ רַחֲמִין וִירַחַם עֲלָךְ וְיַסְגִנָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ:
@395 אֲרֵי תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבַּד דְכָשָׁר קֳדָם יְיָ אֱלָהָךְ:
@396 בְּנִין אַתּוּן קֳדָם יְיָ אֱלָהֲכוֹן לָא תִתְחַמְמוּן וְלָא תְשַׁווּן מְרָט בֵּין עֵינֵיכוֹן עַל מִית:
@397 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ וּבָךְ אִתִּרְעֵי יְיָ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכָּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@398 לָא תֵיכוּל כָּל דִמְרָחָק:
@399 דֵין בְּעִירָא דְתֵיכְלוּן תּוֹרִין אִמְרִין דִרְחֵלִין וְגָדְיָן דְעִזִין:
@400 אַיָלָא וְטַבְיָא וְיַחְמוּרָא וְיַעְלָא וְרֵימָא וְתוֹרְבָּלָא וְדִיצָא:
@401 וְכָל בְּעִירָא דִסְדִיקָא פַרְסָתָא וּמַטִלְפָא טִלְפִין תַּרְתֵּין פַּרְסָתָא מַסְקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@402 בְּרַם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַרְסָתָא מַטִלְפֵי טִלְפַיָא יָת גַמְלָא וְיָת אַרְנְבָא וְיָת טַּפְזָא אֲרֵי מַסְקֵי פִּשְׁרָא אִנוּן וּפַרְסָתְהוֹן לָא סְדִיקָא מְסָאֲבִין אִנוּן לְכוֹן:
@403 וְיָת חֲזִירָא אֲרֵי מַסְדִיק פַּרְסָתָא הוּא וְלָא פָשַׁר מְסָאָב הוּא לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבֵלְתְּהוֹן לָא תִקְרְבוּן:
@404 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין תֵּיכְלוּן:
@405 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין לָא תֵיכְלוּן מְסָאָב הוּא לְכוֹן:
@406 כָּל צִפַּר דַכְיָא תֵּיכְלוּן:
@407 וְדֵין דִי לָא תֵיכְלוּן מִנְהוֹן נִשְׁרָא וְעָר וְעַזְיָא:
@408 וּבַת כַּנְפָא וְטָרָפִיתָא וְדַיְתָא לִזְנַהּ:
@409 וְיָת כָּל עֹרְבָא לִזְנֵהּ:
@410 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:
@411 וְקַדְיָא וְקִפוֹפָא וּבַוְתָא:
@412 וְקָתָא וִירַקְרֵקָא וְשָׁלֵי נוּנָא:
@413 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַּלֵפָא:
@414 וְכֹל רִחֲשָׁא דְעוֹפָא מְסָאָב הוּא לְכוֹן לָא יִתְאָכְלוּן:
@415 כָּל עוֹפָא דְכֵי תֵּיכְלוּן:
@416 לָא תֵיכְלוּן כָּל נְבִילָא לְתוֹתָב עָרֵל דִי בְקִרְוָיךְ תִּתְּנִנַהּ וְיֵיכְלִנַהּ אוֹ תְזַבְּנִנַהּ לְבַר עַמְמִין אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ לָא תֵיכוּל בְּשַׂר בַּחֲלָב:
@417 עַשְׂרָא תְעַשַׂר יָת כָּל עֲלָלַת זַרְעָךְ דְיִפּוֹק חַקְלָא שַׁתָּא בְשַׁתָּא:
@418 וְתֵיכוּל קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ בְּדִיל דְתֵילַף לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ כָּל יוֹמַיָא:
@419 וַאֲרֵי יִסְגֵי מִנָךְ אָרְחָא אֲרֵי לָא תִכּוּל לְמִטְלֵהּ אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@420 וְתִתֵּן בְּכַסְפָּא וּתְצוּר כַּסְפָּא בִּידָךְ וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@421 וְתִתֵּן כַּסְפָּא בְּכֹל דִי יִתִּרְעֵי נַפְשָׁךְ בְּתוֹרֵי וּבְעָנָא וּבַחֲמַר חֲדַת וְעַתִּיק וּבְכֹל דִי תִשְׁאֲלִנָךְ נַפְשָׁךְ וְתֵיכוּל תַּמָן קֳדָם יְיָ אֱלָהָךְ וְתֶחֱדֵי אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@422 וְלֵוָאָה דִי בְקִרְוָיךְ לָא תִשְׁבְּקִנֵהּ אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ:
@423 מִסוֹף תְּלַת שְׁנִין תַּפֵק יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא הַהִיא וְתַצְנַע בְּקִרְוָיךְ:
@424 וְיֵיתֵי לֵוָאָה אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ וְיֵיכְלוּן וְיִשְׂבְּעוּן בְּדִיל דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדֵי יְדָךְ דִי תַעְבֵּד:
@425 מִסוֹף שְׁבַע שְׁנִין תַּעְבֵּד שְׁמִטְתָא:
@426 וְדֵין פִּתְגַם שְׁמִטְתָא דְתַשְׁמֵט כָּל גְבַר מַרֵי רְשׁוּ דִי יַרְשֵׁי בְּחַבְרֵהּ לָא יִתְבַּע מִן חַבְרֵהּ וּמִן אֲחוּהִי אֲרֵי קְרָא שְׁמִטְתָא קֳדָם יְיָ:
@427 מִן בַּר עַמְמִין תִּתְבַּע וְדִי יְהֵי לָךְ עִם אָחוּךְ תַּשְׁמֵט יְדָךְ:
@428 לְחוֹד אֲרֵי לָא יְהֵי בָךְ מִסְכֵּנָא אֲרֵי בָרָכָא יְבָרֵכִנָךְ יְיָ בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ:
@429 לְחוֹד אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@430 אֲרֵי יְיָ אֱלָהָךְ בָּרְכָךְ כְּמָא דִי מַלִיל לָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף וְתִשְׁלוֹט בְּעַמְמִין סַגִיאִין וּבָךְ לָא יִשְׁלְטוּן:
@431 אֲרֵי יְהֵי בָךְ מִסְכֵּנָא מֵחַד מֵאַחָיךְ בַּחֲדָא מִקִרְוָיךְ בְּאַרְעָךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תַתְקֵף יָת לִבָּךְ וְלָא תִקְפֹּץ יָת יְדָךְ מֵאֲחוּךְ מִסְכֵּנָא:
@432 אֶלָא מִפְתַּח תִּפְתַּח יָת יְדָךְ לֵהּ וְאוֹזָפָא תּוֹזְפִנֵהּ כְּמִסַת חֶסְרוֹנֵהּ דְיַחֲסִיר לֵהּ:
@433 אִסְתַּמַר לָךְ דִילְמָא יְהֵי פִתְגָם עִם לִבָּךְ בִּרְשַׁע לְמֵימַר קְרִיבָא שַׁתָּא שְׁבִיעֲתָא שַׁתָּא דִשְׁמִטְתָא וְתַבְאֵשׁ עֵינָךְ בְּאָחוּךְ מִסְכֵּנָא וְלָא תִתֵּן לֵהּ וְיִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@434 מִתַּן תִתֵּן לֵהּ וְלָא יַבְאֵשׁ לִבָּךְ בְּמִתְּנָךְ לֵהּ אֲרֵי בְּדִיל פִּתְגָמָא הָדֵין יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ:
@435 אֲרֵי לָא יִפְסוֹק מִסְכֵּנָא מִגוֹ אַרְעָא עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימַר מִפְתַּח תִּפְתַּח יָת יְדָךְ לַאֲחוּךְ לְעַנְיָךְ וּלְמִסְכֵּנָךְ בְּאַרְעָךְ:
@436 אֲרֵי יִזְדַבַּן לָךְ אֲחוּךְ בַּר יִשְׂרָאֵל אוֹ בַּת יִשְׂרָאֵל וְיִפְלְחִנָךְ שִׁית שְׁנִין וּבְשַׁתָּא שְׁבִיעֲתָא תִּפְטְרִנֵהּ בַּר חוֹרִין מֵעִמָךְ:
@437 וַאֲרֵי תִפְטְרִנֵה בַּר חוֹרִין מֵעִמָךְ לָא תִפְטְּרִנֵה רֵיקָן:
@438 אַפְרָשָׁא תַפְרֵשׁ לֵהּ מֵעָנָךְ וּמֵאִדְרָךְ וּמִמַעֲצַרְתָּךְ דִי בָרְכָךְ יְיָ אֱלָהָךְ תִּתֶּן לֵהּ:
@439 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ עַל כֵּן אֲנָא מְפַקְדָךְ יָת פִּתְגָמָא הָדֵין יוֹמָא דֵין:
@440 וִיהֵי אֲרֵי יֵימַר לָךְ לָא אֶפוֹק מֵעִמָךְ אֲרֵי רָחֲמָךְ וְיָת אֱנַשׁ בֵּיתָךְ אֲרֵי טַב לֵהּ עִמָךְ:
@441 וְתִסַב יָת מַרְצְעָא וְתִתֵּן בְּאֻדְנֵהּ וּבְדָשָׁא וִיהֵי לָךְ עִבֵד פָּלַח לְעָלָם וְאַף לְאַמְתָךְ תַּעְבֶּד כֵּן:
@442 לָא יִקְשֵׁי בְעֵינָךְ בְּמִפְטְרָךְ יָתֵהּ בַּר חוֹרִין מֵעִמָךְ אֲרֵי עַל חַד תְּרֵין כַּאֲגַר אֲגִירָא פָּלְחָךְ שִׁית שְׁנִין וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל דִי תַעְבֵּד:
@443 כָּל בּוּכְרָא דִי יִתְיְלִיד בְּתוֹרָךְ וּבְעָנָךְ דִכְרִין תַּקְדֵשׁ קָדָם יְיָ אֱלָהָךְ לָא תִפְלַח בְּבוּכְרָא דְתוֹרָךְ וְלָא תֵגוֹז בּוּכְרָא דְעָנָךְ:
@444 קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ שַׁתָּא בְשַׁתָּא בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@445 וַאֲרֵי יְהֵי בֵהּ מוּמָא חֲגִיר אוֹ עֲוִיר כֹּל מוּם בִּישׁ לָא תִכְּסִנֵהּ קֳדָם יְיָ אֱלָהָךְ:
@446 בְּקִרְוָיךְ תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא כִּבְסַר טַבְיָא וְאַיְלָא:
@447 לְחוֹד יָת דְמֵהּ לָא תֵיכוּל עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@448 טַר יָת יַרְחָא דַאֲבִיבָא וְתַעְבֵּד פִּסְחָא קֳדָם יְיָ אֱלָהָךְ אֲרֵי בְּיַרְחָא דַאֲבִיבָא אַפְּקָךְ יְיָ אֱלָהָךְ מִמִצְרַיִם וַעֲבַד לָךְ נִסִין בְּלֵילְיָא:
@449 וְתִכּוֹס פִּסְחָא קֳדָם יְיָ אֱלָהָךְ מִן בְּנֵי עָנָא וְנִכְסַת קוּדְשַׁיָא מִן תּוֹרֵי בְּאַתְרָא דִי יִתִּרְעֵי יְיָ לְאַשְׁרָאָה שְׁכִנְתֵּה תַּמָן:
@450 לָא תֵיכוּל עֲלוֹהִי חֲמִיעַ שִׁבְעָא יוֹמִין תֵּיכוּל עֲלוֹהִי פַטִיר לְחֵם עֹנִי אֲרֵי בִּבְהִילוּ נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם בְּדִיל דְתִדְכַּר יָת יוֹמָא מִפְּקָךְ מֵאַרְעָא דְמִצְרַיִם כָּל יוֹמֵי חַיָיךְ:
@451 וְלָא יִתְחֲזֵי לָךְ חֲמִר בְּכָל תְּחוּמָךְ שִׁבְעָא יוֹמִין וְלָא יְבִית מִן בִּסְרָא דִי תִכּוֹס בְּרַמְשָׁא בְּיוֹמָא קַדְמָאָה לְצַפְרָא:
@452 לֵית לָךְ רְשׁוּ לְמִכֹּס יָת פִּסְחָא בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@453 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן תִּכּוֹס יָת פִּסְחָא בְּרַמְשָׁא כְּמֵעַל שִׁמְשָׁא זְמַן מִפְקָךְ מִמִצְרָיִם:
@454 וּתְבַשֵׁל וְתֵיכוּל בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ וְתִתְפְּנֵי בְצַפְרָא וּתְהַךְ לְקִרְוָיךְ:
@455 שִׁתָּא יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה כְּנֵשׁ קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד עִבִידָא:
@456 שִׁבְעָא שָׁבוּעִין תִּמְנֵי לָךְ מִדְשַׁרְיוּת מַגְלָא בַּחֲצַד עוּמְרָא דַאֲרָמוּתָא תִּשְׁרֵי לְמִמְנֵּי שִׁבְעָא שָׁבוּעִין:
@457 וְתַעְבֵּד חַגָא דְשָׁבוּעַיָא קֳדָם יְיָ אֱלָהָךְ מִסַת נִדְבַת יְדָךְ דִי תִתֵּן כְּמָא דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@458 וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בֵינָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@459 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרָיִם וְתִטַר וְתַעְבֵּד יָת קְיָמַיָא הָאִלֵין:
@460 חַגָא דִמְטָלַיָא תַּעְבֵּד לָךְ שִׁבְעָא יוֹמִין בְּמִכְנְשָׁךְ מֵאִדְרָךְ וּמִמַעְצַרְתָּךְ:
@461 וְתֶחֱדֵי בְּחַגָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ:
@462 שִׁבְעָא יוֹמִין תֵּחוֹג קָדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עֲלַלְתָּךְ וּבְכָל עוֹבָדֵי יְדָיךְ וּתְהֵי בְּרַם חָדֵי:
@463 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזֵי כָל דְכוּרָךְ קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי בְּחַגָא דְפַטִירַיָא וּבְחַגָא דְשָׁבוּעַיָא וּבְחַגָא דִמְטָּלַיָא וְלָא יִתְחֲזֵי קֳדָם יְיָ רֵיקָנוּן:
@464 גְבַר כְּמַתְּנַת יְדֵהּ כְּבִרְכָּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ: ססס:
@465 דַיָנִין וּפֻרְעָנִין תְּמַנֵי לָךְ בְּכֹל קִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְשִׁבְטָיךְ וִידוּנוּן יָת עַמָא דִין דִקְשׁוֹט:
@466 לָא תַצְלֵי דִין לָא תִשְׁתְּמוֹדַע אַפִּין וְלָא תְקַבֵּל שֹׁחֲדָא אֲרֵי שֹׁחֲדָא מְעַוֵּר עֵינֵי חַכִּימִין וּמְקַלְקַל פִּתְגָמִין תְּרִיצִין:
@467 קֻשְׁטָא קֻשְׁטָא תְּהֵי רָדִיף בְּדִיל דְתֵיחֵי וְתֵירַת יָת אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@468 לָא תִצוֹב לָךְ אֲשֵׁרַת כָּל אִילָן בִּסְטַר מַדְבְּחָא דַיְיָ אֱלָהָךְ דִי תַעְבֶּד לָךְ:
@469 וְלָא תְקִים לָךְ קָמָא דִי סָנֵי יְיָ אֱלָהָךְ:
@470 לָא תִכּוֹס קֳדָם יְיָ אֱלָהָךְ תּוֹר וְאִמָר דִי יְהֵי בֵהּ מוּמָא כֹּל מִדַעַם בִּישׁ אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ הוּא:
@471 אֲרֵי יִשְׁתְּכַח בֵּינָךְ בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ גְבַר אוֹ אִתְּתָא דִי יַעְבֵּד יָת דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְמֶעְבַּר עַל קְיָמֵהּ:
@472 וַאֲזַל וּפְלַח לְטַעֲוַת עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילֵי שְׁמַיָא דִי לָא פַקֵדִית:
@473 וְיִתְחַוֵי לָךְ וְתִשְׁמַע וְתִתְבַּע יָאוּת וְהָא קֻשְׁטָא כֵּוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֶבְתָּא הָדָא בְּיִשְׂרָאֵל:
@474 וְתַפֵּק יָת גַבְרָא הַהוּא אוֹ יָת אִתְּתָא הַהִיא דִי עֲבָדוּ יָת פִּתְגָמָא בִישָׁא הָדֵין לִתְרַע בֵּית דִינָךְ יָת גַבְרָא אוֹ יָת אִתְּתָא וְתִרְגְמִנוּן בְּאַבְנַיָא וִימוּתוּן:
@475 עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטִל דְחַיַב קְטוֹל לָא יִתְקְטֵל עַל מֵימַר סָהִיד חָד:
@476 יְדָא דְסַהֲדַיָא תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְּבַתְרֵיתָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@477 אֲרֵי יִתְכַסֵי מִנָךְ פִּתְגָמָא לְדִינָא בֵּין דְמָא לִדְמָא בֵּין דִינָא לְדִינָא וּבֵין מַכְתַּשׁ סְגִירוּ לְמַכְתַּשׁ סְגִירוּ פִּתְגָמֵי פְלֻגְתָּא דִינָא בְּקִרְוָיךְ וּתְקוּם וְתִסַק לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@478 וְתֵיתֵי לְוָת כָּהֲנַיָא לֵוָאֵי וּלְוָת דַיָנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתִתְבַּע וִיחַוּוּן לָךְ יָת פִּתְגָמָא דְדִינָא:
@479 וְתַעְבֵּד עַל מֵימַר פִּתְגָמָא דִי יְחַוּוּן לָךְ מִן אַתְרָא הַהוּא דִי יִתִּרְעֵי יְיָ וְתִטַר לְמֶעְבַּד כְּכֹל דִי יַלְפֻנָךְ:
@480 עַל מֵימַר אוֹרַיְתָא דִי יַלְפֻנָךְ וְעַל דִינָא דִי יֵימְרוּן לָךְ תַּעְבֵּד לָא תִסְטֵּי מִן פִּתְגָמָא דִי יְחַוּוּן לָךְ יַמִינָא וּשְׂמָאלָא:
@481 וּגְבַר דִי יַעְבֵּד בִּרְשַׁע בְּדִיל דְלָא לְקַבָּלָא מִן כַּהֲנָא דְקָאֵם לְשַׁמָשָׁא תַמָן קֳדָם יְיָ אֱלָהָךְ אוֹ מִן דַיָנָא וְיִתְקְטֵל גַבְרָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@482 וְכָל עַמָא יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יַרְשִׁיעוּן עוֹד:
@483 אֲרֵי תֵעוֹל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וְתֵירְתַהּ וְתֵיתֵב בַּהּ וְתֵימַר אֱמַנִי עֲלַי מַלְכָּא כְּכָל עַמְמַיָא דִי בְסַחֲרָנָי:
@484 מַנָאָה תְמַנֵי עֲלָךְ מַלְכָּא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ מִגוֹ אַחָיךְ תְּמַנֵי עֲלָךְ מַלְכָּא לֵת לָךְ רְשׁוּ לְמַנָאָה עֲלָךְ גְבַר נוּכְרַי דִי לָא אֲחוּךְ הוּא:
@485 לְחוֹד לָא יַסְגֵי לֵהּ סוּסָוָן וְלָא יָתֵב יָת עַמָא לְמִצְרָיִם בְּדִיל לְאַסְגָּאָה לֵהּ סוּסָוָן וַיְיָ אֲמַר לְכוֹן לָא תוֹסְפוּן לְמִתוּב בְּאֹרַח הָדֵין עוֹד:
@486 וְלָא יַסְגֵי לֵהּ נְשִׁין וְלָא יִטְעֵי לִבֵּהּ וְכַסְפָּא וְדַהַבָא לָא יַסגֵי לֵהּ לַחֲדָא:
@487 וִיהֵי:כְמִתְּבֵהּ עַל כָּרְסָא מַלְכוּתֵהּ וְיִכְתּוֹב לֵהּ יָת פַּתְשֶׁגֶן אוֹרַיְתָא הָדָא עַל סִפְרָא מִן קֳדָם כָּהֲנַיָא לֵוָאֵי:
@488 וּתְהֵי עִמֵהּ וִיהֵי קָרֵי בֵהּ כָּל יוֹמֵי חַיוֹהִי בְּדִיל דְיֵלַף לְמִדְחַל קֳדָם יְיָ אֱלָהֵהּ לְמִטַּר יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא וְיָת קְיָמַיָא הָאִלֵין לְמֶעְבָּדְהוֹן:
@489 בְּדִיל דְלָא יְרִים לִבֵּהּ מֵאֲחוֹהִי וּבְדִיל דְלָא יִסְטֵּי מִן תַּפְקֶדְתָּא יַמִינָא וּשְׂמָאלָא בְּדִיל דְיוֹרֵךְ יוֹמִין עַל מַלְכוּתֵהּ הוּא וּבְנוֹהִי בְּגוֹ יִשְׂרָאֵל:
@490 לָא יְהֵי לְכָהֲנַיָא לֵוָאֵי כָּל שִׁבְטָא דְלֵוִי חֳלָק וְאַחֲסָנָא עִם יִשְׂרָאֵל קֻרְבָּנַיָא דַיְיָ וְאַחֲסַנְתֵּהּ יֵיכְלוּן:
@491 וְאַחֲסָנָא לָא יְהֵי לֵהּ בְּגוֹ אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל לֵהּ:
@492 וְדֵין יְהֵי דְחָזֵי לְכָהֲנַיָא מִן עַמָא מִן נָכְסֵי נִכְסָתָא אִם תּוֹר אִם אִמָר וְיִתֵּן לְכַהֲנָא דְרוֹעָא וְלוֹעָא וְקֻבְתָא:
@493 רֵישׁ עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וְרֵישׁ גִזָא דְעָנָךְ תַּפְרֵשׁ לֵהּ:
@494 אֲרֵי בֵהּ יִתִּרְעֵי יְיָ אֱלָהָךְ מִכָּל שִׁבְטָיךְ לְמֵקַם לְשַׁמָשָׁא בִשְׁמָא דַיְיָ הוּא וּבְנוֹהִי כָּל יוֹמַיָא:
@495 וַאֲרֵי יֵיתֵי לֵוָאָה מֵחֲדָא מִקִרְוָיךְ מִכָּל יִשְׂרָאֵל דִי הוּא דָר תַּמָן וְיֵיתֵי בְּכָל רְעוּת נַפְשֵׁהּ לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@496 וִישַׁמַשׁ בִּשְׁמָא דַיְיָ אֱלָהֵהּ כְּכָל אֲחוֹהִי לֵוָאֵי דִמְשַׁמְשִׁין תַּמָן (בִּצְלוֹ) קֳדָם יְיָ:
@497 חֳלָק כָּחֳלָק יֵיכְלוּן בַּר מִמַטַרְתָּא דְיֵיתֵי בְּשַׁבַּתָּא דְכֵן אַתְקִינוּ אֲבָהָתָא:
@498 אֲרֵי אַתְּ עָלֵל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תֵילַף לְמֶעְבַּד כְּתֹעֲבַת עַמְמַיָא הָאִנוּן:
@499 לָא יִשְׁתְּכַח בָּךְ מַעֲבַר בְּרֵהּ וּבְרַתֵּהּ בְּנוּרָא קָסֵם קֻסְמִין מְעָנֵן וּמְנַחֵשׁ וְחָרָשׁ:
@500 וְרָטִין רְטָן וְשָׁאֵל בִּדִין וּדְכוּרוּ וְתָבַע מִן מֵתַיָא:
@501 אֲרֵי מְרָחָק יְיָ כָּל דְיַעְבֵּד אִלֵין וּבְדִיל תּוֹעֲבָתָא הָאִלֵין יְיָ אֱלָהָךְ מְתָרַךְ יָתְהוֹן מִקֳדָמָךְ:
@502 שְׁלִים תְּהֵי בְּדַחַלְתָּא דַיְיָ אֱלָהָךְ:
@503 אֲרֵי עַמְמַיָא הָאִלֵין דִי אַתְּ יָרֵת יָתְהוֹן מִן מְעָנְנַיָא וּמִן קַסָמַיָא שָׁמְעִין וְאַתְּ לָא כֵן יְהַב לָךְ יְיָ אֱלָהָךְ:
@504 נְבִיָא מִבֵּינָךְ מֵאַחָיךְ כְּוָתִי יְקִים לָךְ יְיָ אֱלָהָךְ מִנֵהּ תְּקַבְּלוּן:
@505 כְּכֹל דִי שְׁאֶלְתָּא מִקֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב בְּיוֹמָא דִקְהָלָא לְמֵימָר לָא אוֹסֵף לְמִשְׁמָע יָת קָל מֵימְרָא דַיְיָ אֱלָהַי וְיָת אֶשָׁתָא רַבְּתָא הָדָא לָא אֶחֱזֵי עוֹד וְלָא אֵמוּת:
@506 וַאֲמַר יְיָ לִי אוֹטִיבוּ דִי מַלִילוּ:
@507 נְבִיָא אֲקִים לְהוֹן מִגוֹ אֲחֵיהוֹן כְּוָתָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵהּ וִימַלֵל עִמְהוֹן יָת כָּל דִי אֲפַקְדִנֵהּ:
@508 וִיהֵי גַבְרָא דִי לָא יְקַבֵּל לְפִתְגָמַי דִי יְמַלֵל בִּשְׁמִי מֵימְרִי יִתְבַּע מִנֵהּ:
@509 בְּרַם נְבִיָא דִי יַרְשַׁע לְמַלָלָא פִתְגָמָא בִּשְׁמִי יָת דִי לָא פַקֵדִתֵּה לְמַלָלָא וְדִי יְמַלֵיל בְּשׁוּם טַעֲוַת עַמְמַיָא וְיִתְקְטֵל נְבִיָא הַהוּא:
@510 וַאֲרֵי תֵימַר בְּלִבָּךְ אֶכְדֵן נִדַע יָת פִּתְגָמָא דִי לָא מַלְלֵהּ יְיָ:
@511 דִי יְמַלֵל נְבִיָא בִּשְׁמָא דַיְיָ וְלָא יְהֵי פִתְגָמָא וְלָא יִתְקַיַם הוּא פִתְגָמָא דִי לָא מַלְלֵהּ יְיָ בִּרְשַׁע מַלְלֵהּ נְבִיָא לָא תִדְחַלּ מִנֵהּ:
@512 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעֲהוֹן וְתֵרְתִנוּן וְתֵיתֵב בְּקִרְוֵיהוֹן וּבְבָתֵּיהוֹן:
@513 תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@514 תְּתַקֵן לָךְ אָרְחָא וּתְתַלַת יָת תְּחוּם אַרְעָךְ דִי יַחְסְנִנָךְ יְיָ אֱלָהָךְ וִיהֵי לְמֵעִירוֹק תַּמָן כָּל קָטוֹלָא:
@515 וְדֵין פִּתְגַם קָטוֹלָא דְיֵעִרוֹק תַּמָן וְיִתְקַיַם דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵהּ וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקָמוֹהִי:
@516 וְדִי יֵעוֹל עִם חַבְרֵהּ בְּחֻרְשָׁא לְמִקַץ אָעִין וְתִתְמְרֵיג יְדֵהּ בְּפַרְזְלָא לְמִקַץ אָעָא וְיִשְׁתְּלֵף פַּרְזְלָא מִן אָעָא וְיַשְׁכַּח יָת חַבְרֵהּ וִימוּת הוּא יֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין וְיִתְקַיַם:
@517 דִילְמָא יִרְדוֹף גָאֵל דְמָא בָּתַר קָטוֹלָא אֲרֵי יֵחַם לִבֵּה וְיַדְבְּקִנֵהּ אֲרֵי תִסְגֵי אָרְחָא וְיִקְטְלִנֵהּ נְפַשׁ וְלֵהּ לֵית חוֹבַת דִין דִקְטוֹל אֲרֵי לָא סָנֵי הוּא לֵהּ מִתְּמַלֵי וּמִדְקָמוֹהִי:
@518 עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימָר תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ:
@519 וְאִם יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ וְיִתֶּן לָךְ יָת כָּל אַרְעָא דִי מַלִיל לְמִתַּן לַאֲבָהָתָךְ:
@520 אֲרֵי תִטַר יָת כָּל תַּפְקֶדְתָּא הָדָא לְמֶעְבְּדַהּ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹהִי כָּל יוֹמַיָא וְתוֹסֵף לָךְ עוֹד תְּלַת קִרְוִין עַל תְּלַת אִלֵין:
@521 וְלָא יִשְׁתְּפֵךְ דָם זַכַּי בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וִיהֵי עֲלָךְ חוֹבַת דִין דִקְטוֹל:
@522 וַאֲרֵי יְהֵי גְבַר סָנֵי לְחַבְרֵהּ וְיִכְמַן לֵהּ וִיקוּם עֲלוֹהִי וְיִמְחִנֵהּ נְפָשׁ וִימוּת וְיֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין:
@523 וִישַׁלְחוּן סָבֵי קַרְתֵּהּ וְיִדְבְּרוּן יָתֵהּ מִתַּמָן וְיִתְּנוּן יָתֵהּ בְּיַד גָאֵל דְמָא וִימוּת:
@524 לָא תְחוּס עֵינָךְ עֲלוֹהִי וּתְפַלֵי אַשְׁדִי דָם זַכַּי מִיִשְׂרָאֵל וְיֵיטַב לָךְ:
@525 לָא תַשְׁנֵי תְּחוּמָא דְחַבְרָךְ דִי תְחִימוּ קַדְמָאֵי בְּאַחֲסַנְתָּךְ דִי תַחֲסֵן בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@526 לָא יְקוּם סָהִיד חַד בִּגְבַר לְכָל עַוָיָן וּלְכָל חוֹבִין בְּכָל חֵט דִי יֶחְטֵי עַל מֵימַר תְּרֵין סָהֲדִין אוֹ עַל מֵימַר תְּלָתָא סָהֲדִין יִתְקַיַם פִּתְגָמָא:
@527 אֲרֵי יְקוּם סָהִיד שְׁקַר בִּגְבָר לְאַסְהָדָא בֵהּ סַטְּיָא:
@528 וִיקוּמוּן תְרֵין גֻבְרִין דִי לְהוֹן דִינָא קֳדָם יְיָ קֳדָם כָּהֲנַיָא וְדַיָנַיָא דִי יְהוֹן בְּיוֹמַיָא הָאִנוּן:
@529 וְיִתְבְּעוּן דַיָנַיָא יָאוּת וְהָא סָהִיד שְׁקַר סָהֲדָא שִׁקְרָא אַסְהַד בַּאֲחוֹהִי:
@530 וְתַעְבְּדוּן לֵהּ כְּמָא דִי חַשִׁיב לְמֶעְבַּד לַאֲחוֹהִי וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@531 וּדְיִשְׁתַּאֲרוּן יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד עוֹד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@532 וְלָא תְחוּס עֵינָךְ נַפְשָׁא חֳלַף נַפְשָׁא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא יְדָא חֳלַף יְדָא רַגְלָא חֳלַף רַגְלָא:
@533 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְתֶחֱזֵי סוּסָוָן וּרְתִכִּין עַם סַגִי מִנָךְ לָא תִדְחַל מִנְהוֹן אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ בְּסַעְדָךְ דְאַסְקָךְ מֵאַרְעָא דְמִצְרָיִם:
@534 וִיהֵי כְּמִקְרָבְכוֹן לַאֲגָחָא קְרָבָא וְיִתְקְרִיב כַּהֲנָא וִימַלֵל עִם עַמָא:
@535 וְיֵימַר לְהוֹן שְׁמַע יִשְׂרָאֵל אַתּוּן קְרִיבִין יוֹמָא דֵין לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּעַ לִבְּכוֹן לָא תִדְחֲלוּן וְלָא תִתְבַּהֲתוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן:
@536 אֲרֵי יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן לַאֲגָחָא לְכוֹן קְרָב עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרַק יָתְכוֹן:
@537 וִימַלְלוּן סָרְכַיָא קֳדָם עַמָא לְמֵימָר מָן גַבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא חָנְכֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יַחְנְכִנֵהּ:
@538 וּמָן גַבְרָא דִי נְצִיב כַּרְמָא וְלָא אַחֲלֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יְחַלִנֵהּ:
@539 וּמָן גַבְרָא דִי אֵרַס אִתְּתָא וְלָא נָסְבַהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחֳרָן יִסְבִנַהּ:
@540 וְיוֹסְפוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וְיֵימְרוּן מָן גַבְרָא דְדָחֵל וּתְבִיר לִבָּא יְהַךְ וִיתוּב לְבֵיתֵהּ וְלָא יִתְּבַר יָת לִבָּא דַאַחוֹהִי כְּלִבֵּהּ:
@541 וִיהֵי כַּד יְשֵׁצוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וִימַנוּן רַבָּנֵי חֵילָא בְּרֵישׁ עַמָא:
@542 אֲרֵי תִקְרַב לְקַרְתָּא לַאֲגָחָא (קְרָבָא) עֲלַהּ וְתִקְרֵי לַהּ מִלִין דִשְׁלָם:
@543 וִיהֵי אִם שְׁלַם תַּעֲנִנָךְ וְתִפְתַּח לָךְ וִיהֵי כָּל עַמָא דְיִשְׁתְּכַח בַּהּ יְהוֹן לָךְ מַסְקֵי מִסִין וְיִפְלְחֻנָךְ:
@544 וְאִם לָא תַשְׁלֵם עִמָךְ וְתַעְבֵּד עִמָךְ קְרָב וּתְצוּר עֲלַהּ:
@545 וְיִמְסְרִנַהּ יְיָ אֱלָהָךְ בִּידָךְ וְתִמְחֵי יָת כָּל דְכוּרַהּ לְפִתְגַם דְחָרֶב:
@546 לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכֹל דִי יְהֵי בְקַרְתָּא כָּל עֲדָאַהּ תֵּבוֹז לָךְ וְתֵיכוּל יָת עֲדָאָה דְסַנְאָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@547 כֵּן תַּעְבֵד לְכָל קִרְוַיָא דִי רְחִיקִין מִנָךְ לַחֲדָא דִי לָא מִקִרְוֵי עַמְמַיָא הָאִלֵין אִנוּן:
@548 לְחוֹד מִקִרְוֵי עַמְמַיָא הָאִלֵין דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לָא תְקַיַם כָּל נִשְׁמָתָא:
@549 אֲרֵי גַמָרָא תְגַמְרִנוּן חִתָּאֵי וֶאֱמֹרָאֵי כְּנַעֲנָאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@550 בְּדִיל דִי לָא יַלְפוּן יָתְכוֹן לְמֶעְבַּד כְּכָל תּוֹעֲבָתְהוֹן דִי עֲבָדוּ לְטַעֲוָתְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהֲכוֹן:
@551 אֲרֵי תְצוּר לְקַרְתָּא יוֹמִין סַגִיאִין לַאֲגָחָא עֲלַהּ לְמִכְבְּשַׁהּ לָא תְחַבֵּל יָת אִילָנַהּ לַאֲרָמָא עֲלוֹהִי פַּרְזְלָא אֲרֵי מִנֵה תֵּיכוּל וְיָתֵהּ לָא תְקוּץ אֲרֵי לָא כַאֲנָשָׁא אִילַן חַקְלָא לְמֵיעַל מְקָדָמָךְ בִּצְיָרָא:
@552 לְחוֹד אִילָן דְתִדַע אֲרֵי לָא אִילַן דְמַאֲכָל הוּא יָתֵהּ תְּחַבַּל וּתְקוּץ וְתִבְנֵי כַרְקוֹמִין עַל קַרְתָּא דִי הִיא עָבְדָא עִמָךְ קְרָבָא עַד דְתִכְבְּשַׁהּ:
@553 אֲרֵי יִשְׁתְּכַח קְטִּילָא בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ רָמֵי בְּחַקְלָא לָא אִתְיְדַע מַן קָטְּלֵהּ:
@554 וְיִפְּקוּן סָבָיךְ וְדַיָנָיךְ וְיִמְשְׁחוּן לְקִרְוַיָא דִי סַחֲרָנוּת קְטִילָא:
@555 וּתְהֵי קַרְתָּא דִקְרִיבָא לִקְטִילָא וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא עֶגְלַת תּוֹרֵי דִי לָא אִתְפְּלַח בַּהּ דִי לָא נְגִידַת בְּנוּר:
@556 וְיֶחֱתוּן סָבֵי קַרְתָּא הַהִיא יָת עֲגַלְתָּא לְנַחֲלָא בַיָר דִי לָא יִתְפְּלַח בֵּהּ וְלָא יִזְדְרַע וְיִנְקְפוּן תַּמָן יָת עֲגַלְתָּא בְּנַחֲלָא:
@557 וְיִתְקָרְבוּן כָּהֲנַיָא בְּנֵי לֵוִי אֲרֵי בְהוֹן יִתִּרְעֵי יְיָ אֱלָהָךְ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִּשְׁמָא דַיְיָ וְעַל מֵימְרֵהוֹן יְהֵי כָּל דִין וְכָל מַכְתַּשׁ סְגִירוּ:
@558 וְכֹל סָבֵי קַרְתָּא הַהִיא דִקְרִיבִין לִקְטִילָא יַסְחוּן יָת יְדֵיהוֹן עַל עֲגַלְתָּא דִנְקֶפְתָּא בְנַחֲלָא:
@559 וִיתִיבוּן וְיֵימְרוּן יְדָנָא לָא אַשְׁדוֹ יָת דְמָא הָדֵין וְעֵינָנָא לָא חֲזָאָה:
@560 כָּהֲנַיָא יֵימְרוּן כַּפַּר לְעַמָךְ יִשְׂרָאֵל דִי פְרַקְתָּא יְיָ וְלָא תִתֵּן חוֹבַת דַם זַכַּי בְּגוֹ עַמָךְ יִשְׂרָאֵל וְיִתְכַּפַּר לְהוֹן עַל דְמָא:
@561 וְאַתְּ תְּפַלֵי אַשְׁדִי דַם זַכַּי מִבֵּינָךְ אֲרֵי תַעְבֵּד דְכָשַׁר קֳדָם יְיָ: ססס:
@562 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִמְסְרִנוּן יְיָ אֱלָהָךְ בִּידָךְ וְתִשְׁבֵּי שִׁבְיְהוֹן:
@563 וְתֶחֱזֵי בְּשִׁבְיָה אִתְּתָא שַׁפִּירַת חֵזוּ וְתִתִּרְעֵי בַהּ וְתִסְבַהּ לָךְ לְאִנְתּוּ:
@564 וְתָעֵלִנַהּ לְגוֹ בֵיתָךְ וּתְגַלַח יָת רֵישַׁהּ וּתְרַבִּי יָת טוּפְרָנָהָא:
@565 וְתֶעְדֵי יָת כְּסוּת שִׁבְיַהּ מִנַהּ וְתֵיתַב בְּבֵיתָךְ וְתִבְכֵּי יָת אֲבוּהָא וְיָת אִמַהּ יְרַח יוֹמִין וּבָתַר כֵּן תֵּיעוּל לְוָתַהּ וְתִבְעֲלִנַהּ וּתְהֵי לָךְ לְאִנְתּוּ:
@566 וִיהֵי אִם לָא תִתִּרְעֵי בַהּ וְתִפְטְּרִנַהּ לְנַפְשַׁהּ וְזַבָּנָא לָא תְזַבְּנִנַהּ בְּכַסְפָּא לָא תִתָּגַר בַּהּ חֳלַף דִי עִינִיתַהּ:
@567 אֲרֵי תְהֶוְיָן לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחֶמְתָּא וַחֲדָא שְׂנִיאֲתָא וִילִידָן לֵהּ בְּנִין רְחֶמְתָּא וּשְׂנִיאֲתָא וִיהֵי בְּרָא בוּכְרָא לִשְׂנִיאֲתָא:
@568 וִיהֵי בְּיוֹמָא דְיַחְסֵן לִבְנוֹהִי יָת דִי יְהֵי לֵהּ לֵית לֵהּ רְשׁוּ לְבַכָּרָא יָת בַּר רְחֶמְתָּא עַל אַפֵּי בַר שְׂנִיאֲתָא בּוּכְרָא:
@569 אֲרֵי יָת בּוּכְרָא בַר שְׂנִיאֲתָא יַפְרַשׁ לְמִתַּן לֵהּ תַּרְתֵּין חָלָקִין בְּכֹל דִי יִשְׁתְּכַח לֵהּ אֲרֵי הוּא רֵישׁ תָּקְפֵּהּ לֵהּ חָזְיָא בְכֵרוּתָא:
@570 אֲרֵי יְהֵי לִגְבַר בַּר סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבַּל לְמֵימַר אֲבוּהִי וּלְמֵימַר אִמֵהּ וּמַלְפָן יָתֵהּ וְלָא יְקַבֵּל מִנְהוֹן:
@571 וְיֶחֱדוּן בֵּהּ אֲבוּהִי וְאִמֵּהּ וְיַפְּקוּן יָתֵהּ לָקֳדָם סָבֵי קַרְתֵּהּ וְלִתְרַע בֵּית דִין אַתְרֵהּ:
@572 וְיֵימְרוּן לְסָבֵי קַרְתֵּהּ בְּנָנָא דֵין סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבֵּל לְמֵימְרָנָא זָלֵל בְּסָר וְסָבֵי חֲמַר:
@573 וְיִרְגְמֻנֵהּ כָּל אֶנָשֵׁי קַרְתֵּהּ בְּאַבְנַיָא וִימוּת וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן:
@574 וַאֲרֵי יְהֵי בִגְבַר חוֹבַת דִין דִקְטוֹל וְיִתְקְטֵל וְתִצְלוֹב יָתֵהּ עַל צְלִיבָא:
@575 לָא תְבִית נְבִלְתֵּהּ עַל צְלִיבָא אֲרֵי מִקְבַּר תִּקְבְּרִנֵהּ בְּיוֹמָא הַהוּא אֲרֵי עַל דְחָב קֳדָם יְיָ אִצְטְלַב וְלָא תְסָאֵב יָת אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@576 לָא תֶחֱזֵי יָת תּוֹרָא דְאָחוּךְ אוֹ יַת אִמְרֵהּ דְטָעָן וְתִתְכְּבֵשׁ מִנְהוֹן אָתָבָא תָתֵבִנוּן לְאָחוּךְ:
@577 וְאִם לָא קָרֵב אֲחוּךְ לְוָתָךְ וְלָא יְדַעַתְּ לֵהּ וְתַכְנְשִׁנֵהּ לְגוֹ בֵיתָךְ וִיהֵי עִמָךְ עַד דְיִתְבַּע אֲחוּךְ יָתֵהּ וְתָתֵיבִנֵהּ לֵהּ:
@578 וְכֵן תַּעְבֵּד לַחֲמָרֵהּ וְכֵן תַּעְבֵּד לִכְסוּתֵהּ וְכֵן תַּעְבֵּד לְכָל אֲבֵדַת אֲחוּךְ דִי תֵיבַד מִנֵהּ וְתַשְׁכְּחִנַהּ לֵית לָךְ רְשׁוּ לְאִתְכַּסָאָה:
@579 לָא תֶחֱזֵי יָת חֲמָרָא דְאָחוּךְ אוֹ תוֹרֵהּ רָמָן בְּאָרְחָא וְתִתְכְּבֵשׁ מִנְהוֹן אֲקָמָא תְקִים עִמֵהּ:
@580 לָא יְהֵי תִקוּן זֵין דִגְבַר עַל אִתְּתָא וְלָא יְתַקֵן גְבַר בְּתִקוּנֵי אִתְּתָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ כָּל עָבֵד אִלֵין:
@581 אֲרֵי יְעָרַע קִנָא דְצִפְּרָא קֳדָמָךְ בְּאָרְחָא בְּכָל אִילָן אוֹ עַל אַרְעָא אֶפְרוֹחִין אוֹ בֵיעִין וְאִמָא רְבֵעָא עַל אֶפְרֹחִין אוֹ עַל בֵּיעִין לָא תִסַב אִמָא עַל בְּנַיָא:
@582 שַׁלָחָא תְשַׁלַח יָת אִמָא וְיָת בְּנַיָא תִּסַב לָךְ בְּדִיל דְיֵיטַב לָךְ וְתוֹרִיפךְ יוֹמִין:
@583 אֲרֵי תִבְנֵי בֵּיתָא חַדְתָּא וְתַעְבֵּד תְּיָקָא לְאִגְרָךְ וְלָא תְשַׁוִי חוֹבַת דִין דִקְטוֹל בְּבֵיתָךְ אֲרֵי יִפֵּל דְנָפֵל מִנֵהּ:
@584 לָא תִזְרַע כַּרְמָךְ עֵרוּבִין דִילְמָא תִסְתָּאַב דִמְעַת זַרְעָא דִי תִזְרַע וַעֲלָלַת כַּרְמָא:
@585 לָא תִרְדֵי בְתוֹרָא וּבַחֲמָרָא כַּחֲדָא:
@586 לָא תִלְבַּשּׁ שַׁעַטְנֵזָא עֲמַר וְכִתָּן מְחֻבַּר כַּחֲדָא:
@587 כְּרֻסְפְּדִין תַּעְבֶּד לָךְ עַל אַרְבַּע כַּנְפֵי כְסוּתָךְ דִי תְכַסֵי בַהּ:
@588 אֲרֵי יִסַב גְבַר אִתְּתָא וְיֵעוּל לְוָתַהּ וְיִסְנִנַהּ:
@589 וִישַׁוִי לַהּ תַּסְקוֹפֵי מִלִין וְיַפֵּק עֲלַהּ שׁוּם בִּישׁ וְיֵימַר יָת אִתְּתָא הָדָא נְסֵבִית וְעַלִית לְוָתַהּ וְלָא אַשְׁכָּחִית לַהּ בְּתוּלִין:
@590 וְיִסַב אֲבוּהָא (נ''א אֲבוּהִי) דְעוּלֶמְתָּא וְאִמַהּ וְיַפְּקוּן יָת בְּתוּלֵי עוּלֶמְתָּא לָקֳדָם סָבֵי קַרְתָּא לִתְרַע בֵּית דִין אַתְרָא:
@591 וְיֵימַר אֲבוּהָא דְעוּלֶמְתָּא לְסָבַיָא יָת בְּרַתִּי יְהָבִית לְגַבְרָא הָדֵין לְאִנְתּוּ וּסְנִנַהּ:
@592 וְהָא הוּא שַׁוִי תַּסְקוֹפֵי מִלִין לְמֵימַר לָא אַשְׁכָּחִית לִבְרַתָּךְ בְּתוּלִין וְאִלֵין בְּתוּלֵי בְרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם סָבֵי קַרְתָּא:
@593 וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא יָת גַבְרָא וְיַלְקוּן יָתֵהּ:
@594 וְיִגְבּוּן מִנֵהּ מְאָה סִלְעִין דִכְסָף וְיִתְּנוּן לַאֲבוּהָא דְעוּלֶמְתָּא אֲרֵי אַפֵּק שׁוּם בִּישׁ עַל בְּתוּלְתָּא דְיִשְׂרָאֵל וְלֵהּ תְּהֵי לְאִנְתּוּ לֵית לֵהּ רְשׁוּ לְמִפְטְּרַהּ כָּל יוֹמוֹהִי:
@595 וְאִם קֻשְׁטָא הֲוָה פִּתְגָמָא הָדֵין לָא אִשְׁתְּכָחוּ בְתוּלִין לְעוּלֶמְתָּא:
@596 וְיַפְּקוּן יָת עוּלֶמְתָּא לִתְרַע בֵּית אָבוּהָא וְיִרְגְמֻנַהּ אֱנָשֵׁי קַרְתַּהּ בְּאַבְנַיָא וּתְמוּת אֲרֵי עָבְדַת קְלָנָא בְּיִשְׂרָאֵל לְזַנָאָה בֵּית אֲבוּהָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@597 אֲרֵי יִשְׁתְּכַח גְבַר דְשָׁכֵב עִם אִתְּתָא אִתַּת גְבַר וְיִתְקַטְלוּן אַף תַּרְוֵיהוֹן גַבְרָא דְשָׁכֵב עִם אִתְּתָא וְאִתְּתָא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@598 אֲרֵי תְהֵי עוּלֶמְתָּא בְתֻלְתָּא דִמְאָרְסָא לִגְבַר וְיַשְׁכְּחִנַהּ גְבַר בְּקַרְתָּא וְיִשְׁכּוּב עִמַהּ:
@599 וְתַפְּקוּן יָת תַּרְוֵיהוֹן לִתְרַע קַרְתָּא הַהִיא וְתִרְגְמוּן יָתְהוֹן בְּאַבְנַיָא וִימוּתוּן יָת עוּלֶמְתָּא עַל עֵסַק דִי לָא צְוָחַת בְּקַרְתָּא וְיָת גַבְרָא עַל עֵסַק דְעַנִי יָת אִתַּת חַבְרֵהּ וּתְפַלֵי עָבֵד דְבִּישׁ מִבֵּינָךְ:
@600 וְאִם בְּחַקְלָא יַשְׁכַּח גְבַר יָת עוּלֶמְתָּא דִמְאָרְסָא וְיִתְקֶף בַּהּ גַבְרָא וְיִשְׁכּוּב עִמַהּ וְיִתְקְטֵּל גַבְרָא דְשָׁכֵב עִמַהּ בִּלְחוֹדוֹהִי:
@601 וּלְעוּלֶמְתָּא לָא תַעְבֵּד מִדַעַם לֵית לְעוּלֶמְתָּא חוֹבַת דִין דִקְטוֹל אֲרֵי כְּמָא דִיקוּם גַבְרָא עַל חַבְרֵהּ וְיִקְטְּלִנֵהּ נְפַשׁ כֵּן פִּתְגָמָא הָדֵין:
@602 אֲרֵי בְחַקְלָא אַשְׁכְּחַהּ צְוָחַת עוּלֶמְתָּא דִמְאָרְסָא וְלֵית דְפָרִיק לַהּ:
@603 אֲרֵי יַשְׁכַּח גְבַר עוּלֶמְתָּא בְתֻלְתָּא דִי לָא מְאָרְסָא וְיֶחֱדִנַהּ וְיִשְׁכּוּב עִמַהּ וְיִשְׁתַּכְּחוּן:
@604 וְיִתֵּן גַבְרָא דְיִשְׁכֻּב עִמַהּ לַאֲבוּהָא דְעוּלֶמְתָּא חַמְשִׁין סִלְעִין דִכְסַף וְלֵהּ תְּהֵי לְאִנְתּוּ חֳלַף דִי עַנְיַהּ לֵית לֵהּ רְשׁוּ לְמִפְטְרַהּ כָּל יוֹמוֹהִי:
@605 לָא יִסַב גְבַר יָת אִתַּת אֲבוּהִי וְלָא יְגַלֵי כַּנְפָא דַאֲבוּהִי:
@606 לָא יִדְכֵּי דְפָסִיק וְדִמְחַבַּל לְמֵעַל בִּקְהָלָא דַיְיָ:
@607 לָא יִדְכֵּי מַמְזֵרָא לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לֵהּ לְמֵעַל בִּקְהָלָא דַיְיָ:
@608 לָא יִדְכּוּן עַמוֹנָאֵי וּמוֹאָבָאֵי לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָא דַיְיָ עַד עָלָם:
@609 עַל עֵסַק דִי לָא עֲרָעוּ יָתְכוֹן בְּלַחְמָא וּבְמַיָא בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם וְדִי אֲגַר עֲלָךְ יָת בִּלְעָם בַּר בְּעוֹר מִפְּתוֹר אֲרַם דִי עַל פְּרָת לְלַטָּיוּתָךְ:
@610 וְלָא אָבֵי יְיָ אֱלָהָךְ לְקַבָּלָא מִן בִּלְעָם וַהֲפַךְ יְיָ אֱלָהָךְ לָךְ יָת לְוָטִין לְבִרְכָן אֲרֵי רָחֲמָךְ יְיָ אֱלָהָךְ:
@611 לָא תִתְבַּע שְׁלָמְהוֹן וְטָבָתְהוֹן כָּל יוֹמָיךְ לְעָלָם:
@612 לָא תְרַחַק אֱדוֹמָאָה אֲרֵי אֲחוּךְ הוּא לָּא תְרַחַק מִצְרָאָה אֲרֵי דַיָר הֲוֵיתָא בְאַרְעֵהּ:
@613 בְּנִין דִי יִתְיְלִידוּ לְהוֹן דָרָא תְלִיתָאָה יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָה דַיְיָ:
@614 אֲרֵי תִפּוֹק מַשְׁרִיתָא עַל בַּעֲלֵי דְבָבָךְ וְתִסְתַּמַר מִכֹּל מִדַעַם בִּישׁ:
@615 אֲרֵי יְהֵי בָךְ גְבַר דִי לָא יְהֵּי דְכֵי מִקְרֵהּ לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@616 וִיהֵי לְמִפְנֵי רַמְשָׁא יַסְחֵי בְמַיָא וּכְמֵעַל שִׁמְשָׁא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@617 וַאֲתַר מְתַקֵן יְהֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וְתִפּוֹק תַּמָן לְבָרָא:
@618 וְסִכְּתָא תְּהֵי לָךְ עַל זֵינָךְ וִיהֵי בְּמִיתְבָךְ לְבָרָא וְתַחְפַּר בַּהּ וּתְתוּב וּתְכַסֵי יָת מִפְּקָתָךְ:
@619 אֲרֵי יְיָ אֱלָהָךְ שְׁכִינְתֵּהּ מְהַלְכָא בְּגוֹ מַשְׁרִיתָךְ לְשֵׁזָבוּתָךְ וּלְמִמְסַר בַּעֲלֵי דְבָבָךְ קֳדָמָךְ וּתְהֵי מַשְׁרִיתָךְ קַדִישָׁא וִלָא יִתְחֲזֵי בָךְ עֲבֵרַת פִּתְגָם וִיתוּב מֵימְרֵהּ מִלְאוֹטָבָא לָךְ:
@620 לָא תִמְסַר עֶבֶד עַמְמִין לְיַד רִבּוֹנֵהּ דְיִשְׁתֵּזֵב לְוָתָךְ מִלְוָת רִבּוֹנֵהּ:
@621 עִמָךְ יִתֵּב בֵּינָךְ בְּאַתְרָא דִי יִתִּרְעֵי בַּחֲדָא מִן קִרְוָיךְ בִּדְיֵיטַּב לֵהּ לָא תוֹנִנֵהּ:
@622 לָא תְהֵי אִתְּתָא מִבְּנַת יִשְׂרָאֵל לִגְבָר עָבֵד וְלָא יִסַב גַבְרָא מִבְּנֵי יִשְׂרָאֵל אִתְּתָא אָמָא:
@623 לָא תָעֵל אֲגַר זַנִיתָא וְחוּלְפַן כַּלְבָא לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לְכָל נִדְרָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ אַף תַּרְוֵיהוֹן:
@624 לָא תְרַבֵּי לַאֲחוּךְ רִבִּית כְּסַף רִבִּית עִבוּר רִבִּית כָּל מִדַעַם דְמִתְרַבֵּי:
@625 לְבַר עַמְמִין תְּרַבֵּי וְלַאֲחוּךְ לָא תְרַבֵּי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דִי אַתְּ עָלֵל:לתַמָן לְמֵירְתַהּ:
@626 אֲרֵי תִדַר נְדַר קֳדָם יְיָ אֱלָהָךְ לָא תְאַחַר לְשַׁלָמוּתֵהּ אֲרֵי מִתְבַּע יִתְבְּעִנֵהּ יְיָ אֱלָהָךְ מִנָךְ וִיהֵי בָךְ חוֹבָא:
@627 וַאֲרֵי תִתִּמְנַע לְמִנְדַר לָא יְהֵי בָךְ חוֹבָא:
@628 אַפָּקוּת סִפְוָתָךְ תִּטַר וְתַעְבֵּד כְּמָא דִי נְדַרְתָּא קֳדָם יְיָ אֱלָהָךְ נְדַבְתָּא דִי מַלֶלְתָּא בְּפוּמָךְ:
@629 אֲרֵי תִתָּגַר בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל עִנְבִין כְּנַפְשָׁךְ שִׂבְעָךְ וּלְמָאנָךְ לָא תִתֵּן:
@630 אֲרֵי תִתָּגַר בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף מְלִילָן בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ:
@631 אֲרֵי יִסַב גְבַר אִתְּתָא וְיִבְעֲלִנַהּ וִיהֵי אִם לָא תַשְׁכַּח רַחֲמִין בְּעֵינוֹהִי אֲרֵי אַשְׁכַּח בַּהּ עֲבֵרַת פִתְגָם וְיִכְתּוֹב לַהּ גֵט פִּטוּרִין וִיהַב בִּידַהּ וְיִפְטְּרִנַהּ מִבֵּיתֵהּ:
@632 וְתִפּוֹק מִבֵּיתֵהּ וּתְהַךְ וּתְהֵי לִגְבַר אָחֳרָן:
@633 וְיִסְנִנַהּ גַבְרָא בַתְרָאָה וְיִכְתּוֹב לַהּ גֵטּ פִטּוּרִין וְיִתֵּן בִּידַהּ וְיִפְטְרִנַהּ מִבֵּיתֵהּ אוֹ אֲרֵי יְמוּת גַבְרָא בַתְרָאָה דְנָסְבַהּ לֵה לְאִנְתּוּ:
@634 לֵית לֵהּ רְשׁוּ לְבַעֲלַהּ קַדְמָאָה דִי פָטְרַהּ לְמִתֻּב לְמִסְבַהּ לְמֶהֱוֵי לֵה לְאִנְתּוּ בָּתַר דִי אִסְתָּאָבַת אֲרֵי מְרָחָקָא הִיא קֳדָם יְיָ וְלָא תְחַיַב יָת אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@635 אֲרֵי יִסַב גְבַר אִתְּתָא חַדְתָּא לָא יִפּוֹק בְּחֵילָא וְלָא יֵעִבַר עֲלוֹהִי לְכָל מִדָעַם פָּנֵי יְהֵי לְבֵיתֵהּ שַׁתָּא חֲדָא וְיַחְדֵי יָת אִתְּתֵהּ דִי נְסַב:
@636 לָא יִסַב מַשְׁכּוֹנָא רֵחַיָא וְרִכְבָּא אֲרֵי בְהוֹן מִתְעֲבֵד מָזוֹן לְכָל נְפַשׁ:
@637 אֲרֵי יִשְׁתְּכַח גְבַר גָנֵב נַפְשָׁא מֵאֲחוֹהִי מִבְּנֵי יִשְׂרָאֵל וְיִתָּגַר בֵּהּ וִיזַבְּנִנֵהּ וְיִתְקְטֵל גַנָבָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@638 אִסְתַּמַר בְּמַכְתַּשׁ סְגִירוּ לְמִטַּר לַחֲדָא וּלְמֶעְבָּד כְּכֹל דִי יַלְפוּן יָתְכוֹן כָּהֲנַיָא לֵוָאֵי כְּמָא דִי פַקֶדְתִּנוּן תִּטְרוּן לְמֶעְבָּד:
@639 הֱוֵי דְכִיר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְמִרְיָם בְּאָרְחָא בְּמִפָקְכוֹן מִמִצְרָיִם:
@640 אֲרֵי תַרְשֵׁי בְחַבְרָךְ רְשׁוּ מִדָעַם לָא תֵעוּל לְבֵיתֵהּ לְמִסַב מַשְׁכּוֹנֵהּ:
@641 בְּבָרָא תְּקוּם וְגַבְרָא דִי אַתְּ רָשֵׁי בֵהּ יַפֵק לְוָתָךְ יָת מַשְׁכּוֹנָא לְבָרָא:
@642 וְאִם גְבַר מִסְכֵּן הוּא לָא תִשְׁכּוּב בְּמַשְׁכּוֹנֵהּ:
@643 אָתָבָא תָתֵב לֵהּ יָת מַשְׁכּוֹנָא כְּמֵעַל שִׁמְשָׁא וְיִשְׁכּוּב בִּכְסוּתֵהּ וִיבָרֵכִנָךְ וְלָךְ תְּהֵי זְכוּתָא קֳדָם יְיָ אֱלָהָךְ:
@644 לָא תַעֲשׁוֹק אֲגִירָא עַנְיָא וּמִסְכֵּנָא מֵאַחָיךְ אוֹ מִגִיוֹרָךְ דִי בְאַרְעָךְ בְּקִרְוָיךְ:
@645 בְּיוֹמֵהּ תִּתֵּן אַגְרֵהּ וְלָא תֵעוּל עֲלוֹהִי שִׁמְשָׁא אֲרֵי עַנְיָא הוּא וְלֵהּ הוּא מְסַר יָת נַפְשֵׁהּ וְלָא יִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@646 לָא יְמוּתוּן אֲבָהָן עַל פּוּם בְּנִין וּבְנִין לָא יְמוּתוּן עַל פּוּם אֲבָהָן אֱנַשׁ בְּחוֹבֵהּ יְמוּתוּן:
@647 לָא תַצְלֵי דִין גִיוֹרָא וְיִתַּמָא וְלָא תִסַב מַשְׁכּוֹנָא לְבוּשׁ אַרְמְלָא:
@648 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ מִתַּמָן עַל כֵּן אֲנָא מְפַקְדָךְ לְמֶעְבַּד יָת פִּתְגָמָא הָדֵין:
@649 אֲרֵי תַחְצוֹד חֲצָדָךְ בְּחַקְלָךְ וְתִנְשֵׁי עֻמְרָא בְחַקְלָא לָא תְתוּב לְמִסְבֵהּ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ:
@650 אֲרֵי תַחְבּוֹט זֵיתָךְ לָא תְפַלֵי בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@651 אֲרֵי תִקְטוֹף כַּרְמָךְ לָא תְעָלֵל בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@652 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרָיִם עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵעְבַּד יָת פִּתְגָמָא הָדֵין:
@653 אֲרֵי יְהֵי דִין בֵּין גֻבְרַיָא וְיִתְקָרְבוּן לְדִינָא וִידוּנֻנוּן וִיזַכּוּן יָת זַכָּאָה וִיחַיְבוּן יָת חַיָבָא:
@654 וִיהֵי אִם בַּר חַיָבָא לְאַלְקָאָה חַיָבָא וְיִרְמִנֵהּ דַיָנָא וְיַלְקִנֵהּ קֳדָמוֹהִי כְּמִסַת חוֹבְתֵהּ בְּמִנְיָן:
@655 אַרְבְּעִין יַלְקִנֵהּ לָא יוֹסֵף דִילְמָא יוֹסֵף לְאַלְקָיוּתֵהּ עַל אִלֵין מָחָא רַבָּא וְיֵקַל אֲחוּךְ לְעֵינָיךְ:
@656 לָא תֵחוֹד פּוּם תּוֹרָא בִּדְיָשֵׁהּ:
@657 אֲרֵי יֵתְבוּן אַחִין כַּחֲדָא וִימוּת חַד מִנְהוֹן וּבַר לֵית לֵהּ לָא תְהֵי אִתַּת מֵתָנָא לְבָרָא לִגְבַר אוֹחֲרָן יְבָמַהּ יֵעוּל עֲלַהּ וְיִסְבַהּ לֵהּ לְאִנְתּוּ וְיִבְּמַהּ:
@658 וִיהֵי בּוּכְרָא דִי תְלִיד יְקוּם עַל שְׁמָא דַאֲחוּהִי מֵתָנָא וְלָא יִתִּמְחֵי שְׁמֵהּ מִיִשְׂרָאֵל:
@659 וְאִם לָא יִצְבֵי גַבְרָא לְמִסַב יָת יְבִמְתֵּהּ וְתִסַק יְבִמְתֵהּ לִתְרַע בֵּית דִינָא לָקֳדָם סָבַיָא וְתֵימַר לָא צָבֵי יְבָמִי לַאֲקָמָא לַאֲחוּהִי שְׁמָא בְּיִשְׂרָאֵל לָא אָבֵי לְיַבָּמוּתִי:
@660 וִיקְרוּן לֵהּ סָבֵי קַרְתֵּהּ וִימַלְלוּן עִמֵהּ וִיקוּם וְיֵימַר לָא רְעֵנָא לְמִסְבַהּ:
@661 וְתִתְקְרַב יְבִמְתֵּהּ לְוָתֵה לָקֳדָם סָבַיָא וְתַשְׁרֵי סֵינֵהּ מֵעַל רַגְלֵהּ וְתֵרוֹק בְּאַנְפּוֹהִי וְתָתֵב וְתֵימַר כְּדֵין יִתְעֲבֵד לִגְבַר דִי לָא יִבְנֵי יָת בֵּיתָא דַאֲחוּהִי:
@662 וְיִתְקְרֵי שְׁמֵהּ בְּיִשְׂרָאֵל בֵּית שְׁרִי סֵינָא:
@663 אֲרֵי יִנְצוּן גֻבְרִין כַּחֲדָא גְבַר וַאֲחוּהִי וְתִתְקְרֵב אִתַּת חַד לְשֵׁזָבָא יָת בַּעֲלַהּ מִיַד מָחוּהִי וְתוֹשֵׁט יְדַהּ וְתִתְקֵף בְּבֵית בַּהֲתְּתֵהּ:
@664 וּתְקוּץ יָת יְדַהּ לָא תְחוּס עֵינָךְ:
@665 לָא יְהֵי לָךְ בְּכִיסָךְ מַתְקַל וּמַתְקָל רַבְּתָא וּזְעֶרְתָּא:
@666 לָא יְהֵי לָךְ בְּבֵיתָךְ מְכִילָא וּמְכִילָא רַבְּתָא וּזְעֶרְתָּא:
@667 מַתְקִלִין שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ מְכִילָן שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@668 אֲרֵי מְרָחָק קֳדָם יְיָ אֱלהָךְ כָּל עָבֵד אִלֵין כֹּל עָבֵד שְׁקַר:
@669 הֲוֵי דְכִיר יָת דִי עֲבַד לָךְ עֲמָלֵק בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם:
@670 דִי עָרְעָךְ בְּאָרְחָא וְקָטֵל בָּךְ כָּל דַהֲווֹ מִתְאַחֲרִין בַּתְרָךְ וְאַתְּ מְשַׁלְהֵי וְלָאֵי וְלָא דָחֵיל מִן קֳדָם יְיָ:
@671 וִיהֵי כַּד יְנִיחַ יְיָ אֱלָהָךְ לָךְ מִכָּל בַּעֲלֵי דְבָבָךְ מִסְחוֹר סְחוֹר בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ תִּמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא לָא תִּתִּנְשֵׁי: פפפ:
@672 וִיהֵי אֲרֵי תֵעוּל לְאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וְתֵירְתַהּ וְתֵיתֵב בַּהּ:
@673 וְתִסַב מֵרֵישׁ כָּל אִבָּא דְאַרְעָא דִי תָעֵל מֵאַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ וּתְשַׁוֵי בְסַלָא וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@674 וְתֵיתֵי לְוָת כַּהֲנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתֵימַר לֵהּ חַוֵיתִי יוֹמָא דֵין קֳדָם יְיָ אֱלָהָךְ אֲרֵי עַלִית לְאַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָנָא לְמִתַּן לָנָא:
@675 וְיִסַב כַּהֲנָא סַלָא מִידָךְ וְיַחְתִנֵהּ קֳדָם מַדְבְּחָא דַיְיָ אֱלָהָךְ:
@676 וְתָתֵיב וְתֵימַר קֳדָם יְיָ אֱלָהָךְ לָבָן אֲרָמָאָה בָּעָא לְאוֹבָדָא יָת אַבָּא וּנְחַת לְמִצְרַיִם וְדָר תַּמָן בְּעַם זְעֵר וַהֲוָה תַמָן לְעַם רַב תַּקִיף וְסַגִי:
@677 וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְעַנְיָנָא וִיהָבוּ עֲלָנָא פָּלְחָנָא קַשְׁיָא:
@678 וְצַלֵינָא קֳדָם יְיָ אֱלָהָא דַאֲבָהָתָנָא וְקַבִּיל יְיָ צְלוֹתָנָא וּגְלֵי קֳדָמוֹהִי עַמְלָנָא וְלֵאוּתָנָא וְדוּחֲקָנָא:
@679 וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא וּבִדְרָעָא מְרַמְמָא וּבְחֶזְוָנָא רַבָּא וּבְאָתִין וּבְמוֹפְתִין:
@680 וְאַיְתָנָא לְאַתְרָא הָדֵין וִיהַב לָנָא יָת אַרְעָא הָדָא אַרְעָא עָבְדָא חֲלַב וּדְבָש:
@681 וּכְעַן הָא אַיְתֵתִי יָת רֵישׁ אִבָּא דְאַרְעָא דִיהַבְתְּ לִי יְיָ וְתַחְתִנֵהּ קֳדָם יְיָ אֱלָהָךְ וְתִסְגוּד קֳדָם יְיָ אֱלָהָךְ:
@682 וְתֶחֱדֵי בְכָל טַבְתָא דִי יְהַב לָךְ יְיָ אֱלָהָךְ וְלֶאֱנַשׁ בֵּיתָךְ אַתְּ וְלֵוָאֵי וְגִיוֹרָא דִי בֵינָךְ:
@683 אֲרֵי תְשֵׁצֵי לְעַשָׂרָא יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא תְלִיתָאָה שְׁנַת מַעְשְׂרָא וְתִתֵּן לְלֵוָאֵי לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא וְיֵכְלוּן בְּקִרְוָיךְ וְיִשְׂבְּעוּן:
@684 וְתֵימַר קֳדָם יְיָ אֱלָהָךְ פַּלֵתִי קֹדֶשׁ מַעְשְׂרָא מִן בֵּיתָא וְאַף יְהָבִתֵּהּ לְלֵוָאֵי וּלְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא כְּכָל פִּקוּדָךְ דִי פַקִדְתַּנִי לָא עֲבָרִית מִפִּקוּדָיךְ וְלָא אִתִּנְשֵׁיתִי:
@685 לָא אֲכָלִית בְּאֶבְלִי מִנֵהּ וְלָא פַלֵתִי מִנֵהּ בִּמְסָאָב וְלָא יְהָבִית מִנֵהּ לְמִית קַבֵּלִית לְמֵימְרָא דַיְיָ אֱלָהָי עֲבָדִית כְּכֹלּ דִי פַקִדְתַּנִי:
@686 אִסְתְּכִי מִמְדוֹר קוּדְשָׁךְ מִן שְׁמַיָא וּבָרֵךְ יָת עַמָךְ יָת יִשְׂרָאֵל וְיָת אַרְעָא דִי יְהַבְתְּ לָנָא כְּמָא דִי קַיֶמְתָּא לַאֲבָהָתָנָא אֲרַע עָבְדָא חֲלַב וּדְבָשׁ:
@687 יוֹמָא הָדֵין יְיָ אֱלָהָךְ מְפַקְדָךְ לְמֶעְבַּד יָת קְיָמַיָא הָאִלֵין וְיָת דִינַיָא וְתִטַר וְתַעְבֵּד יָתְהוֹן בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@688 יָת יְיָ חֲטַּבְתָּ יוֹמָא דֵין לְמֶהֱוֵי לָךְ לֶאֱלָהּ וְלִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר קְיָמוֹהִי וּפִקוּדוֹהִי וְדִינוֹהִי וּלְקַבָּלָא לְמֵימְרֵהּ:
@689 וַיְיָ חָטְבָךְ יוֹמָא דֵין לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב כְּמָא דִי מַלִיל לָךְ וּלְמִטַר כָּל פִּקוּדוֹהִי:
@690 וּלְמִתְּנָךְ עִלָאָה עַל כָּל עַמְמַיָא דִי עֲבַד לְתֻשְׁבָּחָא וּלְשׁוּם וְלִרְבוּ וּלְמֶהֱוָךְ עַם קַדִישׁ קֳדָם יְיָ אֱלָהָךְ כְּמָא דִי מַלִיל:
@691 וּפַקִיד מֹשֶׁה וְסָבֵי יִשְׂרָאֵל יָת עַמָא לְמֵימָר טַר יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@692 וִיהֵי בְּיוֹמָא דִי תַעְבְּרוּן יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וּתְקִים לָךְ אַבְנִין רַבְרְבִין וּתְסוּד יָתְהוֹן בְּסִידָא:
@693 וְתִכְתּוֹב עֲלֵיהוֹן יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא בְּמֶעְבְּרָךְ בְּדִיל דִי תֵעוּל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבַשׁ כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ:
@694 וִיהֵי בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא תְּקִימוּן יָת אַבְנַיָא הָאִלֵין דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין בְּטּוּרָא דְעֵיבָל וּתְסוּד יָתְהוֹן בְּסִידָא:
@695 וְתִבְנֵי תַמָן מַדְבְּחָא קֳדָם יְיָ אֱלָהָךְ מַדְבַּח אַבְנִין לָא תְרִים עֲלֵיהוֹן פַּרְזְלָא:
@696 אַבְנִין שָׁלְמִין תִּבְנֵי יָת מַדְבְּחָא דַיְיָ אֱלָהָךְ וְתַסֵק עֲלוֹהִי עֲלָוָן קֳדָם יְיָ אֱלָהָךְ:
@697 וְתִכּוֹס נִכְסַת קוּדְשִׁין וְתֵיכוּל תַּמָן וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ:
@698 וְתִכְתּוֹב עַל אַבְנַיָא יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא פָּרַשׁ יָאוּת:
@699 וּמַלִיל מֹשֶׁה וְכָהֲנַיָא לֵוָאֵי לְכָל יִשְׂרָאֵל לְמֵימָר אֲצֵית וּשְׁמַע יִשְׂרָאֵל יוֹמָא הָדֵין הֲוֵיתָא לְעַמָא קֳדָם יְיָ אֱלָהָךְ:
@700 וּתְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וְתַעְבֵּד יָת פִּקוּדוֹהִי וְיָת קְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@701 וּפַקִיד מֹשֶׁה יָת עַמָא בְּיוֹמָא הַהוּא לְמֵימָר:
@702 אִלֵין יְקוּמוּן לְבָרָכָא יָת עַמָא עַל טוּרָא דִגְרִזִים בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא שִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשכָר וְיוֹסֵף וּבִנְיָמִין:
@703 וְאִלֵין יְקוּמוּן עַל לְוָטַיָא בְּטוּרָא דְעֵיבָל רְאוּבֵן גָד וְאָשֵׁר וּזְבוּלֻן דָן וְנַפְתָּלִי:
@704 וִיתִיבוּן לֵוָאֵי וְיֵימְרוּן לְכָל אֱנַשׁ יִשְׂרָאֵל קָלָא רָמָא:
@705 לִיט גַבְרָא דִי יַעְבֵּד צֶלֶם וּמַתְּכָא מְרָחָקָא קֳדָם יְיָ עֹבַד יְדֵי אֳמָן וְשַׁוִי בְסִתְרָא וִיתִיבוּן כָּל עַמָא וְיֵימְרוּן אָמֵן:
@706 לִיטּ דְיִקְלֵי אֲבוּהִי וְאִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@707 לִיטּ דְיַשְׁנֵי תְּחוּמָא דְחַבְרֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@708 לִיט דְיַטְעֵי עַוִירָא בְּאָרְחָא וְיֵימַר כָּל עַמָא אָמֵן:
@709 לִיטּ דְיַצְלֵי דִין דַיַר יִתַּמָא וְאַרְמְלָא וְיֵימַר כָּל עַמָא אָמֵן:
@710 לִיט דְיִשְׁכּוּב עִם אִתַּת אֲבוּהִי אֲרֵי גַלִי כַּנְפָא דַאֲבוּהִי וְיֵימַר כָּל עַמָא אָמֵן:
@711 לִיט דְיִשְׁכּוּב עִם כָּל בְּעִירָא וְיֵימַר כָּל עַמָא אָמֵן:
@712 לִיט דְיִשְׁכּוּב עִם אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@713 לִיט דְיִשְׁכּוּב עִם חֲמוֹתֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@714 לִיט דְיִמְחֵי לְחַבְרֵהּ בְּסִתְרָא וְיֵימַר כָּל עַמָא אָמֵן:
@715 לִיטּ דִי מְקַבֵּל שׂחֲדָא לְמִקְטַל נְפַשׁ דַם זַכַּי וְיֵימַר כָּל עַמָא אָמֵן:
@716 לִיט דִי לָא יְקַיַם יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא לְמֶעְבַּד יָתְהוֹן וְיֵימַר כָּל עַמָא אָמֵן:
@717 וִיהֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיִתְּנִנָךְ יְיָ אֱלָהָךְ עִלָאָה עַל כָּל עַמְמֵי אַרְעָא:
@718 וְיֵיתוּן עֲלָךְ כָּל בִּרְכְּתָא הָאִלֵין וְיִדְבְּקֻנָךְ אֲרֵי תְקַבַּל לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@719 בְּרִיךְ אַתְּ בְּקַרְתָּא וּבְרִיךְ אַתְּ בְּחַקְלָא:
@720 בְּרִיךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ וּוַלְדָא דִבְעִירָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@721 בְּרִיךְ סַלָךְ וְאַצְוָתָךְ:
@722 בְּרִיךְ אַתְּ בְּמֵעֲלָךְ וּבְרִיךְ אַתְּ בְּמִפְּקָךְ:
@723 יִתֵּן יְיָ יָת בַּעֲלֵי דְבָבָךְ דְקָיְמִין עֲלָךְ תְּבִירִין קֳדָמָךְ בְּאָרְחָא חַדָא יִפְּקוּן לְוָתָךְ וּבְשִׁבְעָא אָרְחָן יֵעִרְקוּן מִקֳדָמָךְ:
@724 יְפַקֵד יְיָ עִמָךְ יָת בִּרְכְּתָא בְּאוֹצָרָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ וִיבָרְכִנָךְ בְּאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@725 יְקִימִנָךְ יְיָ לֵהּ לְעַם קַדִישׁ כְּמָא דִי קַיִים לָךְ אֲרֵי תִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ וּתְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי:
@726 וְיֶחֱזוּן כָּל עַמְמֵי אַרְעָא אֲרֵי שְׁמָא דַיְיָ אִתְקְרֵי עֲלָךְ וְיִדְחֲלוּן מִנָךְ:
@727 וְיוֹתְרִנָךְ יְיָ לְטָבָא בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@728 יִפְתַּח יְיָ לָךְ יָת אוֹצָרֵהּ טָבָא יָת שְׁמַיָא לְמִתַּן מְטַר אַרְעָךְ בְּעִדָנֵהּ וּלְבָרָכָא יָת כָּל עוֹבָדֵי יְדָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף:
@729 וְיִתְּנִנָךְ יְיָ לְתַקִיף וְלָא לְחַלָשׁ וּתְהֵי בְּרַם לְעֵלָא וְלָא תְהֵי לְתַחְתָּא אֲרֵי תְקַבֵּל לְפִקוּדַיָא דַיְיָ אֱלָהָךְ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִטַר וּלְמֶעְבָּד:
@730 וְלָא תִסְטוּן מִכָּל פִּתְגָמַיָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין יַמִינָא וּשְׂמָאלָא לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא לְמִפְלְחִנוּן:
@731 וִיהֵי אִם לָא תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיֵיתוּן עֲלָךְ כָּל לְוָטַיָא הָאִלֵין וְיִדְבְּקֻנָךְ:
@732 לִיטּ אַתְּ בְּקַרְתָא וְלִיט אַתְּ בְּחַקְלָא:
@733 לִיט סַלָךְ וְאַצְוָתָךְ:
@734 לִיטּ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@735 לִיט אַתְּ בְּמֵעֲלָךְ וְלִיט אַתְּ בְּמִפְּקָךְ:
@736 יְגָרֵי יְיָ בָּךְ יָת מֵאַרְתָּא וְיָת שִׁגוּשַׁיָא וְיָת מְזוֹפִיתָא בְּכָל אוֹשָׁטוּת יְדָךְ דִי תַעְבֵּד עַד דְתִשְׁתֵּצֵי וְעַד דְתֵיבַד בִּפְרִיעַ מִן קֳדָם בִּישׁוּת עוֹבָדָיךְ דִשְׁבַקְתָּא דַחַלְתִּי:
@737 יַדְבֵּק יְיָ בָּךְ יָת מוֹתָא עַד דִישֵׁיצֵי יָתָךְ מֵעַל אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמִירְתַהּ:
@738 יִמְחִנָךְ יְיָ בְּשַׁחֶפְתָּא וּבְקַדַחְתָּא וּבִדְלֶקְתָּא וּבְחַרְחוּרָא וּבְחַרְבָּא וּבְשִׁדְפוֹנָא וּבְיַרְקוֹנָא וְיִרְדְפֻנָךְ עַד דְתֵיבָד:
@739 וִיהוֹן שְׁמַיָךְ דִי עִלָוֵי רֵישָׁךְ חֲסִינִין כִּנְחָשָׁא מִלְאֲחָתָא מִטְרָא וְאַרְעָא דִי תְחוֹתָךְ תַּקִיפָא כְפַרְזְלָא מִלְמֶעְבַּד פֵּרִין:
@740 יִתֵּן יְיָ יָת מְטַר אַרְעָךְ אַבְקָא וְעַפְרָא מִן שְׁמַיָא יֵחוּת עֲלָךְ עַד דְתִשְׁתֵּצֵי:
@741 יִתְּנִנָךְ יְיָ תְּבִיר קֳדָם סָנְאָךְ בְּאָרְחָא חֲדָא תִּפּוֹק לְוָתֵהּ וּבְשִׁבְעָא אָרְחָן תֵּעִרוֹק מִקָדָמוֹהִי וּתְהֵי לְזִיעַ לְכָל מַלְכְּוַת אַרְעָא:
@742 וּתְהֵי נְבִלְתָּךְ מְשַׁגְרָא לְמֵיכַל לְכָל עוֹפָא דִשְׁמַיָא וְלִבְעִירַת אַרְעָא וְלֵית דְמָנִיד:
@743 יִמְחִנָךְ יְיָ בְּשִׁחֲנָא דְמִצְרַיִם וּבִטְּחוֹרִין וּבְגַרְבָּא וּבַחֲרִיס יַבִּישׁ דִי לָא תִכּוּל לְאִתַּסָאָה:
@744 יִמְחִנָךְ יְיָ בְּטַפְשׁוּתָא וּבְסַמְיוּתָא וּבְשַׁעֲמָמוּת לִבָּא:
@745 וּתְהֵי מְמַשֵׁשׁ בְּטִּהֲרָא כְּמָא דִי מַשֵׁשׁ עַוִירָא בְּקַבְלָא וְלָא תַצְלַח יָת אָרְחָתָיךְ וּתְהֵי בְּרַם עָשִׁיק וְאָנִיס כָּל יוֹמַיָא וְלֵית דְפָרִיק:
@746 אִתְּתָא תֵירוֹס וּגְבַר אָחֳרָן יִשְׁכְּבִנַהּ בֵּיתָא תִבְנֵי וְלָא תֵיתֵב בֵּהּ כַּרְמָא תִצוֹב וְלָא תְחַלִנֵהּ:
@747 תּוֹרָךְ יְהֵי נָכֵס לְעֵינָיךְ וְלָא תֵיכוּל מִנֵהּ חֲמָרָךְ יְהֵי אָנֵס מִקֳדָמָךְ וְלָא יְתוּב לָךְ עָנָךְ מְסִירִין לְבַעֲלֵי דְבָבָךְ וְלֵית לָךְ פָּרִיק:
@748 בְּנָיךְ וּבְנָתָיךְ מְסִירִין לְעַמָא אָחָרָן וְעֵינָךְ חֲזָן וִיסוּפָן בִּגְלָלְהֵן כָּל יוֹמָא וְלֵית חֵילָא בִּידָךְ:
@749 אִבָּא דְאַרְעָךְ וְכָל לֵאוּתָךְ יֵכוּל עַמָא דִי לָא יְדַעַתְּ וּתְהֵי בְּרַם עָשִׁיק וּרְעִיעַ כָּל יוֹמַיָא:
@750 וּתְהֵי מִשְׁתַּטֵה מֵחֵזוּ עֵינָיךְ דִי תֶחֱזֵי:
@751 יִמְחִנָךְ יְיָ בְשִׁחֲנָא בִישָׁא עַל רְכֻבַיָא וְעַל שָׁקַיָא דִי לָא תִכּוּל לְאִתַּסָאָה מִפַּרְסַת רַגְלָךְ וְעַד מוֹחָךְ:
@752 יַגְלֵי יְיָ יָתָךְ וְיָת מַלְכָּךְ דִי תְקִים עֲלָךְ לְעַם דִי לָא יְדַעַתְּ אַתְּ וְאַבָהָתָיךְ וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא אָעָא וְאַבְנָא:
@753 וּתְהֵי לְצָדוּ לִמְתַל וּלְשׁוֹעֵי בְכֹל עַמְמַיָא דִי יִדְבְּרִנָךְ יְיָ לְתַמָן:
@754 בַּר זְרַע סַגִי תַּפֵּק לְחַקְלָא וּזְעֵר תִּכְנוֹשׁ אֲרֵי יַחְסְלִנֵהּ גוֹבָא:
@755 כַּרְמִין תִּצוּב וְתִפְלַח וְחַמְרָא לָא תִשְׁתֵּי וְלָא תִכְנוֹשׁ אֲרֵי תֵיכְלִנֵהּ תֹּלַעְתָּא:
@756 זֵיתִין יְהוֹן לָךְ בְּכָל תְּחוּמָךְ וּמִשְׁחָא לָא תְסוּךְ אֲרֵי יִתְּרוּן זֵיתָיךְ:
@757 בְּנִין וּבְנָן תּוֹלִיד וְלָא יְהוֹן לָךְ אֲרֵי יְהָכוּן בְּשִׁבְיָא:
@758 כָּל אִילָנָךְ וְאִבָּא דְאַרְעָךְ יַחְסְנִנֵהּ סַקָאָה:
@759 תּוֹתַב עָרֵל דִי בֵינָךְ יְהֵי סְלִיק עֵיל מִנָךְ לְעֵלָא לְעֵלָא וְאַתְּ תְּהֵי נָחֵת לְתַחְתָּא לְתַחְתָּא:
@760 הוּא יוֹזְפִנָךְ וְאַתְּ לָא תוֹזְפִנֵהּ הוּא יְהֵי לְתַקִיף וְאַתְּ תְּהֵי לְחַלָשׁ:
@761 וְיֵיתוּן עֲלָךְ כָּל לְוָטַּיָא הָאִלֵין וְיִרְדְפֻנָךְ וְיִדְבְּקֻנָךְ עַד דְתִשְׁתֵּצֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִי פַקְדָךְ:
@762 וִיהוֹן בָּךְ לְאָת וּלְמוֹפֵת וּבִבְנָיךְ עַד עֳלָם:
@763 חֳלָף דִי לָא פְלַחְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֶדְוָא וּבְשַׁפִּירוּת לִבָּא מִסְגֵי כֹּלָא:
@764 וְתִפְלַח יָת בַּעֲלֵי דְבָבָךְ דִי יְגָרִנֵהּ יְיָ בָּךְ בְּכַפְנָא וּבְצַחוּתָא וּבְעַרְטִּלְיָתָא וּבַחֲסִירוּת כֹּלָא וְיִתֵּן נִיר פַּרְזְלָא עַל צַוְארָךְ עַד דִישֵׁיצֵי יָתָךְ:
@765 יַיְתִי יְיָ עֲלָךְ עַם מֵרָחִיק מִסְיָפֵי אַרְעָא כְּמָא דִי מִשְׁתְּדִי נִשְׁרָא עַמָא דִי לָא תִשְׁמַע לִישָׁנֵהּ:
@766 עַם תַּקִיף אַפִּין דִי לָא יִסַב אַפִּין לְסָבָא וְעַל יָנְקָא לָא מְרַחֵם:
@767 וְיֵיכוּל וַלְדָא דִבְעִירָךְ וְאִבָּא דְאַרְעָךְ עַד דְתִשְׁתֵּצֵי דִי לָא יַשְׁאַר לָךְ עִבוּרָא חַמְרָא וּמִשְׁחָא בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַד דְיוֹבֵד יָתָךְ:
@768 וְיָעֵק לָךְ בְּכָל קִרְוָיךְ עַד דְיִכְבַּשׁ שׁוּרָיךְ רָמַיָא וּכְרִיכַיָא דִי אַתְּ רָחֵץ לְאִשְׁתֵּזָבָא בְּהֵן בְּכָל אַרְעָךְ וְיָעֵק לָךְ בְּכָל קִרְוָיךְ בְּכָל אַרְעָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@769 וְתֵיכוּל וַלְדָא דִמְעָךְ בְּשַׂר בְּנָיךְ וּבְנָתָיךְ דִי יְהַב לָךְ יְיָ אֱלָהָךְ בִּצְיָרָא וּבְעַקְתָא דְיָעֵק לָךְ סַנְאָךְ:
@770 גַבְרָא דְרַכִּיךְ בָּךְ וְדִמְפַנַק לַחֲדָא תַּבְאֵשׁ עֵינֵהּ בְּאָחוּהִי וּבְאִתַּת קְיָמֵהּ וּבִשְׁאָר בְּנוֹהִי דִי יַשְׁאַר:
@771 מִלְמִתַּן לְחַד מִנְהוֹן מִבְּשַׂר בְּנוֹהִי דִי יֵיכוּל מִדְלָא אִשְׁתָּאַר לֵהּ כֹּלָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְכָל קִרְוָיךְ:
@772 דְרַכִּיכָא בָךְ וְדִמְפַנְקָא דִי לָא נַסִיאַת פַּרְסַת רַגְלַהּ לַאֲחָתָא עַל אַרְעָא מִמְפַנְקוּ וּמֵרַכִּיכוּ תַּבְאֵשׁ עֵינַהּ בִּגְבַר קְיָמַהּ וּבִבְרַהּ וּבִבְרַתַּהּ:
@773 וּבִזְעֵר בְּנָהָא דְיִפְּקוּן מִנַהּ וּבִבְנָהָא דִי תְלִיד אֲרֵי תֵיכְלִנוּן בַּחֲסֵירוּת כֹּלָא בְּסִתְרָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְּקִרְוָיךְ:
@774 אִם לָא תִטַר לְּמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא דִכְתִיבִין בְּסִפְרָא הָדֵין לְמִדְחַל יָת שְׁמָא יַקִירָא וּדְחִילָא הָדֵין יָת יְיָ אֱלָהָךְ:
@775 וְיַפְרַשׁ יְיָ יָת מְחָתָךְ וְיָת מָחַת בְּנָיךְ מָחָן רַבְרְבָן וּמְהֵימְנָן וּמַכְתְּשִׁין בִּישִׁין וּמְהֵימְנִין:
@776 וְיָתֵב בָּךְ יָת כָּל מַכְתְּשֵׁי מִצְרַיִם דִי דְחֶלְתָּא מִקֳדָמֵיהוֹן וְיִדְבְּקוּן בָּךְ:
@777 אַף כָּל מְרַע וְכָל מָחָא דִי לָא כְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדָא יַיְתִנוּן יְיָ עֲלָךְ עַד דְיִשְׁתֵּצָךְ:
@778 וְתִשְׁתַּאֲרוּן בְּעַם זְעֵר חֳלָף דִי הֲוֵיתוּן כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@779 וִיהֵי כְּמָא דְחַדֵי יְיָ עֲלֵיכוֹן לְאוֹטָבָא יָתְכוֹן וּלְאַסְגָאָה יָתְכוֹן כֵּן יֶחֱדֵי יְיָ עֲלֵיכוֹן לְאוֹבָדָא יָתְכוֹן וּלְשֵׁצָאָה יָתְכוֹן וְתִטַלְטְלוּן מֵעַל אַרְעָא דְאַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@780 וִיבַדְרִנָךְ יְיָ בְּכָל עַמְמַיָא מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ אָעָא וְאַבְנָא:
@781 וּבְעַמְמַיָא הָאִנוּן לָא תְנוּחַ וְלָא יְהֵי מְנָח לְפַרְסַת רַגְלָךְ וְיִתֵּן יְיָ לָךְ תַּמָן לֵב דָחֵל וְחַשְׁכַת עַיְנִין וּמַפְּחַן נְפָשׁ:
@782 וִיהוֹן חַיָיךְ תְּלָן לָךְ מִקָבֵל וּתְהֵי תָוֵה לֵילְיָא וִימָמָא וְלָא תְהֵימִין בְּחַיָיךְ:
@783 בְּצַפְרָא תֵימַר מָן יִתֵּן רַמְשָׁא וּבְרַמְשָׁא תֵימַר מָן יִתֵּן צַפְרָא מִתַּוְהוּת לִבָּךְ דִי תְהֵי תָוֵה וּמֵחֵזוּ עֵינָיךְ דִי תְהֵי חָזֵי:
@784 וְיָתֵיבִנָךְ יְיָ מִצְרַיִם בִּסְפִינָן בְּאָרְחָא דִי אֲמָרִית לָךְ לָא תוֹסֵף עוֹד לְמֶחְזְיַהּ וְתִזְדַבְּנוּן תַּמָן לְבַעֲלֵי דְבָבָךְ לְעַבְדִין וּלְאַמְהָן וְלֵית דְקָנֵהּ:
@785 אִלֵין פִּתְגָמֵי קְיָמָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְמִגְזַר עִם בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דְמוֹאָב בַּר מִקְיָמָא דִי גְזַר עִמְהוֹן בְּחֹרֵב:
@786 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן אַתּוּן חֲזֵיתוּן יָת כָּל דִי עֲבַד יְיָ לְעֵינֵיכוֹן בְּאַרְעָא דְמִצְרַיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@787 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ אָתַיָא וּמוֹפְתַיָא רַבְרְבַיָא הָאִנוּן:
@788 וְלָא יְהַב יְיָ לְכוֹן לִבָּא לְמִדַע וְעַיְנִין לְמֶחֱזֵי וְאֻדְנִין לְמִשְׁמַע עַד יוֹמָא הָדֵין:
@789 וְדַבָּרִית יָתְכוֹן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא לָא בְלִיאַת כְּסוּתְכוֹן מִנְכוֹן וּמְסָנָךְ לָא:עַדוֹ מֵעַל רַגְלָךְ:
@790 לַחְמָא לָא אֲכַלְתּוּן וַחֲמַר חֲדַת וְעַתִּיק לָא שְׁתֵיתוּן בְּדִיל דְתִדְעוּן אֲרֵי אֲנָא יְיָ אֶלָהֲכוֹן:
@791 וַאֲתֵתוּן לְאַתְרָא הָדֵין וּנְפַק סִיחוֹן מַ לְכָּא דְחֶשְׁבּוֹן וְעוֹג מַ לְכָּא דְמַתְנָן לָקֳדָמוּתָנָא לַאֲגָחָא קְרָבָא וּמְחוֹנוּן:
@792 וּנְסִבְנָא יָת אַרְעֲהוֹן וִיהָבִנַהּ לְאַחֲסָנָא לְשִׁבְטָּא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה:
@793 וְתִטְרוּן יָת פִּתְגָמֵי קְיָמָא הָדָא וְתַעְבְּדוּן יָתְהוֹן בְּדִיל דְתִצְלְחוּן יָת כָּל דִי תַּעְבְּדוּן: פפפ:
@794 אַתּוּן קָיְמִין יוֹמָא דֵין כֻּלְכוֹן קֳדָם יְיָ אֱלָהֲכוֹן רֵישֵׁיכוֹן שִׁבְטֵיכוֹן סָבֵיכוֹן וְסָרְכֵיכוֹן כָּל אֱנַשׁ יִשְׂרָאֵל:
@795 טַפְלְכוֹן נְשֵׁיכוֹן וְגִיוֹרָךְ דִי בְּגוֹ מַשְׁרִיתָךְ מִלָקֵטּ אָעָיךְ עַד מְלֵי מַיָיךְ:
@796 לְאָעָלוּתָךְ בִּקְיָמָא דַיְיָ אֱלָהָךְ וּבְמוֹמָתֵהּ דִי יְיָ אֱלָהָךְ גְזַר עִמָךְ יוֹמָא דֵין:
@797 בְּדִיל לַאֲקָמָא יָתָךְ יוֹמָא דֵין קֳדָמוֹהִי לְעַמָא וְהוּא יְהֵי לָךְ לֶאֶלָהּ כְּמָא דִי מַלִיל לָךְ וּכְמָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@798 וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יָת קְיָמָא הָדָא וְיָת מוֹמָתָא הָדָא:
@799 אֲרֵי יָת מָן דְאִיתוֹהִי הָכָא עִמָנָא קָאֵם יוֹמָא דֵין קֳדָם יְיָ אֱלָהָנָא וְיָת מָן דְלֵיתוֹהִי הָכָא עִמָנָא יוֹמָא דֵין:
@800 אֲרֵי אַתּוּן יְדַעְתּוּן יָת דִיתֵבְנָא בְּאַרְעָא דְמִצְרָיִם וְיָת דִי עֲבַרְנָא בְּגוֹ עַמְמַיָא דִי עֲבַרְתּוּן:
@801 וַחֲזֵיתוּן יָת שִׁקוּצֵיהוֹן וְיָת טַעֲוָתְהוֹן אָעָא וְאַבְנָא כַּסְפָּא וְדַהֲבָא דִי עִמְהוֹן:
@802 דִילְמָא אִית בְּכוֹן גְבַר אוֹ אִתְּתָא אוֹ זַרְעִית אוֹ שִׁבְטָא דִי לִבֵּהּ פָּנֵי יוֹמָא דֵין מִדַחַלְתָּא דַייָ אֱלָהָנָא לִמְהַךְ לְמִפְלַח יָת טַעֲוַת עַמְמַיָא הָאִנוּן דִילְמָא אִית בְּכוֹן גְבַר מְהַרְהַר חֶטְאִין אוֹ זָדוֹן:
@803 וִיהֵי בְּמִשְׁמְעֵהּ יָת פִּתְגָמֵי מוֹמָתָא הָדָא וִיחַשַׁב בְּלִבֵּהּ לְמֵימַר שְׁלָמָא יְהֵי לִי אֲרֵי בְּהַרְהוֹר לִבִּי אֲנָא אָזֵל בְּדִיל לְאוֹסָפָא לֵהּ חֶטְאֵי שָׁלוּתָא עַל זְדָנוּתָא:
@804 לָא יֵיבֵי יְיָ לְמִשְׁבַּק לֵהּ אֲרֵי בְּכֵן יִתְקֵף רָגְזָא דַיְיָ וְחֶמְתֵהּ בְּגַבְרָא הַהוּא וְיִדְבְּקוּן בֵּהּ כָּל לְוָטַּיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יָת שְׁמֵהּ מִתְּחוֹת שְׁמַיָא:
@805 וְיַפְרְשִׁנֵהּ יְיָ לְבִישָׁא מִכֹּל שִׁבְטַיָא דְיִשְׂרָאֵל כְּכֹל לְוָטֵי קְיָמָא דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין:
@806 וְיֵימַר דָרָא בַתְרָאָה בְּנֵיכוֹן דִי יְקוּמוּן מִבַּתְרֵיכוֹן וּבַר עַמְמִין דִי יֵיתֵי מֵאַרְעָא רְחִיקָא וְיֶחֱזוּן יָת מְחָתָא דְאַרְעָא הַהִיא וְיָת מַרְעָהָא דִי אַמְרַע יְיָ בַּהּ:
@807 גָפְרֵתָא וּמִלְחָא יְקִידַת כָּל אַרְעַהּ לָא תִזְרַע וְלָא תַצְמַח וְלָא יִסַק בַּהּ כָּל עֶסְבָּא כְּמַהְפֶּכְתָּא דִסְדֹם וַעֲמֹרָה אַדְמָה וּצְבוֹיִם דִי הֲפַךְ יְיָ בְּרָגְזֵהּ וּבְחֶמְתֵהּ:
@808 וְיֵימְרוּן כָּל עַמְמַיָא עַל מֶה עֲבַד יְיָ כְּדֵין לְאַרְעָא הָדָא מָא תְקוֹף רָגְזָא רַבָּא הָדֵין:
@809 וְיֵימְרוּן עַל דִשְׁבָקוּ יָת קְיָמָא דַיְיָ אֱלָהָא דַאֲבָהָתְהוֹן דִי גְזַר עִמְהוֹן בְּאַפָּקוּתֵהּ יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם:
@810 וַאֲזָלוּ וּפְלָחוּ לְטַעֲוַת עַמְמַיָא וּסְגִידוּ לְהוֹן דַחֲלָן דִי לָא יְדָעֻנוּן וְלָא אוֹטִיבָא לְהוֹן:
@811 וּתְקֵף רָגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתָאָה עֲלַהּ יָת כָּל לְוָטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין:
@812 וְטַּלְטְּלִנוּן יְיָ מֵעַל אַרְעֲהוֹן בִּרְגַז וּבְחֵמְתָא וּבִתְקוֹף רְגַז וְאַגְלִנוּן לְאַרְעָא אָחֳרִי כְּיוֹמָא הָדֵין:
@813 דְמִטַמְרָן קֳדָם יְיָ אֱלָהָנָא וּדְמִגַלְיָן לָנָא וְלִבְנָנָא עַד עֳלָם לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@814 וִיהֵי אֲרֵי יֵיתוּן עֲלָךְ כָּל פִּתְגָמַיָא הָאִלֵין בִּרְכָן וּלְוָטִין דִי יְהָבִית קֳדָמָךְ וּתְתוּב לְלִבָּךְ בְּכָל עַמְמַיָא דִי אַגְלָךְ יְיָ אֱלָהָךְ לְתַמָן:
@815 וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ כְּכֹל דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין אַתְּ וּבְנָיךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@816 וִיתוּב יְיָ אֱלָהָךְ יָת שְׁבִי גַלְוָתָךְ וִירַחַם עֲלָךְ וִיתוּב וְיִכְנְשִׁנָךְ מִכָּל עַמְמַיָא דִי בַדְרָךְ יְיָ אֱלָהָךְ לְתַמָן:
@817 אִם יְהֵי גַלְוָתָךְ בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנְשִׁנָךְ יְיָ אֱלָהָךְ וּמִתַּמָן יְקָרְבִנָךְ:
@818 וְיָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִירִיתוּ אֲבָהָתָךְ וְתֵרְתַהּ וְיוֹטֶב לָךְ וְיַסְגִנָךְ מֵאֲבְהָתָךְ:
@819 וְיֶעְדֵי יְיָ אֱלָהָךְ יָת טַפְשׁוּת לִבָּךְ וְיָת טַּפְשׁוּת לִבָּא דִבְנָיךְ לְמִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ בְּדִיל חַיָיךְ:
@820 וְיִתֵּן יְיָ אֱלָהָךְ יָת כָּל לְוָטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבָךְ וְעַל סָנְאָךְ דִי רְדָפוּךְ:
@821 וְאַתְּ תְּתוּב וּתְקַבַּל לְמֵימְרָא דַיְיָ וְתַעְבֵּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@822 וְיוֹתְרִינָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ לְטָּבָא אֲרֵי יְתוּב יְיָ לְמֶחֱדֵי עֲלָךְ לְטָב כְּמָא דִי חֲדִי עַל אֲבָהָתָךְ:
@823 אֲרֵי תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין אֲרֵי תְתוּב קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@824 אֲרֵי תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לָא מַפְרְשָׁא הִיא מִנָךְ וְלָא רְחִיקָא הִיא:
@825 לָא בִשְׁמַיָא הִיא לְמֵימָר מָן יִסַק לָנָא לִשְׁמַיָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@826 וְלָא מֵעִבְרָא לְיַמָא הִיא לְמֵימַר מָן יֵעִבַר לָנָא לְעִבְרָא דְיַמָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@827 אֲרֵי קָרִיב לָךְ פִּתְגָמָא לַחֲדָא בְּפוּמָךְ וּבְלִבָּךְ לְמֶעְבְּדֵהּ:
@828 חֲזֵי דִיהָבִית קֳדָמָךְ יוֹמָא דֵין יָת חַיֵי וְיָת טַבְתָא וְיָת מוֹתָא וְיָת בִּישָׁא:
@829 דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי וְדִינוֹהִי וְתֵיחֵי וְתִסְגֵי וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@830 וְאִם יִפְנֵי לִבָּךְ וְלָא תְקַבֵּל וְתִטְּעֵי וְתִסְגוּד לְטַּעֲוַת עַמְמַיָא וְתִפְלְחִנוּן:
@831 חַוֵיתִי לְכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן לָא תוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתְּ עָבֵר יָת יַרְדְנָא לְמֵעַל לְתַמָן לְמֵירְתַהּ:
@832 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא חַיֵי וּמוֹתָא יְהָבִית קֳדָמָךְ בִּרְכָן וּלְוָטִין וְתִתִּרְעֵי בְּחַיֵי בְּדִיל דְתֵיחֵי אַתְּ וּבְנָיךְ:
@833 לְמִרְחַם יָת יְיָ אֱלָהָךְ לְקַבָּלָא לְמֵימְרֵהּ וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ אֲרֵי הוּא חַיָיךְ וְאוֹרָכוּת יוֹמָיךְ לְמִתַּב עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן: פפפ:
@834 וַאֲזַל מֹשֶׁה וּמַלִיל יָת פִּתְגָמַיָא הָאִלֵין עִם כָּל יִשְׂרָאֵל:
@835 וַאֲמַר לְהוֹן בַּר מְאָה וְעֶשְׂרִין שְׁנִין אֲנָא יוֹמָא דֵין לֵית אֲנָא יָכִיל עוֹד לְמִפַּק וּלְמֵעָל וַיְיָ אֲמַר לִי לָא תֵעִבַר יָת יַרְדְנָא הָדֵין:
@836 יְיָ אֱלָהָךְ מֵימְרֵהּ עֲבַר קֳדָמָךְ הוּא יְשֵׁצֵי יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ וְתֵירְתִנוּן יְהוֹשֻׁעַ הוּא עֲבַר קֳדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@837 וְיַעְבֵּד יְיָ לְהוֹן כְּמָא דִי עֲבַד לְסִיחוֹן וּלְעוֹג מַלְכֵי אֱמוֹרָאָה וּלְאַרְעֲהוֹן דִי שֵׁצִי יָתְהוֹן:
@838 וְיִמְסְרִנוּן יְיָ קֳדָמֵיכוֹן וְתַעְבְּדוּן לְהוֹן כְּכָל תַּפְקֶדְתָּא דִי פַקֵדִית יָתְכוֹן:
@839 תְּקִיפוּ וְאַלִימוּ לָא תִדְחֲלוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ הוּא דִמְדַבַּר קֳדָמָךְ לָא יִשְׁבְּקִנָךְ וְלָא יַרְטֵשִׁנָךְ:
@840 וּקְרָא מֹשֶׁה לִיהוֹשֻׁעַ וַאֲמַר לֵהּ לְעֵינֵי כָל יִשְׂרָאֵל תְּקַף וְאַלִים אֲרֵי אַתְּ תֵּעוּל עִם עַמָא הָדֵין לְאַרְעָא דִי קַיִים יְיָ לַאֲבְהָתְהוֹן לְמִתַּן לְהוֹן וְאַתְּ תַּחְסְנִנַהּ יָתְהוֹן:
@841 וַיְיָ הוּא דִמְדַבַּר קֳדָמָךְ מֵימְרֵהּ יְהֵי בְסַעְדָךְ לָא יִשְׁבְּקִנָךְ וְלָא יַרְחֵקִנָךְ לָא תִדְחַל וְלָא תִתְּבַר:
@842 וּכְתַב מֹשֶׁה יָת אוֹרַיְתָא הָדָא וִיהָבַהּ לְכָהֲנַיָא בְּנֵי לְוֵי דְנָטְלִין יָת אֲרוֹן קְיָמָא דַיְיָ וּלְכָל סָבֵי יִשְׂרָאֵל:
@843 וּפַקִיד מֹשֶׁה יָתְהוֹן לְמֵימָר מִסוֹף שְׁבַע שְׁנִין בִּזְמַן שַׁתָּא דִשְׁמִטְתָא בְּחַגָא דְמְטַלַיָא:
@844 בְּמֵיתֵי כָל יִשְׂרָאֵל לְאִתְחֲזָאָה קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי תִּקְרֵי יָת אוֹרַיְתָא הָדָא קֳדָם כָּל יִשְׂרָאֵל וְתַשְׁמְעִנוּן:
@845 כְּנוֹשׁ יָת עַמָא גֻבְרַיָא וּנְשַׁיָא וְטַּפְלָא וְגִיוֹרָךְ דִי בְקִרְוָיךְ בְּדִיל דְיִשְׁמְעוּן וּבְדִיל דְיַלְפוּן (נ''א דְיֵלְפוּן) וְיִדְחֲלוּן מֵקֳדָם יְיָ אֱלָהֲכוֹן וְיִטְרוּן לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@846 וּבְנֵיהוֹן דִי לָא יָדְעוּן יִשְׁמְעוּן וְיַלְפוּן (נ''א וְיֵלְפוּן) לְמִדְחַל יָת יְיָ אֱלָהֲכוֹן כֹּל יוֹמַיָא דִי אַתּוּן קְיָמִין עַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא תַּמָן לְמֵירְתַהּ:
@847 וַאֲמַר יְיָ לְמֹשֶׁה הָא קְרִיבוּ יוֹמָיךְ לִמְמַת קְרָא יָת יְהוֹשֻׁעַ וְאִתְעֲתָּדוּ בְּמַשְׁכַּן זִמְנָא וֶאֱפַקְדִנֵהּ וַאֲזַל מֹשֶׁה וִיהוֹשֻׁעַ וְאִתְעַתָּדוּ בְּמַשְׁכַּן זִמְנָא:
@848 וְאִתְגְלִי יְיָ בְּמַשְׁכְּנָא בְּעַמוּדָא דַעֲנָנָא וְקָם עַמוּדָא דַעֲנָנָא עַל תְּרַע מַשְׁכְּנָא:
@849 וַאֲמַר יְיָ לְמֹשֶׁה הָא אַתְּ שָׁכֵב עִם אֲבָהָתָךְ וִיקוּם עַמָא הָדֵין וְיִטְּעֵי בָּתַר טַעֲוַת עַמְמֵי אַרְעָא דִי הוּא עַל תַּמָן בֵּינֵיהוֹן וְיִשְׁבְּקוּן דַחַלְתִּי וְיַשְׁנוּן יָת קְיָמִי דִי גְזָרִית עִמְהוֹן:
@850 וְיִתְקוֹף רָגְזִי בְהוֹן בְּיוֹמָא הַהוּא וְאַרְחֵקִנוּן וֶאֱסַלֵק שְׁכִנְתִּי מִנְהוֹן וִיהוֹן לְמִבַּז וִיעָרְעַן יָתְהוֹן בִּישָׁן סַגִיאָן וְעָקָן וְיֵימַר בְּיוֹמָא הַהוּא הֲלָא מִדְלֵית שְׁכִינַת אֱלָהַי בֵּינִי עָרְעוּנִי בִּישַׁיָא הָאִלֵין:
@851 וַאֲנָא סַלָקָא אֶסַלֵק שְׁכִנְתִּי מִנְהוֹן בְּיוֹמָא הַהוּא עַל כָּל בִּישָׁא דִי עֲבָדוּ אֲרֵי אִתְפְּנִיוּ לְטַעֲוַת עַמְמַיָא:
@852 וּכְעַן כְּתִיבוּ לְכוֹן יָת תֻּשְׁבַּחְתָּא הָדָא וְאַלְפַהּ יָת בְּנֵי יִשְׂרָאֵל שַׁוְיַהּ בְּפוּמְהוֹן בְּדִיל דִתְהֵי קֳדָמַי תֻּשְׁבַּחְתָּא הָדָא לְסָהִיד בִּבְנֵי יִשְׂרָאֵל:
@853 אֲרֵי אָעֵלִנוּן לְאַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן עָבְדָא חֲלַב וּדְבַשׁ וְיֵיכְלוּן וְיִשְׂבְּעוּן וְיִתְפַּנְקוּן וְיִתְפְּנוּן בָּתַר טַּעֲוַת עַמְמַיָא וְיִפְלְחֻנוּן וְיִרְגְזוּן קֳדָמַי וְיַשְׁנוּן יָת קְיָמִי:
@854 וִיהֵי אֲרֵי יְעָרְעָן יָתֵהּ בִּישָׁן סַגִיאָן וְעָקָן וְתָתֵב תֻּשְׁבַּחְתָּא הָדָא קֳדָמוֹהִי לְסָהִיד אֲרֵי לָא תִתְנְשֵׁי מִפּוּם בֵּנֵיהוֹן ארֵי גִלֵי קֳדָמַי יָת יִצְרְהוֹן דִי אִנוּן עָבְדִין יוֹמָא דֵין עַד לָא אָעֵלִנוּן לְאַרְעָא דִי קַיֵמִית:
@855 וּכְתַב מֹשֶׁה יָת תּוּשְׁבַּחְתָּא הָדָא בְּיוֹמָא הַהוּא וְאַלֵפִנַהּ לִבְנֵי יִשְׂרָאֵל:
@856 וּפַקִיד יָת יְהוֹשֻׁעַ בַּר נוּן וַאֲמַר תְּקֵף וְאַלִים אֲרֵי אַתְּ תָּעֵל יָת בְּנֵי יִשְׂרָאֵל לְאַרְעָא דִי קַיֵמִית לְהוֹן וּמֵימְרִי יְהֵי בְסַעְדָךְ:
@857 וַהֲוָה כַּד שֵׁצֵי מֹשֶׁה לְמִכְתַּב יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא עַל סִפְרָא עַד דִשְׁלִימוּ:
@858 וּפַקִיד מֹשֶׁה יָת לֵוָאֵי נָטְלֵי אֲרוֹן קְיָמָא דַיְיָ לְמֵימָר:
@859 סִיבוּ יָת סִפְרָא דְאוֹרַיְתָא הָדֵין וּתְשַׁוּוּן יָתֵהּ מִסְטַר אֲרוֹן קְיָמָא דַיְיָ אֱלָהֲכוֹן וִיהֵי תַמָן בָּךְ לְסָהִיד:
@860 אֲרֵי אֲנָא יְדַעְנָא יָת סַרְבָנוּתָךְ וְיָת קְדָלָךְ דְקַשְׁיָא הָא בְעַד אֲנָא קַיָם עִמְכוֹן יוֹמָא דֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ וְאַף אֲרֵי בָּתַר דְאֵמוּת:
@861 כְּנִישׁוּ לְוָתִי יָת כָּל סָבֵי שִׁבְטֵיכוֹן וְסָ רְכֵיכוֹן וֶאֱמַ לֵל קֳדָמֵיהוֹן יָת פִּתְגָמַיָא הָאִלֵין וְאַסְהֵד בְּהוֹן יָת שְׁמַיָא וְיָת אַרְעָא:
@862 אֲרֵי יְדַעְנָא בָּתַר דְאֵמוּת אֲרֵי חֲבָּלָא תְחַבְּלוּן וְתִסְטוּן מִן אָרְחָא דִי פַקֵדִית יָתְכוֹן וּתְעָרַע יָתְכוֹן בִּשְׁתָּא בְּסוֹף יוֹמַיָא אֲרֵי תַעְבְּדוּן יָת דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי בְּעוֹבָדֵי יְדֵיכוֹן:
@863 וּמַלִיל מֹשֶׁה קֳדָם כָּל קְהָלָא דְיִשְׂרָאֵל יָת פִּתְגָמֵי תּוּשְׁבַּחְתָּא הָדָא עַד דִשְׁלִימוּ: פפפ:
@864 אַצִיתוּ שְׁמַיָא וֶאֱמַלֵל וְתִשְׁמַע אַרְעָא מֵימְרֵי פֻמִי:
@865 יְבַסַם כְּמִטְרָא אוּלְפָּנִי יִתְקַבַּל כְּטַלָא מֵימְרִי כְּרוּחֵי מִטְרָא דְנָשְׁבִין עַל דִתְאָה וְכִרְסִיסֵי מַלְקוֹשָׁא דִי עַל עִשְׂבָּא:
@866 אֲרֵי בִּשְׁמָא דַיְיָ אֲנָא מְצַלֵי הָבוּ רְבוּתָא קֳדָם אֱלָהָנָא:
@867 תַּקִיפָא דְשָׁלְמִין עוֹבָדוֹהִי אֲרֵי כָּל אֹרְחָתֵהּ דִינָא אֱלָהָא מְהֵימְנָא דְמִן קֳדָמוֹהִי עַוְלָה לָא נָפֵק מִן קֳדָם דְזַכַּי וְקַשִׁיט הוּא:
@868 חַבִּילוּ לְהוֹן לָא לֵהּ בְּנַיָא דִי פְלָחוּ לְטַעֲוָתָא דָרָא דְאַשְׁנִיוּ עוֹבָדוֹהִי וְאִשְׁתַּנִיוּ:
@869 הָא קֳדָם יְיָ אַתּוּן גָמְלִין דָא עַמָא דְקַבִּילוּ אוֹרַיְתָא וְלָא חַכִּימוּ הֲלָא הוּא אֲבוּךְ וְאַתְּ דִי לֵהּ הוּא עָבְדָךְ וְאַתְקְנָךְ:
@870 אִדְכַּר יוֹמִין דְמִן עָלְמָא אִסְתַּכַּל בִּשְׁנֵי דַר וְדַר שְׁאַל אֲבוּךְ וִיחַוִּי לָךְ סָבָיךְ וְיֵימְרוּן לָךְ:
@871 בְּאַחֲסָנָא עִלָאָה עַמְמַיָא בְּפָרָשׁוּתֵהּ בְּנֵי אֲנָשָׁא קַיִים תְּחוּמֵי עַמְמַיָא לְמִנְיַן בְּנֵי יִשְׂרָאֵל:
@872 אֲרֵי חֳלָקָא דַיְיָ עַמֵהּ יַעֲקֹב עֲדַב אַחֲסַנְתֵּהּ:
@873 סַפִּיק צָרְכֵּיהוֹן בְּאַרְעָא מַדְבְּרָא וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא אַשְׁרִנוּן סְחוֹר סְחוֹר לִשְׁכִנְתֵּהּ אַלֵפִנוּן פִּתְגָמֵי אוֹרַיְתָא נְטָרִנוּן כְּבָבַת עֵינֵיהוֹן:
@874 כְּנִשְׁרָא דִמְחִישׁ לְקִנֵהּ עַל בְּנוֹהִי מִתְחוֹפֵף פָּרִיס גַדְפּוֹהִי מְקַבֶּלְהוֹן מְנַטֶלְהוֹן עַל תְּקוֹף אֵבָרוֹהִי:
@875 יְיָ בִּלְחוֹדוֹהִי עֲתִיד לְאַשְׁרָיוּתְהוֹן בְּעָלְמָא דְּהוּא עָתִיד לְאִתְחַדָתָא וְלָא יִתְקַיַם קֳדָמוֹהִי פָּלְחַן טַּעֲוָן:
@876 אַשְׁרִנוּן עַל תָּקְפֵּי אַרְעָא וְאוֹכָלִנוּן בִּזַת סָנְאֵיהוֹן וִיהַב לְהוֹן בִּזַת שַׁלִיטֵי קִרְוִין וְנִכְסֵי יָתְבֵי כְּרַכִּין תַּקִיפִין:
@877 יְהַב לְהוֹן בִּזַת מַלְכֵיהוֹן וְשַׁלִיטֵיהוֹן עִם עוֹתַר רַבְרְבֵיהוֹן וְתַקִפֵיהוֹן עַמָא דְאַרְעֲהוֹן וְאַחֲסַנְתְּהוֹן עִם בִּזַת חֵילֵיהוֹן וּמַשִׁרְיָתְהוֹן וְדַם גִבָּרֵיהוֹן יִתָּשַׁד כְּמַיָא:
@878 וְעַתַּר יִשְׂרָאֵל וּבְעַט אַצְלַח תְּקוֹף קְנָא נִכְסִין וּשְׁבַק פָּלְחַן אֱלָהָא דְעָבְדֵהּ וְאַרְגֵז קֳדָם תַּקִיפָא דְפָרְקֵהּ:
@879 אַקְנִיאוּ קֳדָמוֹהִי בְּפָלְחַן טַעֲוָן בְּתוֹעֶבְתָּא אַרְגִיזוּ קֳדָמוֹהי:
@880 דבָּחוּ לשֵׁדין דִלֵית בְּהוֹן צְרוֹךְ דַחֲלָן דְלָא יְדָעֻנוּן חַדְתִּין דִי מִקָרִיב אִתְעֲבִידוּ לָא אִתְעַסְקוּ בְהוֹן אֲבָהָתְכוֹן:
@881 דַחֲלַת תַקִיפָא דִבְרָאָךְ אִתְנְשֵׁתָא שְׁבַקְתָּא פָלְחַן אֱלָהָא דְעָבְדָךְ:
@882 וּגְלֵי קֳדָם יְיָ וּתְקֵף רָגְזֵהּ מִדְאַרְגִיזוּ קֳדָמוֹהִי בְּנִין וּבְנָן:
@883 וַאֲמַר אֶסַלֵק שְׁכִנְתִּי מִנְהוֹן גְלֵי קֳדָמַי מָה יְהֵי בְסוֹפֵיהוֹן אֲרֵי דָרָא דְאַשְׁנִיוּ אִנוּן בְנַיָא דִלֵית בְּהוֹן הֵימָנוּ:
@884 אִנוּן אַקְנִיאוּ קֳדָמַי בְּלָא דַחֲלָא אַרְגִיזוּ קֳדָמַי בְּפָלְחַן טַעֲוָן וַאֲנָא אַקְנִנוּן בְּלָא עַם בְּעַמָא טַּפְּשָׁא אַרְגֵזִנוּן:
@885 אֲרֵי קִדוּם תַּקִיף כְּאֶשָׁא נְפַק מִקָדָמַי בִּרְגַז וְשֵׁצֵי עַד שְׁאוֹל אֲרָעִית וְאָסֵף אַרְעָא וַעֲלַלְתַּהּ וְשֵׁצְיַת עַד סְיָפֵי טוּרַיָא:
@886 אָסֵף עֲלֵיהוֹן בִּישִׁין מַכְתָּשַׁי אֱשֵׁצֵי בְהוֹן:
@887 נְפִיחֵי כָפָן וַאֲכוּלֵי עוּף וּכְתִישֵׁי רוּחִין בִּישָׁן וְשֵׁן חֵיוַת בָּרָא אֱגָרֵי בְהוֹן עִם חֲמַת תַּנִינַיָא דְזָחֲלִין בְּעַפְרָא:
@888 מִבָּרָא תְּתַכֵּל חַרְבָּא וּמִתְּוָנַיָא חַרְגַת מוֹתָא אַף עוּלֵמֵיהוֹן אַף עוּלֵמָתְהוֹן יָנְקֵיהוֹן עִם אֱנַשׁ סָבֵיהוֹן:
@889 אֲמָרִית יֵחוֹל רוּגְזִי עֲלֵיהוֹן וֶאֱשֵׁצִנוּן אֱבַטַל מִבְּנֵי אֲנָשָׁא דוּכְרָנֵיהוֹן:
@890 אִלוּלָפוֹן רָגְזָא דְסָנְאָה כְּנִישׁ דִילְמָא יִתְרַבְרַב בְּעֵל דְבָבָא דִילְמָא יֵימְרוּן יְדָנָא תְקִיפַת לָנָא וְלָא מִן קֳדָם יְיָ הֲוַת כָּל דָא:
@891 אֲרֵי עַם מְאַבְּדֵי עֵצָה אִנוּן וְלֵית בְּהוֹן סוּכְלְתָנוּ:
@892 אִלוּ חַכִּימוּ אִסְתַּכָּלוּ בְדָא סְבָרוּ מָה יְהֵי בְסוֹפֵיהוֹן:
@893 אֶכְדֵין יִרְדוֹף חַד אַלְפָא וּתְרֵין יֶעֶרְקוּן לְרִבּוֹתָא אֶלָהֵן (אֲרֵי) תַּקִיפְהוֹן מְסָרִנוּן וַייָ אַשְׁלֵמִנוּן:
@894 אֲרֵי לָא כְתָקְפָּנָא תָּקְפְהוֹן וּבַעֲלֵי דְבָבָנָא הֲווֹ דַיָנָנָא:
@895 אֲרֵי כְפֻרְעֲנוּת עַמָא דִסְדוֹם פֻּרְעֲנוּתְהוֹן וְלָקוּתְהוֹן כְּעַם עֲמֹרָה מָחָתְהוֹן בִּישִׁין כְּרֵישֵׁי חֶוְיָן וְתֻשְׁלָמַת עוֹבָדֵיהוֹן כִּמְרָרוּתְהוֹן:
@896 הָא כְמָרַת תַּנִינַיָא כַּס פֻּרְעֲנוּתְהוֹן וּכְרֵישׁ פְּתָנֵי חֶוְיָן אַכְזְרָאִין:
@897 הֲלָא כָל עוֹבָדֵיהוֹן גְלָן קֳדָמַי גְנִיזִין לְיוֹם דִינָא בְּאוֹצְרָי:
@898 קֳדָמַי פֻּרְעֲנוּתָא וַאֲנָא אֲשַׁלֵם לְעִדָן דְיִגְלוּן מֵאַרְעֲהוֹן אֲרֵי קָרִיב יוֹם תְּבָרְהוֹן וּמַבַּע דְעָתִיד לְהוֹן:
@899 אֲרֵי יְדִין יְיָ דִינָא דְעַמֵהּ וּפֻרְעֲנוּת עֲבְדוֹהִי צַדִיקַיָא יִתְפְרַע אֲרֵי גְלֵי קֳדָמוֹהִי דִבְעִדָן דְתִתְקֵף עֲלֵיהוֹן מָחַת סָנְאָה יְהוֹן מִטַלְטְלִין וּשְׁבִיקִין:
@900 וְיֵימַר אָן דַחֲלָתְהוֹן תַּקִיפָא דַהֲווֹ רְחִיצִין בֵּהּ:
@901 דִי תְרַב נִכְסָתְהוֹן הֲווֹ אָכְלִין שָׁתָן חֲמַר נִסְכֵּיהוֹן יְקוּמוּן כְּעַן וִיסַעֲדוּנְכוֹן יְהוֹן עֲלֵיכוֹן מָגֵן:
@902 חֲזוֹ כְּעַן אֲרֵי אֲנָא אֲנָא הוּא וְלֵית אֱלָהּ בַּר מִנִי אֲנָא מֵמִית וּמְחַיֵה מָחֵינָא וְאַף מַסֵינָא וְלֵית מִן יְדִי מְשֵׁזֵב:
@903 אֲרֵי אַתְקֵנִית בִּשְׁמַיָא בֵּית שְׁכִנְתִּי וַאֲמָרִית קַיָם אֲנָא לְעָלְמִין:
@904 אִם עַל חַד תְּרֵין כְּחֵיזוּ בַרְקָא מִסוֹף שְׁמַיָא וְעַד סוֹף שְׁמַיָא תִּתְגְלִי חַרְבִּי וְתִתְקֵף בְּדִינָא יְדִי אָתֵב פֻּרְעֲנוּתָא לְסָנְאַי וּלְבַעֲלֵי דְבָבַי אֱשַׁלֵם:
@905 אֱרַוֵי גִירַי מִדְמָא וְחַרְבִּי תִּקְטוֹל בְּעַמְמַיָא מִדַם קְטִילָן וְשִׁבְיָן לְאַעְדָאָה כִתְרִין מֵרֵישׁ סָנְאָה וּבְעַל דְבָבָא:
@906 שַׁבָּחוּ עַמְמַיָא עַמֵהּ אֲרֵי פֻּרְעֲנוּת עַבְדוֹהִי צַדִיקַיָא יִתְפְּרַע וּפֻרְעֲנוּת יָתֵיב לְסָנְאוֹהִי וִיכַפֵּר עַל אַרְעֵהּ וְעַל עַמֵהּ:
@907 וַאֲתָא מֹשֶׁה וּמַלִּיל יָת כָּל פִּתְגָמֵי תֻשְׁבַּחְתָּא הָדָא קֳדָם עַמָא הוּא וְהוֹשֵׁעַ בַּר נוּן:
@908 וְשֵׁצִי מֹשֶׁה לְמַלָלָא יָת כָּל פִּתְגָמַיָא הָאִלֵין עִם כָּל יִשְׂרָאֵל:
@909 וַאֲמַר לְהוֹן שַׁווּ לִבְּכוֹן לְכָל פִּתְגָמַיָא דִי אֲנָא מַסְהֵד בְּכוֹן יוֹמָא דֵין דִי תְפַקְדִנוּן יָת בְּנֵיכוֹן לְמִטַר לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@910 אֲרֵי לָא פִתְגָם רֵקָא הוּא מִנְכוֹן אֲרֵי הוּא חַיֵיכוֹן וּבְפִתְגָמָא הָדֵין תּוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא תַּמָן לְמֵירְתַהּ:
@911 וּמַלִיל יְיָ עִם מֹשֶׁה בִּכְרַן יוֹמָא הָדֵין לְמֵימָר:
@912 סַק לְטוּרָא דַעֲבָרָאֵי הָדֵין טוּרָא דִנְבוֹ דִי בְּאַרְעָא דְמוֹאָב דִי עַל אַפֵּי יְרֵחוֹ וַחֲזֵי יָת אַרְעָא דִכְנַעַן דִי אֲנָא יָהֵב לִבְנֵי יִשְׂרָאֵל לְאַחֲסָנָא:
@913 וּמוּת בְּטוּרָא דִי אַתְּ סָלֵק לְתַמָן וְתִתְכְּנֵשׁ לְעַמָךְ כְּמָא דְמִית אַהֲרֹן אֲחוּךְ בְּהוֹר טוּרָא וְאִתְכְּנִישׁ לְעַמֵהּ:
@914 עַל דִי שַׁקַרְתּוּן בְּמֵי:מרִי בְּגוֹ בְּנֵי יִשְׂרָאֵל בְּמֵי מַצוּת רְקָם מַדְבְּרָא דְצִין עַל דִי לָא קַדִשְׁתּוּן יָתִי בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@915 אֲרֵי מִקֳבֵל תֶּחֱזֵי יָת אַרְעָא וּלְתַמָן לָא תֵעוּל לְאַרְעָא דִי אֲנָא יָהֵב לִבְנֵי יִשְׂרָאֵל: פפפ:
@916 וְדָא בִרְכְּתָא דִי בְרִיךְ מֹשֶׁה נְבִיָא דַיְיָ יָת בְּנֵי יִשְׂרָאֵל קֳדָם מוֹתֵהּ:
@917 וַאֲמַר יְיָ מִסִינַי אִתְגְלִי וְזֵהוֹר יְקָרֵהּ מִשֵׂעִיר אִתְחֲזֵי לָנָא אִתְגְלִי בִגְבֻרְתֵּהּ מִטוּרָא דְפָארָן וְעִמֵהּ רִבְבַת קַדִישִׁין כְּתַב יַמִינֵהּ מִגוֹ אֶשָׁתָא אוֹרַיְתָא יְהַב לָנָא:
@918 אַף חַבִּיבִנוּן לְשִׁבְטַיָא כָּל קַדִישׁוֹהִי בֵית יִשְׁרָאֵל בִּגְבוּרָא אַפֵּקִנוּן מִמִצְרָיִם וְאִנוּן מִדַבְּרִין תִּחוֹת עֲנָנָךְ נָטִלִין עַל מֵימְרָךְ:
@919 אוֹרַיְתָא יְהַב לָנָא מֹשֶׁה מְסָרַהּ יְרֻתָּא לְכִנְשַׁת יַעֲקֹב:
@920 וַהֲוָה בְיִשְׂרָאֵל מַלְכָּא בְּאִתְכַּנָשׁוּת רֵישֵׁי עַמָא כַּחֲדָא שִׁבְטַיָא דְיִשְׂרָאֵל:
@921 יְחִי רְאוּבֵן לְחַיֵי עַלְמָא וּמוֹתָא תִנְיָנָא לָא יְמוּת וִיקַבְּלוּן בְּנוֹהִי אַחֲסַנְתְּהוֹן בְּמִנְיָנְהוֹן:
@922 וְדָא לִיהוּדָה וַאֲמַר קַבֵּל יְיָ צְלוֹתֵהּ דִיהוּדָא בְּמִפְּקֵהּ לְאַגָחָא קְרָבָא וּלְעַמֵהּ תָּתֵיבִנֵהּ לִשְׁלָם יְדוֹהִי יַעְבְּדָן לֵהּ פֻּרְעֲנוּתָא מִסָנְאוֹהִי וְסָעִיד מִבַּעֲלֵי דְבָבוֹהִי הֲוֵי לֵהּ:
@923 וּלְלֵוִי אֲמַר תּוּמַיָא וְאוּרַיָא אַלְבֶּשְׁתָּא לִגְבַר דְאִשְׁתְּכַח חֲסִידָא קֳדָמָךְ דִי נַסִיתוֹהִי בְּנִסֵתָא וַהֲוָה שְׁלִים בְּחַנְתּוֹהִי עַל מֵי מַצוּתָא וְאִשְׁתְּכַח מְהֵימָן:
@924 דְעַל אֲבוֹהִי וְעַל אִמֵהּ לָא רַחֵם כַּד חָבוּ מִן דִינָא וְאַפֵּי אֲחוֹהִי וּבְנוֹהִי לָא נְסִיב אֲרֵי נְטָרוּ מַטְרַת מֵימְרָךְ וּקְיָמָךְ לָא אַשְׁנִיוּ:
@925 כָּשְׁרִין אִלֵין דְיַלְפוּן דִינָיךְ לְיַעֲקֹב וְאוֹרַיְתָךְ לְיִשְׂרָאֵל יְשַׁוּוּן קְטוֹרֶת בּוּסְמִין קֳדָמָךְ וּגְמִיר לְרַעֲוָא עַל מַדְבְּחָךְ:
@926 בָּרֵךְ יְיָ נִכְסוֹהִי וְקוּרְבַּן יְדוֹהִי תְּקַבֵּל בְּרַעֲוָא תְּבַר חַרְצָא דְסָנְאוֹהִי וּדְבֵעֲלֵי דְבָבוֹהִי דְלָא יְקוּמוּן:
@927 לְבִנְיָמִן אֲמַר רְחִימָא דַיְיָ יִשְׁרֵי לְרָחְצַן עֲלוֹהִי יְהֵי מָגֵן עֲלוֹהִי כָּל יוֹמַיָא וּבְאַרְעֵהּ תִּשְׁרֵי שְׁכִנְתָּא:
@928 וּלְיוֹסֵף אֲמַר מְבָרָכָא מִן קֳדָם יְיָ אַרְעֵהּ עָבְדָא מִגְדָנִין מִטַלָא דִשְׁמַיָא מִלְעֵלָא וּמִמַבּוּעֵי עֵינָוָן וּתְהוֹמִין דְנָגְדָן מִמַעֲמַקֵי אַרְעָא מִלְרָע:
@929 וְעָבְדָא מִגְדָנִין וַעֲלָלָן מִיבוּל שִׁמְשָׁא וְעָבְדָא מִגְדָנִין מֵרֵישׁ יְרַח בִּירַח:
@930 וּמֵרֵיש טוּרַיָא בַכִּירַיָא וּמִטוּב רָמָן דְלָא פָסְקָן:
@931 וּמִטוּב אַרְעָא וּמָלָאַהּ וְרָעֵי לֵהּ דִשְׁכִנְתֵּהּ בִּשְׁמַיָא וְעַל מֹשֶׁה אִתְגְלִי בַאֲסָנָא יֵיתוּן כָּל אִלֵין לְרֵישָׁא דְיוֹסֵף וּלְגַבְרָא פָּרִישָׁא דַאֲחוֹהִי:
@932 רַבָּא דִבְנוֹהִי זִיוָא לֵהּ וּגְבוּרָן דְאִתְעֲבִידָא לֵהּ מִקֳדָם דְתוּקְפָא וְרוּמָא דִילֵהּ בִּגְבֻרְתֵּהּ עַמְמַיָא יִקְטֵל כַּחֲדָא עַד סְיָפֵי אַרְעָא וְאִנוּן רִבְוָתָא דְבֵית אֶפְרַיִם וְאִנוּן אַלְפַיָא דְבֵית מְנַשֶׁה:
@933 וְלִזְבוּלֻן אֲמַר חֲדֵי זְבוּלֻן בְּמִפְּקָךְ לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִשָׂשׂכָר בִּמְהָכָךְ לְמֶעְבַּד זִמְנֵי מוֹעֲדַיָא בִּירוּשְׁלֵם:
@934 שִׁבְטַּיָא דְיִשְׂרָאֵל לְטוּר בֵּית מַקְדְשָׁא יִתְכַּנְשׁוּן תַּמָן יִכְסוּן נִכְסַת קוּדְשִׁין לְרַעֲוָא אֲרֵי נִכְסֵי עַמְמַיָא יֵיכְלוּן וְסִימָא דְמִטַמְרָא בְחָלָא מִתְגַלְיָא לְהוֹן:
@935 וּלְגָד אֲמַר בְּרִיךְ דְאַפְתֵּי לְגָד כְּלֵיתָא שָׁרֵי וְיִקְטוֹל שִׁלְטוֹנִין עִם מַלְכִין:
@936 וְאִתְקַבֵּל בְּקַדְמֵתָא דִילֵהּ אֲרֵי תַמָן בְּאַחֲסַנְתֵּהּ מֹשֶׁה סָפְרָא רַבָּא דְיִשְׂרָאֵל קְבִיר וְהוּא נָפֵק וְעַל בְּרֵישׁ עַמָא זַכְוָן קֳדָם יְיָ עֲבַד וְדִינוֹהִי עִם יִשְׂרָאֵל:
@937 וּלְדָן אֲמַר דָן תַּקִיף כְּגוּר אַרְיְוָן אַרְעֵהּ שָׁתְיָא מִן נַחֲלַיָא דְנָגְדָן מִן מַתְנָן:
@938 וּלְנַפְתָּלִי אֲמַר נַפְתָּלִי שְׂבַע רַעֲוָא וּמְלֵי בִּרְכָן מִן קֳדָם יְיָ מַעֲרָב יָם גִנוֹסַר וְדָרוֹמָא יֵרָת:
@939 וּלְאָשֵׁר אֲמַר בְּרִיךְ מִבִּרְכַּת בְּנַיָא אָשֵׁר יְהֵי רַעֲוָא לְאַחוֹהִי וְיִתְרַבֵּי בְּתַפְנוּקֵי מַלְכִין:
@940 תַּקִיף כְּפַרְזְלָא וּנְחָשָׁא מוֹתָבָךְ וּכְיוֹמֵי עוּלֵמָתָךְ תָּקְפָּךְ:
@941 לֵית אֱלָהּ כֶּאֱלָהָא דְיִשְׂרָאֵל דִשְׁכִנְתֵּהּ בִּשְׁמַ יָא בְּסַעְדָךְ וְתָקְפֵּהּ בִּשְׁמֵי שְׁמַיָא:
@942 מְדוֹר אֱלָהָא דִי מִלְקַדְמִין בְּמֵימְרֵהּ אִתְעֲבֵד עָלְמָא וְתָרִיךְ מִקֳדָמָךְ סָנְאָה וַאֲמַר שֵׁצִי:
@943 וּשְׁרָא יִשְׂרָאֵל לְרָחְצָן בִּלְחוֹדוֹהִי כְּעֵין בִּרְכְּתָא דְבָרֵכִנוּן יַעֲקֹב אֲבוּהוֹן לְאַרְעָא עָבְדָא עִבוּר וַחֲמָר אַף שְׁמַיָא דְעִלָוֵיהוֹן יְשַׁ מְשֻׁנוּן בְּטַלָא:
@944 טוּבָּךְ יִשְׂרָאֵל לֵית דִכְוָתָךְ עַמָא דְפֻרְקָנֵהּ מִן קֳדָם יְיָ תַּקִיף בְּסַעְדָךְ וּדְמִן קֳדָמוֹהִי נִצְחָן גִבַּרְוָתָךְ וִיכַדְבוּן סָנְאָךְ לָךְ וְאַתְּ עַל פְּרִיקַת צַוָארֵי מַלְכֵיהוֹן תִּדְרֹךְ:
@945 וּסְלֵיק מֹשֶׁה מִמֵישְׁרָא דְמוֹאָב לְטוּרָא דִנְבוֹ רֵישׁ רָמָתָא דִי עַל אַפֵּי יְרֵחוֹ וְאַחְזְיֵהּ יְיָ יָת כָּל אַרְעָא יָת גִלְעָד עַד דָן:
@946 וְיָת כָּל נַפְתָּלִי וְיָת אַרְעָא דְאֶפְרַיִם וּמְנַשֶׁה וְיָת כָּל אַרְעָא דִיהוּדָה עַד יַמָא מַעַרְבָא:
@947 וְיָת דָרוֹמָא וְיָת מֵישְׁרָא בִּקְעֲתָא דִירֵחוֹ קַרְתָּא דְדִקְלַיָא עַד צוֹעַר:
@948 וַאֲמַר יְיָ לֵהּ דָא אַרְעָא דִי קַיֵמִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמֵימָר לִבְנָיךְ אֶתְּנִנַהּ אַחֲזִיתָךְ בְּעֵינָיךְ וּלְתַמָן לָא תְעִבַּר:
@949 וּמִית תַּמָן מֹשֶׁה עַבְדָא דַיְיָ בְּאַרְעָא דְמוֹאָב עַל מֵימְרָא דַיְיָ:
@950 וּקְבַר יָתֵהּ בְּחֵילָתָא בְּאַרְעָא דְמוֹאָב לְקֳבֵל בֵּית פְּעוֹר וְלָא יְדַע אֱנַשׁ יָת קְבֻרְתֵּה עַד יוֹמָא הָדֵין:
@951 וּמֹשֶׁה בַּר מְאָה וְעַשְׂרִין שְׁנִין כַּד מִית לָא כְהַת עֵינוֹהִי וְלָא שְׁנָא זִיו יְקָרָא דְאַפּוֹהִי:
@952 וּבְכוֹ בְנֵי יִשְׂרָאֵל יָת מֹשֶׁה בְּמֵישְׁרַיָא דְמוֹאָב תְּלָתִין יוֹמִין וּשְׁלִימוּ יוֹמֵי בָכִיתָא אֶבְלָא דְמֹשֶׁה:
@953 וִיהוֹשֻׁעַ בַּר נוּן מְלֵי רוּחַ חָכְמְתָא אֲרֵי סְמַךְ מֹשֶׁה יָת יְדוֹהִי עֲלוֹהִי וְקַבִּילוּ מִנֵהּ בְּנֵי יִשְׂרָאֵל וַעֲבָדוּ כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@954 וְלָא קָם נְבִיָא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה דִי אִתְגְלִי לֵהּ יְיָ אַפִּין בְּאַפִּין:
@955 לְכָל אָתַיָא וּמוֹפְתַיָא דִי שָׁלְחֵהּ יְיָ לְמֶעְבַּד בְּאַרְעָא דְמִצְרָיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@956 וּלְכֹל יְדָא תַקֶפְתָּא וּלְכֹל חֵזְוָנָא רַבָּא דִי עֲבַד מֹשֶׁה לְעֵינֵי כָּל יִשְׂרָאֵל: חזק:

@1 **אלה הדברים.** לפי שהן דברי תוכחות ומנה כאן כל המקומות שהכעיסו לפני המקום בהן, לפיכך סתם את הדברים והזכירם ברמז מפני כבודן של ישראל: **אל כל ישראל.** אלו הוכיח מקצתן, היו אלו שבשוק אומרים, אתם הייתם שומעים מבן עמרם ולא השיבותם דבר מכך וכך, אלו היינו שם היינו משיבים אותו, לכך כנסם כלם ואמר להם הרי כלכם כאן כל מי שיש לו תשובה ישיב: **במדבר.** לא במדבר היו אלא בערבות מואב, ומהו במדבר, אלא בשביל מה שהכעיסוהו במדבר שאמרו (שמות טז, ג) מי יתן מותנו וגו' : **בערבה.** בשביל הערבה שחטאו בבעל פעור בשטים בערבות מואב: **מול סוף.** על מה שהמרו בים סוף בבואם לים סוף שאמרו (שם יד, יא) המבלי אין קברים במצרים, וכן בנסעם מתוך הים, שנאמר (תהלים קו, ז) וימרו על ים בים סוף, כדאיתא בערכין (טו, א) : **בין פארן ובין תפל ולבן.** אמר רבי יוחנן [רשב''י] חזרנו על כל המקרא ולא מצינו מקום ששמו תפל ולבן, אלא הוכיחן על הדברים שתפלו על המן שהוא לבן, שאמרו (במדבר כא, ה) ונפשנו קצה בלחם הקלקל ועל מה שעשו במדבר פארן על ידי המרגלים: **וחצרות.** במחלקתו של קרח. דבר אחר אמר להם, היה לכם ללמוד ממה שעשיתי למרים בחצרות בשביל לשון הרע, ואתם נדברתם במקום: **ודי זהב.** הוכיחן על העגל שעשו בשביל רב זהב שהיה להם, שנאמר (הושע ב, י) וכסף הרביתי לה וזהב עשו לבעל:
@2 **אחד עשר יום מחרב.** אמר להם משה ראו מה גרמתם, אין לכם דרך קצרה מחורב לקדש ברנע כדרך הר שעיר ואף הוא מהלך אחד עשר יום, ואתם הלכתם אותו בשלשה ימים, שהרי בעשרים באיר נסעו מחורב שנאמר (במדבר י, יא) ויהי בשנה השנית בחדש השני בעשרים בחדש וגו' ובעשרים ותשעה בסיון שלחו את המרגלים מקדש ברנע, צא מהם שלשים יום שעשו בקברות התאוה, שאכלו הבשר חדש ימים, ושבעה ימים שעשו בחצרות להסגר שם מרים, נמצא בשלשה ימים הלכו כל אותו הדרך, וכל כך היתה שכינה מתלבטת בשבילכם למהר ביאתכם לארץ, ובשביל שקלקלתם הסב אתכם סביבות הר שעיר ארבעים שנה:
@3 **ויהי בארבעים שנה בעשתי עשר חדש באחד לחדש.** מלמד שלא הוכיחן אלא סמוך למיתה. ממי למד, מיעקב שלא הוכיח את בניו אלא סמוך למיתה. אמר, ראובן בני, אני אומר לך מפני מה לא הוכחתיך כל השנים הללו, כדי שלא תניחני ותלך ותדבק בעשו אחי. ומפני ארבעה דברים אין מוכיחין את האדם אלא סמוך למיתה, כדי שלא יהא מוכיחו וחוזר ומוכיחו, ושלא יהא חברו רואהו ומתבייש ממנו וכו' כדאיתא בספרי. וכן יהושע לא הוכיח את ישראל אלא סמוך למיתה, וכן שמואל, שנאמר (ש''א יב, ג) הנני ענו בי. וכן דוד את שלמה בנו:
@4 **אחרי הכתו.** אמר משה אם אני מוכיחם קודם שיכנסו לקצת הארץ, יאמרו מה לזה עלינו, מה היטיב לנו, אינו בא אלא לקנתר ולמצא עלה שאין בו כח להכניסנו לארץ, לפיכך המתין עד שהפיל סיחון ועוג לפניהם והורישם את ארצם ואחר כך הוכיחן: **סיחן** וגו' **אשר יושב** וגו' **.** אלו לא היה סיחון קשה והיה שרוי בחשבון, היה קשה, שהמדינה קשה, ואלו היתה עיר אחרת וסיחון שרוי בתוכה היתה קשה, שהמלך קשה, על אחת כמה וכמה שהמלך קשה והמדינה קשה: **אשר יושב בעשתרת.** המלך קשה והמדינה קשה: **עשתרת.** הוא לשון צוקין וקושי כמו (בראשית יד, ה) עשתרות קרנים, ועשתרות זה הוא עשתרות קרנים שהיו שם רפאים שהכה אמרפל, שנאמר (בראשית יד, ה) ויכו את רפאים בעשתרות קרנים, ועוג נמלט מהם והוא שנאמר (שם יד, יג) ויבא הפליט, ואומר (דברים ג, יא) כי רק עוג מלך הבשן נשאר מיתר הרפאים: **באדרעי.** שם המלכות:
@5 **הואיל.** התחיל כמו (בראשית יח, כז) הנה נא הואלתי: **באר את התורה.** בשבעים לשון פרשה להם:
@6 **רב לכם שבת.** כפשוטו. ויש מדרש אגדה הרבה לכם גדלה ושכר על ישיבתכם בהר הזה, עשיתם משכן מנורה וכלים, קבלתם תורה, מניתם לכם סנהדרין, שרי אלפים ושרי מאות:
@7 **פנו וסעו לכם.** זו דרך ערד וחרמה: **ובאו הר האמרי.** כמשמעו: **ואל כל שכניו.** עמון ומואב והר שעיר: **בערבה.** זה מישור של יער: **בהר.** זה הר המלך: **ובשפלה.** זו שפלת דרום: **ובנגב ובחוף הים.** אשקלון ועזה וקסרי וכו' כדאיתא בספרי: **עד הנהר הגדל.** מפני שנזכר עם ארץ ישראל, קראו גדול. משל הדיוט אומר עבד מלך מלך, הדבק לשחור וישתחוו לך, קרב לגבי דהנא ואדהן:
@8 **ראה נתתי.** בעיניכם אתם רואים. איני אומר לכם מאומד ומשמועה: **באו ורשו.** אין מערער בדבר ואינכם צריכים למלחמה, אלו לא שלחו מרגלים לא היו צריכים לכלי זין: **לאבתיכם.** למה הזכיר שוב לאברהם ליצחק וליעקב, אלא אברהם כדאי לעצמו, יצחק כדאי לעצמו, יעקב כדאי לעצמו:
@9 **ואמר אליכם בעת ההוא לאמר.** מהו לאמר, אמר להם משה, לא מעצמי אני אומר לכם, אלא מפי הקדוש ברוך הוא: **לא אוכל לבדי** וגו' **.** אפשר שלא היה משה יכול לדון את ישראל, אדם שהוציאם ממצרים וקרע להם את הים והוריד את המן והגיז את השלו לא היה יכול לדונם, אלא כך אמר להם, ה' אלהיכם הרבה אתכם, הגדיל והרים אתכם על דיניכם נטל את הענש מכם ונתנו על הדינין. וכן אמר שלמה (מלכים א' ג, ט) כי מי יוכל לשפט את עמך הכבד הזה, אפשר מי שכתוב בו (שם ה, יא) ויחכם מכל האדם, אומר מי יוכל לשפט, אלא כך אמר שלמה אין דיני אמה זו כדיני שאר האמות, שאם דן והרג ומכה וחונק ומטה את דינו וגוזל אין בכך כלום, אני אם חיבתי ממון שלא כדין, נפשות אני נתבע, שנאמר (משלי כב, כג) וקבע את קבעיהם נפש:
@10 **והנכם היום ככוכבי השמים.** וכי ככוכבי השמים היו באותו היום, והלא לא היו אלא ששים רבוא, מהו והנכם היום, הנכם משולים כיום, קימים כחמה וכלבנה וככוכבים:
@11 **יסף עליכם ככם אלף פעמים.** מהו שוב ויברך אתכם כאשר דבר לכם, אלא אמרו לו משה אתה נותן קצבה לברכתנו, כבר הבטיח הקדוש ברוך הוא את אברהם (בראשית יג, טז) אשר אם יוכל איש למנות וגו' , אמר להם זו משלי היא, אבל הוא יברך אתכם כאשר דבר לכם:
@12 **איכה אשא לבדי.** אם אומר לקבל שכר לא אוכל, זו היא שאמרתי לכם לא מעצמי אני אומר לכם, אלא מפי הקדוש ברוך הוא: **טרחכם.** מלמד שהיו ישראל טרחנין. היה אחד מהם רואה את בעל דינו נוצח בדין, אומר יש לי עדים להביא, יש לי ראיות להביא, מוסיף אני עליכם דינין: **ומשאכם.** מלמד שהיו אפיקורוסין. הקדים משה לצאת, אמרו, מה ראה בן עמרם לצאת, שמא אינו שפוי בתוך ביתו. אחר לצאת, אמרו, מה ראה בן עמרם שלא לצאת, מה אתם סבורים, יושב ויועץ עליכם עצות רעות וחושב עליכם מחשבות: **וריבכם.** מלמד שהיו רוגנים:
@13 **הבו לכם.** הזמינו עצמכם לדבר: **אנשים.** וכי תעלה על דעתך נשים, מה תלמוד לומר אנשים, צדיקים כסופים: **נבונים.** מבינים דבר מתוך דבר. זו היא ששאל אריוס את רבי יוסי, מה בין חכמים לנבונים. חכם דומה לשלחני עשיר, כשמביאין לו דינרין לראות רואה, וכשאין מביאין לו יושב ותוהא. נבון דומה לשלחני תגר, כשמביאין לו מעות לראות רואה, וכשאין מביאין לו מחזר ומביא משלו: **וידעים לשבטיכם.** שהם נכרים לכם, שאם בא לפני מעטף בטליתו איני יודע מי הוא ומאיזה שבט הוא ואם הגון הוא, אבל אתם מכירין בו, שאתם גדלתם אותו, לכך נאמר וידעים לשבטיכם: **בראשיכם.** ראשים ומכבדים עליכם שתהיו נוהגין בהם כבוד ויראה: **ואשימם.** חסר יו''ד, [לומר] למד שאשמותיהם של ישראל תלויות בראשי דיניהם, שהיה להם למחות ולכון אותם לדרך הישרה:
@14 **ותענו אתי** וגו' **.** החלטתם את הדבר להנאתכם, היה לכם להשיב, רבנו משה ממי נאה ללמוד ממך או מתלמידך לא ממך שנצטערת עליה. אלא ידעתי מחשבותיכם. הייתם אומרים, עכשיו יתמנו עלינו דינין הרבה, אם אין מכירנו אנו מביאין לו דורון והוא נושא לנו פנים: **לעשות.** אם הייתי מתעצל, אתם אומרים עשה מהרה:
@15 **ואקח את ראשי שבטיכם.** משכתים בדברים, אשריכם, על מי באתם להתמנות, על בני אברהם יצחק ויעקב, על בני אדם שנקראו אחים ורעים, חלק ונחלה וכל לשון חבה: **אנשים חכמים וידעים.** אבל נבונים לא מצאתי. זו אחת משבע מדות שאמר יתרו למשה ולא מצא אלא שלש, אנשים צדיקים, חכמים וידעים: **ראשים עליכם.** שתנהגו בהם כבוד. ראשים במקח, ראשים בממכר, ראשים במשא ומתן, נכנס אחרון ויוצא ראשון: **שרי אלפים.** אחד ממנה על אלף: **שרי מאות.** אחד ממנה על מאה: **ושטרים.** מניתי עליכם לשבטיכם. אלו הכופתין והמכין ברצועה על פי הדינין:
@16 **ואצוה את שפטיכם.** אמרתי להם הוו מתונים בדין, אם בא דין לפניך פעם אחת שתים ושלש אל תאמר כבר בא דין זה לפני פעמים הרבה אלא היו נושאים ונותנים בו: **בעת ההוא.** משמניתים אמרתי להם, אין עכשיו כלשעבר, לשעבר הייתם ברשות עצמכם, עכשיו הרי אתם משעבדים לצבור: **שמע.** לשון הוה [בהאזינכם] כמו (שמות כ, ז) זכור, (דברים ה, יא) שמור: **ובין גרו.** זה בעל דינו, שאוגר עליו דברים. דבר אחר ובין גרו, אף על עסקי דירה בין חלקת אחים אפלו בין תנור לכירים:
@17 **לא תכירו פנים במשפט.** זה הממנה להושיב הדינין, שלא יאמר איש פלוני נאה או גבור, אושיבנו דין, איש פלוני קרובי, אושיבנו דין בעיר, והוא אינו בקי בדינין נמצא מחיב את הזכאי ומזכה את החיב. מעלה אני על מי שמנהו כאלו הכיר פנים בדין: **כקטן כגדל תשמעון.** שיהא חביב עליך דין של פרוטה כדין של מאה מנה, שאם קדם ובא לפניך לא תסלקנו לאחרון [לאחריו] . דבר אחר כקטן כגדל תשמעון, כתרגומו, שלא תאמר, זה עני הוא וחברו עשיר ומצוה לפרנסו אזכה את העני ונמצא מתפרנס בנקיות. דבר אחר שלא תאמר היאך אני פוגם כבודו של עשיר זה בשביל דינר, אזכנו עכשיו, וכשיצא לחוץ אומר אני לו, תן לו שאתה חיב לו: **לא תגורו מפני איש.** לא תיראו. דבר אחר לא תגורו, לא תכניס דבריך מפני איש. לשון (משלי י, ה) אוגר בקיץ: **כי המשפט לאלהים הוא.** מה שאתה נוטל מזה שלא כדין, אתה מזקיקני להחזיר לו, נמצא שהטית עלי המשפט: **תקרבון אלי.** על דבר זה נסתלק ממנו משפט בנות צלפחד, וכן שמואל אמר לשאול (שמואל א' ט, יט) אנכי הראה, אמר לו הקדוש ברוך הוא, חייך שאני מודיעך שאין אתה רואה. ואימתי הודיעו, כשבא למשוח את דוד (שם טז, ו) וירא את אליאב ויאמר אך נגד ה' משיחו, אמר לו הקדוש ברוך הוא, ולא אמרת אנכי הראה (שם טז, ז) אל תבט אל מראהו:
@18 **את כל הדברים אשר תעשון.** אלו עשרת הדברים שבין דיני ממונות לדיני נפשות:
@19 **המדבר הגדול והנורא.** שהיו בו נחשים כקורות, ועקרבים כקשתות:
@22 **ותקרבון אלי כלכם.** בערבוביא, ולהלן הוא אומר (דברים ה, כ. כא) ותקרבון אלי כל ראשי שבטיכם וזקניכם ותאמרו הן הראנו וגו' , אותה קריבה היתה הוגנת. ילדים מכבדים את הזקנים ושלחום לפניהם, וזקנים מכבדים את הראשים ללכת לפניהם, אבל כאן, ותקרבון אלי כלכם, בערבוביא. ילדים דוחפין את הזקנים וזקנים דוחפין את הראשים: **וישבו אתנו דבר.** באיזה לשון הם מדברים: **את הדרך אשר נעלה בה.** אין דרך שאין בה עקמימות: **ואת הערים אשר נבא אליהן.** תחלה לכבוש:
@23 **וייטב בעיני הדבר.** בעיני ולא בעיני המקום. ואם בעיני משה היה טוב למה אמרה בתוכחות, משל לאדם שאומר לחברו מכור לי חמורך זה, אמר לו הן. נותנו אתה לי לנסיון, אמר לו הן. בהרים וגבעות, אמר לו הן. כיון שראה שאין מעכבו כלום, אמר הלוקח בלבו, בטוח הוא זה שלא אמצא בו מום. מיד אמר לו טול מעותיך ואיני מנסהו. מעתה אף אני הודיתי לדבריכם, שמא תחזרו בכם כשתראו שאיני מעכב, ואתם לא חזרתם בכם: **ואקח מכם.** מן הברורים שבכם מן המסלתים שבכם: **שנים עשר אנשים איש אחד לשבט.** מגיד שלא היה שבט לוי עמהם:
@24 **עד נחל אשכל.** מגיד שנקרא על שם סופו: **וירגלו אתה.** מלמד שהלכו בה ארבעה אומנין שתי וערב:
@25 **ויורדו אלינו.** מגיד שארץ ישראל גבוהה מכל הארצות: **ויאמרו טובה הארץ.** מי הם שאמרו טובתה, יהושע וכלב:
@26 **ותמרו.** לשון התרסה, התרסתם כנגד מאמרו:
@27 **ותרגנו.** לשון הרע, וכן (משלי יח, ח) דברי נרגן, אדם המוציא דבה: **בשנאת ה' אתנו.** והוא היה אוהב אתכם, אבל אתם שונאים אותו. משל הדיוט אומר, מה דבלבך על רחמך מה דבלביה עלך: **בשנאת ה' אתנו הוציאנו מארץ מצרים.** הוצאתו לשנאה היתה. משל למלך בשר ודם, שהיו לו שני בנים ויש לו שתי שדות אחת של שקיא ואחת של בעל, למי שהוא אוהב נותן של שקיא, ולמי שהוא שונא נותן לו של בעל. ארץ מצרים של שקיא היא, שנילוס עולה ומשקה אותה, וארץ כנען של בעל, והוציאנו ממצרים לתת לנו את ארץ כנען:
@28 **ערים גדלת ובצורת בשמים.** דברו הכתובים לשון הבאי:
@29 **לא תערצון.** לשון שבירה כתרגומו, ודומה לו (איוב ל, ו) בערוץ נחלים לשכן, לשבור נחלים:
@30 **ילחם לכם.** בשבילכם:
@31 **ובמדבר אשר ראית.** מוסב על מקרא שלמעלה המנו (פסוק ל) , ככל אשר עשה אתכם במצרים, ועשה אף במדבר אשר ראית אשר נשאך וגו' : **כאשר ישא איש את בנו.** כמו שפירשתי אצל (שמות יד, יט) ויסע מלאך האלהים ההולך לפני מחנה ישראל וגו' . משל למהלך בדרך ובנו לפניו באו לסטים לשבותו וכו' :
@32 **ובדבר הזה.** שהוא מבטיחכם להביאכם אל הארץ, אינכם מאמינים בו:
@33 **לראותכם.** כמו להראותכם. וכן (שמות יג, כא) לנחותם הדרך, וכן (תהלים כו, ז) לשמע בקול תודה, וכן (מלכים ב' ט, טו) ללכת לגיד [להגיד] ביזרעאל (לגיד כתיב, להגיד קרי) :
@36 **אשר דרך בה.** חברון, שנאמר (במדבר יג, כב) ויבא עד חברון:
@37 **התאנף.** נתמלא רוגז:
@40 **פנו לכם.** אמרתי להעביר אתכם דרך רוחב ארץ אדום לצד צפון לכנס לארץ, קלקלתם וגרמתם לכם עכוב: **פנו לכם.** לאחוריכם ותלכו במדבר לצד ים סוף. שהמדבר שהיו הולכים בו לדרומו של הר שעיר, היה מפסיק בין ים סוף להר שעיר, עתה המשכו לצד הים ותסבבו את הר שעיר כל דרומו מן המערב למזרח:
@41 **ותהינו.** לשון (במדבר יד, מ) הננו ועלינו אל המקום, זה הלשון שאמרתם, לשון הן, כלומר נזדמנתם:
@42 **לא תעלו.** לא עליה תהא לכם, אלא ירידה:
@44 **כאשר תעשינה הדברים.** מה הדבורה הזאת כשהיא מכה את האדם מיד מתה, אף הם כשהיו נוגעים בכם מיד מתים:
@45 **ולא שמע ה' בקלכם.** כביכול עשיתם מדת רחמיו, כאלו אכזרי:
@46 **ותשבו בקדש ימים רבים.** תשע עשרה שנה, שנאמר כימים אשר ישבתם בשאר המסעות והם היו שלשים ושמנה שנה, תשע עשרה מהם עשו בקדש ותשע עשרה שנה הולכים ומטורפים וחזרו לקדש, כמו שנאמר (במדבר לב, יג) ויניעם במדבר. כך מצאתי בסדר עולם:
@47 **ונפן ונסע המדברה.** אלו לא חטאו היו עוברים דרך הר שעיר לכנס לארץ מן דרומו לצפונו, ובשביל שקלקלו הפכו לצד המדבר שהוא בין ים סוף לדרומו של הר שעיר, והלכו אצל דרומו מן המערב למזרח דרך ים סוף. דרך יציאתן ממצרים שהוא במקצוע דרומית מערבית, משם היו הולכים לצד המזרח: **ונסב את הר שעיר.** כל דרומו עד ארץ מואב:
@49 **פנו לכם צפנה.** סובו לכם לרוח מזרחית מן הדרום לצפון, ופניכם לצפון, נמצאו הולכין את רוח מזרחית. וזהו שנאמר (שופטים יא, יח) ויבא ממזרח שמש לארץ מואב:
@50 **ונשמרתם מאד.** ומהו השמירה, (פסוק ה) אל תתגרו בם:
@51 **עד מדרך כף רגל.** אפלו מדרך כף רגל, כלומר אפלו דריסת הרגל איני מרשה לכם לעבור בארצם שלא ברשות. ומדרשי אגדה, עד שיבא יום דריסת כף רגל על הר הזיתים שנאמר (זכריה יד, ד) ועמדו רגליו וגו' : **ירשה לעשו.** מאברהם, עשרה עממים נתתי לו, שבעה לכם וקיני וקנזי וקדמוני הן עמון ומואב ושעיר, אחד מהם לעשו והשנים לבני לוט, בשכר שהלך אתו למצרים ושתק על מה שהיה אומר על אשתו, אחותי היא, עשאו כבנו:
@52 **תכרו.** לשון מקח. וכן (בראשית נ, ה) אשר כריתי לי, שכן בכרכי הים קורין למכירה כירה:
@53 **כי ה' אלהיך ברכך.** לפיכך לא תכפו את טובתו להראות כאלו אתם עניים, אלא הראו עצמכם עשירים:
@54 **ונפן ונעבר.** לצד צפון, הפכנו פנים להלוך רוח מזרחית:
@55 **ואל תתגר** וגו' **.** לא אסר להם על מואב אלא מלחמה, אבל מיראים היו אותם ונראים להם כשהם מזינים, לפיכך כתיב (במדבר כב, ג) ויגר מואב מפני העם שהיו שוללים ובוזזים אותם. אבל בבני עמון נאמר (פסוק יט) ואל תתגר בם, שום גרוי, בשכר צניעות אמם שלא פרסמה על אביה כמו שעשתה הבכירה, שקראה שם בנה, מואב: **ער.** שם המדינה:
@56 **האמים לפנים** וגו' **.** אתה סבור שזו ארץ רפאים שנתתי לו לאברהם לפי שהאמים שהם רפאים ישבו בה לפנים, אבל לא זו היא כי אותם רפאים הורשתי מפני בני לוט והושבתים תחתם:
@57 **רפאים יחשבו** וגו' **.** רפאים היו נחשבים אותם אמים כענקים הנקראים רפאים על שם שכל הרואה אותם ידיו מתרפות: **אמים.** על שם שאימתם מטלת על הבריות, וכן (פסוק יב) ובשעיר ישבו החרים ונתתים לבני עשו:
@58 **יירשום.** לשון הוה, כלומר נתתי בהם כח שהיו מורישים אותם והולכים:
@61 **היתה בם.** למהר ולהמם בתוך ארבעים שנה שלא יגרמו לבניהם עוד להתעכב במדבר:
@63 **ויהי כאשר תמו** וגו' **. וידבר ה' אלי** וגו' **.** אבל משלוח המרגלים עד כאן לא נאמר בפרשה זו, וידבר, אלא ויאמר, ללמדך, שכל שלשים ושמנה שנה שהיו ישראל נזופים לא נתיחד עמו הדבור בלשון חבה פנים אל פנים וישוב הדעת, ללמדך, שאין השכינה שורה על הנביאים אלא בשביל ישראל: **אנשי המלחמה.** מבן עשרים שנה היוצאים בצבא:
@65 **אתה עבר היום את גבול מואב** וגו' **וקרבת מול בני עמון** וגו' **.** מכאן שארץ עמון לצד צפון:
@66 **ארץ רפאים תחשב.** ארץ רפאים נחשבת אף היא לפי שהרפאים ישבו בה לפנים, אבל לא זו היא שנתתי לאברהם:
@69 **והעוים היושבים בחצרים** וגו' **.** עוים מפלשתים הם, שעמהם הם נחשבים בספר יהושע, שנאמר (יהושע יג, ג) חמשת סרני פלשתים העזתי והאשדודי האשקלוני הגתי והעקרוני והעוים. ומפני השבועה שנשבע אברהם לאבימלך לא יכלו ישראל להוציא ארצם מידם, והבאתי עליהם כפתורים והשמידום וישבו תחתם, ועכשיו אתם מתרים לקחתה מידם:
@71 **תחת כל השמים.** למד שעמדה חמה למשה ביום מלחמת עוג ונודע הדבר תחת כל השמים:
@72 **ממדבר קדמות.** אף על פי שלא צוני המקום לקרא לסיחון לשלום, למדתי ממדבר סיני מן התורה שקדמה לעולם. כשבא הקדוש ברוך הוא לתנה לישראל חזר אותה על עשו וישמעאל, וגלוי לפניו שלא יקבלוה ואף על פי כן פתח להם בשלום, אף אני קדמתי את סיחון בדברי שלום. דבר אחר ממדבר קדמות, ממך למדתי שקדמת לעולמך בדברים. יכול היית לשלוח ברק אחד ולשרוף את המצריים, אלא שלחתני מן המדבר אל פרעה לאמר (שמות ה, א) שלח את עמי, במתון:
@75 **כאשר עשו לי בני עשו.** לא לענין לעבור את ארצם אלא לענין מכר אוכל ומים: **עד אשר אעבר את הירדן.** מוסב על אעברה בארצך:
@77 **החלתי תת לפניך.** כפה שר של אמוריים של מעלה תחת רגליו של משה והדריכו על צוארו:
@78 **ויצא סיחן.** לא שלח בשביל עוג לעזור לו, ללמדך שלא היו צריכים זה לזה:
@79 **ואת בניו.** בנו כתיב, שהיה לו בן גבור כמותו:
@80 **מתם.** אנשים. בבזת סיחון נאמר בזזנו לנו לשון בזה, שהיתה חביבה עליהם ובוזזים איש לו, וכשבאו לבזת עוג כבר היו שבעים ומלאים והיתה בזויה בעיניהם ומקרעין ומשליכין בהמה ובגדים ולא נטלו כי אם כסף וזהב. לכך נאמר (דברים ג, ז) בזונו לנו, לשון בזיון. כך נדרש בספרי בפרשת (במדבר כה, א) וישב ישראל בשטים:
@83 **כל יד נחל יבק.** כל אצל נחל יבוק: **וכל אשר צוה ה' אלהינו.** שלא לכבוש, הנחנו:
@84 **ונפן ונעל.** כל צד צפון הוא עליה:
@85 **אל תירא אתו.** ובסיחון לא הצרך לומר אל תירא אתו, אלא מתירא היה משה שלא תעמוד לו זכות ששמש לאברהם שנאמר (בראשית יד, יג) ויבא הפליט, והוא עוג:
@87 **חבל ארגב.** מתרגמנן בית פלך טרכונא. וראיתי תרגום ירושלמי, במגלת אסתר קורא פלטין טרכונין. למדתי חבל ארגוב הפרכיא, היכל מלך, כלומר שהמלכות נקראת על שמה. וכן את הארגוב דמלכים (מלכים ב' טו, כה) אצל היכל מלך, הרגו פקח בן רמליהו לפקחיה בן מנחם:
@88 **מערי הפרזי.** פרוזות ופתוחות בלא חומה, וכן (זכריה ב, ח) פרזות תשב ירושלם:
@89 **החרם.** לשון הוה [כמו] הלוך וכלות:
@91 **מיד.** מרשות:
@92 **צידנים יקראו לחרמון** וגו' **.** ובמקום אחר הוא אומר (דברים ד, מח) ועד הר שיאון הוא חרמון, הרי לו ארבעה שמות למה הצרכו לכתב, להגיד שבח ארץ ישראל, שהיו ארבע מלכיות מתפארות בכך, זו אומרת על שמי יקרא, וזו אומרת על שמי יקרא: **שניר.** הוא שלג בלשון אשכנז [ שנעע ] ובלשון כנען:
@94 **מיתר הרפאים.** שהרגו אמרפל וחבריו בעשתרות קרנים והוא פלט מן המלחמה שנאמר (בראשית יד, יג) ויבא הפליט זהו עוג: **באמת איש.** באמת עוג:
@95 **ואת הארץ הזאת ירשנו בעת ההוא.** האמורה למעלה, (פסוק ח) מנחל ארנון ועד הר חרמון: **מערער אשר על נחל ארנון.** אינו מחבר לראשו של מקרא אלא לסופו, על נתתי לראובני ולגדי. אבל לענין ירשה עד הר חרמון היה:
@96 **ההוא יקרא ארץ רפאים.** היא אותה שנתתי לאברהם:
@99 **תוך הנחל וגבול.** כל הנחל ועוד מעבר לשפתו, כלומר עד ועד בכלל ויותר מכאן:
@100 **מכנרת.** מעבר הירדן המערבי הוא ונחלת בני גד מעבר הירדן המזרחי, ונפל בגורלם רוחב הירדן כנגדם ועוד מעבר שפתו עד כנרת וזהו שנאמר והירדן וגבול, הירדן ומעבר לו:
@101 **ואצו אתכם.** לבני ראובן ולבני גד היה מדבר: **לפני אחיכם.** הם היו הולכים לפני ישראל למלחמה, לפי שהיו גבורים, ואויבים נופלים לפניהם, שנאמר (דברים לג, כ) וטרף זרוע אף קדקד:
@106 **ואתחנן.** אין חנון בכל מקום אלא לשון מתנת חנם. אף על פי שיש להם לצדיקים לתלות במעשיהם הטובים, אין מבקשים מאת המקום אלא מתנת חנם. לפי שאמר לו (שמות לג, יט) וחנתי את אשר אחן, אמר לו בלשון ואתחנן. דבר אחר זה אחד מעשרה לשונות שנקראת תפלה, כדאיתא בספרי: **בעת ההיא.** לאחר שכבשתי ארץ סיחון ועוג דמיתי שמא התר הנדר: **לאמר.** זה אחד משלשה מקומות שאמר משה לפני המקום איני מניחך עד שתודיעני אם תעשה שאלתי אם לאו:
@107 **ה' אלהים.** רחום בדין: **אתה החלות להראות את עבדך.** פתח להיות עומד ומתפלל, אף על פי שנגזרה גזרה. אמר לו ממך למדתי, שאמרת לי (שמות לב, י) ועתה הניחה לי, וכי תופס הייתי בך, אלא לפתוח פתח, שבי תלוי להתפלל עליהם, כמו כן הייתי סבור לעשות עכשיו: **את גדלך.** זו מדת טובך וכן הוא אומר (במדבר יד, יז) ועתה יגדל נא כח ה': **ואת ידך.** זו ימינך, שהיא פשוטה לכל באי עולם: **החזקה.** שאתה כובש ברחמים את מדת הדין החזקה: **אשר מי אל** וגו' **.** אינך דומה למלך בשר ודם, שיש לו יועצין וסנקתדרין הממחין בידו כשרוצה לעשות חסד ולעבור על מדותיו, אתה אין מי ימחה בידך אם תמחול לי ותבטל גזרתך. ולפי פשוטו אתה החלות להראות את עבדך מלחמת סיחון ועוג, כדכתיב (דברים ב, לא) ראה החלתי תת לפניך, הראני מלחמת שלשים ואחד מלכים:
@108 **אעברה נא.** אין נא אלא לשון בקשה: **ההר הטוב הזה.** זו ירושלים: **והלבנון.** זה בית המקדש:
@109 **ויתעבר ה'.** נתמלא חמה: **למענכם.** בשבילכם, אתם גרמתם לי. וכן הוא אומר (תהלים קו, לב) ויקציפו על מי מריבה וירע למשה בעבורם: **רב לך.** שלא יאמרו הרב כמה קשה והתלמיד כמה סרבן ומפציר. דבר אחר רב לך הרבה מזה שמור לך, רב טוב הצפון לך:
@110 **וראה בעיניך.** בקשת ממני (פסוק כה) ואראה את הארץ הטובה, אני מראה לך את כלה שנאמר (דברים לד, א) ויראהו ה' את כל הארץ:
@111 **וצו את יהושע.** על הטרחות ועל המשאות ועל הריבות: **וחזקהו ואמצהו.** בדבריך, שלא ירך לבו לומר כשם שנענש רבי עליהם כך סופי לענש עליהם, מבטיחו אני כי הוא יעבור והוא ינחיל: **כי הוא יעבר.** אם יעבור לפניהם ינחלו, ואם לאו לא ינחלו. וכן אתה מוצא כששלח מן העם אל העי והוא ישב (יהושע ז, ה) ויכו מהם אנשי העי וגו' (שם ז, י) , וכיון שנפל על פניו אמר לו קום לך. קם לך כתיב, אתה הוא העומד במקומך ומשלח את בני למלחמה, למה זה אתה נפל על פניך, לא כך אמרתי למשה רבך אם הוא עובר, עוברין, ואם לאו, אין עוברין:
@112 **ונשב בגיא** וגו' **.** ונצמדתם לעבודה זרה ואף על פי כן (דברים ד, א) ועתה ישראל שמע אל החקים והכל מחול לך ואני לא זכיתי למחל לי:
@114 **לא תספו.** כגון חמש פרשיות בתפלין, חמשת מינין בלולב, וחמש ציציות, וכן ולא תגרעו:
@118 **ושמרתם.** זו משנה: **ועשיתם.** כמשמעו: **כי הוא חכמתכם ובינתכם** וגו' **.** בזאת תחשבו חכמים ונבונים לעיני העמים:
@120 **חקים ומשפטים צדיקם.** הגונים ומקבלים:
@121 **רק השמר לך** וגו' **פן תשכח את הדברים.** אז כשלא תשכחו אותם ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעותו אותם מתוך שכחה תחשבו שוטים:
@122 **יום אשר עמדת.** מוסב על מקרא שלמעלה ממנו אשר ראו עיניך, יום אשר עמדת בחורב אשר ראיתם את הקולות ואת הלפידים: **ילמדון.** ילפון, לעצמם: **ילמדון.** יאלפון, לאחרים:
@126 **ואתי צוה ה' בעת ההוא ללמד אתכם.** תורה שבעל פה:
@128 **סמל.** צורה:
@131 **ופן תשא עיניך.** להסתכל בדבר ולתת לב לשוב לטעות אחריהם: **אשר חלק** וגו' **לכל העמים.** להאיר להם. דבר אחר לאלהות. לא מנען מלטעות אחריהם, אלא החליקם בדברי הבליהם לטרדם מן העולם. וכן הוא אומר (תהלים לו, ג) כי החליק אליו בעיניו למצא עונו לשנא:
@132 **מכור.** הוא כלי שמזקקים בו את הזהב:
@133 **התאנף.** נתמלא רוגז: **על דבריכם.** על אודותיכם על עסקיכם:
@134 **כי אנכי מת** וגו' **אינני עבר.** מאחר שמת מהיכן יעבר, אלא אף עצמותי אינם עוברין:
@135 **תמונת כל.** תמונת כל דבר: **אשר צוך ה'.** אשר צוך עליו שלא לעשות:
@136 **אל קנא.** מקנא לנקום אנפרנמנ''ט בלע''ז [חמה] מתחרה על רגזו להפרע מעובדי עבודה זרה:
@137 **ונושנתם.** רמז להם שיגלו ממנה לסוף שמונה מאות וחמשים ושתים שנה, כמנין ונושנתם. והוא הקדים והגלם לסוף שמונה מאות וחמשים והקדים שתי שנים לונושנתם, כדי שלא יתקים בהם (פסוק כו) כי אבד תאבדון וזהו שנאמר (דניאל ט, יד) וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו, צדקה עשה עמנו שמהר להביאה שתי שנים לפני זמנה:
@138 **העידתי בכם.** הנני מזמינם להיות עדים שהתריתי בכם:
@140 **ועבדתם שם אלהים.** כתרגומו. משאתם עובדים לעובדיהם כאלו אתם עובדים להם:
@143 **לא ירפך.** מלהחזיק בך בידיו. ולשון לא ירפך לשון לא יפעיל הוא, לא יתן לך רפיון, לא יפריש אותך מאצלו. וכן אחזתיו ולא ארפנו (שה''ש ג ד) , שלא ננקד ארפנו. כל לשון רפיון מוסב על לשון מפעיל ומתפעל, כמו (מלכים ב' ד, כז) הרפה לה, תן לה רפיון (דברים ט, יד) הרף ממני, התרפה ממני:
@144 **לימים ראשונים.** על ימים ראשונים: **ולמקצה השמים.** וגם שאל לכל הברואים אשר מקצה אל קצה זהו פשוטו. ומדרשו, מלמד על קומתו של אדם שהיתה מן הארץ עד השמים והוא השעור עצמו אשר מקצה אל קצה: **הנהיה כדבר הגדול הזה.** ומהו הדבר הגדול, השמע עם וגו' :
@146 **הנסה אלהים.** הכי עשה נסים שום אלוה, **לבא לקחת לו גוי** וגו' **.** כל ההי''ן הללו תמיהות הן, לכך נקודות הן בחט''ף פת''ח, הנהיה, הנשמע, הנסה, השמע: **במסות.** על ידי נסיונות הודיעם גבורותיו, כגון (שמות ח, ה) התפאר עלי, אם אוכל לעשות כן, הרי זה נסיון: **באותות.** בסימנין להאמין שהוא שלוחו של מקום, כגון (שמות ד, ב) מה זה בידך: **ובמופתים.** הם נפלאות שהביא עליהם מכות מפלאות: **ובמלחמה.** בים, שנאמר (שם יד, כה) כי ה' נלחם להם:
@147 **הראת.** כתרגומו אתחזיתא. כשנתן הקדוש ברוך הוא את התורה פתח להם שבעה רקיעים. וכשם שקרע את העליונים כך קרע את התחתונים. וראו שהוא יחידי, לכך נאמר אתה הראת לדעת:
@149 **ותחת כי אהב.** וכל זה תחת אשר אהב: **ויוצאך בפניו.** כאדם המנהיג בנו לפניו שנאמר (שמות יד, יט) ויסע מלאך האלהים ההולך וגו' וילך מאחריהם. דבר אחר ויוצאך בפניו בפני אבותיו, כמו שנאמר (תהלים עח, יב) נגד אבותם עשה פלא. ואל תתמה על שהזכירם בלשון יחיד, שהרי כתבם בלשון יחיד ויבחר בזרעו אחריו:
@150 **ממך מפניך.** סרסהו ודרשהו להוריש מפניך גוים גדולים ועצומים ממך: **כיום הזה.** כאשר אתה רואה היום:
@153 **אז יבדיל.** נתן לב להיות חרד לדבר שיבדילם. ואף על פי שאינן קולטות עד שיבדלו אותן שבארץ כנען, אמר משה, מצוה שאפשר לקימה אקימנה: **בעבר הירדן מזרחה שמש.** באותו עבר שבמזרחו של ירדן: **מזרחה שמש.** לפי שהוא דבוק, נקודה רי''ש בחטף, מזרח של שמש, מקום זריחת השמש:
@156 **וזאת התורה.** זו שהוא עתיד לסדר אחר פרשה זו:
@157 **אלה העדת** וגו' **אשר דבר.** הם הם אשר דבר בצאתם ממצרים חזר ושנאה להם בערבות מואב:
@159 **אשר בעבר הירדן.** שהוא במזרח, שהעבר השני היה במערב:
@164 **לא את אבתינו.** בלבד **כרת ה'** וגו' **כי אתנו:**
@165 **פנים בפנים.** אמר ר' ברכיה, כך אמר משה אל תאמרו אני מטעה אתכם על לא דבר, כדרך שהסרסור עושה בין המוכר ללוקח, הרי המוכר עצמו מדבר עמכם:
@166 **לאמר.** מוסב על (פסוק ד) דבר ה' עמכם בהר מתוך האש לאמר אנכי ה' וגו' ואנכי עומד בין ה' וביניכם:
@168 **על פני.** בכל מקום אשר אני שם וזהו כל העולם. דבר אחר כל זמן שאני קים. עשרת הדברות כבר פרשתים:
@176 **שמור.** ובראשונות הוא אומר (שמות כ) זכור. שניהם בדבור אחד ובתיבה אחת נאמרו ובשמיעה אחת נשמעו: **כאשר צוך.** קודם מתן תורה במרה: **וזכרת כי עבד היית** וגו' **.** על מנת כן פדאך שתהיה לו עבד ותשמר מצותיו:
@177 **כאשר צוך.** אף על כבוד אב ואם נצטוו במרה שנאמר (שמות טו, כה) שם שם לו חק ומשפט:
@178 **ולא תנאף.** אין לשון נאוף אלא באשת איש:
@179 **ולא תתאוה.** לא תרוג אף הוא לשון חמדה, כמו (בראשית ב, ט) נחמד למראה, דמתרגמנן דמרגג למחזי:
@180 **ולא יסף.** מתרגמנן ולא פסק. כי קולו חזק וקים לעולם. דבר אחר, ולא יסף, לא הוסיף להראות באותו פומבי:
@185 **ואת תדבר אלינו.** התשתם את כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כי ראיתי שאינכם חרדים להתקרב אליו מאהבה. וכי לא היה יפה לכם ללמוד מפי הגבורה ולא ללמוד ממני:
@195 **ה' אלהינו ה' אחד.** ה' שהוא אלהינו עתה ולא אלהי האמות, הוא עתיד להיות ה' אחד, שנאמר (צפניה ג, ט) כי אז אהפך אל עמים שפה ברורה לקרא כלם בשם ה' ונאמר (זכריה יד, ט) ביום ההוא יהיה ה' אחד ושמו אחד:
@196 **ואהבת.** עשה דבריו מאהבה. אינו דומה עושה מאהבה לעושה מיראה. העושה אצל רבו מיראה כשהוא מטריח עליו מניחו והולך לו: **בכל לבבך.** בשני יצריך. דבר אחר בכל לבבך, שלא יהיה לבך חלוק על המקום: **ובכל נפשך.** אפלו הוא נוטל את נפשך: **ובכל מאדך.** בכל ממונך יש לך אדם שממונו חביב עליו מגופו לכך נאמר ובכל מאדך. דבר אחר ובכל מאדך בכל מדה ומדה שמודד לך בין במדה טובה בין במדת פרענות וכן דוד הוא אומר (תהלים קטז, יג) כוס ישועות אשא וגו' (שם קטז, יג) צרה ויגון אמצא וגו' :
@197 **והיו הדברים האלה.** ומהו האהבה והיו הדברים האלה, שמתוך כך אתה מכיר בהקדוש ברוך הוא ומדבק בדרכיו: **אשר אנכי מצוך היום.** לא יהיו בעיניך כדיוטגמא ישנה שאין אדם סופנה, אלא כחדשה שהכל רצין לקראתה. דיוטגמא, מצות המלך הבאה במכתב:
@198 **ושננתם.** לשון חדוד הוא, שיהיו מחדדים בפיך, שאם ישאלך אדם דבר לא תהא צריך לגמגם בו, אלא אמור לו מיד: **לבניך.** אלו התלמידים. מצינו בכל מקום שהתלמידים קרויים בנים, שנאמר (דברים יד, א) בנים אתם לה' אלהיכם, ואומר (מלכים ב' ב, ג) בני הנביאים אשר בבית אל, וכן בחזקיהו שלמד תורה לכל ישראל וקראם בנים שנאמר (ד''ה ב' כט, יא) בני עתה אל תשלו. וכשם שהתלמידים קרויים בנים, שנאמר בנים אתם לה' אלהיכם, כך הרב קרוי אב, שנאמר (מלכים ב' ב) אבי אבי רכב ישראל וגו' : **ודברת בם.** שלא יהא עיקר דבורך אלא בם. עשם עיקר ואל תעשם טפל: **ובשכבך.** יכול אפלו שכב בחצי היום, תלמוד לומר ובקומך. יכול אפלו עמד בחצי הלילה, תלמוד לומר בשבתך בביתך ובלכתך בדרך. דרך ארץ דברה תורה, זמן שכיבה וזמן קימה:
@199 **וקשרתם לאות על ידך.** אלו תפלין שבזרוע: **והיו לטטפת בין עיניך.** אלו תפלין שבראש ועל שם מנין פרשיותיהם נקראו טטפת. טט בכתפי שתים, פת באפריקי שתים:
@200 **מזזות ביתך.** מזוזת כתיב, שאין צריך אלא אחת: **ובשעריך.** לרבות שערי חצרות ושערי מדינות ושערי עירות:
@202 **חצובים.** לפי שהיו מקום טרשין וסלעים נופל בו לשון חציבה:
@203 **מבית עבדים.** כתרגומו מבית עבדותא, ממקום שהייתם שם עבדים:
@204 **ובשמו תשבע.** אם יש בך כל המדות הללו, שאתה ירא את שמו ועובד אותו, אז בשמו תשבע, שמתוך שאתה ירא את שמו תהא זהיר בשבועתך, ואם לאו לא תשבע:
@205 **מאלהי העמים אשר סביבותיכם.** הוא הדין לרחוקים, אלא לפי שאתה רואה את סביבותיך תועים אחריהם הצרך להזהיר עליהם ביותר:
@207 **במסה.** כשיצאו ממצרים שנסוהו במים, שנאמר (שמות יז, ז) היש ה' בקרבנו:
@209 **הישר והטוב.** זו פשרה, לפנים משורת הדין:
@210 **כאשר דבר.** והיכן דבר (שמות כג, כז) והמתי את כל העם וגו' :
@211 **כי ישאלך בנך מחר.** יש מחר שהוא אחר זמן:
@217 **ונשל.** לשון השלכה והתזה, וכן (דברים יט, ה) ונשל הברזל:
@218 **לא תחנם.** לא תתן להם חן. אסור לו לאדם לומר כמה נאה גוי זה. דבר אחר אל תתן להם חניה בארץ:
@220 **כי יסיר את בנך מאחרי.** בנו של גוי כשישא את בתך, יסיר את בנך אשר תלד לו בתך מאחרי. למדנו שבן בתך הבא מן הגוי קרוי בנך, אבל בן בנך הבא מן הגויה אינו קרוי בנך אלא בנה, שהרי לא נאמר על בתו לא תקח כי תסיר את בנך מאחרי:
@221 **מזבחתיהם.** של בנין: **מצבותם.** אבן אחת: **ואשירהם.** אילנות שעובדין אותן: **ופסיליהם.** צלמים:
@223 **לא מרבכם.** כפשוטו. ומדרשו לפי שאין אתם מגדילים עצמכם כשאני משפיע לכם טובה לפיכך חשקתי בכם: **כי אתם המעט.** הממעטין עצמכם, כגון אברהם, שאמר (בראשית יח, כז) ואנכי עפר ואפר, וכגון משה ואהרן שאמרו (שמות טז, ח) ונחנו מה, לא כנבוכדנצר שאמר (ישעיה יד, יד) אדמה לעליון, וסנחריב שאמר (שם לו, כ) מי בכל אלהי הארצות, וחירם שאמר (יחזקאל כח, ב) אל אני מושב אלהים ישבתי: **כי אתם המעט.** הרי כי משמש בלשון דהא:
@224 **כי מאהבת ה'.** הרי כי משמש בלשון אלא. לא מרבכם חשק ה' בכם, אלא מאהבת ה' אתכם: **ומשמרו את השבועה.** מחמת שמרו את השבועה:
@225 **לאלף דור.** ולהלן הוא אומר (דברים ה, ט) לאלפים, כאן שהוא סמוך אצל לשומרי מצותיו, העושין מיראה, הוא אומר לאלף, ולהלן שהוא סמוך אצל לאוהביו, העושין מאהבה, ששכרם יותר גדול, הוא אומר לאלפים: **לאוהביו.** אלו העושין מאהבה: **ולשומרי מצותיו.** אלו העושין מיראה:
@226 **ומשלם לשנאיו אל פניו.** בחייו משלם לו גמולו הטוב כדי להאבידו מן העולם הבא:
@227 **היום לעשותם.** ולמחר לעולם הבא לטול שכרם:
@228 **והיה עקב תשמעון.** אם המצות הקלות שאדם דש בעקביו תשמעון: **ושמר ה'** וגו' **.** ישמור לך הבטחתו:
@229 **שגר אלפיך.** ולדי בקרך, שהנקבה משגרת ממעיה: **ועשתרת צאנך.** מנחם פרש אבירי בשן (תהלים כב, יג) , מבחר הצאן. כמו (בראשית יד, ה) עשתרות קרנים, לשון חזק. ואונקלוס תרגם ועדרי ענך. ורבותינו אמרו למה נקרא שמם עשתרות שמעשירות את בעליהן:
@230 **עקר.** שאינו מוליד:
@233 **כי תאמר בלבבך.** על כרחך לשון דלמא הוא, שמא תאמר בלבבך מפני שהם רבים לא אוכל להורישם, אל תאמר כן, לא תירא מהם. ולא יתכן לפרשו באחת משאר לשונות של 'כי', שיפול עליו שוב לא תירא מהם:
@235 **המסות.** נסיונות: **והאותות.** כגון (שמות ד, ג) ויהי לנחש, (שמות ד, ט) והיו לדם ביבשת: **והמופתים.** המכות המפלאות: **והיד החזקה.** זה הדבר: **והזרוע הנטויה.** זה החרב של מכת בכורות:
@236 **הצרעה.** מין שרץ העוף, שהיתה זורקת בהם מרה ומסרסתן ומסמאה את עיניהם בכל מקום שהיו נסתרים שם:
@238 **פן תרבה עליך חית השדה.** והלא אם עושין רצונו של מקום אין מתיראין מן החיה, שנאמר (איוב ה, כג) וחית השדה השלמה לך, אלא גלוי היה לפניו שעתידין לחטוא:
@239 **והמם.** נקוד קמ''ץ כלו, לפי שאין מ''ם אחרונה מן היסוד, והרי הוא כמו והם אותם. אבל (ישעי' כח, כח) והמם גלגל עגלתו, כלו יסוד. לפיכך חציו קמ''ץ וחציו פת''ח, כשאר פעל של שלש אותיות:
@243 **כל המצוה.** כפשוטו. ומדרש אגדה אם התחלת במצוה גמור אותה, שאינה נקראת אלא על שם הגומרה, שנאמר (יהושע כד, לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם, והלא משה לבדו נתעסק בהם להעלותם, אלא לפי שלא הספיק לגמרה וגמרוה ישראל, נקראת על שמם:
@244 **התשמר מצותיו.** שלא תנסהו ולא תהרהר אחריו:
@246 **שמלתך לא בלתה.** ענני כבוד היו שפים בכסותם ומגהצים אותם כמין כלים מגוהצים, ואף קטניהם כמו שהיו גדלים היה גדל לבושן עמהם, כלבוש הזה של חומט שגדל עמו: **לא בצקה.** לא נפחה כבצק, כדרך הולכי יחף שרגליהם נפוחות:
@250 **זית שמן.** זיתים העושים שמן:
@263 **גדלים ועצמים ממך.** אתה עצום, והם עצומים ממך:
@266 **אל תאמר בלבבך.** צדקתי ורשעת הגוים גרמו:
@267 **לא בצדקתך** וגו' **אתה בא לרשת** וגו' **כי ברשעת הגוים.** הרי כי משמש בלשון אלא:
@271 **ואשב בהר.** אין ישיבה אלא לשון עכבה:
@273 **לחת.** לחת כתיב, ששתיהם שוות:
@280 **ואתנפל לפני ה' כראשנה ארבעים יום.** שנאמר (שמות לב, ל) ועתה אעלה אל ה' אולי אכפרה. באותה עליה נתעכבתי ארבעים יום. נמצאו כלים בעשרים ותשעה באב. שהוא עלה בשמונה עשר בתמוז, בו ביום נתרצה הקדוש ברוך הוא לישראל ואמר לו למשה (דברים י, א) פסל לך שני לוחת, עשה עוד ארבעים יום, נמצאו כלים ביום הכפורים. בו ביום נתרצה הקדוש ברוך הוא לישראל בשמחה ואמר לו למשה (במדבר יד, כ) סלחתי כדברך. לכך הקבע למחילה ולסליחה. ומנין שנתרצה ברצון שלם, שנאמר בארבעים של לוחות אחרונות ואנכי עמדתי בהר כימים הראשונים (דברים י, י) , מה הראשונים ברצון אף אחרונים ברצון, אמור מעתה אמצעיים היו בכעס:
@282 **ובאהרן התאנף ה'.** לפי ששמע לכם: **להשמידו.** זה כלוי בנים. וכן הוא אומר (עמוס ב, ט) ואשמיד פריו ממעל: **ואתפלל גם בעד אהרן.** והועילה תפלתי לכפר מחצה, ומתו שנים ונשארו השנים:
@283 **טחון.** לשון הוה כמו (בראשית כו, יג) הלוך וגדל:
@287 **ואתנפל** וגו' **.** אלו הן עצמם האמורים למעלה (פסוק יח) וכפלן כאן, לפי שכתוב כאן סדר תפלתו, שנאמר (פסוק כו) ה' אלהים אל תשחת עמך וגו' :
@292 **בעת ההוא.** לסוף ארבעים יום נתרצה לי ואמר לי פסל לך, ואחר כך ועשית לך ארון עץ, ואני עשיתי ארון תחלה, שכשאבוא והלחות בידי היכן אתנם. ולא זה הוא הארון שעשה בצלאל, שהרי משכן לא נתעסקו בו עד לאחר יום הכפורים, כי ברדתו מן ההר צוה להם על מלאכת המשכן, ובצלאל עשה משכן תחלה ואחר כך ארון וכלים, נמצא זה ארון אחר היה. וזהו שהיה יוצא עמהם למלחמה. ואותו שעשה בצלאל לא יצא למלחמה אלא בימי עלי, ונענשו עליו ונשבה:
@297 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** מה ענין זה לכאן. ועוד, וכי מבארות בני יעקן נסעו למוסרה, והלא ממוסרות באו לבני יעקן, שנאמר (במדבר לג, לא) ויסעו ממוסרות וגו' . ועוד, שם מת אהרן, והלא בהר ההר מת, צא וחשוב ותמצא שמונה מסעות ממוסרה להר ההר. אלא, אף זו מן התוכחה, ועוד זאת עשיתם כשמת אהרן בהר ההר לסוף ארבעים שנה ונסתלקו ענני כבוד, יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים, וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם, עד שהחזירו אתכם בדרך חזרתכם, ומשם חזרתם הגדגדה הוא חור הגדגד:
@298 **ומן הגדגדה** וגו' **.** ובמוסרה עשיתם אבל כבד על מיתתו של אהרן שגרמה לכם זאת, ונדמה לכם כאלו מת שם. וסמך משה תוכחה זו לשבירת הלוחות, לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא, כיום שנשתברו בו הלוחות. ולהודיעך שהקשה לו מה שאמרו (במד' יד, ד) נתנה ראש לפרוש ממנו, כיום שעשו בו את העגל:
@299 **בעת ההוא הבדיל ה'** וגו' **.** מוסב לענין הראשון: **בעת ההוא.** בשנה הראשונה לצאתכם ממצרים וטעיתם בעגל ובני לוי לא טעו, הבדילם המקום מכם. וסמך מקרא זה לחזרת בני יעקן לומר שאף בזו לא טעו בה בני לוי, אלא עמדו באמונתם: **לשאת את ארון.** הלוים: **לעמד לפני ה' לשרתו ולברך בשמו.** הכהנים, והוא נשיאת כפים:
@300 **על כן לא היה ללוי חלק.** לפי שהבדלו לעבודת מזבח ואינן פנויין לחרוש ולזרוע: **ה' הוא נחלתו.** נוטל פרס מזמן מבית המלך:
@301 **ואנכי עמדתי בהר.** לקבל הלוחות האחרונות. ולפי שלא פרש למעלה כמה עמד בהר בעליה אחרונה זו, חזר והתחיל בה: **כימים הראשונים.** של לוחות הראשונות, מה הם ברצון אף אלו ברצון. אבל האמצעיים שעמדתי שם להתפלל עליכם היו בכעס:
@302 **ויאמר ה' אלי** וגו' **.** אף על פי שסרתם מאחריו וטעיתם בעגל, אמר לי (שמות לב, לד) לך נחה את העם:
@303 **ועתה ישראל.** אף על פי שעשיתם כל זאת, עודנו רחמיו וחבתו עליכם, ומכל מה שחטאתם לפניו אינו שואל מכם כי אם ליראה וגו' : **כי אם ליראה** וגו' **.** רבותינו דרשו מכאן, הכל בידי שמים חוץ מיראת שמים:
@304 **לשמר את מצות ה'.** ואף היא לא לחנם, אלא לטוב לך, שתקבלו שכר:
@305 **הן לה' אלהיך.** הכל, ואף על פי כן רק באבותיך חשק ה' מן הכל:
@306 **בכם.** כמו שאתם רואים אתכם חשוקים מכל העמים היום הזה:
@307 **ערלת לבבכם.** אוטם לבבכם וכסויו:
@308 **ואדני האדנים.** לא יוכל שום אדון להציל אתכם מידו: **לא ישא פנים.** אם תפרקו עלו: **ולא יקח שחד.** לפיסו בממון:
@309 **עשה משפט יתום ואלמנה.** הרי גבורה, ואצל גבורתו אתה מוצא ענותנותו: **ואהב גר לתת לו לחם ושמלה.** ודבר חשוב הוא זה, שכל עצמו של יעקב אבינו על זה נתפלל, (בראשית כח, כ) ונתן לי לחם לאכל ובגד ללבש:
@310 **כי גרים הייתם.** מום שבך אל תאמר לחברך:
@311 **את ה' אלהיך תירא.** ותעבוד לו ותדבק בו, ולאחר שיהיו בך כל המדות הללו, אז בשמו תשבע:
@315 **וידעתם היום.** תנו לב לדעת ולהבין ולקבל תוכחתי: **כי לא את בניכם.** אני מדבר עכשיו שיוכלו לומר אנו לא ידענו ולא ראינו בכל זה:
@319 **בקרב כל ישראל.** כל מקום שהיה אחד מהם בורח, הארץ נבקעת מתחתיו ובולעתו, אלו דברי רבי יהודה. אמר לו רבי נחמיה, והלא כבר נאמר (במדבר טז, לב) ותפתח הארץ את פיה, ולא פיותיה. אמר לו, ומה אני מקים בקרב כל ישראל. אמר לו שנעשית הארץ מדרון כמשפך, וכל מקום שהיה אחד מהם [בורח] , היה מתגלגל ובא עד מקום הבקיעה: **ואת כל היקום אשר ברגליהם.** זה ממונו של אדם שמעמידו על רגליו:
@320 **כי עיניכם הראת.** מוסב על מקרא האמור למעלה, (פסוק ב) כי לא את בניכם אשר לא ידעו וגו' כי אם עמכם אשר עיניכם הרואות וגו' :
@323 **לא כארץ מצרים הוא.** אלא טובה המנה. ונאמרה הבטחה זו לישראל ביציאתם ממצרים, שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזו. יכול בגנותה הכתוב מדבר, וכך אמר להם, לא כארץ מצרים היא, אלא רעה המנה, תלמוד לומר (במדבר יג, כב) וחברון שבע שנים נבנתה וגו' , אדם אחד בנאן, וחם בנה צוען למצרים בנו, וחברון לכנען. דרך ארץ אדם בונה את הנאה ואחר כך בונה את הכעור שפסלתו של ראשון, הוא נותן בשני. ובכל מקום, החביב קודם. הא למדת שחברון יפה מצוען, ומצרים משבחת מכל הארצות, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען שבח מצרים היא, שהיתה מקום מלכות, שכן הוא אומר (ישעיה ל, ד) כי היו בצוען שריו. וחברון פסלתה של ארץ ישראל, לכך הקצוה לקבורת מתים, ואף על פי כן היא יפה מצוען. ובמסכת כתבות (קיב, א) דרשו בענין אחר, אפשר אדם בונה בית לבנו הקטן ואחר כך לבנו הגדול, אלא שמבנה על אחד משבעה בצוען: **אשר יצאתם משם.** אפלו ארץ רעמסס [וארץ גושן] אשר ישבתם בה והיא במיטב ארץ מצרים שנאמר (בראשית מז, יא) במיטב הארץ וגו' , אף היא אינה כארץ ישראל: **והשקית ברגלך.** ארץ מצרים היתה צריכה להביא מים מנילוס ברגלך ולהשקותה וצריך אתה לנדד משינתך ולעמול, והנמוך שותה ולא הגבוה, ואתה מעלה המים מן הנמוך לגבוה. אבל זו (פסוק יא) למטר השמים תשתה מים. אתה ישן על מטתך, והקדוש ברוך הוא משקה נמוך וגבוה, גלוי ושאינו גלוי, כאחת: **כגן הירק.** שאין די לו בגשמים ומשקין אותו ברגל ובכתף:
@324 **ארץ הרים ובקעת.** משבח ההר מן המישור, שהמישור, בבית כור אתה זורע כור, אבל ההר בבית כור ממנו חמשת כורין, ארבע מארבע שפועיו, ואחד בראשו: **ובקעת.** הן מישור:
@325 **אשר ה' אלהיך דרש אתה.** והלא אף כל הארצות הוא דורש, שנאמר (איוב לח, כו) להמטיר על ארץ לא איש, אלא כביכול אינו דורש אלא אותה, ועל ידי אותה דרישה שדורשה דורש את כל הארצות עמה: **תמיד עיני ה' אלהיך בה.** לראות מה היא צריכה ולחדש לה גזרות, עתים לטובה עתים לרעה וכו' , כדאיתא בראש השנה (יז, ב) : **מרשית השנה.** מראש השנה נדון מה יהא בסופה:
@326 **והיה אם שמע.** והיה, מוסב על האמור למעלה, (פסוק יא) למטר השמים תשתה מים: **והיה אם שמע תשמעו.** אם שמע בישן תשמעו בחדש. וכן (דברים ח, יט) והיה אם שכח תשכח, אם התחלת לשכח, סופך שתשכח כלה, שכן כתיב במגלה אם תעזבני יום, יומים אעזבך [ במגילת חסידים ] (ספרי מח) : **מצוה אתכם היום.** שיהיו עליכם חדשים, כאלו שמעתם בו ביום: **לאהבה את ה'.** שלא תאמר הרי אני לומד בשביל שאהיה עשיר, בשביל שאקרא רב, בשביל שאקבל שכר. אלא כל מה שתעשו עשו מאהבה וסוף הכבוד לבא: **ולעבדו בכל לבבכם.** עבודה שהיא בלב. וזו היא תפלה, שהתפלה קרויה עבודה, שנאמר (דניאל ו, יז) אלהך די אנת פלח לה בתדירא, וכי יש פלחן בבבל, אלא על שהיה מתפלל, שנאמר (שם ו, יא) וכוין פתיחן לה וגו' . וכן בדוד הוא אומר (תהלים קמא, ב) תכון תפלתי קטרת לפניך: **בכל לבבכם ובכל נפשכם.** והלא כבר הזהיר על כך (דברים ו, ה) בכל לבבך ובכל נפשך, אלא, אזהרה ליחיד אזהרה לצבור:
@327 **ונתתי מטר ארצכם.** עשיתם מה שעליכם, אף אני אעשה מה שעלי: **בעתו.** בלילות שלא יטריחו אתכם. דבר אחר בעתו, בלילי שבתות שהכל מצויין בבתיהם: **יורה.** היא רביעה הנופלת לאחר הזריעה שמרוה את הארץ ואת הזרעים: **ומלקוש.** רביעה היורדת סמוך לקציר למלאות התבואה בקשיה. ולשון מלקוש, דבר המאוחר. כדמתרגמינן (בראשית ל, מב) והיה העטופים ללבן, לקישיא. דבר אחר לכך נקראת מלקוש שיורדת על המלילות ועל הקשין: **ואספת דגנך.** אתה תאספנו אל הבית ולא אויביך. כענין שנאמר (ישעי' סב, ח. ט) אם אתן את דגנך וגו' כי מאספיו יאכלהו, ולא כענין שנאמר (שופטים ו, ג) והיה אם זרע ישראל וגו' :
@328 **ונתתי עשב בשדך.** שלא תצטרך להוליכה למדבריות. דבר אחר שתהיה גוזז תבואתך כל ימות הגשמים ומשליך לפני בהמתך ואתה מונע ידך ממנה שלשים יום קודם לקציר ואינה פוחתת מדגנה: **ואכלת ושבעת.** הרי זו ברכה אחרת, שתהא ברכה מצויה בפת בתוך המעים:
@329 **השמרו לכם.** כיון שתהיו אוכלים ושבעים, השמרו לכם שלא תבעטו, שאין אדם מורד בהקדוש ברוך הוא אלא מתוך שביעה, שנאמר (דברים ח, יב. יד) פן תאכל ושבעת ובקרך וצאנך ירבין, מה הוא אומר אחריו, ורם לבבך ושכחת: **וסרתם.** לפרוש מן התורה ומתוך כך ועבדתם אלהים אחרים. שכיון שאדם פורש מן התורה הולך ומדבק בעבודה זרה. וכן דוד אמר (שמואל א' כו, יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבד וגו' , ומי אמר לו כן, אלא כיון שאני מגרש מלעסוק בתורה, הריני קרוב לעבוד אלהים אחרים: **אלהים אחרים.** שהם אחרים לעובדיהם, צועק אליו ואינו עונהו, נמצא עשוי לו כנכרי:
@330 **את יבולה.** אף מה שאתה מוביל לה, כענין שנאמר (חגי א, ו) זרעתם הרבה והבא מעט: **ואבדתם מהרה.** על כל שאר היסורין אגלה אתכם מן האדמה, שגרמה לכם לחטוא. משל למלך ששלח בנו לבית המשתה והיה יושב ומפקידו [ומפקדו] אל תאכל יותר מצרכך שתבא נקי לביתך, ולא השגיח הבן ההוא. אכל ושתה יותר מצרכו והקיא וטנף את כל בני המסבה. נטלוהו בידיו וברגליו וזרקוהו אחורי פלטרין [פלטין] : **מהרה.** איני נותן לכם ארכא. ואם תאמרו והלא נתנה ארכא לדור המבול, שנאמר (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, דור המבול לא היה להם ממי ללמוד ואתם יש לכם ממי ללמוד:
@331 **ושמתם את דברי.** אף לאחר שתגלו היו מצינים במצות, הניחו תפלין, עשו מזוזות כדי שלא יהיו לכם חדשים כשתחזרו. וכן הוא אומר (ירמיה לא, כ) הציבי לך צינים:
@332 **לדבר בם.** משעה שהבן יודע לדבר, למדהו תורה צוה לנו משה (דברים לג, ד) , שיהא זה למוד דבורו. מכאן אמרו, כשהתינוק מתחיל לדבר, אביו מסיח עמו בלשון הקדש ומלמדו תורה, ואם לא עשה כן הרי הוא כאלו קוברו, שנאמר ולמדתם אתם את בניכם לדבר בם וגו' למען ירבו ימיכם וימי בניכם:
@334 **למען ירבו ימיכם וימי בניכם.** אם עשיתם כן ירבו, ואם לאו לא ירבו, שדברי תורה נדרשין מכלל לאו הן, ומכלל הן לאו: **לתת להם.** לתת לכם אין כתיב כאן, אלא לתת להם, מכאן נמצינו למדים תחית המתים מן התורה:
@335 **שמר תשמרון.** אזהרת שמירות הרבה להזהר בתלמודו שלא ישתכח: **ללכת בכל דרכיו.** הוא רחום ואתה תהא רחום, הוא גומל חסדים ואתה גמול חסדים: **ולדבקה בו.** אפשר לומר כן, והלא אש אוכלה הוא, אלא הדבק בתלמידים ובחכמים ומעלה אני עליך כאלו נדבקת בו:
@336 **והוריש ה'.** עשיתם מה שעליכם אף אני אעשה מה שעלי: **ועצמים מכם.** אתם גבורים, והם גבורים מכם, שאם לא שישראל גבורים, מה השבח שמשבח את האמוריים לומר ועצמים מכם, אלא אתם גבורים משאר אמות והם גבורים מכם:
@338 **לא יתיצב איש** וגו' **.** אין לי אלא איש, אמה ומשפחה ואשה בכשפיה מנין, תלמוד לומר לא יתיצב מכל מקום. אם כן מה תלמוד לומר איש, אפלו כעוג מלך הבשן: **פחדכם ומוראכם.** והלא פחד הוא מורא, אלא פחדכם על הקרובים ומוראכם על הרחוקים. פחד לשון בעיתת פתאום. מורא לשון דאגה מימים רבים: **כאשר דבר לכם.** והיכן דבר (שמות כג, כז) את אימתי אשלח לפניך וגו' :
@339 **ראה אנכי נתן לפניכם היום ברכה וקללה.** האמורות בהר גרזים ובהר עיבל:
@340 **את הברכה.** על מנת אשר תשמעו:
@341 **מן הדרך אשר אנכי מצוה אתכם היום ללכת** וגו' **.** הא למדת שכל העובד עבודה זרה הרי הוא סר מכל הדרך שנצטוו ישראל. מכאן אמרו כל המודה בעבודה זרה ככופר בכל התורה כלה:
@342 **ונתתה את הברכה.** כתרגומו ית מברכיא, את המברכים: **על הר גרזים.** כלפי הר גרזים, הופכין פניהם ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' . כל הארורים שבפרשה אמרו תחלה בלשון ברוך, ואחר כך הפכו פניהם כלפי הר עיבל ופתחו בקללה:
@343 **הלא המה.** נתן בהם סימן: **אחרי.** אחרי העברת הירדן הרבה והלאה למרחוק. וזהו לשון אחרי. כל מקום שנאמר אחרי, מפלג הוא: **דרך מבוא השמש.** להלן מן הירדן לצד מערב. וטעם המקרא מוכיח שהם שני דברים, שננקדו בשני טעמים, אחרי, נקוד בפשטא, ודרך, נקוד במשפל והוא דגש, ואם היה אחרי דרך, דבור אחד, היה נקוד אחרי, במשרת, בשופר הפוך, ודרך, בפשטא ורפה: **מול הגלגל.** רחוק מן הגלגל: **אלוני מרה.** שכם הוא, שנאמר (בראשית יב, ו) עד מקום שכם עד אלון מרה:
@344 **כי אתם עברים את הירדן** וגו' **.** נסים של ירדן יהיו סימן בידכם שתבואו ותירשו את הארץ:
@347 **אבד תאבדון.** אבד ואחר כך תאבדון מכאן לעוקר עבודה זרה שצריך לשרש אחריה: **את כל המקומות אשר עבדו שם** וגו' **.** ומה תאבדון מהם, את אלהיהם אשר על ההרים:
@348 **מזבח.** של אבנים הרבה: **מצבה.** של אבן אחת, והוא בימוס ששנויה במשנה (ע''ז מז, ב) אבן שחצבה מתחלתה לבימוס: **אשרה.** אילן הנעבד: **ואבדתם את שמם.** לכנות להם שם לגנאי, בית גליא קורין לה בית כריא, עין כל עין קוץ:
@349 **לא תעשון כן.** להקטיר לשמים בכל מקום (פסוק ה) , כי אם במקום אשר יבחר. דבר אחר ונתצתם את מזבחתם ואבדתם את שמם לא תעשון כן, אזהרה למוחק את השם ולנותץ אבן מן המזבח או מן העזרה. אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין את המזבחות, אלא שלא תעשו כמעשיהם, ויגרמו עונותיכם למקדש אבותיכם שיחרב:
@350 **לשכנו תדרשו.** זה משכן שילה:
@351 **וזבחיכם.** שלמים של חובה: **מעשרתיכם.** מעשר בהמה ומעשר שני לאכול לפנים מן החומה: **תרומת ידכם.** אלו הבכורים, שנאמר בהם (דברים כו, ד) ולקח הכהן הטנא מידך: **ובכורות בקרכם.** לתתם לכהן ויקריבם שם:
@352 **אשר ברכך ה'.** לפי הברכה הבא:
@353 **לא תעשון ככל אשר אנחנו עשים** וגו' **.** מוסב למעלה (דברים יא, לא) על כי אתם עברים את הירדן וגו' כשתעברו את הירדן, מיד מתרים אתם להקריב בבמה, כל ארבע עשרה שנה של כבוש וחלוק, ובבמה לא תקריבו כל מה שאתם מקריבים פה היום במשכן, שהוא עמכם ונמשח והוא כשר להקריב בו חטאות ואשמות נדרים ונדבות, אבל בבמה אין קרב אלא הנדר והנדב. וזהו איש כל הישר בעיניו, נדרים ונדבות שאתם מתנדבים על ידי שיישר בעיניכם להביאם ולא על ידי חובה, אותם תקריבו בבמה:
@354 **כי לא באתם.** כל אותן ארבע עשרה שנה: **אל המנוחה.** זו שילה: **הנחלה.** זו ירושלים: **עד עתה.** כמו עדין:
@355 **ועברתם את הירדן וישבתם בארץ.** משתחלקוה ויהא כל אחד מכיר את חלקו ואת שבטו: **והניח לכם.** לאחר כבוש וחלוק ומנוחה (שופטים ג, א) מן הגוים אשר הניח ה' לנסות בם את ישראל. ואין זאת אלא בימי דוד, אז:
@356 **והיה המקום** וגו' **.** בנו לכם בית הבחירה בירושלים. וכן הוא אומר בדוד (שמואל ב' ז, א. ב) ויהי כי ישב המלך בביתו, וה' הניח לו מסביב מכל אויביו. ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים, וארון האלהים ישב בתוך היריעה: **שמה תביאו** וגו' **.** למעלה אמרו (פסוק ו) לענין שילה וכאן אמור לענין ירושלים, ולכך חלקם הכתוב, לתן התר בין זו לזו, משחרבה שילה ובאו לנוב, וחרבה נוב ובאו לגבעון, היו הבמות מתרות עד שבאו לירושלים: **מבחר נדריכם.** מלמד שיביאו מן המבחר:
@358 **השמר לך.** לתן לא תעשה על הדבר. **בכל מקום אשר תראה.** אשר יעלה בלבך, אבל אתה מקריב על פי נביא, כגון אליהו בהר הכרמל:
@359 **באחד שבטיך.** בחלקו של בנימין. ולמעלה הוא אומר (פסוק ה) מכל שבטיכם. הא כיצד, כשקנה דוד את הגרן מארונה היבוסי גבה הזהב מכל השבטים, ומכל מקום הגרן בחלקו של בנימין היה:
@360 **רק בכל אות נפשך.** במה הכתוב מדבר, אם בבשר תאוה להתירה להם בלא הקרבת אמורים, הרי הוא אומר במקום אחר (פסוק כ) כי ירחיב ה' אלהיך את גבולך וגו' ואמרת אכלה בשר וגו', במה זה מדבר, בקדשים שנפל בהם מום, שיפדו ויאכלו בכל מקום. יכול יפדו על מום עובר, תלמוד לומר רק: **תזבח ואכלת.** אין לך בהם התר גזה וחלב, אלא אכילה על ידי זביחה: **הטמא והטהור.** לפי שבאו מכח קדשים, שנאמר בהם (ויקרא ז, יט) והבשר אשר יגע בכל טמא לא יאכל, הצרך להתיר בו, שטמא וטהור אוכלין בקערה אחת: **כצבי וכאיל.** שאין קרבן בא מהם: **כצבי וכאיל.** לפטרן מן הזרוע והלחיים והקבה:
@361 **רק הדם לא תאכלו.** אף על פי שאמרתי שאין לך בו זריקת דם במזבח, לא תאכלנו: **תשפכנו כמים.** לומר לך שאין צריך כסוי. דבר אחר הרי הוא כמים להכשיר את הזרעים:
@362 **לא תוכל.** בא הכתוב לתן לא תעשה על הדבר. רבי יהושע בן קרחה אומר יכול אתה, אבל אינך רשאי, כיוצא בו (יהושע טו, סג) ואת היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם, יכולים היו, אלא שאינן רשאין, לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה. ולא יבוסים היו אלא חתיים היו, אלא על שם העיר ששמה יבוס [נקראים יבוסים] . כך מפורש בפרקי דרבי אליעזר. והוא שנאמר (שמואל ב' ה, ו) כי אם הסירך העורים והפסחים, צלמים שכתבו עליהם את השבועה: **ובכרת בקרך.** אזהרה לכהנים: **ותרומת ידך.** אלו הבכורים:
@363 **לפני ה'.** לפנים מן החומה: **והלוי אשר בשעריך.** אם אין לך לתת לו מחלקו, כגון מעשר ראשון, תן לו מעשר עני. אין לך מעשר עני, הזמינהו על שלמיך:
@364 **השמר לך.** לתן לא תעשה על הדבר: **על אדמתך.** אבל בגולה אינך מזהר עליו יותר מעניי ישראל:
@365 **כי ירחיב** וגו' **.** למדה תורה דרך ארץ, שלא יתאוה אדם לאכול בשר, אלא מתוך רחבת ידים ועושר: **בכל אות נפשך** וגו' **.** אבל במדבר נאסר להם בשר חלין, אלא אם כן מקדישה ומקריבה שלמים:
@366 **כי ירחק ממך המקום.** ולא תוכל לבוא ולעשות שלמים בכל יום כמו עכשיו שהמשכן הולך עמכם: **וזבחת** וגו' **כאשר צויתך.** למדנו שיש צווי בזביחה היאך ישחוט, והן הלכות שחיטה שנאמרו למשה בסיני:
@367 **אך כאשר יאכל את הצבי** וגו' **.** אינך מזהר לאכלן בטהרה. אי מה צבי ואיל חלבן מתר, אף חלין חלבן מתר, תלמוד לומר אך:
@368 **רק חזק לבלתי אכל הדם.** ממה שנאמר חזק אתה למד שהיו שטופים בדם לאכלו, לפיכך הצרך לומר חזק, דברי רבי יהודה. רבי שמעון בן עזאי אומר, לא בא הכתוב אלא להזהירך וללמדך עד כמה אתה צריך להתחזק במצות, אם הדם, שהוא קל להשמר ממנו, שאין אדם מתאוה לו, הצרך לחזקך באזהרתו, קל וחמר לשאר מצות: **ולא תאכל הנפש עם הבשר.** אזהרה לאבר מן החי:
@369 **לא תאכלנו.** אזהרה לדם התמצית:
@370 **לא תאכלנו.** אזהרה לדם האיברים: **למען ייטב לך** וגו' **.** צא ולמד מתן שכרן של מצות, אם הדם שנפשו של אדם קצה ממנו, הפורש ממנו זוכה לו ולבניו אחריו, קל וחמר לגזל ועריות שנפשו של אדם מתאוה להם:
@371 **רק קדשיך.** אף על פי שאתה מתר לשחוט חלין, לא התרתי לך לשחוט את הקדשים ולאכלן בשעריך בלא הקרבה, אלא הביאם לבית הבחירה:
@372 **ועשית עלתיך.** אם עולות הם תן הבשר והדם על גבי המזבח, ואם זבחי שלמים הם, דם זבחיך ישפך על המזבח תחלה ואחר כך והבשר תאכל. ועוד דרשו רבותינו (פסוק כו) , רק קדשיך בא ללמד על הקדשים שבחוצה לארץ וללמד על התמורות ועל ולדות קדשים שיקריבו:
@373 **שמר.** זו משנה שאתה צריך לשמרה בבטנך שלא תשכח. כענין שנאמר (משלי כב) כי נעים כי תשמרם בבטנך, ואם שנית אפשר שתשמע ותקיים, הא כל שאינו בכלל משנה אינו בכלל מעשה: **את כל הדברים.** שתהא חביבה עליך מצוה קלה כמצוה חמורה: **הטוב.** בעיני השמים: **והישר.** בעיני אדם:
@375 **פן תנקש.** אנקלוס תרגם לשון מוקש. ואני אומר שלא חש לדקדק בלשון, שלא מצינו נו''ן בלשון יוקש ואפלו ליסוד הנופל ממנו, אבל בלשון טרוף וקשקוש מצינו נו''ן (דניאל ה, ו) וארכבתה דא לדא נקשן. ואף זה אני אומר, פן תנקש אחריהם פן תטרף אחריהם להיות כרוך אחר מעשיהם, וכן (תהלים קט, יא) ינקש נושה לכל אשר לו, מקלל את הרשע להיות עליו נושים רבים והיו מחזירין ומנקשין אחר ממונו: **אחרי השמדם מפניך.** אחר שתראה שאשמידם מפניך, יש לך לתת לב מפני מה נשמדו אלו, מפני מעשים מקלקלים שבידיהם, אף אתה לא תעשה כן שלא יבואו אחרים וישמידוך: **איכה יעבדו.** לפי שלא ענש על עבודת אלילים אלא על זבוח וקטור ונסוך והשתחואה, כמו שכתוב (שמות כב, יט) בלתי לה' לבדו, דברים הנעשים לגבוה, בא ולמדך כאן, שאם דרכה של עבודה זרה לעבדה בדבר אחר, כגון פוער לפעור, וזורק אבן למרקוליס, זו היא עבודתה וחיב. אבל זבוח וקטור ונסוך והשתחואה, אפלו שלא כדרכה חיב:
@376 **כי גם את בניהם.** גם, לרבות את אבותיהם ואמותיהם. אמר ר' עקיבא אני ראיתי נכרי שכפתו לאביו לפני כלבו ואכלו:
@377 **את כל הדבר.** קלה כחמורה: **תשמרו לעשות.** לתן לא תעשה על עשה האמורים בפרשה. שכל השמר לשון לא תעשה הוא, אלא שאין לוקין על השמר של עשה: **לא תסף עליו.** חמשה טוטפות בתפלין, חמשה מינין בלולב, ארבע ברכות בברכת כהנים:
@378 **ונתן אליך אות.** בשמים, כענין שנאמר בגדעון (שופטים ו, יז) ועשית לי אות, ואומר (שם ו, לט) יהי נא חרב אל הגזה וגו' : **או מופת.** בארץ. [ ס''א אות . בשמים , דכתיב (בראשית א, יד) והיו לאתת ולמועדים או מופת . בארץ . דכתיב (שופטים שם) אם טל יהיה על הגזה לבדה ועל כל הארץ חרב ] אף על פי כן לא תשמע לו. ואם תאמר מפני מה נותן לו הקדוש ברוך הוא ממשלה לעשות אות, כי מנסה ה' אלהיכם אתכם:
@381 **ואת מצותיו תשמרו.** תורת משה: **ובקולו תשמעו.** בקול הנביאים: **ואתו תעבדו.** במקדשו: **ובו תדבקון.** הדבק בדרכיו. גמול חסדים, קבור מתים, בקר חולים, כמו שעשה הקדוש ברוך הוא:
@382 **סרה.** דבר המוסר מן העולם שלא היה ולא נברא ולא צויתיו לדבר כן, דישטולוד''א בלע''ז : **והפדך מבית עבדים.** אפלו אין לו עליך אלא שפדאך, דיו:
@383 **כי יסיתך.** אין הסתה אלא גרוי, שנאמר (שמואל א' כו, יט) אם ה' הסיתך בי, אמיטר''א בלע''ז , שמשיאו לעשות כן: **אחיך.** מאב: **בן אמך.** מאם: **חיקך.** השוכבת בחיקך ומחקה בך אפיקייד''א בלע''ז , וכן (יחזקאל מג, יד) ומחיק הארץ, מיסוד התקוע בארץ: **אשר כנפשך.** זה אביך. פרש לך הכתוב את החביבין לך, קל וחמר לאחרים: **בסתר.** דבר הכתוב בהוה, שאין דברי מסית אלא בסתר. וכן שלמה הוא אומר (משלי ז, ט) בנשף בערב יום באישון לילה ואפלה: **אשר לא ידעת אתה ואבתיך.** דבר זה גנאי גדול הוא לך שאף האמות אין מניחין מה שמסרו להם אבותיהם, וזה אומר לך עזוב מה שמסרו לך אבתיך:
@384 **הקרבים אליך או הרחקים.** למה פרט קרובים ורחוקים, אלא כך אמר הכתוב, מטיבן של קרובים אתה למד טיבן של רחוקים, כשם שאין ממש בקרובים כך אין ממש ברחוקים: **מקצה הארץ.** זו חמה ולבנה וצבא השמים שהן מהלכין מסוף העולם ועד סופו:
@385 **לא תאבה לו.** לא תהא תאב לו. לא תאהבנו. לפי שנאמר (ויקרא יט, יח) ואהבת לרעך כמוך, את זה לא תאהב: **ולא תשמע אליו.** בהתחננו על נפשו למחול לו, לפי שנאמר (שמות כג, ה) עזב תעזב עמו, לזה לא תעזוב: **ולא תחוס עינך עליו.** לפי שנאמר (ויקרא יט, טז) לא תעמד על דם רעך, על זה לא תחוס: **ולא תחמול.** לא תהפך בזכותו: **ולא תכסה עליו.** אם אתה יודע לו חובה אינך רשאי לשתוק:
@386 **כי הרג תהרגנו.** אם יצא מבית דין זכאי, החזירהו לחובה. יצא מבית דין חיב, אל תחזירהו לזכות: **ידך תהיה בו בראשונה.** מצוה ביד הנסת להמיתו. לא מת בידו, ימות ביד אחרים, שנאמר ויד כל העם וגו' :
@389 **לשבת שם.** פרט לירושלים שלא נתנה לדירה: **כי תשמע** וגו' **לאמר.** אומרים כן, יצאו וגו' :
@390 **בני בליעל.** בלי עול. שפרקו עלו של מקום: **אנשים.** ולא נשים: **ישבי עירם.** ולא יושבי עיר אחרת. מכאן אמרו אין נעשית עיר הנדחת עד שידיחוה אנשים, ועד שיהיו מדיחיה מתוכה:
@391 **ודרשת וחקרת ושאלת היטב.** מכאן למדו שבע חקירות מרבוי המקרא. כאן יש שלש דרישה וחקירה והיטב. ושאלת, אינו מן המנין, וממנו למדו בדיקות. ובמקום אחר הוא אומר (דברים יט, יח) ודרשו השופטים היטב. ועוד במקום אחר הוא אומר (שם יז, ד) ודרשת היטב. ולמדו היטב היטב לגזרה שוה, לתן האמור של זה בזה:
@392 **הכה תכה.** אם אינך יכול להמיתם במיתה הכתובה בהם, המיתם באחרת:
@393 **לה' אלהיך.** לשמו ובשבילו:
@394 **למען ישוב ה' מחרון אפו.** שכל זמן שעבודה זרה בעולם, חרון אף בעולם:
@396 **לא תתגדדו.** לא תתנו גדידה ושרט בבשרכם על מת כדרך שהאמוריים עושין, לפי שאתם בניו של מקום ואתם ראויין להיות נאים ולא גדודים ומקורחים: **בין עיניכם.** אצל הפדחת. ובמקום אחר הוא אומר (ויקרא כא, ה) לא יקרחו קרחה בראשם, לעשות כל הראש כבין העינים:
@397 **כי עם קדוש אתה.** קדשת עצמך מאבותיך. ועוד, ובך בחר ה':
@398 **כל תועבה.** כל שתעבתי לך, שאם צרם אזן בכור כדי לשחטו במדינה, הרי דבר שתעבתי לך כל מום לא יהיה בו, ובא ולמד כאן שלא ישחט ויאכל על אותו המום. בשל בשר בחלב הרי דבר שתעבתי לך, והזהיר כאן על אכילתו:
@400 **זאת הבהמה** וגו'' **איל וצבי ויחמור.** למדנו שהחיה בכלל בהמה, ולמדנו שבהמה וחיה טמאה מרבה מן הטהורה, שבכל מקום פורט את המועט: **ואקו.** מתרגם יעלא (איוב לט, א) יעלי סלע הוא אשטנבו''ק : **ותאו.** תורבלא, שור היער. באלא יער, בלשון ארמי:
@401 **מפרסת.** סדוקה כתרגומו: **פרסה.** פלנט''א [כף רגל] : **ושסעת.** חלוקה בשתי צפרנים. שיש סדוקה ואינה חלוקה בצפרנים והיא טמאה: **בבהמה.** משמע מה שנמצא בבהמה אכל, מכאן אמרו שהשליל נתר בשחיטת אמו:
@402 **השסועה.** בריה היא שיש לה שני גבין ושתי שדראות. אמרו רבותינו למה נשנו, בבהמות מפני השסועה, ובעופות מפני הראה, שלא נאמרו בתורת כהנים:
@403 **ובנבלתם לא תגעו.** רבותינו פרשו, ברגל. שאדם חיב לטהר את עצמו ברגל. יכול יהיו מזהרים בכל השנה, תלמוד לומר (ויקרא כא, א) אמור אל הכהנים וגו' ומה טמאת המת חמורה, כהנים מזהרים ואין ישראל מזהרים, טמאת נבלה קלה לא כל שכן:
@406 **כל צפור טהורה תאכלו.** להתיר משלחת שבמצורע:
@407 **וזה אשר לא תאכלו מהם.** לאסר את השחוטה:
@408 **והראה ואת האיה** וגו' **.** היא ראה היא איה היא דיה. ולמה נקרא שמה ראה, שרואה ביותר. ולמה הזהיר בכל שמותיה, שלא לתן פתחון פה לבעל דין לחלוק, שלא יהא האוסרה קורא אותה ראה והבא להתיר אומר, זו דיה שמה או איה שמה, וזו לא אסר הכתוב. ובעופות פרט לך הטמאים, ללמד שהעופות הטהורים מרבים על הטמאים, לפיכך פרט את המועט:
@411 **והתנשמת.** קלב''א שורי''ץ :
@412 **שלך.** השולה דגים מן הים:
@413 **דוכיפת.** הוא תרנגול הבר ובלע''ז הרופ''א וכרבלתו כפולה:
@414 **שרץ העוף.** הם הנמוכים הרוחשים על הארץ, כגון זבובין וצרעים וחגבים טמאים, הם קרויים שרץ:
@415 **כל עוף טהור תאכלו.** ולא את הטמא. בא לתן עשה על לא תעשה. וכן בבהמה, אותה תאכלו ולא בהמה טמאה, לאו הבא מכלל עשה, עשה, לעבור עליהם בעשה ולא תעשה:
@416 **לגר אשר בשעריך.** גר תושב שקבל עליו שלא לעבוד עבודה זרה ואוכל נבלות: **כי עם קדוש אתה לה'.** קדש את עצמך במתר לך. דברים המתרים ואחרים נוהגים בהם אסור, אל תתירם בפניהם: **לא תבשל גדי.** שלש פעמים. פרט לחיה ולעופות ולבהמה טמאה: **לא תבשל גדי** וגו':
@417 **עשר תעשר.** מה ענין זה אצל זה, אמר להם הקדוש ברוך הוא לישראל, לא תגרמו לי לבשל גדיים של תבואה עד שהן במעי אמותיהן, שאם אין אתם מעשרים מעשרות כראוי, כשהוא סמוך להתבשל אני מוציא רוח קדים והיא משדפתן. שנאמר (מלכים ב' יט, כא) ושדפה לפני קמה, וכן לענין בכורים: **שנה שנה.** מכאן שאין מעשרין מן החדש על הישן:
@418 **ואכלת** וגו' **.** זה מעשר שני. שכבר למדנו לתן מעשר ראשון ללוים, שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל וגו' , ונתן להם רשות לאכלו בכל מקום, שנאמר (שם יח, לא) ואכלתם אתו בכל מקום, על כרחך זה מעשר אחר הוא:
@419 **כי יברכך.** שתהא התבואה מרבה לשאת:
@421 **בכל אשר תאוה נפשך.** כלל: **בבקר ובצאן וביין ובשכר.** פרט: **ובכל אשר תשאלך נפשך.** חזר וכלל. מה הפרט מפורש ולד ולדות הארץ וראוי למאכל אדם וכו' :
@422 **והלוי** וגו' **לא תעזבנו.** מלתן לו מעשר ראשון: **כי אין לו חלק ונחלה עמך.** יצאו לקט שכחה ופאה והפקר, שאף הוא יש לו חלק עמך בהן כמוך, ואינן חיבין במעשר:
@423 **מקצה שלש שנים.** בא ולמד שאם השהה מעשרותיו של שנה ראשונה ושניה לשמטה, שיבערם מן הבית בשלישית:
@424 **ובא הלוי.** ויטול מעשר ראשון: **והגר והיתום.** ויטלו מעשר שני, שהוא של עני של שנה זו, ולא תאכלנו אתה בירושלים כדרך שנזקקת לאכול מעשר שני של שתי שנים: **ואכלו ושבעו.** תן להם כדי שביעה. מכאן אמרו אין פוחתין לעני בגורן וכו' . ואתה הולך לירושלים למעשר של שנה ראשונה ושניה שהשהית ומתודה בערתי הקדש מן הבית (דברים כו, יג) , כמו שמפורש ב''כי תכלה לעשר'' (שם כו, יב) :
@425 **מקץ שבע שנים.** יכול שבע שנים לכל מלוה ומלוה, תלמוד לומר (פסוק ט) קרבה שנת השבע. ואם אתה אומר שבע שנים לכל מלוה ומלוה להלואת כל אחד ואחד, היאך היא קרבה, הא למדת שבע שנים למנין השמטות:
@426 **שמוט כל בעל משה ידו.** שמוט את ידו של כל בעל משה:
@427 **את הנכרי תגש.** זו מצות עשה:
@428 **אפס כי לא יהיה בך אביון.** ולהלן הוא אומר (פסוק יא) כי לא יחדל אביון, אלא בזמן שאתם עושים רצונו של מקום, אביונים באחרים ולא בכם, וכשאין אתם עושים רצונו של מקום אביונים בכם: **אביון.** דל מעני, ולשון אביון שהוא תאב לכל דבר:
@429 **רק אם שמוע תשמע.** אז לא יהיה בך אביון: **שמוע תשמע.** שמע קמעא משמיעין אותו הרבה:
@430 **כאשר דבר לך.** והיכן דבר, ברוך אתה בעיר: (דברים כח, ג) **והעבטת.** כל לשון הלואה כשנופל על המלוה, נופל בלשון מפעיל. כגון והלוית, והעבטת. ואם היה אומר ועבטת היה נופל על הלוה, כמו ולוית: **והעבטת גוים.** יכול שתהא לוה מזה ומלוה לזה, תלמוד לומר ואתה לא תעבט: **ומשלת בגוים רבים.** יכול גוים אחרים מושלים עליך, תלמוד לומר ובך לא ימשלו:
@431 **כי יהיה בך אביון.** התאב תאב קודם: **מאחד אחיך.** אחיך מאביך, קודם לאחיך מאמך: **שעריך.** עניי עירך קודמים לעניי עיר אחרת: **לא תאמץ.** יש לך אדם שמצטער אם יתן אם לא יתן, לכך נאמר לא תאמץ. יש לך אדם שפושט את ידו וקופצה, לכך נאמר ולא תקפץ: **מאחיך האביון.** אם לא תתן לו, סופך להיות אחיו בעניות [של אביון] :
@432 **פתח תפתח.** אפלו כמה פעמים: **כי פתח תפתח.** הרי כי משמש בלשון אלא: **והעבט תעביטנו.** אם לא רצה במתנה, תן לו בהלואה: **די מחסרו.** ואי אתה מצוה להעשירו: **אשר יחסר לו.** אפלו סוס לרכוב עליו ועבד לרוץ לפניו: **לו.** זו אשה. וכן הוא אומר (בראשית ב, יח) אעשה לו עזר כנגדו:
@433 **וקרא עליך.** יכול מצוה, תלמוד לומר (דברים כד, טו) ולא יקרא: **והיה בך חטא.** מכל מקום, אפלו לא יקרא. אם כן למה נאמר וקרא עליך, ממהר אני לפרע על ידי הקורא יותר ממי שאינו קורא:
@434 **נתון תתן לו.** אפלו מאה פעמים: **לו.** בינו ובינך: **כי בגלל הדבר.** אפלו אמרת לתן, אתה נוטל שכר האמירה עם שכר המעשה:
@435 **על כן.** מפני כן: **לאמר.** עצה לטובתך אני משיאך: **לאחיך לעניך.** לאיזה אח, לעני: **לעניך.** ביו''ד אחד, לשון עני אחד הוא. אבל ענייך בשני יודי''ן, שני עניים:
@436 **כי ימכר לך.** על ידי אחרים, שמכרוהו בית דין בגנבתו הכתוב מדבר. והרי כבר נאמר (שמות כא, ב) כי תקנה עבד עברי, ובמכרוהו בית דין הכתוב מדבר. אלא מפני שני דברים שנתחדשו כאן. אחד שכתוב או העבריה, אף היא תצא בשש. ולא שמכרוה בית דין, שאין האשה נמכרת בגנבתה, שנאמר בגנבתו ולא בגנבתה, אלא בקטנה שמכרה אביה, ולמד כאן שאם יצאו שש שנים קודם שתביא סימנין תצא. ועוד חדש כאן (פסוק יד) העניק תעניק:
@438 **העניק תעניק.** לשון עדי בגובה ובמראית העין, שיהא נכר שהטיבות לו. ויש מפרשים לשון הטענה על צוארו: **מצאנך ומגרנך ומיקבך.** יכול אין לי אלא אלו בלבד, תלמוד לומר אשר ברכך, מכל מה שברכך בוראך. ולמה נאמרו אלו, מה אלו מיוחדים שהם בכלל ברכה אף כל שהוא בכלל ברכה, יצאו פרדות. ולמדו רבותינו במסכת קדושין (יז, א) בגזרה שוה כמה נותן לו מכל מין ומין:
@439 **וזכרת כי עבד היית.** והענקתי ושניתי לך מבזת מצרים ובזת הים, אף אתה הענק ושנה לו:
@441 **עבד עולם.** יכול כמשמעו, תלמוד לומר (ויקרא כה, י) ושבתם איש אל אחזתו ואיש אל משפחתו תשובו, הא למדת שאין זה, אלא עולמו של יובל: **ואף לאמתך תעשה כן.** הענק לה. יכול אף לרציעה השוה הכתוב אותה, תלמוד לומר (שמות כא, ה) ואם אמר יאמר העבד, עבד נרצע, ואין אמה נרצעת:
@442 **כי משנה שכר שכיר.** מכאן אמרו עבד עברי עובד בין ביום ובין בלילה. וזהו כפלים שבעבודת שכירי יום. ומהו עבודתו בלילה, רבו מוסר לו שפחה כנענית והולדות לאדון:
@443 **כל הבכור** וגו' **תקדיש.** ובמקום אחר הוא אומר לא יקדיש, שנאמר (ויקרא כז, כו) אך בכור אשר יבכר לה' וגו' , הא כיצד, אינו מקדישו לקרבן אחר, וכאן למד שמצוה לומר הרי אתה קדוש לבכורה. דבר אחר אי אפשר לומר תקדיש שכבר נאמר לא יקדיש, ואי אפשר לומר לא יקדיש שהרי כבר נאמר תקדיש, הא כיצד, מקדישו אתה הקדש עלוי, ונותן להקדש כפי טובת הנאה שבו: **לא תעבד בבכור שורך ולא תגז** וגו' **.** אף החלוף למדו רבותינו שאסור, אלא שדבר הכתוב בהוה:
@444 **לפני ה' אלהיך תאכלנו.** לכהן הוא אומר, שכבר מצינו שהוא ממתנות כהנה אחד תם ואחד בעל מום, שנאמר (במדבר יח, יח) ובשרם יהיה לך וגו' : **שנה בשנה.** מכאן שאין משהין אותו יותר על שנתו. יכול יהא פסול משעברה שנתו, כבר הקש למעשר, שנאמר (לעיל יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך ובכרת בקרך וצאנך, מה מעשר שני אינו נפסל משנה לחברתה, אף בכור אינו נפסל, אלא שמצוה תוך שנתו: **שנה בשנה.** אם שחטו בסוף שנתו, אוכלו אותו היום ויום אחד משנה אחרת. למד שנאכל לשני ימים ולילה אחד:
@445 **מום.** כלל: **פסח או עור.** פרט: **כל מום רע.** חזר וכלל. מה הפרט מפורש מום הגלוי ואינו חוזר, אף כל מום שבגלוי ואינו חוזר:
@447 **רק את דמו לא תאכל.** שלא תאמר הואיל וכלו התר הבא מכלל אסור הוא, שהרי קדוש ונשחט בחוץ בלא פדיון ונאכל, יכול יהא אף הדם מתר, תלמוד לומר רק את דמו לא תאכל:
@448 **שמור את חדש האביב.** מקודם בואו שמור, שיהא ראוי לאביב להקריב בו את מנחת העמר, ואם לאו, עבר את השנה: **ממצרים לילה.** והלא ביום יצאו, שנאמר (במדבר לג, ג) ממחרת הפסח יצאו בני ישראל וגו' , אלא לפי שבלילה נתן להם פרעה רשות לצאת, שנאמר (שמות יב, לא) ויקרא למשה ולאהרן לילה וגו' :
@449 **וזבחת פסח לה' אלהיך צאן.** שנאמר (שמות יב, ה) מן הכבשים ומן העזים תקחו: **ובקר.** תזבח לחגיגה. שאם נמנו על הפסח חבורה מרבה, מביאים עמו חגיגה כדי שיהא נאכל על השובע, ועוד למדו רבותינו דברים הרבה מפסוק זה:
@450 **לחם עני.** לחם שמזכיר את העוני שנתענו במצרים: **כי בחפזון יצאת.** ולא הספיק בצק להחמיץ וזה יהיה לך לזכרון. וחפזון לא שלך היה אלא של מצרים, שכן הוא אומר (שמות יב, לג) ותחזק מצרים על העם וגו' : **למען תזכר.** על ידי אכילת הפסח והמצה, את יום צאתך:
@451 **ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר.** אזהרה למותיר בפסח דורות, לפי שלא נאמר אלא בפסח מצרים, ויום ראשון האמור כאן הוא ארבעה עשר בניסן, כמה דאתאמר (שמות יב, טו) אך ביום הראשון תשביתו שאר מבתיכם. ולפי שנסתלק הכתוב מענינו של פסח והתחיל לדבר בחקות שבעת ימים, כגון שבעת ימים תאכל עליו מצות ולא יראה לך שאור בכל גבולך, הצרך לפרש באיזו זביחה הוא מזהיר, שאם כתב ולא ילין מן הבשר אשר תזבח בערב לבקר הייתי אומר שלמים הנשחטים כל שבעה כלן בבל תותירו ואינן נאכלין אלא ליום ולילה, לכך כתב בערב ביום הראשון. דבר אחר בחגיגת ארבעה עשר הכתוב מדבר, ולמד עליה שנאכלת לשני ימים. והראשון האמור כאן, ביום טוב הראשון הכתוב מדבר. וכן משמעות המקרא, בשר חגיגה אשר תזבח בערב, לא ילין ביום טוב הראשון עד בקרו של שני, אבל נאכלת היא בארבעה עשר ובחמשה עשר, כך היא שנויה במסכת פסחים (עא ב) :
@453 **בערב כבוא השמש מועד צאתך ממצרים.** הרי שלשה זמנים חלוקים, בערב, משש שעות ולמעלה זבחהו. וכבוא השמש, תאכלהו. ומועד צאתך, אתה שורפהו. כלומר, נעשה נותר ויצא לבית השרפה:
@454 **ובשלת.** זהו צלי אש, שאף הוא קרוי בשול: **ופנית בבקר.** לבקרו של שני, מלמד שטעון לינה ליל של מוצאי יום טוב:
@455 **ששת ימים תאכל מצות.** ובמקום אחר הוא אומר (שמות יב, טו) שבעת ימים, שבעה מן הישן וששה מן החדש. דבר אחר למד על אכילת מצה בשביעי, שאינה חובה, ומכאן אתה למד לששת ימים. שהרי שביעי בכלל היה ויצא מן הכלל ללמד, שאין אכילת מצה בו חובה אלא רשות, ולא ללמד על עצמו יצא אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף כלם רשות, חוץ מלילה הראשון שהכתוב קבעו חובה, שנאמר (שמות יב, יח) בערב תאכלו מצות: **עצרת לה' אלהיך.** עצור עצמך מן המלאכה. דבר אחר כנופיא של מאכל ומשתה, לשון (שופטים יג, טו) נעצרה נא אותך:
@456 **מהחל חרמש בקמה.** משנקצר העמר שהוא ראשית הקציר:
@457 **מסת נדבת ידך.** די נדבת ידך, הכל לפי הברכה, הבא שלמי שמחה, וקדש קרואים לאכול:
@458 **והלוי:. והגר והיתום והאלמנה.** ארבעה שלי כנגד ארבעה שלך, בנך ובתך ועבדך ואמתך, אם אתה משמח את שלי, אני משמח את שלך:
@459 **וזכרת כי עבד היית** וגו' **.** על מנת כן פדיתיך, שתשמור ותעשה את החקים האלה:
@460 **באספך.** בזמן האסיף שאתה מכניס לבית פרות הקיץ. דבר אחר באספך מגרנך ומיקבך, למד שמסככין את הסכה בפסולת גורן ויקב:
@462 **והיית אך שמח.** לפי פשוטו אין זה לשון צווי אלא לשון הבטחה, ולפי תלמודו למדו מכאן לרבות לילי יום טוב האחרון לשמחה:
@463 **ולא יראה את פני ה' ריקם.** אלא הבא עולות ראיה ושלמי חגיגה:
@464 **איש כמתנת ידו.** מי שיש לו אוכלין הרבה ונכסים מרבין יביא עולות מרבות ושלמים מרבים:
@465 **שפטים ושטרים.** שופטים, דינים הפוסקים את הדין. ושוטרים, הרודין את העם אחר מצותם. שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט: **בכל שעריך.** בכל עיר ועיר: **לשבטיך.** מוסב על תתן לך. שופטים ושוטרים תתן לך לשבטיך בכל שעריך אשר ה' אלהיך נתן לך: **לשבטיך.** מלמד שמושיבין דינין לכל שבט ושבט ובכל עיר ועיר: **ושפטו את העם** וגו' **.** מנה דינין מומחים וצדיקים לשפוט צדק:
@466 **לא תטה משפט.** כמשמעו: **לא תכיר פנים.** אף בשעת הטענות. אזהרה לדין שלא יהא רך לזה וקשה לזה, אחד עומד ואחד יושב. לפי שכשרואה שהדין מכבד את חברו מסתתמין טענותיו: **ולא תקח שחד.** אפלו לשפוט צדק: **כי השחד יעור.** משקבל שחד ממנו אי אפשר שלא יטה את לבו אצלו להפוך בזכותו: **דברי צדיקים.** דברים המצדקים, משפטי אמת:
@467 **צדק צדק תרדף.** הלך אחר בית דין יפה: **למען תחיה וירשת.** כדאי הוא מנוי הדינין הכשרים להחיות את ישראל ולהושיבן על אדמתן:
@468 **לא תטע לך אשרה.** לחייבו עליה משעת נטיעתה ואפלו לא עבדה עובר בלא תעשה על נטיעתה: **לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך.** אזהרה לנוטע אילן ולבונה בית בהר הבית:
@469 **ולא תקים לך מצבה.** מצבת אבן אחת, להקריב עליה אפלו לשמים: **אשר שנא.** מזבח אבנים ומזבח אדמה צוה לעשות, ואת זו שנא כי חק היתה לכנענים. ואף על פי שהיתה אהובה לו בימי האבות, עכשיו שנאה, מאחר שעשאוה אלו חק לעבודה זרה:
@470 **לא תזבח** וגו' **כל דבר רע.** אזהרה למפגל בקדשים על ידי דבור רע. ועוד נדרשו בו שאר דרשות בשחיטת קדשים:
@471 **לעבר בריתו.** אשר כרת אתכם שלא לעבוד עבודה זרה:
@472 **אשר לא צויתי.** לעבדם:
@473 **נכון.** מכון העדות:
@474 **והוצאת את האיש ההוא:. אל שעריך** וגו' **.** המתרגם אל שעריך, לתרע בית דינך, טועה, שכן שנינו אל שעריך זה שער שעבד בו, או אינו אלא שער שנדון בו, נאמר שעריך למטה ונאמר שעריך למעלה (פסוק ב) מה שעריך האמור למעלה שער שעבד בו אף שעריך האמור למטה שער שעבד בו. ותרגומו לקרוך:
@475 **שנים [עדים] או שלשה.** אם מתקימת עדות בשנים למה פרט לך בשלשה, להקיש שלשה לשנים, מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כלם:
@477 **כי יפלא.** כל הפלאה לשון הבדלה ופרישה, שהדבר נבדל ומכסה ממך: **בין דם לדם.** בין דם טמא לדם טהור: **בין דין לדין.** בין דין זכאי לדין חיב: **בין נגע לנגע.** בין נגע טמא לנגע טהור: **דברי ריבת.** שיהו חכמי העיר חולקים בדבר, זה מטמא וזה מטהר זה מחיב וזה מזכה: **וקמת ועלית.** מלמד שבית המקדש גבוה מכל המקומות:
@478 **הכהנים הלוים.** הכהנים שיצאו משבט לוי: **ואל השפט אשר יהיה בימים ההם.** ואפלו אינו כשאר שופטים שהיו לפניו אתה צריך לשמוע לו. אין לך אלא שופט שבימיך:
@480 **ימין ושמאל.** אפלו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין, וכל שכן שאומר לך על ימין ימין ועל שמאל שמאל:
@482 **וכל העם ישמעו.** מכאן שממתינין לו עד הרגל וממיתין אותו ברגל:
@485 **לא ירבה לו סוסים.** אלא כדי מרכבתו, שלא ישיב את העם מצרימה, שהסוסים באים משם. כמה שנאמר בשלמה, ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה (מלכים א' י, כט) :
@486 **ולא ירבה לו נשים.** אלא שמונה עשרה, שמצינו שהיו לו לדוד שש נשים, ונאמר לו ואם מעט ואספה לך כהנה וכהנה (שמואל ב' יב, ח) : **וכסף וזהב לא ירבה לו מאד.** אלא כדי לתן לאכסניא [לאפסניא] :
@487 **והיה כשבתו.** אם עשה כן, כדאי הוא שתתקיים מלכותו: **את משנה התורה.** שתי ספרי תורה. אחת שהיא מנחת בבית גנזיו ואחת שנכנסת ויוצאת עמו. ואונקלוס תרגם פתשגן, פתר משנה לשון שנון ודבור:
@488 **דברי התורה.** כמשמעו:
@489 **ולבלתי סור מן המצוה.** אפלו מצוה קלה של נביא: **למען יאריך ימים.** מכלל הן אתה שומע לאו. וכן מצינו בשאול שאמר לו שמואל שבעת ימים תוחל עד בואי אליך להעלות עלות (שמואל א' י, ח) וכתיב ויוחל שבעת ימים (שמואל א' יג, ח) ולא שמר הבטחתו לשמור כל היום, ולא הספיק להעלות העולה עד שבא שמואל ואמר לו נסכלת לא שמרת וגו' ועתה ממלכתך לא תקום (שם יג ז. יד) . הא למדת, שבשביל מצוה קלה של נביא נענש: **הוא ובניו.** מגיד שאם בנו הגון למלכות הוא קודם לכל אדם:
@491 **כל שבט לוי.** בין תמימין בין בעלי מומין: **חלק.** בבזה: **ונחלה.** בארץ: **אשי ה'.** קדשי המקדש [הקדשים] : **ונחלתו.** אלו קדשי הגבול תרומות ומעשרות. אבל נחלה גמורה לא יהיה לו בקרב אחיו. ובספרי דרשו, ונחלה לא יהיה לו. זו נחלת שאר: **בקרב אחיו.** זו נחלת חמשה. ואיני יודע מה היא. ונראה לי שארץ כנען שמעבר הירדן ואלך נקראת ארץ חמשה עממין, ושל סיחון ועוג, שני עממין אמורי וכנעני. ונחלת שאר לרבות קיני וקנזי וקדמוני. וכן דורש בפרשת מתנות שנאמרו לאהרן על כן לא היה ללוי וגו' (דברים י, ט) להזהיר על קיני וקנזי וקדמוני. שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי ונחלה לא יהיה לו אלו נחלת חמשה. בקרב אחיו אלו נחלת שבעה. נחלת חמשה שבטים ונחלת שבעה שבטים. ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד, שכן משה הנחיל לראובן וגד וחצי שבט מנשה, ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה, ושבעה האחרים נטלו מאליהן אחרי מות יהושע, מתוך כך הזכיר חמשה לבד ושבעה לבד: **כאשר דבר לו.** לאהרן, בארצם לא תנחל וגו' אני חלקך (במדבר יח, כ) :
@492 **מאת העם.** ולא מאת הכהנים: **אם שור אם שה.** פרט לחיה: **הזרוע.** מן הפרק של ארכבה עד כף של יד שקורין אשפלדו''ן [עצם השכם] : **והלחיים.** עם הלשון. דורשי רשומות היו אומרים, זרוע, תחת יד, שנאמר (במדבר כה, ז) ויקח רמח בידו. לחיים, תחת תפלה, שנאמר (תהל' קו, ל) ויעמד פינחס ויפלל: **והקבה.** תחת (במד' כה) האשה אל קבתה:
@493 **ראשית דגנך.** זו תרומה, ולא פרש בה שעור, אבל רבותינו נתנו בה שעור, עין יפה אחד מארבעים, עין רעה אחד מששים, בינונית אחד מחמשים. וסמכו על המקרא שלא לפחות מאחד מששים, שנאמר וששיתם האיפה מחמר השערים (יחזקאל מה, יג) ששית האיפה, חצי סאה. כשאתה נותן חצי סאה לכור, הרי אחד מששים, שהכור שלשים סאין: **וראשית גז צאנך.** כשאתה גוזז צאנך בכל שנה תן ממנה ראשית לכהן. ולא פרש בה שעור. ורבותינו נתנו בה שעור אחד מששים. וכמה צאן חיבות בראשית הגז, חמש רחלות, שנאמר (שמואל א' כה, יח) וחמש צאן עשויות. רבי עקיבא אומר ראשית גז שתים, גז צאנך ארבע, תתן לו הרי חמש:
@494 **לעמד לשרת.** מכאן שאין שרות אלא מעומד:
@496 **וכי יבא הלוי.** יכול בבן לוי ודאי הכתוב מדבר, תלמוד לומר ושרת, יצאו לויים שאין ראויין לשרות: **ובא בכל אות נפשו** וגו' **ושרת.** למד על הכהן שבא ומקריב קרבנות נדבתו או חובתו ואפלו במשמר שאינו שלו. דבר אחר עוד למד על הכהנים הבאים לרגל שמקריבין במשמר ועובדין בקרבנות הבאים מחמת הרגל, כגון מוספי הרגל, ואף על פי שאין המשמר שלהם:
@497 **חלק כחלק יאכלו.** מלמד שחולקין בעורות ובבשר שעירי חטאות. יכול אף בדברים הבאים שלא מחמת הרגל, כגון תמידין ומוספי שבת ונדרים ונדבות, תלמוד לומר לבד ממכריו על האבות, חוץ ממה שמכרו האבות בימי דוד ושמואל, שנקבעו המשמרות ומכרו זה לזה טול אתה שבתך ואני אטול שבתי:
@498 **לא תלמד לעשות.** אבל אתה למד להבין ולהורות, כלומר להבין מעשיהם כמה הם מקלקלים, ולהורות לבניך לא תעשה כך וכך, שזה הוא חק הגוים:
@499 **מעביר בנו ובתו באש.** היא עבודת המולך. עושה מדורות אש מכאן ומכאן ומעבירו בין שתיהם: **קסם קסמים.** איזהו קוסם, האוחז את מקלו ואומר אם אלך אם לא אלך. וכן הוא אומר, (הושע ד, יב) עמי בעצו ישאל ומקלו יגיד לו: **מעונן.** רבי עקיבא אומר אלו נותני עונות, שאומרים עונה פלונית יפה להתחיל. וחכמים אומרים אלו אוחזי העינים: **מנחש.** פתו נפלה מפיו, צבי הפסיקו בדרך, מקלו נפל מידו:
@500 **וחבר חבר.** שמצרף נחשים או עקרבים או שאר חיות למקום אחד: **ושאל אוב.** זה מכשפות ששמו פיתום ומדבר משחיו ומעלה את המת בבית השחי שלו: **וידעני.** מכניס עצם חיה ששמה ידוע, לתוך פיו, ומדבר העצם על ידי מכשפות: **ודרש אל המתים.** כגון המעלה בזכרותו והנשאל בגלגלת:
@501 **כל עשה אלה.** עשה כל אלה לא נאמר אלא כל עשה אלה, אפלו אחת מהן:
@502 **תמים תהיה עם ה' אלהיך.** התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות, אלא כל מה שיבא עליך קבל בתמימות ואז תהיה עמו ולחלקו:
@503 **לא כן נתן לך ה' אלהיך.** לשמוע אל מעוננים ואל קוסמים שהרי השרה שכינה על הנביאים ואורים ותמים:
@504 **מקרבך מאחיך כמני.** כמו שאני מקרבך מאחיך יקים לך תחתי, וכן מנביא לנביא:
@509 **אשר לא צויתיו לדבר.** אבל צויתיו לחברו: **ואשר ידבר בשם אלהים אחרים.** אפלו כון את ההלכה, לאסור את האסור ולהתיר את המתר: **ומת.** בחנק. שלשה מיתתן בידי אדם, המתנבא מה שלא שמע ומה שלא נאמר לו ונאמר לחברו, והמתנבא בשם עבודה זרה. אבל הכובש את נבואתו והעובר על דברי נביא והעובר על דברי עצמו מיתתן בידי שמים, שנאמר אנכי אדרש מעמו (פסוק יט) :
@510 **וכי תאמר בלבבך.** עתידין אתם לומר, כשיבא חנניה בן עזור ומתנבא (ירמיה כז, טז) הנה כלי בית ה' מושבים מבבלה עתה מהרה, וירמיהו עומד וצווח על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה, (שם כז, כב) בבלה יובאו עם גלות צדקיהו:
@511 **אשר ידבר הנביא.** ויאמר דבר זה עתיד לבא עליכם, ותראו שלא יבא, הוא הדבר אשר לא דברו ה' והרג אותו. ואם תאמר זו במתנבא על העתידות, הרי שבא ואמר עשו כך וכך ומפי הקדוש ברוך הוא אני אומר, כבר נצטוו שאם בא להדיחך מאחת מכל המצות לא תשמע לו, אלא אם כן ממחה הוא לך שהוא צדיק גמור, כגון אליהו בהר הכרמל שהקריב בבמה בשעת אסור הבמות כדי לגדור את ישראל. הכל לפי צורך השעה וסיג הפרצה, לכך נאמר אליו תשמעון: **לא תגור ממנו.** לא תמנע עצמך מללמד עליו חובה ולא תירא לענש עליו:
@514 **תכין לך הדרך.** מקלט מקלט היה כתוב על פרשת דרכים: **ושלשת את גבול ארצך.** שיהא מתחלת הגבול עד העיר הראשונה של עיר מקלט, כשעור מהלך שיש ממנה עד השניה. וכן משניה, לשלישית. וכן מן השלישית, עד הגבול השני של ארץ ישראל:
@516 **ונדחה ידו.** כשבא להפיל הגרזן על העץ, ותרגומו ותתמריג ידיה, לשון ונשמטה ידו להפיל מכת הגרזן על העץ. כי שמטו הבקר, תרגם יונתן (שמואל ב' ו, ו) ארי מרגוהי תוריא: **ונשל הברזל מן העץ.** יש מרבותינו אומרים נשמט הברזל מקתו, ויש מהם אומרים שישיל הברזל חתיכה מן העץ המתבקע, והיא נתזה והרגה:
@517 **פן ירדף גאל הדם.** לכך אני אומר להכין לך דרך, וערי מקלט רבים:
@519 **ואם ירחיב.** כאשר נשבע לתת לך ארץ קיני וקנזי וקדמוני:
@520 **ויספת לך עוד שלש.** הרי תשע. שלש שבעבר הירדן ושלש שבארץ כנען ושלש לעתיד לבא:
@522 **וכי יהיה איש שנא לרעהו.** על ידי שנאתו הוא בא לידי וארב לו. מכאן אמרו עבר אדם על מצוה קלה סופו לעבור על מצוה חמורה. לפי שעבר על לא תשנא, סופו לבא לידי שפיכת דמים. לכך נאמר כי יהיה איש שנא לרעהו וגו' , שהיה לו לכתוב וכי יקום איש וארב לרעהו והכהו נפש:
@524 **לא תחוס עינך.** שלא תאמר הראשון כבר נהרג, למה אנו הורגים את זה ונמצאו שני ישראלים הרוגים:
@525 **לא תסיג גבול.** לשון (ישעיה מב, יז) נסגו אחור, שמחזיר סימן חלקת הקרקע לאחור לתוך שדה חברו למען הרחיב את שלו. והלא כבר נאמר (ויקרא יט, יג) לא תגזל, מה תלמוד לומר לא תסיג, למד על העוקר תחום חברו שעובר בשני לאוין. יכול אף בחוצה לארץ, תלמוד לומר בנחלתך אשר תנחל וגו' , בארץ ישראל עובר בשני לאוין, בחוצה לארץ אינו עובר אלא משום לא תגזל:
@526 **עד אחד.** זה בנה אב. כל עד שבתורה שנים, אלא אם כן פרט לך בו אחד: **לכל עון ולכל חטאת.** להיות חברו נענש על עדותו, לא עונש גוף ולא עונש ממון, אבל קם הוא לשבועה. אמר לחברו תן לי מנה שהלויתיך, אמר לו אין לך בידי כלום, ועד אחד מעיד שיש לו, חיב להשבע לו: **על פי שני עדים.** ולא שיכתבו עדותם באגרת וישלחו לבית דין, ולא שיעמוד תרגמן בין העדים ובין הדינים:
@527 **לענות בו סרה.** דבר שאינו, שהוסר העד הזה מכל העדות הזאת, כגון, שאמרו להם והלא עמנו הייתם אותו היום במקום פלוני:
@528 **ועמדו שני האנשים.** בעדים הכתוב מדבר, ולמד שאין עדות בנשים, ולמד שצריכין להעיד עדותן מעומד: **אשר להם הריב.** אלו בעלי הדין: **לפני ה'.** יהי דומה להם כאלו עומדין לפני המקום, שנאמר (תהלים פב, א) בקרב אלהים ישפט: **אשר יהיו בימים ההם.** יפתח בדורו כשמואל בדורו, צריך אתה לנהוג בו כבוד:
@529 **ודרשו השופטים היטב.** על פי המזימין אותם, שבודקים וחוקרים את הבאים להזימם בדרישה ובחקירה: **והנה עד שקר.** כל מקום שנאמר עד, בשנים הכתוב מדבר:
@530 **כאשר זמם.** ולא כאשר עשה. מכאן אמרו, הרגו אין נהרגין: **לעשות לאחיו.** מה תלמוד לומר לאחיו, למד על זוממי בת כהן נשואה שאינן בשריפה, אלא כמיתת הבועל שהוא בחנק, שנאמר (ויקרא כא, ט) היא באש תשרף, היא ולא בועלה. לכך נאמר כאן לאחיו, כאשר זמם לעשות לאחיו, ולא כאשר זמם לעשות לאחותו. אבל בכל שאר מיתות השוה הכתוב אשה לאיש, וזוממי אשה נהרגין כזוממי איש. כגון שהעידוה שהרגה את הנפש, שחללה את השבת, נהרגין במיתתה. שלא מעט כאן אחותו אלא במקום שיש לקים בהן הזמה במיתת הבועל:
@531 **ישמעו ויראו.** מכאן שצריכין הכרזה, איש פלוני ופלוני נהרגין על שהוזמו בבית דין:
@532 **עין בעין.** ממון, וכן שן בשן וגו' :
@533 **כי תצא למלחמה.** סמך הכתוב יציאת מלחמה לכאן, לומר לך, שאין מחסר אבר יוצא למלחמה. דבר אחר לומר לך, אם עשית משפט צדק אתה מבטח שאם תצא למלחמה אתה נוצח. וכן דוד הוא אומר (תהלים קיט, קכא) עשיתי משפט וצדק בל תניחני לעשקי: **על איבך.** יהיו בעיניך כאויבים, אל תרחם עליהם כי לא ירחמו עליך: **סוס ורכב.** בעיני כלם כסוס אחד, וכן הוא אומר (שופטים ו, טז) והכית את מדין כאיש אחד. וכן הוא אומר (שמות טו, יט) כי בא סוס פרעה: **עם רב ממך.** בעיניך הוא רב, אבל בעיני אינו רב:
@534 **כקרבכם אל המלחמה.** סמוך לצאתכם מן הספר מגבול ארצכם: **ונגש הכהן.** המשוח לכך. והוא הנקרא משוח מלחמה: **ודבר אל העם.** בלשון הקדש:
@535 **שמע ישראל.** אפלו אין בכם זכות אלא קרית שמע בלבד, כדאי אתם שיושיע אתכם: **על איביכם.** אין אלו אחיכם, שאם תפלו בידם אינם מרחמים עליכם, אין זו כמלחמת יהודה עם ישראל, שנאמר (דה''י ב' כח, טו) ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה, וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל, ויביאום ירחו עיר התמרים אצל אחיהם, וישובו שמרון, אלא על אויביכם אתם הולכים, לפיכך התחזקו למלחמה: **אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו.** ארבע אזהרות כנגד ארבעה דברים שמלכי האמות עושים. מגיפים בתריסיהם כדי להקישן זה לזה כדי להשמיע קול שיחפזו אלו שכנגדם וינוסו, ורומסים בסוסיהם ומצהילין אותם להשמיע קול שעטת פרסות סוסיהם, וצווחין בקולם ותוקעין בשופרות ומיני משמיעי קול: **אל ירך לבבכם.** מצהלת סוסים: **אל תיראו.** מהגפת התריסין: **ואל תחפזו.** מקול הקרנות: **ואל תערצו.** מקול הצוחה:
@536 **כי ה' אלהיכם** וגו' **.** הם באים בנצחונו של בשר ודם ואתם באים בנצחונו של מקום. פלשתים באו בנצחונו של גלית, מה היה סופו, נפל ונפלו עמו: **ההלך עמכם.** זה מחנה הארון:
@537 **ולא חנכו.** לא דר בו. חנוך לשון התחלה: **ואיש אחר יחנכנו.** ודבר של עגמת נפש הוא זה:
@538 **ולא חללו.** לא פדאו בשנה הרביעית, שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכל הדמים בירושלים:
@539 **פן ימות במלחמה.** ישוב פן ימות, שאם לא ישמע לדברי הכהן כדאי הוא שימות:
@540 **ויספו השטרים.** למה נאמר כאן ויספו, מוסיפין זה על דברי הכהן, שהכהן מדבר ומשמיע מן (פסוק ג, ד) שמע ישראל עד להושיע אתכם, ומי האיש ושני ושלישי כהן מדבר ושוטר משמיע, וזה שוטר מדבר ושוטר משמיע: **הירא ורך הלבב.** רבי עקיבא אומר כמשמעו, שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה. רבי יוסי הגלילי אומר הירא מעבירות שבידו, ולכך תלתה לו תורה לחזור על בית וכרם ואשה לכסות על החוזרים בשביל עברות שבידם, שלא יבינו שהם בעלי עברה, והרואהו חוזר אומר שמא בנה בית או נטע כרם או ארש אשה:
@541 **שרי צבאות.** שמעמידין זקפין, מלפניהם ומלאחריהם וכשילין של ברזל בידיהם וכל מי שרוצה לחזור הרשות בידו לקפח את שוקיו. זקפין, בני אדם עומדים בקצה המערכה לזקוף את הנופלים ולחזקם בדברים שובו אל המלחמה ולא תנוסו, שתחלת נפילה ניסה:
@542 **כי תקרב אל עיר.** במלחמת הרשות הכתוב מדבר, כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחקת וגו' :
@543 **כל העם הנמצא בה.** אפלו אתה מוצא בה משבעה אמות שנצטוית להחרימם, אתה רשאי לקימם: **למס ועבדוך.** עד שיקבלו עליהם מסים ושעבוד:
@544 **ואם לא תשלים עמך ועשתה עמך מלחמה.** הכתוב מבשרך שאם לא תשלים עמך סופה להלחם בך אם תניחנה ותלך: **וצרת עליה.** אף להרעיבה ולהצמיאה ולהמיתה מיתת תחלואים:
@545 **ונתנה ה' אלהיך בידך.** אם עשית כל האמור בענין, סוף שה' נותנה בידך:
@546 **והטף.** אף טף של זכרים. ומה אני מקים (פסוק יג) והכית את כל זכורה, בגדולים:
@549 **כאשר צוך.** לרבות את הגרגשי:
@550 **למען אשר לא ילמדו.** הא אם עשו תשובה ומתגירים, אתה רשאי לקבלם:
@551 **ימים.** שנים: **רבים.** שלשה. מכאן אמרו אין צרין על עירות של נכרים פחות משלשה ימים קודם לשבת. ולמד שפותח בשלום שנים או שלשה ימים. וכן הוא אומר (שמואל ב' א, א) וישב דוד בצקלג ימים שנים, ובמלחמת הרשות הכתוב מדבר: **כי האדם עץ השדה.** הרי כי משמש בלשון דלמא. שמא האדם עץ השדה להכנס בתוך המצור מפניך להתיסר ביסורי רעב וצמא כאנשי העיר, למה תשחיתנו:
@552 **עד רדתה.** לשון רדוי, שתהא כפופה לך:
@554 **ויצאו זקניך.** מיחדים שבזקניך, אלו סנהדרי גדולה: **ומדדו.** ממקום שהחלל שוכב: **אל הערים אשר סביבת החלל.** לכל צד לידע איזו קרובה:
@556 **אל נחל איתן.** קשה, שלא נעבד: **וערפו.** קוצץ ערפה בקופיץ. אמר הקדוש ברוך הוא תבא עגלה בת שנתה שלא עשתה פרות ותערף במקום שאינו עושה פרות, לכפר על הריגתו של זה שלא הניחוהו לעשות פרות:
@559 **ידינו לא שפכה.** וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה. והכהנים אומרים כפר לעמך ישראל:
@560 **ונכפר להם הדם.** הכתוב מבשרם שמשעשו כן, יכפר להם העון:
@561 **ואתה תבער.** מגיד שאם נמצא ההורג אחר שנתערפה העגלה הרי זה יהרג, והוא הישר בעיני ה':
@562 **כי תצא למלחמה.** במלחמת הרשות הכתוב מדבר, שבמלחמת ארץ ישראל אין לומר ושבית שביו, שהרי כבר נאמר (לעיל כ, טז) לא תחיה כל נשמה: **ושבית שביו.** לרבות כנענים שבתוכה ואף על פי שהם משבעה אמות:
@563 **אשת.** אפלו אשת איש: **ולקחת לך לאשה.** לא דברה תורה אלא כנגד יצר הרע. שאם אין הקדוש ברוך הוא מתירה, ישאנה באסור. אבל אם נשאה, סופו להיות שונאה, שנאמר אחריו (פסוק טו) כי תהיין לאיש וגו' וסופו להוליד ממנה בן סורר ומורה, לכך נסמכו פרשיות הללו:
@564 **ועשתה את צפרניה.** תגדלם כדי שתתנול:
@565 **והסירה את שמלת שביה.** לפי שהם נאים, שהגוים בנותיהם מתקשטות במלחמה בשביל להזנות אחרים עמהם: **וישבה בביתך.** בבית שמשתמש בו, נכנס ונתקל בה, יוצא ונתקל בה, רואה בבכייתה, רואה בנוולה, כדי שתתגנה עליו: **ובכתה את אביה.** כל כך למה, כדי שתהא בת ישראל שמחה וזו עצבה, בת ישראל מתקשטת וזו מתנולת:
@566 **והיה אם לא חפצת בה.** הכתוב מבשרך שסופך לשנאותה: **לא תתעמר בה.** לא תשתמש בה, בלשון פרסי קורין לעבדות ושמוש, עימראה. מיסודו של רבי משה הדרשן למדתי כן:
@569 **פי שנים.** כנגד שני אחים: **בכל אשר ימצא לו.** מכאן שאין הבכור נוטל פי שנים בראוי לבא לאחר מיתת האב, כבמחזק:
@570 **סורר.** סר מן הדרך: **ומורה.** מסרב בדברי אביו, לשון ממרים: **ויסרו אותו.** מתרין בו בפני שלשה ומלקין אותו. בן סורר ומורה אינו חיב, עד שיגנוב ויאכל תרטימר בשר וישתה חצי לוג יין. שנאמר (פסוק כ) זולל וסבא, ונאמר (משלי כג, כ) אל תהי בסובאי יין בזוללי בשר למו. ובן סורר ומורה נהרג על שם סופו, הגיעה תורה לסוף דעתו, סוף שמכלה ממון אביו ומבקש למודו ואינו מוצא, ועומד בפרשת דרכים ומלסטם את הבריות, אמרה תורה ימות זכאי ואל ימות חיב:
@573 **וכל ישראל ישמעו ויראו.** מכאן שצריך הכרזה בבית דין, פלוני נסקל על שהיה בן סורר ומורה:
@574 **וכי יהיה באיש חטא משפט מות.** סמיכות הפרשיות מגיד, שאם חסים עליו אביו ואמו, סוף שיצא לתרבות רעה ויעבור עברות ויתחיב מיתה בבית דין: **ותלית אתו על עץ.** רבותינו אמרו, כל הנסקלין, נתלין, שנאמר (פסוק כג) כי קללת אלהים תלוי. והמברך ה', בסקילה:
@575 **כי קללת אלהים תלוי.** זלזולו של מלך הוא, שאדם עשוי בדמות דיקנו וישראל הם בניו. משל לשני אחים תאומים שהיו דומין זה לזה, אחד נעשה מלך, ואחד נתפס ללסטיות ונתלה, כל הרואה אותו אומר המלך תלוי. כל קללה שבמקרא לשון הקל וזלזול, כמו (מלכ' א' ב, ח) והוא קללני קללה נמרצת:
@576 **והתעלמת.** כובש עין כאלו אינו רואהו: **לא תראה' והתעלמת.** לא תראה אותו שתתעלם ממנו, זהו פשוטו. ורבותינו אמרו פעמים שאתה מתעלם וכו' :
@577 **עד דרש אחיך.** וכי תעלה על דעתך שיתנהו לו קודם שידרשהו, אלא דרשהו שלא יהא רמאי: **והשבתו לו.** שתהא בו השבה, שלא יאכל בביתך כדי דמיו ותתבעם ממנו. מכאן אמרו, כל דבר שעושה ואוכל יעשה ויאכל, ושאינו עושה ואוכל, ימכר:
@578 **לא תוכל להתעלם.** לכבוש עינך כאלו אינך רואה אותו:
@579 **הקם תקים.** זו טעינה. להטעין משאוי שנפל מעליו: **עמו.** עם בעליו, אבל אם הלך וישב לו, ואמר לו הואיל ועליך מצוה אם רצית לטעון טעון, פטור:
@580 **לא יהיה כלי גבר על אשה.** שתהא דומה לאיש כדי שתלך בין האנשים, שאין זו אלא לשם ניאוף: **ולא ילבש גבר שמלת אשה.** לילך ולישב בין הנשים. דבר אחר שלא ישיר שער הערוה ושער של בית השחי: **כי תועבת.** לא אסרה תורה אלא לבוש המביא לידי תועבה:
@581 **כי יקרא.** פרט למזמן: **לא תקח האם.** בעודה על בניה:
@582 **למען ייטב לך.** אם מצוה קלה שאין בה חסרון כיס, אמרה תורה למען ייטב לך והארכת ימים, קל וחמר למתן שכרן של מצות חמורות:
@583 **כי תבנה בית חדש.** אם קימת מצות שלוח הקן סופך לבנות בית חדש ותקיים מצות מעקה, שמצוה גוררת מצוה, ותגיע לכרם ושדה ולבגדים נאים. לכך נסמכו פרשיות הללו: **מעקה.** גדר סביב לגג, ואונקלוס תרגם תיקא כעין תיק שמשמר מה שבתוכו: **כי יפל הנפל.** ראוי זה לפול ואף על פי כן לא תתגלגל מיתתו על ידך, שמגלגלין זכות על ידי זכאי וחובה על ידי חיב:
@584 **כלאים.** חטה ושעורה וחרצן במפלת יד: **פן תקדש.** כתרגומו תסתאב. כל דבר הנתעב על האדם, בין לשבח כגון הקדש, בין לגנאי כגון אסור, נופל בו לשון קדש, כמו (ישעיה סה, ה) אל תגש בי כי קדשתיך: **המלאה.** זה מלוי ותוספת שהזרע מוסיף:
@585 **לא תחרש בשור ובחמור.** הוא הדין לכל שני מינים שבעולם, והוא הדין להנהיגם יחד קשורים זוגים בהולכת שום משא:
@586 **שעטנז.** לשון ערוב. ורבותינו פרשו שוע טווי ונווז:
@587 **גדלים תעשה לך.** אף מן הכלאים. לכך סמכן הכתוב:
@588 **ובא אליה ושנאה.** סופו:
@589 **ושם לה עלילת דברים.** עברה גוררת עברה, עבר על לא תשנא (ויקרא יט, יז) סופו לבא לידי לשון הרע: **את האשה הזאת.** מכאן שאין אומר דבר אלא בפני בעל דין:
@590 **אבי הנערה ואמה.** מי שגדלו גדולים הרעים יתבזו עליה:
@591 **ואמר אבי הנערה.** מלמד שאין רשות לאשה לדבר בפני האיש:
@592 **ופרשו השמלה.** הרי זה משל, מחורין הדברים כשמלה:
@593 **ויסרו אתו.** מלקות:
@595 **ואם אמת היה הדבר.** בעדים והתראה שזנתה לאחר ארוסין:
@596 **אל פתח בית אביה.** ראו גדולים שגדלתם: **וסקלוה אנשי עירה.** במעמד כל אנשי עירה: **לזנות בית אביה.** כמו בבית אביה:
@597 **ומתו גם שניהם.** להוציא מעשה חדודים שאין האשה נהנית מהם: **גם.** לרבות הבאים מאחריהם. דבר אחר גם שניהם לרבות את הולד, שאם היתה מעברת אין ממתינין לה עד שתלד:
@598 **ומצאה איש בעיר.** לפיכך שכב עמה, פרצה קוראה לגנב. הא אלו ישבה בביתה לא אירע לה:
@601 **כי כאשר יקום** וגו' **.** לפי פשוטו זהו משמעו, כי אנוסה היא ובחזקה עמד עליה כאדם העומד על חברו להרגו. ורבותינו דרשו בו הרי זה בא ללמד ונמצא למד וכו' :
@605 **לא יקח.** אין לו בה לקוחין ואין קדושין תופסין בה: **ולא יגלה כנף אביו.** שומרת יבם של אביו הראויה לאביו. והרי כבר הזהר עליה משום (ויקרא יח, יד) ערות אחי אביך, אלא לעבור על זו בשני לאוין ולסמוך לה (פסוק ג) לא יבא ממזר, ללמד שאין ממזר אלא מחיבי כריתות וקל וחמר מחיבי מיתות בית דין, שאין בעריות מיתת בית דין שאין בה כרת:
@606 **פצוע דכא.** שנפצעו או שנדכאו ביצים שלו: **וכרות שפכה.** שנכרת הגיד ושוב אינו יורה קלוח זרע אלא שופך ושותת ואינו מוליד:
@607 **לא יבא ממזר בקהל ה'.** לא ישא ישראלית:
@608 **לא יבא עמוני.** לא ישא ישראלית:
@609 **על דבר.** על העצה שיעצו אתכם להחטיאכם: **בדרך.** כשהייתם בטרוף:
@611 **לא תדרש שלמם.** מכלל שנאמר (פסוק יז) עמך ישב בקרבך יכול אף זה כן, תלמוד לומר לא תדרש שלמם:
@612 **לא תתעב אדמי.** לגמרי ואף על פי שראוי לך לתעבו שיצא בחרב לקראתך: **לא תתעב מצרי.** מכל וכל, אף על פי שזרקו זכוריכם ליאור. מה טעם, שהיו לכם אכסניא בשעת הדחק. לפיכך. ט **בנים אשר יולדו להם דור שלישי.** ושאר האמות מתרין מיד. הא למדת שהמחטיא לאדם קשה לו מן ההורגו, שההורגו הורגו בעולם הזה, והמחטיאו מוציאו מן העולם הזה ומן העולם הבא, לפיכך אדום שקדמם בחרב לא נתעב וכן מצרים שטבעום, ואלו שהחטיאום נתעבו:
@614 **כי תצא** וגו' **ונשמרת.** שהשטן מקטרג בשעת הסכנה:
@615 **מקרה לילה.** דבר הכתוב בהוה: **ויצא אל מחוץ למחנה.** זו מצות עשה: **לא יבא אל תוך המחנה.** זו מצות לא תעשה. ואסור לכנס למחנה לויה, וכל שכן למחנה שכינה:
@616 **והיה לפנות ערב.** סמוך להערב שמשו יטבול, שאינו טהור בלא הערב שמש:
@617 **ויד תהיה לך.** כתרגומו ואתר, כמו (במדבר ב, יז) איש על ידו: **מחוץ למחנה.** חוץ לענן:
@618 **על אזנך.** לבד משאר כלי תשמישך: **אזנך.** כמו כלי זינך:
@619 **ולא יראה בך.** הקדוש ברוך הוא ערות דבר:
@620 **לא תסגיר עבד.** כתרגומו. דבר אחר אפלו עבד כנעני של ישראל שברח מחוצה לארץ לארץ ישראל:
@622 **לא תהיה קדשה.** מפקרת, מקדשת ומזמנת לזנות: **ולא יהיה קדש.** מזמן למשכב זכור. ואונקלוס תרגם לא תהי אתתא מבנת ישראל לגבר עבד, שאף זו מפקרת לבעילת זנות היא, מאחר שאין קדושין תופסין לו בה, שהרי הקשו לחמור, שנאמר (בראשית כב, ה) שבו לכם פה עם החמור, עם הדומה לחמור. ולא יסב גברא מבני ישראל אתתא אמא, שאף הוא נעשה קדש על ידה, שכל בעילותיו בעילות זנות שאין קדושין תופסין לו בה:
@623 **אתנן זונה.** נתן לה טלה באתננה פסול להקרבה: **ומחיר כלב.** החליף שה בכלב: **גם שניהם.** לרבות שנוייהם, כגון חטים ועשאן סלת:
@624 **לא תשיך.** אזהרה ללוה שלא יתן רבית למלוה, ואחר כך אזהרה למלוה (ויקרא כה, לז) את כספך לא תתן לו בנשך:
@625 **לנכרי תשיך.** ולא לאחיך. לאו הבא מכלל עשה, עשה, לעבור עליו בשני לאוין ועשה:
@626 **לא תאחר לשלמו.** שלשה רגלים. ולמדוהו רבותינו מן המקרא:
@628 **מוצא שפתיך תשמר ועשית.** לתן עשה על לא תעשה:
@629 **כי תבא בכרם רעך.** בפועל הכתוב מדבר: **כנפשך.** כמה שתרצה: **שבעך.** ולא אכילה גסה: **ואל כליך לא תתן.** מכאן שלא דברה תורה אלא בשעת הבציר, בזמן שאתה נותן לכליו של בעל הבית, אבל אם שכרו לעדור ולקשקש, אינו אוכל:
@630 **כי תבא בקמת רעך.** אף זו בפועל הכתוב מדבר:
@631 **כי מצא בה ערות דבר.** מצוה עליו לגרשה שלא תמצא חן בעיניו:
@632 **לאיש אחר.** אין זה בן זוגו של ראשון, הוא הוציא רשעה מתוך ביתו וזה הכניסה:
@633 **ושנאה האיש האחרון.** הכתוב מבשרו שסופו לשנאותה, ואם לאו קוברתו, שנאמר או כי ימות:
@634 **אחרי אשר הטמאה.** לרבות סוטה שנסתרה:
@635 **אשה חדשה.** שהיא חדשה לו ואפלו אלמנה, פרט למחזיר גרושתו: **ולא יעבר עליו.** דבר הצבא: **לכל דבר.** שהוא צורך הצבא, לא לספק מים ומזון ולא לתקן דרכים, אבל החוזרים מעורכי המלחמה על פי כהן, כגון בנה בית ולא חנכו או ארס אשה ולא לקחה, מספיקין מים ומזון ומתקנין את הדרכים: **יהיה לביתו.** אף בשביל ביתו, אם בנה בית וחנכו ואם נטע כרם וחללו, אינו זז מביתו בשביל צרכי המלחמה: **לביתו.** זה ביתו: **יהיה.** לרבות את כרמו: **ושמח.** ישמח את אשתו. ותרגומו ויחדי ית אתתיה. והמתרגם ויחדי עם אתתיה, טועה הוא, שאין זה תרגום של ושמח אלא של ושמח:
@636 **לא יחבל.** אם בא למשכנו על חובו בבית דין, לא ימשכננו בדברים שעושים בהן אוכל נפש: **רחים.** היא התחתונה: **ורכב.** היא העליונה:
@637 **כי ימצא.** בעדים והתראה. וכן כל כי ימצא שבתורה: **והתעמר בו.** אינו חיב עד שישתמש בו:
@638 **השמר בנגע הצרעת.** שלא תתלוש סימני טמאה, ולא תקוץ את הבהרת: **ככל אשר יורו אתכם.** אם להסגיר אם להחליט אם לטהר:
@639 **זכור את אשר עשה ה' אלהיך למרים.** אם באת להזהר שלא תלקה בצרעת, אל תספר לשון הרע. זכור העשוי למרים שדברה באחיה ולקתה בנגעים:
@640 **כי תשה ברעך.** תחוב בחברך: **משאת מאומה.** חוב של כלום:
@642 **לא תשכב בעבוטו.** לא תשכב ועבוטו אצלך:
@643 **כבוא השמש.** אם כסות לילה הוא, ואם כסות יום החזירהו בבקר, וכבר כתוב בואלה המשפטים (שמות כב, כה) עד בא השמש תשיבנו לו, כל היום תשיבנו לו וכבוא השמש תקחנו: **וברכך.** ואם אינו מברכך, מכל מקום ולך תהיה צדקה:
@644 **לא תעשק שכיר.** והלא כבר כתוב, אלא לעבור על האביון בשני לאוין לא תעשוק שכר שכיר שהוא עני ואביון, ועל העשיר כבר הזהר (ויקרא יט, יג) לא תעשק את רעך: **אביון.** התאב לכל דבר: **מגרך.** זה גר צדק: **בשעריך.** זה גר תושב האוכל נבלות: **אשר בארצך.** לרבות שכר בהמה וכלים:
@645 **ואליו הוא נשא את נפשו.** אל השכר הזה הוא נושא את נפשו למות, עלה בכבש ונתלה באילן: **והיה בך חטא.** מכל מקום, אלא שממהרין להפרע על ידי הקורא:
@646 **לא יומתו אבות על בנים.** בעדות בנים. ואם תאמר בעון בנים, כבר נאמר איש בחטאו יומתו, אבל מי שאינו איש, מת בעון אביו, הקטנים מתים בעון אבותם בידי שמים:
@647 **לא תטה משפט גר יתום.** ועל העשיר כבר הזהר (דברים טז, יט) לא תטה משפט, ושנה בעני לעבור עליו בשני לאוין, לפי שנקל להטות משפט עני יותר משל עשיר, לכך הזהיר ושנה עליו: **ולא תחבל.** שלא בשעת הלואה:
@648 **וזכרת.** על מנת כן פדיתיך לשמור חקותי אפלו יש חסרון כיס בדבר:
@649 **ושכחת עמר.** ולא גדיש. מכאן אמרו עמר שיש בו סאתים ושכחו אינו שכחה: **בשדה.** לרבות שכחת קמה ששכח מקצתה מלקצור: **לא תשוב לקחתו.** מכאן אמרו, שלאחריו שכחה, שלפניו אינו שכחה, שאינו בבל תשוב: **למען יברכך.** ואף על פי שבאת לידו שלא במתכון, קל וחמר לעושה במתכון. אמור מעתה, נפלה סלע מידו ומצאה עני ונתפרנס בה הרי הוא מתברך עליה:
@650 **לא תפאר.** לא תטול תפארתו ממנו. מכאן שמניחין פאה לאילן: **אחריך.** זו שכחה:
@651 **לא תעולל.** אם מצאת בו עוללות לא תקחנה. ואיזו היא עוללות כל שאין לה לא כתף ולא נטף. יש לה אחד מהם הרי היא לבעל הבית. וראיתי בתלמוד ירושלמי איזו היא כתף, פסיגין זה על גב זה. נטף, אלו התלויות בשדרה ויורדות:
@653 **כי יהיה ריב.** סופם להיות נגשים אל המשפט. אמור מעתה אין שלום יוצא מתוך מריבה, מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה: **והרשיעו את הרשע.** יכול כל המתחיבין בדין לוקין, תלמוד לומר והיה אם בן הכות הרשע, פעמים לוקה ופעמים אינו לוקה. ומי הוא הלוקה, למוד מן הענין (פסוק ד) , לא תחסם שור בדישו, לאו שלא נתק לעשה:
@654 **והפילו השפט.** מלמד שאין מלקין אותו לא עומד ולא יושב אלא מטה: **לפניו כדי רשעתו.** ולאחריו כדי שתים. מכאן אמרו, מלקין אותו שתי ידות מלאחריו ושליש מלפניו: **במספר.** ואינו נקוד במספר, למד שהוא דבוק, לומר במספר ארבעים ולא ארבעים שלמים, אלא מנין שהוא סוכם ומשלים לארבעים, והן ארבעים חסר אחת:
@655 **לא יסיף.** מכאן אזהרה למכה את חברו: **ונקלה אחיך.** כל היום קוראו רשע ומשלקה קראו אחיך:
@656 **לא תחסם שור בדישו.** דבר הכתוב בהוה והוא הדין לכל בהמה חיה ועוף העושים במלאכה שהיא בדבר מאכל. אם כן למה נאמר שור, להוציא את האדם: **בדישו.** יכול יחסמנו מבחוץ, תלמוד לומר לא תחסם שור מכל מקום, ולמה נאמר דיש, לומר לך מה דיש מיוחד דבר שלא נגמרה מלאכתו וגדולו מן הארץ, אף כל כיוצא בו, יצא החולב והמגבן והמחבץ שאין גדולו מן הארץ, יצא הלש והמקטף שנגמרה מלאכתו לחלה, יצא הבודל בתמרים ובגרוגרות שנגמרה מלאכתן למעשר:
@657 **כי ישבו אחים יחדו.** שהיתה להם ישיבה אחת בעולם, פרט לאשת אחיו שלא היה בעולמו: **יחדו.** המיוחדים בנחלה, פרט לאחיו מן האם: **ובן אין לו.** עין עליו: בן או בת, או בן הבן, או בת הבן, או בן הבת, או בת הבת:
@658 **והיה הבכור.** גדול האחים הוא מיבם אותה: **אשר תלד.** פרט לאילונית שאינה יולדת: **יקום על שם אחיו.** זה שיבם את אשתו יטול נחלת המת בנכסי אביו: **ולא ימחה שמו.** פרט לאשת סריס ששמו מחוי:
@659 **השערה.** כתרגומו לתרע בית דינא:
@660 **ועמד.** בעמידה: **ואמר.** בלשון הקדש, ואף היא דבריה בלשון הקדש:
@661 **וירקה בפניו.** על גבי קרקע: **אשר לא יבנה.** מכאן למי שחלץ שלא יחזור וייבם, דלא כתיב אשר לא בנה, אלא אשר לא יבנה, כיון שלא בנה שוב לא יבנה:
@662 **ונקרא שמו** וגו' **.** מצוה על כל העומדים שם לומר חלוץ הנעל:
@663 **כי ינצו אנשים.** סופן לבא ליד מכות, כמו שנאמר מיד מכהו. אין שלום יוצא מתוך ידי מריבה:
@664 **וקצתה את כפה.** ממון דמי בשתו. הכל לפי המביש והמתביש. או אינו אלא ידה ממש, נאמר כאן לא תחוס, ונאמר להלן בעדים זוממין (לעיל יט, יג) לא תחוס, מה להלן ממון, אף כאן ממון:
@665 **אבן ואבן.** משקלות: **גדולה וקטנה.** גדולה שמכחשת את הקטנה, שלא יהא נוטל בגדולה ומחזיר בקטנה:
@666 **לא יהיה לך.** אם עשית כן, לא יהיה לך כלום:
@667 **אבן שלמה וצדק יהיה לך.** אם עשית כן יהיה לך הרבה:
@669 **זכור את אשר עשה לך.** אם שקרת במדות ובמשקלות הוי דואג מגרוי האויב, שנאמר (משלי יא, א) מאזני מרמה תועבת ה', וכתיב בתריה בא זדון ויבא קלון:
@670 **אשר קרך בדרך.** לשון מקרה. דבר אחר לשון קרי וטמאה, שהיה מטמאן במשכב זכור. דבר אחר לשון קור וחום, צננך והפשירך מרתיחתך, שהיו כל האמות יראים להלחם בכם ובא זה והתחיל והראה מקום לאחרים. משל לאמבטי רותחת שאין כל בריה יכולה לירד בתוכה, בא בן בליעל אחד קפץ וירד לתוכה. אף על פי שנכוה, הקרה אותה בפני אחרים: **ויזנב בך.** מכת זנב, חותך מילות וזורק כלפי מעלה: **כל הנחשלים אחריך.** חסרי כח מחמת חטאם, שהיה הענן פולטן: **ואתה עיף ויגע.** עיף בצמא, דכתיב (שמות יז, ג) ויצמא שם העם למים, וכתיב אחריו ויבא עמלק: **ויגע.** בדרך: **ולא ירא.** עמלק, **אלהים' מלהרע לך**:
@671 **תמחה את זכר עמלק.** מאיש ועד אשה מעולל ועד יונק משור ועד שה (שמואל א' טו, ג) . שלא יהא שם עמלק נזכר אפלו על הבהמה, לומר בהמה זו משל עמלק היתה:
@672 **והיה כי תבוא וירשתה וישבת בה.** מגיד שלא נתחיבו בבכורים עד שכבשו את הארץ וחלקוה:
@673 **מראשית.** ולא כל ראשית, שאין כל הפרות חיבין בבכורים אלא שבעת המינין בלבד. נאמר כאן ארץ, ונאמר להלן (לעיל ח, ח) ארץ חטה ושערה וגו' , מה להלן משבעת המינים שנשתבחה בהם ארץ ישראל, אף כאן שבח ארץ ישראל שהן שבעה מינין: **זית שמן.** זית אגורי ששמנו אגור בתוכו: **ודבש.** הוא דבש תמרים: **מראשית.** אדם יורד לתוך שדהו ורואה תאנה שבכרה כורך עליה גמי לסימן ואומר הרי זו בכורים:
@674 **אשר יהיה בימים ההם.** אין לך אלא כהן שבימיך, כמו שהוא: **ואמרת אליו.** שאינך כפוי טובה: **הגדתי היום.** פעם אחת בשנה ולא שתי פעמים:
@675 **ולקח הכהן הטנא מידך.** להניף אותו. כהן מניח ידו תחת יד הבעלים ומניף:
@676 **וענית.** לשון הרמת קול: **ארמי אבד אבי.** מזכיר חסדי המקום. ארמי אבד אבי, לבן, בקש לעקור את הכל, כשרדף אחר יעקב. ובשביל שחשב לעשות, חשב לו המקום כאלו עשה, שאמות העולם חושב להם הקדוש ברוך הוא מחשבה רעה כמעשה: **וירד מצרימה.** ועוד אחרים באו עלינו לכלותנו, שאחרי זאת ירד יעקב למצרים: **במתי מעט.** בשבעים נפש:
@680 **אל המקום הזה.** זה בית המקדש: **ויתן לנו את הארץ.** כמשמעו:
@681 **והנחתו.** מגיד שנוטלו אחר הנחת הכהן ואוחזו בידו כשהוא קורא, וחוזר ומניף:
@682 **ושמחת בכל הטוב.** מכאן אמרו אין קורין מקרא בכורים אלא בזמן שמחה, מעצרת ועד החג, שאדם מלקט תבואתו ופירותיו ויינו ושמנו, אבל מהחג ואלך, מביא ואינו קורא: **אתה והלוי.** אף הלוי חיב בבכורים אם נטעו בתוך עריהם: **והגר אשר בקרבך.** מביא ואינו קורא, שאינו יכול לומר לאבותינו:
@683 **כי תכלה לעשר את כל מעשר תבואתך בשנה השלישית.** כשתגמור להפריש מעשרות של שנה השלישית, קבע זמן הבעור והוידוי בערב הפסח של שנה הרביעית, שנאמר (דברים יד, כח) מקצה שלש שנים תוציא וגו' . נאמר כאן מקץ, ונאמר להלן (שם לא, י) מקץ שבע שנים, לענין הקהל מה להלן רגל אף כאן רגל, אי מה להלן חג הסכות אף כאן חג הסכות, תלמוד לומר כי תכלה לעשר, מעשרות של שנה השלישית רגל שהמעשרות כלין בו, וזהו פסח, שהרבה אילנות יש שנלקטין אחר הסכות, נמצאו מעשרות של שלישית כלין בפסח של רביעית, וכל מי ששיהה מעשרותיו הצריכו הכתוב לבערו מן הבית: **שנת המעשר.** שנה שאין נוהג בה אלא מעשר אחד משני מעשרות שנהגו בשתי שנים שלפניה, ששנה ראשונה של שמטה נוהג בה מעשר ראשון, כמו שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל את המעשר, ומעשר שני, שנאמר (דברים יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך, הרי שני מעשרות, ובא ולמדך כאן בשנה השלישית שאין נוהג מאותן שני מעשרות אלא אחד, ואיזה, זה מעשר ראשון. ותחת מעשר שני תן מעשר עני שנאמר כאן **ונתת ללוי.** את אשר לו, הרי מעשר ראשון. **לגר ליתום ולאלמנה.** זה מעשר עני: **ואכלו בשעריך ושבעו.** תן להם כדי שבען מכאן אמרו אין פוחתין לעני בגורן פחות מחצי קב חטים וכו' :
@684 **ואמרת לפני ה' אלהיך.** התודה שנתת מעשרותיך: **בערתי הקדש מן הבית.** זה מעשר שני ונטע רבעי, ולמדך שאם שיהה מעשרותיו של שתי שנים ולא העלם לירושלים, שצריך להעלותם עכשיו: **וגם נתתיו ללוי.** זה מעשר ראשון. וגם, לרבות תרומה ובכורים: **ולגר ליתום ולאלמנה.** זה מעשר עני: **ככל מצותך.** נתתים כסדרן ולא הקדמתי תרומה לבכורים, ולא מעשר לתרומה ולא שני לראשון, שהתרומה קרויה ראשית, שהיא ראשונה משנעשה דגן, וכתיב מלאתך ודמעך לא תאחר (שמות כב, כח) , לא תשנה את הסדר: **לא עברתי ממצותיך.** לא הפרשתי ממין על שאינו מינו ומן החדש על הישן: **ולא שכחתי.** מלברך על הפרשת מעשרות:
@685 **לא אכלתי באני ממנו.** מכאן שאסור לאונן: **ולא בערתי ממנו בטמא.** בין שאני טמא והוא טהור, בין שאני טהור והוא טמא. והיכן הזהר על כך (לעיל יב, יז) לא תוכל לאכל בשעריך. זו אכילת טמאה, כמו שנאמר בפסולי המקדשים (לעיל טו, כב) בשעריך תאכלנו הטמא והטהור וגו' , אבל זה, לא תוכל לאכול דרך אכילת שעריך האמור במקום אחר: **ולא נתתי ממנו למת.** לעשות לו ארון ותכריכין: **שמעתי בקול ה' אלהי.** הביאותיו לבית הבחירה: **עשיתי ככל אשר צויתני.** שמחתי ושמחתי בו:
@686 **השקיפה ממעון קדשך.** עשינו מה שגזרת עלינו, עשה אתה מה שעליך לעשות, שאמרת (ויקרא כו, ג) אם בחקתי תלכו ונתתי גשמיכם בעתם: **אשר נתתה לנו כאשר נשבעת לאבתינו.** לתת לנו וקימת ארץ זבת חלב ודבש:
@687 **היום הזה ה' אלהיך מצוך.** בכל יום יהיו בעיניך חדשים, כאלו בו ביום נצטוית עליהם: **ושמרת ועשית אותם.** בת קול מברכתו הבאת בכורים היום, תשנה לשנה הבאה:
@688 **האמרת.** והאמירך (פסוק יח) אין להם עד מוכיח במקרא. ולי נראה שהוא לשון הפרשה והבדלה. הבדלתי לך מאלהי הנכר להיות לך לאלהים, והוא הפרישך אליו מעמי הארץ להיות לו לעם סגלה. ומצאתי להם עד, והוא לשון תפארת, כמו (תהלים צ''ד) יתאמרו כל פועלי און:
@689 **כאשר דבר לך.** (שמות יט, ה) והייתם לי סגלה:
@690 **ולהיתך עם קדש** וגו' **כאשר דבר.** (ויקרא כ, כו) והייתם לי קדושים:
@691 **שמר את כל המצוה.** לשון הוה גרדנ''ט בלע''ז (בעאבאכטענד) :
@692 **והקמת לך.** בירדן ואחר כך תוציא משם אחרות ותבנה מהן מזבח בהר עיבל. נמצאת אתה אומר, שלשה מיני אבנים היו, שנים עשר בירדן, וכנגדן בגלגל, וכנגדן בהר עיבל, כדאיתא במסכת סוטה (ל''ה) :
@698 **באר היטב.** בשבעים לשון:
@699 **הסכת.** כתרגומו: **היום הזה נהיית לעם.** בכל יום יהיו בעיניך כאלו היום באת עמו בברית:
@702 **לברך את העם.** כדאיתא במסכת סוטה (לב, א) ששה שבטים עלו לראש הר גרזים, וששה לראש הר עיבל, והכהנים והלוים והארון למטה באמצע. הפכו לוים פניהם כלפי הר גרזים ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' ואלו ואלו עונין אמן. חזרו והפכו פניהם כלפי הר עיבל ופתחו בקללה ואומרים, (פסוק טו) ארור האיש אשר יעשה פסל וגו' , וכן כלם עד (פסוק כו) ארור אשר לא יקים:
@706 **מקלה אביו.** מזלזל, לשון (לעיל כ''ה) ונקלה אחיך:
@707 **מסיג גבול.** מחזירו לאחוריו וגונב את הקרקע, לשון (ישעיה נט) והסג אחור:
@708 **משגה עור.** הסומא בדבר ומשיאו עצה רעה:
@714 **מכה רעהו בסתר.** על לשון הרע הוא אומר. ראיתי ביסודו של רבי משה הדרשן, אחד עשר ארורים יש כאן, כנגד אחד עשר שבטים. וכנגד שמעון לא כתב ארור, לפי שלא היה בלבו לברכו לפני מותו כשברך שאר השבטים, לכך לא רצה לקללו:
@716 **אשר לא יקים.** כאן כלל את כל התורה כלה וקבלוה עליהם באלה ובשבועה:
@720 **שגר אלפיך.** ולדות בקרך שהבהמה משגרת ממעיה: **ועשתרות צאנך.** כתרגומו. ורבותינו אמרו למה נקרא שמם עשתרות, שמעשירות את בעליהן ומחזיקות אותם כעשתרות הללו שהן סלעים חזקים:
@721 **ברוך טנאך.** פירותיך. דבר אחר טנאך דבר לח שאתה מסנן בסלים: **ומשארתך.** דבר יבש שנשאר בכלי ואינו זב:
@722 **ברוך אתה בבאך וברוך אתה בצאתך.** שתהא יציאתך מן העולם בלא חטא כביאתך לעולם:
@723 **ובשבעה דרכים ינוסו לפניך.** כן דרך הנבהלים לברוח, מתפזרין לכל צד:
@736 **המארה.** חסרון כמו (ויקרא יג, נב) צרעת ממארת: **המהומה.** שגוש קול בהלות:
@738 **בשחפת.** שבשרו נשחף ונפוח: **ובקדחת.** לשון (דברים לב, כב) כי אש קדחה באפי והיא אש של חולים מלויי''ד בלע''ז (פיעבערהימצע) שהיא חמה מאד: **ובדלקת.** חמה יותר מקדחת, ומיני חלאים הם: **ובחרחר.** חולי המחממו תוך הגוף וצמא תמיד למים ובלע''ז אישרדימינ''ט לשון (איוב ל, ל) ועצמי חרה מני חרב (ירמי' ו, כט) נחר מפוח מאש: **ובחרב.** יביא עליך גיסות: **שדפון וירקון.** מכות תבואה שבשדות: **שדפון.** רוח קדים אשלי''דה בלע''ז (זאננפערבראננט) : **ירקון.** יובש ופני התבואה מכסיפין ונהפכין לירקון קמ''א בלע''ז : **עד אבדך.** תרגום עד דתיבד, כלומר עד אבוד אותך שתכלה מאליך:
@739 **והיו שמיך אשר על ראשך נחשת.** קללות הללו משה מפי עצמו אמרן, ושבהר סיני מפי הקדוש ברוך הוא אמרן כמשמען, ושם נאמר (ויקרא כו, יד) ואם לא תשמעו לי, (ויקרא כו, כא) ואם תלכו עמי קרי, וכן הוא אומר (פסוק טו) בקול ה' אלהיך (פסוק כא) ידבק ה' בך, (פסוק כב) יככה ה'. הקל משה בקללותיו לאמרן בלשון יחיד. וגם כן בקללה זו הקל, שבראשונות הוא אומר (ויקרא כו, יט) את שמיכם כברזל ואת ארצכם כנחושה, שלא יהיו השמים מזיעין כדרך שאין הברזל מזיע, ומתוך כך יהא חורב בעולם והארץ תהא מזיעה כדרך שהנחשת מזיע, והיא מרקבת פירותיה, וכאן הוא אומר שמיך נחשת וארצך ברזל, שיהיו שמים מזיעין אף על פי שלא יריקו מטר, מכל מקום לא יהיה חורב של אבדן בעולם, והארץ לא תהא מזיעה כדרך שאין הברזל מזיע, ואין הפרות מרקיבין. ומכל מקום קללה היא, בין שהיא כנחשת בין שהיא כברזל, לא תוציא פרות, וכן השמים לא יריקו מטר:
@740 **מטר ארצך אבק ועפר.** זיקא דבתר מטרא, מטר יורד ולא כל צרכו ואין בו כדי להרביץ את העפר, והרוח באה ומעלה את האבק ומכסה את עשב הזרעים שהן לחים מן המים, ונדבק בהם ונעשה טיט ומתיבש, ומרקיבין:
@741 **לזעוה.** לאימה ולזיע, שיזועו כל שומעי מכותיך ממך, ויאמרו אוי לנו, שלא יבוא עלינו כדרך שבא על אלו:
@743 **בשחין מצרים.** רע היה מאד, לח מבחוץ ויבש מבפנים, כדאיתא בבכורות (מא, א) : **גרב.** שחין לח: **חרס.** שחין יבש כחרס:
@744 **ובתמהון לבב.** אוטם הלב אשטורדישו''ן בלע''ז [תדהמה] :
@745 **עשוק.** בכל מעשיך יהיה ערעור:
@746 **ישגלנה.** לשון שגל, פלגש, והכתוב כנהו לשבח, ישכבנה, ותקון סופרים הוא זה: **תחללנו.** בשנה הרביעית לאכול פריו:
@748 **וכלות אליהם.** מצפות אליהם שישובו ואינם שבים. כל תוחלת שאינה באה, קרויה כליון עינים:
@753 **לשמה.** אשטורדישו''ן [תדהמה] כל הרואה אותך ישום עליך: **למשל.** כשתבא מכה רעה על אדם, יאמרו זו דומה למכת פלוני: **ולשנינה.** לשון (לעיל ו, ז) ושננתם, ידברו בך, וכן תרגומו ולשועי, לשון ספור, ואשתעי:
@754 **יחסלנו.** יכלנו, ועל שם כך נקרא חסיל, שמכלה את הכל:
@756 **כי ישל.** ישיר פירותיו, לשון (לעיל יט, ה) ונשל הברזל:
@758 **יירש הצלצל.** יעשנו הארבה רש מן הפרי: **יירש.** יעני: **צלצל.** מין ארבה. ואי אפשר לפרש יירש לשון ירשה, שאם כן היה לו לכתוב יירש, ולא לשון הורשה וגירושין, שאם כן היה לכתוב יוריש:
@763 **מרב כל.** בעוד שהיה לך כל טוב:
@765 **כאשר ידאה הנשר.** פתאום, ודרך מצלחת, ויקלו סוסיו: **לא תשמע לשונו.** לא תכיר לשונו, וכן (ברא' מא) תשמע חלום לפתר אותו. וכן (שם מב) כי שומע יוסף אינטינדר''י בלע''ז [להבין] :
@768 **עד רדת חמתיך.** לשון רדוי וכבוש:
@769 **ואכלת פרי בטנך בשר בניך** וגו' **במצור.** מחמת שיהיו צרין על העיר ויהיה שם מצוק, עקת רעבון:
@770 **הרך בך והענג.** הוא הרך הוא הענוג, לשון פנוק. ומהתענג ומרך מוכיח עליהם ששניהם אחד, אף על פי שהוא מפנק ודעתו קצה בדבר מאוס, ימתק לו לרעבונו בשר בניו ובנותיו עד כי תרע עינו בבניו הנותרים מתת לאחד מהם מבשר בניו אחיהם אשר יאכל. דבר אחר הרך בך הרחמני ורך הלבב, מרב רעבנותם, יתאכזרו ולא יתנו מבשר בניהם השחוטים לבניהם הנותרים:
@772 **תרע עינה באיש חיקה ובבנה ובבתה.** הגדולים:
@773 **ובשליתה.** בניה הקטנים. בכלן תהא עינה צרה כשתאכל את האחד מלתן לאשר אצלה מן הבשר. נט **והפלא ה' את מכתך.** מפלאות ומבדלות משאר מכות: **ונאמנות.** ליסרך לקים שליחותן:
@776 **אשר יגרת מפניהם.** מפני המכות, כשהיו ישראל רואים מכות משנות הבאות על מצרים, היו יראים מהם שלא יבואו גם עליהם, תדע, שכן כתיב (שמות טו, כו) אם שמע וגו' כל המחלה אשר שמתי במצרים לא אשים עליך, אין מיראין את האדם אלא בדבר שהוא יגור ממנו:
@777 **יעלם.** לשון עליה:
@778 **ונשארתם במתי מעט תחת** וגו' **.** מועטין חלף מרבין:
@779 **כן ישיש ה'.** את אויביכם עליכם להאביד וגו' : **ונסחתם.** לשון עקירה וכן (משלי טו, כה) בית גאים יסח ה':
@780 **ועבדת שם אלהים אחרים.** כתרגומו, לא עבודת אלהות ממש, אלא מעלים מס וגולגליות לכומרי עבודה זרה:
@781 **לא תרגיע.** לא תנוח, כמו (ישעיה כח, יב) וזאת המרגעה: **לב רגז.** לב חרד, כתרגומו דחל, כמו (שם יד, ט) שאול מתחת רגזה לך, (שמות טו, יד) שמעו עמים ירגזון, (שמואל ב' כב, ח) מוסדות השמים ירגזו: **וכליון עינים.** מצפה לישועה ולא תבא:
@782 **חייך תלאים לך.** על הספק, כל ספק קרוי תלוי, שמא אמות היום בחרב הבאה עלינו. ורבותינו דרשו זה הלוקח תבואה מן השוק: **ולא תאמין בחייך.** זה הסומך על הפלטר:
@783 **בבקר תאמר מי יתן ערב.** ויהיה הערב של אמש. **ובערב תאמר מי יתן בקר.** של שחרית, שהצרות מתחזקות תמיד, וכל שעה מרבה קללתה משלפניה:
@784 **באניות.** בספינות, בשביה: **והתמכרתם שם לאיביך.** אתם מבקשים להיות נמכרים להם לעבדים ולשפחות: **ואין קנה.** כי יגזרו עליך הרג וכליון: **והתמכרתם.** בלע''ז איפורוונדרי''ץ וו''ש [ותמכרו עצמכם] . ולא יתכן לפרש והתמכרתם לשון ונמכרתם על ידי מוכרים אחרים, מפני שנאמר אחריו ואין קונה:
@785 **לכרת את בני ישראל.** שיקבלו עליהם את התורה באלה ובשבועה: **מלבד הברית.** קללות שבתורת כהנים שנאמרו בסיני:
@788 **ולא נתן ה' לכם לב לדעת.** להכיר את חסדי הקדוש ברוך הוא ולדבק בו: **עד היום הזה.** שמעתי שאותו היום שנתן משה ספר התורה לבני לוי, כמו שכתוב (לקמן לא, ט) ויתנה אל הכהנים בני לוי, באו כל ישראל לפני משה ואמרו לו, משה רבינו, אף אנו עמדנו בסיני וקבלנו את התורה ונתנה לנו, ומה אתה משליט את בני שבטך עליה, ויאמרו לנו יום מחר לא לכם נתנה, לנו נתנה. ושמח משה על הדבר, ועל זאת אמר להם היום הזה נהיית לעם וגו' (לעיל כז, ט) , היום הזה הבנתי שאתם דבקים וחפצים במקום:
@791 **ותבאו אל המקום הזה.** עתה אתם רואים עצמכם בגדלה וכבוד, אל תבעטו במקום ואל ירום לבבכם, ושמרתם את דברי הברית הזאת. דבר אחר ולא נתן ה' לכם לב לדעת, שאין אדם עומד על סוף דעתו של רבו וחכמת משנתו עד ארבעים שנה, ולפיכך לא הקפיד עליכם המקום עד היום הזה, אבל מכאן ואלך יקפיד ולפיכך (פסוק ח) **ושמרתם את דברי הברית הזאת** וגו' :
@794 **אתם נצבים.** מלמד שכנסם משה לפני הקדוש ברוך הוא ביום מותו להכניסם בברית: **ראשיכם שבטיכם.** ראשיכם לשבטיכם: **זקניכם ושטריכם.** החשוב חשוב קודם, ואחר כך כל איש ישראל:
@795 **מחטב עציך.** מלמד שבאו כנענים להתגיר בימי משה, כדרך שבאו גבעונים בימי יהושע. וזהו האמור בגבעונים (יהושע ט, ד) ויעשו גם המה בערמה, ונתנם משה חוטבי עצים ושואבי מים:
@796 **לעברך.** להיותך עובר בברית. ולא יתכן לפרשו כמו להעבירך, אלא כמו (לעיל ד, יד) לעשותכם אותם: **לעברך בברית.** דרך העברה, כך היו כורתים ברית, עושין מחצה מכאן ומחצה מכאן ועוברים בנתים, כמו שנאמר (ירמיה לד, יח) העגל אשר כרתו לשנים ויעברו בין בתריו:
@797 **למען הקים אתך היום לו לעם.** כל כך הוא נכנס לטרוח למען קים אתך לפניו לעם: **והוא יהיה לך לאלהים.** לפי שדבר לך ונשבע לאבותיך שלא להחליף את זרעם באמה אחרת, לכך הוא אוסר אתכם בשבועות הללו, שלא תקניטוהו אחר שהוא אינו יכול להבדל מכם. עד כאן פרשתי לפי פשוטו של פרשה. ומדרש אגדה, למה נסמכה פרשת אתם נצבים לקללות, לפי ששמעו ישראל מאה קללות חסר שתים, חוץ ממ''ט שבתורת כהנים, הוריקו פניהם ואמרו מי יוכל לעמוד באלו, התחיל משה לפיסם אתם נצבים היום, הרבה הכעסתם למקום ולא עשה אתכם כליה והרי אתם קימים לפניו: **היום.** כיום הזה שהוא קים והוא מאפיל ומאיר, כך האיר לכם וכך עתיד להאיר לכם, והקללות והיסורין מקימין אתכם ומציבין אתכם לפניו. ואף הפרשה של מעלה מזו פיוסין הם (לעיל פסוק א') , אתם ראיתם את כל אשר עשה. דבר אחר, אתם נצבים. לפי שהיו ישראל יוצאין מפרנס לפרנס ממשה ליהושע, לפיכך עשה אותם מצבה כדי לזרזם. וכן עשה יהושע, וכן שמואל (שמואל א' יב, ז) התיצבו ואשפטה אתכם, כשיצאו מידו ונכנסו לידו של שאול:
@799 **ואת אשר איננו פה.** ואף עם דורות העתידים להיות:
@800 **כי אתם ידעתם** וגו' **ותראו את שקוציהם.** לפי שראיתם האמות עובדי עבודה זרה ושמא השיא לב אחד מכם אותו ללכת אחריהם, פן יש בכם וגו' (פסוק יז) לפיכך אני צריך להשביעכם:
@801 **ותראו את שקוציהם.** על שם שהם מאוסים כשקצים: **גלליהם.** שמסרחים ומאוסין כגלל: **עץ ואבן.** אותן של עצים ושל אבנים ראיתם בגלוי, לפי שאין הגוים יראים שמא יגנבו, אבל של כסף וזהב, עמהם, בחדרי משכיתם הם, לפי שהם יראים שמא יגנבו:
@802 **פן יש בכם.** שמא יש בכם: **אשר לבבו פנה היום.** מלקבל עליו הברית: **שרש פרה ראש ולענה.** שרש מגדל עשב מר כגידין, שהם מרים, כלומר מפרה ומרבה רשע בקרבכם:
@803 **והתברך בלבבו.** לשון ברכה, יחשב בלבו ברכת שלום לעצמו לאמר, לא יבואוני קללות הללו, אך שלום יהיה לי: **והתברך.** בינדיר''א שי''י בלע''ז [יברך את עצמו] , כמו והתגלח והתפלל: **בשררות לבי אלך.** במראית לבי, כמו (במדבר כד, יז) אשורנו ולא קרוב, כלומר מה שלבי רואה לעשות: **למען ספות הרוה.** לפי שאוסיף לו פרענות על מה שעשה עד הנה בשוגג והייתי מעביר עליהם, וגורם עתה שאצרפם עם המזיד ואפרע ממנו הכל. וכן תרגם אנקלוס בדיל לאוספא ליה חטאי שלותא על זדנותא, שאוסיף לו אני השגגות על הזדונות: **הרוה.** שוגג שהוא עושה כאדם שכור שלא מדעת: **הצמאה.** שהוא עושה מדעת ובתאוה:
@804 **יעשן אף ה'.** על ידי כעס הגוף מתחמם והעשן יוצא מן האף, וכן (ש''ב כב, ט) עלה עשן באפו, ואף על פי שאין זו לפני המקום, הכתוב משמיע את האזן כדרך שהיא רגילה ויכולה לשמוע, כפי דרך הארץ: **וקנאתו.** לשון חמה אנפרטמינ''ט [חמה] אחיזת לבישת נקמה, ואינו מעביר על המדה:
@805 **הכתובה בספר התורה הזה.** ולמעלה הוא אומר (לעיל כח, סא) בספר התורה הזאת גם כל חלי וכל מכה וגו' , הזאת, לשון נקבה, מוסב על התורה. הזה, לשון זכר, מוסב על הספר, ועל ידי פסוק הטעמים הן נחלקין לשתי לשונות, בפרשת הקללות הטפחא נתונה תחת בספר, והתורה הזאת דבוקים זה לזה, לכך אמר הזאת, וכאן הטפחה נתונה תחת התורה, נמצא ספר התורה דבוקים זה לזה, לפיכך לשון זכר נופל אחריו, שהלשון נופל על הספר:
@810 **לא ידעום.** לא ידעו בהם גבורת אלהות: **ולא חלק להם.** לא נתנם לחלקם. ואונקלוס תרגם ולא אוטיבא להון, לא הטיבו להם שום טובה, ולשון לא חלק אותו אלוה שבחרו להם, לא חלק להם שום נחלה ושום חלק:
@812 **ויתשם ה'.** כתרגומו וטלטלנון, וכן (ירמיה יב, יד) הנני נותשם מעל אדמתם:
@813 **הנסתרת לה' אלהינו.** ואם תאמרו מה בידינו לעשות, אתה מעניש את הרבים על הרהורי היחיד, שנאמר (פסוק יז) פן יש בכם איש וגו' , ואחר כך (פסוק כא) וראו את מכות הארץ ההיא, והלא אין אדם יודע טמונותיו של חברו, אין אני מעניש אתכם על הנסתרות, שהן לה' אלהינו והוא יפרע מאותו יחיד, אבל הנגלות' לנו ולבנינו לבער הרע מקרבנו, ואם לא נעשה דין בהם יענשו הרבים. נקוד על לנו ולבנינו, לדרוש, שאף על הנגלות לא ענש את הרבים עד שעברו את הירדן, משקבלו עליהם את השבועה בהר גרזים ובהר עיבל, ונעשו ערבים זה לזה:
@816 **ושב ה' אלהיך את שבותך.** היה לו לכתוב והשיב את שבותך, רבותינו למדו מכאן שהשכינה כביכול שרויה עם ישראל בצרת גלותם, וכשנגאלין הכתיב גאלה לעצמו, שהוא ישוב עמהם. ועוד יש לומר, שגדול יום קבוץ גליות ובקשי, כאלו הוא עצמו צריך להיות אוחז בידיו ממש איש איש ממקומו, כענין שנאמר (ישעיה כז, יב) ואתם תלקטו לאחד אחד בני ישראל, ואף בגליות שאר האמות מצינו כן (ירמיהו מח, מז) ושבתי שבות מואב:
@824 **לא נפלאת היא ממך.** לא מכסה היא ממך, כמו שנאמר (דברים יז, ח) כי יפלא, ארי יתכסי, (איכה א, ט) ותרד פלאים, (איוב מ, יג) ותרד במטמוניות. מכסה, חבוש בטמון:
@825 **לא בשמים היא.** שאלו היתה בשמים, היית צריך לעלות אחריה וללמדה:
@827 **כי קרוב אליך.** התורה נתנה לכם בכתב ובעל פה:
@828 **את החיים ואת הטוב.** זה תלוי בזה, אם תעשה טוב הרי לך חיים, ואם תעשה רע הרי לך המות. והכתוב מפרש והולך היאך:
@829 **אשר אנכי מצוך היום לאהבה.** הרי הטוב, ובו תלוי: **וחיית ורבית.** הרי החיים:
@830 **ואם יפנה לבבך.** הרי הרע:
@831 **כי אבד תאבדון.** הרי המות:
@832 **העדתי בכם היום את השמים ואת הארץ.** שהם קימים לעולם וכאשר תקרה אתכם הרעה יהיו עדים שאני התריתי בכם בכל זאת. דבר אחר, העידתי בכם היום את השמים וגו' , אמר להם הקדוש ברוך הוא לישראל, הסתכלו בשמים שבראתי לשמש אתכם, שמא שנו את מדתם, שמא לא עלה גלגל חמה מן המזרח והאיר לכל העולם, כענין שנאמר (קהלת א, ה) וזרח השמש ובא השמש, הסתכלו בארץ שבראתי לשמש אתכם, שמא שנתה מדתה, שמא זרעתם אותה ולא צמחה, או שמא זרעתם חטים והעלתה שעורים, ומה אלו שנעשו לא לשכר ולא להפסד אם זוכין אין מקבלין שכר ואם חוטאין אין מקבלין פרענות, לא שנו את מדתם, אתם, שאם זכיתם תקבלו שכר, ואם חטאתם תקבלו פרענות על אחת כמה וכמה: **ובחרת בחיים.** אני מורה לכם שתבחרו בחלק החיים, כאדם האומר לחברו בחר לך חלק יפה בנחלתי, ומעמידו על חלק היפה ואומר לו, את זה ברור לך, ועל זה נאמר (תהלים טז, ה) ה' מנת חלקי וכוסי אתה תומיך גורלי, הנחת ידי על גורל הטוב לומר את זה קח לך:
@834 **וילך משה.** וגו' :
@835 **אנכי היום.** היום מלאו ימי ושנותי ביום זה נלדתי וביום זה אמות: **לא אוכל עוד לצאת ולבא.** יכול שתשש כחו, תלמוד לומר (דברים לד, ז) לא כהתה עינו ולא נס לחה. אלא מהו לא אוכל, איני רשאי, שנטלה ממני הרשות ונתנה ליהושע. דבר אחר, לצאת ולבא בדברי תורה, מלמד שנסתמו ממנו מסורות ומעינות החכמה: **וה' אמר אלי.** זהו פרוש לא אוכל עוד לצאת ולבא, לפי שה' אמר אלי:
@839 **לא ירפך.** לא יתן לך רפיון להיות נעזב ממנו:
@840 **כי אתה תבוא את העם הזה.** ארי את תיעול עם עמא הדין. משה אמר לו ליהושע, זקנים שבדור יהיו עמך, הכל לפי דעתן ועצתן, אבל הקדוש ברוך הוא אמר ליהושע, כי אתה תביא את בני ישראל אל הארץ אשר נשבעתי להם (דברים לא, כג) , תביא על כרחם, הכל תלוי בך, טול מקל והך על קדקדן. דבר אחד לדור, ולא שני דברים לדור:
@842 **ויכתב משה** וגו' **ויתנה.** כשנגמרה כלה, נתנה לבני שבטו:
@843 **מקץ שבע שנים.** בשנה ראשונה של שמטה, בשמינית. ולמה קורא אותה שנת השמטה, שעדין שביעית נוהגת בה, בקציר של שביעית היוצא למוצאי שביעית:
@844 **תקרא את התורה הזאת.** המלך היה קורא מתחלת אלה הדברים, כדאיתא במסכת סוטה (מא, א) , על בימה של עץ שהיו עושין בעזרה:
@845 **האנשים.** ללמוד: **והנשים.** לשמוע: **והטף.** למה בא, לתת שכר למביאיהם:
@847 **ואצונו.** ואזרזנו:
@849 **נכר הארץ.** גויי הארץ:
@850 **והסתרתי פני.** כמו שאיני רואה בצרתם:
@852 **את השירה הזאת.** (לקמן לב, א) האזינו השמים עד (לב, מג) וכפר אדמתו עמו:
@853 **ונאצוני.** והכעיסוני, וכן כל נאוץ לשון כעס:
@854 **וענתה השירה הזאת לפניו לעד.** שהתריתי בו בתוכה על כל המוצאות אותן: **כי לא תשכח מפי זרעו.** הרי זו הבטחה לישראל, שאין תורה משתכחת מזרעם לגמרי:
@856 **ויצו את יהושע בן נון.** מוסב למעלה כלפי שכינה, כמו שמפורש (פסוק כא) אל הארץ אשר נשבעתי (להם) :
@859 **לקח.** כמו (שמות כ) זכור, (דב' ה) שמור, (שמו''ב ג) הלוך: **מצד ארון ברית ה'.** נחלקו בו חכמי ישראל בבבא בתרא (יד, ב) . יש מהם אומרים דף היה בולט מן הארון מבחוץ ושם היה מנח. ויש אומרים מצד הלוחות היה מנח, בתוך הארון:
@861 **הקהילו אלי.** ולא תקעו אותו היום בחצוצרות להקהיל את הקהל, לפי שנאמר (במדבר י, ב) עשה לך, ולא השליט יהושע עליהם בחייו של משה. ואף בחייו נגנזו קודם יום מותו, לקים מה שנאמר (קהלת ח, ח) ואין שלטון ביום המות: **ואעידה בם את השמים ואת הארץ.** ואם תאמר הרי כבר העיד למעלה (לעיל ל, יט) העידתי בכם היום וגו' , התם לישראל אמר, אבל לשמים ולארץ לא אמר, ועכשיו בא לומר האזינו השמים וגו' :
@862 **אחרי מותי כי השחת תשחתון.** והרי כל ימי יהושע לא השחיתו, שנאמר (יהושע כד, לא) ויעבדו בני ישראל את ה' כל ימי יהושע, מכאן שתלמידו של אדם חביב עליו כגופו, שכל זמן שיהושע חי נראה למשה כאלו הוא חי:
@864 **האזינו השמים.** שאני מתרה בהם בישראל ותהיו אתם עדים בדבר (לעיל ל, יט) שכך אמרתי להם שאתם תהיו עדים, וכן ותשמע הארץ. ולמה העיד בהם שמים וארץ, אמר משה אני בשר ודם, למחר אני מת, אם יאמרו ישראל לא קבלנו עלינו הברית מי בא ומכחישם, לפיכך העיד בהם שמים וארץ, עדים שהן קימים לעולם. ועוד, שאם יזכו, יבואו העדים ויתנו שכרם, הגפן תתן פריה, והארץ תתן יבולה, והשמים יתנו טלם. ואם יתחיבו, תהיה בהם יד העדים תחלה (לעיל יא, יז) , ועצר את השמים ולא יהיה מטר והאדמה לא תתן את יבולה, ואחר כך ואבדתם מהרה על ידי האמות:
@865 **יערף כמטר לקחי.** זו היא העדות שתעידו שאני אומר בפניכם, תורה נתתי לישראל שהיא חיים לעולם כמטר זה שהוא חיים לעולם, כאשר יערפו השמים טל ומטר: **יערף.** לשון נטיפה וכן (לקמן לג, כח) יערפו טל, (תהלים סה, יב) ירעפון דשן: **תזל כטל.** שהכל שמחים בו, לפי שהמטר יש שהן עצבים, כגון הולכי דרכים ומי שהיה בורו מלא יין: **כשעירם.** לשון (תהלים קמח, ח) רוח סערה, כתרגומו כרוחי מטרא. מה הרוחות הללו מחזיקים את העשבים ומגדלין אותם, אף דברי תורה מחזיקין את לומדיהן ומגדלין אותם: **וכרביבים.** טפי מטר. ונראה לי על שם שיורה כחץ נקרא רביב, כמה דאת אמר (בראשית כא) רובה קשת: **דשא.** אדברי''ץ עטיפת הארץ מכסה בירק: **עשב.** קלח אחד קרוי עשב, וכל מין ומין לעצמו קרוי עשב:
@866 **כי שם ה' אקרא.** הרי כי משמש בלשון כאשר, כמו (ויקרא כג) כי תבאו אל הארץ, כשאקרא ואזכיר שם ה', אתם הבו גדל לאלהינו וברכו שמו. מכאן אמרו שעונין ברוך שם כבוד מלכותו אחר ברכה שבמקדש:
@867 **הצור תמים פעלו.** אף על פי שהוא חזק, כשמביא פרענות על עוברי רצונו, לא בשטף הוא מביא, כי אם בדין, כי תמים פעלו: **אל אמונה.** לשלם לצדיקים צדקתם לעולם הבא. ואף על פי שמאחר את תגמולם, סופו לאמן את דבריו: **ואין עול.** אף לרשעים משלם שכר צדקתם בעולם הזה: **צדיק וישר הוא.** הכל מצדיקים עליהם את דינו, וכך ראוי וישר להם. צדיק מפי הבריות. וישר הוא וראוי להצדיקו:
@868 **שחת לו** וגו' **.** כתרגומו חבילו להון ולא ליה: **בניו מומם.** בניו היו, והשחתה שהשחיתו היא מומם: **בניו מומם.** מומם של בניו היה ולא מומו: **דור עקש.** עקום ומעקל, כמו (מיכה ג, ט) ואת כל הישרה יעקשו, ובלשון משנה חלדה ששניה עקומות ועקושות: **ופתלתל.** אנטורטיליי''ש כפתיל הזה שגודלין אותו ומקיפין אותו סביבות הגדיל. פתלתל מן התבות הכפולות, כמו (ויקרא יג, מט) ירקרק, אדמדם, (תהלים לח, יא) סחרחר, (מלכים א' ז, כג) סגלגל:
@869 **הלי''י תגמלו זאת.** לשון תמה, וכי לפניו אתם מעציבין, שיש בידו לפרע מכם ושהטיב לכם בכל הטובות: **עם נבל.** ששכחו את העשוי להם: **ולא חכם.** להבין את הנולדות שיש בידו להטיב ולהרע: **הלא הוא אביך קנך.** שקנאך, שקננך בקן הסלעים ובארץ חזקה, שתקנך בכל מיני תקנה: **הוא עשך.** אמה באמות: **ויכננך.** אחרי כן בכל מיני בסיס וכן. מכם כהנים מכם נביאים ומכם מלכים, כרך שהכל תלוי בו:
@870 **זכר ימות עולם.** מה עשה בראשונים שהכעיסו לפניו: **בינו שנות דר ודר.** דור אנוש שהציף עליהם מי אוקינוס ודור המבול ששטפם. דבר אחר לא נתתם לבבכם על שעבר. בינו שנות דר ודר להכיר להבא שיש בידו להטיב לכם ולהנחיל לכם ימות המשיח והעולם הבא: **שאל אביך.** אלו הנביאים שנקראים אבות, כמו שנאמר באליהו (מלכים ב' ב, יב) אבי אבי רכב ישראל: **זקניך.** אלו החכמים: **ויאמרו לך.** הראשונות:
@871 **בהנחל עליון גוים.** כשהנחיל הקדוש ברוך הוא למכעיסיו את חלק נחלתן הציפן ושטפם: **בהפרידו בני אדם.** כשהפיץ דור הפלגה היה בידו להעבירם מן העולם ולא עשה כן, אלא יצב גבלת עמים קימם ולא אבדם: **למספר בני ישראל.** בשביל מספר בני ישראל שעתידים לצאת מבני שם, ולמספר שבעים נפש של בני ישראל שירדו למצרים, הציב גבולות עמים שבעים לשון:
@872 **כי חלק ה' עמו.** למה כל זאת, לפי שהיה חלקו כבוש ביניהם ועתיד לצאת. ומי הוא חלקו, עמו. ומי הוא עמו **יעקב חבל נחלתו.** והוא השלישי באבות, המשלש בשלש זכיות, זכות אבי אביו וזכות אביו וזכותו, הרי שלשה, כחבל הזה שהוא עשוי בשלשה גדילים והוא ובניו היו לו לנחלה, ולא ישמעאל בן אברהם, ולא עשו בן יצחק:
@873 **ימצאהו בארץ מדבר.** אותם מצא לו נאמנים בארץ המדבר, שקבלו עליהם תורתו ומלכותו ועלו, מה שלא עשו ישמעאל ועשו, שנאמר (לקמן לג, ב) וזרח משעיר למו הופיע מהר פארן: **ובתהו ילל ישימן.** ארץ ציה ושממה, מקום יללת תנינים ובנות יענה, אף שם נמשכו אחר האמונה, ולא אמרו למשה היאך נצא למדברות מקום ציה ושממון, כענין שנאמר (ירמיה ב, ב) לכתך אחרי במדבר: **יסבבנהו.** שם סבבם והקיפם בעננים וסבבם בדגלים לארבע רוחות וסבבן בתחתית ההר, שכפהו עליהם כגגית: **יבוננהו.** שם בתורה ובינה: **יצרנהו.** מנחש שרף ועקרב ומן האמות: **כאישון עינו.** הוא השחור שבעין, שהמאור יוצא המנו. ואונקלוס תרגם ימצאהו יספיקהו כל צרכו במדבר, כמו (במדבר יא, כב) ומצא להם, (יהושע יז, טז) לא ימצא לנו ההר: **יסבבנהו.** אשרינון סחור סחור לשכינתיה, אהל מועד באמצע וארבעה דגלים לארבע רוחות:
@874 **כנשר יעיר קנו.** ניהגם ברחמים ובחמלה, כנשר הזה רחמני על בניו ואינו נכנס לקנו פתאום, עד שהוא מקשקש ומטרף על בניו בכנפיו, בין אילן לאילן בין שוכה לחברתה, כדי שיעורו בניו, ויהא בהם כח לקבלו: **יעיר קנו.** יעורר בניו: **על גוזליו ירחף.** אינו מכביד עצמו עליהם אלא מחופף, נוגע ואינו נוגע, אף הקדוש ברוך הוא (איוב לז, כג) שדי לא מצאנהו שגיא כח, כשבא לתן תורה לא נגלה עליהם מרוח אחת אלא מארבע רוחות, שנאמר (לקמן לג, ב) ה' מסיני בא וזרח משעיר למו הופיע מהר פארן ואתה מרבבות קדש, (חבקוק ג, ג) . אלוה מתימן יבא, זו רוח רביעית: **יפרש כנפיו יקחהו.** כשבא לטלן ממקום למקום אינו נוטלן ברגליו כשאר עופות, לפי ששאר עופות יראים מן הנשר, שהוא מגביה לעוף ופורח עליהם, לפיכך נושאן ברגליו מפני הנשר, אבל הנשר אינו ירא אלא מן החץ לפיכך נושאן על כנפיו. אומר מוטב שיכנס החץ בי ולא יכנס בבני, אף הקדוש ברוך הוא (שמות יט, ד) ואשא אתכם על כנפי נשרים, כשנסעו מצרים אחריהם והשיגום על הים היו זורקים בהם חצים ואבני בליסטראות, מיד (שמות יד, יט. כ) ויסע מלאך האלהים וגו' ויבא בין מחנה מצרים וגו' :
@875 **ה' בדד ינחנו.** ניהגם במדבר בטח ובדד: **ואין עמו אל נכר.** לא היה כח באחד מכל אלהי הגוים להראות כחו ולהלחם עמהם. ורבותינו דרשוהו על העתיד, וכן תרגם אנקלוס. ואני אומר דברי תוכחה הם, להעיד השמים והארץ, ותהא השירה להם לעד שסופן לבגד ולא יזכרו הראשונות שעשה להם, ולא הנולדות שהוא עתיד לעשות להם, לפיכך צריך לישב הדבר לכאן ולכאן. וכל הענין מוסב על (פסוק ז) זכר ימות עולם בינו שנות דר ודר, כן עשה להם, וכן עתיד לעשות, כל זה היה להם לזכור:
@876 **ירכבהו על במותי ארץ.** כל המקרא כתרגומו: **ירכבהו** וגו' **.** על שם שארץ ישראל גבוה מכל הארצות: **ויאכל תנובת שדי.** אלה פרות ארץ ישראל שקלים לנוב ולהתבשל מכל פרות הארצות: **וינקהו דבש מסלע.** מעשה באחד שאמר לבנו בסיכני הבא לי קציעות מן החבית. הלך ומצא הדבש צף על פיה. אמר לו זו של דבש היא. אמר לו השקע ידך לתוכה ואתה מעלה קציעות מתוכה: **ושמן מחלמיש צור.** אלו זיתים של גוש חלב: **במותי ארץ.** לשון גבוה: **שדי.** לשון שדה: **חלמיש צור.** תקפו וחזקו של סלע. כשאינו דבוק לתבה של אחריו, נקוד חלמיש, (תהלים קיד, ח) וכשהוא דבוק, נקוד חלמיש:
@877 **חמאת בקר וחלב צאן.** זה היה בימי שלמה, שנאמר (מלכים א' ה, ג) עשרה בקר בראים ועשרים בקר רעי ומאה צאן: **עם חלב כרים.** זה היה בימי עשרת השבטים, שנאמר (עמוס ו, ד) ואוכלים כרים מצאן: **חלב כליות חטה.** זה היה בימי שלמה, שנאמר (מלכים א' ה, ב) ויהי לחם שלמה וגו' : **ודם ענב תשתה חמר.** בימי עשרת השבטים, (עמוס ו, ו) השתים במזרקי יין: **חמאת בקר.** הוא שומן הנקלט מעל גבי החלב: **וחלב צאן.** חלב של צאן, וכשהוא דבוק נקוד חלב כמו (שמות כג, יט) בחלב אמו: **כרים.** כבשים: **ואילים.** כמשמעו: **בני בשן.** שמנים היו: **כליות חטה.** חטים שמנים כחלב כליות וגסין ככוליא: **ודם ענב.** היה שותה יין טוב וטועם יין חשוב: **חמר.** יין בלשון ארמי: **חמר.** אין זה שם דבר, אלא לשון משבח בטעם אינו''ש בלע''ז . ועוד יש לפרש שני מקראות הללו אחר תרגום של אנקלוס, אשרינון על תוקפי ארעא וגו' :
@878 **עבית.** לשון עובי: **כשית.** כמו כסית, לשון (איוב טו, כז) כי כסה פניו בחלבו, כאדם ששמן מבפנים וכסליו נכפלים מבחוץ, וכן הוא אומר (שם) ויעש פימה עלי כסל: **כשית.** יש לשון קל בלשון כסוי, כמו (משלי יב, טז) וכסה קלון ערום ואם כתב כשית דגוש היה נשמע כסית את אחרים, כמו (איוב טו, כז) כי כסה פניו: **וינבל צור ישעתו.** גנהו ובזהו, כמו שנאמר (יחזקאל ח, טז) אחוריהם אל היכל ה' וגו' , אין לך נבול גדול מזה:
@879 **יקנאהו.** הבעירו חמתו וקנאתו: **בתועבת.** במעשים תעובים, כגון משכב זכור (ויקרא יח, כב) וכשפים (ויקרא יח, יב) , שנאמר בהם תועבה:
@880 **לא אלה.** כתרגומו דלית בהון צרוך, אלו היה בהם צורך לא היתה קנאה כפולה כמו עכשיו: **חדשים מקרוב באו.** אפלו האמות לא היו רגילים בהם. גוי שהיה רואה אותם, היה אומר זה צלם יהודי: **לא שערום אבתיכם.** לא יראו מהם לא עמדה שערתם מפניהם. דרך שערות האדם לעמוד מחמת יראה, כך נדרש בספרי. ויש לפרש עוד שערום לשון (ישעיה יג, כא) ושעירים ירקדו שם, שעירים הם שדים. לא עשו אבותיכם שעירים הללו:
@881 **תשי.** תשכח. ורבותינו דרשו, כשבא להיטיב לכם אתם מכעיסין לפניו ומתישים כחו מלהיטיב לכם: **אל מחללך.** מוציאך מרחם, לשון (תהלים כט, ט) יחולל אילות, (שם מח, ז) חיל כיולדה:
@883 **מה אחריתם.** מה תעלה בהם בסופם: **כי דור תהפכת המה.** מהפכין רצוני לכעס: **לא אמן בם.** אין גדולי נכרים בהם, כי הוריתים דרך טובה וסרו ממנה: **אמן.** לשון (אסתר ב, ז) ויהי אמן נורריטור''ה בלע''ז . דבר אחר אמן לשון אמונה, כתרגומו. אמרו בסיני (שמות כד, ז) נעשה ונשמע, ובשעה קלה בטלו הבטחתם ועשו העגל:
@884 **קנאוני.** הבעירו חמתי: **בלא אל.** בדבר שאינו אלוה: **בלא עם.** באמה שאין לה שם, שנאמר (ישעיה כג, יג) הן ארץ כשדים זה העם לא היה, ובעשו הוא אומר (עובדיה א, ב) בזוי אתה מאד: **בגוי נבל אכעיסם.** אלו המינים, וכן הוא אומר (תהלים יד, א) אמר נבל בלבו אין אלהים:
@885 **קדחה.** בערה: **ותיקד.** בכם עד היסוד: **ותאכל ארץ ויבלה.** ארצכם ויבולה: **ותלהט.** ירושלים המיסדת על ההרים, שנאמר (שם קכה, ב) ירושלים הרים סביב לה:
@886 **אספה עלימו רעות.** אחביר רעה על רעה לשון (ישעיה כט, א) ספו שנה על שנה, (לעיל כט, יח) ספות הרוה, (ירמיה ז, כא) עלותיכם ספו על זבחיכם. דבר אחר, אספה אכלה, כמו (בראשית יט, טו) פן תספה: **חצי אכלה בם.** כל חצי אשלים בהם. וקללה זו לפי הפרענות לברכה היא, חצי כלים והם אינם כלים:
@887 **מזי רעב.** אנקלוס תרגם, נפיחי כפן, ואין לי עד מוכיח עליו. ומשמו של רבי משה הדרשן מטולושא שמעתי שעירי רעב, אדם כחוש מגדל שער על בשרו: **מזי.** לשון ארמי שער מזיא, דהוה מהפך במזיא: **ולחמי רשף.** השדים נלחמו בהם, שנאמר (איוב ה, ז) ובני רשף יגביהו עוף, והם שדים: **וקטב מרירי.** וכריתות שד ששמו מרירי. קטב, כריתה, כמו (הושע יג, יד) אהי קטבך שאול: **ושן בהמת.** מעשה היה והיו הרחלים נושכין וממיתין: **חמת זחלי עפר.** ארס נחשים המהלכים על גחונם על העפר, כמים הזוחלים על הארץ. זחילה לשון מרוצת המים על העפר, וכן כל מרוצת דבר המשפשף על העפר והולך:
@888 **מחוץ תשכל חרב.** מחוץ לעיר תשכלם חרב גיסות: **ומחדרים אימה.** כשבורח ונמלט מן החרב, חדרי לבבו נקופים עליו מחמת אימה והוא מת והולך בה. דבר אחר ומחדרים אימה, שבבית תהיה אימת דבר, כמו שנאמר (ירמיה ט, כ) כי עלה מות בחלונינו, וכן תרגם אנקלוס. דבר אחר, מחוץ תשכל חרב על מה שעשו בחוצות, שנאמר (ירמיה יא, יג) ומספר חצות ירושלים שמתם מזבחות לבשת. ומחדרים אימה. על מה שעשו בחדרי חדרים, שנאמר (יחזק' ח, יב) אשר זקני בית ישראל עושים בחטף איש בחדרי משכיתו:
@889 **אמרתי אפאיהם.** אמרתי בלבי אפאה אותם. ויש לפרש אפאיהם, אשיתם פאה, להשליכם מעלי הפקר. ודגמתו מצינו בעזרא (נחמיה ט, כב) ותתן להם ממלכות ועממים ותחלקם לפאה, להפקר. וכן חברו מנחם. ויש פותרים אותו כתרגומו יחול רגזי עליהון, ולא יתכן, שאם כן היה לו לכתוב אאפאיהם אחת לשמוש ואחת ליסוד, כמו (ישעיה מה, ה) אאזרך, (איוב טז, ה) אאמצכם במו פי, והאל''ף התיכונה אינה ראויה בו כלל. ואונקלוס תרגם אחר לשון הבריתא השנויה בספרי, החולקת תיבה זו לשלש תיבות. אמרתי אף אי הם, אמרתי באפי אתנם כאלו אינם, שיאמרו רואיהם עליהם איה הם:
@890 **לולי כעס אויב אגור.** אם לא שכעס האויב כנוס עליהם להשחית ואם יוכל להם וישחיתם יתלה הגדלה בו ובאלהיו ולא יתלה הגדלה בי, וזהו שנאמר פן ינכרו צרימו, ינכרו הדבר לתלות גבורתי בנכרי, שאין הגדלה שלו: **פן יאמרו ידנו רמה** וגו' **.** כי אותו גוי אבד עצות המה:
@891 **ואין בהם תבונה.** שאלו היו חכמים, ישכילו זאת, איכה ירדף וגו' :
@892 **יבינו לאחריתם.** יתנו לב להתבונן לסוף פרענותם של ישראל:
@893 **איכה ירדף אחד.** ממנו אלף מישראל: **אם לא כי צורם מכרם וה' הסגירם.** מכרם ומסרם בידינו. דילבר''ר בלע''ז :
@894 **כי לא כצורנו צורם.** כל זה היה להם לאויבים להבין שהשם הסגירם ולא להם ולאלהיהם הנצחון, שהרי עד הנה לא יכלו כלום אלהיהם כנגד צורנו, כי לא כסלענו סלעם. כל צור שבמקרא לשון סלע: **ואיבינו פלילים.** ועכשיו אויבינו שופטים אותנו, הרי שצורנו מכרנו להם:
@895 **כי מגפן סדם גפנם.** מוסב למעלה. אמרתי בלבי אפאיהם ואשבית זכרם, לפי שמעשיהם מעשה סדום ועמורה: **שדמת.** שדה תבואה, כמו (חבקוק ג, יז) ושדמות לא עשה אכל, (מלכים ב' כג, ד) בשדמות קדרון: **ענבי רוש.** עשב מר: **אשכלת מררת למו.** משקה מר ראוי להם, לפי מעשיהם פרענותם. וכן תרגם אנקלוס ותשלמת עובדיהון כמררותהון:
@896 **חמת תנינם יינם.** כתרגומו. הא כמרת תניניא כס פרענותהון, הנה כמרירות נחשים כוס משתה פרענותם: **וראש פתנים.** כוסם, שהוא אכזר לנשוך. אויב אכזרי יבא ויפרע מהם:
@897 **הלא הוא כמס עמדי.** כתרגומו. כסבורים הם ששכחתי מעשיהם, כלם גנוזים ושמורים לפני: **הלא הוא.** פרי גפנם ותבואת שדמותם כמוס עמדי:
@898 **לי נקם ושלם.** עמי נכון ומזמן פרענות נקם וישלם להם כמעשיהם, הנקם ישלם להם גמולם. ויש מפרשים ושלם, שם דבר, כמו ושלום, והיא מגזרת והדבר אין בהם (ירמיה ה, יג) , כמו והדבור. ואימתי אשלם להם: **לעת תמוט רגלם.** כשתתום זכות אבותם שהן סמוכין עליו: **כי קרוב יום אידם.** משארצה להביא עליהם יום אידם קרוב ומזמן לפני להביא על ידי שלוחים הרבה: **וחש עתדות למו.** ומהר יבואו העתידות להם: **וחש.** כמו (ישעיה ה, יט) ימהר יחישה. עד כאן העיד עליהם משה דברי תוכחה להיות השירה הזאת לעד, כשתבא עליהם הפרענות, ידעו שאני הודעתים מראש. מכאן ואלך העיד עליהם דברי תנחומין שיבואו עליהם ככלות הפרענות ככל אשר אמר למעלה (ל, א ג) והיה כי יבאו עליך וגו' כל הדברים האלה הברכה והקללה וגו' ושב ה' אלהיך את שבותך וגו' :
@899 **כי ידין ה' עמו.** כשישפוט אותן ביסורין הללו האמורים עליהם, כמו (איוב לו, לא) כי בם ידין, ייסר עמים. כי, זה, אינו משמש בלשון דהא, לתת טעם לדברים של מעלה, אלא לשון תחלת דבור, כמו (ויקרא כה, ב) כי תבאו אל הארץ, כשיבואו עליהם משפטים הללו ויתנחם הקדוש ברוך הוא על עבדיו לשוב ולרחם עליהם: **יתנחם.** לשון הפך המחשבה להיטיב או להרע: **כי יראה כי אזלת יד.** כשיראה כי יד האויב הולכת וחוזקת מאד עליהם, ואפס בהם עצור ועזוב: **עצור.** נושע על ידי עוצר ומושל שיעצור בהם: **עזוב.** על ידי עוזב. עוצר הוא המושל העוצר בעם שלא ילכו מפזרים בצאתם לצבא על האויב. בלשון לע''ז מיינטינדו''ר . עצור, הוא הנושע במעצור המושל. עזוב, מחזק, כמו (נחמיה ג, ח) ויעזבו את ירושלים עד החומה, (ירמיה מט, כה) איך לא עזבה עיר תהלה. עצור מיינטינו''ד [נשלט] . עזוב אינפורצדו''ר [מבצר] :
@900 **ואמר.** הקדוש ברוך הוא עליהם: **אי אלהימו.** עבודה זרה שעבדו: **צור חסיו בו.** הסלע שהיו מתכסין בו מפני החמה והצנה, כלומר שהיו בטוחין בו להגן עליהם מן הרעה:
@901 **אשר חלב זבחימו.** היו אותן אלהות אוכלים, שהיו מקריבין לפניהם ושותין יין נסיכם: **יהי עליכם סתרה.** אותו הצור יהי לכם מחסה ומסתור:
@902 **ראו עתה.** הבינו מן הפרענות שהבאתי עליכם ואין לכם מושיע ומן התשועה שאושיעכם ואין מוחה בידי: **אני אני הוא.** אני להשפיל ואני להרים: **ואין אלהים עמדי.** עומד כנגדי למחות: **עמדי.** דגמתי וכמוני: **ואין מידי מציל.** הפושעים בי:
@903 **כי אשא אל שמים ידי.** כי בחרון אפי אשא ידי אל עצמי בשבועה: **ואמרתי חי אנכי.** לשון שבועה היא, אני נשבע חי אנכי:
@904 **אם שנותי ברק חרבי.** אם אשנן את להב חרבי, כמו (יחזקאל כא, טו) למען היה לה ברק שפלנדו''ר : **ותאחז במשפט ידי.** להניח מדת רחמים באויבי שהרעו לכם, (זכריה א, טו) אשר אני קצפתי מעט והמה עזרו לרעה. דבר אחר ותאחז ידי את מדת המשפט להחזיק בה ולנקום נקם: **אשיב נקם** וגו' **.** למדו רבותינו באגדה מתוך לשון המקרא, שאמר ותאחז במשפט ידי, לא כמדת בשר ודם מדת הקדוש ברוך הוא, מדת בשר ודם זורק חץ ואינו יכול להשיבו, והקדוש ברוך הוא זורק חציו ויש בידו להשיבם, כאלו אוחזן בידו, שהרי ברק הוא חצו, ונאמר כאן ברק חרבי ותאחז במשפט ידי, והמשפט הזה לשון פרענות הוא. בלע''ז יושטיצי''א :
@905 **אשכיר חצי מדם.** האויב: **וחרבי תאכל בשר.** בשרם: **מדם חלל ושביה.** זאת תהיה להם מעון דם חללי ישראל ושביה ששבו מהם: **מראש פרעות אויב.** מפשע תחלת פרצות האויב, כי כשהקדוש ברוך הוא נפרע מן האמות, פוקד עליהם עונם ועונות אבותיהם מראשית פרצה שפרצו בישראל:
@906 **הרנינו גוים עמו.** לאותו הזמן ישבחו האמות את ישראל ראו מה שבחה של אמה זו שדבקו בהקדוש ברוך הוא בכל התלאות שעברו עליהם ולא עזבוהו, יודעים היו בטובו ובשבחו: **כי דם עבדיו יקום.** שפיכות דמיהם כמשמעו: **ונקם ישיב לצריו.** על הגזל ועל החמס, כענין שנאמר (יואל ד, יט) מצרים לשממה תהיה ואדום למדבר שממה תהיה מחמס בני יהודה, ואומר (עובדיה א, י) מחמס אחיך יעקב וגו' : **וכפר אדמתו עמו.** ויפיס אדמתו ועמו על הצרות שעברו עליהם ושעשה להם האויב: **וכפר.** לשון רצוי ופיוס, כמו (בראשית לב, כא) אכפרה פניו, אניחניה לרגזיה: **וכפר אדמתו.** ומה היא אדמתו, **עמו.** כשעמו מתנחמים ארצו מתנחמת, וכן הוא אומר (תהלים פה, ב) רצית ה' ארצך, במה רצית ארצך, שבת שבות יעקב: בפנים אחרים היא נדרשת בספרי, ונחלקו בה ר' יהודה ור' נחמיה. ר' יהודה דורש כלה כנגד ישראל, ור' נחמיה דורש כלה כנגד האמות. רבי יהודה דורשה כלפי ישראל. **אמרתי אפאיהם, כמו שפירשתי עד ולא ה' פעל כל זאת. כי גוי אבד עצות המה.** אבדו תורתי שהיא להם עצה נכונה. **ואין בהם תבונה.** להתבונן. **איכה ירדף אחד מן האמות אלף מהם אם לא כי צורם מכרם, כי לא כצורנו צורם, הכל כמו שפרשתי עד תכליתו.** ור' נחמיה דורשה כלפי האמות. **כי גוי אבד עצות המה, כמו שפרשתי תחלה עד ואויבינו פלילים. כי מגפן סדום גפנם.** של אמות. **ומשדמת עמורה** וגו' **.** ולא ישימו לבם לתלות הגדלה בי. **ענבמו ענבי רוש.** הוא שאמר **לולי כעס אויב אגור על ישראל להרעילם ולהמרירם, לפיכך אשכלות מררת למו להלעיט אותם על מה שעשו לבני. חמת תנינם יינם.** מוכן להשקותם על מה שעושין להם. **כמוס עמדי.** אותו הכוס, שנאמר (תהלים עה, ט) כי כוס ביד ה' וגו' . **לעת תמוט רגלם.** כענין שנאמר (ישעיה כו, ו) תרמסנה רגל. **כי ידין ה' עמו.** בלשון זה משמש כי ידין בלשון דהא, ואין ידין לשון יסורין, אלא כמו כי יריב את ריבם מיד עושקיהם, **כי יראה כי אזלת יד** וגו' **. ואמר אי אלהימו.** האויב יאמר אי אלהימו של ישראל, כמו שאמר טיטוס הרשע כשגדר את הפרכת, כענין שנאמר (מיכה ז, י) ותרא אויבתי ותכסה בושה האמרה אלי איו ה' אלהיך. **ראו עתה כי אני** וגו' **.** אז יגלה הקדוש ברוך הוא ישועתו ויאמר ראו עתה כי אני אני הוא, מאתי באת עליהם הרעה, ומאתי תבא עליהם הטובה. **ואין מידי מציל.** מי שיציל אתכם מן הרעה אשר אביא עליכם. **כי אשא אל שמים ידי.** כמו כי נשאתי, תמיד אני משרה מקום שכינתי בשמים, כתרגומו אפלו חלש למעלה וגבור למטה, אימת העליון על התחתון, וכל שכן שגבור למעלה וחלש מלמטה. **ידי.** מקום שכינתי, כמו (במדבר ב, יז) איש על ידו, והיה בידי להפרע מכם, אבל אמרתי שחי אנכי לעולם, איני ממהר לפרוע, לפי שיש לי שהות בדבר, כי אני חי לעולם, ובדורות אחרונים אני נפרע מהם, והיכולת בידי להפרע מן המתים ומן החיים. מלך בשר ודם שהוא הולך למות, ממהר נקמתו להפרע בחייו, כי שמא ימות הוא או אויבו ונמצא שלא ראה נקמתו ממנו, אבל אני חי לעולם, ואם ימותו הם ואיני נפרע בחייהם, אפרע במותם. **אם שנותי ברק חרבי.** הרבה ''אם'' יש שאינם תלויין, כשאשנן ברק חרבי ותאחז במשפט ידי וכו' , כמו שפרשתי למעלה:
@907 **הוא והושע בן נון.** שבת של דיוזגי היתה, נטלה רשות מזה ונתנה לזה, העמיד לו משה מתרגמן ליהושע, שיהא דורש בחייו, כדי שלא יאמרו ישראל בחיי רבך לא היה לך להרים ראש. ולמה קוראו כאן הושע, לומר שלא זחה דעתו עליו, שאף על פי שנתנה לו גדלה, השפיל עצמו כאשר מתחלתו:
@909 **שימו לבבכם.** צריך אדם שיהיו עיניו ולבו ואזניו מכונים לדברי תורה, וכן הוא אומר (יחזקאל מ, ד) בן אדם ראה בעיניך ובאזניך שמע ושים לבך וגו' , הרי דברים קל וחמר, ומה תבנית הבית שהוא נראה לעינים ונמדד בקנה צריך אדם שיהיו עיניו ואזניו ולבו מכונים להבין, דברי תורה שהן כהררין התלויין בשערה על אחת כמה וכמה:
@910 **כי לא דבר רק הוא מכם.** לא לחנם אתם יגעים בה, כי הרבה שכר תלוי בה, כי הוא חייכם. דבר אחר, אין לך דבר ריקן בתורה שאם תדרשנו שאין בו מתן שכר, תדע לך שכן אמרו (בראשית לו, כב) ואחות לוטן תמנע, (שם לו, יב) ותמנע היתה פלגש וגו' לפי שאמרה איני כדאי להיות לו לאשה הלואי ואהיה פילגשו, וכל כך למה, להודיע שבחו של אברהם שהיו שלטונים ומלכים מתאוים להדבק בזרעו:
@911 **וידבר ה' אל משה בעצם היום הזה.** בשלשה מקומות נאמר בעצם היום הזה, נאמר בנח (שם ז, יג) בעצם היום הזה בא נח וגו' , במראית אורו של יום, לפי שהיו בני דורו אומרים בכך וכך אם אנו מרגישין בו אין אנו מניחין אותו לכנס בתבה, ולא עוד אלא אנו נוטלין כשילין וקרדמות ומבקעין את התבה. אמר הקדוש ברוך הוא הריני מכניסו בחצי היום, וכל מי שיש בידו כח למחות יבא וימחה. במצרים נאמר (שמות יב, נא) בעצם היום הזה הוציא ה', לפי שהיו מצרים אומרים בכך וכך אם אנו מרגישין בהם אין אנו מניחים אותם לצאת, ולא עוד אלא אנו נוטלין סיפות וכלי זין והורגין בהם. אמר הקדוש ברוך הוא הריני מוציאן בחצי היום וכל מי שיש בו כח למחות יבא וימחה. אף כאן, במיתתו של משה, נאמר בעצם היום הזה, לפי שהיו ישראל אומרים בכך וכך אם אנו מרגישין בו אין אנו מניחין אותו, אדם שהוציאנו ממצרים וקרע לנו את הים והוריד לנו את המן והגיז לנו את השלו והעלה לנו את הבאר ונתן לנו את התורה אין אנו מניחין אותו. אמר הקדוש ברוך הוא הריני מכניסו בחצי היום וכו' :
@913 **כאשר מת אהרן אחיך.** באותה מיתה שראית וחמדת אותה, שהפשיט משה את אהרן בגד ראשון והלבישו לאלעזר וכן שני וכן שלישי וראה בנו בכבודו. אמר לו משה, אהרן אחי, עלה למטה, ועלה. פשוט ידיך, ופשט. פשוט רגליך, ופשט. עצום עיניך, ועצם. קמוץ פיך, וקמץ. והלך לו. אמר משה אשרי מי שמת במיתה זו:
@914 **על אשר מעלתם בי.** גרמתם למעול בי: **על אשר לא קדשתם אותי.** גרמתם לי שלא אתקדש, אמרתי לכם (במדבר כ, ח) ודברתם אל הסלע, והם הכוהו, והצרכו להכותו פעמים, ואלו דברו עמו ונתן מימיו בלא הכאה, היה מתקדש שם שמים, שהיו ישראל אומרים ומה הסלע הזה שאינו לשכר ולא לפרענות, אם זכה אין לו מתן שכר, ואם חטא אינו לוקה, כך מקים מצות בוראו, אנו לא כל שכן:
@915 **כי מנגד.** מרחוק: **תראה** וגו' **.** כי אם לא תראנה עכשיו לא תראנה עוד בחייך: **ושמה לא תבוא.** וידעתי כי חביבה היא לך, על כן אני אומר לך עלה וראה:
@916 **וזאת הברכה** וגו' **לפני מותו.** סמוך למיתתו שאם לא עכשיו, אימתי:
@917 **ויאמר ה' מסיני בא.** פתח תחלה בשבחו של מקום ואחר כך פתח בצרכיהם של ישראל. ובשבח שפתח בו, יש בו הזכרת זכות לישראל, וכל זה דרך רצוי הוא, כלומר כדאי הם אלו שתחול עליהם ברכה: **מסיני בא.** יצא לקראתם כשבאו להתיצב בתחתית ההר כחתן היוצא להקביל פני כלה, שנאמר (שמות יט, יז) לקראת האלהים, למדנו שיצא כנגדם: **וזרח משעיר למו.** שפתח לבני עשו שיקבלו את התורה ולא רצו: **הופיע.** להם: **מהר פארן.** שהלך שם ופתח לבני ישמעאל שיקבלוה, ולא רצו: **ואתה.** לישראל: **מרבבת קדש.** ועמו מקצת רבבות מלאכי קדש, ולא כלם ולא רבם, ולא כדרך בשר ודם שמראה כל כבוד עשרו ותפארתו ביום חפתו: **אש דת.** שהיתה כתובה מאז לפניו באש שחורה על גב אש לבנה, נתן להם בלוחות כתב יד ימינו. דבר אחר, אש דת כתרגומו, שנתנה להם מתוך האש:
@918 **אף חבב עמים.** גם חבה יתרה חבב את השבטים. כל אחד ואחד קרוי עם, שהרי בנימין לבדו היה עתיד להולד כשאמר הקדוש ברוך הוא ליעקב (בראשית לה, יא) גוי וקהל גוים יהיה ממך: **כל קדשיו בידך.** נפשות הצדיקים הגנוזות אתו, כענין שנאמר (שמואל א' כה, כט) והיתה נפש אדני צרורה בצרור החיים את ה' אלהיך: **והם תכו לרגלך.** והם ראוים לכך, שהרי תכו עצמן לתוך תחתית ההר לרגלך בסיני. תכו לשון פעלו, התוכו לתוך מרגלותיך: **ישא מדברתיך.** נשאו עליהם עול תורתך: **מדברתיך.** המ''ם בו קרוב ליסוד, כמו (במדבר ז, פט) וישמע את הקול מדבר אליו, (יחזקאל ב, ב) ואשמע את מדבר אלי, כמו מתדבר אלי, אף זה מדברותיך מה שהיית מדבר להשמיעני לאמר להם. טיי''ש פורפרלידורי''ש בלע''ז . ואונקלוס תרגם שהיו נוסעים על פי דבריך, והמ''ם בו שמוש משמשת לשון מן. דבר אחר, אף חבב עמים, אף בשעת חבתם של אמות העולם שהראית להם פנים שוחקות ומסרת את ישראל בידם: **כל קדשיו בידך.** כל צדיקיהם וטוביהם דבקו בך ולא משו מאחריך ואתה שומרם: **והם תכו לרגלך.** והם מתמצעים ומתכנסים לתחת צלך: **ישא מדברתיך.** מקבלים גזרותיך ודתותיך בשמחה. ואלה דבריהם:
@919 **תורה.** אשר צוה לנו משה מורשה היא לקהלת יעקב, אחזנוה ולא נעזבנה:
@920 **ויהי.** הקדוש ברוך הוא: **בישרון מלך.** תמיד עול מלכותו עליהם: **בהתאסף.** בכל התאסף ראשי חשבון אסיפתם: **ראשי.** כמו (שמות ל, יב) כי תשא את ראש, ראויין אלו שאברכם. דבר אחר, בהתאסף, בהתאספם יחד באגדה אחת ושלום ביניהם הוא מלכם, ולא כשיש מחלוקת ביניהם:
@921 **יחי ראובן.** בעולם הזה: **ואל ימת.** לעולם הבא, שלא יזכר לו מעשה בלהה: **ויהי מתיו מספר.** נמנין במנין שאר אחיו, דגמא היא זו, כענין שנאמר (בראשית לה, כב) וישכב את בלהה ויהיו בני יעקב שנים עשר, שלא יצא מן המנין:
@922 **וזאת ליהודה.** סמך יהודה לראובן, מפני ששניהם הודו על קלקול שבידם, שנאמר (איוב טו, יח. יט) אשר חכמים יגידו וגו' להם לבדם וגו' ולא עבר זר בתוכם. ועוד פרשו רבותינו, שכל ארבעים שנה שהיו ישראל במדבר היו עצמות יהודה מתגלגלים בארון מפני נדוי שקבל עליו, שנאמר (בראשית מד, לב) וחטאתי לאבי כל הימים, אמר משה, מי גרם לראובן שיודה יהודה וכו' : **שמע ה' קול יהודה.** תפלת דוד ושלמה ואסא מפני הכושים, ויהושפט מפני העמונים, וחזקיה מפני סנחריב: **ואל עמו תביאנו.** לשלום מפני המלחמה: **ידיו רב לו.** יריבו ריבו וינקמו נקמתו: **ועזר מצריו תהיה.** על יהושפט התפלל על מלחמת רמות גלעד, (דה''ב יח, לא) ויזעק יהושפט וה' עזרו. דבר אחר, שמע ה' קול יהודה, כאן רמז ברכה לשמעון מתוך ברכותיו של יהודה, ואף כשחלקו ארץ ישראל נטל שמעון מתוך גורלו של יהודה שנאמר (יהושע יט, ט) מחבל בני יהודה נחלת בני שמעון. ומפני מה לא יחד לו ברכה בפני עצמו, שהיה בלבו עליו על מה שעשה בשטים, כן כתוב באגדת תהלים:
@923 **וללוי אמר.** ועל לוי אמר: **תמיך ואוריך.** כלפי שכינה הוא מדבר: **אשר נסיתו במסה.** שלא נתלוננו עם שאר המלינים: **תריבהו** וגו' **.** כתרגומו. דבר אחר, תריבהו על מי מריבה, נסתקפת לו לבוא בעלילה, אם משה אמר (במדבר כ, י) שמעו נא המורים, אהרן ומרים מה עשו:
@924 **האמר לאביו ולאמו לא ראיתיו.** כשחטאו בעגל ואמרתי (שמות לב, כו) מי לה' אלי, נאספו אלי כל בני לוי וצויתים להרוג את אבי אמו והוא מישראל, או את אחיו מאמו, או את בן בתו, וכן עשו. ואי אפשר לפרש אביו ממש ואחיו מאביו וכן בניו ממש, שהרי לוים הם ומשבט לוי לא חטא אחד מהם שנאמר כל בני לוי: **כי שמרו אמרתך.** (שמות כ, ב) לא יהיה לך אלהים אחרים: **ובריתך ינצרו.** ברית מילה, שאותם שנלדו במדבר, וישראל לא מלו את בניהם, והם היו מולין ומלין את בניהם:
@925 **יורו משפטיך.** ראויין אלו לכך: **וכליל.** עולה:
@926 **מחץ מתנים קמיו.** מחץ קמיו, מכת מתנים, כענין שנאמר (תהלים סט, כד) ומתניהם תמיד המעד, ועל המעוררין על הכהנה אמר כן. דבר אחר, ראה שעתידין חשמנאי ובניו להלחם עם היונים והתפלל עליהם לפי שהיו מועטים, שנים עשר בני חשמנאי ואלעזר כנגד כמה רבבות, לכך נאמר ברך ה' חילו ופעל ידיו תרצה: **ומשנאיו מן יקומון.** מחץ קמיו ומשנאיו מהיות להם תקומה:
@927 **לבנימן אמר.** לפי שברכת לוי בעבודת הקרבנות, ושל בנימין בבנין בית המקדש בחלקו, סמכן זה לזה, וסמך יוסף אחריו, שאף הוא משכן שילה היה בנוי בחלקו, שנאמר (שם עח, סז) וימאס באהל יוסף וגו' . ולפי שבית עולמים חביב משילה לכך הקדים בנימין ליוסף **חפף עליו.** מכסה אותו ומגין עליו: **כל היום.** לעולם, משנבחרה ירושלים, לא שרתה שכינה במקום אחר: **ובין כתפיו שכן.** בגובה ארצו היה, בית המקדש בנוי אלא שנמוך עשרים ושלש אמה מעין עיטם, ושם היה דעתו של דוד לבנותו, כדאיתא בשחיטת קדשים (זבחים נד, ב) אמרי נחתי ביה פורתא משום דכתיב ובין כתפיו שכן, אין לך נאה בשור יותר מכתפיו:
@928 **מברכת ה' ארצו.** שלא היתה בנחלת השבטים ארץ מלאה כל טוב כארצו של יוסף: **ממגד.** לשון עדנים ומתק: **ומתהום.** שהתהום עולה ומלחלח אותה מלמטה, אתה מוצא בכל השבטים ברכתו של משה מעין ברכתו של יעקב:
@929 **וממגד תבואת שמש.** שהיתה ארצו פתוחה לחמה וממתקת הפרות: **גרש ירחים.** יש פרות שהלבנה מבשלתן ואלו הן, קשואין ודלועין. דבר אחר גרש ירחים. שהארץ מגרשת ומוציאה מחדש לחדש:
@930 **ומראש הררי קדם.** ומבורכת מראשית בשול הפרות שהרריה מקדימין לבכר בשול פירותיהם. דבר אחר מגיד שקדמה בריאתן לשאר הרים: **גבעות עולם.** גבעות העושות פרות לעולם ואינן פוסקות מעוצר הגשמים:
@931 **ורצון שכני סנה.** כמו שוכן סנה ותהא ארצו מבורכת מרצונו ונחת רוחו של הקדוש ברוך הוא הנגלה עלי תחלה בסנה: **רצון.** נחת רוח ופיוס, וכן כל רצון שבמקרא: **תבואתה.** ברכה זו לראש יוסף: **נזיר אחיו.** שהפרש מאחיו במכירתו:
@932 **בכור שורו.** יש בכור שהוא לשון גדלה ומלכות, שנאמר (תהלים פט, כח) אף אני בכור אתנהו, וכן (שמות ד, כה) בני בכורי ישראל: **בכור.** מלך היוצא ממנו והוא יהושע: **שורו.** שכחו קשה כשור לכבש כמה מלכים: **הדר לו.** נתון לו שנאמר (במדבר כז, כ) ונתתה מהודך עליו: **וקרני ראם קרניו.** שור, כחו קשה, ואין קרניו נאות, אבל ראם, קרניו נאות, ואין כחו קשה, נתן ליהושע כחו של שור ויופי קרני ראם: **אפסי ארץ.** שלשים ואחד מלכים אפשר שכלם מארץ ישראל היו, אלא אין לך כל מלך ושלטון שלא קנה לו פלטרין ואחזה בארץ ישראל, שחשובה לכלם היא, שנאמר (ירמיה ג, יט) נחלת צבי צבאות גוים: **והם רבבות אפרים.** אותם המנגחים הם הרבבות שהרג יהושע, שבא מאפרים: **והם אלפי מנשה.** הם האלפים שהרג גדעון במדין, שנאמר (שופטים ח, י) וזבח וצלמנע בקרקר וגו' :
@933 **ולזבולן אמר.** אלו חמשה שבטים שברך באחרונה. זבולן גד דן נפתלי ואשר, כפל שמותיהם לחזקם ולהגבירם, לפי שהיו חלשים שבכל השבטים, הם הם שהוליך יוסף לפני פרעה, שנאמר ומקצה אחיו לקח חמשה אנשים (בראשית מז, ב) , לפי שנראים חלשים ולא ישים אותם לו שרי מלחמתו: **שמח זבולן בצאתך ויששכר באהלך.** זבולן ויששכר עשו שותפות, זבולן לחוף ימים ישכון ויוצא לפרקמטיא בספינות ומשתכר, ונותן לתוך פיו של יששכר והם יושבים ועוסקים בתורה, לפיכך הקדים זבולן ליששכר, שתורתו של יששכר על ידי זבולן היתה: **שמח זבולן בצאתך.** הצלח בצאתך לסחורה: **ויששכר.** הצלח בישיבת אהליך לתורה לישב ולעבר שנים ולקבע חדשים, כמו שנאמר (דה''א יב, לג) ומבני יששכר יודעי בינה לעתים, ראשיהם מאתים, ראשי סנהדראות היו עוסקים בכך. ועל פי קביעות עתיהם ועבוריהם:
@934 **עמים.** של שבטי ישראל: **הר יקראו.** להר המוריה יאספו, כל אסיפה על ידי קריאה היא ושם יזבחו ברגלים זבחי צדק: **כי שפע ימים יינקו.** יששכר וזבולן, ויהא להם פנאי לעסוק בתורה: **ושפני טמוני חול.** כסויי טמוני חול, טרית וחלזון וזכוכית לבנה היוצאים מן הים ומן החול, ובחלקו של יששכר וזבולן היה, כמו שאמרו במסכת מגלה (ו, א) זבולן עם חרף נפשו למות (שופטים ה, יח) משום דנפתלי על מרומי שדה, שהיה מתרעם זבולן על חלקו, לאחי נתת שדות וכרמים וכו' : **ושפני.** לשון כסוי, כמו שנאמר (מ''א ו, ט) ויספן את הבית, (שם ז, ג) וספן בארז, ותרגומו ומטלל בכיורי ארזא. דבר אחר, עמים הר יקראו, על ידי פרקמטיא של זבולן, תגרי אמות העולם באים אל ארצו, והוא עומד על הספר והם אומרים הואיל ונצטערנו עד כאן, נלך עד ירושלים ונראה מה יראתה של אמה זו, ומה מעשיה, והם רואים כל ישראל עובדים לאלוה אחד, ואוכלים מאכל אחד, לפי שהגוים אלוהו של זה לא כאלוהו של זה, ומאכלו של זה לא כמאכלו של זה, והם אומרים אין אמה כשרה כזו ומתגיירין שם, שנאמר שם יזבחו זבחי צדק: **כי שפע ימים יינקו.** זבולן ויששכר, הים נותן להם ממון בשפע:
@935 **ברוך מרחיב גד.** מלמד שהיה תחומו של גד מרחיב ועולה כלפי מזרח: **כלביא שכן.** לפי שהיה סמוך לספר, לפיכך נמשל כאריות, שכל הסמוכים לספר צריכים להיות גבורים: **וטרף זרוע אף קדקד.** הרוגיהן היו נכרין, חותכים הראש עם הזרוע במכה אחת:
@936 **וירא ראשית לו.** ראה לטול לו חלק בארץ סיחון ועוג, שהיא ראשית כבוש הארץ: **כי שם חלקת מחקק.** כי ידע אשר שם בנחלתו חלקת שדה קבורת מחוקק והוא משה: **ספון.** אותה חלקה ספונה וטמונה מכל בריה, שנאמר (לקמן לד, ו) ולא ידע איש את קבורתו: **ויתא.** גד: **ראשי עם.** הם היו הולכים לפני החלוץ בכבוש הארץ לפי שהיו גבורים, וכן הוא אומר (דברים ג, יח) ואתם תעברו חלוצים לפני אחיכם וגו' : **צדקת ה' עשה.** שהאמינו דבריהם ושמרו הבטחתם לעבור את הירדן עד שכבשו וחלקו. דבר אחר ויתא משה ראשי עם. צדקת ה' עשה, על משה אמור:
@937 **דן גור אריה.** אף הוא היה סמוך לספר לפיכך מושלו באריות: **יזנק מן הבשן.** כתרגומו, שהיה הירדן יוצא מחלקו ממערת פמיאס, והיא לשם, שהיא בחלקו של דן, שנאמר (יהושע יט, מז) ויקראו ללשם דן וזנוקו וקלוחו מן הבשן. דבר אחר, מה זנוק זה יוצא ממקום אחד ונחלק לשני מקומות, כך שבטו של דן נטלו חלק בשני מקומות. תחלה נטלו בצפונית מערבית עקרון וסביבותיה, ולא ספקו להם, ובאו ונלחמו עם לשם שהיא פמיאס והיא בצפונית מזרחית, שהרי הירדן יוצא ממערת פמיאס והוא במזרחה של ארץ ישראל, ובא מהצפון לדרום וכלה בקצה ים המלח, שהוא במזרח יהודה, שנטל בדרומה של ארץ ישראל, כמו שמפורש בספר יהושע, והוא שנאמר (שם יט, מז) ויצא גבול בני דן מהם ויעלו בני דן וילחמו עם לשם וגו' , יצא גבולם מכל אתו הרוח שהתחילו לנחול בו:
@938 **שבע רצון.** שהיתה ארצו שבעה כל רצון יושביה: **ים ודרום ירשה.** ים כנרת נפלה בחלקו ונטל מלא חבל חרס בדרומה לפרוש חרמים ומכמורות: **ירשה.** לשון צווי, כמו (דברים א, כא) עלה רש, והטעם של מעלה ברי''ש מוכיח, כמו ירש, ידע, לקח, שמע, כשמוסיף בו ה''א יהיה הטעם למעלה שמעה, ידעה, סלחה, לקחה אף כאן ירשה לשון צווי. ובמסורת הגדולה מצינו באלפא ביתא לשון צווי דטעמיהון מלעיל:
@939 **ברוך מבנים אשר.** ראיתי בספרי, אין לך בכל השבטים שנתברך בבנים כאשר, ואיני יודע כיצד: **יהי רצוי אחיו.** שהיה מתרצה לאחיו בשמן אנפיקינון ובקפלאות והם מרצין לו בתבואה. דבר אחר, יהי רצוי אחיו שהיו בנותיו נאות והוא שנאמר (דברי הימים א' ז, לא) הוא אבי ברזית, שהיו בנותיו נשואות לכהנים גדולים הנמשחים בשמן זית: **וטבל בשמן רגלו.** שהיתה ארצו מושכת שמן כמעין. ומעשה שנצטרכו אנשי לודקיא לשמן מנו להם פולמוסטום אחד וכו' , כדאיתא במנחות (פה, ב) :
@940 **ברזל ונחשת מנעלך.** עכשיו הוא מדבר נגד כל ישראל, שהיו גבוריהם יושבים בערי הספר ונועלים אותה שלא יוכלו האויבים לכנס בה כאלו היא סגורה במנעולים ובריחים של ברזל ונחשת. דבר אחר ברזל ונחשת מנעלך, ארצכם נעולה בהרים שחוצבין מהם ברזל ונחשת, וארצו של אשר היתה מנעולה של ארץ ישראל: **וכימיך דבאך.** וכימים שהם טובים לך, שהן ימי תחלתך, ימי נעוריך, כן יהיו ימי זקנתך, שהם דואבים זבים ומתמוטטים. דבר אחר, וכימיך דבאך וכימיך שהם טובים לך כמנין ימיך, כל הימים אשר אתם עושים רצונו של מקום, יהיו דבאך, שכל הארצות יהיו דובאות כסף וזהב לארץ ישראל, שתהא מבורכת בפירות. וכל הארצות מתפרנסות המנה וממשיכות לה כספם וזהבם אישקורונ''ט . הכסף והזהב כלה מהם, שהן מזיבות אותם לארצכם:
@941 **אין כאל ישרון.** דע לך ישורון שאין כאל בכל אלהי העמים, ולא כצורך צורם: **רכב שמים.** הוא אותו אלוה שבעזרך ובגאותו הוא רוכב שחקים:
@942 **מענה אלהי קדם.** למעון, הם השחקים לאלהי קדם, שקדם לכל אלהים וברר לו שחקים לשבתו ומעונתו, ומתחת מעונתו כל בעלי זרוע שוכנים: **זרעת עולם.** סיחון ועוג ומלכי כנען, שהיו תקפו וגבורתו של עולם, לפיכך על כרחם יחרדו ויזועו וכחם חלש מפניו. לעולם אימת הגבוה על הנמוך, והוא שהכח והגבורה שלו בעזרך: **ויגרש מפניך אויב.** ואמר לך השמד אותם: **מענה.** כל תיבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה:
@943 **בטח בדד.** כל יחיד ויחיד איש תחת גפנו ותחת תאנתו, מפזרין ואין צריכים להתאסף ולישב יחד מפני האויב: **עין יעקב.** כמו (במדבר יא, ז) ועינו כעין הבדלח, כעין הברכה שברכם יעקב, לא כבדד שאמר ירמיה (ירמיה טו, יז) בדד ישבתי, אלא כעין הבטחה שהבטיחם יעקב (בראשית מח, כא) והיה אלהים עמכם והשיב אתכם אל ארץ אבותיכם: **יערפו.** יטיפו: **אף שמיו יערפו טל.** אף ברכתו של יצחק נוספת על ברכתו של יעקב (שם כז, כח) ויתן לך האלהים מטל השמים וגו' :
@944 **אשריך ישראל.** לאחר שפרט להם הברכות אמר להם מה לי לפרוט לכם, כלל דבר, הכל שלכם: **אשריך ישראל מי כמוך.** תשועתך בה' אשר הוא מגן עזרך ואשר הוא וחרב גאותך: **ויכחשו איביך לך.** כגון הגבעונים שאמרו (יהושע ט, ט) מארץ רחוקה באו עבדיך וגו' : **ואתה על במותימו תדרך.** כענין שנאמר (שם י, כד) שימו את רגליכם על צוארי המלכים האלה:
@945 **מערבות מואב אל הר נבו.** כמה מעלות היו ופסען משה בפסיעה אחת: **את כל הארץ.** הראהו את כל ארץ ישראל בשלותה והמציקין העתידים להיות מציקין לה: **עד דן.** הראהו בני דן עובדים עבודה זרה שנאמר (שופטים יח, ל) ויקימו להם בני דן את הפסל, והראהו שמשון שעתיד לצאת ממנו למושיע:
@946 **ואת כל נפתלי.** הראהו ארצו בשלותה וחרבנה, והראהו דבורה וברק מקדש נפתלי נלחמים עם סיסרא וחילותיו: **ואת ארץ אפרים ומנשה.** הראהו ארצם בשלותה ובחרבנה והראהו יהושע נלחם עם מלכי כנען שבא מאפרים, וגדעון שבא ממנשה נלחם עם מדין ועמלק: **ואת כל ארץ יהודה.** בשלותה ובחרבנה והראהו מלכות בית דוד ונצחונם: **עד הים האחרון.** ארץ המערב בשלותה ובחרבנה. דבר אחר, אל תקרי הים האחרון אלא היום האחרון, הראהו הקדוש ברוך הוא כל המאורעות שעתידין לארע לישראל עד שיחיו המתים:
@947 **ואת הנגב.** ארץ הדרום. דבר אחר, מערת המכפלה, שנאמר (במדבר יג, כב) ויעלו בנגב ויבא עד חברון: **ואת הככר.** הראהו שלמה יוצק כלי בית המקדש, שנאמר (מ''א א' ז, מו) בככר הירדן יצקם המלך במעבה האדמה:
@948 **לאמר לזרעך אתננה הראיתיך.** כדי שתלך ותאמר לאברהם ליצחק וליעקב שבועה שנשבע לכם הקדוש ברוך הוא קימה, וזהו לאמר, לכך הראיתיה לך, אבל גזרה היא מלפני ששמה לא תעבר, שאלולי כך, הייתי מקיימך עד שתראה אותם נטועים וקבועים בה ותלך ותגיד להם:
@949 **וימת שם משה.** אפשר משה מת וכתב וימת שם משה, אלא עד כאן כתב משה, מכאן ואלך כתב יהושע. רבי מאיר אומר אפשר ספר התורה חסר כלום, והוא אומר (לעיל לא, כו) לקח את ספר התורה הזה, אלא הקדוש ברוך הוא אומר ומשה כותב בדמע: **על פי ה'.** בנשיקה:
@950 **וקבר אתו.** הקדוש ברוך הוא בכבודו. רבי ישמעאל אומר הוא קבר את עצמו, וזהו אחד משלשה אתין שהיה רבי ישמעאל דורש כן. כיוצא בו (במדבר ו, יג) ביום מלאת ימי נזרו יביא אתו, הוא מביא את עצמו. כיוצא בו (ויקרא כב, טז) והשיאו אותם עון אשמה, וכי אחרים משיאים אותם, אלא הם משיאים את עצמם: **מול בית פעור.** קברו היה מוכן שם מששת ימי בראשית לכפר על מעשה פעור, וזה אחד מן הדברים שנבראו בערב שבת בין השמשות:
@951 **לא כהתה עינו.** אף משמת: **ולא נס לחה.** לחלוחית שבו, לא שלט בו רקבון ולא נהפך תאר פניו:
@952 **בני ישראל.** הזכרים, אבל באהרן מתוך שהיה רודף שלום ונותן שלום בין איש לרעהו ובין אשה לבעלה נאמר (במדבר כ, כט) כל בית ישראל, זכרים ונקבות:
@954 **אשר ידעו ה' פנים אל פנים.** שהיה לבו גס בו ומדבר אליו בכל עת שרוצה, כענין שנאמר (שמות לב, ל) ועתה אעלה אל ה', (במדבר ט, ח) עמדו ואשמעה מה יצוה ה' לכם:
@956 **ולכל היד החזקה.** שקבל את התורה בלוחות בידיו: **ולכל המורא הגדול.** נסים וגבורות שבמדבר הגדול והנורא: **לעיני כל ישראל.** שנשאו לבו לשבור הלוחות לעיניהם, שנאמר (לעיל ט, יז) ואשברם לעיניכם, והסכימה דעת הקדוש ברוך הוא לדעתו, שנאמר אשר שברת, יישר כחך ששברת (שמות לד, א) :

@1 **במדבר בערבה מול סוף.** ראוי שלא יעלם ממנו שאי אפשר שתהיה הכוונ' בזה שדבר משה אל כל ישראל אלו הדברים באלו המקומות שזכר בהם הפסוק וזה כי כבר זכר אחר זה שאלה הדברים דבר משה בשנת הארבעי' בעשתי עשר חדש באחד לחדש אחרי הכותו את סיחון ועוג והנה היו אז ישראל בערבות מואב כמו שנזכר במה שקדם ולזה הוא מחוייב שיהיה הרצון שכבר דבר משה אל כל ישראל אלה הדברים והמקרי' שארעו להם באלו המקומו' כדי שיקבלו תוכחת וזה מבואר מהספורים שספר משה בזה הספר ולזה יהיה הרצון בזה אלה הדברים אשר דבר מה אל כל ישראל שקרו להם בעבר הירדן במדבר בערבה והוא מדבר שמרו פי יי' יתע' עצבו את רוח קדשו בכמה מקומות אלא שכפל הענין במלות שונות:
@1 **מול סוף.** שם מרו ועצבו את רוח קדשו כאמרו וימרו על ים בים סוף:
@1 **בין פארן.** ידוע כי במדבר פארן היו כשהיה דבר המרגלים אשר בו מרי עצום:
@1 **ובין תופל.** אחשוב שרמז בזה למה שעשו ישראל בשטים שנו ונצמדו לבעל פעור שהוא דבר בלי טעם רצוני לומר זאת הע"ז כי השכל מעיד בקלות על מומה והנה התפל הוא דבר שאין לו טעם. ואפשר שיהיה תופל שם כלל למשכן היה רחב השטים חלק ממנו:
@1 **ולבן.** הוא לבנה ואחשוב ששם היה מחלוקת קרח ושאר מה שחטאו ישראל אז אשר בא זכרו בפרשת קרח ולזה המשיך אליו זכרון החטא שחטאו בחצרות אהרן ומרי' מצד דברם במשה ולזה אמרו בזה הספר זכור את אשר עשה יי' למרים בדרך בצאתכם ממצרי':
@1 **ודי זהב.** גנה אותם על הספקתם הזהב במעשה העגל עם מה שהשתדל אהרן למנוע זה כמו שבארנו בפרשת כי תשא ולזה שאל שיתפרקו הנזמים אשר באזני נשיהם בניהם ובנותיהם אשר היה בו מהקושי העצום ועם כל זה מחרו להתפרק הנזמים אשר באזני נשיהם ובנותיהם ולזה גנה אותם משה על זה כי כבר נתב' ממנו עוצם תשוקתם לע"ז. ואפשר שנאמ' כי באומרו לבן הורה על תלונותיהם על המן שהיה כזרע גד לבן. והביאור הראשון נראה לנו יותר וכן אפשר שנאמ' כי באמרו ודי זהב הורה על שכבר נתרעמו מזולת סבה תביאם אל זה כי היה להם ספקם מזהב לקנות בו כל הקנינים שירצו כי כבר היה יי' יתעלה עמהם והוא ספק צרכם במדבר כל ימי עמדם שם:
@2 **אחד עשר יום מחורב דרך הר שעיר עד קדש ברנע.** ר"ל כי במהלך אחד עשר יום שהיה מחורב עד קדש ברנע כשילכו דרך הר שעיר קרו להם כל אלו המקרים הרעים שזכר משה:
@3 **ויהי בארבעים שנה בעשתי עשר חדש באחד לחדש.** אין הרצון בזה שיהיה אז דברי משה אלה הדברים אל כל ישראל כי אז מת אהרן כמו שנזכר בפרשת מסעי. ואחר מיתתתו היתה מלחמת מדין ואחריה מלחמת סיחון ואחריה מלחמת עוג. ולא יתכן שיהיה זה כלו ביום שמת אהרן ולזה הוא מבואר שהרצון בזה שבארבעים שנה לצאת בני ישרשאל בעשתי עשר חדש באחד לחדש הגיעו לצאת מקדש ובאו אז להר ההר ושם מת אהרן ביום ההוא כמו שנזכר בפרשת מסעי הנה מפני חטאיהם נתארך להם הזמן באלה המסעות עד שלא הלכו כי אם מהלך אחד עשר יום בכל זה הזמן:
@3 **דבר משה אל כל ישר' ככל אשר צוה יי' אתו אליהם.** אמר זה שלא יחשוב חושב שאלה הדברים אשר דבר משה לישראל הנזכרים באלה הדברים אמרם משה מפי עצמו לפי שלא נאמר בהם וידבר יי' אל משה ויאמר יי' אל משה כי כל אלו הדברים אמרם משה מפי הגבורה להוכיח ישראל ולהוסיף ביאור על דברי התורה ולהשלים המצוות בה כמו שאמר אחר זה:
@5 **בעבר הירדן בארץ מואב הואיל משה באר את התורה הזאת.** והנה זכר שאלה הדברים כלם אמרם משה אחרי מלחמת סיחון ועוג להעיר להם כי עונותיהם הטו עד שלא נכנסו לארץ תכף צאתם ממצרי' כי מעת שנבדלו מהחטאי' נצחו אלו המלכים החזקים עם היותם יושבים בערים בצורות וזכר כי יי' יתעלה אמר להם בחורב שלא יתעכבו עוד בהר חורב אך יסעו להם לבא לרשת ארץ ישראל בכללה כאשר נשבע לאבות ולהישיר עוד לזה השתדל משה שיהיו שופטים רבים על העם כמו שיעץ לו יתרו והסכים לו השם יתעלה כדי שינהיגו כלם כלל ישראל בהנהגה הראויה לפי משפטי התורה כי בזה יהיו יותר ראויים לירושת הארץ והנה מנה אותם קצתם בשררה גדולה עד שיהיו שרי אלפים לסבה שזכרנו בפרשת יתרו וקצתם שם שרי מאות וקצתם שרי חמשים וקצתם שרי עשרות והנה צוה אותם משה להתנהג בדרכי התורה בענין המשפט לא יטו ממנה. וצוה גם כן ישראל כל הדברים אשר ראוי להם לעשות כדי שתדבק בהם ההשגחה האלהית ויהיו יותר מוכנים לירושת הארץ. ואחר זה כשרצה הש' יתעלה להנחילם הארץ סבבו ישראל לשלח שם מרגלי' ושלחם שם משה לבקשת ישראל אחר שנמלך בזה בשם יתעלה כי הוא צוהו לשלח שם מרגלים כמו שנזכר בפרשת שלח לך ובחירת ישראל הרעה סבבה שנתאחרו אחר זה במדבר כל זה הזמן הארוך כי לא בטחו בשם יתעלה עם רוב הנפלאות שהראה להם במצרים ועל הים ובמדבר הנה זהו כלל הדברים האלה בקצרה:
@16 **שמוע בן אחיכם.** ר"ל שישמעו הריב בין אחיהם והם הטוען והנטען הישראלי' כדי שיעמדו על אמתת הדבר קודם שפטם ומזה המקום יתבאר שאין ראוי שישמעו דברי הריב אלא בין אחיהם אך לא ישמעו אחד מהם קודם בא חבירו כי זה אולי יביאם לשפוט שלא כדין כי צדיק הראשון בריבו ולא יצא הדיין מהאמנת מה שספר אליו הראשון כי אם בקושי עצום:
@16 **ושפטתם צדק.** בין איש ובין אחיו ובין גרו הוא מבואר שהוא הדין לאשה אך לפי שאין הנשים באות לדין כי אם על המעט לא זכר האשה ואולם הקטן לא ישפטו אותו שאין לו דעת לסדר טענותיו והתורה אמרה שמוע בין אחיכם:
@16 **ובין גירו.** ביאר שהוא הדין לגר צדק שנתגייר וקבל עליו לקיים כל התורה כי הוא כמו אחינו:
@17 **לא תכירו פנים במשפט.** למדנו מזה שאין ראוי לדיין לכבד אחד מהבעלי דינין בעניין שמיעת הדין יותר מחבירו כי זה אולי יביא לעות הדין ולזה אמר כקטן כגדול תשמעון:
@17 **לא תגורו מפני איש.** הוזהר הדיין שלא יטה משפטו מפני יראתם מהבעל דין שמא יזיקהו:
@17 **והדבר אשר יקשה מכם תקריבון אלי ושמעתיו.** הנה יקריבו הדבר הקשה למשה שלא נתבאר דינו בתורה והוא יבאר להם דינו מפי הגבורה לפרוש להם על פי יי':
@19 **ונסע מהר חורב ונלך את כל המדבר הגדול והנורא.** באר בזה מה שהיה להם לבטוח בעבורו בשם יתעלה בירושת הארץ כי הוא הוליכם בכל המדבר הגדול והנורא ההוא ולא חסרו בו דבר כי הוא הוציא להם דבש מסלע ושמן מחלמיש צור ועם כל זה לא היה האמנתם בו ולא שמעו ורצו לשלח שם מרגלים ואולי יספק מספק ויאמר איך אמר משה רבינו עליו השלום שהם אמרו לו נשלחה אנשי' לפנינו ויחפרו לנו את הארץ וכבר נתבאר בפרשת שלח לך שהשם יתעלה צוה זה למשה אלא שהתר זה הספק הוא ממה שיקל וזה כי מה שהיה סתום שם ביאר בזה המקום והנה התחלתה היתה מישראל והסכים השם יתעלה לעשות בקשתם כי לא היה בשלוח מרגלים מרי ולא היה ראוי גם כן שימשך ממנו מרי כי כבר ראו ישראל עוצם גבורת השם יתעלה לעשות כל אשר יחפוץ והנה המרי שנמשך ממנו היה מפני בחירת ישראל הרעה ולזה אמר משה ויטב הדבר בעיני כי לא היה מענינו שום מרי מצד עצמותו ושאם היה בו מרי לא היה השם יתעלה מסכים בו והנה זכר שהמרגלים השיבו דבר ואמרו כי טובה הארץ אשר יי' נותן להם ולא זכר בזה המקום שאר הדברים שאמרו קצתם להניא לב ישראל מההסכמה לעלות להלחם עמהם כי לא שולחו על אותם הדברים ולא היה לישראל להאמינם בזה כי עיניהם ראו גבורת השם ומופתיו הנפלאים שהתמידו להם ולזה אמר להם משה כי הם מרו את פי יי' כאשר לא אב לעלות כי איך שיהיה חוזק העם ההוא וחוזק המקומות שהיה יושב בהם היה להם לבטוח כי יד יי' יתעלה לא תקצר:
@27 **ותרגנו באהליכם.** היו מתקוטטים עם עצמם והיו אומרים אלו הדברים הקשים להניא לב כל בני ביתם ואומר לכם לא תערצון ולא תיראון מהם וגו'. הנה זכר להם משה רבוי הנפלאות שעשה יי' יתע' במצרים ובמדבר שם נשאם וכלכלם כאשר ישא איש את בנו והנהיג אותם שם בעמו' אש לילה ובענן יום לבקש להם מנוחה והיא ירושת הארץ כאומרו כי לא באתם עד עתה אל המנוחה ואל הנחלה:
@34 **וישמע יי' את קול דבריכם ויקצוף וגו' זולתי כלב בן יפונה הוא יראנה.** הנה לא זכר עמו יהושע אע"פ שהיה דבר השם יתעלה שלא ישאר מה זולתי כלב בן יפונה ויהושע בן נון לפי שהיה לכל אחד מהם דבר ייחדהו והו' כי לכלב אמר יי' יתע' לתת את הארץ אשר דרך בה והוא חברון וליהושע אמר יי' יתעלה שהוא ינחיל הארץ לישראל. ולזה הוא מבואר שגם הוא יחיה מהאנשים ההם התרים את הארץ:
@37 **גם בי התאנף יי' בגללכם לאמר גם אתה לא תבא שם.** הנה זכר זה בזה המקום ואף עלפי שהיה מפני דבר מי מריבה לפי שהוצרך להזכיר כי יהושע ינחיל הארץ לישראל וכבר ביארנו בפרשת פרה איך היה זה בסיבת ישראל והיה על צד העונש להם כמו שזכרנו שם:
@41 והנה זכר זה כי בשמעם זאת הגזרה הקשה מיי' יתע' נראו ממנה גם כן קצת קצף במגפה והוא מות מוציאי דבה תכף במגפה לפני יי' כמו שנזכר בפרשת שלח לך אז נתחרטו כאשר לא האמינו בשם יתע' והסכימו לעלות ולהלחם עם האמורי היושב בהר ושלח להם יי' יתעלה שלא ילחמו עמהם כי השגחתו אינה דבוקה בהם מצד עוצם מרים והם מרו שנית את פי יי' ועלו להלחם עם האמוריים אשר שם בהר ורדפו ישראל והכום בשעיר עד חרמה:
@45 **ותשובו ותבכו לפני יי'.** הנה מפני שזה הטוב לא היה ראוי לישר' אז אם לא מצד הדבק בהם ההשגחה הפרטית מהשם יתעלה והסירוה במרים לא הועיל להם בכותם לפני יי' להושיבה להם ולבטל הגזר' שגזר עליהם תחת מרים בדבר מהמרגלים עם שהש' יתעלה רצה ליסרם כדי שיקבלו מוסר לעתיד לטוב להם ולזה לא הסכים לבטל הגזרה הזאת בשום פנים:
@49 **רב לכם סוב את ההר הזה וגו'.** אמר זה כי אולי יחשוב חושב שעד סוף שנת הארבעים לא יתחילו להשתדל בירושת הארץ ולזה זכר יכ אף על פי שלא נשלמה השנה ההיא כיון שמתו כל האנשים שנגזרה עליהם הגזרה שלא יכנסו לארץ הנה רצה השם יתע' שיתחילו להשתדל בזה.
@51 והנה זכר כי השם יתעלה צוה לישראל שלא יתגרו למלחמה בבני עשו כי השם יתעלה לא יתן להם מארצם עד מדרך כף רגל ולזה לא יהיו נעזרים במלחמה ההיא מהשם יתעלה והנה אמר כי הם ייראו מאד מישראל להעיר אותם שאם לא יתנו אותם לעבר בגבולם בסב' יראתם מהם הנה עם כל זה ישמרו להלחם עמהם:
@51 **כי ירושה לעשו נתתי את הר שעיר.** הרצון בזה מפאת ההשגחה הכוללת אשר תמשך מהשם יתעלה מאומה אומה וצוה אותם שאם יעברו בו יקנו מאתם אוכל ומים לשתות ולא יקחו דבר בחזקה וכן מצאנו שעשו ישראל כי שלחו למלך אדום שיניהם לעבור בארצו ואמרו לו שאם ישתו מימיו יתנו מכרם וכאשר לא רצה זה מלך אדום נטו מגבולו כמו שנזכר בפרשת פרה:
@53 **כי יי' אלהיך ברכך וגו'.** ולזה אין לך לחוש אם תפזר מכספך מעט לתת לבני עשו באוכל ומים שתקנה מהם:
@55 **אל תצר את מואב.** הנה הסבה בזה היא הסבה בעינה שזכרנו בדבר בני עשו והנה צוה להם שלא ישימום במצור ולא יתגרו בם מלחמה וכן מנע זה מבני עמון וזכר שהמואבי' ירשו את ארצם מהאימים כי כן רצה יי' יתעלה מפאת ההשגחה הכוללת:
@58 **כאשר עשה ישראל לארץ ירושתו.** ר"ל ארץ סיחון ועוג ושאר המקומות אשר כבשו או שנתן הארץ ההיא יי' להם מצד השגחה הפרטית ולזה אמר בזה המקום אשר נתן יי' להם מה שלא אמר כן בירושת שעיר ומואב וירושת בני עמון והכפתורים להעיר על ההבדל בין ירושת הארץ לישראל ובין ירושת האומות כי הם היו מסודרו' מהשם יתעלה מפאת ההשגחה הכוללת וירושת ארץ ישראל מפאת ההשגחה הפרטית בזה המאמר אמר משה אחרי הכותו את סיחון ועוד כמו שנזכר בראש זאת הפרשה:
@60 **שלשים ושמנה שנה עד תום כל הדור.** ידוע כי שלוח המרגלים היה בשנה השנית לצאת בני ישראל ממצרים וכבר עבר מהשנה השנית קצתה כי היו ימי בכורי ענבים בעבור המרגלים בארץ ולזה לא נשארו עד ארבעים שנה פחות מה שנשאר מעת עבר' נחל זרד עד חש אחד אחר מות משה כי אם ל"ח שנה וקצת חדשי':
@61 **וגם יד יי' היתה בה להומם וגומ'.** הנה זכר שאעפ"י שהאריך להם הזמן עד סוף מ' שנה כדי שלא ימותו בלא עתם הנה סביב בא הזמן ההוא מהר יי' יתעלה להמית הנשארים קודם זה מעט כדי שיתחילו ישראל לרשת את הארץ אשר מעבר לירדן על יד משה לולי חטא העם כמו שזכרנו בפרשת פרה:
@65 **אל תצורם ואל תתגר בם מלחמה.** בל זה מבואר ממה שזכרנו בירושת מואב והנה המשיל ירושת בני עמון זאת הארץ אשר היה בה לירושת בני שעיר ולירושת הכפתורים כי כל אלו ההצלות הם מסוג אחד כי כולם היו מפאת ההשגחה הכוללת:
@70 **סעו ועברו את נחל ארנון.** הוא היה התחלת גבול בסיחון כמו שנתבאר בפרשת פרה:
@70 **ראה נתתי בידך את סיחון וגו'.** אין ראוי לספק איך שלח לו מש דברי שלום והשם יתעלה צוהו שיתגר בם מלחמה וזה כי הוא מבואר באופן כולל ממה שנזכר בפרשת שופטים כי גם ארץ כנען צוה השם יתעלה שכאשר יקרבו אל עיר להלחם עליה יקראו אליה לשלום ולזה הוא מבואר שרצון השם יתעלה היה שיקראו לו לשלום תחלה ולולי זה לא עשה משה ככה והנה זכר כי השם יתעלה הקשה רוחו ואמץ את לבבו לבלתי תתם לעבור בגבולו למען תתו ביד ישראל ולא היה בזה עול בחק השם יתעלה כמו שביאר בהקשת השם יתעלה את לב פרעה בפרת וארא. ורגזו וחלו מפניך הוא מעניין יראה כטעם רגזו ואל תחטאו חדלו רוגז:
@75 **כאשר עשו לי בני עשו היושבים בשעיר.** לפי שידענו שהוא לא אבה לתת ישראל עבור בגבולו למדנו מזה גם כן שהמואבים היושבים בער לא נתנום עבור בגבולם ומזה גם כן יתבא' שאמרו אכלה ער מואב ר"ל העם שיה יושב בה אז כמו שתרגם אנקלוס כי ער נשארה למואב כמו שיתבאר בה המקום ולזה יתבאר כי הדברים הקודמים לזה שלח לסיחון אך לא שלח לא זה המאמר ר"ל אמרו כאשר עשו לי בני עשו וגו'. והנה הרצון בו שכמו שעשו לי בני עשו והמואבים שלא נתנוני לעבור בגבולם עד אשר אעבור את הירדן כי לא שאלתי מהם כי אם דריסת הרגל לא אבה סיחון מלך חשבון העבירנו בו ותהיה וי"ו מולא אבה ללא עניין וכמוהו רבים או הרצון באמרו ולא אבה הנה לא אבה:
@83 **רק אל ארץ בני עמון לא קרבת.** כבר בארנו הסיבה בזה בפרשת פרה באמרו כי עז גבול בני עמון והאריך בכאן בעד מלחמות עוג לזכור הפרטים כי היה בענינה פלא עצום כי היו במלכותו ששים עיירות בצורות חומה גבוהה דלתים ובריח לבד מהעיירו' הבלתי מוקפות חומה שהיו הרבה מאוד וכבשום כולם בזמן קצר מאד כי משה לא יה אחרי אהרן כי אם חדש א' ובחלק קטן ממנו נעשה זה לפי מה שיתבאר מהדברים הרבים שעשה משה בזה הזמן:
@92 **צידוני' יקראו לחרמן שריון.** הנה דקדקה התורה בכל זה להוסיף אמות בזה הספור:
@94 **הנה ערשו ערש ברזל.** לכבדותו מצד כובד גופו נצטרך לנשאו במשכבו ערש ברזל תשע אמות ארכה וארבע אמות רחבה באמת איש. הנכון לפי הפשט כמו שזכר הרב המורה והוא מבואר כי אמרו באמת איש ירצה בו באמת האנשים והיא האמה הנהוגה שהיא אמת איש בינוני ולזה יהיה גובה עוג כמו שש אמות בינוניות או שבע או יותר מעט לפני הנהוג מאורך המטה יותר מאורך השוכב בה ואולם לרז"ל בזה המאמר על צד ההפלגה והגוזמא ויש לו פנים זולת מה שיובן ממנו להמון כמו שבארנו בביאורנו במסכת ברכות על מה שאמרו רז"ל עקר טורא בת תלתא פרסי:
@99 **ועד נחל ארנון תוך הנחל וגבול.** ר"ל שכבר נתן לו תוך הנחל שהוא גבול סיחון כי ארנון הוא גבול מאוב ועד יבוק הנחל גבול בני עמון הנה היה שם הנחל יבוק כאמרו ויעבר את מעבר יבק והיה הנחל ההוא גבול בני עמון:
@101 **ואצוה אתכם בעת ההיא לאמור.** לפי שהיו דבריו אל כל ישראל שהיו חלק מהם הראובני והגדי וחצי שבט המנשי הוצרך לדבר בשני השבטים וחצי לנוכח כי להם היה מדבר והנה הנשאר עד סוף הפרשה הוא מבואר:
@106 **ואתחנן אל יי' בעת ההיא עד אז יבדיל משה.** ענין התחנה הוא בקשה ותפילה:
@107 **אתה החלות להראות את עבדך וגומ'.** אמר החלות להעיר כי מה שהשיג מזה הוא שעור מעטי ביחס אל גודל השם יתעלה ועוצם ידו וכאלו הוא התחלה לבד לראיית אלו הדברים שזכר כי יותר ויותר לאין שעור יוכל השם יתעלה לעשות מהנפלאות:
@107 **אשר מי אל בשמים ובארץ.** אחשוב כי מלת מי מושכת עצמה ואחרת עמה והרצון בזה אשר מי בשמים ובארץ ומי אל אשר יעשה כמעשיך וכגבורותיך וביאור זה מי הוא זולתך שיהיה מנהיג השמים והארץ בכללות כי אתה לבדך הוא אלוהי השמים ואלהי הארץ כמו שאמ' אברהם וזה כי המלאכים יש להם הנהנה חלקית בשמים ובארץ אך ההנהגה הכוללת בהם הוא לשם יתעלה לבדו כמו שביארנו בחמישי מספר מ"י ומי אשר יעשה כמעשך וכגבורותיך כי המלאכים המניעים הגלגלים יעשו המסודר בהם לבד ולא ישנו את תפקיד' אך השם ית' עשה כל מה שירצה וישנה לפעמים הסדור המסודר מהמלאכי' ההם והוא גם כן עשאם כולם אחר שלא היו כמו שנזכר בפרש' בראשית ומאתו יסודרו כלל כל המעשים. או ירצה בזה מי באלהים בשמי' ובארץ והם המלאכים שיש להם הנהגה מה בשמי' ובארץ המניעים הגלגלים שיוכל לעשו' כמעשיך ובגבורותך וזה שהם לא יוכלו לעשו' כמעשיך כי מעשיך בהנהגת כלל העולם ומעשיהם הם בחלק מה ממנו ולא יוכלו לעשות בגבורותיך במה שתשתנה הסדורים המתחייבים מהם בעשותך הנפלאות והם לא ישנו את תפקידם. ואם באלו שהם היותר נכבדים לא יהיה שישוה לך בזה כ"ש שלא ימצא זה במי שלמטה מהם:
@108 **אעברה נא ואראה את הארץ הטובה אשר בעבר הירדן.** ביאר בזה שארץ ישראל טובה מכל הארצות וענין הטוב אשר בה הוא יתרון הכנה אל שישפע בה השפע האלהי כמו שזכרנו בפרשת שלח לך. ולזה יהיה חושק משה לראות הארץ להוסיף לו שלמות על שלמותו בנבואה ובחכמה:
@108 **ההר הטוב הזה והלבנון.** ידוע כי יער הלבנון היה בהר המוריה ושם היה בית המקדש והנה העי' בזה שזה המקום הוא היותר הנכון שבארץ ישראל ולזה אמר יעקב עליו אין זה כי אם בית אלהים וזה שער השמים. להורות על יתרון הכנת זה המקום אל שישפע בו השפע האלהי ולזה אמר דוד ולציון יאמר איש ואיש יולד בה והוא יכוננה עליון:
@109 **ויתעבר יי' בי למענכם.** כבר ביארנו בפרשת פרה איך היתה הגזרה הזאת על משה בעון ישראל. ויאמר יי' אלי רב לך. ר"ל רב לך חכמה ושפע נבואה במה שהשגת עד שלא יהוה נביא אחר כמך ולזה אין צורך לך לבא בארץ לזאת הסבה כי כבר זכית באלה המעלות למה שלא זכה אחר:
@110 **עלה ראש הפסגה.** כי מה שחשקת לראות את הארץ מצד ידיעתך פריה וטובה הנה תוכל לראותה מראש הפסגה כשתעיין שם לפאת מערב ולפאת צפון ולפאת דרום ולפאת מזרח:
@111 **וצו את יהושע וחזקהו ואמצהו וגו'.** הצואות הם איך יתנהג יהושע במה שיעשהו בהנחילו הארץ לישראל והחזוק והאמוץ ההוא הוא שלא יירא מהמלכיות ההם ושיתחזק ללכת בדרכי התורה:
@112 **ונשב בגאי מול בית פעור.** ר"ל שאז ישכנו בגאי מול בית פעור כשהיה זה והנה זכר זה בעבור מי שיספר אחר זה מענין לכת ישראל אחרי בעל פעור:
@113 **ועתה ישראל שמע אל החקים ואל המשפטים.** הנה החקים מה שאין טעמם מבואר והמשפטים מה שהדין נותן והשכל ישפטהו:
@113 **למען תחיון ובאתם וירישתם.** מגיד שהתועלת בשמיעת אל החקים ואל המשפטים שצוה השם יתעלה הוא השגת החיים האמתיים ראשונה ובעצמות ואולם בשנית ימשך מהתועלת שירשו הארץ:
@114 **לא תוסיפו מן הדבר אשר אנוכי מצוה אתכם.** הזהיר בזה המקום שלא להוסיף דבר על מצות התורה ושלא לגרוע מהם כדי שישמרו מצות התורה בכללם ולזה הוא מבואר שההוספת במצות שיהיה תכלית לשמור מצות התורה לא נמנעה וההוספה במצות שיהיה תכלית לשמור מצות התורה לא נמנעה וההוספת שתכליתה אין לשמור מצות התורה לא נמנעה וכן הענין בגרעון משל ההוספה שאינה לשמור מצות התורה אך להפך כי התורה התירה בעילת אשת יפת תואר אשר ישבנה במלחמה בתנאים שנזכרו בפרשת כי תצא ואם יוסיפו על זאת המצוה ויעשו זה הדין ביפת תואר שלא ישבנה במלחמה הנה זאת ההוספה הוא כנגד כונת התורה וכן אם לוקחו על ארבעה מינים שבלולב מין או מינין אחרים כי אז תפסד כונת התורה. וכן אם חדשו מצוה יש בה קצת הריסת כונת התורה משל ההוספה שהיא לשמור כונת התורה הגדרים שהוסיפו חכמים כמו אמירה לגוי בשבת שהוא שבות ושלא להכין בי"ט להאכיל את הגוי ומה שידמה לזה ויש ג"כ שם קצת מצו' מדרבנן כמו נר חנוכה וקריאת מגלה והכונה בזה ההמשך לכונת התורה שהשתדלה במקומות רבים לפרסם הניסים להוסיף אמונה בשם יתעלה משל הגרעון שאינו לשמור כונת התורה כאלו תאמר שגרעו ממצות יבום וחליצה ויתקנו שאם לא יחפוץ ליבם תהיה אשת המת מותרת לאחר בלא חליצה או שיגרעו כל זאת המצוה בכללה והנה ירבו המשלים על זה משל הגרעון שהוא לשמור כונת התורה שאם יתקנו שתהיה מצות חליצה קודמת למצות יבום מפני ראותם שכונת היבום אינה לשם שמים במייבמים או אם יתקנו שיהיה אסור לבא על יפת תואר קודם שנתגיירה והוא מבואר שלא יוכלו לגרוע מצוה בכללה לשמור כונת התורה ולפי שהוא אפשר שיחשוב חושב שכבר תשלם כונת התורה בזולת המצוה התלויה בארץ אחר שאין נוהגות בכל מושבו' והתורה ראוי שתהיה השלמת התועלת למקיימים אותה באי זה מקום שיהיה הוסיף להזהיר על דבר המצות ההם כאמרו ראה למדתי אתכם חקים ומשפטים כאשר צוני יי' אלהי לעשות כן בקרב הארץ אשר אתם באים שמה לרשתה והם הקרבנות והטמאות והטהרות ומתנות כהונה ולויה:
@115 **עיניכם הרואות את כל אשר עשה יי' בבעל פעור.** ירצה לפי מה שאחשוב שראוי לכם להיות זהירים מאד שלא לפרוץ ולצאת מכוונת התורה כי אתם ראיתם כי אשר היו מכם רודפים אחר הזנות עם בנות מואב שהיו עובדות בבעל פעור השמידו השם יתעלה מקרבך עד שכבר מתו כלם ואתם שהייתם דבקים ביי' ולא רדפתם אחר הזנות חיים כלכם היום לא נפקד איש מאשר לא נמשכו לזה הפועל המגונה וזה ממה שיורה שזה הענין לא היה במקרה כי לא יתכן מה שבקרי שיסכים בכמו זה הרבוי כי מה שבקרי הוא מעטי:
@117 **ראה למדתי אתכם חקים ומשפטים.** כבר זכרנו הסבה למה הוצרך לשנות זה המאמר אשר נכללו בו המצו' התלויות בארץ:
@118 **ושמרתם ועשיתם כי היא חכמתכם ובינתכם.** כבר ביארנו אופן החכמה אשר נשיג בעניין הטמאות והטהרות והקרבנות ומתנות כהונה ולויה מצד היותם בשעור שהוגבלו בו ולזה אמר כי הוא חכמתכם ובינתכם לעיני העמים כי מאלו הדברים נעמוד על חכמת הנמצאות כמו שביארנו:
@118 **אשר ישמעון את כל החקים האלה.** ר"ל אשר יבינו את דבר כל החקים האלה או ירצה בזה כי מי שישמור כל החקים האלה יכיר תכף אופן החכמה בהם מצד מה שהובדל הדבר בהם בקצת הדברים מקצת וכאלו תאמר שהיתה טמאת השרץ למטה מטומאת נבלת הבהמה וטמאת נבלת הבהמה למטה מטומאת נבלת האדם כי זה ממה שיביא להכיר כי בחכמה נפלאה סודר זה הנימוס התוריי:
@119 **כי מי גוי גדול אשר לו אלהים קרובים אליו.** הרצון בזה כי הגוים מצד היותם תחת ההשגחה הכוללת לבד לא יהיו נעזרים מהשם יתעלה רק בטובות המסודרות מצד השגחה ההיא אבל ישראל שהם תחת ההשגחה הפרטית הם נעזרים בכל מה שיבקשו מהשם יתעלה וזהו אמרו בכל קראנו אליו רוצה לומר בכל מה שנשאל ממנו:
@120 **ומי גוי גדול אשר לו חקים ומשפטים וגו'.** אמנם אמר זה לפי שתורתנו השלמה היא מסודרת על צד היושר והחכמו' ולזה לא תכב' על מקיימ' כי עצם דברי ה' גוזר על ההמשך אחריהם ואין העניין כן בתורות שאר האומות ונימוסיהם שאינם מסודרים מהיושר והחכמה ויעמיסו עם זה על בני הנימוס דברי' יכבדו מאד כאמרו כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם:
@121 **רק השמר לך ושמור נפשך מאד וגו'.** הרצון בזה שישמרו נפשם שלא ישכחו מעמד הר סיני הנפלא אשר העיד על היות התורה מסודרת מהשם יתעלה כי כל העם ראו את הקולות ואת הלפידים ושאר המופתים שנעשו שם ולזה צוה אותם שיודיעו זה לבניהם דור אחר דור כי זאת היא פנה גדולה בענין התורה:
@124 **קול דברים אתם שומעים ותמונה אינכם רואים זולתי קול.** הנה אמר זה להרחיק התמונה מהשם יתעלה כי אינו בעל גוף שתהיה לו תמונה ואותי צוה יי' בעת ההיא ללמד אתכם וגו'. הנה רמז בזה מה שנאמר שם למשה ואלה המשפטי' אשר תשים לפניהם ויתר המצות שנאמרו שם למשה אשר קצתם אינם נוהגות אלא בארץ:
@127 **ונשמרתם מאד לנפשותיכם.** רוצה לומר שתשמרו מזה בעבור נפשותיכם שיאבדו בזה החטא רצוני לומר אם תתנו תמונה לשם יתעלה:
@128 **פן תשחיתון ועשיתם וגו' תמונת כל סמל.** הוא כמו צלם תבנית זכר או נקבה ירצה לפי מה שאחשוב תבנית איש או אשה ואחר זה ירד מהדרגה וזכר תחלה הב"ח ההולך ואחר זכר תבנית המעופף ואחריו תבנית הדגה ושם רמש האדמה בין המעופף והדג לפי שהוא יותר פחות במציאותו מהמעופף ולזה תמצא ברבים מהם שהם מולידים ביצה בלתי שלמה כמו הענין בדגים:
@131 **ופן תשא עיניך השמימה וראית את השמש וגומ'.** רוצה לומר כי כשתראה ותתבונן בענין הכוכבים אשר ישפיע השם יתעלה באמצעותם הרבה מהנמצאות השפלות וסודרו מה' הרבה מהמקרים והמשיגים אשר יקרו לאומה אומה אולי תטעה ותתן להם אלהות או אחד מהם והשתחוית להם ועבדתם כמו שעשו הרבה מהקודמים והזכיר השמש תחלה כי פעולותיו יותר גלויות בענינים הקודמים והטבעים ואחריו היה הירח בזה הענין ואחריהם כוכבי לכת ושאר הכוכבים אחריהם והנה אמר כי זה עם שהוא טעות לכל האנשים אשר יתנו להם אלהות הוא טעות יותר נפלא לישראל וזה כי שאר האומות חלק להם השם יתעלה אלו הכוכבים ולזה אפשר להם לטעות לעשות אלוה מהכוהב המושל עליהם כאלו תאמר שעם כך תחת ממשלת כוכב פלוני ולפי הוראתו לטוב או לרע יהיה ענין האומה ההיא על הרוב ואין הענין כן בישראל כי הם אינם תחת ממשלת הכוכבים כי השם יתעלה לקחם והוציאם מכור הברזל ממצרים להיות לו לעם נחלה במה שמשך אותם לאמונתו ועבודתו בעניין הנפלאות והמופתים שחדש בהוציאו אותם מארץ מצרים ובתורתו השלמה שנתן להם ומפני זה אין ישראל תחת ממשלת הכוכבי' כי השגחת השם יתעלה דבקה בהם מזה הצד:
@133 **ויי' התאנף בי** גללכם. כבר בארנו למה הוצרך משה לומ' להם בכל פעם שזה העונש השיגהו מצדם והנה הורך להזכיר זה בזה המקום להודיע להם שהוא משתדל שאחר מותו לא יעשו זה העון הנפלא רוצה לומר לעבוד עבודה זרה ולזה הודיעם בזה המקום שהוא מת בארץ ההיא אך הם יעברו את הירדן והוכיחם והזהירם שלא ישכחו את יי' מרוב הטובה שתהיה להם שם ויעבדו עבודה זרה אשר צוה הש' יתעלה שלא יעבדוה כי השם יתעלה יעניש עובדי עבודה זרה עונש נפל כמו האש שתשחית כל מה שתלקח בו כן ישחיתם:
@137 **כי תוליד בנים ובני בנים ונושנתם בארץ וגומר.** רה איך ראתה התורה עבוד ישראל עבודה זרה אחר שארכו להם הימים בארץ והתחכם השם יתעלה לפי מה שאפשר להצילם מזה:
@138 **העידותי בכם היום את השמים ואת הארץ.** לפי שהשמים והארץ עומדים לעולם וקיימים נתנם עדים על זה הייעוד הרע להעיד שכבר נתקיים להם זה הייעוד:
@139 **והפיץ יי' אתכם בעמים וגו'.** הנה עונותיהם הטו שכבר נתקיים זה הייעוד הרע בגלות עשרת השבטים שלא נשאר מהם כי אם מתי מספ' כמו שנזכר בספר מלכי' ובגלות ראשון שגלו לבבל והוכרחו שם להשתחוות לצלם כמו שנזכר בספר דניאל ואליהם ידמה שרמז בזה המקום וכבר נתקיים קצתו בימי השופטים ומצאנו כי תכף שהיו מבקשים את יי' בכל לבבם ובכל נפשם היה השם יתע' שולח להם מושיע כמו שנזכר בספר שופטים:
@142 **בצר לך ומצאוך כל הדברים האלה באחרית הימים.** בז המקום רמז אל הגלות הזה הארוך אשר אנחנו בו היום נפוצים בעמים בחטאינו ובעונות אבותינו ולזה אמר באחרית הימים להעיר על שזה יהיה אחר זמן ארך אורך נפלא:
@142 **ושבת עד יי' אלהיך ושמעת בקולו.** רוצה לומ' שאז תשוב אל השם יתעלה ותקיים מצותיו והנה השם יתעלה אל רחום לא יסור השגחתו ממך מכל וכל:
@143 **ולא ישחיתך.** השחתה כוללת על עונותיך ולא ישכח את ברית אבותיך אשר נשבע להם לתת לזרעם אחריהם ארץ כנען ומבריתו את האבות יתחייב שלא יכלה אתכם כי תופר בריתו בזה. העניין והראיה לך על שומרי בריתו את האבות הנפלאות אשר עשה לך בצאתך ממצרים שלא היו מצד זכותך שתדבק בך כמו זאת ההשגחה הנפלאה אבל יהיו מצד ברית השם יתעלה עם האבות כמו שנתבאר בפרשת ואלה שמות:
@144 **כי שאל נא לימים ראשונים.** אם קרה כך מעת בריאת העולם באחד ממקומות הארץ שישמע עם קול אלהים מדבר מתוך האש כמו ששמעת אתה במעמד הר סיני כי זה דבר לא נהיה כלל והיה גם כן מן הפלא שהיית אחר דבר אלהיך עמך וכבר היה מפורסם אז כי מי שיראה אלו המראות הנפלאות ימות תכף ולזה אמר יעקב כי ראיתי אלהים פנים אל פנים ותנצל נפשי ואם נסה השם יתעל לקחת לו גוי מקרב גוי על ידי נפלאות רבות המספר כמו שעשה לך השם יתעלה בהוציאו אותך ממצרים ועיניך רואות והנה עשה זה השם יתעלה מצד בריתו עם האבות כמו שזכרנו להביא אותך למדרגה שתאמין בשם יתעל אתה הראית אלו הנפלאות לתכלית שתדע כי יי' הוא האלהים והוא שליט בארץ כמו שהוא שליט בשמים וכבר עמדת על זה מצד הפלאות שחדש לך בארץ כי זה מופת כי ליי' הארץ:
@147 **אין עוד מלבדו.** שלא יחשוב חושב כי יש אלהים בשמים מנהיג השמים ויש אל אחר בארץ מנהיג הארץ כי זה הוא שקר אך השם יתעלה הוא המנהיג השמים והארץ אין עוד מלבדו וכבר יעיר על זה כי השם יתעלה שנה הסדורים אשר בארץ מפאת הכוחות השופעות שם מהגלגלים וזה דבר לא יכול עליו אם לא היה שליט בשמים ובארץ וזה ממה שצריך אל ביאור יותר רחב אך במה שזכרנו בו די לזאת הכונה בזה הביאור כי לא יכול האריכות הצריך בזה ובמה שידמה לו:
@148 **מן השמים השמיעך את קולו ליסרך.** רוצה לומר כי במעמד הר סיני השמיעך השם יתעלה את קולו מן השמים לתת לך הנימוס התוריי בדעות ובמדות אשר נכלל כלו בעשרת הדברים ההם כמו שביארנו בפרשת יתרו:
@148 **ועל הארץ הראך את אשו הגדולה.** שנראה לך שם ושמעת את דברו מתוך האש וזה לך גם כן לאות כי הוא בשמים ובארץ:
@149 **ותחת כי אהב את אבותיך וגומ'.** הנה לאהבת השם יתעלה את אבותיך ובחר בזרע האבות המיוחס להם והוא זרע יעקב הנה הוציאך ממצרים בפניו רוצה לומר בהשגחתו הפרטית שהוא מיוחסת אל פניו כי המביט מביט בפניו וזהו כוחו גדול כי מפאת זאת השגחה יתחדשו הנפלאות:
@150 **להוריש גוים גדולים ועצומים.** הנה נעשה זה לתכלת שתירשו תכף את הארץ מיד הגוים הגדולים העצומים ההם כמו שראית בעיניך היום הזה שירשת ארץ שני מלכי האמורי:
@151 **וידעת היום והשבות אל לבבך כי יי' הוא האלהים.** רוצה לומר אחר שהשם יתעלה הראך את כל זה להודיעך כי הוא אלהי השמים ואלהי האר אין עוד זולתו באלהות הנה צריך שתדע זה ותשיב אל לבבך כי יי' הוא האלהים בשמי ממעל ועל הארץ מתחת אין עוד כמו שיחשבו המאמינים בשניות שיהיו שנים אלהי השמים זולת אלהי הארץ וכבר ביאר הפילוסוף מום זאת האמונה וביאר שהענין הוא כן כמו שהגיד בספרו מה שאחר הטבע ואין הנה מקום זאת החקירה ובהיות הענין כן הנה ראוי לך לשמור מצותיו וחוקיו לטוב לך ולזרעך והנה זאת הטובה הוא בעצמות מה שהוא טוב אנושי והוא הצלחת הנפש וימשך לו ג"כ טוב גופיי בעבור דבקות השגחה האלהית והוא ששמירת חקיו ומצותיו יסבב שתאריכו ימים על האדמה בדרך שתהיה לכם ולזרעכם כל הימים והוא מבואר כי לולי עבור אבותינו על דברי התורה היינו אנחנו מחזיקין בארץ ישראל ולא גלינו ממנה והוא מבואר מספורי דברי הנביאים. הנה זה ביאור זאת הפרשה.
@153 **ספר** שכבר הבדיל משה אז השלשה ערים שצוה השם יתעלה להבדיל מעבר הירדן מזרחה לנוס שם כל מכה נפש בשגגה בלא כוונה אשר אינו שונא לו מתמול שלשום שאם היה שונא לו אולי סבב הרוצח השגגה בכוונה שאם יקרה שיעבור שם השונא לו ינזק ובזה התנאי ימלט הרוצח בעיר מקלטו מיד גואל הדם אמנם אם הרג מזיד אף על פי שנס אל עיר מקלטו ישפטוהו הסנהדרין ויתנוהו ביד גואל הדם להמיתו כמו שהתבאר בפרשת מסעי והם בצר ורמות וגולן כמו שצוה השם יתעלה.
@156 **וזאת התורה.** שסדר משה לפני בני ישראל והם העדות והחקים והמשפטים אשר דבר משה אל בני ישראל בצאתם ממצרים כי אז נתנה התורה בכללות ואולם סדר משה לפני בני ישראל אותם הדברים שנאמרו אז בעבר הירדן בגאי מול בית פעור והנה תאר המקום ההוא בתארים רבים מודיעים אותו להוסיף אמות בזה הספור ובזה המקום יתבאר כי כל מה שנזכר בזה הספר נתן למשה בהר סיני אך בקצתו הוסיף ביאור בזה המקום במה שאמ' בעבר לירדן בארץ מואב הואיל משה באר את התורה הזאת לאמר וראוי היה להיות כן כי התורה מצד היותר נימוס אחד כולל לתכלית אחר מוגבל הנה יחוייב שיהיה סדורו יחד לא פעמים בפעמים כמו שנזכר בפרשת בראשית:
@162 **שמע ישראל את החקים ואת המשפטי' אשר אנכי דובר באזניכם היום ולמדתם אותם.** למדנו מזה שחייב אדם ללמד תורה לא ללמוד לבד עם שבמצות הלמוד לאחרים נכללה מצות הלמידה כי מי שלא למד לעצמו לא יוכל ללמוד לאחרים:
@164 **לא את אבותינו כרת את הברית וגומ'.** הרצון בזה כי לא נתנה התורה לאבות לבד אך להם ולזרעם אחריהם לאין תכלית ולזה ראוי שיחשוב כל דור ודור כאלו לו נתנה התורה:
@166 **אנכי עומד בין יי' וביניכם בעת ההיא וגומ'.** הנה זה היה בעת שאמרו לו ישראל דבר אתה עמנו ונשמעה כי יראתם מפני האש הנה מפני זה נתבאר בפרש' יתרו שיראו העם ועמדו מרחוק אחרי שמעם מפי הגבורה זה הקול הנפלא עשרת הדברים באמרו את הדברים דבר יי' אל כל קהלכם בהר מתוך האש בענן ובערפל:
@166 **ולא עליתם בהר.** רוצה לומר כי אף על פי שלא עליתם בהר לא יה לכם רשות לעלות בו אף על פי כן יראתם והנה אמר זה להעיר שאם היו מסכימים לשמוע כל דברי הורה מפי השם יתעלה היו שומעים אותם כמו ששמעו עשרת הדברם כי לא עשה זה השם יתעלה ליראם ולבהלם לכוונה שיברחו מלשמוע והראיה כי משה היה בהר וישראל לא עלו בהר ולזה לא היה להם לירוא כל כך ולזה הוא מבואר שכבר היה לישראל להאמין שאר מצות התורה כמו האמנתם עשרת הדברים ששמעו אותם מפי הגבורה:
@166 **הנה** כבר ביארנו כל זה ותועלותיו בפרשת יתרו ומשם ילקח הביאור בו זולתי מעט שבא בזה המקום והוא שכבר אמר פה שמור תמורת אמרו זכור בפרשת יתרו ולזה יהיה הרצון באמרו לקדשו שתקדשהו בדברים כדי שתשמור את השבת ולזה יחוייב שיהיה זה הקדוש סמוך לכניסתו כדי שיזכיר כי שבת הוא וישמור מעשות מלאכה בו ומזה המקום למדו רבותינו זכרונם לברכה שהנשים מחוייבות בקדוש היום כי הן מחוייבות בתכלית אשר בעבורו צותה התורה לקדשו בדברים והיא השמירה מעשות בו מלאכה:
@166 ועוד נתחדש בו גם כן בפרשת יתרו נתן הסבה בענין מצוות השבת להזכיר לנו כי השם יתעלה חדש העולם בשבת ימים וביום השביעי שבת וינפש כי זאת פנה גדולה מפנות התורה רוצה לומר אמונת החדוש ואולם בזה המקום נתן הסבה במצות שבת לזכור המופתים שעשה לנו השם יתעלה בהוציאו אותנו מארץ מצרים כי אז היינו עבדים ולא היה לנו רשות לנוס מהעבודה הקשה אשר היה מעביד אותנו פרעה ועמו והנה אין זה סתירה בחק התורה וזה כי התורה תצוה מה שתצוה לתועלות רבים כאשר היה אפשר לה זה כמו העניין בטבע שישתמש לפעמי' במה שיעשהו לתועלת יותר מאחר כמו שנזכר בספ' בעלי חיי':
@179 **ולא תתאוה.** הנה התאוה היא בלב לבד ולפי מה שביאר' בפר' יתרו מההדרגה באלו הדברות ראוי שתתברר שהתאוה מביאה לידי חמוד והנה ההבדל שיש בין החמוד ובין התאוה הוא כי התאוה הוא בלב לבד והחמוד הוא לקיחת דרך שיגיע לו הדבר שהיתה בו התאוה ויוציא זה לפועל כאלו תאמר שישתדל עם האיש ההוא בעל הבית שיוכרח למכור לו ביתו או שדהו או מה שהתאוה וזה יהיה אם בהבאתו לו אנשים יבקשו ממנו זה לא יוכל להשיב פניה' או במה שידמה לזה והראיה בזה שדבר החמוד דבר שיש בו מעשה מה שאמר ולא יחמוד איש את ארצך בעלותך לראות את פני יי' אלהיך ואמר לא תחמוד כסף וזהב עליהם ולקחת לך:
@180 **קול גדול ולא יסף.** רוצה לומר שלא יסף להתחדש שם קול אחר קול אך הקול ההוא היה נמשך ומתדבק בזולת הפסקים וגם כן לא פסק הקול ההוא אחר דברו עשרות הדברים אך היה נמשך אל ישראל להתרחקו מעל המקום ההוא שלא ישמעוהו והנה אמר זה להוסיף אמות לישראל שכל התורה היה אפשר להם לשמוע בזה האופן לולי יראתם מפני האש והקולות הנפלאים ההם כמו שקדם או יהיה הרצון באמרו ולא יסף שלא יסף עוד להתחדש כמו זה הקול הנפלא מהשם יתעלה באופן שישמעו דבריו כלל עם אחד והביאור הראשון ידמה שיהיה נאות יותר ואם שניהם כאחד טובים:
@181 **כשמעכם את הקול מתוך החשך.** הוא הערפל שזכר תחלה כאמרו מתוך האש הענן והערפל ויכתבם על שני לוחות אבנים ביאר בזה כי המכתב אשר בלוחות לא היה נעשה במלאכה אך השם יתעלה חדש המכתב ההוא בהם על דרך המופת וזה גם כן עוד לאות על שנתנו אלו הדברים מהשם יתעלה ובזה אמר במה שקדם והלוחות מעשה אלהים המה והמכתב מכתב אלהים הוא חרות על הלוחות:
@182 **ותאמרו הן הראנו יי' אלהינו את גדלו ואת כבודו וגומ' ואת תדבר אלינו את כל אשר ידבר יי' אלהינו אליך ושמענו ועשינו.** הנה התחלה אמרו כל אשר ידבר יי' נעשה להעיר שלא יאמינו רק מה אשר יתברר להם אשר דברו יי' ולזה הוצרכו להתחדש אלו הקולות הנפלאים כדי שישמע העם אלו הדברים מהשם יתע' אך אחר שראו זה הפלא וייראו מלשמוע השאר בזה האופן פן ימותו והאמינו במשה ואמרו לו שישמע הוא הדברים מהשם יתעלה ויביאם אליהם והם ישמעו דברי משה ויעשו אותם:
@187 והנה ספר שיישר בעיני יי' מה שאמרו למשה **מי יתן והיה לבבם זה ליראה אותי** ולמדנו מזה שהדברים המיוחסים אל הבחירה אין השם יתעלה מבריח אחד מחלקי האפשר על דרך החיוב שאם היה הענין כן לא היה אומר השם יתעלה מי יתן והיה לבבם זה להם שכבר היה זה ביד השם יתעלה לפי זאת ההנחה רוצה לומר לחייב שתהיה בחירתם תמיד אל ההמשך בדרכי התורה ואף על פי שמצאנו שהשם יתעלה יטה הבחירה בעת מה למי שירצה כמו שמצינו בהקשותו לב פרעה וסיחון ומה שידמה לזה הנה זה הוא על דרך המופת ומה שזה דרכו לא יהיה תמיד כמו שביארנו בששי מספר מלחמותיי':
@187 **ולשמור את כל מצותי כל הימים.** למדנו מזה שאלו המצות בכללם רצה השם יתעלה שיעמדו כל הימים כי עליהם אמר זה המאמר ולזה הוא מבואר שלא ימיר השם יתעלה את התורה ולא מצוה ממצותיה ולבניהם לעולם רוצה לומר כל הימי' וזה מבואר מהפסוק' בעצמו:
@188 **לך אמור להם שובו לכם לאהליכם.** אמר זה שכבר הוזהרו מלגשת אל אשה קודם זה כדי שיהיו נכונים לשמוע דברי השם יתעלה כאמרו היו נכונים לשלשה ימים אל תגשו אל אשה ואחר שנפרדו מאלו הדברים הקדושים הותרו לגשת אל נשותיהם:
@189 **ואתה פה עמוד עמדי.** ביאר בזה שהם לבדם הותרו לשוב לאהליהם לא משה כי תמיד היה עם השם יתעלה ומדבר עמו ולזה היה ראוי שיהיה מקודש לנבואה תמיד ולזה פרש משה מן האשה כמו שיראה ממה שדברו אהרן ומרים במשה על אודות האשה הכושית אשר לקח שפרש ממנה כמו שנזכר בסוף פרשת בהעלותך:
@189 **ואדברה אליך את המצוה ואת החוקים והמשפטים אשר תלמדם ועשו בארץ.** ידוע כי במצוה האחת חקים ומשפטים אשר תלמדם ועשו בארץ. ידוע כי במצוה האחת חקים ומשפטים כמו שמצאנו במצות קרבן שנאמר בה ככל חקותיו וככל משפטיו תעשו אותו כחקת הפסח וכמשפטו כן יעשה והנה אמר אשר תלמדם ולא אמר אשר תדבר אליהם להעיר שמשה היה מלמד לישראל המצוה ופרושיה ודקדוקיה ולזה אמר הואיל משה באר את התורה הזאת וזהו אמרו גם כן וזאת המצוה והחקי' והמשפטים אשר צוה יי' אלהיכם ללמד אתכם ולא אמר להגיד לכם ולזה רמז לפי מה שאחשוב אמרו הואיל משה באר את התורה וגומ' כי אז למדה וביארה וגלה סתומיה ועמוקותיה:
@190 **לא תסורו ימן ושמאל.** רמז בימין אל ההוספה ובשמאל אל הגרעון כי המוסיף יחשוב לעשות טוב כי הוא עושה מצות השם יתעלה ויותר מזה והוא יפסיד בזה כוונת התורה כמו שזכרנו במה שקדם:
@191 **למען תחיון וטוב לכם והארכתם ימים בארץ.** ידמה כי רמז באמרו למען תחיון בחיי הנפש והם הטוב אמתי באדם במה שהוא אדם ובהארכת הימים בארץ רמז אל הטיוב הגופיי המישיר אל הטוב הנפשיי:
@193 **אתה ובנך ובן בנך וכל ימי חייך.** רוצה לומר כל הדורות הנמשכים ממך זה אחר זה ולזה אמר אתה ובנך ובן בנך והנה הוא כאלו אמר כל הימים אשר יתקיים לך זה אחר זה הנה זה באור מה שיצטרך אל ביאור לזאת הפרשה:
@195 **שמע ישראל.** הכוונה בו ההאמנה והשמיעה יבינו בו על צד הבנה וההמון יאמינו בו על דרך צד השמיעה והקבלה מהיחידים:
@195 **יי' אלהינו.** צוה בזה להאמין כי מי שנקר שמו יי' הוא אלהינו רוצה לומר שהוא מנהיג אותנו ומשגיח בנו ואף על פי שאנחנו פחותים ביחס מאד אל מעלתו יתעלה וכבר נתאמתה זאת הפנה והותרו הספקות הנופלות בה ברביעי מספר מלחמות יי' וכבר בארנו בפרשת ואלה שמות שזה השם רוצה לומר יו"ד ה"א וא"ו ה"א הוא היותר מורה על מהות השם יתעלה מכל השמות שיפלו וכן הענין בשם האחד כמו שביארנו שם ובביאורנו למה שאחר הטבע:
@195 **יי' אחד.** צוה בזה להאמין שהנמצא הקדוש הזה שנקא בזה השם הקדוש הוא אחד וראוי שלא יעלם ממנו שכבר יתבאר מזה שכמו שלא ישתת וזולתו יתעלה בשם יו"ד ה"א וא"ו ה"א כן לא ישתתף זולתו שם האחד כי שני אלו השמות יאמרו בו יתעלה באמתת ובקדימה ויאמרו על זולתם באחור בצד מצדדי שתוף השם יתעלה וזה כי כל הנמצאות קנו האחדות והמציאות ממנו ולזה יהיה הוא יתעלה היותר אמתי באלו השמות ואם אמר אומר כי גם המניעים הנבדלים הם אמתיים בשם האחד כי אין בהם שום הרכבה כמו שאין הרכבה בשם יתעלה אמרנו לו כי אלו מצד מה שהם עלולים ממנו יחוייב להם בהשיגם עצמם שישיגו היותם עלולים ומזה הצד תהיה להם השגה מה בהכרח בעלה הראשונה כמו שביארנו בחמישי מספר מלחמות יי' ולזה יהיו מרכבים משני עניני' עניין בו ישכילו עצמם וענין בו ישכילו זולתם ואולם השם יתעלה לא ישיג כי אם עצמו כי אין לו עלה קודמת לזה הוא יותר ראוי אמתי בשם האחדות עם שהאחדות אשר לאלו הוא חסר מאד ביחס אל האחדות הנכבד אשר לשם יתעלה כמו שביארנו כל זה בראשון ובחמישי מספר מלחמות יי' ואם אמר אומר שבשם יתעלה הרכבה מזה הצד מצד השגתו בעלולים ממנו אמרנו לו שאין לו בהשגת העלה הזאת שהיא שכל העלולים ממנה שום הרכבה כי מצד השיגה עצמה תשיג העלולים ממנה מצד היותר נכבד ממציאותם כמו שביארנו שם ואין הנה מקום זאת החקירה:
@196 **ואהבת את יי' אלהיך.** צונו בזה המאמר לאהוב השם יתעלה ולפי שהאהבה מבואר מענינה שלא תהיה לדבר שאין בו שום השגה כל שכן כשלא תהיה בזה האופן השלם אשר זכר פה הנה יחוייב זה הציווי שנעשה בדרך שתהיה לנו השגה מה בזה השם הנכבד והנורא כדי שנתעורר מפני זה לאהבו וכל מה כשנוסף האהבה בו יתעלה נוסיף לאהבה אותו והנה זה יושג לנו מצד שקדנו על מצוות התורה כי הם יישירונו אל השגתו יתעלה כמו שביארנו בזה בזה הספר ומצד החקירה על פעולות השם יתעלה הנפלאות המושגות לנו מענין אלו הנמצאות אשר אצלנו והוא מבואר כי כשיעמוד האדם על זה תהיה אהבתו יתעלה יותר חזקה מכל האהבות אשר אצלו כי סבות האהבה הם השלמות והמעלה והערבות והתועלת כמו שנזכר בספר המדות. ולפי שהשם יתעלה הוא בתכלית השלמות והמעלה עד ששלמות כל נמצא זולתו חסרון ביחס אל שלמותו יתעלה הנה יהיה היותר נאהב לאין שעור מזה הצד ולפי שהערבות אשר תהיה בהשגתו יתעלה למעלה מכל הערביות לאין שיעור כמו שביארנו בחמישי מספר מלחמות השם ובביאורינו למה שאחר הטבע הנה יהיה היותר נאהב לאין שעור מזה הצד ולפי שהתועל' שיושב מהשגתו יתע' למעלה מכל התועלות כי הוא השגת החיים הניצחיים הנה יהיה היותר נאהב לאין שעור מזה הצד עם שהוא המשפיע לאדם כל הערביות והתועלות שיושגו לו והוא הממציא אותו והשומר מציאותו הזמן האפשרי לו:
@196 **בכל לבבך.** ידוע כי הלב יאמר על הרצון והנה באדם שני מינים מהרצון והחפץ האחד הוא הכח המתעורר שהוא נמשך לציור הדמיון והשני הוא הכח המתעורר שהוא נמשך לציור השכל וכבר יראה האדם לפעמים בעצמו שני אלו הכחות יחד ויחלוק זה עם זה וברעים יגבר היצר הרע ובטובים ינצח היצר הטוב וכאלו הזהיר בזה וצוה שיכניע האדם כל מיני רצונו לאהבת השם יתעלה וימשך מהאהבה הזאת שישמור מצותיו כי האוהב ישתדל לעשו' רצון אוהבו כפי היכולת:
@196 **ובכל נפשך ובכל מאודך.** לפי שהרצון באמרו ובכל מאודך שלא יחוש אם יפזר כל מאודו או יפסידהו לאהבת השם יתעלה הנה יתבאר מזה שהרצון באמרו בכל נפשך שהוא אפי' יטלו את נפשו וימיתוהו לא יחוש לאהבת השם הנכבד ולשמור מצותיו ויהיה אמרו בכל נפשך מענין אמרו כי בנפשו דבר אדוניהו וכבר ביארנו התנאים אשר בהם יתיר האדם עצמו למיתה לאהבת הש' יתעלה בפרשת אמור אל הכנים והוא מבואר שאין הרצון באמרו בכל נפשך מענין רצון על דרך מה שאמר אם יש את נפשכם שהוא כמו רצונכם שאם היה זה כן יהיה אמרו בכל נפשך לבטלה כי כבר אמר תחלה בכל לבבך:
@197 **והיו הדברים האלה אשר אנכי מצוך היום על לבבך.** צוהו שיהיו אלו הדברים אשר צוה בזה המקום תמיד אצל לבבנו ומחשבתנו כדי שלא נשכח אותם כי הם מהגדולות שבפנות התורה ולפי שאמ' אחר זה לדבר בם ולכתבם בתפלין ובמזוזות והתנה בזה המקום ואמר והיו הדברים האלה למדנו מזה שאין ראוי להמיר בהם סדר אלו הדברים ולא להמיר הלשון בלשון אחר כי כל זה הוא נכלל באמרו והיו הדברים האלה:
@198 **ושננתם לבניך.** הוא מענין למוד וקראו שנון מצד השנות הדברים הצריכים בלמוד כי אם לא ידע בפעם אחת ישנה לו או ישלש עד שילמוד מה שצריך למדו ומזה המקום יתבאר שצריך גם כן שילמדם וידעם האדם כי מי שלא ידע לעצמו לא יוכל ללמד לאחרים עם שהוא מן השקר שתצוה התורה שיעדו קטנים אלו הפנות הגדולות ולא תצוה שידעו הגדולים לפי שבנים נאמר על התלמידים כמו שמצאנו שנקראו תלמידי הנביאים בני הנביאים ידענו שכבר כלל זה הצווי גם כן שילמדם לתלמידיהם וזה גם כן נכנס בצווי ואהבתו כי האוהב יפרסם לכל מעלת אוהבו ולזה אמרו רבותינו ז"ל ואהבת את יי' אלהיך אהבתו על הבריות:
@198 **ודברת בם בשבתך בביתך ובלכתך בדרך.** למדנו מזה שזאת הפרשה צריך אדם לקרות כפי מה שהיא בזולת שום שנוי בשכבו ובקומו והנה מאמרו ודברת בם למדנו שהוא מחוייב כשיקרא את שמע שיהיה דבורו כאלו הדברים לא בדברים אחרים כי התעסקו בדברים אחרים יבלבלו כונתו באופן שלא יהיה כוונתו בם ומזה המקום למדנו שאין ראוי לו לרמוז בעיניו ולקרות בשפתותיו והדומה לזה בעת קרותו את שמע כי זהו כמו דבור בדברים אחרים עם קריאתו את שמע ולפי שאמ' בשבתך בביתך ובלכתך בדרך ולא אמר בבית ובדרך למדנו מזה שכאשר היה בשבתו בביתו או לכתו בדרך לצורך עצמו הו' חייב לזאת המצוה ואולם אם לא היה הלכת והשבת לו אבל היה לצורך עשיית מצוה לכבוד השם יתעלה הנה לא תדחה המצוה שהוא עוסק בה בעבור המצוה הזאת אלא אם היה יכול לעשות שתיהם כמו שהתבאר בשרשים הכוללים:
@198 **בשכבך ובקומך.** ידוע כי האדם יקרא שוכב בכל זמן שהוא שוכב על מטתו ויקרא קם בעת שהוא קם מעל המטה לבד ולפי שאלו הפעולות אין הכוונה בהם המציאות אבל העת שדרכו שיקרא בו זה כמו שזכרנו בשרשים הכוללים יהיה הרצון בשכבך בשעה שבני אדם שוכבי' ובקומך בשעה שבני אדם קמים והוא מבואר שזאת השעה הוא על הרוב בזמן שכיבה מעת צאת הכוכבים עד עלות השחר וזמן קימה הוא אחר זמן שכיבה והוא על הרוב אחר עליית השחר וכאלו הזמנים ראוי שתהיה קריאת זאת הפרשה אמנם לא יצא מגדר בשכבך אם היה זמן השעה זמן שכיבה על המעט או זמן קימה על המעט כי עדי הוא נכנס תחת גדר אמרו בשכבך ובקומך והנה זמן שכיבה על המעט יכנס מעת שקיעת החמה כי כבר ימצאו אנשים שוכבים אז לפי המנהג וכן ימשך גם כן לזאת הסבה עד הנץ החמה וזמן קימה על המעט ימשך עד עבור שתי שעות מן היום כי כבר ימצאו אנשים מעטים ינהגו לישן עד זה הזמן:
@199 **וקשרתם לאות על ידך.** הרצון בזה שיכתבם ואחר כך יקשרם כי הדברים לא יקשרו אך הנכתב ולפי שדקדק בכתיבה שתעשה על ידי מי שנכנס בגדר אלו המצוות באמרו וכתבתם על מזוזות ביתך ובשעריך למדנו מזה שלא יתכן שיכתבם כי אם מי שהוא בן תורה ולפי שהכתיבה הנהוגה היא בעור בהמה טהורה כי היא היותר שלמה בזה ראוי שתהיה הכתיבה באופן זה וראוי שיהיה בדיו באמרו ואני כותב על הספר בדיו וזה הנהוג גם כן מענין הכתיבה והנה מצאנו זה הלשון בעינו בפרשת קדש לי כל בכור שנאמר והיה לך לאות על ידך ובפרשת כי יבאך שנאמר והיה לך לאות על ידך ובפרשת והיה אם שמוע שנאמר וקשרתם לאות על ידכם למדנו מזה שבתפליחן של יד יכתוב אלו הארבע פרשיות ולפי שהסדור אשר להם בתורה הוא שתהיה ראשונה בפרשת קדש לי כל בכור ושנית פרשת והיה כי יביאך ושלישית פרשת שמע ורביעית רשת והיה אם שמוע ומצאנו שדקדקה התורה באלו העניינים שלא יומר בהם דבר מסדורם כמו שביארנו באמרו והיו הדברים האלה ידענו שהוא מחוייב שיהיה סדורם כן וכבר נלמד זה גם כן ממה שאמר בפרשה הראשונה והיה בלשון יחיד ובשמע והיה אם שמוע אמר בלשון רבים רוצה לומר שכבר אמר וקשרתם אותם ועוד כי בתפלין של ראש אמר בפרשת קדש לי ולזכרון לשון יחיד ובפרשת והיה כי יביאך אמר ולטוטפות לשון רבים ולפי שהקשירה לאלו הארבעה פרשיות היתה שתהיה לאות על ידו וכבר רצתה התורה שיהיו אלו הדברים על לבו הנה ידענו שהכונה בזה הוא שיהיו נקשרים למעלה מהזרוע שהוא אצל הלב והוא הפרק שעל הזרוע השמאלי וזהו ענין האו' לקושר והתפלין כי הוא לסימן שצריך שיהיו אלו הדברים על לבו תמיד ולפי שאין זה הענין אות כי אם למי שקושר התפלין כי לא יראוהו אחרים במקום ההוא לפי הנהוג מלבוש האדם שיכסה הפרק ההוא והנה יתבאר גם כן שהנחת תפילין של יד הוא בזה הפרק מן היד השמאלי לפי שנאמר וקשרתם לאות על ידיך. והנה הקשירה לפי הנהוג תעשה ביד הימיני ולזה יחוייב גם כן שיהיו מקום הנחת תפלין של יד אצל היד השמאלי כי לא יתכן שיקשור האדם ביד הימנית התפילין על היד ההיא בעצמה והנה אמר על ידך רוצה לומר אצל ידך והנה יקרא יד הזרוע עם היד ולזה יהיה זה היד במקום שתאנו אצל היד:
@199 **והיו לטוטפות בין עיניך.** רוצה לומר על המוח כאמרו לא תשימו קרחה בין עיניכם למת שהרצון בו על המוח כי הקרחה לא יתכן שתהיה בין העינים והנה הוא מבואר כי המוח היא בין העינים על המוח במקום השער תהיה הקרחה ושם לבד יתכן שיניח אלו התפילן ולזה אמר בפרשת קדש לי ולזכרון בין עיניך כי שם במוח ימצא כח הזוכר והנה הכוונה באמרו ולטוטפות לדבורים כענין אמרו ולא תטיף על בית ישחק ולפי שאמר בתפלין של יד לאו' שהוא לשון יחיד ואמנם בתפלין של ראש לטוטפות שהוא לשון רבים למדנו שהארבע פרשיות תהיינה יחד כסדרן בכרך אחד בתפלין של יד ואולם בתפלין של ראש תהיינה בד' בתים כי בפרשה השנית בא בה לשון רבים כמו שזכרנו ולזה הוא מבואר כי לא יהיה מהם בכרך אחד זולתי פרש' אחת ולזה יהיו בתפלין של ראש ד' בתים כדי שיהיו אלו הדבורי' נראים הבדלים זה מזה ולזה הקדים בכל הפרשיות האלו זכרון תפלין של יד קודם תפלין של ראש כי הם במקו' יותר נכבד לפי שהלב יותר נכבד מהמוח והנה היו הד' פרשיות בבית אחד בתפלין של יד שהן כנגד הלב והיו בד' בתים בתפלין של ראש כי בזה הישרה מה להשיג ייחוד הש' ית' עם רבוי הפעולות השופעו' מאתו וזה שהלב הוא התחלה לחי ומהחום הטבעי המשתלח ממנו במוח יסודרו מינים רבים מההרגש מצד המקבלים אשר שם וכן הענין בשם ית' כי רבוי פעולותיו לא יורו על רבוי בו ולפי שהלב הוא התחלה למה שישפע מהמוח מהחוש והתנועה הנה היה מהראוי שיהיו תפלין של יד קודמין לתפלין של ראש וזה ממה שיוסי גלוי ושלמות על שהרצון באמרו על ידך הוא כנגד הלב כמו שזכרנו ולפי שאמר בפרשת קדש לי והיה לך לאות על ידכה ובפרשת כי יביאך והיה לאות על ידך הנה למדנו שכל הווייתם המלאכותית צריך שתכוין לשם תפלין וכן העניין בקשירתם ולזה צריך שיהיה עבודם לשם תפלין וכתיבתן ועשייתן וקשירתן ולפי שאמ' במזוזה וכתבתם שהרצון בו הדב' הנהוג בענין הכתיבה למדנו כן הענין בתפלין והוא שתהיה הכתיבה באופן שתהיינה האותיות נכרות ולא ידמו לאות אחרת ותהיה כל אות נבדלת מהאחרת כי זהו מגדר הכתיבה ותהיינה גם כן הד' פרשיות לפי מה שהם בתורה ר"ל שהפתוחות תהיינה שם פתוחות והסתומות סתומות כי זה נהיה בתורה לענין בהכרח לא דבר רק הוא ובכלל הנה הפרשה פתוחה תורה מצד מה על הגמר העניין באופן מה והפרשה סתומה לא תורה על הגמר הענין באופן ההוא אבל הוא מורכב מן ההגמר וההקשר עם מה שאחריו ולזה היתה הפר' ההיא סתומה והנה להעיר על שאין השלמו' נמצא באלו הפרשיות אשר בתפלין לבדן ולא בפרשיות אשר במזוזה לבדם ואע"פ שיחדו בזה מבין שאר הפרשיות אשר בתורה כי השלמות האמתי לכלל התור' לבד תקנו רז"ל שיהיה ספר תורה נכתב בעור השלם ותפלין בחלק ממנו הנקרא קלף ומזוזה בחלק ממנו הנקרא דוכסוסתום להעיר על שאין אלו הפרשיות כי אם חלק מהתורה:
@200 **וכתבתם על מזוזות ביתך ובשעריך.** לפי שזה היה להזכיר דבר אלו הפרשיות אשר צונו לכתבם אצל מזוזות הבית והם פרשת שמע והיה אם שמוע למדנו שאין הרצון שיכתוב אצל כל אחד מזוזת הבית אבל הרצון באמרו אצל מזוזת כל בית ובית ולפי שזה דבר מונח מחוץ לבית למדנו שבמזוזה הימנית לו בהכנסו לבית יונה זה המכתב כי התורה בחרה הימין לכל הענינים לפי מה שהתבאר מפרטים דבי' בתורה והנה הבית יקרא סתם מה שהו' בית דירה:
@200 **ובשעריך.** ר"ל שערי ביתך שיש בהם מזוזה ולפי שאמר ביתך למדנו שאם היה בית מקדש פטור ממזוזה:
@201 **והיה כי יביאך יי'.** הזהירם שרב השבע והשלוה לא יסבב שישכחו הש' ית' שהוציאם ממצרים והנה זכר אלו הדברים בהדרגה כי הערים קודמי' לבנין הבתים שבהם ובפרט הערי' אשר להם חומה אשר יתאחדו בהם כל יושבי העיר כי בראשונה יהיה מקום העיר ותהיה מוקפת חומה אחר זה יבנה כל אחד מהמתישבים בעיר ההיא בית לעצמו והנה הבנין קודם לחציבת הבור וחיבת הבור קודם לנטיעת כרמים כי המי' יותר הכרחיים מהיין ולזה גם כן הקדים הכרמים לזתים כי היין יותר הכרחיי מהשמן:
@204 **את יי' אלהיך תירא.** וצוה בזה ליראה מה' ית' וענין היראה שנירא מלעבור על מצותיו לגודל מעלתו לרוממותו והוא מבואר שהיראה הזאת תשלם אחר שיושג הש' ית' כפי היכולת כי לא ירא האדם ממי שלא ידע מה הוא ולפי שההשגה ההיא תביא אל האהבה כמו שביארנו בפרשת שמע הנה יתחברו בשם יתעלה שתי אלו המדות כי למעלתו ורוממותו ייראו ממנו יראה עצומה ויאהבוהו אהבה נפלאה כמו שקדם:
@204 **ואותו תעבוד.** ידוע כי העבודה תהיה באחד משלשה פנים האופן האחד הוא שישרת העובד הנעבד במה שהוא לצורך נעבד וזאת העבודה לא תתכן בש' ית' כי הוא ברוך הוא בלתי צריך לדבר מנבראיו והאון השני הוא שיראה העוד שהוא עבד לנעבד במה שיצטרך העבד שישאל צרכיו מאדוניו להורות על שאינו שליט בלקיחת דבר מהם ולא יהיו לו כי אם מאדוניו שהוא שליט על הקנינים ההם ובזה האון השני יתכן שיעבוד האדם השם יתעלה רוצה לומר שיראה עצמו שהוא עבד לו ולזה ישאל צרכיו ממנו כמו שישאל העבד מאדוניו ולזה היה המאמר הזה צווי שנתפלל לפניו לבקשת צרכינו ובזה עוד תועלת להישיר האנשים שידעו כי כל הטובות באות מהשם יתע' והאופן השלישי הוא שיעשה העבד מה שיצוה האדון מזולת בטה שיהיה מה שיצוהו לצורך האדון או לצורך העבד וזה גם כן יתכן לאדם שיעבוד השם יתעלה ולפי זה העניין יהיה הרצון באמרו ואותו תעבד שכמו שהעבד עושה מצות אדניו כן תקים מצות השם יתעלה:
@204 **ובשמו תשבע.** צוה בזה להשבע בשם יתע' כאשר יביא ההכרח אל השבועה כי בזולת זה תהיה שוא כמו שהתבאר בפרשת יתרו הנה כמו שיחטא האדם או ישבע בשם יתעלה לשוא או לשקר כן יחטא אם ישבע לזולתו לעת צרכו אל השבועה כי זה יורה שהוא נותן האלמות והנצחות והקיום זולת השם יתעלה:
@205 **לא תלכו אחרי אלהים אחרים מאלהי העמים וגו'.** אמר זה לפי שכבר היה ידוע לשם יתעלה הכשל ישראל באלהי העמים ההם ולזה השתדל להצילם מזה והודיעם העונש הנפלא שימשך להם מהשם יתעלה אם יעשו זה:
@207 **לא תנסו את יי' אלהיכם באשר נסית' במסה.** הזהיר בזה שלא לנסות ושלא לשאול מופתי' רבים מהש' יתעלה אחר שנתבאר להם בנביאו שהוא נביא אמת ולזה אמר כאשר נסיתם במסה כי שם רצו לנסות הש' ית' לראות היש יי' בקרבם אם לא לא לצורך גדול כמו שבארנו בפר' בשלח:
@208 **שמור תשמרון את מצות יי' אלהיכם.** ביאר בזה כי בשמירת המצות התורה והעדות והחקים יתישרו אל הצלחת הנפש והוא אמרו למען ייטב לך וימשך להם גם כן מזה ירושת הארץ שהיא מישירה אל הטוב הזה כמו שביארנו בראש זאת הפרשה ולזה אמר ובאת וירשת את הארץ הטובה:
@211 **כי ישאלך בנך מחר לאמר מה העדות והחוקים וגומ'.** רמז בזה למצות פסח שהיה נאכל על מצות ומרורים ככל החקים והמשפטים שנתבארו בו שהוא בענינו שנוים רבים שיתעורר בעבורם הקטן לשאול מה הסבה בזה וכן הענין בכל השנויים שחדש לנו השם יתעלה לזכור דבר יציאת מצרים כאלו תאמר שלא נאכל שבעת ימים חמץ ושנשב שבעת ימים בסכות ומה שידמה לה:
@215 **ויצונו יי' לעשות את כל החקים האלה ליראה את יי' אלהינו.** ר"ל כי מזה נעמוד על הידיעה בעצם גבורות השם יתעלה ויביא זה אותנו ליראה ממנו:
@215 **טוב לנו כל הימים.** רמז בזה אל הטוב הנצחי אשר לא יכלה והוא הטוב הנפשי:
@215 **ולחיותנו ביום הזה.** רמז בזה אל החיים הגופיים הכלים והפוסקין:
@216 **וצדקה תהיה לנו.** ידוע כי צדקה הוא עשיית העושה מה שבחוקו לעשות והראוי לו כמו שביארנו באמרו והאמין ביי' ויחשבה לו צדקה והנה הרצון בזה כי זה הדבר הוא חוק עלינו וראוי לנו לפי היותר והצדק ונגמול טוב לנפשנו בשמרנו לעשות את כל זאת:
@216 **לפני יי' אלהינו.** ר"ל במקום אשר יבחר לשכן שמו שם כי שם יעשו הפסח והמועדים האחרים והמקום ההוא יתואר בזה התואר כמו שנזכר בפרשת ראה אנכי במקומות רבים:
@217 **ונשל.** והשליך:
@218 **לא תכרות להם ברית ולא תחונם.** הזהיר בזה מחמול עליהם והסבה בז פן יחטיאו אותנו ולזה הזהירתנו במה שיבא שלא נחיה כל נשמה באלו השבעה גוים ואף על פי שכבר רצה השם יתעלה שיקראו להם לשלום חלה כמו שנתב' בפרשת שופטי' הנה הקשה את רוחם ואמץ את לבבם למן החרימם להשגח' על ישראל כמו שנזכר בספר שופטים ולזאת הסבה אמר בפרשת ואלה המשפטים שלא ישבו בארצנו פן יחטיאו אותנו לו:
@219 **ולא תתחתן בם בתך לא תתל לבנו ובתו לא תקח לבנך כי יסיר את בנך מאחרי וגו'.** ידוע כי החתונות לא יתכן לאלו וזה מבואר ממה שנזכר בשפחה כנענית בפרשת משפטים שבניהם אינם למי שהוליד אותם והוא העבד העברי אבל הם בניה והם עבדים כאמרו האשה וילדיה תהיה לאדוניה ולהורות שלא יהיה עמה חתונות לישראל אמר לא יומתו כי לא חופשה בשפחה חרופה ואם תענין בשפחה כנענית בן שנכנסה בקצת מצות התורה כ"ש באלו שלא נכנסו בגדר מצות התורה כלל ואמנם ר"ל באמרו לא תתחתן בם שלא יעשה עמהם דבר דומה לחתונות והוא שתהיה מיוחדת לו כמנהג האשה עם בעלה והוא מבואר מזה שאם נתן ישראל בתו לאחד מאלו הגוים הנה ולדה כשר כמוה ואולם מנע זה כי הגוי שהוליד אותו יסיר הבן ההוא שילדה בה ישר' מאחרי השם יתעלה וכ"ש שימנע מנתינת בן ישראל לנכריה כי הוא יוליד בנים לע"ז כי בניהם הם כמוה ולזה אמר ועבדו אלהים אחרים ר"ל זרע הבן וזרע הבת והנה לא הזהירה תורה אלא דרך חתנות אבל אם באו עליה שלא כדרך חתנות אינו לוקה מן התורה אך נתבאר בסוף פרש' בלק שקנאין פוגעים בו אם מצאוהו בשעת מעשה כמו שעשה פנחס בדבר זמרי וכזבי:
@221 **כי אם כה תעשה להם מזבחותיהם תתוצון וגומ'.** ר"ל שלא תעשו עמהם מה שיביא אתכם לעבודה זרה כמו שנזכר בענין החתנות אבל השתדלו עכ"פ להסיר הע"ז מארצכם כדי שלא תהיו נמשכים אחריה ולזה צוה לנתוץ מזבחותיהם ולגדע אשריהם ולשרו פסיליהם:
@222 **כי עם קדוש אתה ליי' אלהיך וגו'.** ר"ל אין ראוי שתתגאל אתה בכל אלו הפחיתיות ואלו השיקוצים בשאר האומות כי כבר נבדלת משאר האומות בזאת התורה הנפלאה ונתקדשת בה ובה נהיית לשם יתעלה לעם סגלה מכל העמים וביאר להם כי לא מפני שהם עם רב בחר בהם השם יתעלה להשענו שבחזקם ינצחו שאר האומות אך הענין הוא בהפך כי ישראל הם המעט מכל העמים אך מאהבת השם יתע' את ישר' ומצד בריתו עם האבו' הוציאם ממצרי' ביד חזקה לקרבם לעבודתו כדי שיהיו ראויים אל הטוב שייעד הש' יתע' לאבותיהם לתת לזרעם:
@225 **וידעת כי יי' הוא האלהים.** ר"ל כי השם יתעלה הוא המשגיח בך ומנהיג אותך הוא האלהים במוחלט ר"ל שהוא מנהיג כל הנמצאות:
@225 **האל הנאמן.** ר"ל האל נאמן בהבטחתו:
@225 **שומר הברית והחסד לאוהביו ולשומרי מצותיו לאלף דור.** הנה מה שייעד השם יתע' מהטוב הוא חסד בעת ההוא אך קיומו היעוד הוא כמו חק על השם יעלה והוא יקיים אותו לדורות רבים והנה קרא אהביו הדביקי' בו ומשיגים אותו כפי מה שאפשר ושומרי מצותיו הם מקיימי מצות השם יתע' והנה שמירת מצותיו תביא לאהבה את יי' יתעלה כי יהיו דרך להשגתו יתעלה ואהבתו גם כן סבה לשמיר' מצותי ובאר בזה כי הטוב המסודר לאדם מצד ההשגחה הפרטית ימשך לזרעו אחריו דורות רבים רבים מלמנות וכבר יתבאר כי זה הברית שכרת השם יתעלה עם האבות לא יפר לעולם ולזה אמר שישמרם השם יתעלה תמיד מכליון כמו שקדם או ירצה בזה שהש' יתעלה ממתין הברית והחסד לאוהביו לאלף דור וזה שכבר ייעד זה הטוב לאברהם וקיימו לו אחר זמן ארוך באופן יותר שלם במה שהשלים הש' יתע' זרע ישראל וקרבם לעבודתו ויהיה אמרו שומר הברית והחסד מענין אמרו ואביו שמר את הדבר והנה הבאור הזה הוא נאות בזה המקום לפי מה שאחשוב:
@226 **ומשלם לשונאיו אל פניו להאבידו.** ר"ל כי הטוב שייעד לשונאיו לא יאחר הגעתו אבל יגיעהו להם תכף להאביד שונאיו במה שיקרה להם מההפסד והכליון אחר הגעת הטוב ההוא להם כמו שקרה לאלו האומות כבר אבדו קודם הגעת הטוב בישראל וגם הטוב ההוא שמור עדין לישראל כי לא הגיע להם כל הטוב שנשבע השם יתע' לאברהם בימי יהושע כי כבר נתן לו השם יתעלה עשר אומות ולא השחית יהושע כי אם קצת השבעה מהם ולזה יתאמת שזה הטוב שמור לישראל לאלף דור וכאשר ישלם הטוב ההוא יסודר הענין בדרך שלא תקרה עוד מלחמה כי אל יהפוך השם יתעלה אל העמים שפה ברורה לקרוא כלם בשם יי' ולעבדו שכם אחד ובזה יתבאר כי להטיב לישראל היה כשהמתין להם השם יתעלה הברית והחסד לדורות רבים:
@227 **ושמרת את המצוה ואת החקים ואת המשפטים וגו'.** ר"ל כי הוא ראוי שישמור את המצוה ואת החקים ואת המשפטים אשר אנכי מצוך היום לעשותם. כי זה יהיה סבה להביא הטוב ולהתמידו לך הנה זה מה שצריך לבאר בזאת הפרשה.
@228 **והיה עקב.** רוצה לומר בשכר שמיעתכם משפטי התורה וקיימם אותם ימתין לכם הש' יתעלה הברית והחסד אשר נשבע לאבותיכם כדי שיהיה שמו לכם אל העת היותר נאות כמו שקדם בסוף פרשת ואתחנן ואולם עתה יתן לכם ארץ שבעה עממים כמו שזכר אחר זה וכמו שקדם פעמי' רבות:
@229 **ואהבך והרבך וגו'.** ר"ל שבשכר זה יאהבך הש' ית' ותדבק השגחתו בך ויברכך. רוצה לומר שיצליחך וירבך כי ירבה זרעך וזה כי השם יתעלה יברך פרי בטנך ויישיר דבר ההוייה שלא יקרה בה הפסד:
@229 **וברך פרי אדמתך.** בדרך שיהיה לך רב דגן ותירוש ויצהר ויברך הפירו' והצאן בדרך שיפרה וירבה מקנך וזה יהיה על האדמה אשר נשבע לאבותיך לתת לך והנה ביאר בזה כי בשכר קיומו משפטי השם יתעלה יירש הארץ ויצליח בה ברבוי הבני' וברבוי הקנינים:
@230 **ברוך תהיה מכל העמים וגומ'.** הנה מיתרון השגחת השם יתעלה בך תהיה ברוך מכל העמים באופן שלא יהיה בך עקר ועקדה ולא בבהמתך וזה ענין נפלא מאד בעם גדול כזה:
@231 **והסי' יי' ממך כל חולי וכל מדוה מצרים הרעים.** אמנם אמר זה לפי שהיו ישראל חושבים בתחלת הענין שיהיה ממנהג השם יתעלה להמציא הרעות ולא הטובות כמו שזכרנו במה שקדם ולזה אמר שלא די שלא יביא השם יתעלה עליהם רעות אבל יסיר מהם כל חולי ולא יחשבו גם כן שיהיה דרך השם יתעלה לחדש בטובות ולא יוכל לחדש רעות כמו שהיו חושבים קצת הקודמים כי שם שני אלוהות הא' עושה הטובות והאחד עושה הרעות כי כבר יחדש רעות נפלאות כמו מכות מצרים בכל שונאי ישראל:
@232 **ואכלת את כל העמי' וגו'.** אמר שבשכר זה גם כן תשחית כל העמים אשר יי' אלהיך נותן לך:
@232 **ולא תחוס עינך עליהם.** הזהיר בזה שלא לרחם עליהם כדי שלא יחטיאו את ישראל:
@232 **ולא תעבוד את אלהיהם.** ביאר בזה שאם תרחם עליהם לבלתי השחיתם הנה יהיה זה סבה אל שתעבוד אל אלהיהם כי החמלה עליהם הוא מוקש לך עוד הזהירם שלא ייראו שלא יוכלו להוריש הגוים הרבים ההם כי יש להם לבטוח שיד השם יתעלה לא תקצר להוריש' בעבור מה שראו מנפלאותיו שעשה ביציאת מצרים:
@236 **וגם את הצרעה ישלח יי' אלהיך בם.** ידמה שהצרעה היה ממיתה אותם או ירצה בזה שהשם יתעלה ימציא להם מה שימיתם בדרך שלא יהיו הנשארים והנסתרים מפני בני ישראל כאמרו ויי' השליך עליהם אבנים גדולות מן השמים:
@238 **ונשל יי' את הגוים האלה.** אמר שמעט מעט ישליכם השם יתעלה מפני בני ישראל. כי לא יוכלו לכלותם מהר פן תרבה עליהם חית השדה. והנה אמר זה על צד המשל לגוים אשר סביבותיהם שהם חוץ מן הארץ הזאת אשר הוגבלת להיות לישראל כי בראותם זה יעזרום לפחדם שיעשו להם ישראל ככה כמו שעושים לאלו אך בלכדם עיר אחר עיר לא ירגישו בזה כל כך גם הגוים אשר צונו להשמידם ולא תהיה במלחמה עם עם רב מאד ואף על פי שיד השם יתע' לא תקצר הנה יבקש על הרוב במה שיעשוהו הסבות הנאותות כשיתכן זה כמו שזכרנו במקומות רבים במה שקדם לנו בזה הספר:
@240 **לא יתיצב איש בפניך עד השמידך אותם.** שלא יוכלו איש מהם להתיצב לפניך להלחם עמך ויתמיד להם השפלות והדלות הזה עד שכבר תשמיד אותם לגמרי:
@241 **פסילי אלהיהם שרפון.** רוצה לומר שלא תהנו ממנו כי מזה הצד זכר זה בזה המקום כמו שנתבאר במה שאמר אחר זה לא תחמוד כסף וזהב עליהם ולקחת לך והנה הזהיר בו מלהנות בצפוי הפסילים כל שכן בפסילים עצמם:
@241 **פן תנקש בו.** רוצה לומר פן יהיה לך למוקש ויביאך לעבוד עבודה זרה וזה כי לפעמי' יתכן במי שלקח זה שיצליחו נכסיו ויחשוב שמה שבא מן העבודה זרה בידו סבב זה ויביאהו זה לעבוד עבודה זרה:
@241 **כי תועבת יי' אלהיך הוא.** רוצה לומר שזה הדבר הוא נתעב ומרוחק אצל השם יתעל:
@242 **ולא תביא תועבה אל ביתיך וגומ'.** רוצה לומר לא תביא זה הדבר המרוחק בביתך כי זה יסבב שתהיה חרם כמוהו ותשמר:
@242 **שקץ תשקצנו ותעב תתעבנו כי חרם הוא.** בדרך שלא תקרבהו לך ליהנות בו בצד מהצדדים כי חרם הוא ולזה תחוייב להחרימו ולכלותו בדרך שלא ישאר לו שום מציאות:
@244 **למען ענותך לנסותך לדעת את אשר בלבבך.** הרצון זה שהשם יתעלה הסכים לעונת אותם זה הזמן הארוך אשר הוליכם במדבר והנה היתה תוחלתם בירושת הארץ תוחלת ממושכה כדי נסותם וליסרם בכל זה הזמן אם הם עדין חזקים בשמירת מצות השם יתעלה אם לא ולזה יסרם שם על מרותם פיו תכף שהיו עושין המרי כדי שיהיו חזקים בשמירת מצות השם יתעלה לטוב להם ולהורישם את הארץ אשר נשבע לאבות וכבר ענה אותם השם יתעלה שם באופן אחר מהענוי והוא שכבר הרעיבם וענה אותם במה שחסר להם שם מים בקצת המקומות ולא היה להם בשר לאכול ולא רקות ומיני קטנית ולא שומים ולא בצלים ושאר מה שידמה לזה גם לא היה להם לאכול זולתי אל המן עיניהם כדי להודיע להם עוצם נפלאות השם יתע' עד שכבר החיה עם רב כזה במדבר בזולת לחם במן שהוריד להם בדרך פלא והיה עוד מהפלא בזה שלא בלתה שמלתם מעליהם באותם ארבעים שנה ולא בלו מנעליהם מעל רגליהם והיה זה כולו להתמיד להם בזה הזמן הארוך ראיית אלו הנפלאות העצומות כדי שיורגלו בהאמנת השם יתעלה:
@247 **וידעת עם לבבך כי כאשר ייסר איש את בנו.** רוצה לומר כי כבר ידעת כי השם יתעלה ייסר אותך על מרותך פיו בהיותך במדבר כאשר ייסר איש את בנו וזה שהאיש שייסר את בנו תכף מרותו כדי שיכיר שמריו היה סבה שהכהו אביו ויקח בזה מוסר. ואולם השם יתעלה לא נסה לענוש הרשעים תכף מרותם כי הוא ארך אפים אך לאהבתו ישראל ייסרם במדבר תכף מרותם כדי שיכירו כי מרים היה סבה אל הרע שקרה להם ויקחו בבזה מוסר ויכנעו לעבודת ה' ית':
@250 **ארץ חטה ושעורה.** הנה שבח ארץ ישראל באילו המינים מהפירות והם חטה ושעורה שהם המינים היותר נבחרים שבמיני התבואה והקדי' החטה שהיא היותר נבחרת מהשעורה ושעורה היא כבדת מגפן יכי הוא מזון ואולם היין אינו הכרחי כל כך כי יוכלו לשתות מים והגפן יותר נכבד מהתאנה והתאנה יותר נכבד מהרמון וזה מבואר בנפשו:
@250 **ארץ זית שמן ודבש.** הנה כמו שהשמן מתואר לארץ ישראל מצד שהיא ארץ זיתים נכונים לעשות מהם שמן כן הדבש מתואר לארץ ישראל מצד שהיא נכונה להצמיח פירות נכונים יהיה מהם הדבש והם התמרים אך לא כוון בזה בדבש הדבורים כי הדבורים יחדשוהו לא הארץ לפי שהשמן הוא יותר הכרחי מהדבש הקדימו ואין ראוי לבאר מזה שיהיה הרמון יותר נכבד מהזיתים והתמרי' כי כבר התחילו לומר ארץ פעם אחרת ולא המשיך זה אל מה שאמר ארץ חטה ושעורה וזאת הסבה גם כן אין ראוי לבאר מזה שיהיה כל אחד מאלו המינים יותר נכבד מהלחם לפי שהזכירו באחרונה כי כבר אמר בו ארץ פעם שלישית ולא המשיכו אל המינים האחרים:
@251 **ארץ אשר לא במסכנות תאכל בה לחם.** ר"ל שלא תאכל הלחם בדרך עוני וחסרון כי הארץ נותנת פירות הרבה ולזה ימצא בה תמיד רבוי הלחם:
@251 **לא תחסר כל בה.** ר"ל כי כל הדברים ארש יצטרכו לאדם ימצאו שם:
@251 **ארץ אשר אבניה ברזל וגומ'.** לפי שהברזל והנחשת והוא הברזל הקשה מאד יצטרכו לאנשים מאד במלאכותיהם זכר שהם נמצאים בארץ ישראל הרבה:
@252 **ואכלת ושבעת וגו'.** ר"ל בעבור שהאכילה והשביעה לא יהיה לפי הנהוג כי אם מחלתם הנה הרצון בזה שמי שאכל לחם כדי שישבע חייב לברך השם יתעלה והראיה עוד כי מהלחם ידבר כי ממנו דבר קודם בסמוך ובו לבדו זכר אכילה באמרו תאכל בה לחם והנה זאת הברכה היא לשם יתעלה להודות לו על המזון שחנן אותנו כי אם תהיה הכונה בזה שנודה לו לבד על הארץ הטובה אשר נתן לנו כמו שאיפשר שיחשב זה מזה הפסוק הנה לא תהי' ההודאה שלמה כי מהארץ לא יצא לחם בזולת חנינת השם יתע' ולזה יתן הסדר שיהיה הברה לשם יתעלה תחלה על אשר נתן לנו זאת הלחם ואחר נודה על שנתן לנו הארץ הטובה שהיא מוכנת מאד לצאת ממנה לחם תמיד ולפי שלא תלה זאת המצוה בארץ למדנו מזה שהיא נוהגת בכל מקום עם שעצם הענין מחיי' זה כי בכל מקום שאנחנו בו השם יתעלה נותן לנו לחם אשר נאכל ואולם בעונותינו עתה שאין אנו מחזיקים בארץ ראוי שנתן לשם יתעלה תודה על שנתנה לאבותינו ולנו לפי מה שאנחנו מקוים ולזה ראוי שנבקש ממנו שישיבנו שם ולזה תקנו בזה אנשי כנסת הגדולה אלו שלש ברכות ולפי שאמ' על הארץ הטובה אשר נתן לך והנשים לא היו יורשות הארץ אלא על צד הזרות שקרה להם לבנות צלפחד הנה הענין בספק אם מפני שאינן בכלל נתינת הוראה על הארץ הטובה אשר נתן להם תפטרו מברכ' המזון או נאמ' כי מפני שישנן בכלל נתינ' הודא' על הלחם שחננו השם יתעלה יתחייבו בברכת המזון עם שהנשים גם כן שמחו בכללן באץ הטובה שאם לא ירשו הן בעצמן ירשו בעליהן או אביהן אשר בטובתן טוב להן:
@253 **השמר לך פן תשכח.** הוסיף להזהירם שלרוב השומן והלשוה לא ישכחו השם יתעלה ומצותיו לפי שכבר שער השם יתעלה שכן יהיה הענין בסוף והשתדל להצילם מזה כפי היכולת והנה ספר להם שאין ראוי שישכחו השם יתעלה שעשה להם כל הנפלאו' האלו והוא שכבר הוציאם ממצרים שהיו עבדים בזה האופן הנפלא שהתפרסם בתורה והוליכם במדבר הגדול והנורא שהיה משכן הנחשים השרפים הממיתים והיה מקום צמאון שאין בו מים והוציא להם הש' יתע' מים מהצור הקשה והצילם מהיזק הנחשים והעקרבים לולי העת שסבב מרים ונזקו בנחשים מהם על צד הטלת העונש עליהם:
@258 **המאכילך מן במדבר.** רוצה לומר שהיה מאכל שלא ידעוהו הקודמים כי השם יתעלה חדשו אז על דרך פלא:
@258 **למען ענותך.** בחסרון המאכלים הנהוגים כדי שתכיר נפלאות השם יתעלה להיות האנשים בכל מה שירצה וכדי שינסה אותך איך תתנהג במצותיו עם ראותך אלו הנפלאות כדי שכאשר יתבאר לו חיותך ראוי לירושת הארץ יתננה לך ולזה גם כן השם יתעלה מיסרם במדבר על מרים תכף בלי איחור כדי שישמרם בקלות אל שיהיו הזקי ההמשך למצוה השם יתעלה:
@259 **ואמרת בלבבך כחי ועצם ידי.** רוצה לומר אולי כאשר תשכח השם יתעלה שעה לך אלו הנפלאות תאמר בלבבך כי בכוחך ירשת הארץ ולזה צוה שיזכור השם יתע' כי מאתו ינתן הכח לישראל לנצח האומות ההם מצד שמרו בריתו עם האבות והודיעם עם זה שאם ישכחו השם יתע' ויעבדו אלהים אחרים יאבדו כאבוד הגוי אשר יי' מוריש מפניהם:
@263 **שמע ישראל אתה עובר היום את וגו'.** ביאר להם שהגוים שהם באים לרשת הם גדולים ועצומים מישראל ושם בני ענקי שלולי יד השם יתעלה לא יוכל איש להתיצב לפניהם עם שהם בערים גדולות בשמים לרוב גובה הבירות והמגדלים והמבצרים אשר שם ולזה צריך אתה לדעת שלא יהיה נצוחך אותך מצד עצמך אך השם יתעלה הוא המשמיד אותם מפניך:
@266 **אל תאמר בלבבך בהדוף יי' אלהיך וגו'.** ביאר לך כי לא בצדקתך ירשו הארץ אך ברשעת הגוים הם כי לולי רשעתם לא ענשם השם יתעלה בזה העונש כי מעשה ידיו כלם ולזה אמר לאברהם כי לא שלם עון האמורי עד הנה ולפי שלא תספיק זאת הסבה לבד בהורשת הארץ לישראל ביאר שזה הטוב היה לישראל מצד ברית השם יתעלה עם האבות לא בצדקת ישראל לבדה כי אל היתה עדין באופן שתספיק בכמו זאת ההשגחה הנפלאה והנה היה התועלת בזה אולי אם יחשבו ישראל כי צדקתם היתה סב בירושת הארץ עם רשעת הגוים ההם הנה בראותם כי כל הגוים עובדי ע"ז לא ייראו אם יעשו כמעשיהם שיורשו מן הארץ כי אינם צדיקים מהם בדדרך שיתן להם הש' יתע' הארץ בצדקתם אך עתה שידעו כי רשעת הגוים היתה הסבה בזה ולא היתה הארץ לישראל כי אם מצד ההשגחה הפרטית אשר היה דבוקה באבות יש לירוא שברשעתם תאבד הארץ מהם ע"י שאר הגוים כשתהיה להם מצד ההשגחה הכללית:
@268 **וידעת כי לא בצדקתך וגו'.** ביאר להם כי לא בצדקתם יתן להם השם יתעלה הארץ לפי שהם עם קשה ההעתק מהפחיתיו' אשר גדלו עליהם במצרים ויורה זה כי מעת צאתם ממצרים עד בואם לערבות מואב היו תמיד ממרים עם השם יתעלה וזה כי בהיות משה בהר חורב לקבל התורה סרו ישראל מהר מאמונת השם יתעלה עם מה ששמעו באזניהם עשרת הדברים מהש' יתעל באמצעות הקול הנפלא ועשו להם עגל מסכה.
@271 והנה ספר אז לישראל היותו יושב אז בהר מ' יום ומ' לילה בזולת אכילה ושתיה והלוחות שנתן לו השם יתע' היו כתובים באצבע אלהים והיו בהם עשרת הדברים ששמעו כם בזה האופן הנפלא במעמד הר סיני לפרסם לכל ישראל אלו הנפלאות וספר שכבר רצה השם יתעלה להשמידם אז לולי תפלת משה והוא ירד מן ההר וראה חטא ישראל הנפלא והיה זה סבה אל ששבר הלוחות מרוב כעסו כאלו הורה בזה כי לשואת נתן תורה לישראל כי תכף עברו על היותר קשה מנה והוא דבור לא יהיה לך:
@280 **ואתנפל לפני השם בראשונה מ' יום וגו'.** ירצה לפי מה שאחשו' כי הראשונ' בסוף המ' יום כשרא' משה כעס השם יתע' על יש' התנפל לפניו ובקש ממנו שלא יכלה עמו באפו ואחר ירד תכף לנקו' העון כפי מה שאפשר כי לא יתכן שיתפלל לשם יתעלה בעדם והם עדין מחזיקים ברשעתם ולזה ירד תכף מההר ושבר הלוחות בראותו מעשה העגל וצוה להרוג כי העובדים ולשרוף העגל להאבידו ואחר זה היה יותר נכון שיבקש מה' ית' שישוב חרון אפו מישראל אחר שביער הרע מקרבם. והתנפל לפי השם יתעלה בראשונה. שהתנפל לפניו שלא יכלם תכף כמו שזר עליהם ועמד בזה ההתנפלות השני מ' יום ומ' ילה בזולת אכילה ושתיה עד שנעתר לו השם יתעלה וכבר ביארנו על דבר קרח כי יתכן שיענש בחטא אחד כל העם מצד היותם מתאחרים ולזה לא הספיק למשה בערו הרע מקרב ישראל להשיב חרון אפו מהם והוא אפשר שנאמר כי זה בראשונה שב אל אמרו מ' יום ומ' ליה לחם לא אכלתי ומים לא שתישי ויהיה הרצון בזה וכבר התנפלתי לפי יי' וכמו שעמדתי בראשונה מלאכול ולשתות מ' יום ומ' לילה כן עמדתי אז מלאכול ולשתות מ' יום ומ' לילה:
@282 **ובאהרן התאנף יי' וגו'.** הנה אף השם יתעלה היה על אהרן על שכבר היה סבה באופן מה לחטא ישראל ואף על פי שהיתה כונתו טובה כמו שביארנו בפרש' כי תשא והעד שהיתה כונתו טובה שכבר נמחל לו ונתנה הכהונה לו לזרעו וזה לא היה ראוי אם היה חושב להעשות כומר לע"ז אך היה ראוי שיהיה ענשו יותר חזק מהאנשים שהשתחוו לעגל שלפי יתרון מעלת החוטא ראוי שיהיה העונש יותר גדול ועוד כי משה זכר בזה המקום שהתפלל על ישראל אחר הריגתו לחוטאים ולזה הוא מבואר כי הוא התפלל על אשר לא חטאו בזה מצד עצמם ואמר אחר זה ואתפלל גם בעד אהרן וזה ראיה שלא חטא אהרן בזה כי אם במקרה אך הצילם מהחטא לפי כוחו ומפני מה שנמשך במקרה מהחטא לישראל בסבתו הוצרך אל שיתפלל משה עליו להצילו מההשמד וכבר הרחבנו המאמר בזה בפרשת כי תשא.
@286 והנה להשים הספור לבאר להם שהם היו תמיד ממרים עם הש' יתע' זכר להם ענין מה שהקציפו השם יתעלה בתבערה ובמסה ובדבר המרגלים קודם שיבאר הענין מהתפלה שהתפלל לשם יתעלה בהר להשיב חרון אפו על כל החטא שהיה בעשיית העגל כבר ביארנו ענין התפלה הזאת הפרש' כי תשא וממה שבארנו שם התבאר הכונה במה שנזכר התפלה בזה המקום כי הכונה אחת ואם הומר הלשון והסדור בדברים:
@292 **בעת ההיא אמר ה' אלי פסל לך שני לוחות אבנים וגו'.** כבר התבאר בפרשת כי תשא כי אז עמד גם כן בהר מ' יום ומ' ליה בכל פעם בזולת אכילה ושתייה. רוצה לומר כשנתנו לו הלוחות השניות ולא התבאר בזה המקום ששלש פעמי' עמד שם משה בהר ארבעים יום וארבעים לילה בכל פעם בזולת אכילה ושתיה והרצון נאמרו לחם לא אכלתי שלא אכל מזון שאם היה הרצון בו לחם ממש לא היה זה פלא כי גם ישראל היו בלתי אוכלים לחם אך היו אוכלים המן ולזה יחוייב שיהיה הרצון באמרו לחם לא אכלתי שלא אכל שום מזון וזה ממה שאין ספק באמתתו עם שכבר מצאנו באליהו שעמד מ' יום מלאכול:
@297 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** רוצה לומר. מבארות בני יעקן וממוסרה כמו שנזכר בפרשת מסעי שנאמר ויסעו ממוסרה ויחנו בבני יעקן שם מת אהרן ידוע שלא מת אהרן במוסרה ולא בבני יעקן ואולם מת בהר ההר ונקבר שם וזה היה אחר מסעו' רבות מעת היותם בבני יעקן כמו שנזכר בפרשת מסעי ולזה היה הרצון בזה כי שם באלו המסעות שנמשכו זה לזה מת אהרן ונקבר שם על דבר מי מריבה וכאלו היה זה הספור לספר מרי ישראל ולזה הזכיר בארות בני יעקן כאלו באר כזה כי בכל המקומות שעברו אז עד היותם בקדש היה להם מים לשתות ולזה נתרעמו ישראל על מי מריבה בזולת סבה גדולה תביאם אל זה ולזה כפר כי משם נסעו הגדגוד' יטבתה כמו שנזכר בפרשת מסעי והנה זכר ביטבתה שהוא ארץ נחלי מים להעיר עוד כי בסבת מי מריבה מת אהרן כמו שנזכר בפרשת פרה ולהעיר שבכל המקומות שבאו באלו המסעות היה להם מים עד בואם בקדש כמו שקדם:
@299 **בעת ההיא הבדיל ה' את שבט לוי.** רוצה לומר בעת מתן תורה לשאת ארון ברית ה' לא זכ' נשיאת שאר הכים לפי שזה לא יהיה אחר בא ישראל אל המנוחה ואל הנחלה אך נישאת הארון יהיה במלחמה אחר בא ישראל אל המנוחה ולא הנחלה כמו שנתבאר מהמלחמה שהיה בימי עלי:
@299 **לעמוד לפני יי' לשרתו.** מגיד ששרו' הלוי' הוא מעומד:
@299 **ולברך בשמו.** הנה מזה התבאר הכונה באמרו ושרת בשם ה' אלהיו וזה כי השרות הוא להודות לשם יתעלה ולברכו בפה בעת עשיית הקרבנות אך הכהנים היו מריעים בחצוצרות והלוים היו משוררים בפה וזה נתבאר ביאור קצת מזה המקום והנה נשלם הביאור בזה בספר עזרא:
@301 **ואני עמדתי בהר מ' יום כימים הראשונים וגו'.** הרצון בזה כי העלותו בהר על דבר הלוחות השניות עמד שם מ' יום ומ' לילה ואז התחנה לשם יתעל שילך בקרב ישראל ותדבק השגחתו בהם כמו שנזכר בפרשת כי תשא כי כבר אמר השם יתעלה על דבר העגל שילך מלאכו לפניהם אך השגחתו יתע' לא תדבק בהם וזה באמת היה דבר רע לישראל מאד ולזה השתדל מש בעת ההיא אל שירצה השם יתעלה ללכת בקרב' כי בזה יתכן להם שיירשו את הארץ ואף על פי שלא הגיע העת עדין וכאשר נעתר לו השם יתעלה על זה אמר לו שילך למסע לפניהם ויבאו ויירשו את הארץ כי לא היו צריכים להמתין הקץ אחר שהשגחת השם יתע' הדבק בהם והנה אז ערבב הענין מרי ישראל על דבר המרגלים ונתאחרו מפני זה במדבר מ' שנה כמו שקדם והנה זכר בזה המקום להזכיר לישראל כי הם היו ממרים עם השם יתעלה תמיד כמו שקדם:
@303 **ועתה ישראל מה ה' אלהיך וגו'.** רוצה לומר שהוא אינו מעמיס עליך דבר שיהיה ראוי שיכבד עליך כי מה שישאל מעמך לקיים מצותיו אינו כי אם לטוב לך ולעבוד את ה' אלהיך וגו' הכונה בו ענין התפלה כמו שביארנו באמרו ואותו תעבדו:
@303 **ועבדת את ה' אלהיך בכל לבבך ובכל נפשך.** בטעם אמרו ומצאת כי תדרשנו בכל לבבך ובכל נפשך והרצון בו שתהיה תפלתך לו בכוונה שלמה יתאחדו כחתיך המתעוררים והם הנכללים נאמרו בכל לבבך וכחותיך המשיגים והמציירים שהם הדמיון והשכל והנלוים אליהם והם הנכללים באמרו ובכל נפשך:
@307 **ומלתם את ערלת לבבכם.** רוצה לומר שתסירו אוטם לבבכם באופן שתשמעו אל מצות השם יתעלה בכללם. ולא תקשו עוד ערפכם. שלסור מהתכונות הרעות שנשקעתם בהם כי הרבה מרים עד עתה ודעו כי השם יתעלה שהוא מנהיג אתכם הוא אלוה המנהיגים הנבדלים כי הם עלולים ממנו ומהשפע שיושפע ממנו יעשו מה שיעשו והוא המושל על כל מי שיש לו שום ממשלה והוא עושה גדולות וגבורות ונוראות ולזה יעניש אתכ' אם תחטיאו ואף על פי שלא יסודר לכם אז רע מצד ההשגחה הכוללת ולא תוכלו להמלט ממנו שלא יגיע לכם ענשו כי הוא בלתי נושא פנים לגדולים כי לפניו יהיה הגדול כקטון בהשפטו ולא יקבל שוחד שתבטח לפייסו בו כי הוא בלי צריך לדבר מנבראיו ולזה לא יצ' מלפניו רק יושר ומפני זה הוא עושה משפט השפלים החלושים כשיהיו עשוקים והם היתום והאלמנה:
@309 **ואוהב גר לתת לו לחם ושמלה.** ר"ל שהוא משגיח על הנרדפים כמו הענין בגר שאין לו עוזר מפני שאין לו קרובים והנה השם יתעלה ישגיח בו לתת לו לחם לאכול ובגד ללבוש וזה אמנם סודר ממנו יתעלה בו לפי מה שאחשוב מצד ההשגחה הכוללת שבה נותן לחם לכל בשר ואף על פי שאינו באופן שיתכן שתדבק בו ההשגחה הפרטי':
@310 **ואהבתם את הגר.** צוה לאהוב את הגר כי אין בשער עזרתו ולזה צוה עליו במקומות רבים מהתורה:
@311 **את ה' אלהיך תירא.** כבר פרשנו אלו המצות הנכללות בזה הפסוק בפרשת ואתחנן מלבד אמרו ובו תדבק והנה הרצון בו שישתדל שידבק בו כפי כחו וזה יהיה כשילמד התורה והחכמה אשר יתישר מהם להשגתו יתעלה לפי מה שאפשר וזהו הדבקות ולפי שזה לא יתכן לאדם אם לא באמצעות החכמים שילמדוהו זה כמו שביארנו בביאורנו לשיר השירים הנה כללה זאת המצוה שידבק בחכמים כי הם המישירי' אותו לקיים זאת המצוה והם יעמידו איש ואיש על מה שאפשר לו מזה:
@312 **הוא תהלתך.** רוצה לומר אין ראוי שתהלל זולתו כי הוא עשה אתך כל הנפלאות עצומות אשר ראו עיניך במצרים ועל הים ובמדבר בשבעים נפש ירדו אבותיך הנה זה אחד מהפלאים העצומים כי בארץ מצרים שדמו לכלות אתכם וענו אתכם תכלית הענוי כדי למעט אתכם השגיח ה' יתע' בכם באופן ששם שתכם בזה הרבוי הנפלא בזמן לא ארוך מאד כי לא עמדו שם כי אם מאתים ועשר שנה כמו שביארנו בספר ואלה שמות:
@314 **ואהבת את השם אלהיך וגו'.** למדנו מזה שהתורה הזאת היא נצחית כאמרו כבר שנשמור את משמרתו וחקתיו ומשפטיו כל הימים:
@315 **וידעתם היום כי לא את בניכם.** רוצה לומר אתם יודעים כל זה כי אין דברי את בניכם שלא ידעו ולא ראו כל אלו הנפלאות שזכר תכף כי עיניכם הרואות את כל מעשה השם הגדול אשר עשה:
@321 **ושמרתם את המצוה.** ר"ל הנה לזאת הסבה ראוי שתשתדלו בשמירת כל מצות השם יתע' כדי שתירשו את הארץ ותאריכו ימים עליה כמו שייעד להם השם יתעלה כי אתם ראיתם שקיים כל מה שהבטיח ועשה אלו הנפלאות העצומות אשר ייעד חדושם קדש התחדשם:
@323 **לא כארץ מצרים היא וגו'.** ידוע שאין מטר יורד במצרים ולזה יצטרכו להשקו' הארץ הנעבדת והנזרע ברגליהם:
@323 **כגן הירק.** להוליך מן מי היאור אל התעלו' אשר בהן ישקו השדה ההוא בל ארץ ישראל אינו כן כי למטר השמים תשתה מים ואם תחשבו שהמטר ירד שם וימעטו מפני זה פרות הארץ היא הנה תדעו כי ליושר ירידת המטר שם ידמה שהשגחת השם יתעלה תהיה תמיד בה מראשית השנה ועד אחרית השנה לתת בכל עת מה שיאות לצמחים כאלו תאמר שינשב שם הרוח בעת הצורך אל הרוחות וירד שם מטר בעת הצורך אל המטר:
@326 **והיה אם שמוע תשמעו וגו' לאהבה את ה' אלהיכם.** הנה ביארנו זאת המצוה בפרשת שמע:
@326 **ולעבדו בכל לבבכם ובכל נפשכם.** רוצה לומר להתפלל לפניו בכוונה שלמה כמו שביארנו בזאת הפרשה והנה הקדים לזכירת זאת המצוה אהבת השם יתעלה כי היא תסבב השגת השם יתעלה כפי מה שאפשר ובזה תהיה התפלה נשמעת ואחר ביאר שאם יעשו זה ימשך להם מהשגה הפרטית שיתן להם השם יתע' מטר ארצם בעתו בעת הזריעה והוא יורה ובעת נתינת התבואה פריה והוא מלקוש באופן שתתן הארץ דגן ותירוש ויצהר לא תמנע מזה בשנים מהשנים ויתן עשב בשדה שתאכל הבהמה הרועה שם ויאכלו וישבעו כי לא יחסר כל טוב:
@329 **השמרו לכם פן יפתה לבבכם.** ביאר להם שאם יעבדו ע"ז יהיה כל זה בהפך כי השמים לא יתנו מטר והארץ לא יתתן את יבולה ולזה יחסר להם המזון ויאבדו מהרה לסבות אחרות זכרם במה שקדם ובמה שיבא כו שחרב והדבר ומה שידמה להם:
@331 **ושמתם את דברי אלה על לבבכם.** רוצה לומר שתתבוננו להם תמיד כדי שתקחו מוסר ותשמרו מצות השם יתעלה ולא תפנו לע"ז והנה סמך עליה ענין תפלין של יד להישירנו אל שהכוונה בזה היא שיהיו נגד הלב כמו שביארנו בפרשת ואתחנן:
@331 **וקשרתם אותם לאות על ידכם. והיו לטוטפות בין עיניכם. ולמדתם אותם את בניכם.** כל זה ביארנו בפרש' ואתחנן ואולם אמר ושננתם לבניך וכאן אמר ולמדתם אותם את בניכם כי לעומק הדברים הכוללים פרשת שמע ולהיות מהשרשים היותר עקריים יצטרך המלמד לשנות הלמוד פעמים רבות מה שאין כן בזאת הפרשה כי איננה רבת העומק:
@332 **לדבר בם בשבתך בביתך וגו'.** הנה כבר ביארנו דבר זאת המצוה בפרשת ואתחנן וכאלו ביאר בכאן שצריך לחנך הקטנים בקריאה שמע ובפרשת והיה אם שמוע בעת השכיבה ובעת הקימה:
@333 **וכתבתם על מזוזות ביתיך ובשעריך.** כבר בארנו זאת המצוה בפרשת ואתחנן ובכאן התבאר שבמזוזות נכתבו פר' שמע ופר' והיה אם שמוע ובשכבו ובקומו חייב אדם לקרות שי אלו הפרשיות אך בתפלין של ראש ושל יד יהיו עם אלו השתי פרשיות אחרות והם קדש לי כל בכור והיה כי יביאך:
@334 **למען ירבו ימיכם וגו'.** בעבור שייעד בקיום התורה טוב נצחי לכל אחד מהדורות דור אחר דור:
@334 **כימי השמים על הארץ.** לדמנו מזה שהתורה היא נצחית גם כן כימי השמים על הארץ וזה ממה שלא נצטרך אל ביאור:
@335 **כי אם שמור תשמרון את המצוה הזאת וגו'.** ללכת בכל דרכיו. רוצה לומר להדמות אל מנהגי השם יתעלה ופעלותיו כפי היכולת כי הוא צדיק וישר ומשפיע מטובו לכל הנמצאות ומזה יקנה האדם מנהג להתנהג ביושר ואמת ולהטיב לזולתו כפי מה שאפשר לו הנה זה באור מה שצריך לזאת הפרשה:
@339 **זכר** שכבר נתן השם יתעלה לפני ישראל ברכה וקללה והענין הוא בבחירתם וזה שאם ישמעו אל מצות השם אתעלה תבא להם הברכה והקללה אם לא ישמעו אל מצותיו:
@341 **וסרתם מן הדרך אשר אנכי מצוה אתכם ללכת אחרי אלהים אחרים.** ידענו שכבר היו שם קללות כשיעברו על אחת משארנין המצו' ואף על פי שלא יעבדו עבודה זרה כמו שנזכר מענין או הקללות בפרשת כי תבא ולזה יהיה הרצון בזה שאם יסורו ממצוה אחת ממצות התורה הנה יהיה זה סבה אל שיעבדו עבודה זרה כי זה יהיה סבה אל שיקלו במצות התורה ויעברו על החמורות אחר עברם על הקלות:
@342 **והיה כי יביאך וגו'.** כבר נתבאר בפשרת כי תבא שזאת המצוה נתחייבו בה תכף כניסתם לאר אחר עברם הירדן ולזה תמצא בספר יהושע כי אחר שהכה יהושע את יריחו ואת העי קיים זאת המצוה כמו שנתבאר מעניינה בפרשת כי תבא וזכר שם שכבר עשה יהושע כאשר צוה משה עבד יי' את בני ישראל ולזה הוא מבואר שמה שאמר בזה המקום והיה כי יביאך יי' אלהיך אל האר אין הרצון בו שימתינו שיירשו את הארץ אבל תכף שיוכלו לקיים זאת המצוה שם יקיימוהו ולזה לא אמר בזה וירשתם אותם וישבתם בה כמו שאמר במצות הנזכרות אחר זה וזה כי הכונה היתה בזה כדי שיהיו ישראל יותר זריזים בשמירת התורה מפני שמיעתם אלו הברכות והקללות ולפי שזריזותם בשמירת התורה היה לו מבוא עצום בירושתם את הארץ כמו שנזכר בזה הספר פעמים רבות חוייב שיעשו זה תכף היותם שליטים במקום ההוא אשר בו יקיימו זאת המצוה לפי מה שנתבאר מעניינה בפרשת כי תבא וכבר נתבאר זה גם כן שם באופן שלם כמו שיתבאר במה שיבא בג"ה:
@342 **ונתת את הברכה על הר גריזים ואת הקללה על הר עיבל.** למדנו מזה שבאופן שיתן הברכה על הר גריזים יתן הקללה למול הר עיבל וכבר התבאר בפרשת כי תבא שנתינת הקללה למול הר עיבל תהיה תחלה בפרט לעובר על מצוה אחת מהמצות הנזכרות שם ואחר כך תהיה בכלל וכן הענין בנתינת הברכה למול הר גריזים כי כבר תהיה בפרט כשיאמרו ברוך למי שמקיים המצוה על כל ארור שכתב תחילה בפרשת כי תבא למי שיעבור על המצוה ההיא וכבר תהיה הברכה על הפרטי' קודמת על הקללה על הפרטים כמו שמצאנו שם הברכה על הכלל היא קודמת לקללה על הכלל והנה היה הסדר כן שהלוים אמרו תחלה ברך על מי שמקיים פרט ופרט כנגד הר גריזים ואחר כך אמר ארור על כל מי שיעבור על כל פרט ופרט ואחר זה אמרו כל הברכות הנכתבות בפרשת כי תבא כנגד הר גריזים והם נאמרות בכלל על מי שמקיים וישמור מצות השם יתעלה ואחר זה הפכו פניהם למול הר עיבל ואמרו קללות והנכתבות שם בכלל למי שלא ישמע אל דבר התורה ולזה אמר בספר יהושע כאשר צוה משה עבד ה' לברך ישראל בראשונה ואחר כן קרא את דברי התורה הזאת הברכה והקללה. למדנו מזה שכבר ברכו העם בראשונה בברכות לא תכתבו בתורה ואחר כן קראו כל הכתו' בפרשת והיה כי תבא מהברכות והקללות על הסדר הכתוב שם ועוד למדנו מזה שכמו שנתבאר בקללות שהיו חלוף ביניהם אלא שהברכה היתה למול הר גריזים והקללה למול הר עיבל:
@343 **הלא המה בעבר הירדן אחרי דרך מבא השמש.** רוצה לומר שההרים האלו ימצאו כשיעברו את הירדן דר ךהולך ממזרח למערב כי לפאת מערב מהירדן היתה ארץ כנען והארץ אשר נתן לשני השבטים וחצי היתה מעבר הירדן מזרחה כמו שזכר במה שקדם ואולם למה נתן הברכה אצל הר גריזים והקללה אצל הע עיבל הנה לא אדע בה טעם אלא שלהראות עוצם ההבדל שיש בין הענינים האלו רצה להבדיל ביניהם עד שלא תהיה הקללה ואנשיה בצד שתהיה הברכה ואנשיה כי ההבדל בין שומרי התורה ובין העוברים על דבריה עצום מאד ולזה הוכרח אל שיתן הברכה לצד אחד והקללה לצד אחר ואם היינו יודעים צדדי אלו ההרים אולי היינו נותנים סבה מיוחדת למה תהיה הברכה אצל הר גריזים והקללה אצל הר עיבל והנה ידענו כי השם יתעלה צוה לבנות מזבח בהר עיבל ולכתוב שם משנה תורה באבנים שישדו בשיד והנה הושמה הקללה אצל הצד ההוא שיהיה בו המזבח והיה בו כתוב משנה תורה כדי שיתבארו להם דברים אשר עליהם היתה הקללה אם לא יקיימום כאלו יאמר שאם יעשו כמו זאת העבודה לא לשם יתעלה אם לא יקיימו משנה התורה הכתוב שם הנה תדבק הקללה בהם והנה זאת המצוה לא היתה אלא לפי שעה:
@344 **כי אתם עוברים את הירדן לבא לרשת את הארץ וגומ'.** ירצה לפי מה שאחשוב שכאשר יעברו את הירדן לבא לרשת את הארץ יקיימו זאת המצוה שזכר רוצה לומ' נתינת הברכה על הר גריזים והקללה על הר עיבל אמנם אח' שיירשו את האר' וישבו בה ישמרו לעשו' בה תמיד כל החקי' והמשפטי' אשר זכר אחר זה והוא לעקור ע"ז מארצם ושאר המצות הנמשכות לה אשר נוהגות באר לבד או בארץ ובחוצה לארץ ולא ינהגו בכניסתם לבד כמו הענין בזאת המצוה אך ינהגו תמיד קצתם באר לבד וקצתם בארץ ובחוצה לארץ או ירצה בזה שכבר הודיע להם שכאשר יעברו את הירדן לבא לרשת את הארץ שלא יתעכבו אחר זה בירושת הארץ כמו שנתעכבו במדבר עד שכבר הודיעם בזה שעברם את הירדן יישירם לבא לרשת את הארץ מצד המופת הנפלא שיעשה להם ה' ית' בעברם את הירדן שנתפרסם זה לכל מלכי האמורי אשר בעבר הירדן ימה והכנעני אשר על הים וימס לבבם ולא היה בהם עוד רוח מפני בני ישר' כמו שנזכר בספר יהושע עם שזה המופת הנפלא נעשה באופן שנתיישרו בו ישראל מאד להאמין בשם יתעלה שהיה מבא גדול לירושתם הארץ:
@345 **ושמרתם לעשות.** הנה מפני שלא ישמור לעשות מי שלא ידע מה שצוה הנה יחוייב מזה שילמדו המצות כדי שיעשום והנה השמירה היא בלב כמו הענין זכירה והכונה בזה שישמרו בלבם אלו המצות כדי שיתיישרו לעשותם בעת הצורך. כי הם נוהגות תמיד:
@345 **את כל החקים ואת כל המשפטים וגו'.** גם אחר שתירשו את הארץ ותשבו בה כי הם נוהגים תמיד והנה נוהגים קצתם בארץ לבד וקצתם נוהגים בין בארץ בין בחוצה לארץ:
@346 **אלה החקים והמשפטים אשר תשמרון לעשות בארץ.** זכה עתה החקים והמשפטים שנוהגים בארץ כל הימים תמיד שיהיו ישראל חיים על האדמה ההיא רצוני לומר בארץ ישראל:
@347 **אבד תאבדון את כל המקומו' אשר עבדו שם הגוים אשר אתם יורשים אותם וגו'.** הנה זאת המצוה היא לעקור עבודה זרה מארץ ישראל והיא נוהגת תמיד בכל עת שתמצא עבודה זרה שם והוא מבואר מענינה שאי אפשר בה שתנהג אלא בארץ ישראל כי כבר ביארה התורה שזאת המצוה היא לעקור ע"ז מארץ ישראל:
@347 **את כל המקומות אשר עבדו שם.** מגיד שאנחנו חייבים בארץ ישראל להרוס הבתים שעבדו בהם עבודה זרה ולאבדם כשנבנה הבית לעבודה זרה כמו שיתבאר במה שיבא:
@347 **את אלהיהם על ההרים הרמים ועל הגבעות ותחת כל עץ רענן.** למדנו שאנחנו חייבים לאבד העבודה זרה ששמו באי זה מקום שיהיה בארצינו והנה זכר אלו המקומות כי הם היו נוהגים שישימו שם אלהיהם ולמדנו מזה שאם בטלו אותם הגוי' עבודה זרה ההיא שלא נחוייב לאבדה שאינה אלהיהם בעת שמצאנוה והתורה אמרה את אלהיהם על ההרים שיהיו אלהיהם בעת שמצאנום וכן אמר בפרשת ואתחנן פסילי אלהיהם תשרפון ואמר בזה המקום ופסילי אלהיהם תגדעון ולדנו עוד מזה שאם השתחוו להרים או לגבעות אין אנחנו צריכין לאבדן כי התורה זכרה שאלהיהם על ההרים צונו לאבד ולא ההרים כי לא נקראם המקומות אשר עבדו שם את אלהיהם ולזה גם כן אם עשו מהם עבודה זרה לא נחוייב לאבדם כי אין בהם תפיסת יד אדם כמו שאם השתחוו לשמש או לירח לא תאסר לנו הנאתם ומזה המקום למדנו שהע"ז שהוא תחת עץ רענן לא נחוייב לאבד כי אם הע"ז לא העץ ההוא אחר שאין בו תפיסת יד אדם כמו הענין בהרים ובגבעות אך אם יש בו תפיסת יד אדם כגון שנטעון לע"ז יחוייב לאבדו וזו היא אשרה שחייבה תורה לשרפה:
@348 **ונתצתם את מזבחותם.** רוצה לומר המזבחות שעבדו בהם ע"ז והנה לא צוה לאבדו אלא לנתצו. וזה יהיה כשלא היה בו תפיסת יד אדם לע"ז וחוייבו לנתצו כדי שלא ישאר בו שם מזבח וכן הענין באבן אשר יעשו ממנה מצבה להשתחוות עליה לע"ז כיון שאין בה תפיסת יד אדם לעבודה זרה ישברוה והיא מותרת בהנאה והנה ישברוה לאבד את שמה שלא תקרא מצבה:
@348 **ואשיריהם תשרפון באש.** כבר בארנו שזה יהיה באין שנטעו תחלה לע"ז שיש בה תפיסת יד אדם בכולו:
@348 **ופסילי אלהיהם תגדעון.** זה יהיה באילן שלא נטעון תחלה לע"ז ועשה בה מעשה ע"ז כאלו תאמר שגדעו ופסלו לע"ז הנה מה שצמח אחר זה או מה שיהיה בו תפיסת יד אדם לעבודה זרה אסור ולזה מגדע אותו והשאר מותר ואולם בפרשת ואתחנן אמר פסילי אלהיהם תשרפון באש וזה אמנם יהיה בפסל שנפסל כולו לע"ז כמו שחצב אבן לע"ז:
@348 **ואבדתם את שמם מן המקום ההוא.** זה יהיה בבית שעבדו בו ע"ז ולא היה בו תפיסת יד אדם לעבודה זרה שכבר היה בנוי לא לשם ע"ז ולזה חודש בו דבר לעבודה זרה הנה יספיק שיאבד זה השם מהמקום ההוא ר"ל שיסירה משם ויעבדה כמו שנתבאר בעבודה זרה שהושמה תחת עץ רענן שהעץ ההוא לא נאסר אך יאבד ע"ז שהושמה תחתיו או יהיה הרצון שישתדלו עכ"פ לאבד שם ע"ז מן המקום ההוא שהוא בו אם היה כתוב שם כמו שנהגו בהרבה מאלו:
@349 **לא תעשון כן ליי' אלהיכם.** הוזהרנו בזה שלא לאבד ולנתץ מה שהוא לשם שמים ולזה יתבאר שהנותץ אבן אחת מהמזבח או מהיכל דרך השחתה עובר בלאו ונכלל בזה גם כן שאם אבד שם מהשמות הקדושים עובר בלאו שנאמר ואבדתם את שמם וגומ' לא תעשו כן ליי' אלהיכם:
@350 **כי אם אל המקום אשר יבחר יי' אלהיכם מכל שבטיכם וגומ'.** לא תעשון כן ליי' אלהיכם כמו שהיו עושים הגוים לעבוד אלהיהם במקומות רבים כאמרו אבד תאבדון את כל המקומות אשר עבדו שם הגוים כי אתה לא תעבדוהו כ"א במקום מיוחד והוא המקום אשר יבחר יי' אלהיכם מכל השבטים שם לבד תהיה זאת העבודה לה להעיר על ייחוד הנעבד בה ולזה היה במקום מיוחד ועל יד משפחה מיוחדת והנה אמר מכל שבטיכם לפי שמקו' בית המקדש קנוהו כל השבטים כמו שנתבאר במה שנזכר בסוף שמואל שכבר קנה דוד את גורן הארונה ואת הבקר בכסף חמשים ובמקום אחר אמר שקנהו שש מאות שקלים להורות שמכל אחד מהשבטים לקח חמשים שקלים ואמנם ירושלם היה מאחד השבטים כמו שנתבאר בספר יהושע. ולזה אמ' אחר זה במקום אשר יבחר יי' באחד שבטיך לשום שמו שם ר"ל השרות שכינתו שם ויהיה הרצון בזה שישים שמו שם לשכנו או ירצה בזה מענין ברכת כהני' שנא' שם ושמו את שמי על בני ישר' ולזה אמר אחר זה לשכנו ר"ל להשרו' שכינתו שם ואע"פ שברכת כהנים נאמרת בכל מקום שנא' בכל מקום אשר אזכיר את שמי אבא אליך וברכתיך הנה נלמד מזה ששם המפורש לא יהיה נזכר על יד הכהנים כי אם בבית המקדש לזה אמר לשום את שמו שם אך בשאר המקומות יזכרוהו בכינוי ולזה אמ' אשר אזכיר את שמי שהוא מעניין אזכרה כמו שביאר' שם ר"ל שאריח שמי שם אך לא יהיה נזכר שם בכתבו כמו ריח הדבר שאינו הדבר בעל הריח:
@350 **ובאת שמה.** כבר נתבאר במה שקדם ששלש פעמים בשנה יחוייב להם לבא שמה:
@351 **והבאתם שמה עולותיכם וגומ'.** לפי שסמך זה אל אמרו ובאת שמה למדנו מזה שברגל הראשון שיבא שם יחוייב להביא שם קרבנותיו ונדריו שנא' ובאת שמה והבאת' שמה עולותיכ' הם של יחיד או של צבור:
@351 **זבחיכם.** הם זבחי שלמי צבור או זבחי שלמי יחיד:
@351 **מעשרותיכם.** הם של יחיד. והם שני מעשרות שהם נאכלים שם לבעלים אחד מעשר שני מדגן תירוש ויצהר ואחד מעשר בהמה הנזכרת בסוף פרש' אם בחוקותי:
@351 **ותרומת ידיכם.** אלו בכורים שהיו ישר' מחוייבים להביאם שם בידיהם כמו שנזכר בפרש' והיה כי תבא ולקח ההן הטנא מידך:
@351 **נדריכם ונדבותיכם.** זו עולה הבאה בנדר ונדבה או שלמים כי אלו באים בנדר ונדבה כמו שנזכר בפר' אמור אל כהנים:
@351 **ובכורות בקרבם וצאנכם.** הוא פטר רחם שהוא לכהנים והם יקריבו לש"י אמוריהם והשאר נאכל לכהנים והנה לא זכר חטאות ואשמות לפי שכבר נתבאר בהם שמקו' שחיטתם הוא מקו' שחיטת העולה עם שהדברים ק"ו שאם לא הותר להקריב קדשים קלים כי אם בזה המקו כל שכן קדשי הקדשים:
@352 **ואכלתם שם לפני יי' אלהיכם.** ר"ל במקום אשר יבחר יי' יאכלו הנאכל מכל אלו שזכר ואולי לזאת הסבה שתק חטאות ואשמות לפי שכבר נתבאר בהם שמקום שחיטתן הוא מקום שחיטת העולה עם הדברים ק"ו לקצר המאמר בזה המקום כי אותם אינם נאכלים כי אם לפני' מן הקלעי' ואלו שזכר פה נאכלים לפני' מן העיר:
@352 **ושמחתם בכל משלח ידכם וגומ'.** ר"ל בכל מה שתוכלו לשלח ידכם לעשות ממנו שלמי שמחה במועדי' כשתבואו בבית הבחירה לראו' פני הש"י תשמחו שם אתם ונשיכם ואחשוב כי לנשי' מצות ראיה רשות:
@352 **אשר ברכך יי' אלהיך.** הנה אלו השלמים הם לפי הברכה אש ברך אותך ש"י כי העשיר מרבה בשלמים אלו:
@353 **לא תעשון ככל אשר אנחנו עושים פה היום וגו'.** אמר זה לפי מה שאחשוב שכבר הותרו הבמות לישראל בזולת עולה ושלמי' כמו שנזכר בפר' אחרי מות ולזה היה יכול להקריבם זר כי לא נמנע מזר אלא מלקריב אל משכן יי' ולא היה אסור הקרבת עולה ושלמי' בבמת יחיד כי אם במדנ' לסבה בעינה שנאסרה שם בשר תאוה כמו שבארנו במה שקדם אמנם אחר זה שהותר בשר תאוה הותרו אלו לעשות בבמה יחיד ולזה מצאנו בשאול שהקריב את העולה בבמת יחיד וכן מצאנו בדוד ואל גנו אותם הנביאים שהיו שם על זה ומזה נלמוד גם כן כי ליחיד הותר במת יחיד לא לצבור שנא' איש כל הישר בעיניו ולזה מצאנו שהמקריבי' בבמת יחיד היו יחידים:
@354 **כי לא באתם עד עתה אל המנוחה ואל הנחלה.** מגיד שכיון שבאו אל המנוחה נאסרו הבמות ואחר כך הותרו עד היותם אל הנחלה כי לא נאסרו כי אם כאשר באו אל המנוחה ואל הנחלה. והנה המחונה היה משכן שלה והנחלה היה בית המקדש שהיה בירושלם ואחריו נאסרו הבמות מכל וכל:
@356 **וכל מבחר נדריכם אשר תדרו ליי'.** אחשוב שרמז בזה אל הבהמות שאין בהם מום שנדר אותם ליי' והנה כל זה המאמר זולתי מעט שקצר בו כאלו העיר שכבר יהיו שם שני מקומו' אשר יבחר ה' והם המנוחה והנחלה שזכר תחלה:
@357 **ושמחתם לפי יי' אלהיכם וגו'.** אלו שלמי שמחה:
@357 **והלוי אשר בשעריך כי אין לו חלק ונחלה עמך.** מגיד שאם יש בידו מעשר ראשון שהוא חלק לוי נתנו לו. ואם לא נותן לו מן השלמי' או ממעשר עני:
@358 **השמר לך פן תעלה עולותיך בכל מקום.** ה"ה לשאר הקרבנות אך כתוב קצר ויורה על זה מה שאמר בפסוק אחר זה כי אם במקום אשר יבחר ה' אלהיך באחד שבטך שם תעלה עולותיך וגו' ושם תעשה כל אשר אנכי מצוך. רוצה לומר שאר הקרבנות שחייב קודם זה להביא במקום ולזה יחוייב שיהיו כלם בלא תעשה:
@360 **רק בכל אות נפשך תזבח ואכלת בשר.** ראוי שתדע שאי אפשר שתהיה הכונה בזה להתיר בשר תאוה שנאסר במדבר שהרי זכר אחר זה ענין התר בשר תאוה בפרשת כי ירחיב יי' אלהיך את גבולך ואי אפשר שיתיר זה בקרבנות שהרי ביאר שאין לו רשות להביאם כי אם במקום אשר יבחר ה' ובהיות הענין כן הנה לא ישאר אלא שיהיה זה המאמר בפסולי המוקדשין והם אשר יש בהם מום רע כמו שנזכר בבכור בפר' כל הבכור שאם יש בו מום רע והוא מום קבוע לא יזבחנו ליי' ואם שם בשעריך תאכלנו הטמא והטהור יחדו כצבי וכאיל רק את דמו לא תאכל על הארץ תשפכנו כמים כמו שאמר זה בה המקו' ולזה הוא מבואר שזה מהמאמ' הוא בפסולי המוקדין כי כבר נתבא' למעלה שלא יחוייב הביאם שם כאמרו וכל מבחר נדריכם מגיד שהעי מומין לא יחוייב להביא שם ובהיות הענין כן כבר יתבאר בפר' בחקותי שגם הבהמה הטמאה יחוייב שתפדה בצאתה לחולין למדנו מזה שהוא יחייב באלו שיפדו ואמר תזבח לפי שלא הותר לגדלם אחרי שנפדו כי הם אסורים בגזה ועבודה כמו שהתבאר בפר' כל הבכור:
@360 **ואכלת בשר.** הבשר הותר לו לאכול אך לא יוכל לגדלם ויאכל החלב ואמר ואכלת שלא יותר לו להאכילו לכלבי' כי עדין יש בו קצת קדוש':
@360 **כברכת יי' אלהיך אשר נתן לך.** למד בזה דרך ארץ שיאכל האדם מהבשר לפי עשרו לא יותר וכאלו באר בזה שלא יאסר אם עבר זמנו שהיה ראוי שיאכלנו אם לא היה בו מום ואף על פי שזכר דינו דין קדש לקצת הדברים:
@360 **בכל שעריך.** מגיד שמותר לשחטו ולאכלו בכל המקומות הטמא והטהור יחדו כצבי וכאיל בעבור שלמדנו ממה שאמר תחלה שיש בו עדין קצת קדושה הוצרך לבאר שלא הוזהר הטמא מלאכלו אך טמא וטהור אוכלין בקערה אחת כמו הענין בצבי ואיל שאינן ראויין לקרבן:
@361 **רק הדם לא תאכלנו על הארץ תשפכנו כמי'.** הוצרך לומ' זה לפי שכב' ביאר שיש בו קצת קדושה. אולי יחשוב חושב שדמו יהיה אסור כדם קדשים. לזה ביאר שהוא כמים שמותרים בהנאה ואמ' על הארץ תשפכנו באר שאינו טעון כסוי כדם צבי ואיל:
@362 **לא תוכל לאכול בשעריך וגומ'.** הוזהר בזה שלא לאכל מעשר שני של דגן ותירוש ויצהר חוץ מהמקום אשר יבחר יי' ושלא יאכלו הכהנים הבכורות חוץ מהמקום ההוא ולא השלמים והנה אמר כל נדריך אשר תדור מה שלא אמר כן במה שקדם אך אמר נדריכם וכל מבחר דריכם לכלול העולה עם השלמים כי היא באה בנדר ונדבה כמו השלמים ואי אפשר שנאמר שיכלול בזה פסולי המוקדשין כי כבר הורו לאכול בשערים כמו שקדם ולזה יהיה זאת האזהרה שלא יאכל מבשר העולה באי זה מקום שיהיה כי לא הותר אלא למזבח כאמרו ועשית עולותיך הבשר והדם והנה הדברים קל וחומר אם הדברים שהתר להם במחיצתו נאסר חוץ ממחיצתו לא כל שכן במה שבכל המקומות הם חוץ למחיצתו לאכילת אדם ובכלל הנה נלמד מזה הענין שלא יותר דבר לאכול כי אם בגדרים שהתירה אותם התורה ולפי שלא הותרה העלה כי אם למזבח הנה יהיה מזה אזהרה שלא יאכל אדם מבשרה באי זה מקום שיהיה כי כל מקום יקרא שעריך לזה הענין וכן נלמד מזה שלא יאכל אדם קדשים קודם זריקת הדם כי עדין לא הותרו לאדם ומזה גם כן יתבאר והוא קל וחומר שאסור לאכול קדשים חוץ למחיצתו שהוא לפנים מן הקלעים כי שאר המקומות יקראו שעריך לזה הענין והוא ידוע שהבכורים נאכלין בכל מקם לכהנים ממה שנזכר בפרשת קרח מאכילת הבכורים שלא התנה שם מקום מיוחד לאכילתם ולזה תהיה הכוונה באמרו ותרומת ידך שלא יאכל כהן בכורים בשערים קודם הנחתם בעזרה על האופן שהתבאר בפרשת והיה כי תבא:
@364 **השמר לך פן תעזוב אל הלוי.** הנה זאת אזהרה שלא לעזוב את הלוי שיתן לו חלקו הראוי לו מהמעשרות או ממעשר עני או מהשלמים וממעשר שני שנתחייבו לאכלו בירושלם:
@365 **כי ירחיב יי' אלהיך את גבולך וגומ'.** לפי שלא הותר בשר תאוה במדבר הוצרך להזכיר בזה המקום שבכניסתם לארץ יהיו מותרים בבשר תאוה:
@365 **כי תאוה נפשך לאכול בשר.** מגיד שאין ראוי לאכול בשר אלא לתאבון:
@366 **כי ירחק ממך המקום אשר יבחר יי'.** לפי שהתורה היא אחת לכל אנשי התורה כמו שנתבאר במקומות רבים מהתורה הוא מבואר שאין ראוי שיובן מזה שאשר ירחק מהם המקום יהיו מותרים בבשר תאוה לא הקרובים אל המקום אבל הכוונה בזה שלא יהיה המקום קרוב לכל ישראל מפני הרחבת גבולך ולפי שמפני הרוחק התיר זה הוא מבואר ששחיטת בשר תאוה תהיה חוץ מהמקום אך אם יזבחהו במקום יחוייב שיהיה השלמים ויאכל ממנו המזבח חלקו:
@366 **וזבחת מבקרך ומצאנך כאשר צויתיך.** רוצה לומר שבאופן שצויתיך תהיה זביחת הקדשים והוא בשחיטה כך תהיה זאת השחיטה ואולם אמר זה לפי שהזביחה תאמר גם כן על הנחירה אך גדר השחיטה הוא שתהיה בצואר בחתיכת הסמנים וכבר יתבאר לך שהזביחה תאמר גם כן על הנחירה ממה שאמר ויזבח בלק צאן ובקר וישלח לבלעם ואמר מנקרך להורות שאין ראוי שיאכל אדם בשר אם לא היה לו בקר וצאן רוצה לומ' שיהיה לו די ספוקו לקנותה ואמר מבקרך ולא בקרך שאין ראוי לאדם שיאכל כל אשר לו אך ישער ההוצאה לפי קניינו לפי שימצא לו מזונו תמיד:
@366 **ואכלת בשעריך בכל אות נפשך.** רוצה לומר שזה הנשחט חוץ לעזרה תוכל לאכול בשעריך לא מה שישחט בעזרה כי הוא קדש ומזה המקום למדנו שהנשחט יתכן שתאכל לא מה שלא נשחט:
@367 **אך כאשר יאכל את הצבי ואל האיל.** הזהירנו שלא ינהג בזה מנהג קדש כדי שלא יחשוב שהוא שוחט קדשים בחוץ ולמד בזה שצבי ואיל אינם מורים כי אם בשחיטה וכן הוא אומר כי יצוד ציד חיה או עוף אשר יאכל ושפך את דמו וכסהו בעפר וזה יהיה הרצון באמרו ושפך את דמו שחיטה ומזה המקום נלמד שמצות שחיטה נוהגת בבהמה חיה ועוף והכונה בה מה שיתכן שימותו בו בעלי חיים כף מחתיכת הסמנין וכבר שערו רז"ל שלא יתכן שישלם זה בבהמה וחיה כי אם בחתיכת שני סמנין או רובם אך בעוף ישלם בחתיכת סימן אחד להיות חסר החיות מהבהמה והחיה והוא כמו ממוצע בין הבהמה והדגי' שאינם צריכין שחיטה:
@368 **רק חזק לבלתי אכול הדם.** ביאר בזה שדמה אסור באכילה שלא יחשוב החושב שלא יהיה מוזהר רק על דם הקרבן כדי שיתנו על המזבח:
@368 **ולא תאכל הנפש עם הבשר.** רוצה לומר לא תאכל מה שהנפש בו עדין עם הבשר והוא אבר מן החי רוצה לומר כי עדין יש בנפש כח לשלח באבר ההוא הצריך לו מהמזון לא היה בב"ח:
@369 **לא תאכלנו.** הזהיר עוד על הדם כדי שיהיו יותר נזהרים מאכילתו וכבר זכרנו תועלת זאת האזהרה בפרשת צו:
@369 **על הארץ תשפכנו כמים.** למדנו מזה שאין טעון כסוי ואמ' כמי שלא יכוין בשפיכתו על הארץ לדבר מהדברים שהיו מכוונים בו המכשפים ומה שידמה להם אך יהיה לבו בשפכו אותו על הארץ כאלו שופך שם מים:
@370 **לא תאכלנו למען יטב לך.** הודיע בזה שבהיותם נזהרים מזה יגיע להם ולזרעם תועלת עצום:
@371 **רק קדשיך יהיו לך וגומ'.** צונו בזה להביא כל הקרבנות לבית הבחירה ולזה הוא מבואר שהבעלים מטפלים בהבאתם עד שיהיו שם:
@372 **ועשית עולותיך הבשר והדם.** למדנו בזה שאם אין דם לזרוק על המזבח לא זכה המזבח בבשר וכן אם אין בשר לא יזרוק הדם כי זריקת הדם הוא לרצו' הקרבת הבשר ולמדנו מזה עוד שאף עלפי שמחוייב להקטיר כל העולה למזבח שנאמר והקטיר כהן את הכל המזבחה הנה אם פרשו מהמערכה ופקעו משם הקרנים או הטלפים או העצמות או הגדים אינו זקוק להחזירם שם כי התורה לא דקדקה אלא בשר:
@372 **ודם זבחיך ישפך על מזבח ה' אלהיך ובשר תאכל.** למד על דם כל הזבחים שטעון מתנה אחת ואף על פי שנתבאר בחטאת ועולה שיש בהם יותר ממתנה אחת הנה למדנו מזה שאם לא נתן כי אם מתנה אחת לא עכב:
@372 **והבשר תאכל.** למדנו מזה שאינו זוכה באכילת בשר כי אם אחר שזכה המזבח בהם:
@373 **שמור ושמרת את כל הדברים האלה.** רוצה לומר שישמרם בלב וישמע לעשותם וזה יהיה בלמדנו אותם כי הלמידה מישרת אל המעשה וזכר שמקיום אלו המצות יגיע טוב נפשיי וגופיי לו ולבניו עד עולם כדי שיהיו יותר זריזים בענין אלו המצות. הנה זה ביאור מה שיצטרך אל ביאור בזאת הפרשה שהוגבלה ביאורה פה.
@375 **השמר לך פן תנקש אחריהם.** ר"ל פן תנקש במוקש אשר נוקשו הם וזה יהיה אם תנהג במנהגיהם בעריות ובזולת זה כמו שאמ בפרשת קדושים תהיו ולא תלכו בחקות הגוים אשר אני משלח מפניכם:
@375 **פן תדרוש לאלהיהם.** מגיד שאם ילכו במנהגיהם הפחותים סופם לעבוד ע"ז או ירצה בזה שמא תחקור איך היו עובדי' הגוי' עבודה זרה ותחשוב לעבוד הש' יתע' בדרך ההוא והזהיר שלא יעש' כן ליי' כי מה שיחשבוהו עבודה לו יהיה ההפך כי הם היו עושים לאלהיהם כל הדברים המרוחקים והמתועבים לשם יתעלה כי עד שגם בניהם ובנותיהם היו שורפים באש לאלהיהם אולם כונת התורה הוא בהפך זה שלא העמיסה עלינו דבר יכבד עלינו אבל הם דברי ישרים וצדיקים מישרים בעצמותם אל כל הטובות:
@377 **את כל הדבר אשר אנכי מצוה אתכם אותו תשמרו לעשות.** רוצה לומר על האופן אשר צויתי בו:
@377 **לא תוסיף עליו ולא תגרע ממנו.** כבר ביארנו דיני ההוספה והגרעון שהוזהרנו מהם בראש פרש' ואתחנן:
@378 **כי יקום בקרבך נביא או חולם חלום.** ידמה שקרא הנביא למי אשר יתודע אליו שם יתעלה במראה ואשר ידבר בו בחלום קרא חולם חלום:
@378 **ונתן אליך אות או מופת.** ר"ל כדי שיאמינו בדבריו ובא האות והמופת כמו שיעד אותו קודם באו ויאמר נלכה ונעבדה אלהים אחרים אשר לאי דעתם ונעדם ואל זה נתן לך האות והמופת כדי שתאמין לדבריו:
@380 **לא תשמע אל דברי הנביא ההוא או אל חולם החלום ההוא.** הזהיר בכאן שלא לשמוע אל דבריו כשיאמר לעבוד עבודה זרה גם אמר זה לפי שעה ואף על פי שהתבנא בשם השם יתעלה ויאמר שהשם יתעלה צוה לעשות כך כ"ש אם נתנבא בשם עבודה זרה:
@380 **כי מנסה ה' אלהיכם אתכם וגו'.** הרצון בזה שלזה הסכים שיבא זה המטעה לבם כמו שמצאנו בספר יהושע שהשאיר השם יתעלה קצת הגוים ההם לנסות בם את ישראל והנה האות והמופת שיעד בו הנביא שקר ההוא אינו ראיה בבאו שיהיה אמת מה שאמר כי היה זה בלתי ספק על דרך להט וכשוף ומה שידמה להם והעניין ידוע שאין דבריו אמת כי אין שם אלוה זולתי השם יתעלה כמו שנתברר לישראל במעמד הר סיני הנפלא מפי הגבורה ונתברר עוד מצד העיון במה שאין ספק באמתתו ולזה אין דרך לנתינת אות או מופת להביא להאמין ההפך בזה והוא מבואר שמי שישתדל לאהוב השם יתע' בכל לבבו ובכל נפשו ינצל מההאמנה דבריו והוא מי שישתדל להשיגו כפי כחו כי הוא ישער במה שהשיג ממנו שאין אלוה זולתו:
@381 **אחרי ה' אלהיכם תלכו.** צוה שילכו אחרי השם יתעלה ר"ל שילכו בדרכיו בחקרם איך מנהגו במה שישפע ממנו וזה יהיה סבה שייראו ממנו ויראתם ממנו תסבב שישמרו מצותיו וישמעו בקולו ויעבדוהו לא זולתו וידבקו בעבודתו:
@382 **והנביא ההוא או חולם חלום ההוא יומת.** רוצה לומ' על ידי בית די והוא הקלה שבמיתות בית דין כמו שהתבאר מהשרשים הכוללים:
@382 **ובערת הרע מקרבך.** בער העושה הרעות הגדולות לך פן תכשל ותפול ברע:
@383 **כי יסיתך אחיך בן אמך.** רוצה לומר אחיך או בן אמך שאינו אחיך מן האב והנה דבר הכתוב בהוה שלא יסית איש אחר בזאת ההסתה שיש בה מהסכנה העצומה לו אם יודעו דבריו אם לא יהיה קרבו או רעהו אשר כנפשו ולא יאמרו כמו אלו הדברים לזאת הסבה ג"כ כי אם בסתר:
@384 **הקרובים אליך או הרחוקים ממך מקצה השמים ועד קצה השמים.** הנה הקדים הקרובים כי הם היותר נכונים שיכשלו בהם ואחר כן זכר הרחוקים באי זה המקום שיהיו ממזרח שמש עד מבואו או מקצה הדרום עד קצה הצפון:
@385 **לא תאבה לו.** אפילו שהיה אהובך מצד הקרובה והאהבה כמו שזכר תחלה לא תרצה בו ובאהבתו כי בקש להדיחך ולהאבידך וזאת האזהרה שלא יסכים לדבריו:
@385 **ולא תשמע אליו.** מגיד שאם אבה ושמע חייב אף על פי שעדין לא עבד עבודה זרה וזה יהיה כשצוה לעבוד אלהים אחרים מהקרובים אליו או מהרחוקים אבל אם הסית המסית שיעבדוהו לא ינהג בו זה הדין וזה מבואר מהשרשים הכוללים ולפי שזה המאמר היה בסתר וידענו שאין האדם נדון במיתה כי אם על פי עדים למדנו מזה שיש לנסות להכמין לו עדים שיראוהו וישמעו דבריו והוא לא יראם כדי שיוכלו להעיד:
@385 **לא תחוס עינך עליו.** הותיר בזה שלא לחוס על דם המסית ולא תחמול הזהיר בזה שלא ילמדו עליו זכות:
@385 **ולא תכסה עליו.** הזהיר בזה שלא ישתוק אם ידע לו חובה:
@386 **כי הרג תהרגנו.** צוה בזה להמיתו ושהמוסת תהיה בו ידו בראשונה להמיתו ויד כל העם אחרונה ולפי שזאת ההמתה היא בסקילה למדנו שהמוסה חייב להשליך בו אבן שיהיה בו כדי להמית שנאמר להמיתו ואם לא מת ישליכו עליו כל העם אבנים באחרונה והנה כונה התורה בזה לפייס המוסת שיקח נקמתו מזה שהשתדל להאבידו עם שהוא במדרגת העם בזה והתורה אמרה יד העדים תהיה בו בראשונה להמיתו ולא יוסיפו לעשות כדבר הרע הזה בקרבך זו אזהרה למסית ולפי שאמר כדבר הרע הזה ולא אמר הדבר הרע הזה למדנו שאם הסית שיעבדוהו נהרג כיון שבא לידו מעשה שנאמר ולא יוסיפו לעשות והוא מבואר שאף על פי שלא אמר נלך ועבוד ואמר המסית אלך ואעבוד או אמר אלך ואשתחוה ומה שידמה לזה הרי הוא נסקל שנאמר כדבר הרע הזה וראוי שתדע שאם הסית יותר מאחד דינו גם כן כך אלא אם הסית רוב אנשי העיר שאז נקרא מדיח וכבר נתבאר דינו במה שנמשך לזה והנה אם הסית לשנים או יותר הרי הם עדיו וכדי שיכירו אם הוא שוגג או מזיד יראו אם יוכלו להחזירו לטוב ויאמרו לו היאך אתה אומר זה ואיך יתכן שנניח עבודת השם יתע' שהוא אלהים חיים ומלך עולם והלכנו לנוע על העצים והעל האבנים ואם לא חזר בו מביאים אותו לבית דין וסוקלין אותו:
@389 **כי תשמע באחת שעריך אשר יי' אלהיך נותן לך לשבת שם.** יצא ירושלם שלא נתנה לשבת כי לא נהגה לבית דירה אך היו ישראל עולים שם לרגל ולזה הסכימו קצת רבותינו שירושלם לא נתחלקה לשבטים כי היתה כמו משותפת לכל ישראל וכן הענין לערי המקלט כי לא נתנו לדירה אלא למקלט ולפי שאמר באחד שעריך למדנו שאין עושין בעירות רבות זו בצד זו זה הדין:
@390 **יצאו אנשים בני בליעל מקרבך וידיחו את כל יושבי עירם.** הנה התנאי שיהיו מאותו השבט שנאמר מקרבך ושיהיו מאנשי העיר ההיא שנאמ' את יושבי עירם ושיהיו שנים או יותר שנ' יצאו אנשים ולזה יחוייב שלא יהיו המדיחים נשים או קטנים שנאמר אנשים והתנאי עוד שיאמרו להם נלך ונעבוד באיזו שתהיה ממיני העבודות או נלך ונקבלה באלוה כי זה נכנס תחת גדר העבודה ולפי שנאמר וידיחו את יושבי עירם למדנו שהתנאי בזה שיודחו כל יושבי העיר או רובם והנה יתבאר מצד הוראת הגדר שמי שעמד בעיר שלשים יום יקרא מיושבי העיר:
@391 **ודרשת ושאלת וחקרת היטב.** צוה בזה להרבות בחקירות ובדרישות עם העדים ולשאול היטב כל הדברים אשר יעמידום על הבחינה אם עדותם נכון כדי לעמוד על אמתת הענין:
@391 **והנה אמת נכון הדבר.** רוצה לומ' שאחר החקירות והדרישות והבדיקות נתבאר שהענין כן הוא שנעשתה התועבה הזאת בישראל:
@392 **הכה תכה את כל יושבי העיר ההיא לפי חרב.** מפני שאמר העיר סתם הנה הוא מואר שאינה קטנה שהקטנה תקרא עיר קטנה ולא עיר גדולה כי היא תקרא עיר גדולה וביארו חכמים שלזה הענין תקרא עיר סתם ממאה ועד רובו של שבט אך רובו של שבט אין ראוי לשפוט בזה דין עיר הנדחת כי הוא כמו שבט אחד ואין ראוי שיסבבו שיפקד שבט אחד מישראל וידמה שפחות ממאה לא יתכן שיקרא עיר סתם אך הוא כפר או תקרא עיר קטנה או בת העיר אשר אצלה ואולם הגדולה יתכן שתקרא עיר סתם והנה נמנע השפטם שם בדין עיר כשיהיו רובו של שבט לסבה שאמרנו כי הוא כמו שבט אחד לפי משפטי התורה ואין ראוי להשמיד שבט אחד ולזה ידונו העובדים בסקילה וישאר הטף והנשים וראוי שתדע שזה המשפט לא יהיה ע"י סנהדרי קטנה כי כבר ביארה התורה כי לא ישפטו כי אם יחידים ע"פ סנהדרי קטנה שנאמר והבאת את האיש הוא או את האשה ההיא אל שעריך. למדנו מזה שיחידים נהרגים ע"פ ב"ד שבכל שער ושער אך המרובים אינם נהרגי' אלא על פי בית דין הגדול ולזה תעשה הדרישה והחקירה על פי בית דין הגדול. ואחד כשידעו האמת שיודחו רב יושבי העיר שולחים שם חכמים להחזירם למוטב ולהזהירם שלא יעשו כן כמו שמצינו בנביאים שהיו מוכיחים ישראל כשהיו עובדים עבודה זרה ואם חזרו בתשובה מוטב כי התורה אמר את יושבי העיר ההיא והם עתה אחרים כי כבר שבו מדרכם הרעה עם שהוא ראוי שתהיה שם התראה בהשפטם למות ואם לא חזרו בתשובה מצוים הבית דין הגדול לישראל לבא עליהם לצבא להחרים העיר בזה האופן וזה שהם מרבים שם בתי דינין לחקור מי שעבר אחר התראה בעדים באופן ראוי ואם נמצאו העובדים רובה של עיר דנין אותם כעיר הנדחת ואם לא הרי הן יחידים ונדונים העובדים בסקלה כדין עובד עבודה זרה והשאר פטורין ואם היה רובה של עיר מעלין אותה לבית דין הגדול כדי שיגמרו הדין בפניהם ואחר זה מכין העובדים וטפם ונשיהם לפי חרב שנא' חכה תכה כל יושבי העיר ההיא. וזה כולל כל נפש אדם אשר בה ומצילים הצדיקים אשר בה וטפם ונשיהם רוצה לומר אלו שלא עבדו עבודה זרה אחר ההתראה:
@392 **החרם אותם וגומ'.** למדנו מזה שכל מה שהוא מיושבי העיר ההיא מהנכנסים והמקנה אבד שנא' ואת כל שללה ואת כל בהמתה ואפילו נכסי הצדיקים שבה אבל מה שהיה בה מהאנשים שאינם מיושבי העיר או של הקדש אינו אבד שאין אני קורא בו בהמתה ושללה ומזה המקום נלמד שנכסי הרשעים שבהם שהיו חוצה לה אינו מחוייב שישרף לפי שאינו שלל העיר ההיא ואינו בה והתורה אמרה ואת כל אשר בה אך אם נקבצו שם הרי הם נשרפים שהרי הם שללה ולמדנו מזה גם כן שאין מאבדין מהקנינים בשרפה אלא דבר שיתכן שיקרא שללה והוא דבר המטלטל שאינו חסר אלא קבוץ ושרפה ולזה יתבאר שהפירות המחוברי' לקרקע אינם נשרפי' כי הם חסרין תלישה וקבוץ ושרפה וכן הענין במה שידמה לזה:
@393 **ואת כל שללה.** לפי שראוי לבער הרע מקרבנו כשהיה בזה האופן המגונה בתכלית הנה ראוי שלא נשפוט שיהיה אמרו אל תוך רחובה תנאי שאם לא היה לה רחוב לא נשפוט אותה כעיר הנדחת ועוד שהרי אמרה תורה ושרפת באש את העיר ואת כל שללה מכל מקום ולזה הוא מבואר שכונת התורה בקבוץ שללה לתוך רחובה להוסיף פרסום בענין כדי שיוסרו הנשארי' ולזה הוא מבואר שאם לא היה לה רחוב עושין לה רחוב והרי אני קורא בה רחובה ואם יש לה רחוב חוצה לה עושין בדרך שיהיה רחובה רוצה לומר שיבנו בה חומה סביב העיר באופן שיהיה הרחוב תוך החומה ואז יקרא רחובה ויקבצו שם את כל שלל העיר:
@393 **ושרפת באש את העיר ואת כל שללה כליל ליי' אלהיך.** זהו מצות עשה ואמר שזה הפעל ראוי שיעשה ליי'. רוצה לומר שיכון בעשייתו נתינת האלהות לשם יתעלה במה שיחרים ויאבד עובדי עבודה זרה וכל אשר בה והיתה תל לעולם לא תבנה עוד למדנו מזה שאסור לבנות עיר הנדחת לעולם ולפי שלא הזהיר אלא שלא תבנה למדנו מזה שעושה אותה שדות וכרמים גנות ופרדסים:
@394 **ולא ידבק בידך מאומה מן החרם.** הזהיר בזה שלא ליהנות מממון עיר הנדחת ולפי שעבודה זרה ומשמשיה ותקרובת עבודה זרה הכל נקרא חרם כמו שאמר בפרשת ואתחנן למדנו מזה שהנהנה מעבודה זרה ומכל מה שיעשה בשבילה עובר משום לא ידבק בידך מאומה מן החרם:
@394 **למען ישוב יי' מחרון אפו וגומר.** ביאר בזה שהעושה זה הדין בעיר הנדחת משיב חרון אף יי' מישראל ומביא עליהם רחמים זהו דין עיר הנדחת ואולם מדיחיה יתבאר שדם בסקילה ממה שנאמר במסית ולא יוסיפו לעשות כדבר הרע הזה כי זהו דומה לדבר הו' ויש בו מעשה שהרי הודחו יושבי עירם בסבתם ועבדו עבודה זרה לא היו שם מדיחים או שלא היה שם אלא מדיח אחד או שהיו המדיחים מעיר אחרת או משבט אחר או שהיו המדיחים קטנים או נשי' או שהיתה העיר עיר מקלט או עיר שאינה לדירה ולשבת שם או שהיתה כפר קטן או שהיה בה רובה של שבט או שלא הודחה רובה של עיר הרי כל העובדים נדונים כיחידים בסקילה וממונם ליורשיהם וכבר אמרו רבותינו שאין עושין עיר הנדחת סמוכה לספר כי היא היתה משמרת לשאר ערי ישראל שלא יבואו גוים ויחריבו את ארץ ישראל והנה יתבאר זה לפי מה שאחשוב מצד מה שדקדקה התורה שלא יוזקו בה רק יושבי העיר היא ובהמתה ושללה ואולם בעיר הסמוכה לספר יוזקו שאר העיירות:
@396 **בנים אתם ליי' אלהיכם.** ולזה הוא משגיח בכם כהשגחת האב על הבנים:
@396 **לא תתגודדו.** הוא מענין חתיכה כטעם גודו אילנה והכונה בזה שכומרי עבודה זרה היו נוהגים לחבול בעצמם שהיו חותכים בשרם עד שפוך דם עליהם והנה ההתגודדות לא יהיה אלא בכלי חותך הבשר ומזה הזהירה התורה בזה המקום וזה מבואר מצד הסמיכות וכאלו אמר שהשם יתעלה אוהב אתכם ולזה לא יעמיס עליכם דבר יקשה עליכם אבל ישתדל לשמור אתכם מזה ולזה הזהיר אתכם מההתגודדות שלא תחבלו בעצמכם וכבר מצאנו יתגודדו מענין אגדות וחבורות אמר ובית זונה יתגודדו. וכבר הבינוהו קצת מרבותינו מזאת הכונה השנית והוציאוהו מזה הזהירה התורה בזה המקום וזה מבואר מצד הסמיכות וכאלו אמר שהשם יתעל אוהב אתכם ולזה לא יעמיס עליכם דבר יקשה עליכם אבל ישתדל לשמור אתכם מזה ולזה הזהיר אתכם מההתגודדות שלא תחבלו בעצמכם וכבר מצאנו יתגודדו מענין אגדות וחבורות אמר ובית זונה יתגודדו. וכבר הבינוהו קצת מרבותינו מזאת הכונה השנית והוציאוהו מזה האזהרה שלא יהו שתי בי דינין יושבים בעיר אחת וינהג זה וחבורתו מנהג אחד והאחר וחבורתו מנהג אחר והנה הנכון לפי הפשט הוא מה שביארנו:
@396 **ולא תשימו קרחה בין עיניכם למת.** רוצה לומר על הראש שיסיר השער משם כדרך שתהיה שם קרחה על המוח ולמדנו שחייב על שאר הראש כבין העינים ממה שאמר לא יקרחה קרחה בראשם והנה שימת הקרחה תהיה אם שימרוט השער בידו או שישים על הראש דבר יסבב שתהיה שם קרחה. והנה ידמה שכן היה דרך עובדי עבודה זרה לעשות זה על מתיהם ולזה הוצרכה התורה להזהיר על זה ואולם שיעור הקרחה יתבאר מדיני הצרעת כי שם נאמר קרחת וכבר נתבאר שעורו שם והוא מבואר שמריטות שתי שערות לא יקרא קרחה:
@398 **לא תאכל כל תועבה.** ידמה שאין הכונה בזה בענין עבודה זרה אשר נקרא תועבה שהרי מנע ממנו כל הקנאה בכללות שנאמר ולא תביא תועבה אל ביתך ואין הכונה בו גם כן קדשים בעלי מם שנקראו תועבה בפרשת שופטים אמר לא תזבח ליי' אלהיך שור ושה אשר יהיה בו מום וגומר. כי תועבה הוא. וזה שכבר נתבאר במה שקדם שהיו נפדין ונאכלין במומן ולזה אמרו רבותינו שהו מפסולי המוקדשין שהטילו בהם מום וקנס הוא שקנסה אוו התורה מפני שבזה הקדשים כדי שיאכלם שלא יותר לפדותן וימותו במומן ואפשר שיהיה הרצון באמרו כל תועבה לא תאכל כל שקץ כי השקץ והתעוב אחים אמר שקץ תשקצנו ותעב תתעבנו כי חרם הוא והנה הזהיר בזה אכילת הבעלי חיים שאמר בהם כי שקץ הם בפרשת ויהי ביום השמיני והם הדגים והעופות שאין להם סימני טהרה. וכל שרץ העוף ההולך על ארבע. וכל השרץ השורץ על הארץ. וזה נאות מאד מצד הלשון ומצד מה שנמשך אליו כאלו יאמר כי מצד אהבת השם יתעלה את ישראל והיותם בנים לו הזהירם מלאכל המאכלים המשוקצים והמתועבים שהם מזיקים לבריאות האדם ולהכנת שכלו כמו שביארנו בפרשת שמיני:
@399 **זאת הבהמה אשר תאכלו.** התבאר מזה שחיה היא בכלל אכילת בהמה והקדים לזכור מיני הבהמה להיות יותר נכבדים והנה זכר בסדור כי היותר נכבד הקדים השור שיותר נכבד מהכבש והכבש יותר נכבד מהעז:
@401 **כל בהמה מפרסת פרסה.** זכר שסימני טהרה הם בבהמה וחיה שתהיה הבהמה מפרסת פרסה ושוסעת שסע שתי פרסות לא שתהיה לה פרסה עגולה:
@401 **ומעלת גרה בבהמה.** רוצה לומר כי בבהמה עצמה הנזכרת שהיא מפרסת פרסה ושוסעת שסע יצטרך עוד סימן אחר והוא שתהיה מעלת גרה וכשיתקבצו אלו הסימנין אותה תאכלו לא זולתה ואף על פי שהיא מעלת גרה או היא מפרסת פרסה שסועה כיון שלא נתקבצו בה אלו הסמנין כמו הגמל והארנבת והשפן והחזיר וקל וחומר לשאר בהמה טמאה שאין בה שום סימן טהרה:
@406 **כל צפור טהורה תאכלו.** רוצה לומר שכל עוף טהור תאכלו ולא פרט מיניו לרבויים וכבר נתבאר מזה שצפור המצורע אשר שולחה על פני השדה אשר היא טהורה כמו שאמ' שני צפורין חיות טהורות היא מותרת באכילה וכבר ביארנו סימני טהרה בפרשת ויהי ביום השמיני והנה הוסיף בעופות הטמאים בזה המקום הדיה ואמרו רבותינו שכבר נכלל זה גם כן במה שנזכר בפרשת שמיני ושם נתבאר שהוא ההולך על ארבע רגלים:
@415 **כל עוף טהור תאכלו.** ידמה שרמז בזה אל המינים משרץ העוף ההולך על ארבע והוא אשר לו כרעים ממעל לרגליו לנתר בהם והם הארבה והסלעם והחרגול והחגב למיניהם והנה בזה הסדור נזכר זה גם כן בפרשת שמיני:
@416 **לא תאכלו כל נבלה.** היא הבהמה שמתה:
@416 **לגר אשר בשעריך תתננה ואכלה.** הנה גר שער הוא הגר שקבל עליו שלא לעבוד עבודה זרה כי העובד עבודה זרה לא ישב בארצנו כאמרו בפרשת ואלה המשפטים לא ישבו בארצך פן יחטיאו אותך לי. והתורה צותה במקומות רבים לאהוב את הגר ולזה הקדים היותה לגר בנתינתה למכירתה לנכרי והנה לא רצה השם יתעלה שתתן אותה לנכרי לפי שהוא עובד עבודה זרה ולזה לא רצתה שננה אותו מתנת חנם:
@416 **כי עם קדוש אתה לה'.** ולזה ראוי שתקדש עצמך בעניני המאכלים ולא תתגאל במאכלים העם והמגונים:
@416 **לא תבשל גדי בחלב אמו.** כבר ביארנו עניין זאת האזהרה והתועלת המגיע ממנה בפרשת ואל המשפטים ושם ביארנו מה שהגיע מהתועלת מפני ההכפל זאת המצוה בשלשה מקומות מהתורה זהו ביאור מה שנצטרך אל ביאור במה שהגבלנו לבאר פה מזאת הפרשה.
@417 **עשר תעשר אל כל תבואת זרעך.** ידענו שאין הכונה במעשר הנזכר בזה המקום מעשר ראשון שהיה נתן ללוים כי הוא נאכל בכל מקום כמו שנזכר בפרשת קרח וזה המעשר הנזכר בזה המקו' לא היה נאכל כי אם במקום אשר יבחר ה' כמו שזכרנו בזה המקום ולזה הוא מבואר שזה המעשר הוא מעשר שני והוא שהיו מפרישים הבעלים לאכלו במקום אשר יבחר ה' והוא המעשר הנזכר בסוף פרשת אם בחקותי והנה אמר פה את כל תבואת זרעך ובפרשת אם בחקותי אמר וכל מעשר הארץ מזרע הארץ מפרי העץ למדנו מזה שזה המעשר נוהג בזרעים ובפירות האילן והוא מבואר שאינו נוהג אלא בנאכל מהם שנאמר ואכלת לפני ה' אלהיך ואינו נוהג גם כן מן התורה אלא בדבר המתקיים כי לא יתכן בדבר הבלתי מתקיים כמו הירקות שישאנו שם לאכלו והוא מבואר עוד שאינו מחוייב הפרישו עד שתגמר מלאכתו שנאמר ואכלת שאינו מחסור אלא אכילה ועוד שהרי אמרה בזה המעשר מעשר דגנך תירושך ויצהריך שהם דברים שנגמרה מלאכתם לאכילה ולפי שחייבה התורה לעשות את כל תבואת הזרע למדנו שהגיע לחיוב מעשר אסור לו לאכול מהזרעי' והפירות' עד שיעשר:
@417 **כל תבואת זרעך היוצא השדה שנה שנה.** ר"ל כל מה שתכניס מזרעך שיצא מהשדה לזה הוא מבואר שיש לו לזרוע ממנו בשדה קודם שיעשר ואינו מעשר אלא מה שמכניס לביתו ולזה לא ינהג המעשר בלקט שכחה ופאה והדומה להם ולא ראשון שאן אני קורא בו תבואת זרעך אלא אחר שהפריש ממנו חלק הכהנים והלוים וראוי שתדע שאין ראוי שנבין מזה שאם לא היה הזריעה שלו בהיותו בשדה וזה יהיה כשלקחו מאר ונגמרה מלאכתו ביד הלוקח שיהיה פטור מן המעשר וזה שהרי הזרע הוא שלו כיון שקנאו והתורה לא אמר היוצא משדך ועוד שהרי בפרשת בחקותי לא אמר זרעך אבל אמ' מזרע האר מפרי עץ ולא התנה שתהיה הארץ שלו ולא האילן:
@417 **היוצא השדה שנה שנה.** למדנו שבכל שנה חייב לעשר ואינו מעשר מפירות שנה זו על פירות שנה אחרת ומזה המקום התבאר שכן הענין במעשר ראשון כי המעשר שני בא אחריו כמו שביארנו וכן למדנו מזה שאינו מעשר ממין על שאינו מינו כי לא יאמר עשור כי אם בלקיחת החלק העשירי מהדבר ההוא וכן יתבאר מזה שלא יעשר מן התלוש על המחובר או הפך כי אין זה עשור וכן יתבאר שהעשור לא יהיה באומר כי אם במדידה וזה כולו מבואר ולפי שמעשר בהמה היה דינו כדין המעשר שני ולזה סמכו למעשר שני בפרשת בחקותי ואמר בכל אחת מהם שהוא קדש לה' למדנו מזה גם כן שאין מעשרים בה משנה לחברתה ולא צוו להפריש מעשר בהמה כי אם מבקר וצאן לפי שכונת התורה היתה שיעשו ממנה שלים לה לא יופרש כי אם מהמינים הראוי לשלמים ולזה גם כן תמצא במעשר שני שהוא אפשר שיעשו ממנו שלמים כשהיה אפשר זה כמו שיתבאר אחר זה בג"ה:
@418 **ואכלת לפני ה' אלהיך.** מגיד שאין אוכלו שם אלא בשעה שבית הבחירה קיים והעבודה שם כי אז הוא לפני ה' לא בשעה שנחרב הבית ואין העבודה שם:
@418 **מעשר דגנך תירושך ויצהרך.** מגיד שאין מפרישין מעשר שני אלא מדבר שנגמרה מלאכתו לאכילה:
@418 **ובכורות בקרך וצאנך.** זה ממה שירה עוד שאין זה הענין אלא בפני הבית כי הבכור אינו נאכל כי אם בפני הבית דמו ואמוריו הם למזבח כמו שנתבאר בפרשת קרח:
@418 **למען תלמד ליראה את ה' אלהיך כל הימים.** מגיד שתועלת זאת המצוה הוא שילמד האדם בה ליראה את השם יתעלה וזה כי מפני שלא היה נאכל אלא במקום שיבחר השם יתעלה אשר שם ימצאו החכמים שיורו משפטי ה' ליעקב ותורתו לישראל והם הכהנים והלוים המשרתים לפני ה' הנה ימשך להם זה התועלת מפני אם למקום ההוא הנבחר אכול שם זה המעשר עם שענין המעשר בעצמו מישיר אותם ליראת השם יתעלה בהשיגם זה הנמצא העשירי שהוא בעל כל שאר הנמצאות והנה לא יכבד עליהם באם שם ועמדם שם בשלשה רגלים אשר צותה התורה שיבאו שם לפי שיש להם מן המזון מה שלא יותר להם לאכלו אלא במקום בית הבחירה ושם גם כן ירגילו עצמם מפני זה ליראה את השם יתעלה מצד אחד כי כבר ימצא שם מי שיש לו שעור רב מזה המעשר ולא יוכל להתעכב שם עד שיאכלוהו הוא וביתו ולזה ימהר לתת ממנו ללוים ולשאר הצריכים וזה ממה שירגילו לו ויקנה מנהג בעשיית הצדקה ואמר כל הימים להעיר על נצחיות אלו המצות כל זמן שיהיה שם מקום הבחירה ותהיה העבודה שם:
@419 **וכי ירבה ממך הדרך כי לא תוכל שאתו.** מגיד שהוא יכול לפדותו אם מפני רבוי הדרך אם מפני הקושי שיש בנשיאתו אל המקום אשר יבחר ה':
@419 **כי ירחק ממך המקום.** ביאר שזה הקושי יהיה מפני רוחק המקום הנבחר:
@420 **ונתת בכסף.** כבר אמר בפרשת בחקותי שזה הפדיון יהיה אם גאול יגאל איש ממעשרו שיוסיף חמישיתו עליו והנה התבאר שזה הכסף ראוי שיהיה ראוי לקנות בו בקר וצאן ויין ושכר וכל אשר תשאל נפשו וזה לא ישלם כי אם במטבע לא בחתיכת כסף כי לא יוכלו להשתמש בו לקנות מה שירצו כמו הענין במטבע ולפי שאלו הענינים שזכר הם הסבה כשיוכל לחל קדושת המעשר שני על הכסף למדנו מזה שאם נכנס המעשר שני בירושלם אינו יכול לפדותו:
@420 **וצרת הכסף בידך.** למדה התורה שישתדל שלא יאבד כדי שתשלם כונת התורה בזה המעשר:
@421 **בבקר ובצאן.** אמר זה לעשות מהם שלמים שנאמר ושמחת אתה וביתך אך עולות לא יתכן שיעשה מהם כי התורה צותה שיאכלנו במקום בית הבחירה והגיד בזה שאין חשש אף על פי שיאכל מנו המזבח קצת וישארו בידו עורות כי אינם נאכלים ולא יתכן לחללם על כסף כי התורה לא תקנה הפדיון הזה אלאל במעשר שני בעצמו כשלא הגיע למקום הבחירה והיה זה כן לפי שקניית הבקר והצאן הם לכונת האכילה לא לעורות וזה למדנו מזה באמרו ביין ובשכר לא תקפיד התורה אם יקנה היין עם הקנקים:
@421 **ובכל אשר תשאלך נפשך.** לפי שמעשר שני היה מזרע האץ ומפרי עץ והיה הפרט הנזכר בזה המקום דבר שהוא נאכל והוא מגדולי קרקע או ב"ח טהורים למדנו מזה שאין ראוי שיתן הכסף כי אם בדבר שיש בו תועלת לאכילה או לשתייה. והוא עם זה בשר או גדולי קרקע:
@421 **ושמחת אתה וביתך.** מגיד שכבר יתכן לעשות לו מזה השלמי' והם הנקראים שלמי שמחה:
@422 **והלוי אשר בשעריך לא תעזבנו.** כבר ביארנו זאת המצוה במה שקדם מזאת הפרשה:
@423 **מקצה שלש שנים תוציא את כל מעשר תבואתך וגו'.** מגיד שכאשר הפריש מעשר שני שתי שנים שחוייב לאכלו במקום בית הבחירה כמו שקדם הנה שנה השלישית לא יהיה הענין כן רוצה לומר שלא יחוייב להביאו למקום בית הבחירה לאכלו שם אך יניחהו בשעריו רוצה לומר באוצר במקומו ויעשה בו כמו שזכר בסמוך ואמר את כל מעשר להורות שהוא ממתין אל העת שכלו בו המעשרות והוא חג הפסח כי אז נגיעו בכללם התבואות והפירות:
@424 **ובא הלוי כי אין לו חלק ונחלה עמך.** מגיד שאם לא היה לו חלק עמך תן לו מזה המעשר ולמדנו מזה שזה המעשר הוא נתן לעניים וזה יתבאר גם כן מפני שצוה לתת ממנו לגר מפני שסתמו שהוא עני כמו שאמר במתנות עניים לעני ולגר תעזוב אותם ואמר עוד בזה המקום שינתן ליתו' ולאלמנה לפי שסתמן להיות עניים כי אין סומך ידם. וראוי שתדע שהגר הנז' בזה המקום הוא גר צדק ויעיד על זה שכבר סמך אותו ללוי שהוא בן ברית וכן הענין ביתום ואלמנה והענין בעצמו יחייב זה כי כמו אלו המתנות צותה התורה המקומות שינתנו לעניים ולא אמר בנבלה לגר אשר בשעריך תתננה ואכלה אלא מפני שאיננה ראויה לעניי ישראל:
@424 **ואכלו ושבעו.** למדנו מזה שראו שתהיה נתיניה לכל אחד מהם כדי שבעו:
@424 **למען יברכך ה' אלהיך.** ביאר כי בשכר מה שיתן לעניי' מזה יברכהו הש' יתעלה בכל מעשה ידיו כי הוא חנן אותו כדי שיחון העניים כמו שאמר כי בגלל הדבר הזה יברכך ה' אלהיך:
@425 **מקץ שבע שנים תעשה שמטה.** אחר שהזכיר שבשנה השלישית ובשנה השישית משמטה יפריש מעשר עני ביאר בזה המקום מה שיעזוב לעני בשנה השביעית שהוא שנת השמטה והנה הרצון בשמטה שישמט האד' ידיו מפירותיו אשר בנחלתו ויהיו הפקר כמו שביארנו בפר' ואלה המשפטים וכבר ביארנו בזה המקום גם כן שמה שהלוה אדם לחברו מהכסף והפירות ישמט ידו ממנו בזאת השנה שהיה שנת השמטה ולזה אמר שמוט כל בעל משה ידו והוא מבואר שלוה הוא עני ולזה הוצרך ללות:
@426 **לא יגוש את רעהו.** למדנו מזה שאם היה נגוש ועומד קודם השמטה אין השמטה משמטת אותו אך אם לא היה כן הוא מוזהר שלא לתבוע בב"ד החוב שעבר' עליו שביעית והוא מבואר שלא הוצרך להזהירו שלא ינגשהו בשנת השמטה:
@427 **את הנכרי תגוש.** זו מצות עשה כדי שלא נתן מתנות חנם לעובדי עבודה זרה:
@427 **ואשר יהיה לך את אחיך תשמט ידך.** זו היא מצות עשה רוצה לומר שיפקיר החוב ההוא ויסלק ידו ממנו ולזה הוא מבואר שכבר זכה בו הלוה. אולם החוב שיהיה לו אצל הגר תושב אינו מחוייב לנוגשו ולא לעזבו:
@428 **אפס כי לא יהיה בך אביון.** הבטיחם שלא יהיה בך אביון אם ישמרו מצות השם יתעלה ולא יצטרך אחד מכם ללות מחברו או מגוי כמו שאמר והעבטת גוים רבים ואתה לא תעבוט וראוי שתדע כי כבר יתבאר מאמרו מקץ שבע שני' תעשה שמטה וזה דבר השמטה כי השמטת כספים נוהגת בין בארץ בין בחוצה לארץ בין בפני הבית בין שלא בפניו שאם לא היה הדבר כן לא היה צריך לומר תעשה שמטה וזה דבר השמטה אך הי אומר מקץ שבע שנים בשנת השמטה שהיה משמט בה קרקע כמו שנתבאר בפרשת ואלה המשפטים. ואמנם אמר תעשה שמטה שאף על פי שאינה שמטה מדרך אחרת תעשהו שמטה לזה הענין:
@431 **כי יהיה בך אביון מאחד אחיך.** ידענו שהתורה צותה בכללות לחון העניים מישראל איך זה שיהיו אך זכר אלו התנאים להודיע אי זה עני הוא וקדם ולזה אמר מאחד אחיך שהם קרובים כי הם קודמים לשאר עניים שאינם ממשפחתו:
@431 **באחד שעריך.** רוצה לומר שיהיה האביון באחד שעריך אף על פי שלא יהיה קרובך כיון שהוא מעירך והוא קודם לשאר העניים שהם מעיר אחרת או ירצה באמרו באחד שעריך שהוא מאחד מערי שבטיך כי עניי שבטו קודמין לשאר העניים:
@431 **בארצך.** רוצה לומר שיהיה האביון בארצך והוא קודם לעניי חוצה לארץ ולזה אמר גם כן בסוף הפרשה זאת ההדרגה בעינה והוא באמרו לאחיך לענייך ולאביונך בארצך ביאר שאחיו אם הוא עני קודם לעניי עירו ועניי עירו קודמין לענני עיר אחר' מארץ ישראל ועניי ארץ ישראל קודמים לעניי חוצה לארץ:
@431 **לא תאמץ את לבבך.** רוצה לומר להמנע מלרחם עליו:
@431 **ולא תקפוץ את ידך.** אך תפתחה לקחת בה דבר לתת לו:
@432 **פתוח תפתח את ידך לו.** רוצה לומר לתת לו על דרך החמלה והצדקה:
@432 **והעבט תעביטנו.** מגיד שאם יש לו משכון תלוהו על המשכון ותנהג במשכון לפי מה שחייבה התורה במשכון העני לפי מה שנזכר בפרשת ואלה המשפטים:
@432 **די מחסורו אשר יחסר לו.** למדנו שמחסורו הוא עליך. אף על פי שאין לו משכון ואמנם זכר המשכון להודיע שההלואה קודמת למתנה עם שלא יושג בה בשת לעני והנה לא זכר בכאן שיתן לעני בקש די מחסרו להודיע שאף על פי שלא ישאל חייב אתה לפרנסו ואין ראוי שנדמה שכל אחד מהאנשים אשר בעיר יחוייב לתת לו די מחסורו או שיהיה החיוב על הראשון שיבוא אליו העני אבל ראוי שבין בני העיר ישלם זה לעני ולזה הוא מבואר כי צריך שיהיה בעיר ממונה על הצדקה או ממונים והנה אמרו די מחסורו אשר יחסר לו כולל כל מה שיחסר לו ממזון וכסות ואפילו עבד לשמשו ואפילו סוס לרכוב עליו ואמר אשר יחסר לו להעיר שלפי מנהגו וענינו יותן לו המצטרך אליו שאם היה רגיל בפת חטים לא נאכילהו שעורים ואם היה לבוש בגדים חדשים לא נלבישהו שחוקות:
@433 **השמר לך פן יהיה דבר עם לבבך בליעל.** הזהיר בכאן שלא ימנע מלהלוות לעני מפני ראותו שקרבה שנת השמטה ויזכה אז העני במלוה ההוא:
@433 **וקרא עליך אל ה'.** ר"ל שהעני יצעק אל השם יתע' והוא ישמע צעקתו כמו שאמר ביתום ואלמנה כי אם צעוק יצעק אלי ושמעתי כי חנון אני ויהיה הכונה באמרו והיה בך חטא והיה בך עונש כי חטא ועון יאמרו לפעמים על עונש או קצר הכתוב בזה ואמר והיה בך חטא להודיע שאיך שיהיה הנה יהיה בך חטא מפני שלא נתת לאביון ההו' המצטרך לו ואף על פי שלא יקרא עליך אל ה':
@434 **נתון תתן לו.** זו היא מצו' עשה:
@435 **כי לא יחדל אביון מקרב הארץ.** יאמר זה להודיע שגלגל הוא שחוזר בעולם ואם הוא נותן עתה לעני לזמן אחר יעשיר העני ויתן לו או לאחד מזרעו ואולם מה שאמר למעלה אפס כי לא יהיה בך אביון אינו יעוד שלא יהיה בו אביון אך הודיע שאם ישמרו כלם דרכי השם יתעלה ומצותיו לא יהיה בהם אביון וזה שאף על פי שהו' אמת הנה הוא רחוק שיקרה זה שיהיו העם כלם צדיקי' בזה האופן ולזה אמר על דרך היעוד הנבואיי כי לא יחדל אביה מקרב הארץ:
@436 **כי ימכר לך אחיך העברי או העבריה ועבדך שש שנים.** בעבור שזכר עתה דבר השמטת הכספים שהוא בשנת השמטה לכספים ואף על פי שאינה שמטה לקרקע בא לזכור עתה דבר החירות אשר יהיה בשנה השביעית במכירתו לעבד עברי ולפי שזכר דבר עבד עברי זכר עמו דבר אמה העבריה להדמות אשר ביניהם בענין הענקה אשר נתחדש דינם בזה המקום ואמר כי ימכר לך אחיך העברי להעיר על הנמכר בגנבתו שימכרוהו בית דין וכבר נתבאר דינו בשלמות בפרשת ואלה המשפטים היא אשר ימכור אותה אביה לאמה בעודה קטנה כאמרו וכי ימכור איש את בתו לאמה:
@436 **ועבדך שש שנים.** שב לעבד עברי כי האמה העבריה לא תמכר ליותר מהזמן שהיא ברשות אביה כמו שביארנו שם ולזה יתכן שיהיה זה הזמן פחות משש שנים או יותר:
@437 **לא תשלחנו ריקם.** הוא מצות לא תעשה:
@438 **הענק תעניק לו מצאנך ומגרנך ומיקבך.** מפני שאמ' לא תשלחנו למדנו שכיון שלא ישלחהו ריקם יצא ואולם הודיע בזה המקום כי לפי עושר בעל הבית יהיה שעור זאת ההענקה:
@439 **וזכרת כי עבד היית במצרי ויפדך ה' אלהיך.** הנה כמו שהוציאך אז השם יתעלה חפשי והעניק אותך שם במה שנשאתם ממצרים כלי כסף וכלי זהב ושמלות כן אנכי מצוך להוציא העבד עברי חפשי אחר שש שנים ולהעניק לו מאשר ברכך ה' אלהיך:
@440 **והיה כי יאמר אליך.** כבר ביארנו דין זאת הרציעה ותנאיה בפרשת משפטים:
@441 **ואף לאמתך תעשה כן.** רוצה לומר בדבר ההענקה:
@442 **כי משנה שכר שכיר עבדך שש שנים.** אמר זה לפי שהוא עובד ביום ובלילה ולזה היה הרשות ביד רבו למסור לו שפחה כנענית ואפשר שיהיה הרצון בזה כי ימי השכיר הם ג' שנים כאמר' שלש שני כימי שכיר ולזה יהיה זה שעבד ו' שנים עובד משנה שכר שכיר:
@442 **וברכך ה' אלהיך בכל אשר תעשה.** אמר זה שלא יחשוב שום אדם שהש' יתע' יברכהו והוא יושב ובטל ולא ישתדל בהבאת הברכה לו ולזה אמר בכל אשר תעשה כי השם יתעלה יעשה מה שיעשה בסיבות היותר נאותות כשהיה אפשר בה כמו שזכרנו במקומות רבים מזה הספר:
@443 **כל הבכור אשר יולד.** לפי שצריך להיות פטר רחם אמר יולד כי הלידה הוא דרך הרחם:
@443 **הזכר תקדיש להשם אלהיך.** לפי שכבר נאמר בפרש' בחוקותי אך בכור אשר יבוכר להש' בבהמה לא יקדיש איש ואתו למדנו מזה הענין ההקדשה הזאת אשר חייב בה בזה המקום לבכור הוא זולת ענין ההקדשה אשר הזהיר עליו שם ולזה יהיה ענין ההקדשה הזאת שיאמר בכור זה לה' כדי להוסיף שמירתה שלא ינהגו בו מנהג חולים כי כבר הזהיר עליו שלא לעבוד בו ושלא לגזזו וזאת המצו' תהיה לבעלים בהולדו ברששותם וידמה שהם מטפלים בו זמן מה לגדלו ולהניקו מעט כדי שיהיה ראוי שיתנוהו לכהן כמו שמצאנו בתרומה שלא נתנה לכהן אלא אחר גמר מלאכתה ולזה אחיה אזהרת אמרו ולא תעבוד בבכור שורך לבעלים גם כן כמו שהוא לכהן ולזה אמר שורך צאנך ולזה ביאר בזה המקום שהבכור בין תם ובין בעל מום אסור בגזה ובעבודה שנאמר כל הבכור אשר יולד וגו':
@443 **לא תעבוד בבכור שורך ולא תגוז בכור צאנך.** ואף על פי שנולד במומו לפי שקדושתו מרחם והנה הודיע הכתוב זה הדין בבכור והוא הדין לשאר קדשם ואמנם ביארה התורה זה בקדשים קלים ושתקה מהשאר כי הדברים קל וחומר ובכלל האזהרה הזאת רחל ועז להלכה הנה ביארה התורה שאסור ליהנות בקדשים בזולת האופן אשר הגבילה התורה לזה אמר עבודה בבכור שור וגזה בבכר צאן אלא שדברה התורה בהוה והנה שעור הגזה הוא החלק הראשון מהצמר שיהיה ראוי לדבר כי הגזה היא מלאכה יכוין בה תכלית מן התכליות ואיננה באופן שיגזזו שער אחר שער שנוכל לומר שאם גזזו שתי שערות יהיה חייב:
@444 **לפני ה' אלהיך תאכלנו שנה בשנה.** מגיד שאינו נאכל אלא במקום הבחירה והוא נאכל כל שנתו ואמנם אחר זה לא הסכימה התורה לגדלו עוד שמא יגדלנו הכהן ממנו עדרים ויבא הענין לדבר תקלה מצד הגזה והעבודה ומה שידמ' להם והנה מה שאמ' לפני ה' אלהיך תאכלנו אינו מדבר אלא בתם ולפי שאמר לפני ה' אלהי תאכלנו נמשך למה שאמ כל בכור אשר יולד בבקרך. ובצאנך למדנו שהכהן גם כן יחוייב להפריש בכורות והיה זה כן לפי שקדושתו מרחם ובכלל הה ביארה התורה הפטר מכהנים והלוים מבכור אדם שאינו אלא קדושת דמים ושתקה מהבכור וזה יחוייב שיהיה הכהנים והלוים חייבים בבכור בהמה:
@445 **וכי יהיה בו מום פסח או עור כל מום רע לא תזבחנו לה'.** ידענו שאם היה בו מום אי זה שיהיה לא יתכן לזבחו לה' כמו שנתבאר בפרשת אמור אל הכהנים ואולם אמר בזה המקום פסח או עור כל מום רע לפי שבזולת זה לא יתכן שיאכלנו בשעריו. רוצה לומר אם לא היה בו מום קבוע ואמ' לא תשבחנו לה' לבאר שלא הוסרו ממנו מן הקדושה רק שלא יזבחנו ליי' ושהוא אפשר לאכלו בשעריו אך הוא עובד בסוף שנתו שלא הותר לו לזבחו לה' ולא לאכלו בשעריו הנה יוכל להמתין עד העת שהוא ראוי שיהיה עובר בו אם היה עובר והוא שלישי' יום מעת נפילת המום כי שערו חכמים דבר הבחינה הזאת ואולם תוך שנתו אם נפל בו מום עובר יש לו להמתין יותר משלשים יום תוך שנתו כדי להבחין אם נקבע מומו אם לא:
@446 **בשעריך תאכלנו הטמא והטהור יחדו.** מגיד כי כשנשחט במומו יוכל לאכלו בשעריו ויותר לטמא ולטהור לאכול ממנו בקערה אחת וכבר ביארנו בפרש' בא אל פרעה שבכור בהמה טהורה אינו נוהג אלא באדם לזה לא תנהג הזביחה לה' בבכור בהמה טהורה כי אם בבכורות הבאים מארץ ישראל לא בבכורות הבאים מחוצה לארץ ולפי שמצאנו בבכור שהוא ממון כהן ולא זכה בו מן המזבח שהרי הוא אוכלו במומו בלא פדיון למדנו מזה שבכורות חוצה לארץ הם לכהן כי אין תלוי ענינם בארץ כי אם לזבוח ולזה יהיו נאכלים במומן ולזאת הסבה יתבאר שהבכורות נוהגין בין באץ בין בחוצה לארץ בין בפני הבית בין שלא בפני הבית וכבר יתבאר שהכהן יזכה בבכור בהמה בכל מקום וכל זמן שהרי מצאנו בפטר חמור ובבכור אדם שנוהג בכל מקו' ובכל זמן ולפי שאין זוכה בבכור בהמה טהורה מן המזבח למדנו שדינו כדין שאר הבכורות אלא שלא יזבחו ממנו להשם כי אם כשהיה בארץ ובפני הבית לזה אמר והיה כי יביאך בבכורות בפרשת בא אל פרעה והנה אמר בפרשת כל פטר רחם לכל בשר הנה כלל שלשת אלו המינין יחד לענין היותם ממון כהן אלא שביאר שההבדל ביניהם הוא שבכור בהמה טהורה אינו נפדה ושאר הבכורות נפדין וכבר נבאר זה בג"ה ביאור רחב ולפי שאמר בבכור שורך בבכור צאנך למדנו שאם היה של הקדש או של גוי אינו חיי בבכורה. וכן הענין אם היה להם חלק בה שאין אני קורא בה שורך צאנך:
@448 **שמור את חדש האביב.** מזה המקום למדנו שצריך לעבר קצת שנים כדי שיבא פסח בזמן האביב וכבר זכרנו זה במה שקדם:
@448 **הוציאך ה' אלהיך ממצרים לילה.** אף על פי שביום יצאו כאמרו היום אתם יוצאים בחדש האביב. הנה התחלת הוצאתם היתה בלילה כי בסבת מכת בכורות מהרו לשלחם:
@449 **וזבחת פסח לה' אלהיך צאן ובקר.** הנה הצאן היה לפסח אמנם הבקר היה לחגיגת הפסח והם שלמי חגיגה הבאה עם הפסח כמו שזכרנו במה שקדם:
@449 **במקום אשר יבחר ה' לשכן שמו שם.** צוה זה המקום לזבוח את הפסח בבית הבחירה:
@450 **לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות.** כבר ביארנו במה שקדם שאין אכילת מצה חובה אלא בליל הראשון של פסח. ואולם הכונה היא שמה שיאכל מהלחם כל ז' ימים יהיה מצה לא חמץ ושם ביארנו אלו הדינין הנמשכים לה בשלמות ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר כבר ביארנו במה שקדם האזהרה מלהותיר בשר הפסח. ומלחלין אמורי חגיגת הפסח עד הבקר שנאמר ולא ילין חלב חגי עד בקר ובזה המקום הזהיר מלהותיר מבשר שלמי חגיגת הפסח עד הבקר לא תוכל לזבוח את הפסח באחד שעריך ביאר בזה המקום שהפסח אינו נשחט כי אם בית הבחירה כשהיה שם מקום הבחירה רוצה לומ' שילה ובית העולמים שנאסרו אחריו הבמות:
@453 **שם תזבח את הפסח בערב כבא השמש.** רוצה לומר ששחטו לאכלו בערב כבא השמש ולפי שזביחתו היא שם הוא מבואר שזכה המזבח בדמיו ובחלבו:
@453 **מועד צאתך ממצרים.** רוצה לומר כל הלילה שיצאו בו ממצרים שהיה בו מכת בכורות כי הלילה הוא לבד יוכל לאכלו לא יותר ובשלת ואכלת במקום אשר יבחר ה' אלהיך בו מגיד שבשולו ואכילתו יחוייב שיהיה במקם הבחירה ולפי שזה לא יחוייב להיות בבית הבחירה שנה המאמר בזה להעיר שיש הבדל בין זה המקום ומקום זביחת הפסח כי מקום זביחת הפסח ינהג מנהג שאר הקדים ולזה יחוייב שיהיה נשחט בעזרה:
@454 **ופנית בבקר והלכת לאהליך.** לפי שהזכיר בכאן מה שיעשה מהפסח במקום הבחירה חתם המאמ' איך יהיה הפרדו משם בשובו לביתו ואמר שיפנה לביתו בבקר ללכת ולמדה תורה דרך ארץ שלא יצא אדם לדרך אלא ביום ולמדה ובזה יראה שאין באו שם דומה עליו למשא. ואמר בבקר להעיר על החריצות והזריזו' עם שבזה הערה שאם עמד שם קצת היום אין ראוי שיצא משם ביום ההוא מפני חובת המקום הנכבד ההוא:
@455 ששת ימים תאכל מצות וביום השביעי עצרת. אמ' זה כדי שלא נחשוב שנמנה היום השביעי ליום שחיטת הפסח שהוא י"ד ויהיה היום השביעי לו היום העשרים ולזה אמר שאחר שיעברו ששה ימי' לאכילת מצה יהיה היום השביעי עצרת והוא אסור בעשית מלאכת עבודה כמו שקדם ואולם קצר בזה המקום מלבאר אי זו מלאכה הוא שהזהיר עליה בזה המקום להשענו על מה שנתבאר מזה במה שקדם:
@456 **שבעה שבועות תספור לך מהחל חרמש בקמה תחל.** כבר ביארנו במה שקדם שהתחלת הקצירה ראוי שתהיה קצירת העמר הבא בי"ו בניסן ולזה הוא מבואר שזאת הקצירה דוחה שבת כמו שביארנו בפרשת אמור ועשית חג שבועות לה' אלהיך:
@457 **מסת נדבת ידך אשר תתן.** חייבתהו התורה להביא שלמי חגיגה בי"ט ההוא לפי שלא תשיג ידו להתנדב בזה לפי שמעשרותיו שהביא שם אינם בנדבה שהרי הם חובה עליו להביאם שם ולאכלם שם למדנו שצרך להביא מן החולין כאשר יברכך ה' אלהיך לפי שזה הלשון בעינו מצאנו בענין המעשרות זאת הפרשה באמרו. ושמחתם בכל משלח ידכם אתם וביתכם אשר ברכך ה' אלהיך והיה זה כן לפי שהם יהיו בהכרח לפי הברכה מה שאין כן בנדבה למדנו מזה שכבר יביאה גם כן ממעשרותיו ולזה אמרו רבותי' זכרונ' לברכה שהאכילה ראשונה יביא מן החולין והשאר יביא ממעשר שני כי הוא הוגבל לאכלו שם שלמי חגיגה כמו שקדם ואחר כך יאכל מעשר בהמה שהוגבל גם כן לאכלו שם כמו שקדם:
@458 **ושמחת לפני ה' אלהיך.** חייבו גם כן בשלמי שמחה ואמ' לתת ממנו ללוי כשאין לו לתת מחלקו:
@458 **ולגר וליתום ולאלמנה.** צוה בזה כשיהיו צריכים לזה והיו עניים והנה זכר אלו לפי שסתמן להיותם עניים כמו שזכרנו במה שקדם:
@459 **וזכרת כי עבד היית במצרים ושמרת ועשית וגו'.** בעבור שפסח הוא לזכירה גם כן כי עבד היה ישראל במצרים הנה יתבאר שהחגיגה והשמחה נוהגות בו באון שנתבאר בחג השבועות וכבר נתבאר בחג הסכות זה המקום שחגיגה והשמחה נוהגות בו ויתבאר בזה המקום שהם באות מן החולין והמעשרות באופן שזכרנו בחג השבועות עם שכבר מצאנו בכלם אחר זה שנאמר איש כמתנת ידו כברכת ה' אלהיך אשר נתן לך וזה יורה על שאלו הדברים באין מן החולין ומן המעשרות:
@462 **שבעת ימים תחוג לה' אלהיך.** מגיד שחגיגת חג הסכות יש לו תשלומין כל שבעה. וכן הענין בחגיגת יום ראשו של פסח שהרי הוא ראוי בזה הדין כמו חג הסכות. וכבר נתבאר במה שקדם בפרשת אמור אל הכהנים כי ביום ראשון של פסח תהיה שם חגיגה:
@463 **שלש פעמים בשנה יראה כל זכורך את פני ה' אלהיך.** הכונה בזה שיראה האחד את האחר כטעם נתראה פנים ולפי שראיית ה' הדברי' הוא היותר שלמה שאפשר שצריך שיהיה שם בבא להתראות פניו באופן שתהיה ראייתו שלמה לפי מה שאפשר כי למען ראות פלאות אשר בבית הבחירה הובא שם ללמד מהדברים ההם מה שאפשר לו להשיג מהם מהשלמות. ולזה אמרו שסומא באחד מעיניו פטור מן הראיה כן בראותו חסרון ואולי יביא זה לחשוב שבראית השם ית' הדברים יש חסרון ולהורות על שלמות ראיית השם יתע' הדברים חוייב שיהיה הבא שם רואה בשתי עיניו ולזה גם כן דקדקה התורה שלא יבאו שם כי אם הזכרים להיותם יותר שלמי ראיית הלב:
@463 **כל זכורך.** העיר בו שאפילו קטנים יחוייב שיביאום שם כשיהיו בצד יאות לחנכם בזה כדי שילמדו ליראה את ה' הנכבד:
@463 **בחג המצות ובחג השבועות ובחג הסכות.** הנה דקדקה לפתוח בכל המקומות בחד המצות כי הוא הראשון לכל המועדים ומזה הענין נתישר לעמוד על הכונה שכונה התורה באלו המועדים כמו שהתבאר מדברינו במה שקדם:
@463 **ולא יראו פני רקם.** בכאן הזהיר שלא ימנעו מלהעלות עולה לשם יתעלה בבואם לראות פניו. והנה אמרנו שהכונה היתה בכאן לצות על העולה כי היא לה' שאם היתה הכונה בכאן לזולת זה מהקרבנות שיאכל המזבח מהם חלקו כמו השלמים הנה לא היה צריך לצות על זה שהרי היו שם שלמי חגיגה ושלמי שמחה ולזה הוא מבואר שכונת התורה הוא לצות על העולה והיא נקראת עולת ראיה:
@464 **איש כמתנת ידו כברכת ה' אלהיך אשר נתן לך.** לפי שהעולה אי אפשר שתהיה באה מהמעשרות הוצרך לומר איש כמתנת ידו כי לפי אשר תשיגידו ירבה בעולות או ימעיט וכן הענין במה שהוצרך משלמי חגיגה להביא מהחולין והשאר משלמי חגיגה ושלמי שמחה יהיה שעורו. כברכת השם אלהיך אשר נתן לך. רוצה לומר שלפי רוב ברכתו ירבה באלו השלמים או ימעיט ולפי שאין הכונה בשלמי שמחה אלא לשמוח באכילת בשר וראינו שהוא יוצא מהם ידי חובתו במה שיביא שם מהמעשר שני למדנו שאם אין לו מעשר שני יביא מעשר בהמה או בנדרים ונדבות כמו השלמים. הנה זה ביאור מה שצריך לבאר בזה המקום מענין המועדות ואלם שאר דיניהם התבארו במה שקדם.
@465 **שופטים.** אלו דיינים:
@465 **ושוטרים.** אלו הרודים בעם שיש לה' מקל ורצועה להביאם לבית דין ולהנהיגם על פי המשפט אשר יאמרו השופטים:
@465 **תתן לך בכל שעריך.** מגיד שבכל עיר ועיר חייבין למנות שפטים ושוטרים:
@465 **אשר יי' אלהיך נותן לך לשבטיך.** מגיד שבארץ ישראל לבד תנהג המצוה הזאת ואר לשבטיך להעיר שראוי שימנו אלו השופטים מי שהם על כל השבטים והם ימנו שפטים ושוטרים בכל עיר ועיר וימנו שופטים ושטרים בכל שבט ושבט שיהיו על השופטים שבכל שער ושער אשר תחתיהם ויעיד על אמתת זה כי משה מנה השופטים כלם והשוטרים לשבטים כמו שנתבאר בפרשת ואלה הדברים:
@465 **ושפטו את העם משפט צדק.** למדנו מזה שראוי שיהיו אלו השופטים באופן מהחכמה שיהיו ראויים לשפוט את העם משפט צדק ואם לא אין ראוי למנותם ולפי שהמשפט הוא בדיני ממונות ובדיני נפשות כבר ביארנו שהמשפט אשר יהיה בדיני נפשות לא ישלם וכי אם בבית דין של כ"ג והתבאר בזה המקום שכל משפט יצטרכו שופטים והם שנים שנאמר שופטים ושוטרים ומעוט רבים הם שנים ואין ראוי שיהיה בית דין שקול ולזה יוסיפו עליהם אחד והם ג' הנה אם יהיו בעיר ראויים למנות מהם כ"ג שיוכלו לשפוט את העם משפט צדק בדיני נפשות ממנים אותם שם ואם לא הנה ימנו שם בית דין של שלשה אם היו שם ראויים לשפוט צדק בדיני ממונות:
@466 **לא תטה משפט.** רוצה לומר לא תהיה סבה בזה המנוי להטו' משפט וזה יהיה אם תמנה מי שאינו ראוי לשפוט':
@466 **לא תכיר פנים.** רוצה לומר לא תכיר פנים בזה המנוי למנות אדם מפני שהוא קרובך או אהובך או לזולת זה מהסיבות כשלא היה המנוי מצד היותו ראוי לשפוט:
@466 **לא תקח שוחד.** בזה המנוי גם למנו' הראוי לשפוט וזה כי השוחד יעלים ממך זאת הבחינה כי הוא מעור עיני חכמים ומסיר מהם ראות הלב ומעות הדברים הישרים הראוים לצאת מן הצדיקים לפי שלזאת הסבה ימנע מלומר בבלתי ראוי שהוא בלתי ראוי מפני פתוי השוחד:
@467 **צדק צדק תרדוף.** רוצה לומר הוי רץ אחר בית דין יפה שיוכל לשפוט צדק ורדוף הצדק והיושר בכל הדברים כי זה ממה שיגיעך אל החיים הנצחיים ויביאך לירושת הארץ. רוצה לומר להתמיד ולהאריך ישיבתך עליו:
@468 **לא תטע לך אשרה כל עץ.** הזהיר בזה מליטע אשרה אי זה אילן שיהיה אצל מזבח השם יתעלה אף על פי שלא יכוון בה לעבודה זרה לפי שזה היה דרך עובדי עבודה זרה לנטוע אילן אצל מזבחותיהם להתקבץ שם העם ולפי שהזהיר על נטיעת אשרה אפילו לעבודת השם יתעלה הנה הדברים קל וחומר שהוזהרנו מליטע אשרה לעבודה זרה ואפשר עוד שרמז בכאן אל שתי אלו האזהרות ולזה הוציאו בלשון אשרה ויהיה הרצון בזה לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך והכונה בזה לא תטע לך אשרה בשום מקום ולזה אמר לך כמו שביארנו באמרו אלהי זהב לא תעשו לכם שהכונה בו חוץ מהמקדש. ולא תטע לך אשר כל עץ אצל מזבח ה' אלהיך והכונה בזה לא תטע לך אשרה בשום מקום ולזה אמר לך כמו שביארנו באמרו אלהי זהב לא תעשו לכם שהכונה בו חוץ מהמקדש. ולא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך אשר תעשה. מגיד שהמזבח אשר תעשה לך לה' והוא במת יחיד יהיה אסור גם כן לטעת אצלו כל עץ:
@469 **ולא תקים לך מצבה אשר שנא ה' אלהיך.** הנה ענין המצבה הוא בניין שהכל מתקבצים שם והנה הזהיר מהקמתה אפילו לעבוד השם יתעלה כל שכן לעבודה זרה לפי שכן היה דרך עובדי עבודה זרה לעשות אצל עבודה זרה:
@470 **לא תזבח להש' אלהיך שור ושה אשר יהיה בו מום.** הזהיר בזה שלא לזבוח לשם יתע' בעל מום אף על פי שהוא מום עובר כמו גרב לח ומה שידמה לו:
@470 **כל דבר רע כי תועבת ה' אלהיך הוא.** הרצון בזה שאף על פי שלא היה בו מום כיון שיש בו דבר רע הוא תועבת הש' יתע' כמו אתנן זונה ומחיר כלב ומוקצה לעבודה זרה ועובד ורובע ונרבע הזוכה אותו לה' עובר בלא תעשה:
@471 **כי ימצא בקרבך באחד שעריך והוגד לך ושמעת ודרשת היטב.** מגיד שצריך לדרוש ולחקור בזה מאד אם הענין אמת אם לא:
@473 **והנה אמת נכון הדבר.** רוצה לומר שאחר החקירות והבדיקות נמצא שעדות העדים מכוון:
@474 **והוצאת את האיש ההוא או את האשה ההיא אל שעריך.** רוצה לומר שיביאם להשפט לפני השפטים אשר בערים כי לא יצטרך להביא זה הענין לפני בית דין הגדול שבמקום הבחירה כי איננו דבר גדול וזה שהדבר גדול ראוי שיבא לפני סנהדרי גדולה כמו שמצאנו בשופטים ששם משה על ישראל שלא נתן להם כח בדבר גדול כי היו מביאים אותו אל משה והוא היה סנהדרי גדולה עם שבעים איש שהיו עמו שנ' אספה לי שבעים איש מזקני ישר' ומזה המקום למדנו שהיחידים נדונין בסנהדרי קטנה לא העיר כלה ומזה המקום יתבאר שעיר הנדחת היו דנין אותה סנהדרי גדולה וזה שאיש ואשה אתה מוציא אל שעריך לא כל עיר או רובה:
@474 **וסקלתם באבנים ומתו.** ראוי שתדע שזאת הסקילה תהיה בעיר שנמצאו כמו שמצאנו בנערה המאורשה ובכלל הנה בזה האופן יגיע התועלת לבני העיר שצמח זה הרע בתוכם ונוסרו הנשארים והנה אמר ומתו כי כבר תקרא סקילה אף על פי שאין שם מיתה כאמרו ויסקל באבנים ועפר בעפר:
@475 **על פי שנים עדים או שלשה עדים יומת המת.** הזהיר בזה המקום שלא נענש למות על פי עד אחד כי אם על פי שנים עדים או יותר והנה אמר או שלשה עדים להודיע כי כמו שנרבה בדרישות וחקירות ובדיקות אם היו שני עדים כן נרבה בהם אם היו יותר משנים ולא נאמר כיון שהסכימו רבים בזה העדות הנה הוא אמת ואפילו הן מאה או אלף והנה הקיש שנים לשלשה אם היו שם כתות מכחישות זו את זו הרי השנים כשלשה והשלשה כשנים אפילו הן אלף ובצד אחר גם כן שכמו ששני עדים אם ימצא אחד מהם רשע או חומס או אחד מהדברים שיפסל העד בעבורו עדותן בטלה כן הענין אם היו שלשה או יותר בעדות אחד ובאו להעיד עליו:
@476 **יד העדים תהיה בו בראשונה להמיתו.** ביאר בזה שבאבן שישליכו בו כל אחד מהעדים ראוי שיהיה כדי להמית או אם ירה יירה יהיה בהשלכה כדי להמית ואם לא מת בירייה ההיא ישליך עליו העד השני אם יש בה כדי להמית במקום שימות בו בקלות יותר כמו שהתבאר בשרשים הכוללים ואם לא מת בזה תהיה בו יד כל העם באחרונה זה אחר זה עד שימות ואמנם צותה התור' שתהיה בו בראשונה יד העדים כדי שידקדקו יותר בעדותן שיהיה אמתי שאם היה שקר יקשה להם זה יותר מהעדה בשקר כמו שזכרנו במה שקדם:
@477 **כי יפלא ממך דבר למשפט.** למדנו שהוא מדבר בחכם שנעלם ממנו דבר מה למשפט ממשפטי התורה. וזה שמי שאינו יודע דבר לא יאמר עליו שכבר נעלם ממנו אחד מדיני התורה אבל יאמר זה בעצמו' במי שיודע השא' וכ"ש בזה המקו' שלא אמר שיעלם ממנו המשפט ההוא אבל דבר מה ממנו והכונה בזה המאמר שיהיה מחלוקת בשעריך מאחד מהשופטים אשר יש שם עם חביריו או מקצתן עם קצת בדרך שיפלא ממך בשעריך דבר למשפט ולא יוכל להתברר שם:
@477 **בין דם לדם.** הנה המחלוקת היה בין דם לדם הוא שיאמרו קצתם שזה הדם טמא באשה מצד מראהו וקצתם יאמרו שהוא טהור כי אין לו מראה הדם הטמא או שיאמר קצת שהוא דם טהור כאלו תאמר שתהיה שופעת מתוך ארבעים לאחר מ' או מתוך שמונים לאחר שמנים וקצתם יאמרו שהוא דם טמא כי הימים גורמים והתורה טמאהו אחר ימי מלאת או שיאמר קצתם שהוא דם זיבה וקצתם יאמרו שהוא דם נדה או דם לידה כי זמני טומאתה חלוקים:
@477 **בין דין לדין.** כאלו תאמר שנחלקו בשומ' משכון אם יש לו דין שומר חנם או שומר שכר וכן במה שידמה לזה:
@477 **בין נגע לנגע.** שנחלקו בדבר הנגעים שקצתם יאמרו שזה הנגע הוא טמא מפני שעזרו או מפני מראהו ויאמרו קצתם שהוא טהור כי אין לו שיעור הנגע הטמא או שאין לו המראה הטמא ויהיה המחלוקת ביניהם בשעור הראוי לנגע הטמא או במראהו וכן מה שידמה לזה והיה מפני זה דברי ריבות בשעריך ומחלוקת שזה אומר כך וזה אומר כך:
@477 **וקמת ועלית אל המקום אשר יבחר ה'.** למדנו מזה שבמקום הבחיר' היו יושבי' סנהדרי גדולה הכוללת לכל ישראל שהיא על כל הסנהדרין שיש בכל שער ושער:
@478 **ובאת את הכהנים והלוים.** לפי שנאמר בהם יורו משפטיך ליעקב ותורתך לישראל אמר תחלה הכהנים הלוים כי מהם ראוי לבחור לסנהדרי גדולה אם יש בהם ראוים לזה:
@478 **ואל השופט אשר יהיה בימים ההם.** רוצה לומר או אל השופט שיהיה בימים ההם והרצון בזה אף על פי שלא היה כהן ולא לוי ואמר שיהיה בימים ההם שיהיה אז ראוי להיות שופט לפי הדור ההוא ואף על פי שלא היה ראוי לפי דורות אחרים:
@478 **ודרשת והגידו לך את דבר המשפט.** תדרוש עמהם ותחקור מהם להודיע להם המחלוקת במה שהוא ובאיזה טעם נתלה כל אחד מהם. והם יגידו לך את דבר המשפט לפי הנראה להם אם מהקבלה אם מהסברא:
@479 **ועשית על פי הדבר אשר יגידו לך מן המקום ההוא.** צוה כאן לעשות בהוראה הזאת לפי מה שהסכימו ב"ד הגדול שבמקום הבחירה ולפי שלא היה צריך לומר מן המקום ההוא למדנו מזה שאם יצאו מן המקום ההוא והגידו לא חוייב לשמוע לדבריהם ומי שעבר על דבריהם אינו חייב מיתה כי התורה דקדקה שיגידו זה מהמקום ההוא:
@479 **ושמרת לעשות ככל אשר יורוך.** מגיד שאנחנו מחוייבי' להמשך בדבריהם כדברי התורה ובכל מה שיתבארו ממנה ולזה אמר ככל אשר יורוך:
@480 **לא תסור מן הדבר אשר יגידו לך ימין ושמאל.** הזהיר בכאן מעבור על דבריהם וביאורם לדברי התורה אפילו לאסור מה שהתירו או לטמא מה שטהרו וכל שכן להתיר מה שאסרו או לטהר מה שטמאו ולפי שאמר ועשית על פי הדבר ושמרת לעשות אשר יאמרו לך תעשה למדנו שאינו מחוייב ללמוד לתלמידיו כמו שיאמרו בית דין הגדול אך כשיורה הוראה למעשה יחוייב לו להורות על פי התורה אשר הורו סנהדרי גדולה:
@481 **והאיש אשר יעשה בזדון לבלתי שמוע אל הכהן.** על הוראה למעשה הוא חייב לא על למוד והוראה לתלמידיו לא למעשה ולזה אמר אשר יעשה ועל זדון הוא חייב ואינו חייב אם בשוגג הורה למעשה הוראה זו ולזה אמר בזדון ועל מה ששמע מהסנהדרין ההוא הוא חייב לא אם שמע מפי שומע והנה אמר הכהן או השופט כי המופלא שבבית דין והוא מי שהוא ראש עליהם הוא אשר יאמר לו מה שיסכימו בו סנהדרי גדולה כי אין ראוי שיגמ' הדבר כי אם על פיו:
@481 **העומד לשרת שם את פני יי' אלהיך.** למדנו מזה שמקום סנהדרין היה אצל בית הבחירה אשר ישרתו שם השם יתעלה למדנו מאמרו העומד לשרת שהשירות לא יהיה אלא בעמידה:
@481 **ומת האיש ההוא.** זאת המית' חנק הוא לפי מה שתתבאר מהשרשים הכוללים אחר שהתבאר שכבר עשה זה בזדון:
@481 **ובערת הרע מקרבך.** אמר זה לפי שזה המחלוקת יהיה גורם להריסת התורה אם ישפוט בה כל איש לפי דעתו וסברתו ולזה יסדה התורה זה השרש להסיר המחלוקת מענייני התורה בדור ודור ולפי שהאיש ההוא הוא יחיד דנין אותו למיתה בית דין שבעירו אחר החקירה והדרישה ולפי שאמר וכל העם ישמעו וייראו רוצה לומר שכלם ישמעו דבר זה הדין הנפלא וייראו מעשו' כך ולמדנו מזה שמעלין אותו למקום הבחירה ומשהין אותו עד הרגל שיעלו שם הכל ואז יתכן שישמעו זה כל העם וכן הענין במסית שהרי נאמר בו וכל ישראל ישמעו וייראו ולא יזידון עוד רוצה לומר שלא יזידו השופטים להורות לעשות כך כנגד הוראת בית דין הגדול והנה מפני שמצאנו בפרטים שזכרה התורה שהיה בהם המחלוקת שבכלם משתתפים כשיש בהם צד אל שיביאם המחלוקת לדבר שחייבם על זדונם כרת ועל שגגתו חטאת והיה מבואר שאין ראוי שנתן זה הדין החמור למה שהוא קל מהם בזה הענין הנה אם לא היה המחלוקת אשר ביניהם מבוא בשום צד לחטוא בדבר שחייבין על זדונם כרת ועל שגגתו חטאת אין זקן ממרא חייב מיתה עליו אם הורה לעשו' כהוראתו וזה דבר מבואר מהשרשים הכוללים והמשל שאם היה המחלוקת בצציות או בכלאי הכרם או בלולב או בשופר או בסכה ומה שידמה לזה שאין לו מבוא בשום פנים להביא אל חטא שחייבין על זדונו כרת ועל שגגתו חטאת לא יהיה חייב מיתה אם הורה לעשות כהוראתו אמנם אם היה המחלוקת בממון או בדבר מביא לידי ממון בדרך שימשך בהוראתו שיהיה הממון לזה בדין או הפך הנה זה יביא לדבר שחייבין על זדונו כרת ועל שגגתו חטאת כאלו תאמר שקדש אשה בזה הממון ולדברי האומר שהוא כדין הרי היא מקודשת ואם קדשה שני אינה מקודשת לשני וזה המחלוקת יביא לחטא במה שחייבים על זדונו כרת ועל שגגתו חטאת והוא איסור אשת איש ואולם המחלוקת בין דם לדם בין נגע לנגע יביא תכף למה שחייבים על זדונו כרת ועל שגגתו חטאת כי לדברי האומר טהור יכנס במקדש ואם היה טמא הרי הוא חייב על זדונו כרת ועל שגגתו חטאת ולפי שמצאנו זה העונש החמור בזקן ממרא לפי שלא נמשך להוראת בין דין הגדול והיה מבואר שזה הדין הוא יותר ראוי בו מבאיש אחר מפני מעלתו ולפי שכבר יתכן שימשך מזה מההפסד יותר ממה שיקרה באחר לפי שהוא יורה לעשות לרבים ויחטיא בזה רבים אמנם איש אחד לא יחטיא בזה זולתו ולזה הוא מבואר שאיש אחד שעבר על הוראת בית דין הגדול אינו חייב מיתה אך הוא עובר בלא תעשה שנאמר לא תסור וגומ' ובטל מצות עשה שנאמר על פי התור וגו' ולזה רצה שכל ישראל ישמעו וייראו כדי שלא יעברו על הוראת בית דין הגדול:
@483 **כי תבא אל הארץ.** הנה הודיעה התורה העתיד להיות לישראל והוא שאחר ירושה וישיבה ישתדלו להשים עליהם מלך ככל הגוים וגו' שמלכם שופט אותם ולזה סמך משה זאת הפרשה לפרשת סנהדרי גדולה וכן היה העניין שהרי אמרו ישראל לשמואל שימה לנו מלך לשפטנו ככל הגוים. והיינו גם אנחנו וגו'. והוא מבואר שמזה העניין ימשך הפסד התורה בכללה כי התורה התחכמה אל שיהיו שם תמיד ראויי' להוראה לבאר משפטי התורה וחקיה ומצותיה בכללם והם יעמידו התורה וישמרוה מהפסד אך כשיהיה זה הענין מסור למלך לא ישאר שם מי שיעמיד התורה ולזה השגיחה התורה בזה האופן שהשגיחה בזקן ממרה והשתדלה שעם היות להם מלך ימשכו לדברי התור' לא לזולתם כמו שיתבאר מדברינו בבאור זאת הפרשה:
@484 **שום תשים עליך מלך.** היא מצות עשה עם התנאים שזכר אחר זה והוא שיהיה זה המלך אשר יבחר ה' בו ר"ל ע"י נביאו כמו העניין בשאול שבחרו ה' יתע' ע"י שמואל כדי שמה שיבחרהו ראוי להתנהג לפי התורה:
@484 **מקרב אחיך תשים עליך מלך.** ר"ל כשהיה שלא יהיה שם נביא ותבחר אתה המלך שימלוך עליך הנה תחוייב למנותו מקרב אחיך כדי שיתנהג בדרכי התור' אשר גדל בה ומנוי המלך יהיה על ידי ב"ד הגדול כי להם הדברים הכוללים לכל ישראל והנה אמר מלך ולא מלכה כי הנשים דעתן קלה ואל תאוה להם המלוכה:
@484 **לא תוכל לתת עליך איש נכרי וגו'.** הזהיר מנתינת איש נכרי על ישר' שלא ידיחם ויביאם לעבור על דברי תורה ואף על פי שהיה גר ממשפחת גרים אלא אם היתה אמו מישראל שאפילו נתעברה מגוי הרי הבן הוא אחינו רוצה לומר שהוא ישראל כמו שבארנו במה שקדם:
@485 **רק לא ירבה לו סוסים.** רוצה לומר יותר מהצורך למרכבתו:
@485 **ולא ישיב את העם מצרימה וגו'.** רוצה לומר שבה יהיה נשמר שלא ישיב העם מצרימה כי אם הותר לו להרבות סוס ישלח לו אנשים לקנותם משם כי שם נמצאים מאד כאמרו ותעל ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה. והנה אם יעברו האנשים האלה למצרים יעברו על מצות השם יתברך כי הוא צוה לישראל שלא יוסיפו לשוב בדרך הזה עוד רוצה לומר בזה יהיה נשמר שלא ישיב העם מצרימה כדי שלא ילמדו ממנהגיהם המגונים מאד כמו שנזכר בפרשת קדושים תהיו:
@486 **ולא ירבה לו נשים ולא יסור לבבו.** מגיד שאם ירבה לו נשים יסור לבבו מהשם יתעלה ומתורתו לרוב נטות מחשבתו על הנשים מצד רבויים הלא תראה כי שלמה שלא קם כמהו במלכים ושרתה עליו רוח הקודש הטו נשים לבבו והנה המספר המותר למלך לקחת מהנשים ואינו רבוי ביחס אל המלך י"ח שהרי מצאנו בדוד שהיו לו שש נשים ואמר לו השם יתעלה ואם מעט ואוסיפה לך כהנה וכהנה ולא התיר לעצמו לקחת יותר ממה ששלח לו הש"י עם הפלגשי' ושלקח ולזה כאשר הוצרך אל אבישג השונמית לחממו לא לקחה לאשה ולא ידעה ולזה היה שואל אותה אדוניה בן חגית להיות לו לאשה כי לא לקחה דוד לו לאשה:
@486 **וכסף וזהב לא ירבה לו מאוד.** רוצה לומר להשימו בבית גנזיו לאצרו לו לעצמו והסבה בזה כי בקשתו רבוי הכסף והזהב יביאהו לקחת אותו שלא כדין ויסור מהתורה ויביאהו אל הגאוה שהיא גם כן סבה לסור מדברי התורה ואולם אם ירבהו לא לו אך לשם יתעל כמו שעשה דוד באוצר הרב ההוא אשר הכין לה' לבנו' בית המקדש או עש זה לצרכי הציבור ומלחמותיהם אין בזה חטא לו:
@487 **והיה בשבתו על כסא ממלכתו וכתב לו את משנה וגומ'.** הנה נתחייב בזה המלך יותר על הספר שיחוייב כל איש לכתוב לעצמו כמו שיתבאר בג"ה והנה נצטוה המלך בזה כדי שישקוד על התורה ותהיה כל הנהגתו על פי התורה ואמו על ספר הוא המגלה לפי הוראת הגדר:
@487 **מלפני הכהנים הלוי'.** אחשוב שאמ' זה להעתיקו מהספר שאצל הכנים הלוים שהוא היותר מדוקדק שאפשר:
@488 **והיתה עמו.** ר"ל התורה תהיה עמו תמיד שהוא פנוי שיוכל להתעסק בה וקרא בו כל ימי חייו ר"ל בספר ההוא יקרא תמיד ואף על פי שקרא התורה פעמים רבות לא יפטר מה כי הכונה הוא לדבקו בדברי התורה בתכלית מה שאפשר כדי שילמד ליראה את השם יתעלה וישמור את כל דברי התורה והחקי' אשר בה לעשותם:
@489 **לבלתי רום לבבו מאחיו.** מגיד שהגאוה מסירה המלכות ממנו ולזה השתדל הש"י להסיר הגאוה ממנו במה שצוהו לשקוד על דברי התורה ושלא ירבה לו כסף וזהב מאד ובזה גם כן ישמור שלא יסור ממצות התורה ימין ושמאל כדי שיאריך ימים על ממלכתו הוא ובניו בקרב ישראל וזה כי בשכר קיומו התורה יתמיד המלכות לו ולזרעו זמן ארוך ואמר הוא ובניו להגיד שהמלך כשזכה במלכות זכה בו לו ולבניו אם לא יגדו' החטא שיסיר הש"י המלכו' מהם וראוי שתדע שמאמרו שום תשים עליך יתבאר הוא ראוי שיהיה באופן שיהיה עליך מלך ר"ל שתשים בלבך שהוא מלך עליך ולזה ראוי שתירא ממנו ולא תעשה דבר שתסור אימתו מעלך ולא יעשה הוא זה גם כן כי ענין המלך לפי מה שיורה עליו הגדר הוא זה וראוי גם כן שיהיה ענינו ותואו בצד שלא יעשוק ממנו האימה על האנשים והוא מכו' שכל האמור בפר' מלך בספר שמואל מלך מותר לו ולזה הסכמנו לזכרו פה כדי שיהיו דיני מלך נכללי' בזה המקום והנה מה שנזכר שם הוא שיש לו רשות לקחת מבני ישר' מעשר מהבהמות והזרעי' והפרות שנא' צאנכם יעשור ויש לו רשות לקחת בעל כרחם עבדיה' ושפחותיהם וחמוריהם לעשות מלאכתו שנאמר ועשה למלאכתו ויקח בני ישראל לחרוש חרישו ולקצור קצירו ולעשו' כלי מלחמתו וכלי רכבו ובנותיה' יקח לרקחות ולטבחו' ולאופות ובניה' לשי' במרכבתו ולהיות פרשיו ולהיות רצים לפני מרכבתו ובחוריהם היפים יש לו לקחת לשמש לפניו ויש לו להטיל על העם מס או מכס שנאמר ואתם תהיו לו לעבדים ועניין העבדו' הוא נתינת המס שנא' יהיו לך למס ועבדוך:
@490 **לא יהיה לכהנים הלוי' חלק ונחלה עם ישר'.** ר"ל לא יטלו חלק בבזה ונחלה עם ישראל ולא נחלה בארץ והנה יש להם תמורת זה אשי ה' והנה הקרבנות שזכו בהם הכהנים ונחלתו הוא מעשר ראשון הוא ללוים כי הוא להם כמו הנחלה ושאר המתנות שהם לכהנים שהם כמו נחלה כמו שהתבאר בפרשת קרח:
@491 **ונחלה לא יהיה לו בקרב אחיו.** רוצה לומר בארץ לפי שהשם יתעלה הוא נחלתו ודי לו נחלתו בזה והרצון בזה כי מפני שאינו כהן שנאמ' חלק כחלק יאכלו ואין שום חלק ללוי בקדשים שיהיו נאכלים בית הבחירה לבד ולזה הוא מבואר שזה הלוי הוא כהן והנה אמר בו ושרת בשם השם אלהיו כמו שאמר קודם זה לעמוד לשרת לפני ה'. למדנו שהוא מדבר בזה המקום משרות הכהנים ולפי שאמר וכי יבא הלוי יעיר על העת אשר ראוי לבא בו הלוי לפי מה שנתבאר מהשרשים הכוללים וזה אמנם הוא ברגלים למדנו כשיבא שם הכהן ברגל הנה הוא רשאי בכל אות נפשו לבא לבית הבחירה ולשרת שם בשם ה' ככל אחיו הכהנים הלוים העומדים שם לפני ה' ולאכל חלק כחלק עמהם מהקרבנות והמנחה:
@497 **לבד ממכריו על האבות.** ידוע שהאבות חלקו הכהנים למשמרות כדי שיהיה איש על עבודתו באופן שלא יהיה שם מחלוקת ולא תתבלבל מפני זאת העבודה הנכבדת וזהו עניין ממכריהם כאלו מכרו זה לזה חלקם בדרך שיטול זה חלקו בשבת זו וזה חלקו בשבת אחרת וזה יעבוד בשבת זו וזה בשבת אחרת ואמר בזה המקום כי מלבד הקרבנות והעבודות שהם מהממכר הזה יכלו לעבוד הכנים בשוה ולחלק ביניהם חלק כחלק והם הקרבנות והמנחות שהם מפני הרגל ואולם הקרבנות שאינם מפני הרגל המיוחסים לשבת ההוא יהיו לאנשי המשמר לבד העבודה והאכילה לא לזולתם מהכהני' ולפי שהוצרכה התורה להתיר זה לכהנים בעלותם לרגל למדנו שכונת התורה הוא שיהיו הכהנים משמרות כי בזולת זה לא תשלם זאת העבודה הנכבדת באופן ראוי והנה אמרו וכי יבא הלוי יכלול גם כן באו שם להביא קרבנותיו או נדריו ונדבותיו כי מן הראוי לבא שם ולזה יוכל לעבוד אז באלו הקרבנות ולאכל עמם חלק כחלק ואחשוב שכבר אמר כי יבא הלוי לכלול בזה העניין הלוי שהוא גם כן נחלק למשמרות והנה לעניין השרות שהוא בשם יתעלה והוא השיר שאומרי' הלוים על הקרבנות יהיה הבא מהלוי' יכול לשרת בכל אות נפשו לא בשאר עבודות הלוים כי הם לאנשי המשמר. והנה למדנו מזה המקום שהלוים גם כן יחוייב שיהיו נחלקים למשמרות בדרך שיהיה איש על עבודתו ועל משאו כמו שזכרה התורה בפרשת במדבר ופרשת נשא הנה זה ביאור מה שיצטרך אל ביאור מזאת הפרשה שהגבלנו ביאורה פה.
@498 **לא תלמד לעשות כתועבות הגוים ההם.** ידוע שאין הכונה בזה שלא תהיה האזהרה הזאת רק בארץ וזה שאין בכאן דבר יהיה לו התלות בארץ בצד מהצדדים וכבר הזהיר על קצתם גם כן במקומות אחרים ולא התנה בהם שיהיה זה בארץ ואמנם הכונה בזה הוא כי כבר הוצרך הזהירם על זה יותר מפני באם אל הארץ שימצאו שם הגוים ההם עושים אלו הפעולות המגונות ולזה אמר שלא ילמדו לעשות כתועבות הגוים ההם וזהו מצות לא תעשה ולמדנו מזה שלא הזהיר אלא שלא ילמדו לעשות כתועבות הגוים ההם וזהו מצות לא תעשה ולמדנו מזה שלא הזהיר אלא שלא ילמדו לעשות אבל יוכלו ללמוד להכין ולהורות והנה יחוייב לסנהדרין שידעו אלו הדברים מה הם ואיך הם כדי שיוכלו לשפוט עליהם כפי הראוי:
@499 **לא ימצא בך מעביר בנו ובתו באש.** והיא העברה למולך וענינה היה שיעביר האדם קצת זרעו בין האש וידמה אז שכבר כרת ברית עם אלוה ההוא כמו שביארנו באמרו ומזרעך לא תתן להעביר למולך:
@499 **קוסם קסמים.** הוא העושה קצת פעולות כדי שתתבודד מחשבתו ויגיד העתידות מפאת הקסם ובו מינים רבים קצתם יותר מגונים מקצת שכלם בלא תעשה והנה הזהירה התורה מה מפני מה שימשך מזה מההפסד למה שימצא מהכזב בזה המין מההודעה עם שיש בו מינים יתקרבו מאד לעניין עבודה זרה והוא שיעשו מונות ויקריבו לפניהם קצת קטורים וידמו שהצורה תדבר או להם ולזה אחשוב שסמכו למעביר בנו ובתו באש:
@499 **מעונן.** אחשוב שמעונן הוא שיאמר שעה פלוני טובה לכך או רעה ויהיה זה המאמר מופשט מכל סבה אחרת מחייבת זה אך אם יאמר שבתשרי או במרחשון ראוי לזרוע זרעים כך כאמרו תן חלק לשבעה וגם לשמנה ובאדר זרעים כך מפני טבע ההויות מהם או שיאמ' שאין ראוי להקיז דם בתקופת תמוז מפני תגבורת תחום אז או שאין ראוי לחתוך אילן אחר חדוש הירח מפני יתרון הלחות בו או שיפסידהו ויעפשהו וכיוצא בו אינו מכלל העוננות:
@499 **ומנחש.** הנה בענין הנחוש הוא שינחש האדם ויאמר אבא במקום כך ואם יקרה לי כך אעשה כך ואם לא לא כמו שעשה אליעזר ויהונתן או יהיה שילך במקום מה וימצא בדרכו שועל וישוב לו מפני זה להיותו מנחש שכבר ידומה בפעולתיו שיהיה משתדל בעשייתם ואולם בדברים שעברו אינו נחש שיהיה אסור כמו שאמ' נחשתי ויברכני ה' בגללך ולזה רצה שישב עוד אצלו וכן הענין במה שידמה לזה:
@499 **ומכשף.** הוא העושה מעשה כשוף לא האוחז את העינים ויביא לדמות שהוא עושה ואינו עושה וכבר נתבאר זה במה שקדם:
@500 **וחובר חבר.** הוא האומר קצת דברים יחשוב שבאו אז נחשים ועקרבים או אי זה מין שירצה או יאמר לחש על נשיכת עקרב או נחש ויחשוב שיסור חיזקם:
@500 **ושואל אוב.** הוא השואל דבר מבעל אוב והנה בעל אוב בסקילה והשואל לו הוא בלא תעשה ודבר האוב הוא שיעשה בעל האוב קצת פעולות ויאמר קצת דברים עד שידמה השואל שהמת מדבר עמו מתחת הארץ בקול נמוך מאד בלתי נשמע כי אם לשואל כאמרו ושפל מאוב קולך:
@500 **וידעוני.** הוא הדורש אל בעל הידעוני הוא שמניח עצם עוף ששמו ידוע בפיו ויפול כמו נכפה ודיבר בפיו לפי מחשבתו דברים שעתידים להיות:
@500 **ודורש אל המתים.** הוא באי זה צד שיהיה ודורש אליהם אם שילין בבית הקברות ויתבודד דמיונו בעניין המתים וישוב שהמת ידבר עמו ויודיעהו דברים העתידים או יהיה נשאל בגולגלת המת ויעשה פעולות וידבר דברים עד שידמה שיהיה קול נמוך יוצא מתחת שהיו וידבר לו דברים העתידים. והנה אלו הדברים כלם הם רבי ההפסד והגנות והם תועבה השם יתעלה ובגלל התועבות האלה מוריש השם ית' הגוים האלה מפניך:
@502 **תמים תהיה עם ה' אלהיך.** צוה שיהיה בשלמות עם השם יתע' שלא יהיה לבו נקפו כלל באלו השגעונות ולא יפותה אליהם:
@503 **כי הגוים האלה אשר אתה יורש אותם אל מעוננים ואל קוסמים ישמעו.** רוצה לומר כי מפני היותם תחת המזל יקרה להם שיגידו קצת עתידות בזה האופן אך אתה אינך כן כי הנביא לבד הוא אשר יגיד לכם המתחדש באמרו כי לא נחש ביעקב ולא קסם בישראל בעת יאמר ליעקב כמו שפירשנו בפרשת בלק או ירצה כי אלו הגוים לחסרונם לא השגיח השם יתעלה בהם להודיע להם העתידות ואין להם מפני זה נביא ולזאת הסבה נתפייסו באלו המהתלות שיודיעו המעוננים והקוסמים ואולם אתה הנה נתן לך ה' אלהיך שהגיע לך הודעת עתידות בשלמות על יחדי הנביא:
@504 **נביא מקרבך מאחיך כמני וגומ'.** רוצה לומר שאני מקרבך מאחיך אך אין הרצון בזה שיהיה במדרגת משה שהרי זכרה התורה שלא קם נביא עוד בישראל כמשה ולזה אמר אחר זה ונתתי דברי בפיו ולא אמר ואודיעני פנים אל פנים:
@504 **יקים לך ה' אלהיך.** ולזה לא תצטרך לטרוח ללכת בארץ אחרת לדעת העתידות:
@504 **אליו תשמעון.** רוצה לומ' בכל מה שיצוה אתכם מעניני הרשות כמו שמואל לשאול שבעת ימים תוחיל עד בואי אליך ולא קיים מצותו ואמר לו שמואל שכבר עבר על דברי השם יתעלה וכבר רבו המשלים בזה בדברי הנביאים והוא מבואר ממה שבא אחר זה שאפילו במצות התוריות צוה לשמוע אליו וראוי שנחקור מזה ונאמר שאם היתה הכונה בזה שיזהיר לשמוע כל דברי התורה הנה לא יהיה זה הענין שמיעה אליו אבל שמיעה לדברי התורה ואם היתה מצותו לסור ממצות אחרות מהתורה הרי נתבאר במה שעבר שאם צוה לעבוד עבודה זרה לא תשמע לו אפי' לפי שעה ואם היתה מצותו לסור ממצות אחרות מהתורה תמיד הנה זה יהיה גדעון מהתורה והתורה אמרה לא תגרע ממנו וכן הענין בהוספתה כי על דרך הנבואה לא תתכן התוספת בתורה מצוה לדורות ולזה ידמה שסמך בפרשת ראה אנכי אל אמרו לא תוסף עליו ולא תגרע ממנו פרש' נביא השקר להורות שלא נקבל על דרך נבואה שום הוספה תמידית ושום גרעון תמידי בדברי התורה ולזה יחוייב שנשמע אליו במה שצוה לסור ממצות אחרות ממצות התורה שלא תתלה בענין האלהות לפי שעה כמו שמצאנו באליהו בהר הכרמל ובגדעון בן יואש לפי מה שפירשנו בספר שופטים:
@505 **ככל אשר שאלת וגומ'.** רוצה לומר כמו ששאלת בחורב שלא תשמע התורה מפי השם יתעלה אך מנביאו כי יראת מהאש הגדולה ולזה אמרת אלי שאדבר עמכם ותשמעו ולא ידבר עמכם אלהים ויטב בעיני השם יתעלה ונתן לכם תורתו בשלמות על ידי. רוצה לומ' מה שינהג ממנה תמיד ולפי שבקצת העתים יצטרך לי שעה לעבור על קצת המצות שהוא יותר טוב אז לסבה מה כמו שספרנו מעניין אליהו בהר הכרמל הנה ישמעו זה מפי נביא גם כן שכיון שברחו מלשמוע אלו הדברים מפי וזה שכבר אקים להם נביא מקרב אחיכם כמוך שאתה מקרב אחיהם יהיה אצלם:
@507 **ודבר אליהם את כל אשר אצונו.** הן מדברי תורה הן מדברי רשות:
@508 **והיה האיש אשר לא ישמע אל דברי אשר ידבר בשמי אנכי אדרוש מעמו.** רוצה לומר שיהיה חייב מיתה בידי שמים ואמר זה כי אולי יהרהר אחר הנביא ויאמר איך אעבור על דברי התורה. ואולם זאת המחשבה ממנו היא נפסדת כי הוא אינו עובר על דברי התורה אם ישמע אל דבריו לעבור על קצת דברי התורה לפי שעה אך יעבור על דברי התורה אם לא ישמע אל דבריו כשלא היתה מצותו לעבוד עבודה זרה או כנגד אמונת השם יתעלה והיה נכלל בזאת האזהרה נביא שעבר על דברי עצמו:
@509 **אך הנביא אשר יזיד לדבר דבר בשמי.** מגיד שאם לא עשה זה בזדון אינו חייב מיתה:
@509 **אשר לא צויתיו לדבר.** אבל הוא בודה מלבו אלו הדברים ואומר אותם בשמי ויתחייב זה מיתה מפני שנתנבא בשקר ואמר דברים יביאו להכחיש הנבואה או שיביאו לעבור על קצת דברי התורה אשר אנחנו מחוייבים לשמוע לדברי הנביא כהם והמשל שיאמר בשם השם יתעלה שהמטה אשר בידו יהפך לנחש ביום פלוני או יוציא פרח ויוצץ ציץ ויגמול שקדים ביום פלוני וכשלא יקרה זה יתחדש מזה מההפסד שיאמין קצת המון העם שאין יכולת בהשם יתעלה לעשות אלו הנפלאות או שיאמר שהשם יתעלה צוה שילחמו עם זה פלוני ביום השבת והוא לא צוה על זה ויהיה סבה אל שיעברו בזה על מצות התורה והנה יכלול אמרו אשר לא צויתיו לדבר שיאמר השם יתעלה שלחו לומר דברים שמה שצוה אותם השם יתעלה לנביא אחר והנה הפסד שיקרה מזה הוא כי אחר זה יאמר דברים אחרים בשם יתעלה ויחשבוהו העם כנביא ויהיה זה העניין מן ההפסד מה שכבר זכרנו ובכלל אשר לא ציותים לדבר הוא שיאמר דבר בש' השם יתעלה אשר יתבאר לך מהעצם מאמרו שיי' לא צוהו על זה כמו שיוסיף לדורות מצוה או יגרע כי כבר הודיעתנו התורה שזה לא יהיה ונתבאר עוד זה מצד העיון כי לא יתכן שיוחס אל השם יתעלה זה העניין משנוי הרצון:
@509 **ואשר ידבר בשם אלהים אחרים.** רוצה לומר מיתת חנק:
@510 **וכי תאמר בלבבך איכה נדע את הדבר אשר לא דברו יי'.** לפי שצוהב כאן שהמתנבא בשם יי' מה שלא צוהו לדבר הוא חייב מיתה הנה צריך לבית דין שתהיה להם חינת ידעו בה הדבר אשר לא דברו יי':
@511 **אשר ידבר הנביא בשם השם יתעלה ולא יהיה הדבר ולא יבא.** הנה זהו לפי מה שאחשוב אם בעצם הדבור שאמר בשם השם יתעלה. אם באות שישאלו לו אחר זה אמנם בעצם הדבר כמו שיאמ' שכבר מת איש ככה ויחקרו עליו אחר כן ומצאנו שאין הענין כן או שהשם יתעלה אמר אליו שביום ככה יהפכו מי הבור פלוני לדם ובא הזמן ההוא ולא בא מה שייעד ואפשר עוד שיהיה בעצם הדבור באות שיתן עמו באמרו להם המאמר כמו שיאמר שצוהו השם יתעלה שיאמר להם שילכו בעת מה במקום פלוני ואמר עם זה וזה לכם האות שבמקו' ככה תמצאו עתה דבר כך ולא היה כן או שיאמר להם כי ביום פלוני יתחדש אות מה ולא נתחדש וכבר יהיה זה בעצם הדבור באופן אחר כשיאמר להם בשם השם דבר ידוע להם שלא יהיה ולא יבא לעולם ממנו זה הדבר לעולם כמו שיאמר להם בשמו להוסיף לדורות מצוה או לגרוע אותה לדורות ואמנם מה שיהיה מפני אות ישאלו ממנו אחר זה ולא יהיה ולא יבא הנה הוא מעיד שהוא אינו נביא ולזה יתבאר שהדבר שדברו הנביא בשם השם לא דברו יי' וראוי שנחקור בכאן מספק עצום יקרה בזה וזה שלא יתאמת אף על פי שלא יהיה הדבר ולא יבוא היות זה המידע בו נביא שקר וזה שאם היה בזה הייעוד רע הנה השם יתעלה חנון ונחם על הרעה כמו שנתבאר מדברי ירמיהו אל חנניה בן עזור ואם היה הייעוד טוב גם שם לא יבחן אם לא יבוא שהוא נביא שקר כי אולי יעד השם יתעלה הטוב ההוא מפני טוב דרכיהם וכאשר סרו מדרכם הטובה ינחם השם יתעלה מהטוב אשר דבר להביא להם כמו שאמר ירמיהו רגע אדבר על גוי ועל הממלכה והנה התבאר מזה שגם הייעוד הטוב חוזר והיות הענין כן הנה יפול ספק במה מהיעודים יבחן הנביא ונאמר כי לא יבחן הנביא בשם יעוד שיהיה בו תנאי או שיהיה בכחו תנאי רוצה לומר שמעצם היעוד תחייב תנאי כמו הענין ביעוד הטוב שלא יקח זמן מוגבל ומקום מוגבל כמו שביארנו בפרשת וישלח יעקב או כמו הענין ביעוד הרע כי יש תנאי בכחו איך שיהיה כמו שביארנו שם ואולם בייעוד הטוב שיהיה מפני דבר יש תנאי ויסור בסורו וכשלא היה ענינו כן הנה יכהן הנביא שאם יאמר בו שקר הנה הוא נביא שקר והנה יבחן הנביא בכל מה שיאמר מהדברים שהם כך בעת ההוא היה טוב או רע שאם לא נמצאו כן נודע באמת שהוא נביא שקר וזהו אמרו ולא יהיה הדבר ויבחן הנביא עוד במה שיודיע מהדברים העתידים שאין בהם טוב ורע לאיש או לאנשים היה שיאמר שיתחדשו על דרך המופת או שלא יהיה בחדושם דבר זר אצל הטבע כי כשיתבאר שלא יבוא מה שיעד בו הנה נתבאר שהוא נביא שקר:
@511 **בזדון דברו הנביא לא תגורו ממנו.** רוצה לומר כיון שדברו הנביא בזדון. לא תגורו ממנו רוצה לומר אל תיראו מלהמיתו מפני היותו גדול המעלה אצלך ולזה הוא מבואר שאין ראוי לשתוק מללמד עליו חובה ולפי שזה הענין הוא דבר גדול כי הנביא הוא על כל ישראל אם היה נביא אמת הנה לא ישפטוהו כי אם בית דין הגדול שבמקום הבחירה וראוי שלא יעלם מממנו כי בית דין הגדול יש להם כח לעבור על מצות התורה להוראת שעה ולגדר ולסייג שהרי אנחנו מחוייבים לעשות על פי התורה אשר יורו והוא שיהיה להוראת שעה:
@512 **כי יכרית ה' אלהיך את הגויים.** מגיד שאחר ירושה וישיבה בערים ובבתים רוצה לורמ שתשלם החלוקה לשבטים וכל בני השבט קצתם עם קצת חוייבו להבדיל אלו השלש ערי מקלט לא קודם זה וכן מצאנו שהיה הענין בספר יהושע:
@513 **שלש ערים תבדיל לך בתוך ארצך.** אמר זה לפי שלא היה ראוי שתהיינה קצתם בקצות הארץ אבל היה ראוי בזה שישלשו גבול הארץ בדרך שיחלקוהו לשלשה חלקים ובאמצע כל חלק מאלו החלקים תהיה עיר מקלט והנה העדים צריך שיהיו בינונייות לא גדולות ולא קטנות:
@514 **תכין לך הדרך.** הנה הכנת הדרך היתה כדי שיוכל לכוין הרוצח עיר מלקט לנוס אליו וזה היה כתוב מקלט בדרך אשר תביאהו אליו והיתה עוד הכנת הדרך שלא יהיה שם אבן נגף וצור מכשול ולא תל ולא נהר ואם היה שם היו עושים גשר עליו כדי שלא יכשל שם הרוצח ולא יצטרך להתעכב לעבור הנהר והיה עוד מהכנת הדרך שיהיה רחב כדי שלא יכשל שם:
@514 **והיה לנוס שמה כל רוצח.** רוצה לומר היה שהרג שוגג או מזיד הנה ינום שם עד שיתברר דינו ואם היה למות ישלחו זקני עירו ולקחוהו משם ויתנוהו ביד גואל הדם להמיתו כמו שאמר אחר זה בסוף זאת הפרשה:
@515 **וזה דבר הרוצח אשר ינוס שמה וחי.** רוצה לומר שבאלו התנאים תהיה העיר קולטת אותם באופן שלא ימות ביד גואל הדם:
@515 **אשר יכה את רעהו בבלי דעת והוא לא שונא לו מתמול שלשום.** מאמרו אשר יכה את רעהו למדנו שישראל גולה אם הרג ישראל בשגגה וגר תושב אם הרג ישראל בשגגה וגר תושב אם הרג גר תושב בשגגה גולה שהרי אמר בפרשת אלה מסעי שערי מקלט הם לישראל ולגר תושב בתוכם. והנה השננא אף על פי שיעשה בבלי דעת לא יחשב כשוגג כמו שביארנו בפרשת אלה מסעי ואינו גולה:
@516 **ואשר יבא את רעהו ביער לחטוב עצים וגומ'.** למדנו מזה שאם היה העניין ביותר מהשגגה הזאת או פחות אינו גולה משל מה שהוא ביותר שהיה סותר את כותלו ברשות הרבים ונפלה אבן על אדם ומת בבלי דעת והנה זה הוא כמו פושע ואינו גולה משל מה שהיא בפחות שסתר את כותלו בלילה במקום שאין דרך אדם לבוא שם כי זה כמו אנוס או שיהיה כמו בוקע עצים במקום שאין אדם רגיל לבוא שם:
@516 **ונשל הברזל מן העץ והכה את רעהו ומת.** ולא ידע שישנו שם או שיהיה בוקע עצים ונשבר קצת הברזל מן הגרזל והמית כי אין זה מצוי כמו הסרת הברזל מן העץ וכן אם נשל הברזל מן העץ והכה באבן והפילה על ראש אדם ומת אינו גולה כי הוא כח כחו והתורה לא חייבה גלות אלא כשהיה כחו ולמדנו מאמרו ביער שאם היה הרוצח בוקע עצים ברשותו ונשל הברזל מן העץ ומת ברשות המזיק שאין הרוצח גולה כי אינו ביער שיש רשות לנרצח לבא שם. ולמדנו מאמרו ומצא את רעהו ומת שאם המציא רעהו עצמו כשנשל הברזל מן העץ בדרך שהכהו או כשהשליך האבן הרוצח באבן בלא ראות אינו גולה שנאמר ומצא את רעהו לא שימציא הוא את עצמו ואמר בפרשת ואלה מסעי ויפול עליו ולא שיפילה הנרצח על עצמו ולמדנו מזה גם כן שראוי שיהיה זה בדרך מציאה או בדרך נפילה ולזה אם נפלה האבן בעת ההוא מכון להעלותה כאלו תאמר שהיה מושך אותה בחבל להעלותה ונפסק החבל ונפלה הנה אין זאת נפילה או שנשל הברזל מן העץ בעת שהוא מגביה אותו לאחוריו כמנהג הכורת העץ אין זו דרך מציאה ועוד שהתורה אמרה ונדחה ידו בגרזן לכרות העץ בעת שהוא מניע הגזרן לכרות לא כעת שהוא מניעה להגביה ולזה יהיה כאלו פטור מלגלות וכן אם בא הרוצח ברשות להכות הנרצח והרגו בשגגה בעת עשותו המצוה אינו גולה כמו האב המיסר את בנו והרב תלמידו והנה למדנו זה מאמרו לחטוב עצים שהוא דבר הרשות וראוי שתדע שאם לא מת הנרצח תכף באופן שיהיה שם דרך לומר שלא מת מחמת המכה אינו גולה שם שנאמר ומצא את רעהו ומת שימות מהמכה לא מפני דבר אחר:
@517 **פן ירדוף גואל הדם אחרי הרוצח.** מגיד שקודם שהתבאר שהוא גולה ראוי לשמור שלא ירדוף גואל הדם את הרוצח וישיגנו ולזה צותה התורה שנבדיל עוד שלש עדים כדי שלא ירבה הדרך ויהיה זה סבה שישיגנו ואמנם אח' שהתבאר שהוא גולה ישתדלו יותר בשמירתו שהרי אמר בפרשת אלה מסעי והשיבו אותו העדה אל גבול מקלטו ולזה צריך שיתנו לו חבורה שישמרוהו בדרך מגואל הדם בדרך שיושיבוהו אל מקלטו אשר נס שמה. וראוי שתדע שמי שאינו גולה מפני שלא הגיע עניינו לשגגת הגולה. הנה אם הרגו גואל הדם נהרג עליו אולם מי שאינו גלוי מי שחטאו יותר גדול מחטא הגולה הנה אם הרגו גואל הדם פטור כמו הענין במחוייב גלות שאם הרגו גואל הדם חוץ לעיר מקלטו פטור והנה נבאר בכאן מה שנתחדש מביאור זה הדין בספר יהושע וזה שכבר נאמר שם שהרוצח יעמוד פתח שער עיר המקלט וידבר את דבריו באזני זקני העיר ההיא רוצה לומר שיאמר להם שהוא רוצח והם יתנו לו מקום וישב עמם למדנו מזה שבערי המקלט יחוייב להם לתת מקום לרוצח בזולת שכירות לא בשאר ערי הלוים אף על פי שכלם קולטים כמו שזכרנו במה שקדם ולזה אם ירצה לשבת שם יחוייב לתת לו מקום בלא שכירות. ואמר שם וישב בעיר היא עד עמדו לפני העדה למשפט עד מות הכהן הגדול מגיד שבעיר מקלטו שנס שמה ראשונה שמה הוא שב בהתברר הדין שהוא גולה עד מות הכהן הגדול:
@519 **וירחיב ה' אלהיך את גבולך ונתן לך את כל הארץ אשר דבר לתת לאבותיך.** הוא ארץ הקני והקניזי והקדמוני שלא נתנו לישראל עד הנה ויעד השם יתעלה נתינתם לאברהם:
@520 **כי תשמור את כל המצוה הזאת וגומ'.** מגיד שאם היו ישראל שומרים כל מצוות התורה היו נגאלין:
@520 **ויספת לך עוד שלש ערים על השלש האלה.** זה לאות שזה דבר עתיד כי לא מצאנו שהוסיפו ישראל על שש ערי מקלט ועוד שהרי אמר השם יתעלה בתתו עשרת השבטים ביד ירבעם אענה את זרע דוד אך לא כל הימים מגיד שעתיד המלכות להיות כלו לזרע דוד וזה דבר לא נהיה עד הנה ולזה הוא דבר עתיד בהכרח אשרי המחכה ויגיע:
@521 **ולא ישפך דם נקי בקרב ארצך.** ויהיה עליך חטא עצום אם ישפך דם נקי בקרב ארצך:
@522 **וכי יהיה איש שונא לרעהו.** אמר זה לפי שלא יכוין אחד להרוג אחר אם לא היה שונא לו וארב לו. למדנו מזה שהמכוין להרוג את זה והרג זה אינו נהרג שהרי לא ארב לו:
@522 **והכהו נפש ומת.** לא מי שאפשר לומר שמת מחמת דבר אחר:
@522 **ונס אל אחת הערים האל.** להמלט מיד גואל הדם עד שיתברר דינו למות ואחר שנתברר דינו מות ישלחו זקני עירו ויקחו אותו מעיר מקלטו לגמור הדין בפניו ואחר יתנוהו ביד גואל הדם בדרך שימות בידו:
@524 **לא תחוס עינך עליו.** רוצה לומר על הרוצח. אבל השתדל שימות לפי המשפט:
@524 **ובערת הדם הנקי מישראל.** רוצה לומר שופכי הדם הנקי:
@525 **לא תשיג גבול רעך אשר גבלו ראשוני'.** הזהיר בזה מלשנות הגבול בנחלות לפחות קרקע הכירו ואמר אשר גבלו ראשונים להודיע שאם נשתנה הגבול שגבלו ראשונים לאי זו סבה שתהיה והשיגו זה להשיבו למקומו אינו עובר על זה הלאו:
@525 **בנחלתך אשר תנחל.** מגיד שבארץ עובר זה על שני לאוין על לא תגזול ועל לא תשיג אם עשה זה בחזקה ובאונס או על לא תגנוב ולא תשיג אם עשה זה בסתר ובגנבה אמנם אינו עובר כי אם על לאו אחד:
@526 **לא יקום עד אחד באיש לכל עון ולכל חטאת.** למדנו בזה שעד אחד אינו נאמן שישפטו על פיו לכל עון ולכל חטאת איזה חטא שיחטא האדם בו והנה יתבאר מזה שאף על פי שאינו קם לחתוך על פיו המשפט בשלמות הנה הוא קם לחייב שבועת האיש ההוא כמו שמצאנו בסוטה שאף על פי שאין שם עדים שנטמאה לגמור דינה על פיהם הנה יקום בה העדות החלוש ההוא לשבועה:
@526 **על פי שנים עדים או שלשה עדים יקום דבר.** הקיש בזה עדות שלשה לעדות שנים כמו שביארנו במה שקדם על דבר דיני נפשות:
@527 **כי יקום עד אחד באיש לענות בו סרה.** ראוי שתדע שזה העד הוא שנים כי בזולת זה לא יהיה עדות ולא יתכן בו לומר בו כאשר זמם כי עד אחד לא יאמן להביא עליו עונש והנה אלו העדים העידו דבר שהוא סר מדרך האמת:
@528 **ועמדו שני אנשים אשר להם הריב לפני יי'.** מגיד שאלו העדים המעידים שקר יחוייב שיבואו במקום הבחירה לבחון אם הם עדי שקר לפני סנהדרי גדולה ההם הכהנים או השופטים אשר יהיו בימים ההם ודרשו השופטים היטב והנה עד שקר ראוי שישאל שואל איך יבחן שהם עדי שקר כי אף על פי שיעידו מאה כנגד עדותן לא נתברר שעדותן שקר כי השנים נאמנים כמאה כמו שקדם מאמרו על פי שנים או שלשה עדים ואם מפני הדרישה והחקירה איך יתברר שהם עדי שקר מפני שאינם מסכימים זה לזה במקום או בזמן ועוד אם היה שלא יסכימו זה לזה אולי האחד הוא מעיד אמת ומי יודע אי זהו מהם המעיד שקר ואיך יתכן לומר באחד כאשר זמם והנה הדין לא יגמר מפני עדות אחד ולזה יחוייב שנאמר שמצד הדרישה יתבאר ששניהם מעידים שקר והמשל שעם הדרישה החקירה יאמרו שזה היה בירושלם ביום פלוני ויבאו עדים אחרים שיעידו שביום ההוא היו אלו העדים עמהם במקום רחוק מירושלם למרחק עצום שלא יתכן שיהיו ביום ההוא בירושלם כי זה ממה שיחוייב יהיו אלו העדים הראשונים עדי שקר ואפילו היו הראשונים מאה או יותר והשנים שנים לבד ואם יאמר אומר למה יאמינו יותר דברי השני' מדברי הראשוני' שמעידים שכבר היו ביום ההוא בירושלם התשובה הנה הוא יודע שהאדם אינו נאמן בדברי עצמו כדי שיאמן עליו אחד ולזה תמצא שאפי' מאה שיאמרו שאינם חייבין לראובן דבר ובאו שנים עדים והעידו שהם חייבים לו מנה הנה השנים עדים יהיו נאמנים כנגד המאה שהם נוגעים בעדות וכן בזה המקום הוא ידוע שמה שהעידו העדים שראובן הרג שמעון ביום פלוני או במקום פלוני הנה אינם מחייבים אותו מיתה מפני הרגו אותו ביום ההוא או במקו' ההוא כי באי זה יום שהרגהו הוא חייב מיתה ולזה הוא מבואר שאמרם במקום פלוני וביום פלוני אינו מעם העדות אבל הוא לבחון עניינם אם יאמרו אמת אם לאו ולזה הוא מבואר שהם נוגעים בעדותן בזה הענין והשני' שמעידים כנגדם אינם נוגעים בזה העדות כי אינם מעידים בעניין אחר יהיה העונש בעבורו זולתי על עדותן במקום ובזמן ולזה יהיו נאמנים השנים כנגד הראשונים:
@529 **העד שקר ענה באחיו.** מגיד שלא יעשו דבר כנגדו עדיין זולתי שהעיד בו שקר ולזה גם כן אמר כאשר זמם לעשות לאחיו שזמם לבד ולא עשה ואולי יחשוב חושב כי הדברים ק"ו אם מפני העדות שקר לבד יתחייבו בו אף על פי שלא הגיע ממנו התכלית הרע אשר בעבורו העידו לשקר כל שכן שיתחייבו. אם נתנה פרייה ומחשבתם הרעה אלא שכאשר יעויין בזה לטעון בזה טענה לומ' שאין ראוי שיעשו העדי' זוממין אח' שהגיעה המחשבתם לפועל על יד בית דין וזה כי הש' יתעלה מסכים למה שישפטוהו שופטיו ומאתו משפטיו כאמרו ונקי וצדיק אל תהרוג כי לא אצדיק רשע הגיד בזה כי מי שהצדיקוהו היה מהשם יתעלה להצדיקו כמו שביארנו בפרשת ואלה המשפטים ולזה אמר שלמה פלגי מים לב מלך ביד ה' אל כל אשר יחפוץ יטנו ואמר אלי הוא ממלוך אדם חנף ממוקשי עם כי אל אל האמר נשאתי לא אחבול כמו שביארנו לספר איוב והנה היה זה כמו שליח לעשות רצון השם יתעלה באיש ההוא שחטא בדבר אחר ואם לא חטא בזה עם שזה יהיה בושת לבית דין אם יתפרסם שדנו איש להריגה דרך משל על לא חמס בכפיו ויביא זה להרהר אחר משפטי התורה שלא יהיו ישרים ולאלו הסבות יתבאר שאין ראוי שנעניש העדים בזה האופן כאשר יצאה מחשבתם לפועל:
@530 **ועשיתם לו כאשר זמם לעשות לאחיו.** רוצה לומר שאם חשב להפסיד ממון יפסיד ממון להלקותו ילקח להמיתו ימות ואם חשב להזיקו במה שאי אפשר שיוזק בו זה העת כאלו תאמר שהעידו על כהן שהוא בן גרושה או בן חללה או זונה אין העונש להשים אותם חללים כמו שחשבו לעשות לכהן כי זה בלתי אפשר אך היו לוקים בעבור עברם על לא תעשה שהו' לא תענה ברעך עד שקר ולפי שאמ' לאחיו למדנו שזוממי עדות בת כהן שזנתה אינם בשרפה אך בחנק כמו שחשבו לעשות לאחיהם והוא האיש שאמרו ששכב עמה עם שהענין בבת כהן הוא דבר חדוש שהיא בשרפה ובועלה בחנק ולזה לא ימשך זה החדוש כי אם במקום שבארה בו התורה:
@530 **ובערת הרע מקרבך.** בער העושה הרע מקרבך וימשך מזה שיתבער הרע והנשארים ישמעו וייראו ולא יוסיפו לעשות כדבר הרע הזה בקרבך אמר זה בעדים זוממים לפי שכבר יחשב שהם אינם עושים חטא גדול כמו שיחטא ההורג חבירו או המזיק לו והחובל בו בידו ולזה יקלו האנשים בזה החטא ויהיה זה סבה להפסיד הקבוץ המדיני ולזה היה הענין בתכלית הרע וההפסד ולזאת הסבה רצתה התורה שיתפרסם דינו לכל ישר' וזה יהיה בעלותם שם לרגל כדי שיראו כלם מעשות בדבר הרע הזה:
@532 **ולא תחוס עינך נפש בנפש.** הזהיר בזה מלרחם על עד זומם מלעשות לו כאשר זמם נפש בנפש רוצה לומר שאם יחייבו מיתה בעדותן ידונו במיתה ההיא שנאמ' כאשר זמם:
@532 **עין בעין שן בשן יד ביד רגל ברגל.** ראוי שתדע שאי אפשר בעדות שיחייבו בו חסרון אבר כי המחסר אבר יענש בממון כמו שביארנו בפרשת ואלה המשפטים ולזה ירצה בו בזה המקום עונש ממון ולפי שצוה שלא לחמול על עד זומם שלא השלים מחשבתו למדנו שכל שכן שאנחנו מוזהרים מלחמול על החובל בחבירו באיזה צד שיהיה מאותם החמשה דברים שזכרנו ביאורם בפרשה ואלה המשפטים וכבר ביארה זה התורה עוד בביאור בבושת אמר וקצותה את כפה לא תחוס עיניך ואמר עין בעין שן בשן יד ביד רגל ברגל להורות שקנס הממון ישוער לפי האבר שהיה בו הנזק ולמדנו עוד בזה תועלת אחר והוא שכמו שהעין יותר נכבד לאין שיעור יותר מהשן וזה מפורסם מעניינו כן היד היא נכבדת לאין שיעור מהרגל כי היד הוא כלי להשתמש בה בכל המלאכות המעשיות וכמו שהעין יש לו מבוא גדול בעיוניות לראות המוחשים וללמוד ספרים כן הענין ביד כי ביד שיכתוב האדם יתיישר בתכלית מה שאפשר לעמוד על סודות הדברים שתהיה חקירתו בהם והיתה מחכמת המשל הזה כי כמו שהעין הוא למעלה מהשן כן היד למעלה מן הרגל הנה זה ביאור מה שיצטרך אל ביאור במה שהוגבלנו ביאורו מזאת הפרשה.
@533 **כי תצא למלחמה.** הזהיר לירוא מהאויבים ואף על פי שהם עם רב מישראל ויש להם סוס ורכב כי ראוי להם לבטוח בשם יתעלה אשר אין מעצור לו להושיע ברב או במעט ויעיד על זה שכבר העלנו מארץ מצרים בכח גדול וביד חזקה עם היות ישראל אז בתכלית החולשה ולא בחרב ולא בחנית הושיעם השם יתעלה והנה הזהיר מלירוא מהם כי עם שזה הוא ממעוט הבטחון בשם יתעלה הנה הוא דרך אל שינוצחו ישראל:
@534 **והיה בקרבכם אל המלחמה.** הנה יתבאר שזה הדבור יהיה בקרב ישראל אל המלחמה והוא ברצותם לערוך מלחמה כי אז הם בתכלית הקורבה למלחמ' וכבר יתבאר עוד מהדברים הבאים אחר זה:
@534 **ונגש הכהן ודבר אל העם ואמר אליהם.** מגיד שהכהן המיוחד לזה ידבר אז בכללות אל העם אלו הדברים הנזכרים בכאן תחלה ולפי שהם נאמרים להמון רב הנה יחוייב שיהיה זה המאמר בקול רם באופן שיהיה זה המאמר אליהם וכן אמר בפרשת כי תבוא וענו הלוים ואמרו אל כל איש ישראל קול רם ואמנם צוה שיהיה זה על ידי אחר כי הכהן המיוחד לזה ראוי שיהיה גדול המעלה כדרך שישמעו אליו כל ישראל ולפי שלא יהיה ראוי לאיש גדול להגביה קולו מאד חוייב שיהיה שם אחר לאמרם קול רם ולפי שביא אחר זה קצת הדברים ישנו אותם השוטרים להשמיעם אל העם למדנו שזה המאמר שיאמר או הדברים שזכר ראשונה הוא יותר נכבד מהשוטרים ולזה אמרו שהוא כהן אחר ולפי שצוה לדבר אליהם אלו הדברים למדנו שחייב לאמרם בזה הלשון שנאמרו בתורה:
@535 **שמע ישראל אתם קרבים היום למלחמה על אויביכם.** אמר זה להודיעם שצריך שישתדלו שינצחום על כל פנים שאם יפלו בידם לא יחמלו עליהם לפי שהם אויביהם:
@535 **אל ירך לבבכם.** אמר זה לפי שרכות הלבב והפחד הוא סבה ליראה והיראה הוא סבה אל שלא יתנהג האדם בחכמה ובדרכי הגבורה בענין המלחמה אבל יתנהג בחפזה ובבלי ההתישבות וזה יהיה סבה להשבר לבם רוצה לומר שיערצו ויחתו:
@536 **כי יי' אלהיכם וגו'.** כי יי' שהוא מנהיג אתכם ומשגיח הנה הוא הולך עמכם למלחמה רוצה לומר ששכינתו דבקה בכם להלחם בעבורכם עם איביכם או להושיע אתכם מידם כאמרו יי' ילחם לכם והראה בזה המאמר שאם יהיו ישראל ראויים שינצחו אויביהם מפני שקדם בדרכי התורה הנה השם יתעלה הולך עמם להלחם בעבורם אם אויביהם ואם אין ישראל באופן שתדבק בהם כמו ההשגחה הזאת או שלא שלם עון אויביהם עדיין הנה השם יתע' הולך עמם במחנה להושיע אותם מיד אויביהם:
@537 **ודברו השטרים אל העם לאמר.** ידוע שאלו הדברים ראויים היות קודם הדבור הראשון שזכרנו הוא מה שאמר אל תיראו וגו' כי הדבור ההוא איננו ראוי כי אם להולכים להלחם לא להולכים ושבים לביתם ולזה הוא מבואר שאלו הדברים יאמר הכהן תחלה בעת היות ישראל סמך ליציאת ארצם. והדבור שזכר תחלה יאמר סמוך ערכם המלחמה שנאמר כקרבכם אל המלחמה:
@537 **מי האיש אשר בנה בית חדש ולא חנכו.** לא דקדקה התורה שיבנהו אבל כיון שהוא חדש לו שלא חנכו ינהג בו זה הדין שזכר אך אם יש בחנכו עברה כגון שגזלו הוא מבואר שלא יחזור מפני זה ולזה גם כן אמר אשר בנה כי לפי הנהוג יבנה האדם משלו ולפי שאמר בית למדנו שהוא ראוי שיהיה באופן שידבק בו גדר הבית והנה סתם הבית הוא שיהיה ראוי לדירה:
@537 **ילך וישוב לביתו.** צוהו שילך וישוב לביתו שמא ימות במלחמה ואיש אחר יחנכנו והנה אמר זה כי אם ילך במלחמה ידאג על שלא זכה לחנך הבית ויחשוב שבעבור זה סבב השם יתעלה המלחמה לבעבור מנעו שלא יחנכו ויחנכנו אחר ויהיה זה סבה אל שירך לבבו ויירא במלחמה ויבא מפני זה רע לאנשי הצבא והנה ענין לכתו ושובו הוא לספק מים ומזון לבני החיל:
@538 **ומי האיש אשר נטע כרם ולא חללו.** הנה לא דקדקה התורה שיהיה הוא הנוטע איך שיהיה שלא חללו עדין רוצה לומר שלא זכה לאכול ממנו כי עד השנה הרביעית לא יזכה לזה כי השלשה שנים הראשונים יהיה כל פריו ערלה ולפי שלא דקדקה התורה כי אם מפני היראה שיש לו שאיש אחר יחללנו למדנו שכן הדין בכל אילני מאכל שיהיה בהם הרבוי כמו הענין בכרם והנה מצאנו באילנות שם כרם אמר מגדיש ועד קמה ועם כרם זית והנה הפחות שיפול עליו זה השם מהאילנות הם חמשה ולזה יתבאר שאם היו לו חמשה אילני מאכל ולא זכה עדיין לחללם ולאכול מהם הוא הולך ושב לביתו לסבה שזכרנו בענין הבית:
@539 **ומי האיש אשר ארש אשה ולא לקחה.** הנה למדנו מאמרו ואיש אחר יקחנה שאין הקפדה בזה אלא מפני זה הפחד שיהיה לו לסבה אשר זכרנו בענין הבית ולזה הוא מבואר שזה הדין נוהג בכל אשה שתהיה קנויה לו קצת:
@539 **ולא לקחה.** היתה בתולה או אלמנה או שומרת יבם ואם היה בלקוחיה עבירה אינו חוזר מפני זה וזה מבואר וכן המחזיר גרושתו שהרי לקחה וראוי שתדע שמי שארס אשה ולקחה אינו יוצא כלל לצבא עם עורכי המלחמ' ואינו הולך ושב לספק לאנשי הצבא מזונותיהם שנאמר נקי יהיה לביתו שנה אחת ושמח את אשתו אשר לקח כמו שיתבאר במה שיבא בג"ה בפרשת כי תצא ושם התבאר שכן הדין במי שבנה בית חדש וחנכו וכאשר נטע כרם וחללו:
@540 **ויספו השטרים לדבר אל העם וגו'.** ראוי שתדע שעד זה המקום היו דברי הכהנים ראשונה בצאתם מהארץ והשוטרים היו משמיעים זה לעם אחריו אולם בקרבם למלחמה יאמר הכהן כדברי' הראשונים תחלה והוא אמרו שמע ישראל וכהן אחר יאמר הדברים ההם לישראל בקול רם ואחר זה ישוב הכהן לאמר מי האיש אשר בנה וגו' והשוטר משמיע אחריו אלו הדברים לכל ישראל בקול רם והנה אלו השוטרים הם שוטרי של סנהדרי גדולה שהם משותפים לכל ישראל ולזה לא תהיה זאת המלחמה רוצה לומר מלחמת הרשות כי אם על פי בית דין הגדול שהשוטרים הם תחת השופטים ובמצותם יעשו כל מה שיעשו:
@540 **ויספו השטרים לדבר אל העם וגו'.** רוצה לומר שזה המאמר יוסיפו השוטרים לדבר אל העם יותר ממה שישמעו מפי הכהן:
@540 **מי האיש הירא ורך הלבב ילך וישוב לביתו.** רוצה לומר שהיה רך הלב שאין לו כח לשמוע לדברי הכהן שהזהירם מזה מפני טבעו ומנהגו יפרד מאנשי המלחמה וילך וישוב לביתו לספק מזונותיהם לבני הצבא כדי שלא ימס לבב אחיו כלבבו בראותם פחדו והיותו נחפז לנוס כי כך דרך אנשי המלחמה רוצה לומר שבראותם איש אחד מהם נס ינוסו כלם:
@541 **והיה ככלות השטרים לדבר אל העם ופקדו שרי צבאות בראש העם.** מגיד שכל אלו הדברים הם סמוך לעת רצותם לערוך המלחמה ולזה אמר כי תכף שישלימו אלו הדברים ימנו שרי צבאות בראש העם להנהיגם בסדור הראוי לדבר המלחמה ולפי שהשתדלותם היה שלא יגרום איש מהאנשים אשר שם שימס לבב העם היו ממנים אנשי' אחרים גבורי כח ישמרו שלא ינוסו איש מהם כדי שלא ימס לבב העם כלבבו וראוי שתדע שאלו הדיינים ממה שאמר פה מי האיש אש בנה בית גו' אינו נוהג אלא במלחמת הרשות אבל במלחמת מצוה כלם יוצאים והראיה כי במלחמת הרשות מדבר מה שאמר אחר זה כי תקרב אל עיר להלחם וגו' שהיא מלחמת הרשות כמו שהתבאר שם והראיה עוד שבמלחמת מצוה כלם יוצאים מה שאמר משה לבני גד ולבני ראובן כי נשיהם וטפם ישארו בעריהם והם יעברו חלוצים עם אחיהם מגיד שלא נשאו שם מהם כי אם נשיהם וטפם ואולם מה שאמר תחלה שיאמר הכהן שמע ישראל הוא נוהג גם במלחמת מצוה שהרי מצאנו בתורה שהזהיר השם יתעלה פעמים רבות שלא ייראו מאותם הגוים ואל יערצו מפניהם אך לא היו אומרים מי האיש הירא כי כלנו חייבים להחרים הגוים ההם:
@542 **כי תקרב אל עיר להלחם עליה וקראת אליה לשלום.** מגיד שקודם שילחמו עליה יחוייב שיקראו לה לשלום ואם יענו שהם רוצים להיות בשלום עם ישראל ויסכימו כל העיר לפתוח לישראל הנה כל העם הנמצא בה יהיו לישראל למס ויעבדו אותם וזה משותף למלחמת הרשות ולמלחמת המצות כמו שנתבאר בספר יהושע שנאמר לא היתה עיר אשר השלימה אל בני ישראל וגו' כי מאת יי' היתה לחזק את לבם לקראת המלחמ' למען החרימם וזה ראיה שאם היו משלימים לא היו חורגים אותם ולפי שאסור לישראל להניח עובד עבודה זרה בארצם שנאמר לא ישבו בארצך פן יחטיאו אותך לי למדנו שהוא מחוייב כשישלימו שיקבלו שלא לעבוד עבודה זרה ויקבלו עם זה כל המצות שנצטוו בני נח בהם כדי שיכנעו למצת שהם מחוייבים בהם והם שפיכות דמים ואבר מן החי ויתר המצות שהתבאר מהתורה שנתחייבו בהם כמו העריות והגזל כי עליהם היה המבול. ואמר אברהם ואמרו אשתו זאת והרגו אותי ואותך יחיו מגיד שכלם היו נשמרים מערכיות לפי דיניהם. ואולם ברכת יי' היא בכלל עבודה זרה ואין לך חטאה גדולה מזו וכן מחוייבים להושיב דיינין במקומותיהם ולהעמיד אלו הדינים שנאמר שופך דם האדם באדם דמו ישפך וזה אי אפשר מזולת שופט וכשיקבלו עליהם זה צריך שיקבלו עליהם עם זה להיות לישראל למס ולעבדם שנאמ' והיה כל העם הנמצא בה יהיו לך למס ועבדוך והנה ענין המס יכלול מס הגוף והממון כאמרו וזה דבר המס אשר העלה המלך שלמה לבנות את בית יי' ואת המלוא ואת חומת ירושלם ואת כל ערי המסכנות אשר היו לשלמה כל העם הנותר מן האמורי ויעלם שלמה למס עובד למדנו מזה שיש להכריחם לעשות עבודת המלך ולבנות חומה והבתים ומה שיצוו עליו או שיהיו חוטבי עצים ושואבי מים לבית יי' כמו שגזר יהושע לגבעונים ואולם מס הממון הוא שיתנו שנה בשנה סך מה והנה ימשך מענין העבודות שלא יהיו מושלים על ישראל וינהגו כמנהג העדים להיות שפלים לפני ישראל:
@544 **ואם לא תשלים עמך וגו'.** רוצה לומר אם לא תסכים להשלים עמך אך יצאו לעשות מלחמה לישראל או יעמדו תוך העיר ולא ירצו לפתוח לך ולא יצאו גם כן למלחמה אז תתן העיר במצור כדרך שלא יכנס בה שום מזון מחוץ וכאשר יתנה יי' בידיך באי זה שיהיה מאלו הדברים הנה תכה את כל זכורה לפי חרב רוצה לומר האנשים הגדולים כי הזכרים והטף והנשים והבהמה וכל אשר תהיה בעיר וכל שללה תבוז לך:
@546 **ואכלת את שלל אויבך אשר נתן יי' אלהיך לך.** מגיד שגם המאכלות האסורות שימצאו שם יוכלו לאכול כאלו תאמר החזירים המלוחים והנבלות והטרפות אך העבודה זרה והנטפל אליה אסורה כמו שקדם וזה אמנם התירה להם התורה אם ירעבו ולא ימצא להם מה לאכול זולת זה כדי שלא תרפנה ידיהם מן המלחמה:
@547 **כן תעשה לכל הערים הרחוקות.** מגיד שזה אינו נוהג רוצה לומר להחיות הנשים והטף אלא בערים הרחוקות שאינם משבעה עממין אך אם הם משבעה עממין ולא השלימו אסור להחיות מהם הנשים והטף ולזה הוזהרו שלא למות מהם כל נשמה במקום שהיו מחיים קצתם בערי שאר הגוים והטעם כדי שלא ילמדו ישראל לחטא באלו התועבות שגדלו עליהם:
@551 **כי תצור אל עיר ימים רבים.** רוצה לומר אחר שלא הסכימה העיר להשלים עמך וכונה לעשות עמך מלחמה אם לא תוכל להמלט בדרך אחרת כי קודם זה לא יצורו עליה כמו שקדם:
@551 **לא תשחית את עצה לנדוח עליו גרזן כי ממנו תאכל.** מגיד שאסור להשחית אילן מאכל אע"פ שהוא מהאויבים הנלחמים עם ישראל כ"ש אם היה משל ישראל והנה זה לא יהיה אלא כשהיה בזה השחתה אך אם אין בו השחתה רק תועלת יוכל האד' לקצצו ולזאת הסבה ג"כ אסור למנוע מאילן מאכל אמת המים שהוא שותה ממנו כדי שלא יבש וישחיתהו:
@551 **כי האדם עץ השדה לבא מפניך במצור.** רוצה לומר האם עץ השדה הוא אדם שיוכל להיות נכנס מפני אימתך תוך העיר בסבת המצור שאתה צר עליה והנה ה"א מלת האדם הוא ה"א התמה:
@552 **רק עץ אשר תדע כי אל עץ מאכל הוא.** רוצה לומר כמו שהיה אילן סרק או היה ממין עץ מאכל אך יבש כדרך שלא יעשה פירות אותו תשחית ותכרות לבנות מצור על העיר אשר לא שלימה עמך ומבקשת לעשות עמך מלחמה עד שתכבוש אותה ותנהג אז בה לפי הדינים הנזכרים ולפי שאמר עד רדתה למדנו שאפילו בשבת יוכל לבנות המצור ולעסוק במלחמה כיון שהתחילו זה קודם השבת כי אינם מפסיקים דבר המלחמה הזאת מפני שום סבה ולפי שאמר העושה עמך מלחמה למדנו שאם היו רוצים לברוח אין מוחין בידם אף על פי שלא השלימו ולזה בבנותם המצור לא יקיפו העיר מכל רוחותיה אך יניחו רוח אחד שאם יסכימו לברוח דרך שם יוכלו לברוח ואין אנחנו מצווים להמיתם אף על פי שלא הסכימו לקבל עליהם המצות שזכרנו כיון שלא ישבו בארצנו ומניחי' לנו העיר שלהם:
@553 **כי ימצא חלל באדמה אשר יי' אלהיך נותן לך לרשתה.** הנה זה כולל ארץ ישראל ועבר הירדן כי שתיהם נתנם השם יתעלה לרשת:
@553 **כי ימצא חלל.** רוצה לומר שימצא חלל בעת שימצא אבל אם היה מפרכס עדיין או שהיה נחנק אינו נקרא חלל:
@553 **באדמה.** ר"ל על הארץ לא שיהיה טמון בגל:
@553 **נופל בשדה.** לא שיהיה תלוי באילן כי אינו נופל ולא צף על פני המים כי אינו בשדה ולא בתוך העיר כי איננו בשדה:
@553 **לא נודע מי הכהו.** מפני שלא אמר אין עד מי הכהו למדנו שכיון שנודע זה לאחר זולתי המכה לא ינהג בו זה הדין ואפילו היה עבד או אשה שהרי אני קורא בו נודע מי הכהו כיון שנודע לזה:
@554 **ויצאו זקיניך ושופטים.** כיון שאמ' אחר זה זקני העיר ההיא למדנו שאלו הזקנים והשופטים הם הכוללים לכל. העירות ולזה יהיו מבית דין הגדול שבירושלם וראוי היה להיות כן כי אין ראוי שימדוד זה רק מי שהוא על העיירות כלם לשפוט מי מהם יתחייב להביא העגלה ולפי שהמעט שיפול בו שם זקניך הוא שנים והמעט שיפול בו שם שופטיך הוא שלשה כדי שיהיה ראוי לבית דין שלא יהיה בית דין שקול בלי מכריע למדנו שחמשה יוצאים מבית דין הגדול:
@554 **ומדדו את הערים אשר סביבות החלל.** ראוי שתדע שזאת המדידה יחוייב שתהיה מהמקום הנראה בו החיות יותר והוא הראש כי מהמקום ההוא ראוי שיקרא חלל ובחוטם ממנו לפי שבו יוכר תכף אם האדם מת מצד הנשימה והנה אם היו שם חללים רבים מפוזרין מודדין כל אחד בפני עצמו ואם היו זה על זה מודדין מן העליונים כי האחרים ממונים ולפי שכבר נאמר אחר זה ולקחו זקני העיר ההיא למדנו שעיר שאין בה בית דין לא היו מודדין לה ולמדנו מזה עוד שהעיר שהזקנים שבה אינם זקני העיר ההיא אבל זקניך כמו הענין במקום הבחירה לא היו מודדין לה:
@555 **והיה העיר הקרובה אל החלל.** ידמה ממה שאמר בזה כי העיר ההיא מביא העגלה מפני שחזקם שמשם הוא הרוצח והוא מבואר שעיר גדולה ועיר קטנה אף על פי שהעיר הקטנה היא יותר קרובה הנה העיר הגדולה היא יותר קרובה אל החלל כי יותר ראוי שימצאו שם רוצחים מהמצאם בעיר הקטנה והנה מצאנו בתורה שהלכה אחר הרוב שנאמר אחרי רבים להטות ומצאנו בזה המקום שהלכה אחר הקרוב. וזהו אמנם בעיירות שוות:
@555 **ולקחו זקני העיר ההיא.** זהו בית דין שבאותו מקום הקרוב אל החלל:
@555 **עגלת בקר אשר לא עובד בה אשר לא משכה בעול.** והנה העגלה הוא עד שתי שנים לפי מה שיורה עליו הגדר אמר עגלת בקר שיהיה הוייתה ממנה:
@555 **אשר לא עובד בה.** להגיד שהעבודה פוסלת בה כמו הענין בפרה ויקרא עובדה כל מה שנעשה בה לצורך הבעלים לא לצורך עצמה:
@555 **אשר לא משכה בעול.** הנה אם עלה עליה ועל אינה נפסלת ואולם אם משכה בעול שאף על פי שלא חרשה נפסלת ולפי שלא אמר בה תמימה למדנו שאין המומי' פוסלין בה:
@556 **והורידו זקני העיר ההיא את העגלה אל נחל וגו'.** רוצה לומר אל נחל שירוצו מימיו בכח חזק:
@556 **אשר לא יעבד בו ולא יזרע.** לפי שאין הכונה בזה שלא יהיה נזרע המקום ההוא מעולם ולא נעבד כי זה ממה שאי אפשר לדעת אמתתו הנה הוא מבואר שהכונה שלא יזריע בנחל ההוא אחר זה ולא יעבד לעולם וזאת העבודה שנאסרה שם היא בגופה של קרקע כמו הענין בזריעה:
@556 **וערפו שם את העגלה בנחל.** רוצה לומר שבתוך הנחל יערפוה בקופיץ ממול העורף והנה הטרפה היא כמתה ואינ' עגלה כי אם שתוף השם ולפי שמצאנו שאסרה התורה ההנאה גם בנחל שתערף בה למדנו שהעגלה אסורה בהנאה ולזה כונה התורה אשר לא עובד בה כדי שתהיה בכללות משולל ההנות ממנה ולזה היתה עריפתה בנחל איתן כי המים ההם חיים שלא נעשה בהם מלאכה עם שזה יורה שלא היצתה הנאה בארץ שתחת הנחל מזמן רב ולזה ידמה שלא יהיה ראוי עשות מלאכה אחרת עם העריפה והנה העריפה יחוייב שתהיה ביום כמו שהתבאר בשרשים הכוללים:
@557 **ונגשו הכהנים בני לוי כי בם בחר יי'.** זכר בזה המקום שלא יחשוב חושב שתהיה זאת המצוה דבר רק לפי שאין בה הזאה ולא כי אם מעט מהדברים הנוהגים בקדשים ולזה ספר שה הענין הוא דבר גדול ולזה לא ישלם כי אם על יד הכהנים בני לוי:
@557 **לשרתו ולברך בשם יי'.** הוא ברכת כהנים והנה אלו לא יהיו אלא מעומד כי כן דרך השרות ואמר גם כן לעמוד ולשרת. והברכה בשם יתעלה היא גם כן מעומד שהרי גם מה שיברכו הלוים את יי' הוא מעומד כמו שקדם:
@557 **ועל פיהם יהיה כל ריב וכל נגע.** אמר כל ריב כי הם ראויים שיהיו בסנהדרי גדולה שיתבאר המחלוקת בדינים ובנגעים על פיהם עם שראיית הנגעים אינה כי אם על פי כהן:
@558 **וכל זקני העיר ההיא הקרובים אל החלל.** מגיד שכל הזקנים ששם מתקבצים על זה לאמר ידנו לא שפכו ואמר קרובים אל החלל ולא אמר הקרובה אל החלל להגיד שאף על פי שאין העיר יותר קרובה. הנה יתכן שיהיו הם יותר קרובים מפני רוב האנשים הנמצאי' בעיר היא יותר ממה שימצא מזה בעיר הקרובה ממנה:
@558 **ורחצו את ידיהם על העגלה הערופה בנחל.** מגיד שכלם רוחצים ידיהם שם והם בתוך הנחל במקום העריפה:
@559 **וענו ואמרו ידינו לא שפכו את הדם.** ראוי שתדע שזה המאמר לא יאמרו אותו הכהנים כי לא יצטרך לומר להם זה אבל יאמרו זה זקני העיר ההיא אשר ראוי שיהיה הרוצח מעירם ומגיד שאם ראה זה אחד מהם אף על פי שלא ידע מה הכהו אינה נערפת שהרי איננו יכול לומר ועינינו לא ראו וידמה שיאמרו זה להתנצלות וזה כי החטא הוא עליהם אם לא הישירו העם לשמירת דרכי התורה בדרך שלא תהיה ביניהם רציחת נפש ואם לא השגיחו בזה לשמרו לפי מה שראוי אם בא עליהם וזה המאמ' ראוי לאמרו כן בלשון הקדש כמו שהגביל אותו התורה:
@560 **כפר לעמך ישראל.** הנה זה המאמר יאמרו אותו המכפרים לעם והם הכהנים וזה מבואר ולזה אמרה התורה שיהיו נגשי' הכהנים בני לוי ואומרים אותו בלשון הקדש כמו שהוגבל פה והוא שכבר יאמרו כפר לעמך ישראל אשר פדית יי' ולא תתן דם נקי בקרב ישראל. מגיד שהחטא הזה הוא חטא לישראל כלו כי כלם נענשים עליו כמו שקדם והרצון באמרו ולא תתן דם נקי ולא תתן חטאת דם נקי והנה השם יתע' מכפר להם החטא אחר זה שנאמר ונכפר להם הדם והו' מבואר שהחטא אשר להם בשביל שקרה זה המקרה הרע בגבולם הוא מתכפר להם בזה אמנם הרוצח לא יכופר בזה ולזה אמר ונכפר להם ולזאת הסבה אמר במה שקדם ולאר לא יכופר הדם אשר שופך בה כי אם בדם שפכו:
@561 **ואתה תבער הדם הנקי מקרבך.** מגיד שאם תרצה לעשות הישר בעיני יי' תשתדל לבער דם הנקי בהרבותך החקירות בזה כדי שיתברר לך מי הכהו או ירצה בזה שכאשר תעשה הישר בעיני יי' לא יקרה בקרבך כמו זה החטא כי הזקנים יוכיחו העם ויקבלו כלם מוסרם ללכת בדרכי התורה הנה זה ביאור מה שיצטרך אל ביאור בזאת הפרשה:
@562 **כי תצא למלחמה על אויביך.** למדנו שבמלחמת הרשות הכתוב מדבר שנאמר ושבית שביו והנה מז' עממין לא הותר להם שבי אך חוייבו להחרים כל נפש אדם כמו שקדם:
@563 **וראית בשביה אשת יפת תואר וחשקת בה.** ידוע שאין תנאי ההתר לבא עליה שתהיה יפת תואר וזה מבואר בעצמו והנה אמרה התרה וחשקת בה מכל מקום כיון שהוא חושק בה עשתה התורה נחת רוח ליצרו. והנה מן התנאי שיראנה בשביה רוצה לומר בעת השביה אך בזולת זה לא הותר לו אם לא נתגיירה ואמר אשת אי זו שתהיה בתולה או בעולה ואפילו אשת איש כגון שברח בעלה ולמדנו מזה שאין אישות לגוי לאסרה על ישראל ולמדנו מזה שאין לו רשות לקחת יותר מאחת שנאמר אשת וחשקת בה ולא בה ובחברתה:
@563 **ולקחת לך לאשה.** ידוע שאין זה לנשואין שהרי אמר אחר זה ואם לא חפצת בה ושלחתה לנפשה וגו' לא תתעמר בה תחת אשר עניתה מגיד שהוא בא עליה קודם שישאנה ואין הביאה ההיא מה שאמר ואחר כן תבא אליה ובעלתה שהרי אמר אחריו ואם לא חפצת בה מגיד שאם לא רצה לבא עליה להיות לו לאשה לא יוכל להתעמר בה תחת אשר עניתה ולזה לאות שכבר בא עליה קודם זה בגיותה שאם נתגיירה לא הוצרכה התורה לומר ומכור אל תמכרנה בכסף. ואמנם הכונה באמרו ולקחת לך לאשה שיותר לבא עליה ורמז בזה שאין ראוי לו שיקחנה לזה הפעל המגונה אם לא לתכלית שישאנה אחר זה והנה סמך לזה אמרו והבאת אל תוך ביתך. להעיר שאין ראוי שינהג בה הפקר אך יכניסנה לביתו או לדומה לו שיבא שם בצנעה ושם יבא אליה ואמר ולקחת לך לאשה להעיר שאין ראוי שיקחה כי אם לו לא לאיש אחר:
@564 **והבאת אל תוך ביתך.** בארה התורה שאין ראוי לו שיבא עליה ויעזבנה תכף שעשה רצונו ממנה או שיכשל בה עוד אחר זה אבל יחוייב לו שיביאה אל תך ביתו והשתדלה התורה שיעשה בה מה שתשקיט רתיחת התאוה אשר לו בה כדי שלא יקחנה אחר זה לאשה ולזה צותה שתגלח ראשה כדי לנוולה ולהסיר יפיה ולגדל צפרניה כי זה גם כן ממה שינוולה ושתבכה קרוביה עד ירח ימים. כי הבכי גם כן יסיר יופי האשה והנה לזאת הסבה גם כן צותה שתסיר שמלת שביה מעליה כי הבגדי' ההם ישימנה יפה ליפויים ולזה חשק בה בהיותה עם הבגדים הנאים ההם ואמר שתשב בביתו כדי שיראה אותה בנוולה ויסור חשקו ממנה והוא מבואר שאם רצתה להתגייר מיד לא יצטרך לזה כי היא מותרת לו אחר זה ולזה הוא ממתין לה עד שלשים יום לראות אם תרצה להתגייר:
@565 **ואחר כן תבא אליה ובעלתה והיה לך לאשה.** מגיד שאינו בועל אותה אלא להיות לו לאשה וזה יהיה בהכרח אחר שנתגיירה:
@566 **והיה אם לא חפצת בה.** רוצה לומר שמתוך נוולה שראית סר החשק שהיה לך או ששקטה תאותך אחר שבאת אליה:
@566 **ושלחתה לנפשה.** לפי מה שאמר לא תעמר בו וידענו שאסור להושיב בארצנו עובדי עבודה זרה למדנו שאינו משלחה עד שתקבל עליה שלא לעבוד עבודה זרה ויתר המצות שנצטוו בני נח ותהיה לנפשה כמו שאר הגרים התושבים:
@566 **ומכור לא תמכרנה בכסף וגומ'.** הזהיר מזה שלא יוכל למכרה כו שימכרו שאר השבי גם הוא לא יוכל להשתעבד בה במדרגה ההשתעבד בשבי מפני שכבר ענה אותה ולזה יהיה לה זה השכר ממנו וכאלו התחכמה התורה בזה להשקיט תאות החושק בה בשביה מפני ראותו שאחר זה תסור ממנו הממשלה שהיתה לו בה ולפי שאמרה התורה שלא יתעמר בה ולא ימכרנה מפני שענה אותה למדנו שכזה יחוייב שימנע מלתת אותה במתנה שהרי ישעבדה בזה ועוד שהתורה אמרה ושלחתה לנפשה רוצה לומר שבעת שישלחנה תהיה לנפשה:
@567 **כי תהיין לאיש שתי נשים וגו'.** לפי שהכונה בזה הוא שלא יעיר מהבכור חלקו הראוי לו מהנחלה ואף על פי שהוא בן השנואה למדנו שאין דקדוק התור' שתחיינה הנשים שתים לבד ושתהיה האחת אהובה והאחת שנואה אבל רצה התורה להודיע זה הדין במקום אשר יתכן יותר שימצא זה הענין והנה סמך זה לענין יפת תואר לפי שהתורה גלתה שהיא שנואה למקום ולזה השתדל לנוול אותה וכאלו באר בזה שאין לו רשות להעביר חק הנחלה מהבכור שנולד לו ממנה אחר שנתגיירה כי אז היא אשתו והנה בארה זה התורה בכללות:
@568 **והיה ביום הנחילו את בניו את אשר יהיה לו.** רוצה לומר כאשר ינחיל את בניו כל קניניו:
@568 **לא יוכל לבכר את בן האהובה על פני בן השנואה.** הזהיר בזה שלא יתן דין הבכורה לבן האהובה ויסיר מבן השנואה ולפי שלא למדנו מזה עדיין שלא יוכל להסיר מהבכורה בן השנואה ובן האהובה יחד הוצרך לומר אחר זה שיחוייב לו להכיר את הבכור בן השנואה לתת לו פי שנים בכל אשר ימצא לו. רוצה לומר שבכל מה שזכה בו האב ביום ההנחלה והוא ברשותו יהיה לבכור כפל מה שיגיע לכל אחד מבניו הנשארים וזה שאם היו ג' בנים עושים מנכסי האב ד' חלקים השנים לבכור וכן על זה הדרך. ומזה המקום למדנו גם כן שלא יוכל מדרך ההנחלה לעשוק מנחלת אחד מבניו ולתת לאחר ומזה המקום למדנו שאין בכורה בבנות וראוי שתדע שה הדין אינו נוהג אלא במה שהאב נותן על דרך ההנחלה שנאמר ביום הנחילו אבל אם רצה לתת בתורת מתנה נותן מה שירצה לאשה שיהיה מבניו ולפי שהתורה לא הזהירה מזה אלא לבניו למדנו ששאר יורשיו יוכל להנחיל את מי שירצה:
@570 **כי יהיה לאיש בן סורר ומורה.** אין הכונה במה שאמר לאיש אבי הבן הזה שאם היה כן היה אומר אינו שומע בקולו ובקול אמו לא איננו שומע בקול אביו. ולזה יהיה הרצון בזה שיגיע הבן הזה למדרגה שיהיה לאיש וזהו תכף שהגדיל ויצא מכלל קטנות ולפי שבעת ההוא שהוא עת לקיחת מוסר הפליג בזה להיות בלתי שומע לקול אביו ולקול אמו. ונטה אל הזוללות והשכרות הפליגה התורה בענשו להתברר העניין שכל מה שיגדל יוסיף ברוע:
@570 **סורר ומורה.** רוצה לומר שהוא סר ממוסר האב והאם וממרא אותם בדרך שאינו שומע לקולם וזאת ההסרה וההמראה הוא בענין הזוללות והשכרות כמו שאמר אחר זה בננו זה סורר ומורה איננו שומע קולנו זולל וסובא. והנה שם הזולל וסובא לא יפול אלא בזוללי בשר וסובאי יין כאמרו אל תהי בסובאי יין בזוללי בשר למו והוא מבואר שלא באי זה שיעור שיאכל אדם מן הבשר וישתה מן היין יקרא זולל וסובא אבל יש לו שיעור לא יפול זה השם על פחו' ממנו ושערו חכמים כי מי שיאכל בשר משקל חמשים דנרין בת אחת וישתה מן היין חצי לוג בבת אחת יתכן שיתואר בזה השם והוא מבואר מצד הוראת הגדר ולא יקרא מפני זה זולל וסובא גם כן אם לא אכל זה השעור ברעבתנות ושתה היין בגרגרנות כמנהג הזוללים והסובאים ובמנהג שהם אוכלים אותו ושותי' אותו וזה שהבשר לא יהיה חי ולא שלם הבשול והיין לא יהיה חי ולא שלם המזינה וזה מבואר ממנהגם לפי שלא יקרא בזה השם מפני פעם אחת שיקרה לו זה כמו שלא יתואר ברופא מי שרפא פעם אחת אם לא יורגל במלאכת הרפואות הנה צריך שיהיה הענין הזה באון שיוכל זה הבן להרגיל עצמו בו וזה אמנם יהיה כשיגנוב משל אביו ואמו מה שיקנה בו הבשר והיין שאם יגנוב משל אחרים הנה לא ימצא לו לגנוב שם אלא בקושי ויצטרך גם כן שיאכלנו בבית אחרים עם חבורה מהאנשי' רעי המנהג באלו הדברים כי אז ימצא לו בקלות להמשך לזה המעשה ואמנם אם יאכל זה וישתה ברשות אביו הנה לא ישלם לו אלא בקושי ההסתר שם מאביו ומאמו והוא מבואר עוד שהבשר שירגילו לאכלו אילו הגרגרנים הוא בשר בהמה ויחוייב גם כן שיהיה קונה בזול מה שיקנה ממבשר והיין שאם יצטרך לקנות זה ביוקר לא ימצא לו לגנוב משל אביו מה שיוכל להרגיל בו עצמו בזה המנהג הרע כדרך שיתכן שיתואר כשהוא זולל וסובא:
@570 **ויסרו אותו.** הנה מפני שזה המאמר יסבול שיסרו אותו אביו ואמו כאמרו במוציא שם רע ויסרו אותו הנה ראוי שנבין בזה המקום שלקוהו בית דין לפי שהעונש הנפלא שענשוהו התור' אח' זה הוא יותר ראוי בזה האופן ר"ל כאשר נתברר שאינו מקבל מוסר לא מאביו ומאמו ולא מבית דין. והנה אמרו איננו שומע בקול אביו ובקול אמו ר"ל שלא יקבל מוסרם ואף כי יכוהו ויוכיחוהו כי בזול' זה לא יתברר שאינו שומע בקולם ואמרו ויסרו אותו ר"ל מי שיש לו רשות ליסרו אחר האב והאם והם הדיינים:
@570 **ולא ישמע אליהם.** ר"ל שעדיין אינו מקבל מוסר אביו ואמו אף כי לקה ע"י ב"ד:
@571 **ותפשו בו אביו ואמו.** מגיד שצריך ששניהם יסכימו בזה:
@572 **ואמרו אל זקני עירו בננו זה.** ר"ל בננו זה סורר ומורה שהבאנוהו בפניכם ולקח והנה עודנו מחזיק ברשעתו:
@572 **איננו שומע בקולינו זולל וסובא.** וצריך שיהיו זקני העיר ההיא ראויים דון דיני נפשות ר"ל שיהיו עשרים ושלשה וצריך שיהיו שם הדייני' שלקח בפניהם כי בזולת זה לא ישפטוהו סקילה כי המשפט הראשון לאו הוא אלא למלקות:
@573 **וכל ישראל ישמעו וייראו.** לפי שביאר שבשער מקומו יהיה נסקל חוייב מזה שתהיה הודעת זה לכל ישראל כשיכתבו זקני העיר היא כל ישראל סקלנו פלוני בב"ד פלוני מפני שהיה סורר ומורה ואולם התנאים האחרים אשר בזה הענין הם לפי מה שנזכר פה שלא ינהג זה הדין אלא בבן לא בבת שנא' כי יהיה לאיש בן ולא ינהג בבן אלא כשהוא גדול כי לא יהיה בן עונשים קודם זה ואחר זה ימשך לו זה הדין עד שישלם היותו לאיש שנאמר כי יהיה לאיש בעת היותו לאיש לא אחר זה ולפי שהוא יתחיל להיות איש כשיתחילו השערות אצל הערוה כמו שהתבאר בשרשי' הכוללי' הנה נשלמה היותו לאיש אחר שהקיפו השערות כל הגיד ולפי שה ישלם לפי הנהוג בשלשה חדשי' הנה לא יהיה ימי סורר ומורה כי אם ג' חדשים ואם תתאחר בו יותר צמיחת אלו השערות הה נלך בזה לפי הנהוג על דרך הטבע ואם תמהר לו נשפט להקל שכיון שנשלמה היותו לאיש הנה אינו נסקל ולא ינהג זה אלא כשיהיו לאביו ולאמו ידי' לתפוש ורגלים ללכת ולשון לדבר עינים לחזות שנאמר ותפשו בו אביו ואמו והוציאו אותו ואמרו בנינו זה ולפי שהם מרגישים שהוא אינו שומע בקולם למדנו שאינם חרשים וראוי שתדע עוד שאם היה באכילתו ושתייתו צד מצוה או צד עברה לא היה נסקל שנאמר איננו שומע בקולנו שאין בעניינו אלא השמיעה בקולנו או לא שמיעה יצאו מצוה ועברה שיש בהם שמיעה בקול השם יתעלה או לא שמיעה ולפי שההלקאה והסקילה לא יהיה אחת להם אלא בעדות צריכים אביו ואמו שיביאו עדים תחילה שהוא זולל וסובא בתנאים הנזכרים וילקוהו בית דין על זה ואחר זה יביאו עדים שאינו שומע בקולם ויסקלוהו:
@574 **וכי יהיה באיש חטא משפט מות והומת ותלית אותו על עץ.** כבר בארה התורה בזה המקום שהנתלה הוא המקלל שאמ' כי קללת אלהים תלוי ולפי שעובד עבודה זרה נקרא מגדף גם כן כאמרו והנפש אשר תעשה ביד רמה את יי' הוא מגדף למדנו שהעובד עבודה זרה נתלה גם כן ושני אלו הם נסקלים כמו שקדם ומגיד שאחר מיתתם יתלום על עץ:
@575 **לא תלין נבלתו על העץ.** מגיד שאם הלינה עובר בלא תעשה:
@575 **כי קבור תקברנו ביום ההוא.** מגיד שמצות עשה לקברו:
@575 **כי קללת אלהים תלוי.** רוצה לומר מפני שברך השם יתעלה הוא תלוי ויהיה זה גורם לחלול השם כל זמן שיתמיד שם כשיאמרו האנשים על מה נתלה ולפי שכוונת התורה היא זו למדנו שהעץ שיתלוהו עליו ראוי שיהיה נקבר עמו כדי שלא יאמרו זהו העץ שנתלה בו פלוני על שבירך השם יתעלה ויהיה זה גורם לחלול השם והנה מצאנו כי גם לכבוד הבריות חסה התורה שלא יהיה זכר למה שבאה לאדם תקלה על ידו ולזה אמר ואת הבהמה תהרוגו ולזה הוא מבואר שהעץ הוא נקבר עמו ולזה גם כן אמר כי קבור תקברנו ולא אמר תקברנה שיהיה שב אל הנבלה ולזה יחוייב שיהיה העץ תלוש שלא יהיה חסר אלא הקבורה ומזה המקום למדנו שלא ישהו אותו שם אבל יתלוהו ותכף יקברוהו עם העץ כי כל מה שישהו אותו שם נמצא שם שמים מתחלל:
@575 **ולא תטמא את אדמתך אשר יי' אלהיך נותן לך.** רוצה לומר כי בזה החלול לשם יתעלה שיהיה גורם דבר הלנת נבלתו על העץ. תטמא אדמתך. ולזה ראוי שתהיה נזהר לבלתי הלין נבלתו על העץ או אמר ולא תטמא את אדמתך מפני העפוש שיתחדש אז במקם ההוא אם תשאר שם הנבלה ואולם שאר הדינים אשר בזה הוא שאין האשה נתלית שנאמר אותו ולא אותה ושאין תולין כליו עמו אבל תולין אותו ערום שנאמר אותו ואין בית דין תולין שנים ביום אחד שנאמר אותו ולא אותו וחבירו ולמדנו מזה שמצות עשה לקבור כל הרוגי בית דין ביום המיתה שנאמר קבור תקברנו ביום ההוא וכל שכן שראוי לקבור שאר מתים ביום המיתה אלא אם הלינו אותם לכבודם שעל ההלנה שהוא נוול הזהירה תורה לא על ההלנה שהיא לכבוד:
@576 **לא תראה את שור אחיך או את שיו נדחים.** כגון שראה חמור וכליו הפוכים פרה ורוצה בין הכרמים שהצורה מוכחת שהם אובדים וכן כל מה שדומה לזה ואמר לא תראה להגיד שכיון שהוא רואה אותם אפילו מרחוק הוא מחויב להטפל בהם להשיבם לאחיו:
@576 **והתעלמת מהם.** רוצה לומר שאין לך רשות להתעלם מהם אך תחוייב להשיבם והוא מבואר שאינו מתעלם מהם אלא אם היה דרכו שלא להתעלם מהם אם היו שלו והיו נדחים בזה האופן כי אז הוא מתעלם מהם מפני היותם משל אחיו לא שלו ואולם אם היה זה הרואה אותם גדול המעלה עד שיקל בהם אם היו שלו ולא יטרח לחזור אחריהם הוא בעצמו או שהיתה אבידתו שיאבד בעת היותו טורח בזה יותר מערך האבדה ההיא אף על פי שהיתה שלו יעזבינה לזאת הסיבה או שהתורה תכריחהו שלא ילך שם להשיבה ואפילו היתה שלו כמו שהיה כהן והאבדה בבית הקברות הנה לא יחוייב להשיב זאת האבדה:
@576 **השב תשיבם לאחיך.** כיון שהשיבם לאחיו קיים המצות ואף על פי שלא הודיעו זה:
@577 **ואם לא קרוב אחיך אליך.** רוצהלומר כי אף על פי שאתה יודע מי הם הבעלים אינך זקוק לטרוח להשיבה אליהם אם היה רחוק ממך:
@577 **ולא ידעתו.** מגיד שאיך שהיה משי אלו הסבות הנה תאספהו אל תוך ביתך ולא תוך בית אחר:
@577 **והיה עמך עד דרוש אחיך אותו והשבותו לו.** מגיד שאם ידרוש ולא ידרוש אותו הדבר. ר"ל שלא יתן סמנים בדרך שיתבאר שהוא אותו לא תחוייב להשיבו שלא יתן סמנים בדרך שיתבאר שהוא אותו לא תחוייב להשיבו לו אך אם יתן סמניו אז תשיבנו לו:
@578 **כן תעשה לחמורו וכן תעשה לשמלתו וכן תעשה לכל אבדת אחיך וגו'.** מגיד שאר נדחים הוצרך להזכיר שכן יהיה זה הדין בשמלה וכל אבידה שיורה צורת הנחתם שזהו היא אבידה ולא הונחה שם לדעת כמו שירה ענין היותם נדחים בשור ושה שהם אובדים:
@578 **אשר תאבד ממנו.** לא שיאבדה לדעת וכן אם היתה במקום שאבודה ממנו ומכל אדם כמו שהיא נאבדת בזוטו של ים ובשלילותו של נהר שאין אני קורא בזה אשר תאבד ממנו כי לא ממנו לבד היא אובדת:
@578 **לא תוכל להתעלם.** כבר בארנו מתי לא יחוייב להטפל בה ואינו קרוי התעלם וכבר נתבאר בפרשת ואלה המשפטים שזאת המצוה נוהגת גם באבידת רשעי ישראל ולפי שתזהיר על אביד' אחיו למדנו שאם מצא חמור והביאו בביתו עושה מלאכה ואוכל ואינו עומד בטל מפני השבת אבדה לבעלים וכן העניין במה שידמה לזה:
@579 **לא תראה את חמור אחיך או שורו נופלים בדרך.** ראוי שיובן זה שהם נופלים מפני המשא שאם היו נופלים בזולת המשא מפני חולשתם אין שם דרך להקימם ואולם הכונה הוא בזה שהיו רובצים תחת משאם כמו שנזכר בפרשת ואלה המשפטים וכבר צוה שם לפרוק משאם עם הבעלים ובזה המקום צוה להקים המשא עליהם עם הבעלים ולזה אמר הקם תקים עמו וכבר בארנו קודם שה מתי יקרא זה העניין התעלם ומתי לא והנה אמר בפרשת ואלה המשפטים כי תפגע ובזה המקום אמר לא תראה ולזה לא יחוייב אלא על ראייה שהיא כפגיעה וזה לפי מה ששערו חכמים ריס שהוא אחד משבעה ומחצה במיל ואם היה רחוק ממנו יותר משה השיעור אינו חייב בזאת המצוה ואמר הקם תקים עמו שאינו חייב לטעון המשא על הבהמה אם לא יעזרו לו הבעלים ואם היה זקן או חולה טוען הוא לבדו ולפי שאין אדם חייב לעשות מלאכת חבירו ולטרוח בה בחנם הוא מבואר שהטוען יקח שכר על הטעינה אך לא על הפריקה כי אינה מעצם המלאכה:
@580 **לא יהיה כלי גבר על אשה.** הזהיר שלא תלבש אשה בגדים מיוחדים לאיש ומה שידמה לזה שיביא לחשוב לאנשים שהיא איש כי זה ממה שיביא לזנות כי היא תלך בין האנשים לזנות עמהם ולא יורגש בזה וכן לא ילבש גבר בגדים ותכשיטין מיוחדים לנשים כי זה יביאהו להתערב עם הנשים ויזנו עמו ולזה אמר כי תועבת יי' אלהיך כל עושה אלה כי זה יביא אל שתמלא הארץ זמה והנה הרחיקה התורה שלא יהיה אפילו כלי אחד מגבר על אשה ואף על פי שהוא לבדו לא יביא לחשוב בה שהוא איש ושלא ילבש איש אפילו לבוש אחד מיוחד לנשים אף על פי שהוא לבדו לא יביא לחשוב בו שהוא אשה ולזה הוא מבואר שאיש שצובע שערו הלבן או שמלקט לבנות מתוך שחורות עובר על זאת האזהרה וכן האשה ששמה כובע האיש בראשה או מה שידמה לזה הנה זה ביאור מה שהוגבלנו באורו בזאת הפרשה:
@581 **כי יקרא קן צפור.** רוצה לומר עוף טהור ואמר כי יקרא שאם היה מזומן כמו אווזים ותרנגולים ומה שידמה להם אינו חייב לשלח ולזה אמר גם כן לפניך בדרך:
@581 **בכל עץ או על הארץ.** הוא מבואר שדבר הכתוב בהווה אך באי זה מקום שימצא הקן נוהג בו זה הדין ואפילו היה על המים:
@581 **אפרוחים או בצים.** הנה לפי הוראת הגדר יקראו אפרוחים החיים וכן הבצים שתרבץ האם עליהם הם ראוים להיות מהם אפרוח ואם לא לא ידבק בהם גדר הביצה ולא אמר אפרוחים או בצים אלא בהווה שהרי אמר קן צפור וכבר יקרא קן צפור אפילו אין בו כי אפ אפרוח אחד או ביצה אחת:
@581 **והאם רובצת על האפרוחים או על הבצים.** מגיד שאם אינה רובצת עליהם מותר לקחת אותה ואם היא רובצת על דבר מבדיל בינה וביניהם והדבר ההוא נוגע בהם כמו שהיה עליהם בגד והיא רובצת על הבגד ההוא ומה שידמה לזה הרי הדבר ספק אם תקרא רובצת עליהם אם לא ומגיד שאם היה הזכר רובץ עליהם לא ינהג בו זה הדין כי אינו אם וכן אם נשחטה האם שם בקן שהרי אינה אם ואינה בת שלוח:
@581 **לא תקח האם על הבנים.** זאת היא כשהיתה האם לך אם לקחת אותו אבל אם של מוקדשין או שהרגה את הנפש אתה רשאי לקחת אותה:
@582 **שלח תשלח את האם.** מגיד שאם לקחה ושלחה פטור ואינו פטור אם לא קיים עשה שבה הוא או שלוחו אבל אם שלחה אחר שלא מדעתו הנה לא קיים עשה שבה והתורה אמרה שלח תשלח ולזה ילקח כשהיה הדבר באון שימש ממנו חיוב מלקו':
@582 **למען ייטב לך והארכת ימים.** מגיד שאלו המצות יישירו האדם אל הטובות הגופיות והנפשיות והנה התועלת בזאת המצוה היא להרחיק לקיחת הקן בזה האופן כי הרבה יהיה שלא יקח אדם תועלת באפרוחים או בבצים ויהיה זה סבה אל שיניח הקן ההוא ותשלם ההויה בו ולא יבלבל הטוב שמשפיע השם יתעלה בהמצאת אלו המינים אם לא לתועלת אשר כוון בהם ואם אמר אומ' שבלקיחת הקן בכללו עם האם תשלם זאת ההויה אמרנו לו כי דרך אלו העופות המדבריים הוא שיבריחו מיד אדם ואם ישימום במאסר יצטערו ותמנע האם מלרבץ על בניה ויאבד הקן עם שאין ראוי שיקח מהם האדם כי אם על דרך הצידה לא שישתמש לצודם ולהשחיתם בכלי בעינו אשר שם השם יתעלה בהם להתמיד הויתם והוא הדמיון ששם באם לרבץ על הבנים כדי שיצאו ממנו אפרוחים והאהבה הדמיונית ששם בה לרבץ על האפרוחים לגדלם ולהשגיח במחייתם ובזה האופן דומה זאת המצוה במה שהזכיר מלבשל גדי בחלב אמו:
@583 **כי תבנה בית חדש.** אחד הבונה או שנתן לו במתנה או קנאו או יורשו כי כונת התורה היא שלא ישים דמים בביתו והנה אם לא ידבק במקום ההו' שם בית כמו שלא היה בו שיעור בית אינו חייב במעקה שנאמר בית וזה אינו בית:
@583 **ועשית מעקה לגגיך.** אפילו היה של שותפין כיון שהוא בית שהוא ראוי לדירה כי התורה דקדקה בזה כדי שלא יפול הנופל ממנו והנה שיעור המעקה הוא בדרך שישמור מהנפילה ושערו חכמים עשרה טפחים ולזה יחוייב גם כן שיהיה חזק שיוכל האדם להסמך בו בבואו שם ולא יפול והנה אמר לגגך למעט הבתים שאינם ראויים לדירה כמו בתי כנסיות ובתי מדרשות והנה ההיקש אחד בכל מה שיהיה בבית שיוכל ליפול הנופל ממנו כמו הבור ומה שידמה לו אמנם אם היה הבית נמוך והיה אפשר שיפול מרשות הרבים אינו חייב לעשות שם מעקה ברשות הרבים שהרי אין הסכנה ברשותו וכבר אמרה התורה כי יפול הנופל ממנו לא בתוכו והנה נמשכה זאת המצוה לקודמת לה שלא ישתמש האדם בבנין הבית שהוא מסודר מהשכל המעשי לשמירת האדם ולהיות לו למחסה ולמסתור אל הפסדתו במה שיהיה בביתו סבה לו הפך מה שכוון בו:
@584 **לא תזרע כרמך כלאים.** רוצה לומר שלא יזרע עם כרמו כלאים ויהיה זה כשיזרע זרעים משני מינים עם חרצן יחד שהוא אז זורע הכרם וזורע עמו כלאים ואז הוא עובר גם כן עם זה משום זורע כלאים זהרי אמרה תורה שדך לא תזרע כלאים והוא מבואר שכבר יקרא זורע הזורע בידו או מהחפה הזרעים שם בעפר:
@584 **פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם.** ידוע שאין הרצון באמרו פן תקדש שיהיה קדש כי לא יהיו הדברים קדש בכמו אלו הסבות ואולם הקדושה הזאת היא שתהיה נבדל מהנאתם כי הקדש יאמר על ההבדל ולזה גם כן יאמר על הטומאה באמרו אל תגע בי כי קדשתיך ולפי שאמר כי זה יהיה סבה שהמלאה רוצה לומר מלאת הכרם תאסור הזרע אשר תזרע ותבואת הכרם למדנו שלא יתחייב על זריעת הכלאים בכרם בזה האופן אם לא היתה שלמות הוית הזרעים באה עם התבואות הכרם וזה לא יהיה אלא בזרעי' שאינם עושים אלא לשלם שנים כמו החרצן וכן הקנבוס ולוף כמו שזכרו רז"ל. ומזה המקם למדנו שאף על פי שלא יזרע כרמו כלאים אך היו נזרעים בו קצת זרעים והשריש זרעם בעת בא תבואת הכרם שהם נאסרים שנאמר הזרע אשר תזרע ותבואת הכרם שבעת שיזריעו זה יעשה זה תבואה ולפי שאמר לא תזרע כרמך וגו' פן תקדש למדנו כי שלו הוא אוסר ולא של חבירו ולפי שאמר כרמך להעיר על היותו כלם אחד למדנו שאם היה הענין בדרך שיהיה נבדל מכרמו כמו שהיתה שם מחיצה או הפסק יביא מהכלל בכרם ההוא אינו מקודש וראוי שתדע שלא תכלול זאת האזהרה מזריעת מיני אילנות בכרם וזה כי האילנות דרכם שינטעו לא שיזרעו שנאמר ונטעתם כל עץ מאכל ולזה לא נכללו אלא במה שאמר ולא תזרע. ולזאת הסבה היה ראוי ג"כ שיתחייב על זריעת מיני זרעי' בכרם ואף על פי שלא יזרע עמהם חרצן כי בכרם ראוי לומר נטיעה אמר מי האיש אשר נטע כרם. כרמים וזתי' אשר לא נטעת. ועוד כי לא יקרא כרם אלא כשיהיו בו גפנים ואין העניין בזה כמו הענין באמרו שדך לא תזרע כלאים וזה כי השדה יקרא שדה ואם אין בו זרעים ואין העניין כן בכרם כי הארץ לא תקרא כרם אם לא בו גפנים אלא כי מפני שאפשר שיפול קצת ספק על זה כי כבר יאמר האומר אני נוטע כרם או אני זורע כרם היה שלא יתחייב מלקות בזולת זה האופן כי לא ילקו על הספק ולפי שאמר לא תזרע אשר תזרע למדנו שאם זרעהו הרוח או אחר שלא מדעתו אינו אוסר שהרי אינו זורע. והנה לא יקרא כרם אלא מה שהיה נטוע מהגפנים בצורת כרם והמעט שיפול בו זה השם לפי הוראת הנדר הם ה' גפני' ולפי שאמר שיאסר זרע אשר תזרע:
@585 **לא תחרוש בשור ובחמור יחדיו.** הנה מפני שלא אמר לא תחרוש בסוס ובחמור אבל לקח שני מיני' מן החי ההולך אחר טמא ואחר טהור למדנו שזה הדין נוהג בכל שני מיני בהמה או היה שיהיה הא' טהור והשני טמא כמו הענין בשור ובחמור ואין ראוי שנבין שלא יהיה זה נוהג אלא בשור וחמור לפי שכבר מצאנו שדקדקה התורה בכלאי' בכל שני מיני בהמה שנאמר בהמתך לא תרביע כלאים וכל ב' מיני זרעים שנאמר שדך לא תזרע כלאים הנה מפני זה ראוי שנבין מזה המקום שדקדקה התורה נשתוף שי מינים במלאכה שאחד מהם מהטהורה והשני מהטמאה ולפי שאמר יחדיו למדנו שאיך שיהיו במלאכה אחת עובר המשתף אותם במלאכה ההיא על זה הלאו והנה לקח החרישה תמורת כל מלאכה שישתתפו בה כי אין בכאן סבה תחוייב שדקדקה התורה בשור וחמור ולא בשאר המינים ושכבר דקדקה התורה בחרישה ולא בשאר המלאכות ולפי שאמר בשור ובחמור למדנו בשור ואדם או בחמור ואדם לא יאסר זה ועוד כי האדם מצד הנהגתו הב"ח במלאכתם הוא משתתף עמהם. ואם היה האדם מוזהר מלחרוש עם השור אם עם החמור היה ראוי שתצוה לא תחרוש בשור או לא תחרוש בחמור:
@586 **לא תלבש שעטנז צמר ופשתים יחדיו.** לפי שאמר בפרשת קדושים תהיו ובגד כלאים שעטנז לא יעלה עליך למדנו שהעליה שהיא דרך לבישה נאסרה לבד אבל מציע הוא תחתיו בגדים של כלאים ולפי שאין דרך לבישה בגדי צמר ואניצי פשתן שאינו בגד למדנו שאין אסור ללבוש אותם יחד והנה בגד כלאים שעטנז הוא לפי מה שיורה עליו הגדר שיעשה בגד צמר ופשתים יחדיו ולפי שהבגד יהיה נעשה מאלו בזולת טויה כמו הלבדים שנקראים בגד הנה אם עשה לבדין מצמר ופשתן הרי הם כלאי בגדים וכן אם ערבם בטויה שהיה קצת נימי הטיווי צמר וקצתם פשתים וכן אם ערב אותם באריגה באופן שישותפו בה עשות הבגד מהם באחד מאלו השלשה אופנים הנה הוא נקרא בגד כלאי' שעטנז ולפי שאמר צמר ופשתי' יחדיו למדנו שאיך שיהיו יחדיו בבגד בדרך שיתכן בהם שיהיו חלק בגד הנה הבגד ההו' כלאי' ולזה אם חבר חוט אחד של צמר בבגד של פשתן באופן שיהיה חבור עמו רוצה לומ' שיתאחד עם הבגד הנה הבגד ההוא כלאים ראיה לדבר שהרי סמך לזה אמרו גדילים תעשה לך שכבר נתבאר שיושם בו פתיל תכלת שהוא של צמר כאלו באר שמפני המצוה הותר זה אך הוא כלאי' לולי המצוה ומזה יתבאר שאין כלאי בגדים נוהגים אלא בצמר ופשתים והנה לא יקרא צמר אלא הבא מן הצאן וידמה שכבר היו נוהגים לעשות זה כומרי עבודה זרה וזה יתבאר במעט עיון ממה שנזכר בזה בפרשת קדושים תהיו. ולפי שאמר צמר ופשתים יחדיו והנה הם יחדיו כשיתחברו להיות בגד אחד למדנו שאף על פי שלא יתחברו זה לזה הנה מפני שהבגד ההוא נכלל בו צמר ופשתים יחדיו הנה הוא אסור ללובשו מכאן שהלובש חלוק של צמר גמלין והיה בו חוט אחד של צמר רחלים בצד זה וחוט אחד פשתן בצד השני הנה הוא עובר משום כלאי' ואפילו השק והקופה מצטרפים את הכלאים רוצה לומר אם חבר קצת בגד צמר לצד אחד מבגד שק ובגד פשתן לצד השני הנה השק יצרפם להיות כלאים וכן הענין בחתיכת קופה כמו שאמרו בספרי ובתשיעי מכלאים אמרו מצטרפין לכלאים והכל עלה לענין אחד:
@587 **גדילים תעשה לך.** למדנו שבמקום מצוה לבד הותר זה ולזה יתבאר שהכהנים שלבשו בגדי כהונה שלא בשעת עבודה חייבים משום כלאים וכן הנושא שני בגדים שיש בהם ציצית בכל אחד מהם בדרך שיהיה כלאים לולי המצוה ההיא לא הותר ללבוש כי אם אחד מהם כי המצוה כבר קיימה בבגד האחד מהם ולפי שסמך זאת המצוה למה שזכר מצמר ומפשתים למדנו שאין מצות ציצית נוהגת אלא בבגדים של צמר או של פשתים ולפי שאמר תעשה לך גו' למדנו שצריך לעשות הגדילים על ארבע כנפות הכסות לא שישימם שם מן העשוי ולא שישימם באמצע הבגד אבל אצל ארבעה כנפות אין עושים לה גדילים והוא ציצית הנזכר במה שקדם ולפי שאמר כסותך אשר תכסה בה למדנו שאם אינו מתכסה בה אינה חייבת בציצית רוצה לומר אם מונחת בכלי ולמדנו עוד שאם אין בכסות שיעור לכסות בה הקטן שאפשר שתנהג בו זאת המצוה אינו חייב בציצית שנאמר אשר תכסה בה רוצה לומר שתוכל לכסות בה ואחשוב שאין ראוי לאדם שילבש יחד שני בגדים שיש בהם ציצית שהרי נאמר אשר תכסה בה ולא בה ובחברתה וראיתם אות ולא אותו וחבירו עם שזה יביא להאמנת השניות בש' יתעלה ובתורה כי זאת המצוה מעידה על הפך זה כמו שביארנו במה שקדם בסוף פרשת שלח לך. ובכלל הנה כמו שיעברו על נשיאת שני תפילין בראש משום בל תוסיף מפני שיש מקום בראש ראוי להניח בו שני תפילין. כן יעברו על נישאת יותר מבגד ציצית אחד משום בל תוסיף שהרי האדם ראוי לעשות כמה בגדי ציצית כי לא הונח לו המקום מוגבל אם יהיה כבגד העליון או התחתון או האמצעי ואולם שאר הדינין אשר בציצית כבר בארנום בסוף פרשת שלח לך הנה זה ביאור מה שהגבלנו בביאור בה מזאת הפרשה:
@588 **כי יקח איש אשה.** רוצה לומר שקנה אותה לו לאשה באחד ממיני הקניה ואחר כך בא אלה ושנא אותה ומפני שנאתו אותה העליל אותה שלא מצאה בתולה והוציא עליה שם רע לפי שידענו שאין האשה נסקלת על פי הבעל שנאמר על פי שנים עדים או שלשה עדים יומת המת ועוד שאף על פי שנודה שיאמן הנה לא תתחייב מפני זה מיתה כי אולי נבעלה קודם שתארס הנה מזה המקום יתבאר לנו שהוצאת שם רע הזה הוא שהביא עדים שזנתה בבית אביה אחר שנתארסה לו ועל זה אמר והוציא עליה שם רע רוצה לומר על ידי עדים שהעידו שזנתה אחר שנתארסה. או יהיה הרצון באמרו ושם לה עלילות דברים על יד עדים כי מאמרם יאמן ולזה יושמו לה הדברים ההם והם אמרם שנבעלה אחר שנתארסה והוצאתו עליה שם רע הוא מה שיאמר מעצמו שלא מצא לה בתולים כי זה אינו כי אם הוצאת דבה ושם רע כי דבריו אינם נאמנים ולזה ישפטו על פיהם הדיינים ויעיד על אמתת זה הפי' מה שאמר אחר זה והנה הוא שם עלילות דברים לאמר לא מצאתי לבך בתולים רוצה לומר כי לאמת שלא מצא לבתו בתולים שם עלילות דברים בפי העדים להעיד שקר ולא אמ' שם לה כי לא הושמו לה עלילות ההן אחר שיש לה עדים שיזימו עדי הבעל ולזה הוצרך לומ' והוציא עליה שם רע:
@589 **ואמר את האשה הזאת לקחתי.** מגיד שאומר כל דבריו לבית דין בפני אשתו שנאמר הזאת:
@589 **ואקרב אליה ולא מצאתי לה בתולים.** מגיד שהביאה שבא עליה הוא במקום בתולים לא שלח כדרכה:
@590 **ולקח אבי הנערה ואמה והוציאו בתולי הנערה וגומ'.** לפי שהוא מבואר שהוא אפשר להם להביא עדים שכאשר בא עליה בעלה היתה בתולה ואף על פי שיביאו השמלה מגוללה בדמים אין זה עדות שהיתה בתולה כי כבר יתכן שהיו הדמים ההם מן הדמים הבאים מן המקור או מזולתם הוא מבואר שהוצאת הבתולים הוא שיביאו עדים להזים העדים הראשונים והנה מה שאמר אל זקני העיר ידוע שצריך שיהיו ראויים לדון דיני נפשות כי על זה הדבר בא הבעל:
@591 **ואמר אבי הנערה.** למדנו מה שאין ראוי לאשה שתדבר בפני בית דין אך ידברו קרוביה או אוהביה בעבורה כדי שלא תתבייש:
@592 **ופרשו השמלה.** רוצה לומר שכבר חוקרין באלו העדיות עד שיעמדו על אמתת הדבר:
@593 **ולקחו זקני העיר ההיא את האיש ויסרו אותו.** רוצה לומר שילקוהו ולזה אמר שיקחו אותו כדי להלקותו:
@594 **וענשו אותו מאה כסף.** הם מאה שקלים של כסף צרוף:
@594 **ונתנו לאבי הנערה.** מגיד שאם היתה נערה זוכה אביה בזה הקנס ואם לא היה לה אב הרי הוא לעצמה כי לא זכתה התורה בו אלא לאב לא ליורשיו והנה האשה בנעוריה ברשות אביה כמו שביארנו בפרשת ראשי המטות ונתבאר גם כן בזאת הפרשה במוציא שם רע ובאונס ומפתה ולפי שכבר דקדק בכל המקומות לזכור בה שם נערה שנאמר ולקח אבי הנערה ואמר אבי הנערה ונתנו לאבי הנעה למדנו שאם היתה נערה בעת הוצאתו שם רע לא ילקה מוציא שם רע ולא יענש בזה הכסף:
@594 **כי הוציא שם רע על בתולת ישראל.** למדנו שאם לא היתה בתולת ישראל הוא שתהיה הורתה ולדתה בקדושה אין זה הדין נוהג במוציא שם רע רוצה לומר ללקות ולשלם קנס וראוי שתדע שצריך שיאמר שמעת שקדש אותה באלו הקדושין אשר עליה בא עליה זנתה שנאמר את האשה הזאת לקחתי ואקרב אליה ולא מצאתי לה בתולים רוצה לומר את האשה הזאת קדשתי ושבעת קרבתי אליה ולא מצאתי לה בתולים כאלו יאמר שבעת שקדשה היו לה בתולים אך אחר זה כשקרב אליה לא היו לה בתולים לפי שכבר נבעלה בנתים ובזה האופן יהיה זה המאמר בעצם ומדרך מה שהוא כמו שהתבאר בשרשים הכוללים ולזה הוא מבואר שאם הביא עדים שבעת שהיתה מאורשת בקדושים אחרים נבעלה לא ינהג במוציא שם רע זה הדין כאלו תאמר שקדשה לו וגרשה וחזר וקדשה והביא עדים שבהיותה מקודשת לו בקדושין הראשונים נבעלה וכן אם קדשה אחיו והיתה זקוקה לו לא ינהג בה מוציא שם רע זה הדין שאינו יכול לומר את האשה הזאת לקחתי וכן אם לא אמר הבעל אלא שלא מצא לה בתולים ולא הביא עדים שזנתה תחתיו אינו נוהג בו זה הדין ממוציא שם רע שנא' ושם לה עלילות דברים מגיד שצריך שיביא הוא העדים וכן אם לא אמר שזנתה תחתיו שנאמר והוציא עליה שם רע אף על פי שבאו עדים מעצמ' והעידו שמשנתארסה זנתה והוא מבואר שכאשר יאמר שזנתה תחתיו צריך שיוציא שם רע עליה שזנתה כדרכה כי לולי זה לא יהיה רושם בדבריו לאמת שלא מצאה בתולה ומזה יתבאר שאם לא היתה בחזקת בתולה כשנתקדשה לו לא ינהג בו זה הדין כי לא יתבאר מדברי העדים שהלכו בתליה בביאה ההיא והוא המכוון בדברי הבעל ולזה היה ענשה בסקילה כמשפט נערה בתולה מאורסה והנה נדקדק בכל זה במוציא שם רע מפני שעניינו הוא חדוש ואין ראוי שנקח ממנו זולת מה שזכרה אותו התורה:
@594 **ולא תהיה לאשה לא יוכל לשלחה כל ימיו.** עשתה התורה לו כמשפט הראוי לו כי אולי מפני שהית' בעודה שם לה עלילות דברים לתכלית שלא תשאר עמו כלל ורצתה התורה שתהיה לו לאשה כל ימיו והזהירה אותו שלא ישלחנה בגט לפיכך אם שלחה צריך להחזירה ואם היה כהן שאינו יכול להחזירה הנה כבר עבר על לא תעשה בשלחו אותה וראוי שתדע שאם לא היתה ראויה לו אלא בעברה כמו שזנתה תחתיו או שכבר נתברר שהיא אסורה לו לא יחוייב לו לקיימה כי התורה לא התחכמה בזה אלא כנגד רוע תכונתו שמפני שנאתו אותה היה רוצה שלא תשאר עמו ורצתה התורה להכניע רוע רצונו:
@595 **אם אמת היה הדבר הזה וגומ'.** רוצה לומר שכבר נמצאו דברי הבעל אמתיים ולא נמצאו עדים שיזימו עדי הבעל או שהביא הבעל עדים להזים את זוממי עדיו:
@596 **והוציאו הנערה אל פתח אביה וסקלוה.** עשתה התורה זה לבייש הוריה על שלא תקנוה מן המוכר מה שראוי. והוא מבואר שאם אין לה פתח בית אביה הנה היא נסקלת אל שער העיר ההיא כמו שביאר אחר זה במשפט הנערה בתולה מאורסה שאם ישכב איש אותה בעיר יהיו נסקלין על שער העיר למדנו מזה שאם לא היו בעיר אך בבית אביה סוקלין אותה על פתח בית אביה וראוי שתדע שאף על פי שלא היתה נערה בעת הוצאת זה השם הרע כיון שהיתה נערה בתולה מאורסה בעת שזנתה הרי היא נסקלת וכבר החמירה התורה על הנערה בתולה מאורסה יותר ממה שהחמירה בשאר המאורסות או בנשואות הבעולות בעל לפי שזה הענין הורה על הפלגת רוע תכונתה שתכף שגדלה והחלה להולד המותר הזרעי בה נטתה אל הזנות עם היותה בלתי יודעת עדיין טעם משכב האנשים ולא חששה לרוב תאותה אל הצער הקורה לה בהשחתת בתוליה ואל הבשת שיתכן שיקרה לה מזה כי העדר בתוליה יעידו על זנותה הנה זה ממה שיורה כי אחר שישלם להיות גובר המותר הזרעי בה תגדל תאותה יותר ותמלא הארץ זמה עם מה שהרגישה בהנאת משכב האנשים והיותה בטוחה אז מהצער והיות נקייה אז מהבשת שהיה ראוי שישיגנה על זה בהיותה בתולה:
@597 **כי ימצא איש.** רוצה לומר בעדים:
@597 **שוכב עם אשה בעולת בעל.** ידענו כי שוכב יקרא אפילו שלא כדרכה שנאמ' ואת זכר לא תשכב משכבי אשה והנה אמרו בעולת בעל יכלול אפילו בא עליה ארוסה בבית אביה:
@597 **ומתו גם שניהם.** מגיש שכאשר היה הענין כן ימותו שניהם. אך אם היה הוא איש והיא קטנה או היא אשה והוא קטן לא ימות כי אם הגדול מהם שהוא בן עונשים:
@598 **כי יהיה נערה בתולה מאורשה לאיש.** למדנו מזה שאין קדושי קטן כלום ולזה אמר מאורשה לאיש והנה לא ינהג בה זה הדין אלא בעת היותה נערה ושתהיה בחזקת בתולה כי לא חייבה התורה שיעידו העדי שהיא בתולה אז כשנבעלה כי זה לא יתכן:
@598 **ומצאה איש בעיר ושכב עמה.** אפילו שלא כדרכה כי הוא יקרא גם כן משכב כמו שביארנו והנה יעידו עדים על זה המשכב כי בזולת זה לא ימותו כמו שקדם:
@599 **והוציאו את שניהם אל שער העיר ההיא.** הנה דקדקה התורה בכל המקומות שתהיה ההמתה בשער שנמצאו בו כדי שיוסרו כל העם אשר נמצאת בהם זאת הרעה כי בודאי היה זה לרוע מנהג בני העיר המוכיחים והנוכחים:
@599 **את הנערה על דבר אשר לא צעקה בעיר.** אמר זה כי זה מעיד שלא היתה אנוסה כ"א לא נתרצת בזה היתה יכולה לצעוק וימלטוה האנשים ממנו והוא מבואר שהתורה דברה בזה בהוה כי בעיר יהיה על צד הפתוי ובשדה יהיה על צד האונס אך ראוי שתדע שבכל מקום שהתבאר שצעקה ואין מושיע לה הרי היא פטורה כי לא חטאה בזה ובכל מקום שתעשה זה ברצון הלא היא נסקלת:
@600 **והחזיק בה האיש.** ר"ל שלקחה בחזקה ובאונס:
@601 **ולנערה לא תעשה דבר.** למדנו מזה שהאנוס פטור מכלום:
@601 **כי כאשר יקום איש על רעהו ורצחו נפש כן הדבר הזה.** המשיל זה הענין לרוצח לפי שנתבאר היותה אנוסה על זה ראוי שנשפוט כי הדבר קשה לה כאלו בא להרגה מרוב הזנות שיש בזה הענין אצל הנערה הבתולה המאורשה לסבות שזכרנו במה שקדם עם שכל הנשים הטובות והראויות זר בעיניהם ענין הזנות עד שיבחרו המות על הזנות:
@602 **צעקה נערה המאורשה ואן מושיע לה.** למדנו מזה שראוי לרואים שיושיעוה מיד מאנסה וההושעה תהיה בשימלטוה מזה הפועל בצד שיוכלו עליו ולזה אם לא יוכל הרואה לאסרו בדרך שלא יוכל על זה הנה יש לו רשות להכותו או לחבול בו בדרך שתשלם לה ההצלה ממנו ואפילו בנפשו של רודף אחריה אם לא יוכל להצילה בצד אחר ולפי שכבר הקיש לזה הקם על רעהו ורצחו נפש למדנו שהרודף אחר חבירו להרגו יש רשות לרואים להושיעו ואפילו בנפשו של רודף ולזה אמרה התורה לא תעמוד על דם רעך ואינו דוקא דבר שיש מן הסכנה המגיע מנרדף ליד דם כי אפילו ממה שיגיע לו מן הפגם והבושת ואפילו אין בו היזק מן הממון כמו זה הענין המגיע בנאנסת זאת כי כלנו חייבים בכבוד האחד על חבירו:
@603 **כי ימצא איש נערה בתלה אשר לא אורשה וגו'.** רוצה לומר שאנס אותה והיא נערה בחזקת בתולה:
@603 **ושכב עמה ונמצאו.** רוצה לומר שיהיו שם עדים וכבר יתבאר במה שקדם שהנבעלת בעיר סתמה שהיא מפותה עד שיתברר האונס והנבעלת שדה סתמה שהיא אנוסה ולא יצטרך התראה באונס ומפתה כמו שהאוכל משל חבירו משלם ואינו צריך התראה ולפי שדקדקה התורה שתהיה התולה ולזה הסכימ' שיתן לאביה כסף במוהר הבתולות כמו שנזכר בפרשת ואלה המשפטים וזכר בזה המקום שזה הכסף הוא חמשים סלעים של כסף למדנו שלא ינהג זה הדין אלא כשבא עליה כדרכה מהמקום שהיא בתולה כי אין בכאן עונש לה שנוכל לומר שבעבורו דקדקה התורה שתהיה בתולה ולזה גם כן הסכימה התורה שיתן זה הכסף מפני מוהר הבתולות הראוי להם מצד בתוליהן:
@604 **ולו תהיה לאשה.** זו היא מצות עשה ולפי שרצה זה האונס לקחת אותה שלא לשם אישות כי אולי לא יתרצה בזה מצד מעלתו או מצד פחיתותה עמדה התורה כנגד מחשבתו והכריחה אותו שתהיה לו לאשה תחת אשר ענה אותה ונהנה משכיבתה וחשב לקחת זה ממנה בזולת חק שיהיה לו עליה רצתה התורה שיהיה מה שאכל מבשרו ולזה הוא מבואר שאם לא היתה מותרת לו לא יחוייב לו ללקחה ולפי שזה הכסף יתן מפני הנאת בתוליה ונתבאר בחובל בחבירו שהוא משלם ה' דברים כמו שביארנו בפרש' ואלה המשפטים הנה הוא מבואר שהוא ישלם עוד בושת ונזק וצער והוא מבואר גם כן שישלם גם כן שבת ורפוי אם קרה שיצטרך לה זה מפני צער השכיבה ואולם במפותה אינו צער שהרי נתרצתה והוא מבואר שאם אין לנערה האנוסה אב שהקנס הוא לעצמה לא ליורשי האב כי לא זכתה התורה בו אלא לאב:
@604 **לא יוכל לשלחה כל ימיו.** רוצה לומר מפני בחירתו אמנם התורה תכריחהו על זה הנה לא יחוייב לשלח כי התורה לא עמדה בה אלא כנגד בחירתו כמו שנתבאר מדברינו ואם שלחה יחוייב שיחזירנה או עבר על לא תעשה ולזה אם יכול לקיים העשה אחר זה הנה כבר עבר על לא תעשה והוא מבואר שאם לא רצתה להנשא:
@605 **לא יקח איש את אשת אביו.** הנה סמך זה לענין האנוסה להודיע שאשת אביו הוא שאסורה לו לא אנוסת אביו ואף על פי שנתבאר בכאן שזה האונס קושר אותו אל שיקחה לו לאשה הנה מפני שאינה אשתו היא מותרת להנשא לבנו וכאלו העיר בזה שאם לא רצתה בו מפני היותו זקן והיתה מתרצה בבנו היה ראוי לאב להשתדל לפייסה בזה הענין כי בזה תשקוט קצת תלונתה וזהו אמרו לא יקח איש את אשת אביו כאלו יאמר אשת אביו הוא שלא יוכל לקד' אבל מקדש הוא אנוסת אביו והנה לא תמצא באלו העריות שאמר לא יקח כי אם בזה המקום:
@605 **ולא יגלה כנף אביו.** רוצה לומר סתר אביו והוא כאלו אמר ולא יגלה ערות אביו:
@606 **לא יבא פצוע וגו'.** רוצה לומר פצוע ודכא ואמר אחר זה וכרות שפכה למדנו שאלו הפצעים והכריתה והדיבות הוא בכלי ההולדה ולפי ששפיעת הזרע תהיה מהגיד אם בשבילי הזרע אם בהבצים למדנו שבאלו הכלי' אם היתה הפציעה או הדיבה או הכריתה באי זה שיהיה מהם היה זה הנה יקרא באלו השמות רוצה לומר פצוע שפה או דכה שפכה או כרות שפכה והוא מבואר שאלו התארים לא יהיו אלא למי שנעשה לו זה לא למי שנברא בזה החסרון כי לא יתכן שיקרא כרות שפכה אלא למי שנכר' השפכה לא למי שלא כרתוהו לו דבר אלא שנברא בזה חסרון והנה הזהיר בזה המקום שלא יבוא אחד מהם בקהל השם רוצה לומר לקחת אשה מישראל:
@607 **לא יבא ממזר בקהל ה'.** ידוע עי הולד שיהיה לאיש מאשתו הוא בנו והוא נקרא בן ואמנם מי שיש לו ממי שיאן לו אישות בה בשום פנים הוא הנקרא ממזר ולזה הוא מבואר מצד הוראת הגדר והנה הזהיר מלבא ממזר בקהל השם. רוצה לומר שלא ישא ממזר בת ישראל ולא תנשא ממזרת לישראל וענין הביאה בקהל הוא בעילה באישות ולזה אם קדש ולא בעל אינם עוברים על זאת האזהרה:
@607 **גם דור עשירי לא יבא לו בקהל ה'.** כבר נתבאר אחר זה שאין הרצון בזה הלשון שמהדור העשירי ואילך יהיה מותר לבא בקהל זהרי אמר כן בעמוני ומואבי וזכר שם שהו אסור לבא בקהל עד עולם ולזה תהיה הכונה בזה המקום שעד עולם לא יבא ממזר בקהל יי' ואם אמר אומר כי מזה המקום יתבאר שאינו אסור מעשירי ואילך כיון שלא אמר עד עולם אמרנו כי התורה לא תאמר דברים סותרים זה את זה כל שכן שתאמר אותם עם זה ללא ענין ולזה הוא מבואר שאם היתה הכונה באמרה גם דור העשירי שמדור עשירי ואילך יבא בקהל הנה זה יהיה סותר מה שאמר אחריו עד עולם ועוד שלא היה צריך לזכור זה הסותר אבל יספיק כשיאמר לא יבוא עמוני ומואבי בקהל השם עד עולם:
@608 **לא יבא עמוני ומואבי בקהל השם.** ר"ל אחר שנתגיירו כי קודם זה לא היה צריך להזהיר בו וידענו שהמואבית מותרת מיד כשנתגיירה שהרי מצאנו בבועז שהיה משופטי ישראל ונשא רות המואביה ומצאנו גם כן בשלמה המלך שנשא נעמה העמונית ולזה הוא מובא' שהרצון בזה להזהיר בזכרים לבד מעמון ומואב שלא יבאו בקהל יי' ויעיד על זה מה שאמר על דבר אשר לא קדמו אתכם בלחם ובמי' בדרך בצאתכם ממצרים וזה כי דרך האנשים לעשות הפועל לא הנשים ולזה לא נענשו הנקבות:
@609 **ואשר שכר עלים וגומ'.** אמר זה בעבור בלק מלך מואב:
@611 **לא תדרוש שלומם וטובתם כל ימיך לעולם.** מגיד שאף על פי שאנחנו מחוייבים לקרוא לשלום לאשר נלחם עמו הנה לא נעשה כן לעמון ומואב בהיותינו נלחמי' עמהם באי זה עת שיהיה וזה הוא ענין זאת האזהרה:
@612 **לא תתעב אדומי כי אחיך הוא.** הזהיר שלא נתעב אדומי ומצרי מלבא בקהל כמו הענין בעמוני ומואבי אבל כשנתגיירו הדור השלישי יהיה מורת לבא בקהל יי' והם בני בניהם:
@614 **כי תצא מחנה על אויביך וגו'.** אמר כשתצא להלחם על אויביך ושמת העיר במצור בדרך שבני ישראל יעמדו במחנה לצוד על אויביהם צרך שישמרו מכל דבר רע כדי שלא יסור מהם השגחת השם יתעלה:
@615 **כי יהיה בך איש אשר לא יהיה טהור מקרה לילה.** הנה סמך זה למה שאמר ונשמרת מכל דבר להזהיר שלא יהרהר בעברה ביום ויבא לידי טומאה בלילה וצוה שיצא מן המחנה ההוא לפי שהמחנה ההוא הוא קדוש להיות בו שיכנה וידמה שזה יהיה לבד כשיהיה שם אדון אלהים כאמרו כי ה' אלהיך מתהלך בקרב מחניך ומזה המקום למדנו שבעל קרי יוצא חוץ מהמקדש שהוא מחנה שכינה והוא אך ממחנה ישראל לא יצא כי אם המצורע כמו שקדם מאמרו בדד ישב מחוץ למחנה מושב וצוהו לטבול ולהעריב שמשו כמשפט מי שתצא ממנו שכבת זרע:
@617 **ויד תהיה לך מחוץ למחנה וגומ'.** צוה שיתקנו מקום מחוץ למחנה שיפנו שם לכבוד השם יתעלה שהוא מתהלך בקרב המחנה. עם שבזה ישמור המחנה מהעפוש ההוא ולזה גם כן צוהו שתהיה לו יתד אצל כלי מלחמתו שיחפור בו הארץ כשיפנה ויכסה בעפר צואתו ויהיה זה סבה שלא ירגישו בעפוש ההוא במחנה הקדוש ההוא ויהיה כבוד לשם יתעלה ומזה המקום למדנו שאין ראוי להתפלל ולומר דבר קדושה במקום שיש בו צואה אם לא היתה מכוסה:
@619 **להצילך ולתת אויבך לפניך.** התכלי הראשון הוא להצילך ואם זכית שתדבק בך מן ההשגחה שיתן אויבך לפניך יעשה זה גם כן:
@619 **ולא יראה בך ערות דבר ושב מאחריך.** מגיד שאם יראה השם יתעלה בהם שום חטא ודבר מוגנה תסור שכינתו מהם ולמדנו מזה לפי דרכנו שהערוה לא יספיק בה הכסוי אם היה שתראה והיה זה כן כי ענינה יותר מגונה כי ראותה מביא להרהר בעברה:
@620 **לא תדגיר עבד אל אדוניו.** הנה זאת האזהרה בעבד כנעני שברח מחוצה לארץ לארץ להמלט מאדוניו הישראלי והראיה על זה כי העד האמור סתם בתורה הוא עבד כנעני והוא מה שאמר בהם מהם תקנו עבד ואמה. והתנחלתם אותם לבניכם אחריכם:
@621 **עמך ישב בקרבך.** רוצה לומר בארץ בקרבך לא שיהיה לו עיר לעצמו:
@621 **במקום אשר יבחר באחד שעריך.** אך לא במקום הבחירה:
@621 **בטוב לו לא תוננו.** רוצה לומר ביותר נאות לו לצאת ממנו פרנסתו ואף על פי שאיננו יותר טוב מצד עצמו:
@621 **לא תוננו.** זאת אונאת דברים והנה זה העבד יהיה עתה גר צדק כי העבדים נכנסו ברוב המצות לא יחסר בהם אלא שיצאו משעבוד האדון ואז הם גרי צדק כי לולי שעבוד האדון היו מחוייבים בכל זה מצות אך מפני שעבודו הם פטורים ממצות עשה שהזמן גרמא:
@622 **לא תהיה קדשה בבנות ישראל.** רוצה לומר פנוי מוכנת לתשמיש לכל אדם:
@622 **ולא יהיה קדש מבני ישראל.** רוצה לומ' שלא יתפרץ האיש לבעול הפנויות והנה קרא אותו קדש כי העברה תמשכהו לזה וכו' והוא קדש לזה הפעול מרוב המשכו לזה הגנות אם נסתבך בו מעט כי לאי יחשב בזה לחטא מפני היותו פנוי והיא פנויה:
@623 **לא תביא אתנן זונה ומחיר כלב בית יי' אלהיך לכל נדר.** מגיד שעושה אותם נדבה והיר הם כמו בהמה טמאה אשר יקריבו ממנה קרבן להש' שיעריכנה ויכי' בדמיה אך אם נדר עולה או שלמים והביא בהמה או עוף שהם אתנן זונה ומחיר כלב הרי הוא עובר על זאת האזהרה מזה המקום למדנו שאין אסור להקריב למזבח אלא הם עצמם לא חליפיהם ולזה אם היה האתנן או המחיר דמי' וקנה מהם בהמה עוף למזבח אינו עובר על זאת האזהרה והנה הזונה תקרא מי שיש אסור בבעילתה כמו גרושה לכהן הדיוט ואלמנה לכהן גדול ומה שידמה לזה ואולם האחרת שאין אסור בבעילתה תקרא קדשה. ולזה תמצא על הרוב שם הזונה באשת איש ובת איש כהן כי תחל לזנות הנה אמרו אל תחלל בתך להזנותה. ידמה שהוא מזאת הכוונה שאם הי' אשת איש אין ביד האב להזנות' גם לא הוצרך לזאת האזהרה ובכלל הנה הזונה יהיה הרצן בה השטה וחנטיה מדרכי התורה מדבר הבעליה ולזה תהיה הזונה נבעלת בעילה אסורה מן התורה ואולם אתנן זונה הוא מה שיתנה האיש לתת לה בזנות ההוא והוא אתנן לה אחר זנותה כאלו תאמר שאמר לה אם תבעלי לי או לפלוני אתן לך טלה אחר ונבעלה לו ונתן לה טלה אחד תכף הרי זה אתנן זונה ואם לא נתנו לה אלא לאחר זמן מה כיון שלא יחד לה הטלה שנתן לה באתננה אין בו דין אתנן זונה כי לא היה זה אלא פרעון חוב שהיה חייב לה תכף אחר הבעילה והרי נשתנה האתנן וכן אם הקדים לתת לה האתנן קודם הבעילה והקדישה אותו למזבח והקריבתו וקודם בעילה אינו אתנן זונה כי עדיין לא נהיה הזנות. וכבר נתבאר בכלאי הכרם שאין אדם אוסר דבר שאינו שלו ולזה אם נתן לה באתננה מה שאינו שלו אינו נפסל עוף קדשים להיותו מוכן אל העופפות והבעלים מטפלין בהבאתו עד העזרה הרי הוא כמו שלו לפסל והנה מחיר כלב הוא שיחליף כלב בבהמה או עוף אחד או הרבה והנה נפסלו אלו למזבח כי הם תעבת השם יתעלה כמו שזכר והנה אחשוב שאמר זה בכלב לפי שהוא שטוף מאד במשכב זכור ולזה מנע מחירו וחשבו כמו אתנן זונה ומזה המקום נלמד שהאתנן שנתן על המשכב זכור הוא פסול למזבח עם שהוא יותר מתועב מאתנן הזונה וראוי שנלמד מזה שהרובע והנרבע פסולין למזבח כי גם המחיר כלב פסלה התורה מפני היותו רובע ונרבע והנה בזאת האזהרה תועלת אחר כללי אך אינו מיוחד כמו הראשון והוא כי הזונה תהיה על הרוב אשת איש והיא ראויה להיות לבעלה לבד וברית הנשים לבעליהן חזק מאד וגם הכלב להיותו חזק האהבה הדמיונית לבעליו היה ראוי שיהיה לבעליו לבד ובריתו עם בעליו חזק מאד והנה הדברים אשר היו כלי להתנכר דבר ממשלה למי שהוא לו אין ראוי שנשימהו כלי להכיר הממשלה לשם יתעלה הנה זהו ביאור מה שצריך לבאר בזאת הפרשה שהגבלנו ביאורה:
@624 **לא תשיך לאחיך נשך כסף אבל כל דבר אשר ישך.** ידוע שהנשך יהיה מהמלוה לא אל הלוה וזה מבואר מצד הוראת הגדר אך אם יתן לשליח סך מה בשכר מה שיטרח לבקש לו מי שילונו הנה זה נכנס בגדר השכירות לא בגדר הנשך וכן אם הלוה אדם לחבירו והזמינו לפני בית דין לזמן מה ונתן לו סך מה להרויח זמן ההזמנה ההיא לזמן יותר ארוך אין זה גם כן נכנס בגדר הנשך כי איננו אז מלוה לו ממון ואינם גם כן נותן לו זה בשביל הארכת פרעון הממון אבל מצד שהיום ההוא רחוק לו מללכת שם לפני בית דין ולזה יבקש ממנו יום יהיה בו יותר פנוי. והנה אמר נשך כסף נשך אוכל לפי שכבר אמר במה שקדם אך כספך לא תתן לו בנשך ובמרבית לא תתן אכלך ולמד בכאן שאם נתן כספו בנשך כסף או בנשך אוכל וכן הענין באכל עובר בלא תעשה:
@624 **נשך כל דבר אשר ישך.** רוצה לומר אף על פי שלא היה נשך כסף או נשך אכל מכל מקום כיון שהתנה לתת לו בשכר ההלואה אי זה דבר שיהיה שוה כסף בצד מהצדדים עובר בלא תעשה ולפי שהיה אמרו לא תשיך אפשר שיהיה אזהרה ללוה שלא יסבב לאחיו שיהיה נושך וכבר באה האזהרה למלוה כמו שאמר במה שקדם. את כספך לא תתן לו בנשך. הנה ראוי שנבין שבזה המקום באה האזהרה ללוה עם שהוא מבואר שהלוה גם כן יש לו מבוא בזה החטא כי לא יוכל המלוה להלוות ברבית אם לא יסכים הלוה בנתינת הרבית והנה לזה תהיה אזהרה ללוה ולמלוה ולפי שאמר לאחיך למדנו שאינו מצוה להלוות ברבית לגר תושב או שלא ללות ממנו ברבית:
@625 **לנכרי תשיך.** היא מצות עשה מפני שהוא עובד עבודה זרה חייבה אותנו התורה להלוות לו ברבית כשירצה ללות ממנו לגרום לו מהנזק מה שאפשר שלא תהיה בו נטיה מהיושר ולזה צוה גם כן במה שקדם לנגוש הנכרי וראוי שיתבאר שאין הכונה בזה לנכרי תוכל להשיך שאם היה הענין כן היה זה המאמר מותר וזה כי כבר התבאר מאמרו לא תשיך לאחיך שאפי' לגר תושב מותר להשיך וכל שכן לנכרי שהרי מצאנו בנבלה שהקדים הכתוב הנתינה לגר תושב על המכירה לנכרי:
@625 **למען יברכך ה' אלהיך בכל משלח ידך על הארץ.** אין ראוי שיובן מזה שלא תנהג זאת האזהרה כי אם בארץ ישראל כי הוא מבואר כי אין לו התלות בארץ וכבר נזכר במה שקדם בזולת זכירת ארץ ואמנם הכונה בזה הוא שכבר ימשך לה מהטוב בקיום זאת המצוה שיברכך ה' אלהיך בכל משלח ידיך על הארץ ההיא הנבחרת ואולם בזולתה לא ימשך לה כל זה רוצה לומר שתתברך בכל משלח ידך כי אין שאר הארצות מוכנות לברכה כמו זאת הארץ הנבחרת שהיא מוכנת מאד אל שידבק בה ההשגחה האלהית כמו שקדם:
@626 **כי תדור נדר לה' אלהיך לא תאחר לשלמו.** ראוי שתדע שאין הבדל בזה בין נדר לנדבה והדברים קל וחומר אם בנדר שמה שנדר אינו בעין עובר בכל תאחר כל שכן כנדבה שהיא בעין עם שכבר צריך בה למהר להביאה למקם הבחירה כדי לשמרו שלא יהיה מועל בה אם להיותו נהנה ממנה עם שיעבור עם זה בה בגזה ובעבודה ועוד שהרי מצאנו אחר זה במצות עשה שבזה שפרט ביחד הנדר והנדבה וקרא הנדבה נדר כמו שאמר כאשר נדרת לה' אלהיך נדבה אשר דברת בפיך וזה לאות שבה הנדר הנזכר בכאן כלל הנדבה והנה הנדר שהוא להשם הוא עולה או שלמים או נסכים או ערבים או הקדש לבדק הבית או הדמין כי אלו כולם נקראי' נדר לפי מה שנתבאר בפרשת פינחס ובפרש' אם בחקותי וכבר הזהיר במה שקדם הצואה להביא אלו הנדרים למקום הבחירה לרגל שפגע בו תחלה. ובזה המקום הזהיר שלא נאחר לשלמו וראוי שנחקור מתי יעבור הוא על זאת האזהרה ונאמר שכבר ביאר בפרשת פינחס שהנדר אפשר שישלמהו בכל אחד ממועדי השנה שנאמר אלה תעשו להה' במועדיכם לבד מנדריכם ונדבותיכם מגיד שהדברים אחרים יתכן שישלמם באי זה שיהיה משלשה המועדים הנזכרים שם על סדרם ולזה למדנו מזה שלא יעבור בכל תאחר עד שיעברו על הנדר שלשה המועדי' על סדרם והם חג המצות וחג השבועות וחג הסוכות והנה נכלל במה שאמר לא תאחר לשלמו כל מה שנמשך להשלמת הנדר רוצה לומר כי גם בו יעבור בכל תאחר והמשל אם התנדב בהמה ונפל בה מום קודם שיביאה למקום הבחירה ופראה באחרת הרי הוא מוזהר שלא יעברו על האחרת שהפריש שלשה רגלים ומפני שאמר ובאת שמה והבאתם שמה וגומ' למדנו שכל מה שנדר יחוייב לשלמו כשימצא למי ולזה יתחייב בנדרי העניים תכף אם יש עניים אצלו אמר בספר מלכים על שלמה רק בבמות היא מזבח וגומ' וזה לאות שלא נאסרו הבמות במוחלט עד שנבנה בית המקדש:
@626 **כי דרוש ידרשו ה' אלהיך מעמך ודיה בך חטא.** וזה שאם לא תשלם נדריך להשם הנה זה יורה על חלשת אמונתך בו ומעוט יראתך ממנו ולזה יגיעך השם יתעלה עונש על זה:
@627 **וכי תחדל לנדור לא יהיה בך חטא.** הורה בזה שאין חפץ השם יתעלה באלו הנדרים מצד עצמותם ולזה לא יענישך אם תחדל לנדור ואולם יענישך אם נדרת לו ולא תשלם לסבה שזכרנו:
@628 **מוצא שפתיך תשמור ועשית.** צוה בזה המקום לשמור דבר הנדרים כלם כדי לעשות מה שנדר ליי' להוציאו מפיו אבל דברים שבלב אינם כלום ולזה אמר מוצא שפתיך והנה מוצא השפתים הוא לפי שמנהג הטבעי מה שכיון בלב ולזה צריך שיסכימו בדבר הנדר פיו ולבו והנה ביאר בכאן שאלו הדברים יכלול בהם הנדבה גם כן אמר נדבה אשר דברת בפיך לפי שכבר שכבר יחשב שהנדבה יספיק בה כונת הלב לבד כי הדבה מייחסת ללב כאמרו אשר ידבנו לבו וכל נדיב לב ולזה ביאר שצריך בזה גם כן הוצאה בפה מה שבלה:
@629 **כי תבוא בכרם רעך.** ראוי שתדע שאין הרצון בזה שיבא שם בלא רשות בעלים. כי אין ראוי שיעשה עם שהתורה תדבר במה שדרכו להיות כן כמו שהתבאר בשרשים הכוללים ולזה הוא מבואר שהרצון בזה כשיבא שם לעשות מלאכת הבעלים כמו הענין בשכיר וכבר אמר כמו זה בזאת הפרשה גם בבהמות שנא' לא תחסום שור בדישו ולפי שאמר רעך למדנו שאם היה משל הקדש אין השכיר אוכל:
@629 **ואכלת ענבים כנפשך שבעך וגו'.** מגיד שבמה שהוא עושה הוא אוכל בכר ענבים בקמה שבולים לא במה שאינו עושה ואכלת ענבים ולא שימוץ אותם ולא שיתנם לאחר ואפילו לבניו ולאשתו שנא' ואכלת ואמר "כ ואל כליך לא תתן להזהירו שלא יתן אל כליו ולא יתן לאחרים כי הכל הולך אל מקום אחד והוא מבואר שאוכל מהם די שבעו אך לא אכילה נסה שנאמ' כנפשך שבעך ולפי ששנה המאמ' בה בכרם ובקמה שהם גדולי קרקע ודברים שלא נגמרה מלאכתן למדנו שאין הפועל אוכל בשעת מלאכה אלא מגדולי קרקע ודברי' שלא נגמר' מלאכתן ואין ראוי שנשפוט שהתורה לא התירה לשכיר זה בתלוש שהרי גם לבהמה הזהירה התורה מלחסום פיה מלאכול כמה שתעשה בתלוש כאמרו לא תחסום שור בדישו ומזה נלמד ג"כ ביאור אלו הדברים הסתומים הנזכרים פה והוא שבשעת מלאכה הוא שהתיר זה ולזה יחוייב שיהיה עושה מלאכת בעלים קודם שיאכל והוא החלק הראשון שתחלקהו המלאכה ההיא בזה כאלו תאמר שיבצור וימלא הסל מהענבים קודם שיאכל מהענבים:
@629 **ואל כליך לא תתן.** ר"ל אך לכליו של בעל הבית תן וזה עוד ממה שיורה שכראוי לתת לכלי הכתוב מדבר ובאמרו וחרמש לא תניף הורה גם כן שכראוי להניף עליו חרמש הכתוב מדבר וראוי שתדע שלא ינהג זה הדין כי אם במי שהיו מעשיהם גמר מלאכה כמו הענין כחריש וקצי' אבל המנכש אינו אוכל כי אין מעשיו גמר מלאכ' ואמ' וחרמש לא תניף להעיד שלא הותר לו לבטל ממלאכת הבעלים בהיותן על קמתו לצורך אכילתו השבלים וירים מפני זה החרמש כי בעת שהוא קוצר אינו מניף החרמש אבל הוא משפילו וכורע עצמו לקצור ומניף החרמש לימינו לשמאלו לקצור או לשמאלו לימינו אם היה אטר יד ימינו אבל אינו מניף אותו אלא בשעה שהוא בטל מלאכתו וזה מבואר מענין החרמש וזה ממה שיחייב שיהיה הפועל זה על דרך שלא תבוטל מלאכת הבעלים ואמר וקטפת מלילות בידך לפי שמאלו השבולי' לא יאכל האדם שעור רב והנה לא הותר לו לצלות ולקלותן כדי שיהיו יותר נאותים לאכילה כי לא התירה התורה אכילתם אלא כמו שהם שנאמר ואכלת ענבים ולזה תהיה אכילת המלילות כדמיון אכילת הענבים כמו שהם:
@631 **כי יקח איש אשה ובעלה.** לפי שידענו שאין מתנאי המוציא אשתו בגט שיהיה בועל אשתו קודם זה שהרי אמר אחר זה והיתה לאיש אחד ושאה האיש האחרון וכתב לה ספר כריתות ואף על פי שלא בעל אותה הנה הרצון בזה כי יקח איש אשה או שבעלה והנה הקיחה הוא קנין ודרכו שיהיה בכסף או בשטר ולמד בזה המקום שכבר תהיה גם כן אשו בבעילה לבד כמו שמצאנו ביבמה ואמר שאיך שיהיה קניינו אותה מאלו הקנינים יוכל לגרשה:
@631 **והיה אם לא תמצא חן בעיניו כי מצא בה ערות דבר.** אמר זה לפי הנהוג לא יגרש אדם אשתו אלא לסבה גדולה ולזה אמר כי ימצא בה ערות דבר אמנם על דרך האמת כבר ביארה התורה שאפילו לא מצא בה ערות דבר יש לו רשות לגרשה אם שנאה כאמרו ושנאה האיש האחרון וכתב לה ספר כריתות ולזה מבואר שאיך שיהיה שלא מצאה חן בעיניו יש לו רשות לגרשה ולפי שזה הוא התנאי בגט למדנו שאין האיש מגרש אשתו אלא לרצונו כי התורה יחסה כל זה הפועל לרצון האיש:
@631 **וכתב לה.** שצריך שיכתוב הוא או שלוחו והנה לא יפול שם כתב כי אם בכתיבה שתהיה בדברים שרשומם עומד וצרך שיהיה נכתב לשמה לתכלית שתתגרש בו ולזה אמ' לה ספר כריתת ולפי שלא אמר בספר כמו שמצאנו בשאר המקומות כמו כתוב זאת זכרון בספר וכתב את האלות והאלה הכהן בספר למדנו מזה שבאי זה דבר שיכתוב זה הענין תגרש איך שיהיה בדרך שיוכל לתתו ברשותה שנאמ' ונתן בידה ולא יהיה מחוסר מעשה אחר הכתיבה אלא נתינה שנאמר וכתב לה ספר כריתות ונתן בידה והנה ספר כריתות הוא שיהיו נכתבים בו דברים יורו על כריתות האישות שביניהם וסלוקו כי לזה התכלית יתן בידה הספר ההוא ולזה צריך שלא תשאר נקשרת לבעלה בשום דבר מהדברים כל ימי חייב כי יכרות זה הספר בכללות מה שביניהם מהקשר מעת מהעתים ולפי שאמר ושלחה מביתו למדנו שצריך שתהיה כונת הספר ההוא שהוא משלח אותה ומסלק אותה מקניניו ולא שישלח אל עצמו ממנה כי אינו קנין לה אך היא קנינו:
@631 **ונתן בידה ושלחה מבית.** למדנו מזה שצריך שיתננו לה או הוא או שלוחו שנאמר ונתן בידה לא שתקחהו מעצמה ולא שיתנהו לה אחר שאינו שלוחו ולמדנו מאמרו בידה שאם לא הגיע הגט ברשותה או ברשות שלוחה אינה מתגרשת ואמ' אחר זה ושלחה מביתו להורו' שצריך שתהיה נתינתו בידה זה הגט לתכלית שישלחנה מביתו ולפי שאלו הדברים הכרחיים בגט כמו ששנה המאמר אחר זה ושנאה האיש האחרון וכתב לה ספר כריתת ונתן בידה ושלחה מביתו למדנו שצריך שיהיו שם שני עדים כשרים שכבר נשלמו כל אלו התנאים בזה הגט שהרי אמרה תרה על פי שנים עדים או שלשה עדים יקום דבר. ורואי שיתבאר מזה שבשטר מתגרשת לא בכסף:
@634 **לא יוכל בעלה הראשון לשוב לקחתה עוד אחרי אשר הוטמאה.** ידוע כי אין התנאי בה אסרה על בעלה הראשן שתהיה נבעלת לבעל השני כי לא התנה בזה תחלה אלא שתהיה לאיש אחר והיא לו תכף שנתקדשה ועוד שהרי נתבאר מדברי ירמיהו שאין התנאי בזה שתהיה נבעלתה לשני שנאמר לאמור הן ישלח איש את אשתו ויצאה מאתו והלכה והיתה לאיש אח' הישוב אליה עוד הלא חנוף תחנף הארץ ההיא ואת זנית רעים רבים וגו'. ולזה תהיה הכונה בזה שלא יוכל לשוב לקחתה אחר שיהיה אפשר לה שתבעל לבעלה השני והסבה בזה שאם היה מותר להחזירה אחר כן היה זה סבה אל שתמלא הארץ זמה כי מי שיחשוק אשת רעהו ישתדל עמו שיגרשהו ויקחה הוא ואת' עשותו חפצו ממנה יגרשנה וישיבנה לבעלה הראשון כדי שיתרצה בה כי אשו לא עשתה זמה בזה הפועל ולזה לא ירחיקה מפני זה ולזה התבאר שאם הפקירה עצמה אחר שגרשה מזולת קדושין לא נאסרה עלו כי אם ליראה שיגרשה לתכלית שתנשא עם האיש ההוא אוחר ישוב לקחתה בעלה הראשון כי זה מרוחק מאד אצל האנשים רוצה לומר לקיחת אשה מפקרת עצמה ומזה המקו' למדנו שהאשה שנטמאה בהיותה עם בעלה היא אסורה לו שהרי הוטמאה וכבר ביארנו זה עוד בפרש' נשא ממה שאמר ונקתה ונזרעה זרע:
@635 **כי יקח איש אשה חדשה.** למדנו שאם היתה אשתו וגרשה וחזר ונשאה לא ינהג בו זה הדין והרצון באמרו כי יקח נשואין שהרי אמר מי האיש אשר ארש אשה ולא לקחה ועתה מבואר מה יהיה דינו אם לקחה:
@635 **לא יצא בצבא.** רוצה לומר למלחמת הרשות כמו שביארנו באמרו מי האיש אשר ארש אשה:
@635 **ולא יעבור עליו לכל דבר.** רוצה לומר לא לצרכי הגדוד ולא לצרכי העיר אין מעמיסי' עליו שום מעמס:
@635 **נקי יחיה לביתו שנה אחת.** רוצה לומר שנה אחת מיום שנשאה והנה מפני שהתורה השותה דין לבונה הבית ולא חנכו ונוטע כרם ולא חללו ומארש אשה ולא לקחה ושנה גם כן בהשואת השלשה דברים האלו בדברי הקללות הנזכרות בפרשת והיה כי תבא למדנו שהכונה בית וחנכו והנוטע כרם ולא חללו יהיה גם כן נקי לביתו שנה אחת כי התור' ביארה כי לא ישלם הפיוס בזה הפועל לבעליו כי אם לשנה אחת ואמנם זכר זה בענין האשה בזה המקו' לפי שראוי לאדם שיהיה עם אשו בהתחלה באופן שיתפייס לבה בו ותאהבהו ויהיה זה סבה אל שלא תשנא עליו אח' כך ולא יצטרך לו לגרשה ולזאת הסבה צותה התור' שישמח עם אשתו אשר לקח בתתו לה חקה מעונתה:
@636 **לא יחבול ריחים ורכב וגו'.** הנה הריחים הוא אבן התחתון מכלי הטחינה ורכב הוא הכלי העליון והזהירה התורה שלא יקחם לאדם משכון על הלואתו ולא בשעה הלואה ולא אחר הלואה איך שיהיה שיהיו לו למשכון וביארה התורה טעם זאת האזהרה לפי שהעושה זה הוא חושב לקחת למשכון זה הכלי והוא לוקח למשכון נפש בעליו כי הוא משמש בעצמות להכין המזון להם אשר הוא שב להיו' חלק מבעל נפש ולפי הסבה בזה היא היותר משמשין להכנת מזון למדנו כי כל מה שישמש להכין המזון שאנחנו מוזהרים מלקיחתו למשכון ואפילו אם היו שם שני כלים משמשי' יחד לשמוש אחד חייב על זה בפני עצמו ועל זה בפני עצמו ולזה הוצרכה התורה להזכיר בפרט זאת האזהרה רחיים ורכב ללמדנו שהוא חייב על זה בפני עצמו ועל זה בפני עצמו כיון שיש בהם שמוש מה להכנת אכל נפש:
@637 **כי ימצא איש גונב נפש מאחיו מבני ישראל.** למדנו מאמרו גונב נפש שאפילו גונב קטן יתחייב עליו ובאמרו מאחיו מבני ישראל למדנו שאם לא היה מאחיו מבני ישראל כמו הענין בעבד כנעני ובגר תושב לא ינהג בו זה הדין ואף על פי שהיה העבד חציו בן חורין כמו העניין בשפחה חרופה כי אינו עדין מאחינו ולמדנו מאמרו גונב נפש מאחיו שאינו חייב עד שיגנבנו ויוציאנו מרשות אחיו פרט למי שלא יצא מרשות אחיו וחביריו שהוא עומד עמהם כמו האב שגנב את בנו והרב את תלמידו:
@637 **והתעמר בו ומכרו ומת הגנב ההוא.** ראוי שתדע שאין הכונה בזה שישתעבד בו או שימכרנו שהרי דקדק בפרשת ואלה המשפטים בשני אלו הדברים גם כן ואמר וגונב איש ומכרו ונמצא בידו קדם מכירתו אתו ועניין היותו בידו הוא שישתעבד בו אי זה שעבוד שיהיה שיורה שהו' תחת ידו כאלו הוא עבדו ובהיות הענין כן הנה לא יתחייב אם לא מכרו ונשתעבד בו קודם זה:
@637 **ומת הגנב ההוא.** רוצה לומר כישלמו בו כל אלו התנאים לא בזולת זה:
@638 **השמר בנגע צרעת.** הזהיר להשמר בענין נגע הצרעת לנהוג בו לפי מה שיתן הדין באופן שישב מחוץ למחנ' המצורע המוחלט ולא יעלי' איש את נגעיו מהראותם אל הכהן. ולא יחתוך סמני הצרעת כדי שיטהרנו הכהן כי זה ממה שיביא הפסד רב לאנשים ובעל הנגע לא ירגיש בענין הזיקו להם עד שיסורו מפני זה תועלו' רבות ימשכו ממה שסדרה התורה בנגע הצרעת כמו שביארנו בפרשת מצורע:
@639 **זכור את אשר עשה יי' אלהיך למרים.** אמר זה להעיר שאין ראוי לנטות ימין ושמאל ממה שצותה התורה מענין המצורע הלא תראה כי גם מרים עם גודל מעלתה ומעלת אחיה לא הסכים השם יתעלה להעביר לה מדיני צרעת דבר אבל הוכרחה להיותה נסגרת שבעת ימים עד שנתרפאה ואף על פי שנמשך מהסגרה עכוב ישראל כמו שאמר והעם לא נסע עד האסף מרים וסמך דבר מרים לענין הנגעים לבאר שהנגעים על לשון הרע וזולתו מן החטאים ולזה סמך דבר הנגעים לענין גונב נפש:
@640 **כי תשה ברעך משאת מאומה לא תבא אל ביתו לעבוט עבוטו.** הזהיר בזה המקום מי שיש לו מלוה על חבירו שלא יכנס לביתו למשכנו ולפי שזה לא יתכן אם לא על ידי שליח בית דין כי אין כח באדם למשכן חבירו על חובו אלא אם היה זה ברצונו ואולם לא יוכל לקחת משכון ממנו בעל כרחו אבל ראוי שיקראהו לפני בית דין והם יצוו לפרעו או למשכן הלוה הנה תכלול האזהרה הזאת גם כן שליח בית דין שאף על פי שיש לו כח להכריח הלוה לפרוע המלוה או ליתן לו המשכון הנה לא רצתה התורה שיכנס בביתו של לוה לבחור אי זה משכון יקח אבל יכריח הלוה להביא לו משכון מבחוץ לפי החוב ויקחהו שליח בית דין מידו אף על פי שלא מרצונו שאם היה הענין כן הנה לא יהיה כח לבית דין להכריח הלוה לפרוע המלוה והנה הדברים קל וחומר אם כשיתן הלוה ברצונו המשכון למלוה לא רצתה התורה שיכנס המלוה ברשותו לקחת משכונו כדי שלא יבוש המלוה אם לא יתן לו היותר טוב והיותר ראוי להפרע ממנו בקלות כל שכן כשימשכן אותו שליח בית דין בעל כרחו שראוי להשמר מלהכנס בבית הלוה למשכנו כי אין לאל יד הלוה לברוח ממה שירצה אותו שליח בית דין לקחת משכון:
@642 **ואם איש עני הוא לא תשכב בעבוטו.** הנה זה יהיה כשיהיה כסות לילה ואין הכונה בזה שלא ישתמש בעבוטו כי זה ממה שאין צריך להזהיר בו ואפילו אם היה עשיר ואמנם הרצן בזה שלא ישכב ועבוטו אצלו אבל יחוייב לו להביאו לו וביאר שבבא השמש משיבו לו את המשכון כדי שישכב בשמלתו והנה למדנו מזה שהוא הדין לכסות יום להחזירו לו ביום כדי שישתמש בו ביום ואולם דברה התורה בהווה לפי שהממשכן את חבירו ימשכנהו ביום על הרוב ואז לא יוכן לעני לתת לו כי אם כסות לילה והנה למדנו מזה שאם היה לעני במה ישכב זה המשכון לא יחוייב המלוה להשיבו לו ולפי שזה הדין הוא בזה המקום במי שלקחו משכון ממנו שלא בשעת הלואה למדנו שאם לוה על המשכון בתחילת ההלוואה אינו חייב להחזיר:
@643 **ולך תהיה צדקה.** רוצה לומר שהשם יחשבה לך לצדקה אם תשיב לעני כסות יום ביום וכסות לילה בלילה:
@644 **לא תעשוק שכיר עני ואביון.** ידוע כי התורה דברה בזה בהווה וזה כי אף על פי שהיה עשיר אין ראוי לעשוק שכירותו ואולם זכר עני ואביון כי החטא בו יותר עצום כאמרו וקרא עליך אל יי' והיה בך חטא:
@644 **מאחיך או מגרך.** זה גר צדק אשר בארצך בשעריך. רוצה לומר אשר הוא בארצך ובשעריך לבקש שכירותו ממך ולמדנו מזה שאם לא בקש לו שכירותו אינו עובר על איחור שכירותו:
@645 **ביומו תתן שכרו ולא תבא עליו השמש.** הנה במקום אחר אמ' לא תלין פעולת שכיר אתך עד בקר למדנו ששכיר יום גובה כל הילה שנאמ' עד הבקר ואחר זה עובר עליו ושכיר לילה גובה כל היום שנאמר ביומו תתן שכרו ולא הבא עליו השמש ולמדנו מזה שאם היה שכיר לזמן רב ונשלמה פעולת שכירתו ביום גובה כל הלילה שנאמר ולא תלין פעולת שכיר עד השלימו כל פעולתו ששכרו עליה אינו עובר ואז יש לו כל הלילה אם השלים ביום ואם השלים בלילה יש לו כל היום עד בא השמש:
@645 **כי עני הוא ואליו הוא נושא את נפשו.** רוצה לומר כי אל השכירות ההוא נושא נפשו כי ממנו הוא מתפרנס ומחיה עצמו ואם לא תפרעהו בזמנו יקרא עליך אל יי' ויביא עליך עונש חזק על אחורך לעני מזונותיך כי משכירותו הוא מתפרנס וזה שזכר בסוף אינו כי אם בעני כי העשיר אינו מחיר כל לגבות שכירותו ולא תחסר פרנסתו מפני האחור הזה:
@646 **לא יומתו אבות על בנים ובנים לא יומתו על אבות.** בארו רבותינו זה המאמר בעדות הקרובים כדי להשמר מההכפל. שהרי אמר אחר זה איש בחטאו יומתו והנראה מפשט הכתוב שהוא בא להזהיר הדיינים שלא ישפטו למות האבות בעבור חטא הבנים ולא הבנים בעבור חטא אביהם אבל איש בחטאו לבד ואולם דבר עדות הקרובים יתבאר ממה שנזכר ברוצח מענין גואל הדם שמצד רתיחתו ירצה עכ"פ להמית הרוצח אף על פי שאין לו חטא מות ולזה הוא כמו בעל דבר וכמו שבעבור אהבת קרוביו והיותו עצמו ובשר שלו יפותה להמית מי שאין לו חטא כן יפותה להעיד לו עדות אף על פי שאינו אמת ולפי שהגואל לא יעבור שני בשני כמו שבארה התורה בפרשת בהר סיני. או דודו או בן דודו יגאלנו. והנה בן דודו שני בשני הנה אינו נפסל מהקרובים לעדות כי אם שני בשני ועוד שכמו שפסלה התורה הרשע והחמסן לעדות לפי שאנחנו רואים אותם נוטים מדרכי התורה ולזה נחשוד אותם שאולי לסבת ממון או אהבה לא יחוש להעיר שקר כל שכן שנחשוד הקרובים כי כמעט שטבע הקורבה ימשכם לעזור לקרובים להשים מבקשו כי טבע האד' הוא להיות בלתי מתעלם מבשרו והנה תעמוד על זה בחוש מהריב המתחדש בין אנשים אפילו בממון שתמצא הקרובים נקשרים לאגודה אחת לעזור לקרובים אם במשפט אם בכח והנה כמו שהדיינין ראוי שיהיו בלתי נוטים בטבעם לאהבת החלק האחד יותר מהאחר כמו שביארנו בפרשת יתרו כן ראוי שימשך ענין בעדים כי על פיהם יצא מה שיצא מהמשפט כי אם אין עדים אין דיינין והנה הוצרכה התורה לצוות שלא יומתו אבות על בנים לפי שכבר זכרה כי השם יתעלה פוקד עון אבות על בנים ואולי יחשבו הדיינין לעשות דבר ראוי אם ילכו בדרכי השם יתעלה וכן שכן שבארה התורה בעיר הנידחת שימותו בה בנים על אבות ולזה הזהירה התורה מזה בזה המקום וכאלו אמר שאף על פי שזכר בכאן שאם יקרא העני אל יי' יהיה בשוכר עונש מהשם יתעלה הנה אין ראוי לשפטים שילמדו מזה ויענשו הכובש שכר שכיר שלא לפרוע בזמנו כמו שהשם יתעלה עונש אותו:
@647 **לא תטה משפט גר יתום.** רוצה לומר גר צדק ויתום והזהיר עליה מלהנות משפטם כי לשפלותם אולי לא יזהר הדיין מלהטות משפטם כי אין בשער עזרתם ולזה הוסיף זאת האזהרה לדין עליהם:
@647 **ולא תחבול בגד אלמנה.** בין עניה בין עשירה ואפילו ברצונה ואפילו בשעת הלואה אם לקח המשכון ממנה חייב להחזירו לה והנה חמלה עליה לשפלותה ולדאבונה עם שזה יביא לפעמי' לידי זמה במה שימשך מזה מחייוב השבת משכונה של יו ביום ושל לילה בלילה:
@648 **וזכרת כי עבד היית במצרים ויפרך ה' אלהיך משם.** ולזה אתה עובד הש"י ותחוייב לעשות מקניניך מה שירצה כי אתה וקניניך לו:
@649 **כי תקצו' קצירך בשדה.** כי תקצו' כולל אם קצרה הוא או שלוחו אבל אם קצרוה לסטים או קרסמוה נמלים ומה שידמה לזה לא ינהג בקציר הדין הנזכר. קצירך לא קציר הקדש ולא קציר גוים ולא קציר הפקר:
@649 **בשדך.** פרט לשפזרה הרוח את עמריו בשדה אחר כי אע"פ ששכחם שם אינו שכחה:
@649 **ושכחת עומר בשדה.** ושכחת עומר ולא גדיש והנה דרך העומר להיות עושה פחות מסאתים לפי הוראת הגדר ולזה אם יהיו בו סאתים אינו שכחה:
@649 **ושכחת עומר בשדה.** ושכחת עומר ולא גדיש והנה דרך העומר להיות עושה פחות מסאתים לפי הוראת הגדר ולזה אם יהיו בו סאתים אינו שכחה:
@649 **ושכחת עומר בשדה.** ראוי שיהיה נשכח בשדה אבל אם נשכח בעיר כיון שאינו נשכח בשדה אינו שכחה וענין השכחה הזאת הוא במה שדרכו לשכח כמו שאין שם בשדה מי שרואה אותו בעת שאתה שוכחו. אבל אם יש שם רואה אין ראוי לשכחו כי מדרך האנשים שיזכירו קצתם לקצת מה שהם רואים. ורואי שתדע ששכחת הפועלים שם כמו שכחת בעל הבית כי הם שם במקומו וגם על ידיה' נעשה הלקט שהוא לעניים כמו שקדם ולפי שאמר עומר ידענו שאם לא היו האגודות באופן שיקראו עומר לקטנותם הנה אין השכחה נוהגת בהם ולפי שאמר כי תקצור קצירך בשדה אצל זכירתו שכחת העומר למדנו מזה שני דברים האחד שיש שכחה ג"כ בקצירת הקמה וכבר נתבאר זה עוד ממה שאמרה התורה אחר זה לא תפאר אחריך לא תעולל אחריך והנה מה שעזב אחרי הואר שכחה למדנו שהשכחה נוהגת במחובר ולזה תהיה נוהגת בקמה ויוגבל שעורה מהשיעור המוגבל לעומר והשני שהוא שיהיה בעת הקצירה קצירך ואז יהיה נוהג בו דין השכחה אמנם אם בשעת קצירה אינו קצירך בדרך שאינו אז מחוייב בפיאה הנה לא ינהג בו אחר זה דין השכחה והוא מבואר שהשכוח בשדה אע"פ שזכר אותו אחר זה הוא לעניים שהרי הזהירה התורה ואמרה לא תשוב לקחתו והנה ענין השכחה הוא שישכח העומר או הקמה במקום שלא תכריחהו מלאכתו לשוב אצלו להיותו כמו גמר מלאכה אצל המקום ההוא ואפילו היה טמון שם או שקצר בלילה או אסף העמרים בלילה ולפי שאמר כי תקצור למדנו שבמה שראוי לקצור לפי הנהוג ינהג דין השכחה לא במה שאינו ראוי לקצור כמו התבואה שקצרה קודם שנגמרה להאכילה לבהמה:
@649 **לא תשוב לקחתו.** הזהיר מלקיחתו אחר זה אע"פ שזכרו:
@649 **לגר וליתום ולאלמנה יהיה.** מגיד שאם לקחו יחויב לתתו לעניי' והנה זה הגר הנזכר פה הוא גר צדק והיתום והאלמנה וכן ראוי לשאר עניים אך דברה תורה בהווה והראייה על זה שהרי אמר בפרש' בהר סיני תמורת זה המאמר לעני ולגר תעזוב אותם למדנו עוד מאמרו לגר וליתום ולאלמנה יהיה שראוי לעשו' בדרך שתהיה יד העניים שוה בזה ולזה לא ימנע קצת העניים מלהכנס שמה ויניח קצתם להכנס שם ומה שדומה לזה ממה שיסבב אם לא יכנסו העניי' שם או שיכנסו קצתם זולת קצת ולמדנו מאמרו לגר ליתום ולאלמנה יהיה בזמן ההוא מוכן לחיו' לגר ליתום ולאלמנה ר"ל עניי' אז הוא מוזהר שלא לשוב לקחתו לא בזמן שאינו מוכן להיות להם והוא בשעת סור העניים מלחזר אחר אלו העניים הדברים בשדות כי התורה אמרה לגר ליתום לאלמנה יהיה שאע"פ שעבר ולקחו בעל הבית חייב להחזירה לעניים בגורן או בקמה או בפת:
@649 **למען יברכך יי' אלהיך בכל משלח ידיך.** מגיד שבשכר זה יברכך השם יתע' להוסיף על תבואתך כי כמו שתחנן העניים יחנך השם יתעלה. למען תתן להם. כי הוא נותן לחם לכל בשר וישימך כלי לנתינת המזון לעניים אשר ישפיעהו הש' ית' עליהם מצד ההשגחה הכולל:
@650 **כי תחבוט זיתיך לא תפאר אחריך.** ר"ל שמה שישכח מפארות הזית לחבוט ויתיחס אינו חוזר אחר זה כשזכר אותו לעיין בפארות לחבטם והנה אם היה קצת הזית שכוח נשער אם יש בו סאתים אינו שכחה כי כמו זה השעור אין מדרכו שישכח ואם היה שדה לאילן שיהיו בו אילנות רבות ושכח אילן מהם שלא חבט פירותיו הרי זו שכחה כיון שעבר ממנו אם לא היה אצלו מה שראוי שיביאהו לזכרו מצד עוצם המלאכה ואם שכח ג' אילנות במקום אחד אין זו שכחה כי כמו זה לא יורגל לשכחו בעת לקיטת הפירות מהאילנות וכן אם היה שם אילן אחד חשוב אשר לחשיבותו נקרא בשם מיוחד ושכחו כלו אינו שכחה כי חשיבותו יביאהו לזכרו ולזה אינו ראוי שישכח:
@650 **לגר ליתום ולאלמנה יהיה.** כבר פירשנוהו במה שקדם ואולם מה שראוי להוסיף בו ביאור בזה המקום הוא שאם היה האילן גבוה שלא יוכלו העניים לעלות עליו אם לא בסכנה או יעלו שם קצתם זולת קצת ראוי לבעל הבית לעשות באופן שתהיה השכחה לגר ליתום ולאלמנה:
@651 **כי תבצור כרמך לא תעולל אחריך.** הזהיר בזה המקום שמה ששכח מבצירת הכרם אחריו לא ישוב לקחתו ולזה אמר אחריך ואמר ולא תעולל דבר בהוה כי יונקות הגפנים הם היותר ראויות להשכח כמו שאמר באילן לא תפאר לפי שהפארה היא יותר ראויה שתשכח מהאילן כלו וכבר זכרנו דין השכחה באילנות וכן דינה בכרם:
@652 **וזכרת כי עבד היית בארץ מצרי'.** ר"ל ולזה אתה וקנייניך לשם יתעלה ותחוייב לעשות מקנייניך מה שירצה כי הוא הוציאך מהעבדות ההוא:
@653 **כי יהיה ריב בין אנשים וגומ'.** חייבה התורה טוען ונטען לבא לפני בית דין והם ישפטו אותם בעל כרחם:
@653 **והצדיקו או הצדיק והרשיעו את הרשע.** מגיד שהוא מחוייב שיהיו השופטים בתכונת שיצדיקו את הצדיק והרשיעו את הרשע בדרך שלא יטו המשפט ואמר אחר זה והיה אם כן הכות הרשע להגיד שכמו שהם מוזהרים להרשיע הרשע בממון שלא יטו הדין כן הוזהרו להרשיע הרשע למכות כי אולי יחשבו שאינם עושי' בזה עול לשום אדם ויעלימו מפני זה עיניהם מלענשו במלקות והנה הרשע יקרא מי שעבר על מצו' לא תעשה שאין בהם מיתת בית דין ולא עונש ממון כי לא מצאנו במצות עשה לבלי מקיים עונש בידי אדם ולזה סמך לזה אמרו לא תחסום שור בדישו שהוא מצות עשה שלא הוזכר עונש וכמו שזאת העבירה יש בו מעשה כן כל לא תעשה שיש בו מעשה וכן מצאנו שדקדקה התורה שיהיה מעשה במה שחייבה על שגגתו חטאת וכן יתבאר שמה שנתקו התורה לעשה לא יהיה בו מלקות כי לא עבר על לא תעשה עדין עד שיבטל העשה שבו ולזה אינו רשע עדין:
@654 **והפילו השופט והכהו לפניו כדי רשעתו במספר.** מגיד שאינו מוכה אלא כשהוא נופל ולפי שאמר והכהו למדנו שההכאה צריך שיהיה בו בעצמו לא בבגדיו ולזה צריך שיגלה המקום שהכהו בו ולפי שאין ראוי שיתבייש לפני בית דין לגלות עדותו הנה ראוי שיגלו לבו וסביבו יכו עם שההכאה ההיא היא בכלו כי הלב הוא השורש וההתחלה לכללות הגוף וצריך שיכו אותו לפני השופט שיהיו עיניו בהכאות ההם כדי שלא יעבור המלקה אותו החק שהגביל עם שהוא יראה אם לא יוכל לסבול המוכה כל ההכאות ההם ויצוה למנוע מלהכותו כל המספר שהגביל וראוי שתדע שראוי שיהיה אומר מספר מהמכות שיוסר בו ולא יתכן שימות בו כי התורה לא חייבה באלה העבירות ואן ראוי לדיין להוסיף עונש על מה שחייבה התורה כל שכן בכמו זה האופן ואמר כדי רשעתו לבאר שאינו מכה אותו יחד על רשעיות אבל על רשע אחד ולמדנו מזה שמרבים מספר המכות או ממעטין כדי שיהיה במספר ההוא מהמכות כדי ליסרו לפי חולשתו או לפי חוזקו אך שלא יוסיף המספר המוגבל אחר זה וכבר ביארנו כדי רשעתו בזה האופן לפי שאין ראוי שיובן כי לפי גודל החטא ירבה מספר המכות כי כמו שכל חייבי מיתה מה יהיה עונשן שוה אף על פי שבקצתם החטא יותר עצום מקצת כן ראוי שנבין הענין בזה המקום עם שזה האומר לא יתכן שישלם לאחד מהשופטים כי זה דבר בתכלית מההעלם ר"ל היחס שבין קצת החטאים לקצת והיא ראוי אם כן שתבאר התורה מספר המכות באזהרה ואזהרה כמו שביארה מיני המיתות ואמר במספר לבאר שהוא מחוייב שיהיה שם מי שימנה מספר המכות כדי שלא יוסיפו עליהם וזה ג"כ דבר ראוי שימנ' על ידי שופט כמו שדקדקה התורה שיהיה רואה צורת ההכאות וזה לא ישלם בשלמות כי אם על ידי ב' שופטים אחד מעיין בהכאות ואח' מונה ולפי שאין ב"ד שקול הנה יהיו שם ג' שופטים:
@655 **ארבעים יכנו לא יוסיף.** ידוע שאין כונת התורה לצוות שיכנו ארבעים לא פחות שהרי אמרה קודם זה והכהו לפניו כדי רשעתו מגיד שזאת ההכאה תהיה מתחלפת המספר באנשים ואם היה החיוב להכות ארבעים לא פחות וכבר חייב ג"כ שלא יוסיף על זה המספר הנה לא יהיה מספר ההכאות מתחלף לפי די מוסר הרשע וזה הפך מה שזכרה התורה מזה ולזה ראוי שנבין שאמרו מ' יכנו הרצון בו עד מ' יכנו וכמוהו רבי' בתורה ובדברי נביאים כמו שזכר במה שקדם ולפי שאמרו עד מ' יכנו יסבול שיהיה עד בכלל או לא יהיה עד בכלל הנה יחוייב מפני הספק שלא נכהו יותר מל"ט הכאות ואם אמר אומר כי הכונה אפשר שתהיה בזה שהוא מחוייב שיכנו מ' לכל הפחות אך יוסיפו הדיינים להכותו כדי רשעתו ויהיה אמרו לא יוסיף שב אל המספר שאמדוהו והדיינים. התשובה הנה לפי זה הדעת לא היה ראוי שיאמר פן יוסיף להכותו על אלה כי לא זכר המספר ההוא ישתכן שיאמ' אלה ועוד שאם הודינו שהדבר ספק הנה מפני הספק ראוי שנשפט בו להקל למוכה כדי שנשאר מלהטיל עליו מהעונש יותר למה שהגבילה אותו התורה. לא יוסיף ר"ל שלא יוסי' המכה להכותו על האומד שאמדוהו ב"ד:
@655 **פן יוסיף להכותו על אלה מכה רבה ונקלה אחיך לעיניך.** ר"ל אם היה אפשר למכה להוסיף על האומד ההוא הנה לפעמים יקרה שיוסיף להכות על אלה הל"ט שהגבלנו בתורה שהם מכה ורבה ויקרה מזה למוכה מצד החולשה שיתקלקל ברעי או בשתן לפני הדיין ויקבל בזה קלון חזק וכדי שלא יבא זה לקלון השגיחה התורה אל שלא יהיה מספ' ההכאות כי אם עד מ' ויהיה כח לדיינים לגרוע מזה המספר מצד חולשתו כדי שלא יקרה לו כמו זה הבשת ומזה המקום למדנו שאחר שאמדוהו ב"ד למספר מה מהמכות אין ראוי להוסיף עליהם ולמדנו עוד שצריך שיזהרו הדיינים שלא יהיה נקלה ולזה אם אמדוהו למספר מה והתחילו להכותו וראו שאם ישלימו להכותו המספר ההוא ימות או יבא לידי קלון הרי הם מחוייבים לאמדו שנית לפי מה שראוי מצד מה שנתבאר להם מחלשתו ולמדנו מזה עוד שאם התחילו להכותו ונקלה בזה האופן אין מכין אותו יותר ואפילו נקלה מהפחד פטור ואין מכין אותו כי התורה ברחה מהקלותו כי הוא יותר קשה אצל התורה מהמכות ולפי שאמר כדי רשעתו למדנו שאחר שלקה הוסרה רשעתו ואינו רשע אחר שקבל המוסר ולזה ג"כ קראו אחיך אחר לקותו שנאמר ונקלה אחיך והנה מפני שזכרה התורה שכבר יתכן שיוכה עד המ' מכות מזולת שיהיה נקלה למדנו שאין ראוי שתהיינה המכות האלה מכות רב או אבן או אגרוף ולא מכת שבט כי כן יתכן המות כמו שזכרה התורה בפרשת ואלה המשפטים בעבד כנעני ולזה יחוייב שתהיה ההכאה שיהיה ראוי בה לקיחת המוסר. ולזה יהיה בה סכנה בכמו המספר הזה כמו שימצא העניין בזה ברצועת עור ולפי שההכאות יחוייב שתהיינה בגופו אצל לבו שתהיה ההכאה כוללת כל גופו הנה יחולק זה המספר השלוש מלפניו על לבו בין שדיו ושני השלישים אצל שתי כתפיו מאחוריו כי הם אצל הלב כי הלב מוטה מהשמאל אל הימין וזה כלו להקל הלוקה כי אם תהיינה כל הכאות לפניו אצל לבו אולי ימות ולזה ידמה ג"כ שזכרה התורה מספר מכות ראויות להשתלש. ומזה המקום למדנ שהמכה את חבירו עובר בלא תעשה שהרי אף במי שיש רשות להכותו הזהירה התורה מלהכותו יותר ממה שהוגבל כ"ש בשאר האנשים:
@656 **לא תחסום שור בדישו.** הזהיר בכאן מחסימת פה הבהמה מלאכול בשעת מלאכתה ממה היא עושה מגדולי קרקע בין בתלוש בין במחובר. והנה לא זכרה התורה שור ולא דישה אלא שדברה התורה בהווה והנה הכונה להרחיק מדות האכזריות ולזה צותה התורה שלא למנוע עושה המלאכה מאכילת מה שהוא עושה בו ולזה אם חסמה קודם שתהיה חסומה בעת הדישה או חסמה בעת הדישה עובר על זאת האזהרה ואיך שמנעה מלאכל ממה שהיא עושה אם בהכאה או בפחד הכאה אם בקול הרי זה עובר על זאת האזהרה:
@657 **כי ישבו אחים יחדיו ומת אחד מהם ובן אין לו.** ראוי שתדע שאלו האחים יחוייב שיהיו אחים מן האב כי לא ישאיר שם האח מי שהוא אחיו מן האם כי המשפח' מיוחסת אל האב לבד כמו שנתבאר במקומות רבים מהתורה ועוד כי דרך האחים מן האב להיות יושבים יחדיו לא האחים מן האם כי כל אחד יושב עם משפחת בית אביו ולמדנו מאמרו כי ישבו אחים יחדיו שאם לא היתה להם ישיבה יחדיו כמו שמת הראשון קודם שנולד השני הנה לא ינהג בהם זה הדין:
@657 **ובן אין לו.** ר"ל בשום מקום ולזה צריך לחקור אף על פי שאין לו בן מזאת אם יש לו בן מאשה אחרת שהוא הדין ראוי שיקרא בנו להוציא את שנא משפחה ונכרי שאינו בן אלא בנה ולזה הוא מבואר שאם היה לו בן בשום מקום לא ינהג בו זה הדין ואחד בן ואחת בת כי התורה לא השגיחה אלא שלא ימחה שמו מישראל ומי שיש לו בת לא ימחה שמו בישראל והנה נאמן האב לומר זה בני לפטור את אשו מן היבום ומן החליצה והנה ראוי שתמתין היבמה שלש חדשים כדי שיודע אם בן אין לו ממנה שאז יוכר אם היא מעוברתם:
@657 **לא תהיה אשת המת החוצה לאיש זר.** הזהיר שלא יקח אשת המת איש אחר זולתי יבמה שהוא אחי בעלה מן האב כמו שקדם ופי שאמ' אשת המת והיא תקרא אשתו מן הארוסין כאמרו בנער' המאורסה על דבר אשר ענה את אשת רעהו ולפי שאמר אחר זה יבמה יבא עליה ויבמה למדנו שאין הזר עובר בלא תעשה עד שיבא עליה כי הרצון בזה יבמה יבא עליה לאיש זר ולזה יהיה הרצון באמרו לא תהיה אשת המת החוצה לאיש זר לא תהיה לו לאשה באופן שיבעלוה אך יבמה לבד יבא עליה יבמה יבא עליה ולקחת לו לאשה ויבמה. לפי שאמר יבא עליה ולקחה לו לאשה למדנו שכיון שבא עליה איך שיהיה קנאה לו לאשה. אך לפי שאין הביאה נעשית אלא כשיכוין לביאה הנה ראוי שתהיה כונתו לביאה ואף על פי שלא תהיה כונתו לבא עליה והנה זה הפועל נקרא ייבום:
@658 **והיה הבכור אשר תלד יקום על שם אחיו המת.** רוצה לומר הראשון שתלד יוקם בו זרע למת כי כבר יחסוהו לו כמו שאמר על רות המואביה שילדה לבועז בן יולד בן לנעמי כאלו היתה מבנה שהוא הבעל הראשון לרות אך יקרא בשמו להתיחס לו למשפחה הלא תראה שיהודה שביאתו על תמר היה כמו היבום ולא נתיחסו הבנים לער ואונן ול נקראו בשמם ולפי שאמר אשר תלד למדנו שאם אינה ראויה לילד לא ינהג בה זה הדין וכן אם הוא אינו ראוי להוליד כי לא יתכן שיאמ' בו כשייבם אותה והיה הבכור אשר תלד:
@658 **ולא ימחה שמו מישראל.** וזה גם כן מורה שאם היה סריס אינו נוהג בו זה הדין שהרי אין יבומו כלי אל שלא ימחה שמו מישראל שהרי אי אפשר לו להוליד. ולפי שאין הכונה בזה אלא כדי שלא ימחה שם אחיו מישראל למדנו שאינו מייבם אלא לאחת ואע"פ שהיו למת נשים רבות:
@659 **ואם לא יחפוץ האיש לקחת את יבמתו.** למדנו מזה שאם היתה יבמתו באופן שהתורה תמנעהו ממנה כאלו תאמר שהיתה ערוה עליו לא ינהג בה זה הדין כי הא במה שאין בו מונע אלא רצונו יצתה זו שהתור' מונעת אותה ולפי שאינו מייבם אלא לאחת והיתה האחרת בלי ראויה לחליצה וליבום הנה השאר פטורות מזה ג"כ לפי שראוי שאיזו מהם שירצה ליבם יהיה הרשות בידו כי התורה אמרה אשת המת וזה המאמר שב לכל אחת מנשיו כי כל אחת מהם היא אשת המת ולזה ראוי שתהיה כל אחת מהם ראויה לבא עליה יבמה או לא ינהג בה זה הדין והוא מבואר במה שאין ספק בו כי כשלא היה לו בה לקוחין כמו הערוה לא ינהג בה חליצה ויבום שנ' יבא עליה וגו' מי שיש לו בה לוקחים ואולם מי שהוא מוזהר מלקיחתה כמו אלמנה לכהן גדול וגרושה לכהן הדיוט היא בת ייבום וחליצה כי התורה צותה שיקחה לו לאשה ולזה סר ממנו אסור הלאו כי עשה דוחה את לא תעשה:
@659 **ועלתה יבמתו אל השערה את הזקנים.** מגיד שהיבמה באה אצל היבם להתירה כי אלו הזקנים הם זקני עיו ואמרה מאן יבמי וגו' אלו הדברים צריך שתאמרם בלשון הקדש:
@660 **וקראו לו זקעי עירו ודברו אליו.** מגיד שהם צריכים לדבר לו לתת לו עצה ההוגנת לו:
@660 **ועמד ואמר לא חפצתי לקחתה.** צריך שיאמר זה בלשון הקדש:
@661 **ונגשה יבמתו אליו לעיני הזקנים וחלצה נעלו מעל רגלו.** מגיד שצריך שיראו זה הפועל הזקנים והנה התבאר מהשרשים הוללים שה יהיה ברגלו הימני וצריך שיהיה נעל של עור כי זה הוא הנהוג בו ושיהיה לו עקב וצריך שתחלוץ היא לא שיעזור לה בה ושתהיה חולצת מעל רגלו שהוא המקום אשר הוא קשור בו לפי הנהוג לא מעל ארכובתו כי אין זה מעל רגלו הקדי' תחלה שיאמר' אלו הדברים שמורים שהם רוצים להפרד בו זה מזה להורות שצריך שתעשה החליצה לשמה ויתכונו הוא והיא בה שתהיה להסיר הזיקה שיש ביניהם:
@661 **וירקה בפניו.** מזה המקום למדנו שצריך שלא יהיה היבם סומא כי הוא אינו רואה הרוק והתורה כונה שיראה הרוק לביישו וכאלו היא רוקקת מצד מיאוסה אותו ואין הרצון בו שתרוק בו בעצמו כי אין זה מן הראוי אך כמנהג המאוס שרוקקין בראותם אותו כאמרו מפני לא חשבו רוק וצריך שתהיה הרקיק' לפי הנהוג ממנה לא שתרוק דם ולא שתרוק בסבת מאכלים מרבים הורק אבל מעצמה שנ' וירקה:
@661 **וענתה ואמרה ככה יעשה לאיש וגו' ונקרא שמו בישראל בית חלוץ הנעל.** הנה תאמר זה בלשון הקדש ותאמ' זה להעיר שכבר עשתה זה הפועל מהחליצ' לתכלית שתסור זיקתה ממנו ולפי שאמ' בית חלוץ הנעל למדנו שהחליצה לבד היא המעכבת ולזה הוא מבואר שאם חלצה אע"פ שלא קראה ולא רקתה חליצתה כשרה כיון שהיתה לשמה כי אלו הדברים נראה מעניינם שלא חייבה התורה בקריאתם כי אם לתכלית מה שיתבאר שהחליצה היא לשמה:
@663 **כי ינצו אנשים יחדו איש ואחיו.** ולא עבד או גר ותושב ר"ל שאם החזיקה אשת הישראלי במבושיו אין קוצצין כפה להצילו מידה:
@663 **להציל את אישה מיד מכהו.** ולא מיד מכהו נפש כי אז ההותר לה להצל בעלה אפי' בנפשו של מכה אותו כמו שקדם:
@663 **והחזיקה במבושיו.** הוא מקום שיש סכנת נפשות והוא הדין לשאר המקומות שיש בהם סכנת נפשות ולזה יצילהו מידה בעת החזקתה במבושיו בקציצת כפה אם לא יוכלו להצילו בזולת ה:
@664 **לא תחוס עיניך.** הזהיר מלחוס על הרודף ואפי' היה בה התואר שיש לו קצת התנצלות לפי מה שיחשוב ואולם אין זה התנצלות לפי שלא היו מכין זה את זה מכת נפש ולזה לא הותר לה להרוג המכה את אישה:
@665 **לא יהיה לך בכיסך אבן ואבן גדולה וקטנה.** ר"ל שהמשקל דאחד בעצמו לא יהיה לו אחד גדול ואחד קטן כאלו תאמר שיהיה המשקל שהוא ליטרא לו אחד גדול ואחד קטן לקנות באחד ולמכור באחר ואמר לא יהיה לך להעיר שאפילו לא שקל בו אלא קיימו עובד בזאת האזהרה:
@666 **לא יהיה לך בביתך איפה ואיפה גדולה וקטנה.** ר"ל שהסאה דרך משל לא יהיה לו ממנה שנים אחת גדולה ואחת קטנה כי מאלו הדברים ימצא עול לקנות בזו ולמכור בזו:
@667 **אבן שלמה וצדק יהיה לך.** ר"ל משקל שלם וצדק שלא יהיה נוסף על השיעור הראוי וכאלו אמר שלא יהיה חסר ולא יהיה נוסף וזה יכלול ג"כ שיהיה הצדק והיושר בדבר המשקל שנכריע המשקל כפי מה שנהוג ושלא יהיה עול במאזנים אשר ישקול בהם:
@667 **איפה שלמה וצדק.** ר"ל מדה שלמה שלא תהיה חסרה ולא יתירה ושיהיה הצדק במחיקת' או בגדישתה ובכלי המחיקה:
@667 **למען יאריכון ימיך.** מגיד שההתנהג בצדק וביושר מביא ישראל להאריך ימיהם על הארץ:
@668 **כי תועבת יי' אלהיך כל עושה עול.** מגיד שבאי זה דרך שיהיה אין ראוי שיעשו עול ולזה יתבאר מזה שאסור לעשות שום עול במסחר ולזה יהיה אסור לערב פירות בפירות כי בזה האופן יעשו עול הסוחרים כשיערבו מעט מן הרעות ביפות כי לא ירגישו בהם הקונים וכן הענין בשאר מה שימשך ממנו אי זה עול שיהיה קטן או גדול:
@669 **זכור את אשר עשה לך עמלק בדרך בצאתכם ממצרי'.** צוה לזכור תמיד הרע שדמה לעשו' לנו עמלק ברפידים בצאתינו ממצרים והנה מן הדומה שהוא עורר אז המלחמה לראותו ישראל בתכלית החולשה עם שידמה ממה שנזכר בזה המקום שהגידו חכמיו שהוא ינצח ישראל אז מצד המערכת ושאין ישראל ראויין עדיין אל הברכה אשר ברך יצחק את יעקב אשר היא מפאת ההשגחה הפרטית ולזה נמצא להם אז לכלות ישראל ותסור מהם הקללה שנתקללו להיות עובדים ליעקב כי עמלק היה מבני עשו כמו שנזכר בסוף פרשת וישלח יעקב והנה על עומק מחשבתם זאת לכלות ישראל קודם שיהיו ראויים לזאת ההשגחה צוה השם לכלותם כמו שצוה להכות את המדיני' על עומק מחשבת' להסיר מישר' ההשגחה האלהית הפרטית כדי לכלותם באמרו כי צוררי' הם לכם בנכליהם אשר נכלו לכם על דבר פעור ועל דבר כזבי:
@670 **אשר קרך ברך.** ר"ל שהוא הזמין עצמו להלחם עמך בדרך לחשבו שאתה שם בזולת מלחמה עם היותך גם כן עיף ויגע ולא היית גם כן אז ירא אלהים בדרך שתדבק בך ההשגחה הפרטית והנה לולי תפילת משה כבר היו עמלק מנצחים כמו שביארנו שם וזה לאות שלפי המערכת היה שינצח עמלק:
@670 **ויזנב בך כל הנחשלים אחריך.** ר"ל שהרג הזנב שבהם והם כל החלושים שיהיו הולכים בזנב המחנה לחולשתם ולזה הוא מבואר שעמלק קבץ כאן כל הסגית שישלם בהם כלוי ישראל האחת עוררו מלחמה לישראל בדרך שלא נשמרו מזה קודם להחלץ בכלי המלחמה ובזה האופן הרג כל החלושים שיהיו בסוף המחנה כי לא נשארו מהם. והשנית שמצאם יגיעים ועיפים מטורח הדרך והשלישית שעדיין לא דבקה בישראל ההשגחה הפרטית כי אז לא היה ישראל ירא אלהים כמו שנראה מהריב שהריבו ישראל שם ונסו השם ית' כמו שנזכר שם והרביעית מצד הדבק ההשגחה הכללית בעמלק לנצח ישראל ולהתחבר כל אלו הסיבות במה שלא ימלטו מידו שלא יכלם ויסורו מעליו ומעל שני בני עשו הקללות שנתקלל עשו בעבור ברכת יעקב ולזה צוה השם יתעלה שאחר שישלימו מלחמות שבעת גוים יניח יי' לישראל מכל אויביהם מסביב ימחו את זכר עמלק לשערו מה שישתדל זה העם להרע לישראל בכל דור כי כשיהיה לאל ידם וכבר תעמוד על זה ממה שתמצא בימי השופטים מצקלג עיר דוד כי זה יורה היותם פונים תמיד להרע לישראל כשיהיה לאל ידם ומה שדמה לעשות המן בן המדתא האגגי לישראל בימי מרדכי ואסתר לולי יי' שהיה להם היה מכלה אותם:
@671 **לא תשכח.** הזהיר אותם מלשכח בלב מה שעשה להם עמלק. הנה זה ביאור מה שנראה לנו שהוא צריך בזאת הפרשה.
@672 **והיה כי תבא.** מגיד שמצות בכורים אינה נוהגת אלא בארץ ישראל והנה הוא מבואר שהתנאי בה שתשלם הירושה והישיבה בארץ ישראל קודם זה זהרי אמר ראשית בכורי אדמתך תביא בית השם אלהיך ר"ל שיהיו מאדמתך ולזה לא ישלם כי אם אחר ירושה וישיבה שידע כל אחד נחלתו כי כבר אמר בזה המקום גם כן ועתה הנה הבאתי את ראשית פרי האדמה אשר נתת לי:
@673 **ולקחת מראשית כל פרי האדמה אשר תביא מארצך.** ר"ל מהפירות שדרכם להביא מארצו והם הפירו' המיוחסים אל הארץ כמו שקדם ר"ל חטה ושעורה וגפן ותאנה ורמון והזתים והתמרים כי עליהם ראוי לתת הודאה לפני השם יתע' על מה שחנן אותנו מירושת הארץ כמו שנזכר בזה המקום. והנה הבכורים האלה שינה בהם הדין הנזכר פה צריך שיהיו ראשית ר"ל הפירות הנלקטים ראשונה כי בזולת זה לא יוכל לומ' מראשית פרי האדמה והנה יש לו להפריש מהם קצתם שנאמר מראשית ואמר כל פרי להגיד שצריך להפריש מכל פרי ופרי לעצמו ולפי שאמר אשר תביא מארצך למדנו שמארצו אפשר שיופרשו ר"ל ממחובר לקרקע ויהיו בכורי' וזה יהיה כשיאמר דרך משל אלו התאנים יהיו בכורים ויסמן אותם כדי שיכירם:
@673 **ושמת בטנא והלכת אל המקום אשר יבחר יי'.** מגיד שהם טעונין כלי ולפי שאמר על אמרו כל פרי האדמה ושמת בטנא מגיד שוא מביא כל המינים בכלי אחד אם ירצה אך יעשה זה בדרך שיהיה שם כל פרי ופרי בפני עצמו ומגיד שהו' מיטפל בהבאתם עד באם למקם הבחירה ולזה אמר גם כן ראשית בכורי אדמתך תביא בית יי' אלהיך ולזה אם נגנבו או נאבדו קודם שהגיעו שם הבעלי' חייבים באחריותם ולפי שאמר ושמת בטנא והלכת למדנו שלא יחוייב שיהיו הבעלי' נושאי' הטנא מביתם עד בית הבחירה כי לא אמר ושמת בטנא ולקחת בידיך והלכת ולפי שאמר מראשי' וכבר יאמר ראשית על הנבחר ראוי שיהיו הבכורים מהפירות הנבחרים שיש לו לא מהגרועים עם שהם אינם מיוחסים לשבח ארץ ישראל אם לא היו על שלמותם ולפי שאמר כל פרי האדמה. למדנו שאין מביא בכורי' משקה כי אין זה פריה לפי הנהוג ר"ל מן החטה והשעורה ושאר המינים זולת הגפנים והזיתי' שיביא אותם משקה כי זה גם כן פרים לפי הנהוג מהם ולפי שאמר כל פרי האדמה למדנו שהוא מביא בפעם אחת כל בכוריו לא בפעמי' רבות וכבר למדנו זה גם כן ממה שאמר הגדתי היום להשם למדנו שאינו חוזר ומגיד בשנה אחת ולפי שעצרת נקרא יום הבכורים למדנו שמחוייב להביא בכוריו מפירות השנה ההיא לא שיביא בכורים מן הישן על החדש וזה מבואר כי התורה מאד דקדקה שיהיה מפריש הפירות ההם כל שכן שדקדקה שיפריש מהפירות ההם:
@674 **ואמרת אליו הגדתי היום.** הנה יאמר זה בלשון קדש בזה האופן שהגבילה אותו התורה:
@675 ולפי שאמר **ולקח הכהן הטנא מידיך** למדנו שהבעלים מביאים הבכורים בידיהם בבאם אל הכהן והוא לוקח מיד הבעלים ולמדנו מזה שאם הביא בטנא שערכו מועט ישאשר לכהן אך לא נלמד מזה שאם היה כלי שיהיה ערכו רב שיהיה לכהן הכלי ולפי שדקדקה בו התורה שמה שיקח הכהן מיד הבעלי' טעון תנופה כמו שהתבאר בפרשת צו ובמקומו' אחרים ממה שקדם הנה למדנו שהבכורים טעונים תנופה:
@675 **והניחו לפני יי' אלהיך.** לפי שכבר נתבאר בפרשת ויקרא שמה שיונח לפני המזבח צרך שיהיה עם זה לפני יי' הנה יונח זה על קר דרומית מערבית על חודה של קרן לצד הרוח הדרומית וכבר נתבאר זה עוד בזה המקום ממה שאמר אחר זה והנחתו לפני יי' אלהיך וזה ממה שיורה שזאת ההנחה אינה כי אם אחר שיאמר אלו הדברם הנזכרים תכף והנה בעת שיאמר זה המביא יניף הכהן הבכורים כמשפט התנופה:
@676 **וענית ואמרת לפני יי' אלהיך.** הנה יאמר המביא שם מה שזכרה התורה פה בלשון הקדש:
@676 **ארמי אובד אבי.** ר"ל אבי היה אובד בארם לולי עזר השם יתע' שהיה לו או יהיה אובד יוצא והוא שהרצון בזה שהארמי והוא לבן היה מאבד אבי לולא יי' שהיה לו:
@681 **ועתה הנה הבאתי את ראשי' פרי האדמה אשר נתת לי השם.** זה ממה שיורה שאם לא היה בכורים ראשית אינו קורא כי אינו יכול לומר הבאתי את ראשית וכן אם לא היו שלו האילן והקרקע והפירות בעת הקריאה אינו קורא כי אינו יכול לומ' את ראשית פרי האדמה אשר נתת לי והאשה אינה קראה כי אין לה נחלה בארץ ולזה אינה יכולה לומר אשר נתת לי וכן אם לא היה קיים האילן והקרקע כי אין ראוי שיאמר פרי האדמה אשר נתתה לי לפי שעתה אין מדרכו שיהיה ממנו פרי והנה השותפין מביאים בכורים שנאמר בכורי כל אשר בארצם. והנה אם היה הקרקע מאשתו קורא זאת הפרשה שנאמר אשר נתן לך יי' אלהיך ולביתך:
@681 **והשתחוית לפני השם אלהיך.** מגיד שכל הנכנס בבית הבחירה משתחוה לפני השם והוא לצד קדש הקדשים:
@682 **ושמחת בכל הטוב אתה והלוי והגר אשר בקרבך.** אין ראוי שנבין שיאכל הבכורים וישמחו בהם אלו העניים שזכר כי כבר ביארה התורה בפרשת קרח כי הבכורים הם לכהן ולזה הוא מבואר כי הכונה בזה שיזבח שם שלמי שמחה ויאכלו העניי' מהם עמו ולפי שהבכורים טעונין שמחה למדנו מזה שאינן נאכלין באונן כמו הענין במעשר שני:
@683 **כי תכלה לעשר את כל מעשר תבואתך.** כבר קדם כי בשנה שלישית יפרישו הבעלים אחר מעשר ראשון מעשר עני ר"ל שהוא לעניים בשנה ההיא אך בשי שנים הקודמות יפרשו הבעלים מעשר שני והוא לבעלים ועולין ואוכלים אותו במקום הבחירה ולפי שאמר כי תכלה לעשר למדנו שזה יהיה ברגל שכל המעשרות כלות בו בין מפירות הארץ בין מפירות האילן והוא חג הפסח ואמנם הסכמנו שיהיה ברגל לפי שלא אמר והלכת אל מקום אשר יבחר יי' מגיד שאז הם כלם שם:
@683 **ונתת ללוי לגר ליתום ולאלמנה.** זה מעשר עני שנתן ללויים לעניים לאכלו בשערים כמו שקדם:
@684 **ואמרת לפני יי' אלהיך.** לפי שאין אלו הדברים כי אם לשם יתע' להזכיר כל אחד שיעשה המחוייב לו מענין המעשרות והקדשים למדנו שאפשר לומר זה בכל לשון:
@684 **בערתי הקדש מן הבית.** זה מעשר שני כי הוא נקרא קרש וכן נטע רבעי ועני' ביעורו מן הבית הוא אכילתו במקום הבחירה או כסף פדיונם:
@684 **וגם נתתיו ללוי לגר ליתום ולאלמנה.** זה המאמר שב אל מעשר עני ואמר וגם נתתיו ללוי להורות שכבר נתן גם כן מהמתנות הקודמות לו לראוי להם לקט שכחה ופאה לעניים והמעשר ראשון ללוי ותרומה ובכורים לכהן:
@684 **ככל מצותך אשר צויתני.** רוצה לומר בכלל המתנות האלו נהגתי לפי מצות התורה עליהם ולא אחרתי הקודם ולא הקדמתי המאוחר:
@684 **לא עברתי ממצותיך ולא שכחתי.** רוצה לומ' שלא שנה החק שזכרה התורה ברבוי' אלו כאו תאמר שלא הפריש מן החדש על הישן או ממון על שאינו מינו:
@685 **לא אכלתי באוני ממנו.** זה שב אל מעשר שני שאוכלים בשמחה כמו שקדם וזה לאות שהתורה הזהירה מלאכול אותה באנינות הוא אנינות של תורה והוא יום מיתה וקבורה או אינו תופס לילו הבאה אחריו כמו שהתבאר מאמרו בפרשת שמיני ואכלי חטאת היום וראוי שיתבאר כי אינו מדבר כי אם במקום שאין בו אשם אחר זולת אכילתו באונן כי הוא אומר שעשה במצות השם יתע' ולא יחסר לבאר אלא אלו הדברים שלא נתבארו במה שקדם:
@685 **ולא בערתי ממנו בטמא.** שלא אכלתיו בטומאה ולא האכלתיו כי האכילה היא בעודו מגיד שאם אכלו בטמאה במקום הבחירה לוקה:
@685 **ולא נתתי ממנו למת.** ר"ל לצרכי המת כאלו תאמר לקנות לו ארון ותכריכין למת וזה כי התורה יחדה אותו לאכילה ושתיה במקום הבחירה:
@685 **שמעתי בקול ה' אלהי.** ר"ל שנהגתי בכל אלו הדברים לפי משפטי התורה כאלו אמר שבדבר הבכורים שמעתי להביאם בית השם באופן הנזכר ומזה המקום התבאר שצריך שיהיה הכל מבוער קודם זה ולפי שהביעור ממעשר שני כבר יהיה ברגל ללמדנו שבי"ט אחרון של פסח יאמר ודוי מעשר וקודם זה יהיה הכל מבוער והתועלת בה הוא שלא יאחר נתינת המתנות לכהנים וללוים ועניים ואכילת מעשר שני והנה יחוייב לו מפני זה למהר להוציאו לאכילה וישמחו בו העניים והלויים לפי שסמך ודוי מעשר לדבר הבכורים למדנו שעליו גם כן יהיה זה הודוי והוא מבואר שאם אין בידו אלא מעשר שני שהוא מתודה כי עקר הודוי בדבר מעשר שני:
@686 **השקיפה ממעון קדשך מן השמי' וגו'.** ר"ל עשיתי מה שמוטל עלי עשה אתה מה שמוטל עליך. וברך את עמך ונחלתיך:
@687 **היום הזה יי' אלהיך מצוך לעשות את החקים וגומ'.** מבואר ונגלה כי קצת המצות הנזכרות במה שעבר הם חקים וקצתם הם משפטים:
@687 **ושמרת ועשית אותם בכל לבבך ובכל נפשך.** ר"ל שתשמור אותם בלב לעשות אותם בתכלית התשוקה והציור בעניניהם לפי מה שיושג מהם לאיש ואיש:
@688 **את ה' האמרת היום.** לפי שהאמיר הוא הסעיף העליון יחס הרוממות אל ההאמרה כאלו תאמר שמת אותו עליון עליך להיות לך לאלהים ולמנהיג ולהתנהג במצותיו שגזר עליך:
@689 **וה' האמירך היום.** ר"ל רומם אותך על הגוים ויחדך משאר האומות:
@691 **שמור את כל המצוה אשר אנכי מצוה אתכם היו'.** צוה שישמרו כולם זאת המצוה בכללות שזכר בזה המקום כדי שיעשו אותה בבא עתה:
@692 **והקמות לך אבנים גדולות.** רוצה לומר שיהיו עם זה אבנים שלמות שיבנו מהם מזבח בהר עיבל כמו שיזכור אחר זה וצוה לשדותם בסיד כד לכתוב עליהם כל דברי התורה הזאת באר היטב כמו שאמר אחר זה והנה הרצון באמרו באר היטיב הוא שיהיה הכתב מבואר וניכר ולזה גם כן שד אנני' בשיד וכבר נתבאר בספר יהושע כי שם כתבו את משנה תורת משה כמו שנאמר בפרשת מלך וכתב לו את משנה התורה הזאת על ספר ולזה יעתיקו שם כל התורה כלה ויכתבוה באבנים ההם ולזה הוצרכו להיות גדולות מאד כדי שלא יהיה הכתב דקה מאד שנאמר באר היטב:
@694 **והיה בעברכם את הירדן.** רוצה לומר אחר עברכם את הירדן כי הר עיבל היה בעבר הירדן ימה כמו שקדם בפרשת ראה אנכי והנה צוה שם לבנות מהאבנים ההם מזבח ה' ולהעלות עליו עולות ולזבוח שם שלמים ואחר זה יכתבו עליהם את כל דברי התורה כמו שקדם והנה זה היה לתכלית שיכרתו ישראל ברית עם השם יתעלה בקבלם עליהם כל הברכות והקללות הכתובות אחר זה למקיים דברי התורה ולעובר עליהם:
@700 **ועשית את מצותיו ואת חקיו אשר אנכי מצוך היום.** רוצה לומר שעם דברי הברית האלה נהית לעם ותשמור לעשו' תמיד מצותיו וחקיו אשר אנכי מצוך היום והם כל מצות התורה:
@702 **אלה יעמדו לברך את העם על הר גריזים.** הנה השבטים היותר נבחרים שם אותם על הברכה ועל הקללה שם שני בני השפחות והם גד ואשר דם וראובן גם כן לחסרונו וידמה שהיה גם כן זבולון הפחות שבבני הגבירות אחר ראובן כי כבר מצאנו בפרשת ראה אנכי כי הברכה היתה תחילה על הפרטי' ואחר כך הקללה על הפרטים ואחר כך הברכה על הכלל ואחר כן הקללה על הכלל ואמנם קצרה התורה מלזכור פה הברכה על הפרטים כי הוא בפרטים בעצמם שהיתה בהם הקללה כאלו תאמר שהיו אומרים תחת אמרו ארור משיג גבול ברוך אשר לא ישיג גבול וכן על זה הדרך:
@706 והנה סמך מבזה אביו ואמו לעובד ע"ז להעיר שעובד ע"ז מורד במי שילדהו והמציאהו וגדל אותו ושמר אות מציאותו וסמך גם כן להם משיג גבל רעהו להעיר שהעובד אלוה זולת השם יתעלה גם מהעליונים שנתן להם השם יתעלה חלק בהנהגה הנה הוא משיג גבול כי אין מגבול אלו האלוהות אבל הם מנהיגי הנהגות חלקייות לפי מה ששם הש' יתעלה עליהם ביום הבראם:
@708 **ארור משגה עור בדרך.** רוצה לומר להטעותו בדרך כשישאל זה וסמך אותו למשיג גבל רעהו לפי שהוא מזיק חברו מבלי ידיעתו וכן העניין במשנה עור בדרך:
@709 **ארור מטה משפט גר יתום ואלמנה.** רוצה לומר אפילו עשירים הזהיר בזה כי מפני שפלותם יקל לדיין להטות משפטם והנה סמך אלו כלם לעושה ע"ז להורות אע"פ שלא יעבדה יהיה ארור כי הוא משגה העורים הרואים הפסל ההוא שם ויחשבוהו לאלוה עם שהעובד ע"ז אין לו דרך יביאהו להתנהג במדות החשובות וזה כי העובד השם יתעלה יתכוין בדרכיו ובמה שיש מהם מהפלגת היושר והחנינה ויביאהו זה להדמות בדרכי השם יתעלה וללכת בדרכיו ואולם עובד ע"ז לא יעד בה דבר ילמד ממנה להתנהג במדות המשובחות אבל הענין הוא בהפך ולזה גם כן סמך לזה דבר חטאת משפט גר יתום ואלמנה:
@710 ואחר שזכר הנלוה לדבר ע"ז שב להזכיר דבר העריות ושפיכות דמים וזכר תחלה ערות האב כי יש בה מהזרות והעזות יותר ולזה סמך אליה דבר ערות הבהמה והנה אחר ערות האב תהיה היותר זרה ערות אחותו ואחריה תהיה היותר זרה ערות אם אשתו כי יש בה מהעזות יותר ממה שיש מהעזות בגלוי ערות בת אשתו וזה מבואר מאד ואחר שהשלים זה זכר הרציחה שירצח האדם בידיו וזכר אחריה חטאת המשפט במיתת בית דין בעבור שוחד ולמדנו בזה כי העובד עבודה זרה היא היותר קשה שבכל העברות ואחריה גלוי עריות כי היא עם רוב גנותה תמשיך האדם מאד לזה הפועל המגונה מצד ההנאה שישיג בה והנה סמך גם כן גלי עריות לע"ז כי כבר תמצא רוב נימוסי ע"ז מתיישרי' לדבר גלוי הערוה וזה נמצא בעניין עבודת פעור כי פעירתם עצמם לפעור אנשים ונשים מביאים ארותם לידי תאוה ומתך כך ישתתפו בזמה וזה מבואר שהיו עובדיה רבי המספר במעט המקום להם והנה גילוי הערוה יתישר מאד להביא לשפיכות דמים כאשר יראה מזה בעניין גילוי ערות אשת איש וזולתה מהעריות כי אם ימצא ימצאנו בעל האשה או קרובה לנואף עם היותו מקנא בו ימהר יחישה מעשהו להמית ולא יחמול עליו ולא יוכל לסבול עליו להתנקם ממנו ע"י ב"ד וזה ממה שאינו צריך אל הבאור והנה אחר זה כלל קיום כל דברי התורה בקללה אחת:
@717 **והיה אם שמוע תשמע בקול השם אלהיך.** אלו הם הברכות בכלל למקיים את כל דברי התורה הזאת:
@717 **ונתנך השם אלהיך עליון על כל גויי הארץ.** ידוע שה לא יתכן להיות מתמיד על זה האופן אם לא מצד ההשגחה הפרטית וכן מה שזכר מהמשך הברכה בכל הדברים בעיר ובשדה לא יתכן שישלם מפני ההשגחה הכוללת אפילו בעת פרטי אבל תהיה הברכה בקצת זולת קצת כל שכן שלא ימשך ממנו זה בכל הדברים שמיד והיותר נפלא הוא המצא הברכה בסלי פירות ובעסת המשארת ובפירות האוצר וכן מה שזכר מנצוח האויבים תמיד:
@724 **וברכך בארץ אשר השם אלהיך נותן לך.** ר"ל שאלו הברכות ימשכו לך באופן יותר שלם בארץ הנבחרת מצד היותה מוכנת אל שידבק בה השפע האלהי ומצד היותה מוכנת לברכה בעצמה כמו שקדם מענינה:
@725 **ישימך השם לעם קדוש.** ר"ל שישגיח בך השגחת נוספת מצד קדושתך עם שכבר תהיה מיוחד לו בשמרך מצות השם יתעלה ולכתך בדרכיו:
@726 **וראו כל עמי הארץ כי שם יי' נקרא עליך.** רוצה לומר שהם יראו שאין שם עם זולתך יהיה שם השם נקרא עליו להשגיח בו ביחוד:
@727 **והותירך ה' לטובה וגו'.** שלא תאמר הברכה תהיה בדברים האלו בהמצאתם אבל אחר זה ימותו ויפסדו לזה אמר שהשם ישגיח בהשארותם וזכר שהשם יתע' ישגיח בהם בנתינת המטר בעתו ולשלח ברכה בכל מעשה ידיהם:
@728 **והלוית גוים רבים ואתה לא תלוה.** אמר זה להורות על עשרם ושלא יסרו ויהיו לראש לשאר הגוים ולא לזנב ולמעלה לא למטה כי ישמע אל מצות ה' ללמד אותם ולהתנהג בהם על פי התורה:
@730 **לא תסור מכל הדברים.** ביאר כי הנטייה הקטנה ממצות התורה תביא בסוף לעבוד עבודה זרה:
@731 **והיה אם לא תשמע בקול ה' אלהיך.** מגיד שאם לא קיימו כל מצות התורה סופם ליפול באלו הקללות שזכר כי בזה יבא להחיש בשם יתע' ולעבוד ע"ז כמו שקדם או ירמוז בזה אל ע"ז כי היא שקולה כנגד כל המצות וכזה אמור על עבודה זרה בפרשת בהעלותך. וכי תשגו ולא תעשו את כל המצות האלה. ויורה על אמתת זה מה שאמר אחר זה מפני רוע מעלליך אשר עזבתני וביאר שכמו שהברכ' היתה על צד ההשגחה הפרטית כן תהיה הקללה על צד ההשגחה הפרטית ליסרם והוא מבואר מהקללות האלה וכבר נתבאר זה ביאור שלם במה שנזכר בפרשת אם בחקותי ובכלל:
@731 הנה הקללה הנמשכת בכל הדברי' בעיר ובשדה לא יתכן שתהי' מצד ההשגחה הכוללת וכן היות הרע וחסרון וההשחתה נמשך מכל הפעולות שימשך האדם תמיד לא יתכן שתהיה מצד ההשגחה הכוללת וכן לא יהיה הדבר מתמיד אם לא מזה הצד כי מצד ההשגחה הכוללת תקרא המגפה בזה האופן על המעט ועל דרך חזרות:
@738 **בשחפת.** אחשוב שהוא קדחת יום שאינה בגדר הקדחת ואחריה זכר הקדחת שאינה חדה ואחריה זכר הדלקת שהיא קדחת חדה ואחרי' חרחור שהיא קדחת חדה שזופת:
@738 **בשדפון.** הוא חולי שנתך בו הגוף וירקון הוא חלי מתחדש מרוע מזג הכבד ישוב אדם בו נוטה לצבע הירוקת הנה אלו הם מינים מן החלאים הקשים אמר שיביאם השם יתעלה עליהם ליסרם.
@739 וזכר גם כן שימנע מהם המטר בדרך שלא יתנו הצמחים פרים.
@740 וזכר עוד על צד הקללה יהיה מה שירד בארצם מהמטר הויה התהוה מהאיד הקיטורי הוא עשן עב והוא כמו אבק ועפר ניבי"יה בלעז והיא רבת ההפסד לבעל חי ולצמחים.
@741 עוד זכר שהקללות האלה יהיה שינצחוך אויביך תמיד באופן שתצא אליהם בדרך אחד ומרוב פחדך מהם תנוס לפניהם בשעה דרכים כי ממקומות רבים ירדפוך להכות אותך:
@741 **והיית לזעוה לכל ממלכות הארץ.** הנה תירא וינוס לבבך מרוב הפחד בעבור כל ממלכות הארץ עם שגם מהמלכות השפלה תירא וזה דבר לא יתכן שיקרה מצד ההשגח' הכוללת:
@742 **והיתה נבלתך למאכל.** מגיד שמרב הפחד ימותו רבים ולאיקברו ותעזב נבלתם למאכל לכל עוף השמים ולבהמת הארץ. ואף על פי שאינו איש שיקום עליהם ויחריד אותם:
@743 **בשחין מצרים.** הוא היה פורח אבעבועות:
@743 **בטחורים.** הוא הויתו מתחדשות בשת אצל פי הטבעת מחו או מבפנים והוא חלי קשה רפואה:
@743 **ובגרב ובכרס.** רוצה לומר בחכוך ובגרב יבש והם גם כן קשה הרפואה ולזה אמר לא תוכל להרפא:
@744 **שגעון.** הוא חלי יחסר בו דעת האדם:
@744 **ועורון.** הוא סנורי' בעין הלב:
@744 **תמהון לבב.** הוא שיתמה על כל הדברים ולא יברור אי זה ראוי להיות ואי זה בלתי ראוי להיות ולזה לא יכונו מחשבותיו ויהיה כל אחד ממשש בדבר שהוא ברור בצהרים כמו שימשש העור באפילה ולזה לא יצליחו דרכיהם:
@745 **והיית אך עשוק וגזול כל הימים ואין מושיע.** ביאר שלרוב שפלותו יעשיקוהו ויגזלוהו אויביו ואין מושיע אותו מהם ויהיה מהפלגת העשק עד שכאשר יארס אשה יקחנה תחלה האויב למשגל ויגזלנה ממנו וכאשר יטע כרם לא יזכה לאכל מפריו ואחר שזכר שיגזלו ממנו אשה וביתו וכרמו וצאנו ושורו וחמורו וזכר אחר זה שכבר יגזלו ממנו פרי בטנו ופרי אדמתו וכל יגיעו והנה היו הרבה מאלו הקללות בימי השופטים ובימי מלכי ישראל לפי מה שנזכר שם:
@750 **והיית משוגע ממראה עיניך וגו'.** רוצה לומר שמרוב העשק אשר תראה שיעשקוך יאבד שכלך:
@751 **בשחין רע על הברכים ועל השוקיים.** הוא השחין המתחדש מלבנה מלוחה ותקשה מאד רפואתו ואמר אחר זה מכף רגליך ועד קדקדך כאלו יאמר שבהתחלה לא יבא אלא בקצות הגוף כי לחולשם ידחם הטבע שם ואחר יתפשטו בכל גוף אותם השחינים הרעים מכף רגל ועד ראש:
@752 **יוליך השם אותך ואת מלכך אשר תקים עליך.** זה היה בחרבן בית ראשון כשהוגלה יכוניה ואחריו צדקיה ע"י נבוכדנצר לך בבל:
@752 **ועבדת שם אלהים אחרים.** והנה הוכרחו שם לעבוד ע"ז כמו שנתבאר בספר דניאל עד שכלם השתחוו לצלם שעשה נבוכדנצר זולי חנניה מישאל ועזריה או יהיה הרצון באמרו ועבדת שם אלהים ועבדת שם עובדי אלהי' אחרי' הפך מה שכוונה התורה שכלם יהיו לך למס ועבדוך:
@753 **והיית לשמה ולמשל ולשננה.** ר"ל שכל הגוים ישמו ויתמהו על הפלגת רוע ענייניך ותהיה למשל ולמלה כפיהם כאלו לא ידברו כי אם בך ימשילו דבר כל רע בדבריהם אליך כמו שיאמרו כמו שקרה לפלוני יקרה לי אם אעשה כך או יהיה הרצון באמרו לשמה ענין שממה והשמד:
@754 **זרע רב תוציא השדה.** זה נתקיים בימי יואל בן פתואל:
@756 **זתים יהיו לך בכל גבולך.** ר"ל האילנות אך לא יבשלו פרי' אבל ישל מהם והנה זאת הקללה יותר קשה מהעושק וגזל כי בו אולי תלקח עצה כמו שמצאנו שעשו ישראל מפני מדין דברי' הרבה לשמירה שלא יעשקום אך בזה לא תתכן עיצה:
@757 **בנים ובנות תוליד ולא יהיו לך.** אמר זה כי מרוב הרעב וחסרון יצטרכו לשוטט אנה ואנה לבקש טרפם וימצאום האויבים וישבו אותם:
@758 **הצלצל.** הוא ממיני התולעת אוכלי עלי הצמחים ומשחית פרים:
@759 **הגר אשר בקרבך.** הוא גר תושב ואחשוב שאילו הקללות היו בזמן בית שני שהכותיים היו לפעמים מתגברים על ישראל ומשפילים אותם:
@764 **ועבדת את אויביך אשר ישלחנו ה' בך ברעב ובצמא וגו'.** ידמה שזה היה במשל מלכות יון על ישראל בבית שני:
@764 **ונתן עול ברזל על צוארך.** וכבר ידוע שהמלכות העמיס כמה עולים כבדים על ישראל עד שמנעום מלקיים מצות התורה:
@765 **ישא ה' עליך גוי מרחוק.** אלו הם הרומיים ואספסיינוס וטיטוס שהחריבו ארצנו ובאו מרחוק מאד והם היו מלשון אחר ולא נשאו פנים לזקן ונער לא חוננו. וכלו פרי בהמתם ופרי אדמתם ולא השאירו להם שום מזון עד שכבר היו מתים ברעב רבים וזה נתקיים גם כן כשבא מלך אשור על עשרת השבטים וכשבא על ערי יהודה הבצורות וכבשם בידוע שהם כמו במצור על ערי ישראל ר"ל מלכות רומי עד שכאשר היו במצור נתחזק הרעב עד שכאלו בשר בניהם כמו שנזכר בספר יוסף בן גוריון וכאשר הפליג בספור אלו הרעות אמר שזה הרע הנפלא יגיע לישראל אם לא ישמור לעשות את כל דברי התורה הזאת להעיד שא ישמרו דרכי התורה לא היו נופלים במה שנפלו בו מהרע:
@775 **מכות גדולות ונאמנות.** ר"ל מכות גדולות ומתמידות וקיימות:
@776 **והשיב ה' בך את כל מדוה מצרים אשר יגורת מפניהם.** רוצה לומר שיהיה מדרך השם יתעלה לעשות כמו אלו הרעות אך לא טובות כמו שביארנו במה שקד ולזה אמר כל המחלה אשר שמתי במצרים לא אשים עליך כמו שביארנו שם. אמנם עתה כשנטית מדרכי השם יתעלה בזה יביא עליך אותם המכות וגם חלאים ומכות אחרות אינם כתובים בספר התורה הזאת:
@777 **יעלם ה' עלך עד השמדך.** שלא ישארו ממך כי אם מתי מעט והנה כמו שהיה ערב לשם יתעלה להטיב אתכם כאשר שמרתם מצותיו כן יערב לו להשמיד אתכם ולהגלות אתכם עד שתהיו גולים מעל האדמה ההיא ונפוצים בכל העמים מקצה הארץ ועד קצה הארץ וזה היה מקצתינו אחר גלות שומרון ומקצתינו אחר חורבן בית שני ועוד היום אנחנו נפוצי' בכל הגוים השי מחר לקבצנו מכל הארצות אשר הדיחנו שמה:
@780 **ועבדתם שם אלהים.** ר"ל עובדי אלהים אחרים ובגוים ההם לא תרגיע ולא יהיה לך מנוחה מרוב הרדיפות אשר ירדפוך והמעמס הכבד אשר יעמיסו עליך:
@781 **ונתן ה' לך שם לב רגז.** שתירא מאד ויירא לבבך מרוב הצרות הבאות עליך ויחשכו עיניך בעבורם ותכאב נפשך תמיד:
@782 **והיו חייך תלואים לך מנגד.** רוצה לומר שתעמוד בסכנה עצומה עד שלא תאמין בחייך:
@783 **בבקר תאמר מי יתן ערב.** כל כך תהיינה הצרות הולכות וחזק עד שבבקר תתאוה הערב שעבר כי יותר מעט היה לך מהרע בו וכן ההקש מהערב אל הבקר שעבר מצד הפחד שתפחד ומצד מה שתראה שיגיע לה מהרע. והנה יגיע ענין פזורכם בארצותם עד שכבר ישיבך השם יתעלה מצרים באניות להגלותך שם ושם תתחזקנה הצרו' לכם עד שתמכרו שם לעבדים ולשפחות ואין קונה וכבר יעד בפרשת אתם נצבים שאחר שיבאו על ישראל הקללות ויהיו נפוצים בגוים ישובו אל ה' ושב וקבצם מכל הארצות אשר הדיחם שמה:
@785 **אלה דברי הברית אשר כרת ה' את משה.** רוצה לומר שאלו הדברים מהברכות והקללות הנזכרים פה צוה ה' את משה בהר חורב שיכרות זה הברית אל ישראל בארץ מואב מלבד הברית הנזכר בפרשת אם בחקותי אשר כרת השם יתעלה אתם בחורב. וזה כי כל אלו הדברים אמר הש' יתע' למשה בהר חורב כמו שביארנו בפרשת ואתחנן באמרו אלו העדות והחקים והמשפטים אשר דבר משה אל כל ישראל בצאתם ממצרים:
@786 **ויקרא משה אל כל ישראל.** אמר שעם ראותם אלו הנפלאו' העצומות הנה לא האמנתם ביי' אמונה שלמה כי תמיד הייתם ממרים את יי' כמו שקדם ואמר ולא נתן יי' לכם לב לדעת להודות כי עם רוב מה שהביא אתכם אליו באלו הנפלאות העצומות שהראה אתכם לא נשלם לו מצד רוע תכונתכם שיהיה לכם לב לדעת ולהשיג עוצם גבורת השם יתעלה באופן שתיראו ממנו ולזה הוצרכתם לעכב במדבר מ' שנה שכלכלתי אתכם במזון ולבוש בזולת לחם ויין גם לא הוצרכתם ללבוש ונעלים בכל זה הזמן כי על צד המופת עשיתי הענין באופן שלא בלו שמלותיכם ולא נעלכם כדי שתכירו אותי ותדעו כי אני ה' מנהיג אתכם ומשגיח בכם:
@793 **ושמרתם את דברי הברית הזאת.** רוצה לומר שתשמרו בלב דברי התורה אשר עליהם נכרת הברית ותעשו אותם:
@793 **למען תדעון את כל אשר תעשון.** כי מי שלא למד הדבר לא יתישר לעשות אותו עם שזה יהיה סבה שתעמדו על כונת התורה ויגיע להם בעבורה התכלית המכוון בה הנה זה ביאור מה שיצטרך אל ביאור זאת הפרשה.
@794 **ראשיכם שבטיכם.** רוצה לומר ראשיכם ראשי שבטיכם:
@794 **זקניכם.** הם השופטים וקראם זקנים מצד חכמתם ולזה אמר זקני העיר ההיא כמו שקדם על השופטים. והנה זכרם לפי מדרגתם וזה שכבר זכר תחלה ראשי השבטי ואחר כך השופטים ואחר כך השוטרים. ואחר כך זכר כל איש ישראל ואחר כך זכר הטף כי הם כשיגדלו יגיעו לגדר המצות ואחר כך זכר הנשים ואחר כך זכר הגרים אשר בקרב המחנה והם הגרים והתושבים אמר מחוטב עציך על שואב מימיך והם שכיריהם שהיו עושים מלאכתם והנה אמר זה כי כלם היו שם לשמוע דבריו כי דבריו היו לכל ישר כמו שנזכר בראש זה הספר האחרון:
@796 **לעברך בברית ה' אלהיך ובאלתו וגו'.** הנה היה דרך כורתי הברית שיכרתו דבר לחציין ויעברו אחר כך בין הבתרים כמו שראינו בברית בין הבתרים ולזאת הסבה התחכמה התורה בכריתת הברית שתהיה הברכה כנגד הר גריזים והקללה כנגד הר עיבל והיתה התורה כתובה שם בהר עיבל באבני המזבח והקריבו שם קרבנות להעיר שבעבדם השם יתעלה ובשמרם דרכי התורה ימלטו מהקללות ההם והנה היו עוברים ישראל אחר זה עם כל הנטפלין להם בין שני ההרים ההם כדי שיעברו בין ברית השם יתעלה לישראל ובין אלתו להורות שהם כרתו ברית עם השם יתעלה לקיים תורתו בזה האופן שאם יקיימום יחולו עליהם הברכות שיעד השם יתע' ואם לא יקימום יחולו עליהם הקללות אשר קבלום עליהם ויעדם להם השם יתעלה גם כן ואמר כי בזה הברית שהש' יתעלה כורת לישראל היום יקים לו לעם מיוחד מבין שאר העמים לא יובדל עם לעבודתו זולתו והוא יהיה לו לאלהי' לבדו ולמנהיגו למשגיח וכאלו אמר שאם לא יהיה לו לעם בשיתיחד לעבודתו גם השם יתעלה לא יהיה לו לאלהים כי זה תלוי בזה:
@798 **ולא אתכם לבדכם אנכי כורת.** אמ' זה בעבור הדורות הבאים ובעבור הגרי' שיתגיירו משאר האומות כי הם כלם נכנסים בזה הברית והנה האבות כרתו הברית הזה עליהם ועל זרעם והנכרי המתגייר יקבלהו עליו בעת היותו מתגייר:
@800 **כי אתם ידעתם את אשר ישבנו בארץ מצרים.** רוצה לומר הנה אתם ידעתם את אשר ישבנו בארץ מצרים ואת אשר עברנו בקרב הגוים אשר עברתם והם סיחון ועוג וחמשת מלכי מדין והכנעני מלך ערד וראיתם את שקוציה' ואת גלוליהם שעשו הם לאלהים מעץ ואבן אשר אין רוח בקרבם וכסף וזהב אשר שמו עם הצלמים ההם לנוי לפתות האנשים אליהם מצד הקשוט והיופי אשר בהם:
@802 **פן יש בכם איש או אשה או משפחה או שבט.** לפי שזה הדבר מגונה התחיל בפחות ואמר והוא היחיד או היחידה ואחר זה זכר המשפחה שהיא כוללת אנשים רבים ואחר זה זכר השבט שהוא כולל משפחות רבות ואמר פן יש בכם איש או אשה או משפחה או שבט אשר לבבו פונה היום מעם הש' יתעלה ללכת אחרי אלהי הגוים שזכרנו שעברנו בהם שמא יש בכם שרש פורה ממנו דבר מר מאד כמו ראש ולענה.
@803 **והיה בשמעו את דברי** הקללות האלה אשר עליהם וכרת הברית מהש"י את בני ישראל יחשוב בלבו הנה אני יהיה נקי מהקללות האלה ויהיה לי שלום ואתברך באשר אמשך למה שתביאני אליו בחירתי ושלא אשתדל לעיין בדברי התורה אי זה דבר ראוי לי לעשות ואי זה דבר ראוי שאמנע ממנו כדי שתהיה נוספת הרוה עם הצמאה והנה קרא התורה צמאה כי בעלי התאו הישארו צמאי' מאד ממה וקרא בזה ההולך בדרכי לבו כי בו תרוה נפשו ממה שהוא מתאוה אליו ולא תצמא או ירצה מאמרו שלום יהיה לי כי בשרירות לבי אלך שיוסיף על דברי התורה במחשבתו ההולך בדרי לבו ויאמר בברכות שאם ילך בדרכי לבו יהיה ברוך כשלא יכון לעבור על דברי התורה:
@804 **כי אז יעשן אף יי' וקנאתו באיש ההוא.** אמר זה כי בזה התנאי שחשב בלבו לא ימלט משיגיעו לו אלו הקללות ואם היה חוטא בזה האופן יחיד או יחידים ימחה הש"י את שמם מתחת השמי' ולא ישאר להם שום זכר ואם היה חוטא בזה האופן שבט או שבטים הנה יבדילו הש"י לרעה מכל שבטי ישראל ככל אלות הכתוב בספר התורה הזה ולהורות על הפלגת תחלואי השבט ההיא ומכותיה ובא הקללה בארצם וגלותם מעל אדמתם אמר שהדור אחרון שיהיה מהם וגם הנכרי שיבא מארץ רחוקה בראותם את מכות הארץ ההיא ותחלואיה יצדיקו הדין ויאמרו שכל זה הרע בא עליהם על עברם בברית הש"י ובאלתו ועבדו אלהים אחרים אשר לא ידעום אבותיהם ולא חלק להם הש"י שררה והנהג' על ישר' ואם חלק הש"י אותם לכל העמים שהם תחת ממשלתם ר"ל השמים והירח והכוכבים וצבא השמים ועל זה נתשם הש"י מעל אדמתם והשליכם אל ארץ אחרת כמו שהם היום הזה חוץ לארצם בארץ אחרת וזה ממה שיורה שהאיש שיסכים הש' יתעלה לכלותו לא השבט או השבטים ונדמה שזה כלו הוא על ירבעם ועשרת השבטים. והנה ירבעם היה האיש אשר היתה עצתו כך לפרוק מעליו עול תורה ולזה עשה לו שני עגלי זהב והנה בא ענשו שנמחה שמו מתחת השמים עד שלא נשאר לירבעם משתין בקיר וכן היה בשאר מלכי ישראל שאחזו דרכו ואמנם עשרת השבטים הגלה אותם ממלך אשור מעל אדמתם וקודם זה נהרגו מהם רבים מאד ומתו ברעב עד שלא נשארו מהם כי אם מתי מעט וגלה אותם מלך אשור לחלח וחבור נהר גוזן וערי מדי:
@813 **הנסתרות לה' אלהינו והנגלות לנו וגו'.** אמר זה כי אולי יחשוב חושב כי האדם יחטא אם לא יושגו לו כונות התורה ואם היה שהישירה אליו מקניין השלמות האנושי ואם היה כן היה בלתי אפשר שיהיה אדם צדיק בארץ שלא יחטא כי לא יוכל לעמוד על כונות התורה בשלמות ואם היה זה כן איך יתכן שיצוה השם יתעלה לשמור כל מצותיו ואם לא ישמרו כלם יגיע להם אלו העונשים הנפלאים והנה להסיר זה הספק אמרה תורה כי הנסתרות שבמצות התורה והם הפעולות אשר תכוין אליהם בהם מפני היותם על מה שהם עליו הם דברים לא יושגו על תכליתם כי אם לשם יתעלה לבדו ולזה לא ייוחס חטא לבלתי עומד על כונותיה ואולם הנגלות ממותיה והם הפעולות והדברים שצותה התורה לעשות או להמנע מהם הם חוב' לנו ולבנינו תמיד לדורותינו לעשו' כפי מה שגזרה התורה מהם. ומזה יתבאר שאין ראוי לאדם שיאמר הנה מפני שכונת התורה במצות כך להישיר אל דבר כך או להרחיק מדבר כך הנה אני שאני מתיישר באופן שלם אל הכונה ההיא אין חשש אם אעבור על זאת המצוה ולזה אמר הנסתרות להשם אלהינו להורות כי אין יכולת באדם לעמוד על כונות התורה בשלמות הלא הראה כי גם במצות שביארה התורה תועלותם חטא שלמה המלך בחשבו שהוא ישמר ממה שכונה התורה במצוה ההיא להרחיקו כי הוא הרבה לו נשים לחושבו שלא יטו לבבו רוב חכמתו וגודל מעלתו ונכשל בזה ובכלל הנה גם כן מה שזכרה התורה תועלת מצוה הוא אפשר שיהיה בה אצל הש' יתעלה תועלת אחר הלא תראה כי התורה זכרה במקום אחד במצות שבת תועלת אחת והוא שזכר לחדוש הש' יתעלה העלם ובמקום אחר זכרה בו תועלת אחר והוא שהוא זכר יציאת מצרים ולזה הוא מבואר שאין ראיה ממה שנזכר מהתועלת במצוה שלא יהיה שם תועלת אחר זולתו אצל השם יתעלה כ"ש במה שנזכר בתורה התועלת אבל עמדנו עליו על דרך החקירה והעיון והבן זה השרש כי הוא מגדולי השרשים התוריים לשמור חכמת התורה שלא יבאו שועלים ויפרצוה:
@814 **והיה כי יבאו עליך כל הדברים האלה.** הגיד בזה שאחר שיבאו כל אלה הדברים הברכה תחלה ואחר כך הקללה כי כן היתה שהברכה היתה בימי יהושע ובימי הזקנים האריכו ימים אחריו שלא נפל דבר מכל הטוב כמו שנזכר בספר יהושע וכן היתה להם הברכה בימי קצת השופטים ובימי שמואל ושאול ודוד ושלמה שבימי קצת שאר מלכי' אחרים ובית שני בימי החשמונים הנה כל אלו הקללות הדברים מהקללות שזכרנו ותשוב אחר זה אל לבבך בכל המקומות שאתה גולה בהם לשוב עד יי' אלהיך ולשמוע בקולו בכל המצוה אשר אנכי מצוך היום בכל לבבך ובכל נפשך שכל תוקתך וציוריך יהיו לעבוד הש' יתע' ותישיר לזה גם כן בניך כדי לחנכם בעבוד' השם יתעלה לידה ומבטן הנה ישיב את שבותך וירחם אותך. וזה ידמה שיהיה בבנין בית שני ולזה אמר אחר זה ושב וקבצך מכל העמים. רוצה לומר שישוב שנית לקבצך מכל העמים וזה הוא אחר חרבן בית שני כי בבית שני נתקבצו בזה האופן וגם אמר הנביא יוסיף השם שנית ידו לקנות את שאר עמו והפליג בזה ואמר שגם אם יהיה הנדח לגלות בגוים בקצה הישוב משם יקבצהו השם יתעלה ויקחהו משם ויביאהו אל הארץ אשר ירשו אבותינו וזה הוא אמרו אחד מעיר ושנים ממשפחה רוצה לומר כי אע"פ שלא יהיה כי אם אחד בעיר משם יקחהו השם יתעלה וישמרהו שלא ימיתוהו הגוים אשר הוא בקרבם:
@818 **והטיבך והרבך מאבותיך.** רוצה לומר שאחר ייטיב להם השם יתעלה וירבה אותם רבוי נוסף על רבוי אבותיהם:
@819 **ומל ה' אלהיך את לבבך ואת לבב זרעך.** זה יורה שהשם יתעלה יעזרם אז וימול את ערלת לבבם שתכסה ממנו השגת השם יתעלה וזה יהיה מצד המופתים הנפלאים שיראה אותם אז כאמרו כימי צאתך מארץ מצרים אראנו נפלאות וכבר רמזו הנביאים במקומו' אל המופתים שיחודשו בעת ההיא ומכללם הוא תחיית המתים ואז יהפוך הש' יתע' אל עמים שפה ברורה לקרא כלם בשם יי' ולעבדו שכם אחד והנה בזה יתיישרו כלם לאהבה את השם יתע' בכל לבבם ובכל נפשם למען חייהם רוצה לומר למען החיים האמתיים ישיגום באהבתם אותו בכל תשוקותיהם ובכל ציוריהם ואז יתן הש' יתע' את כל הקללות האלה על האויבים ועל השונאים שרדפו ישראל בגלות ובכלל הנה אתה כשתשוב אל השם יתעלה ושמעת בקולו לעשות כל מצותיו מבלי גרעון אז תבא הברכה לך בבני' ובקניני' כאשר באה לאבותיך והנה ביאר בכל זה תכלית הביאור כי כשיתקיימו המצות שהוא נותן היום והם הכתובות בספר התורה הזאת יהיה להם כן וזאת ראיה זאתה התורה לא תומר ולא תשתנה לעולם וזו פנה גדולה מפנות התורה:
@824 **כי המצוה אשר אנכי מצוך היום.** אמר שהמצוה הזאת אינה בשמים שיצטרכו לביאור בה על יד הנביא כי מה שראוי להיות בה נכלל מזאת התורה ואינו גם כן מאופן מהעומק שיצטרכו לשופט:
@826 **מעבר הים.** להבין דבריה כי המצוה מעניינה והיא עשית המצוה הוא דבר קל מאד להגיד אותו בפה ולצייר אותו בלבבו וזה כי לא צותה התור' להעמיק העיון בה עד שיעמדו על כונותיה לפי מה שאפשר אך בטחה כי זה יתכן שישלם עם מה שהישירה אליו בזה הענין הבדל הכהנים והלוים לעבודת השם יתעלה כמו שביארנו במה שקדם:
@828 **ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע.** הנה החיים הם חיים הנפש כי הם החיי' האמתיים והטוב הם ההצלחות הגופייות כי הם גם כן ימשכו מקייום התורה כמו שקדם אבל התכלית העצמי לזה הוא החיים ואלו הטובות ג"כ הנמשכות מקיום מצות התורה הם מישירות אל השגת החיים ההם כי מי שהוא חסר להם ושלמה לא יתכן לו התבודדות בעיון באופן שלם והם המות והרע הם הפך שני אלו והם ימשכו מעזיבת התורה כי הוא יביא לעבוד עבודה זרה כמו שזכר:
@832 **העידותי בכם היום את השמים ואת הארץ.** נתן אותם לעדים כי הם קיימים להעיד שתמיד יתקיימו אלו הדברים עם שהם כמו עוזרים להמשיך זה כאלו יאמר שהשמים והארץ כלם יעזרו להגיע כל אלו הדברים מהברכות והקללות על דרך הכוכבים ממסילות' נלחמו עם סיסרא:
@832 **החיים והמות נתתי לפניך.** הזכיר לזכור תחילה החיים והמות האמתיים כי הם הגמול והעונש אנושיים ואחר זכר הברכה והקללה שהם הטוב והרע להיותם בלתי מכוונים בעצמות ואע"פ שכבר ימשכו מקיים מצוו' התור' והנטייה מהם. ולזה אמר ובחרת בחיים ולא אמר ובחרת בברכה כי אין ראוי לעבוד השם יתעלה כדי שיגיעו אלו הטובות הגופיות אך יעבדהו כדי שישיג החיים הערבים ההם כמו שאמר דוד תודיעיני אורח חיים שובע שמחות את פניך נעימות בימינך נצח ולזה אמר דוד במצוותיו חפץ מאד ולא בשכר מצותיו הנמשך באלו הטובות והקנינים הגופיים:
@833 **לאהבה את יי' אלהיך לשמוע בקולו ולדבקה בו כי היא חייך.** אמ' כי זה הוא בעצמותו חיי האד' והוא מבואר במה שאין ספק בו כי השגת השי"ת אשר בה תשלם אהבת האדם אותו לשמוע בקולו ובה ישלם לו הדבקות בו הוא החיים הנצחיים אשר לא יבלו ואמר אחר זה ואורך ימים לשבת על האדמה כי זה הטוב ימשך ממנה גם כן עם שהו' מישיר אל שיושגו החיים ההם באופן יותר שלם מפני היות הארץ מוכנת אל שידבק בה לאדם השפע האלהי כמו שזכרנו פעמים רבות:
@834 **וילך משה וידבר את כל הדברים האלה.** רוצה לומר הדברים הנזכרים עתה בסמוך עד אמרו לא ירפך ולא יעזבך:
@838 **ועשיתם להם ככל המצות אשר צויתי אתכם.** ר"ל מה שצוה בסוף פרשת שפטים לקרא להם לשלום תחלה באופן הנזכר שם ואם לא יסכימו להשלי' ויכונו להלחם כנגד ישר' יחרימום באופן הנזכר שם ויתנהגו בדבר לפי המצוה הנזכרת שם אך אם לא ישלימו וגם לא ירצו להלח' עם ישר' אך ירצו לברוח לא נצטוו להרגם. וזה מבואר ממה שנזכר שם ולזה גם כן חוייב במצור שיניחו להם מקום יוכלו לברוח ממנו כמו שזכרנו בפרשת שופטים:
@840 **ויקרא מהשה ליהושע ויאמר אליו לעיני כל ישראל.** אמר זה לעיני כל ישראל כדי שיבטחו בו יותר ויכנסו לעשות מצותו:
@842 **ויכתוב משה את התור' הזאת ויתנה אל הכהנים בני לוי.** ידמה שזאת התורה שזר שכתבה משה ונתנה אל הכהנים ואל זקני ישראל היא זולת אשר כתבה לפי מה שנזכר אחר זה שנתנה ללוי' לתת אותה מצד ארון ברית יי' כי זאת היו קוראים בה הכהנים והזקנים והאחרת היה מונחת אצל ארון ברית יי' וידמ' שכתב משה מהם יותר מאחד כי לא יתכן בספר אחד שיספיק לכהנים ולכל זקני ישראל ולזה הסכימו רז"ל שכתב ספר אחד לכל שבט ושבט או יהיה הרצון באמרו כל זקני ישר' השבעים זקני' שהיו סנהדרי גדולה כי היו עומדים אצל הכהנים כמו שקדם:
@843 **ויצו משה אותם לאמר מקץ שבע שנים במועד שנת השמטה בחג הסוכות.** צוה לקרא את התורה הזאת באזני העם האנשים והנשים והטף וגרי הצדק אשר עמהם כדי שיתחנכו כלם לעבודת הש"י ולא תשכח התורה מישראל ואמר כל הימים אשר אתם חיים על האדמה להורות על נצחיות התורה:
@847 **ויאמר יי' אל משה הן קרבו ימיך למות.** צוה לקר' יהושע בזאת הנבואה לצותו שיחזק ויאמץ להתנהג במצות התורה כי הוא יביא בני ישראל אל הארץ ולזה אמר לו ואנכי אהיה עמך להעזר שאלו הדברים הגיעו למשה אז בנבואה ובשליחו' הש"י אמרם אמנם הוצרך לזה לפי ששאר הדברים שזכר פה אמרם הש"י בהר חורב ולזה היה אפשר שיכנס בזה הענין ספק ליהושע שמא אינו במדרגה שיהיה ראוי שתשלם על ידו ירושת הארץ לישראל כי אולי לא השלים נפשו למה שהיה אפשר לו או נתחדש אחד משאר הדברים המונעים ממנו זה ולזה הוצרך שיאמר לו זה הש"י עתה להורות שהוא עתה ראוי לזה:
@849 **אחרי אלהי נכר הארץ.** ר"ל אחרי אלהי נכר עם הארץ:
@850 **והסתרתי פני מהם והיה לאכול.** ר"ל שאסלק השגחתי מהם ויהיה מוכן לכליון ומצאוהו מפני זה רעות רבות וצרות שלא היו דבקו' בו בהיות השגחתי בהם והנה זה הייעוד הוא היותר קשה מכל הייעודים הקודמים כי שאר הייעודים הרעים הם ע"ד ההשגחה לתוכחת ואולם זה הוא ע"ד העזיבה וסור ההשגחה הפרטית בכללות ואמר שאף על פי שישוב ישראל ויכירו כי מפני סור השגחת הש"י מהם קרה להם זה וישובו אל יי' הנה יסתיר הש"י פניו מהם בעבור הרע שעשו לעבוד ע"ז וזה דבר ידמה שהיה תכף מות יהושע והזקנים שהאריכו ימים אחריו שעבדו ישר' ע"ז ונתנם ביד שוטיה' ותמצ' בקצתם שכאשר צעקו אל יי' קצרה רצונו משמוע צעקת' בעבור עמל ישראל שפנו אליו והוא מה שהלכו אחרי אלהים אחרים שעניינם הוא עמל ואון:
@852 **ועתה כתבו לכם את השירה הזאת ולמדה את בני ישראל שימה בפיהם.** כבר נתבאר אחר זה שהשירה היא דבר התורה בכללם עד תומם שנ' ויכתוב משה את השירה ויהי ככלות משה לכתוב את דברי התורה הזאת על ספר עד תומם וזה מעיר שהשירה הזאת רצה בו כל דברי התורה בכללם וגם השירה עמהם והנה ירה שזה הוא ענין התורה בכללה שנא' לקוח את ספר התורה הזאת ושמתם אותו מצד ארון ברית יי' וכן תמצא אחר זה שאמר הקהילו אלי את ראשי שבטיכם ושטריכם ואדברה באזניהם את כל הדברים האלה וזה דבר אינו שיאמר על דברי השירה לבדם והנה אמר ג"כ וידבר משה באזני כל קהל ישראל את כל דברי השירה הזאת עד תומם ואמר בסוף ויכל משה לדבר את כל הדברים האלה אל כל ישראל ויאמ' אליהם שימו לבבכם לכל הדברים אשר אנכי מעיד בכם היום אשר תצוום את בניכם לשמור ולעשות את כל דברי התורה הזאת וזה כולו ממה שיורה בלי ספק שהכונה במה שאמר כתבו לכם את השירה הזאת היא כוללת כל דברי התורה והשירה עמהם עם שהוא מן השקר שתדקדק התורה בלמוד השירה הזאת לכל ישראל ובכתיבתה יותר מדקדוקה בזה בשאר הדברים היותר הכרחיים אשר בתורה ולזה היתה הצואה הזאת שיכתוב כל אחד ספר תורה לעצמו והשיר' עמו בדרך שלא יחסר ממנו דבר מהדברי' בספר התורה והנה צוה משה שילמדה לבני ישראל ר"ל לבאר את מצוותיה ועניניה בדרך שתהיה שומה וסגורה בפיה. ואם אמר אומר שהצואה היתה בזה בשירה לבד הנה יתבאר מזה בק"ו שכל שכן שיחוייב זה בשאר דברי התורה:
@854 **כי לא תשכח מפי זרעו.** למדנו מזה שלא תשתכח תורה מישראל בעת מהעתים:
@855 **ויכתוב משה את השירה הזאת ביום ההוא.** יתכן שהשאר היה נכתב קודם ולמדו לישראל באמרו והודעתי להם את חקי האלהים ואת תורותיו. ולזה לא הוצרך כי אם לכתוב השירה וללמדה לישראל ולזה אמר ויהי ככלות משה או היה זה ע"ד שאר המופתים שנשלם לו כתיבת כל התורה ביום ההוא והנה צוה לקחת את ספר התורה הזאת ולשים אותו מצד ארון ברית יי' להורות שכולו היה מפי הגבורה כמו שהיו עשרת הדברים אשר בארון מפי הגבורה והנה צוה להקהיל אליו כל הזקנים והשוטרים להגיד להם את כל דברי התורה ולהבין אותה להם והם ילמדו לישראל הנה זה ביאור מה שצריך לבאר מזאת הפרשה:
@865 **לקחי.** ר"ל תורתי כאמרו כי לקח טוב נתתי וגו' ונקראת לקח מפני לקיחת הנפשות לעשות מצותיה ובזה נתייחדה התורה הזאת מהנימוסים האחרים ססכי הם לא יקובלו כי אם מצד ההכרח ויראת העונש אך דברי התורה הם ישרים ומשפטיה צדיקים עד שהם בעצמם ימשכו האדם אל ההמשך אחריהם:
@865 **אמרתי.** הם ספורי התורה כי הם רבי התועלת כמו שזכרנו:
@865 **שעירים ורביבים.** הם מינים מהמטר הדק שיפרו וירבו העשבים:
@866 **הבו גודל לאלהינו.** ר"ל תנו גודל לאלהינו. והנה אמר זה אל השמים והארץ כי הם מפעולות השם יתע' ויוכר בהם מקצת גודל השם יתעלה מצד השלמות הנמצא בהם ובמה שיפעל בהם בכללות:
@867 **הצור תמים פעלו.** רוצה לומר השם יתע' שהוא בורא הכל הנה פעלו הוא שלם בתכלית השלמות האפשרי לו:
@867 **אל אמונה ואין עול.** לפי שכבר אמר שכל דרכיו מפשט לא היה צריך לומר אל אמונה ואין עול אם היה הרצון שאינו עושה עול כי מי שכל דרכיו משפט הוא מבואר שאינו עושה עול ועוד כי הוא אמר אחר זה שהוא צדיק וישר ולזה ידמה שתהיה בזה שב אל פעלו רוצה לומר שהוא בפעולותיו מנהיג ומסבב ההגעה אל היושר והאמת ואינו מנהיג ומסבב מה שיהיה בו עול. והמשל כי אע"פ שברא האדם אשר בו כלי' יובילוהו לחטא במקרה הנה השם יתע' לא פעל העול בזה כי הכלים אשר שם בו הם כלים מישירים בעצמות אל קנין השלמות והיושר והאמת ולזה היה לקוח בגדרם ואולם יסבבו לחטא במקרה מפני רוע בחירת האדם:
@868 **שחת לו לא בניו מומם.** לא בניו ר"ל שאינם נולדים ומתחדשים מהשם יתע' והרצון בזה כי הדור עקש ופתלתול לנטות אחר החטאים והפעולות המגונות הוא בעצמו:
@868 **שחת לו.** רוצה לומר כי מידו היתה זאת לו ואין מומם וגנות פעולותיהם נולדים ומתחדשים מהשם יתע' ולזה אין להם התנצלות באלו החטאים:
@869 **עם נבל ולא חכם.** רוצה לומר עם שהשתמש בהכנתו ששם בו השם יתע' להגיע אל החכמה והשלמות בעשיית הנבלות והחטאים המגונים מאד ולא השתמש בה במה שהיא נבראת בעבורו והוא השגת החכמה:
@869 **אביך קנך.** רוצה לומר אביך שהוליד אותך ובראך וקנה אותך להיות לו לעם במה שהוציאך מבית עבדים:
@869 **הוא עשך ויכוננך.** רוצה לומר שהוא עשה אותך במה שלמדך תורתו כאמרו ואת הנפש אש' עשו בחרן וכונן אותך בה והשלימך לתכלית שתהיה לו לנחלה:
@870 **שאל אביך ויגדך.** מפני שמה שזכר זאת ההגדה הם ענינים נעלמים והמושג בהם בחוש לא הצטרכו לשאול לאחרים כי הם בעצמם ראו זה כמו שיתבאר מהנמשך הנה יהיה הרצון באביך בזה המקו' המנהיג והוא הנביא כאמרו והוא מצעק אבי אבי רכב ישראל פרשיו ולזה אמר אחריו זקניך ויאמרו לך שהם החכמים והזקנים והנה המנהיג יקרא אב כאמרו וישימני לאב לפרעה:
@871 **יצב גבולות עמים למספר בני ישראל.** רוצה לומר שהוא הקים גבולות עמים למספר בני ישראל שהיו י"ב והרצון בזה שגבולותיהם בארצותם שנחלו הם לפי ממשקל המזלות המיוחדים לאומה ואומה והם י"ב ולזה לא היו אלו הגוים תחת ממשלת הככבים:
@873 **ימצאהו בארץ מדבר.** ר"ל שישראל מצא השם יתע' בארץ מדבר כי שם נראה לו עוצם אהבתו אותו והשגחתו בו עד שהאכילו מן במדבר ארבעים שנה ולא בלתה שמלתו מעליו ולא נעלו מעל רגליו:
@873 **ובתוהו ילל ישימון יסובבנהו יחוננהו.** רוצה לומר שהשם יתע' היה לו לחומה סביב לשמרו מכל דבר או יהיה יסובבנהו שב אל המדבר והוא יוצא לשלישי והרצון בו שהשם סבב שיהיה ישראל סובב במדבר ההוא זה הזמן הארוך כאמרו רב לכם סוב את ההר הזה להועיל לישראל כמו שזכר במה שקדם:
@873 **יצרנהו כאישון עינו.** רוצה לומר כמו שישמור השםי תע' עינו של אדם שהקיף אותו הלחויות והכתנות ההם השומרות אותו והעפעפיים להיות לו למחסה או ירצה בזה שכבר שמר אות' כמו שישמור האדם אישו עינו והביאור הראשון הוא יותר נכון לפי מה שאשחוב והעיר על זה כי כמו שהעין להיות החוש היותר נכבד הכי לו השם יתע' שמירה יותר חזקה ויותר נפלאה מפני היותו קל לקבל הריעועים כן השתדל השם יתע' לשמור בכל עוז ישראל בהיותם במדבר להישירם אל הטוב מפני היותם מוכנים מאד לנפול ברוע התכונות והאמונות:
@874 **על גוזליו ירחף.** רוצה לומר ינוח וכן אמרו ורוח אלהים מרחפת על פני המים רוצה לומר נחה כמו שביארנו שם או יהיה הרצון באמרו ירחף יעופף והרצון בו שהוא יעופף אצל גוזליו למדם העופפות ולהרגיל בו:
@874 **יקחהו.** רוצה לומר הקן:
@876 **ירכיבהו על במתי ארץ.** רוצה לומר שינחילהו ארץ כנען שהיא גבוהה:
@876 **ויניקהו דבש מסלע.** רוצה לומר מהמקום שהוא בלתי ראוי לצאת ממנו דבש וזה רמז לארץ סיחון שזכו ישראל על ידו להיות להם קצת ארץ מואב ובני עמון ולולי היותם מסיחון לא היו זוכים בו כי כבר הזהירם השם יתע' שלא יגעו בנחלת מואב ובני עמון ואפשר שאמר זה על כל ארץ ישראל כי לא היתה ראויה להם עדיין לולי דבקות ההשגחה האלהית בהם ולזה אמר שהאכילם דבש מסלע:
@876 **ושמן מחלמיש צור.** והוא הסלע החזק:
@877 **חמאת בקר וחלב צאן.** קרא חמאת בקר שלל ענקים וחלב צאן שלל יתר הגוים אשר בארץ כנען החלושים מהם וקרא חלב כרים הממוצעים שאינם מהחלושים ולא מהיותר חזקים כמו שהכרים הם יותר חזקים מהצאן וקרא אילים בני בשן ועתודים והם זכרי העזם עוג מלך הבשן וסיחון מפני יתרון חזקם:
@877 **חלב כליות חטה.** הוא בטעם חלב דגן שהרצון בו הנבחר שבו וזכר החטה ודם ענב להיותם המשובחים שבשבעת המינים המיוחסים לארץ ישראל ואמר כליות חטה להורות על שבח החטה שבארץ ישראל והוא ידוע שהחטה היא בצורה כוליא:
@877 **ודם ענב.** להורות על אודם היין אשר שם והוא שבח ליין כאמרו אל תרא יין כי יתאדם וכאלו אמר שמדם הענב האחד יהיה בו די לשתות יין ואמר כליות חטה ודם ענב להעיר על שלל החלושים מאד מצד היותם מעטים עד שהיו כמו מים כמו שאין בחטה ובענב חיות הנה עם כל זה היה לישר' מהם שלל רב כאמרו ובתים מלאים כל טוב אשר לא מלאת והיה זה כן לפי שכלם היו עשירים מצד שבח ארץ ישראל ונתינת פריה' לרוב ברוב השנים כמו שנתבאר במה שאמר ארץ אשר יי' אלהיך דורש אותה:
@878 **שמנת עבית כשית.** ידוע כי השמן ימשך לו מרוב השומן שהיו אבריו יותר עבים ויהיה כוסה בחלבו בשרו ואיבריו הפנימיים כטעם כי כסה פניו בחלו:
@878 **ויטוש.** ויעזוב:
@878 **וינבל צור ישועתו.** עשאו נובל ולואה מעשות כל אשר יחפוץ כטעם נבול תבול כמו שאמר הנביא המעט מכם חלאות אנשים כי תלו אכם את אלהי:
@879 **יקניאוהו בזרים.** ר"ל יכעיסוהו באלהי' זרים שיעבדו אותם:
@880 **יזבחו לשדים לא אלוה.** ר"ל לדמיונים שחשבו בהם שהם אלוהות כאמרו ויחפאו בני ישר' דברם אשר לא כן על יי' אלהיהם כאלו תאמר שהם כמו שיהיה אלוה מה שאינו נמצא כן אבל הוא דמוי לבד והנה שדים ושעירים הם אחים ולזה אמר ולא יזבחו בני ישר' עוד את זבחיהם לשעירי' אשר הם זונים אחריהם והנה הכונה בשניהם הדמות הדמוים הכוזבי' כי ענין מציאו' השד הוא דמיון לבד ולזה אמרו רז"ל לאחד נראה ומזיק לשני' נראה ואינו מזיק לשלש' אינו נראה ואינו מזיק ואלו היה ענין שהיה לו מציאות בעצמו היה נראה לשלשה כמו שהו נראה לאחד או לשני' ולזה יהיה אמרו לא שערום אבותיכם שלא דמ אותם הדמיוני' אבות שלהם או יהיה פירושו שלא אחזו שער אחד מהם הקודמים ולא ייראו אותם מעשות מהם אלהות:
@881 **צור ילדך תשי.** הבורא שברא אותך והשלימך תשכח ואמ' ילדך כי הבריאה תהיה תחילה ברחם וכאש תשלם ההוייה האפשרית שם תהיה הלידה והנה זה השלמות שהשלימם השם יתע' אשר בו יתכן שיאמר שילדם הוא נתינת תורתו השלימה מהם מצורף על זה מה שתראה אותם מאותותיו ונפלאותיו בהודיעם כי הוא יי':
@881 **ותשכח אל מחולליך.** ר"ל שכבר שכחת אל שיצרך והתחיל ההוייה בך להובילך לגבול השלמות והוא מה שעשה מהאותות והנפלאות במצרים ועל הים כדי שיהיו ראויים לקבל התורה:
@882 **וירא יי' וינאץ מכעס בניו ובנותיו.** הנה וינאץ הוא יוצא כטעם וינאץ בזעם אפו מלך וכהן והרצון בו שהשם יתעלה נאץ בניו ובנותיו ומאסם מרוב כעסו על חטאיהם:
@883 **לא אמון בם.** אין אמונה בהם ר"ל שאין בם דבר אמת אבל בוחרים התהפוכות והם הכזבים שהם הפך הנמצא:
@884 **קנאוני בלא אל.** ר"ל הכעיסו אותי בעבדם מה שאין לו שום חלק באלהות והוא הע"ז:
@884 **אקניאם בלא עם.** אכעיס אותם באומה שאינה עם כי היא כל כך פחותה בתכונות ובמדות ובאמונה שאין ראוי שישלם בה הקבוץ המדיני באופן שתהיה לעם וזהו אמרו בגוי נבל אכעיסם:
@885 **קרחה.** נתחממה ובערה:
@885 **ותיקד עד שאול תחתית.** ר"ל שחרון אפי תוקד בהם עד בואם אל הקבר לא יסור מהם:
@885 **ותאכל ארץ ויבולה.** ר"ל שחרון אפי ישחית הארץ ויבולה בדרך שימותו ברעב כמו שקדם בדברי הקללו':
@885 **ותלהט מוסדי הרים.** ר"ל ותשרוף מוסדות הרים הבצורות כמו שאמר עד רדת חומותיך הבצורות הם נקראו הרות כאמרו על בקעם הרות הגלעד. ההרותיה בקע החרותיהם תבקע ולזה קראם הרים בכל המקו' והנה קראה הרי' והרות כי החזקות שבהם תכנינה בהרים הגבורים:
@886 **אספה.** אכלה:
@886 **חצי.** רמז אל הצרות והמכות והעיר בזה שהם יתיישרו להכותם כמו שיתיישר החץ אל המקום אשר יורוהו וזה לאות כי המכות האלה לא יבואו עליהם בקרי:
@887 **מזי רעב.** אחשוב שיהיה ענינו כמו מסי בחלוף סמ"ך בזי"ן להיות קרבי' במבטא והם ממוצא אחד וענינו התכות רעב כי בסבת הרעב יתך הגוף וימס ובזה הורה על מיני הרעב וחזקו והנה יעשה מן מסה מסי כמו שיעשה שם הקבוץ מן פנה פני ומן בנה בני ומן שנה שני:
@887 **ולחומי רשף.** הנה לחומי רשף הוא מעניין אמרו ולחמם כגללים והוא הבשר ואמר שהרשף והוא האש ימשול בבשרם והרצון בו החום הנכרי השורף אשר ממנו היו מיני הקדחות שזכר בעניין הקללות וכאלו אמר שישלח בהם התכות הרעב שימס בהם בשרם וזה מן אחד מן הצרות הרעות והוא קשה מאד כאמרו טובים היו חללי חרב מחללי רעב ואחר זכר המין השני מהם והוא הדבר והנה זכר הקדחת השורפת תחילה כי היא מביאה אליו:
@887 **וקטב מרירי.** קטב הוא מעניין כריתה. ומרירי הוא האויר העולה מן הארץ בקצת העיתים עם חזק החום והוא ממית כשהיה טבע הדבר נתך ממנו וזהו עניין אמרו מקטב ישור צהרים והרצון בו הכריתה שתתחדש בסבת עפושי האויר וקראו מרירי לפי שמגבוה תהיה סבת אלו העפושים הכוללים והוא מפאת חום השמש והככבים שיהוו אלו ההויות בבטן הארץ ויעלו משם בקצת העיתים אלו האידים המפסידים:
@887 **ושן בהמות.** הנה יכלול שם הבהמה החיות כמו שנזכר בפר' ראה אנכי זאת הבהמה אשר תאכלו וזכר אחר זה מיני החיות:
@887 **חמת זוחלי עפר.** הוא ארס השרצים ההולכים על גחונם כמו הנחשים והדומים להם:
@888 **מחוץ תשכל חרב.** ר"ל כי בהיותם בחוץ ימותו בחרב ובהיותם בחדרים גם משם תפול עליהם אימת מות ליראתם בא האויבים עליהם:
@888 **גם בחור גם בתולה.** ר"ל שהחרב תשכלם כלם בחור ובתולה יונק עם איש שיבה ולא יחמול האויב על אחד מהם:
@889 **אפאיהם.** ר"ל אפאה אותם לפאות העולם ויהיו מפוזרים בתכלית הפזור ובה יהיה הקלו':
@889 **אשבית מאנוש זכרם.** מזולתי הבאתי עליהם מיני הרעות הנזכרים אך בחר השם יתע' בהבאתם כדי שיוכר כי מיי' היתה זאת הסבה:
@890 **אגור.** אירא כטעם לא תגורו מפני איש והנה אמ' זה לדבר כלשון בני אדם:
@891 **כי גוי אובד עצות המה.** שב אל ישר' והרצון בו שאי' בהם עצה וחקירה ישפטו בה בדברי' ולפי מה שבהם:
@894 **ואויבינו פלילים.** ר"ל שאויבינו עצמם שופטים:
@894 **כי לא כצורינו צורם.** ואמר צורם לפי הנחשב בהם אצלם שיהיו אלוהות ולזה תמצא שאמרו פלשתי' או לנו מי יצילינו מיד האלהי' האדירים:
@895 **כי מגפן סדום גפנם.** ר"ל כי הגפן המגדלת הפירות שלהם היא יותר רעה מגפן סדום וקרא האומה גפן וכן עשה בישראל כאמרו גפן בוקק ישר' ואמר כרם היה לידיד לפי שהכרם יעבדוהו עבודות רבות ובאמצעותם יתנו הגפנים פרים וכן האומה ישתדלו בתקון עניניה ונתינת פרים במוסרים והאמונות אשר יביאום להתנהג בהם וכאלו אמ' שאמונותיהם ונימוסיה' הם בתכלי' הרוע עד שקבוצם יותר רע מקבוצי סדום ועמורה אשר שפטם הש"י כמו שנתפרסם ענינו בתורה והפרי המתחדש בהגפן הזאת הוא בתכלי' הרוע והמרירו' והם הענבים והיין ההווה מהענבים הוא כמו ארם התנינים שהוא ממית בקלו':
@896 **וראש פתנים אכזר.** עניינו וחמת ראש התנינים והוא האכזרי שבהם שהוא משחית וממית בתוקף:
@897 **כמוס.** גנוז:
@898 **לי נקם ושלם לעת תמוט רגלם.** אמ' שהנקם אשר לשם יתע' להנקם מכל עושי הרעו' ישלם לאויבי' ברוע מעלליהם לעת תמוט רגלם שיהיה ראוי לבא עליהם הרע מצד ההשגחה הכוללת כי אז יענשם השם יתע' ולא ינצלו מהרע ההוא:
@898 **כי קרוב יום אידם.** ר"ל שזה יהיה כאשר יקרב יום אידם והנקם אשר לי יחיש העתידות למו מהרעות וימהר בואם:
@899 **כי ידין יי' עמו ועל עבדיו יתנחם.** ר"ל כי ישפוט הש"י עמו ויסרם להדיחם עליהם הרעה הזאת על רוע מעלליה' כטעם כי בם ידין עמי' הנה בעבור עבדיו והם האבות יתנחם וימשוך ידו וישיבה מהשחית אותם בכללו' כאמרו ואף גם זאת בהיותם בארץ אויביהם לא מאסתים:
@899 **כי אזלת יד.** ר"ל שהלך כח ישראל:
@899 **ואפס עצור ועזוב.** ר"ל שכרו כל קניניהם העצורים בבית והם האוצרות והעזוב בשדה והוא המקנה ופירות הצמחים ואפשר עם זה שיקרא עצור מה שאין דרכו להיות עזוב והם הערים הנצורות ועזוב יהיה ערי דפרזי עד שלא ישאר מן הארץ שיחזיקו בו והנה זה הביאור השני היותר נכון לפי מה שאפשר:
@900 **ואמר אי אלהימו צור חסיו בו.** ר"ל שהש"י יאמר אז לישראל איה התועבות אשר עשו מהם אלהות ומה שהוא צור לפי מחשבתם אשר חסו בו כאלו יאמר שלא היה כח באלה העבודות זרות לשמרם אך הם היו סבה לנפילתם ברע:
@901 **אשר חלב זבחיהו יאכלו.** כבר מצאנו ג"כ זה העניין נזכר בהצמד ישר' לבעל פעור שנאמר ותקראנה העם לזבחי אלהיהן ויאכל העם למדנו משם שאין ראוי לאכל מזבחי תקרובת ע"ז ולזה גנה אותם בזה המקום ואמר שהם אוכלים חלב הזבחים שנזבחו לע"ז:
@901 **ישו יין נסיכם.** מפני שגנה אותם בזה העניין למדנו משם שאין ראוי לאכל מזבחי תקרובת ע"ז ממה שאנחנו מוזהרים משתיית יין נסך שנתנסך לע"ז:
@901 **יקומו ויעזרוכם.** ר"ל האלהי' ההם והם הע"ז שאל ידם רמז באמרו אי אלהימו:
@901 **יהי עליכם סתרה.** ר"ל שהצור שחסיו בו. והיא ע"ז שהיא צור לפי מחשבתם יהי עליהם למסתור ולמחסה מאלו הרעות אמר זה להורות שאין בם כח להטיב אך באמת הם הסבה בנפילתם ברע:
@902 **ראו עתה כי אני אני הוא.** ר"ל כי אני הוא בעניין אחד תמיד בזולת שנוי. ואני מי שהוא תמיד ואין לי סבה קודמת:
@902 **אני אמית ואחיה.** אמר זה להעיר שהוא הביא עונש המות לישראל על חטאיהם והוא יהיה אותם אחר זה ימחץ וידיו תרפינה ולזה אין לחשוב שיהיו שם שני אלהות האחד פועל הטובות והאח' פועל הרעות כמו שחשבו המצריים וטעו בו קצת ישר' כמו שזכרנו במה שקדם ולזה אמר ואין אלהים עמדי:
@903 **כי אשא אל שמים ידי ואמרתי חי אנכי לעולם.** הוא שבועה. לדבר בלשון בני אדם כי השמים חוקי הקיום מצחד מה שנתן להם הש"י מהכח ביום הבראם וכן אמרתי חי אנכי לעולם הוא על דרך אמרו ואולם חי אנכי וימלא כבוד יי' את כל האר':
@904 **אם שנותי ברק חרבי ותאחז במשפט ידי.** ברק החרב הוא הברזל אשר בו שיברק כשלוטש ושנונו הוא השחזת חודו כדי שיהיה נאות לחתוך בקלו' והרצון בזה אם יהיה שנון ברק החרב שלי להביא רעה על האויבים וזה היה לעת תמוט רגלם כמו שקדם:
@904 **ותאחז במשפט ידי.** ר"ל או תאחז במשפט ידי וזה יהיה אם היו באופן שתדבק בהם השגחתי:
@905 **מדם חלל ושביה מראש פרעות.** אויב הוא שב אל מה שאמ' אשיב נקם לצרי והרצון בזה שישיב נקם לו ממה שהרע בישראל מדם חלל שהרג בהם ומחמס השביה השבה מהם ומה שהרע להם במה הפריעם והשביתם מעשות מצות התורה או יהיה שב אל אמרו אשכיר חיצי מדם אמרו מדם חלל ושביה ואמרו מראש פרעות אויב יהיה שב לאמרו וחרבי תאכל בשר וירצה בזה שחרבו תאכל בשר מהנבחר שבפרעו' האויב שנשבית העברת התער עליה' על רוע מעלליהם כי לא תמוט רגלם עדין:
@906 **הרנינו גוים עמו כי דם עבדיו יקום.** ר"ל שבחו הגוים עמו כאשר יקום דם עבדיו כאמרו אז יאמרו בגוים הגדיל יי' לעשות עם אלה:
@906 **וכפר אדמתו עמו.** ר"ל וטהר אדמו אדמת עמו כטעם וכלה מכפ' את הקדש שהו' מענין טהרה כאמרו וטהרו וקדשו מטמאות בני ישראל או יהיה הרצון בזה וכפר אדמתו עמו רוצה לומר שיטהר טומאת אדמתו וטומאת עמו:
@916 **משה איש האלהים.** ר"ל נביא השם ומצד שהוא נביא ברכם בזאת הברכה והיא היתה להוסיף עליהם טוב מה מתייחס אל הטוב הראוי לבא אליהם או למעט הרע הראוי לבא עליהם כי בכמו זה תועיל ברכת הנביא כמו שביארנו בפרשת תולדות יצחק:
@917 **ה' מסיני בא.** ר"ל ממעמד הר סיני בא הש' לישראל לתת להם תורת והתמימה:
@917 **וזרח משעיר למו.** ידוע כי ישראל סבבו את הר שעיר כל אותם הימים שנתאחרו במדבר אחר דבר המרגלים או רובם כאמרו בפרשת ואלה הדברים ונסב את הר שעיר ימים רבים והנה שם זרח לישראל אור השם יתעלה מפני ראותם עוצם המופתים והנפלאות שעשה להם השם יתעלה במדבר להאכילם מן מ' שנה ושלא בלו שמלותם מעליהם ולא נעליהם מעל רגליהם בכל הזמן הארוך ההוא עד שמשם התחילה הישועה לצמוח לישראל כאמרו רב לכם סוב את ההר הזה פנו לכם צפונה ומן אז התחילו להשתדל במלחמת הגוים אשר נצחום מעבר הירדן מזרחה:
@917 **הופיע מהר פארן.** ידמה שהר פארן הוא הר שעיר והנה כונת אמרו הופיע הוא כמו אמרו וזרח משעיר למו כי הרצון באמור הופיע הראה יפעתו וזיהרו:
@917 **ואתה מרבבות קדש.** הוא ביאור מה שאמר תחילה ה' מסיני בא רוצה לומר שבאו שם והגלותו על ישראל כדי שישמעו כלם דברי התורה מפיו היה מתחדש מרבבות קדש והנה קרא כלל ישראל רבבות קדש להיותם עם קדוש ולפי שכלם הסכימו בזה ואמרו את כל אשר ידבר השם נעשה ונשמע כמו שביארנו בפרשת וישמע יתרו והוה מספרם רבבות רבות כי הם היו ששים רבוא אמר שמרבבות קדש סבב הדבר הזה ותהיה מ"ם מרבבות קדש כמו מ"מ מחטאת נביאיה שהרצון בו בסבת חטא נביאיה:
@917 **מימינו אש דת למו.** רוצה לומר שמימין השם יתעלה והוא היד שייוחס לה עשיית הנפלאות על דרך ההשגחה חדש אש נפלא שהשמיע ממנו דת למו בקול הנפלא שחדש בו על דרך המופת:
@918 **אף חובב עמים.** אחשוב שהוא מענין ההסתר וההתחבאות וכמוהו לטמון בחבי עוני ויהיה חובב וחבב שני שרשים בענין אחד וכן תוכו מענין תוך ויהיה תכה תכך שני שרשים בעניין אחד והנה ידוע כי ישראל בשמעם הדברים מפי הגבורה יראה ממנו ועמדו מרחוק ואמרו למשה דבר אתה עמנו ונשמעה ואל ידבר עמנו אלהים פן נמות ואז אמר הש' יתע' למש' לך אמור להם שובו לכם לאהליכם ואתה פה עמוד עמדי והנה הרצון באמרו מדברותיך דבריך והוא כמו מדברותיך כי הדבר יקרא מדבר כאמרו ומדברך נאוה והרצון בזה הפסוק הוא כן שהיה חובב ימינו הרבבות והעמים ההם מפני פחד האש הגדולה כי אז נתחבאו כלם ולא רצו לראות המראה הגדול כמו שנזכר בפרשת וישמע יתרו הנה נשאר עם זה כל קדושיו בידיך לשמוע ולקבל כל דבריך ואע"פ שלא ישמעו אותם מפיך והם אחר שנכנסו תוך אהליהם הסכימו כי הוא אשר לרגליך והו' משה שעלה על ראש ההר ישא אליהם מדברותיך ויגידם להם ויאמינו בהם כאלו שמעום מפיך:
@919 **תורה צוה לנו משה וגו'.** רוצה לומר התור' שצוה לנו משה קבלנוה עלינו שתהיה ירושה לנצח לקהלת ישראל כאלו שמענו דברים מפי הגבורה ואמנם היה זה כן כי ישראל ראו שאם ירצו ישמעו הכל בזה האופן כמו שנזכר בפרשת ואתחנן ולזה האמינו במשה כאילו השלימו לשמוע כל הדברים מפי הגבורה:
@920 **ויהי בישורון מלך.** ידמה שזה המלך הוא שאול כי אז נתקבצו ראשי עם יחד שבטי ישראל ושאו שמואל שיתן להם מלך ואפשר שזה המאמר שב אל ירבעם כי אז נתאספו ראשי עם אל רחבעם ולפי שבסבת המלך נפלו ישראל ברע שנפלו בו בסוף הענין ידמה שאמר זה בזה המקום לבקש מהש' יתעלה למעט הרע לפי מה שאפשר:
@921 **יחי ראובן ואל ימות.** לפי שמלכות מלכי ישר' היה סבה אל שגלו עשרת השבטים ובתחלה גלה מהם ראובן וגד וחצי שבט המנשי כמו שנזכר בספר דברי הימים וזה הגלו' הגלה פול מלך אשור ותגלת פלאסר מלך אשור והגלות השני ליתר השבטים הנשארים מעשרת השבטים האלה הגלה אותם שלמנאסר מלך אשור ולפי שראובן היה ראוי שיהיה הראשון שזכר בו כי הוא היה הראשון והבכור ייחס זה הגלות לראובן והתפלה עליו היא תפלה ליתר השבטים שגלו עמו כי כלם גלו לחלה וחבור נהר גוזן ועדי מדי כמו שנזכר בספר דברי הימים ובספר מלכי' ולזה אמר זה דרך תפלה יהי ראובן ואל ימות עם אלו הצרות לו ואל ימות לגמרי ביד צריו ואע"פ שיהיו מתיו מספר שיהיו למתי מעטו על רוב חטאיהם להשם כמו שבא זכרו בספר מלכים שבסוף הענין היו עשרת השבטים מספר מעט הנה עם כל זה התפלל לשם יתעלה שלא יכלם לגמרי:
@922 **וזאת ליהודה ויאמר וגו'.** ר"ל וזאת התפלה גם כן אתפלל לה' בעד יהודה כי יהודה גם כן היה עתיד לגלות מעל אדמתו ולשוב מספרם מעט והה נכלל בנימן עמו בזאת התפילה כי יהודה ובנימן היו לעבר אחד והם גלו יחד אך יהודה היה לראש ולזה זכר אותו ואמר שמע ה' קול יהודה ואל עמו תיבאנו ואע"פ שכל אחד מידיו רב לו ריב ומדון במה שחטא בעבדו ע"ז הנה עם כל זה היה לו עזר מצריו שלא יכלוהו בהיותו גולה תחת ידיהם ולזה גם כן אמר על רוב פזור גלות יהודה והיותו נכון אל הכליון מזה הצד שירצה השם יתעלה קול תפלתו להביאו אל עמו באחרית הימים כשיתקבצו כל השבטים וישובו בארצם:
@923 **וללוי אמר תומיך ואוריך וגומ'.** ר"ל שהאורים והתומים של ישראל נתנו למיוחד בחסידים שבכם שהם שבט לוי והוא אהרן וזרעו. והנה זכר האורים והתומים כי עניינם הולך מהלך השלמות מהעבודה שהיתה במקדש כמו שהתבאר מדברינו במה שקדם ולזה לא היה כי אם לכהן גדול:
@923 **אשר נסיתו במסה תריבהו על מי מריבה.** זה שב אל השם יתעלה פעם שלא לנוכח ופעם לנוכח והרצון בו אשר נסית השם יתעלה במסה ושם הריבות עמו על מי מריבה רוצה לומר ברפידים שרבו בני ישראל עם ה' ונסו אותו כאשר לא היה מים לעדה כמו שנזכר בפרשת בשלח והם עשו זה לנסות את השם לראות היש ה' בקרבנו אם אין ומזה המקום נתבאר ששבט לוי היה נקי מזה החטא ואם יקשה בעיניך מה שביארנו מי מריבה על מי רפידים וכבר מצאנו בכתוב מי מריבת קדש ראוי שתדע שזה ממה שיישיר אל ביאורנו זה וזה שמה שהיה מזה בקדש נקרא מי מריבת קדש להבדיל אותו ממי מריבה הנזכר בזה המקום היה מסה ומריבה כמו שנזכר שם בפרשת בשלח:
@924 **האומר לאביו ולאמו לא ראיתיו.** זה היה במעשה העגל כי אז שאל משה מי להשם אלי ויאספו אליו כל בני לוי ואמר להם משה שימלאו ידיהם היום כי איש בבנו ובאחיו ורצה בה כי בזה הענין המגונה שעשו ישראל נמצא גם כן השבט ההוא נבחר ונקי ולא עוד אלא שלשפוט העובדים בעניין העגל אמר כל אחד מהם לאביו ולאמו לא ראיתיו וכן העניין לשאר קרוביו עד שאם היה מוצא זה החטא באחד מקרוביו היה הורג אותו והיה זה כן כי שמרו אמרת השם ובריתו ינצורו והוא התורה בכללה והנה למדנו מזה המקום שאין ראוי לקרוב שיהיה שופט קרובו כי אין טבע האדם סובל לפי הנהוג אל שלא יראה האדם אביו ואמו באופן שלא יוכל לשפוט כראוי כנגדם וכן הענין בשא' הקרובים ולזה שובחו שבט לוי בזה הענין שאין מחק האנשים להתנהג בו:
@925 **יורו משפטיך ליעקב ותורתך וגו'.** הנה הקדים תחילה היותר נכבד מה שילך מדרגת השלמות וזה שהוראת זה השבט משפטי השם יתעלה ותורתו לישראל הוא התכלית המבוקש בעבודה הנכבדת שהיותה נעשית במקדש כמו שנתבאר מדברינו במה שקדם כי זאת העבודה בכללה כונה להעמיד המתעסקים בה על סודו' המציאות ועל סודות התורה גם כן מזה הצד כמו שביארנו בפרשת ויקרא ומצד היותם ראויים גם כן לעיין בתורה ולחקור בסודותיה מפני זאת העבודה כי מצרה הוכנה להם מתנות יחיד בהם בזולת עמל ולפי שהקטורת מעיר על עניין יותר נכבד ממה שתעיר עליו העולה שהיא כליל הקדים הזכרת הקטרת להעל את העולה על המזבח החיצון והנה זכר שתי אלו העבודות לבד לפי שהם היותר נכבדות והנה אמר שאלו הדברים הנכבדים זכה בהם השבט הנבחר מפני היותו להשם מלידה ומבטן ומהריון:
@926 **ברך השם חילו.** התפלל משה בעד זה השבט שיצליח השם יתעלה קנייניו כי יצטרך לזה עזר אלהי שלא יכבשו בידם ישראל מתנות כהנה ולויה והוא גם כן יהיה סבה להתמיד להם השלמות והתפלל ג"כ שיהיו לרצון להשם יתעלה פעל ידיו והם העבודות שיעשה במקדש וענין היותם לרצון הוא שיכוין בהם הכונה הראויה כי זה ממה שיישירם לעמוד על כונת התורה באלו עבודות הנכבדות:
@926 **מחץ מתנים קמיו.** ידמה שזאת התפלה היתה על דבר עלי ושמואל והחשמונים כי הם נלחמו מלחמות הש' והצליחו בהם מאד וזה מבואר מענין שמואל שהיה משבט לוי ומהחשמוני' שהיו מהכהנים הלוים שהגיע מהצלחתם במלחמתם שלא עמד איש בפניהם:
@927 **לבנימן אמר ידיד ה'.** רצה בזה שבנימן הוא ידיד השם יתעלה וישכון לבטח אצלו כי בגבולו היה בית המקדש הנה השם לו לסתרה ולמהסה כל היום ובנהלתו תהיה שכינתו. והנה אמר זה כי מפני היות בנימן בזה המקום נשמר מההמשך לשבטים האחרים כשהמליכו ירבעם והיה זה סבה אל שדבק במלכי יהודה ובזה האופן היה חופף עליו השם יתעלה כל מה שהתמיד היום בשבט אשר נתארך זמן ההצלחה בו יותר ולא העריב יומו קודם זה בגלות שאר השבטים על יד מלך אשור ואפשר שרמז בזה לענין שאול שהיה משבט בנימן שיהיה השם עמו לעזרו במלחמותיו כל היום רוצה לומר כל זמן מלכותו עד שבא יומו ואז נפל ביד פלשתים וכל כך היתה השגחת השם יתעלה במלחמותיו עד שידמה שהשם יתעלה שוכן בין כתפיו:
@928 **וליוסף אמר מבורכת יי' ארצו וגו'.** ידמה שנחלת יוסף היתה במקום הרענן והשמן יותר שבארץ ישראל ולזה אמר שארצו היא מבורכת מהשם יתעלה כי השם יתעלה יתן שם לגדל הצמחים ממתיקות מה שישפיע מן השמים והוא הטל אשר חדושו הוא מקרירות האויר בלילה וגם מתחת תהיה התהום רובצת לבא דרך ספוגיות הארץ אל הצמחים והזרעים לגדלם וגם תהיה מבורכת ארצו שימצאו בו מיני הפירות המשובחים שהויתם הוא פעם אחת בשנה והם התבואות ופירות אילן ומה שידמה להם והם נקראים תבואת שמש וגם תהיה מבורכת ארצו שימצאו בה הצמחים אשר יוציאו בה הצמחים אשר יוציאו פירותיהם מחדש לחדש כמו הרבה ממיני הירקות והם נקראים גרש ירחים ר"ל שתגרש הארץ ותוציא מהם פריה בכל חדש וחדש:
@930 **ומראש הררי קדם.** רוצה לומר שכבר נתן לו מהנבחר שבהרים הקודמים ומהנבחר שבגבעות אשר מעולם והנה כלל מנשה עם אפרים בזה כי נחלתם היתה כמוכה זו לזו כמו שנזכר בספר יהושע:
@931 **וממגד ארץ ומלואה ורצון שוכני סנה וגו'.** מפני שהיו תוצאות גבול מנשה ואפרים הים כמו שנזכר בספר יהושע הנה נתנבא להם משה ממגד ארץ בכללה ומטוב מלואה והם הסחורות הבאות שם דרך הים הנושאות שם מרחוק כל הדברים החשובים הן מפירות הארץ הן מזולתם וזה רצון השוכן בסנה שהוא גדול בארץ הזה כי למעוט תבואתיו יחשוק שיוכן לו בקלות לבא בגבולו מרחוק על הדברים ההכרחיים לו ובזה האופן תמצא עירות גדולות מאד אין להם בעצמם פירות ותבואות אך יסמכו על הסחורות הבאות להם מן הנהר שהוא אצלם או מן הים אשר יובילו אליהם דרך שם בקלות:
@931 **תבואתה לראש יוסף.** ר"ל תבא הברכה לראש יוסף ולקדקד מי שהיה הפרוש שבאחיו והוא יוסף והוא מבואר מענין אשת אדוניו כשבקשה ממנו לשכב אצלה להיות עמה ושם נפשו בכפו לברוח מעשות זה המעשה המגונה ולא עשה כן יהודה בדבר תמר כ"ש שהיה יותר רחוק מזה מה שעשה ראובן בדבר פלגש אביו:
@932 **בכור שורו הדר לו.** אפשר שרמז בזה אל יהושע שהיה משבט אפרים והנה הי לו זיו והדר והיה קרני ראם קרניו לנגח בהם הנה והנה בבוי' אשר כבש ארצם עד קצותיה ואמר משה כי אלו הן רבבות אפרים כי מאפרים יצא יהושע והם אלפי מנשה כי ממנשה יצא גם כן מי שיצליח במלחמה והוא גדעון שהמית זבח וצלמונע ומחניהם שהיה קל"ה אלף והנה ההבדל אשר בין שני המושלים שיצאו מיוסף מבואר ולזה יחס הרבבות לאפרים והאלפים למנשה וכאלו ביארה התורה שמהי שאמר יעקב ואולם אחיו הקטון יגדל ממנו לא ירצה בו רבו המספר אך גודל בממשלה ומלכות וידמה לכי מפני שאמר יחדי אפסי ארץ ולא נתקיים זה ביהושע כי לא כבש כל הארץ ומיוחסת לישר' עד קצותה כי כבר נשארה הארץ הרבה לרשתה כמו שנזכר בספר יהושע הנה יהיה יותר נאות שישוב זה המאמר לדבר משיח בן יוסף אשר יצליח הצלחות רבות במלחמותיו כמו שיתבאר מדברי זכריהו וכבר יהיה לו הדר עד שכבר נאמר עליו שהוא יהיה כדוד וכמו בית דוד לאלהים כמלאך ה' לפני ה' לפני ישראל וזה גם כן ראוי כי לא יצטרך להתנבא על יהושע וכבר נתבאר בתורה ביאור שלם שהוא ינחיל לישראל את הארץ וידמה מזה המקום שזה יצא מאפרים וכאלו ביאר שמפני זה ייחסו הרבבות לאפרים והאלפים למנשה וזה כי אם היה זה מפני יהושע הלא יצא גם כן מאפרים ירבעם בן נבט שהשחית את ישראל והחטיא אותם והיה סבה בסוף הענין אל שגלו יהודה וישראל מעל אדמתם כי מלכי ישראל כלם חטאו בחטא ירבעם ובסוף הענין נכשלו בזה גם כן מלכי יהודה ולמדו ממלכי ישראל כמו שנזכר בספר מלכים:
@933 **ולזבולון אמר שמח זבולון בצאתך וגו'.** בצאתך למלחמה כי כבר היו בני זבולון אנשי מלחמה כמו שאמר זבולון עם חרף נפשו למות או ירצה באמרו בצאתך בצאתך לסחורה ופרקמטיא כי זבולון היה שוכן לחוף ימים כמו שאמר יעקב ואתה יששכר שמח באהליך כי בני יששכר בחרו במנוחה מצד ערבות ארצם ורעננותה ולזה לא היו יוצאי' למלחמה ומפני זה גם כן היו יושבי אהלי' להתעסק בתורה ובחכמה כאמ' ומבני יששכר יודעי בינה לעתים וגומ' והיו שמחים באהליהם מזה הצד כי אין שמחה לאדם תשוה בה כי בה תתענג הנפש תענוג נפלא:
@934 **עמים הר יקראו שם.** ר"ל שהגוים יקראו המקום ההוא כאלו הוא ההר שיהיה בו בית הבחירה וזה היה בעת שהשיבו ארון האלהים משדה פלשתים וראיתם את דרך גבול יעלה בית שמש וגומ' וכאשר הגיעו שם זבחו שם זבחי צדק כמו שנזכר בראש ספר שמואל והוא היה בחלק יששכר כמו שנזכר בספר יהושע והנה חשבו שיהיה המקום ההוא מקו בית המקדש מצד רוב העושר אשר בחלק יששכר שהם יונקים שפע ימים מפני רוב הסחורות הבאות שם דרך הים והנה הם יונקים שפוני טמוני חול ר"ל כי מפני רוב חכמתם כל רז וכל כתוב לא עממום או ירצה בזה כי רבים יקראו נחלת יששכר הם אשר שם יזבחו זבחי צדק והוא בית המקדש והנה קראוהו כן כי הם עשירי' מאד ושם רבוי ההחכמה כמו שראוי להיות זה בבית המקדש או ירצה בזה רבים שיבקשו לעלות במקום הבחירה יזבחו בחלק יששכר זבחי צדק ויעזבו העולים בהר השם והם יתפייסו במקום ההוא להמצא שם רוב העושר והחכמה כמו שראוי זה בבית המקדש וזה אמנם היה אפשר בשעת היתר הבמות והנה קרא עמוקות התורה והחכמה שפוני טמיני חול כי כמו שהטמון בחול נשמר ימים ושנים בזולת עפוש והפסד כן הענין בסודות החכמה והתורה או ירצה בזה שקבוצים מהם יעלו יחד להר השם לזבוח שם זבחי צדק מרוב העושר שנתן להם וזה כי הם יונקים שפע ימים וטובם וגם הארצות הטמונים בחול הים יבואו להם כמו שפירש החכם אבן עזרא:
@935 **ולגד אמר ברוך מרחיב גד וגו'.** אחשוב שרמז בזה אל מלחמת הגריים ויטור ונפיש שנזכרה בדברי הימים ונצחום שבט גד עם הראובני וחצי שבט המנשה וכב' זכר זה עם זכרון שבט גד להעיר כי שבט גד היה העקר בזא' המלחמה וכבר יורה על גבורת בני גד מה שנזכר שם מהאנשי' משבט בני גד שנבדלו אל דוד למצד גבורי החיל אנשי צבה למלחמה עורכי צנה ורומח ופני אריה פניהם וגומר כי זה כלו ממה שיורה על גבורת בני גד ואחשוב שעל זאת המלחמה אמר יעקב גד גדוד יגודנו והו' יגוד עקב כי בסוף הענין שבו מהם נפש אדם מאת אלף ועל זאת המלחמה יתכן שאמר וטרף זרוע אף קדקד ר"ל כי הם נצחו הראש שהוא הקדקד וזרועותיו שהם פרשיו ועוזריו כי כלם נפלו בידם כאמרו יתנו בידם ההגריים וכל שעמהם:
@936 **וירא ראשית לו וגו'.** אף על פי שבני ראובן היו גם כן עם בני גד כששאל שיותן להם נחלתם מעבר הירדן מזרחה הנה יחס זה הענין לגר כי הם היו ההתחלה ולזה הקדימם בספור ההוא ואמר ומקנה רב היה לבני גד ובני ראובן ואמר כי גר ראה שהיה לו ראשי הארץ אשר נחלו ישראל והוא הארץ אשר הנחילם משה מעבר לירדן לפי ששם הארץ ההיא החלקה אשר בה מחוקק ספון והוא משה שיסד לנו החקים מפי הגבורה כי שם בארץ אשר מעבר הירדן היתה קבורתו והנה בחר בה לזאת הסבה לפי שזה הענין הוא ממה שיש לו רושם בהשאיר אמתות התורה אצל ההמון ר"ל כשיתבאר להם שאשר נתנה הוא נקבר שם והנה גד בא אל ראשי עם ישראל כמו שהתנה עמהם משה להלחם עם הגוים ההם עד אשר ירשו גם הם את הארץ והוא עשה שם צדקת השם ומשפטיו עם ישראל רוצה לומר שנשמרו מהחטא בדברי מהדברים כדי שיתישרו יותר לירושת הארץ הלא תראה כי מפני חטא מהם היו נזוקים כולם בדבר עכן בחרם:
@937 **ולדן אמר דן גור אריה וגו'.** המשילו לגור אריה לרוב גבורתו שידלג מן הר בשן כשיראה הטרף וכן היה דבר שמשון שהיה משבט דן שהוא לבדו היה גם על הפלשתים להרגם או אמר זה על שבט דן בהלחמם על לשם ולכדוה כמו שנזכר בספר יהושע:
@938 **ולנפתלי אמר נפתלי שבע רצון.** כי כל מה שבא בחלקו היה טוב ודשן ולזה היה שמח בחלקו כאמרו ונפתלי על מרומי שדה והנה ארצו היה מלאה ברכת ה' ובאה נחלתו במערב ארץ ישראל ודרומה והנה ראה זה כלו משה במראה הנבואה ואפשר שיהיה הרצון בזה שכל שכניו היו גם כן מלאים ברכת השם והם אשר היו לירושתו לפאת ים ולפאת נגב והנה נזכר בספר יהושע שגורל נפתלי פגע בזבולון מנגב ובאשר פגע מים וכבר נתבאר ענין הלח' זבולון כאמרו שמח זבולון בצאתך ועליו גם כן ידמה שאמר כי שפע ימי' ינקו ואע"פ שנכלל בזה יששכר וענין הצלחת אשר יתבאר אחר זה באמרו וטובל בשמן רגלו והרצון בזה שההצלחה אינה לבד בנחלתו אך מלא ברכת השם הים והדרום אשר לירושתו וזה ממה שיהיה לו רושם על התמדת ההצלחה לו:
@939 **ולאשר אמר ברוך מבנים אשר.** בעניין ירושת הארץ הנה הוא יותר רצוי לאחיו שלא יקנאו בו וארצו תהיה שמנה בתכלית עד שהוא כאו יהיה טובל בשמן רגלו וזהו אמרו מאשר שמנה לחמו וידמה גם כן שהיתה נחלתו ארץ זיתים ותמרים ומרוב המצא השמן שם אמר על צד ההפלגה וטובל בשמן רגלו:
@940 **ברזל ונחשת מנעליך.** רוצה לומר שמדרך כף רגליך בנחלה החזק בברזל ונחשת ולזה תהיה ארצך נוחה לכבוש לאויביך:
@940 **וכימיך דבאך.** רוצה לומר במספר ימיך על הארץ יהיה חזקך שם ואף על פי שקצת השבטים גלו בימי השופטים הנה ידמה מזה ששבט אשר היה חזק על ארצו על יום גלות הארץ על יד מלך אשור. ובכאן השלים מה שאמר ביחוד לאחר אחד מהשבטים ובא עתה להגיד דרך כלל ברכת כל ישראל ואמר:
@941 **אין כאל ישרון.** כי הוא רוכב שמים ומניעם לאשר יחפוץ ולזה לא יוכלו אותות השמים להזיק לך והנה הוא בתכלית מהכח והגבורה עד שברממותו נהיו שחק' ונבראו ועוד השלימם ושמם כמו מעון לאלהי קדם מפני המלאכים שברא בהם להניע אותם שהם קרובים להש' יתעלה מכל הנמצאו' ולזה תדבק בהם השגחתו והשגתו תמיד ולזאת הסבה נקראו אלו הנמצאת פניו כאמרו ופני לא יראו והנה השלים השחקים אז ושמם מתחת זרועות עולם וקיימו במה שסדר שישפע מן השמים להשגיח בהויות אלו הנמצאות השפלות ובשמירת מציאותם וזה מהיותר נפלא שבדברים כי הככבים מושפעים מהאיכויות אשר יולידום באלו הנמצאות השפלות וישמרו מציאותם וכבר חקרנו בזה במקומותיו והנה זה הנמצא הנפלא אשר המציא אלו הנמצאו' אמר לגרש מפניך אויב ולהשמיד אותו וזה ממה שאינו אצלו דבר נפלא ואף על פי שלא יהיה זה הרע להם מסודר מהכוכבים כי הוא חדש והמציא הככבים ושם בהם מהכח אל שישפעו מהם אלו העניינים ולזה הוא מבואר בלא ספק שהשם יתע' ימשול עליהם ויעשה כל אשר חפץ אין מעצור לו והוא יעד שישכון ישראל בטח מכל אויביו מסביב וישכון בדד בארץ דגן ותירוש כל המעיין נובע מיעקב והוא זרע ישראל ועם שהארץ נכונה לעשות דגן ותירוש הבטיחם עוד שישגיח בהם בנתינת השמי' טלם להצמיח מוצא על דשא בדרך שתשלם שם הויות פירות הארץ:
@944 **אשריך ישאל מי כמוך עם שהיה נושע ביי' כמך.** וזה ששאר האומות הם תחת ממשלת הכוכבים ולא ישפע להם טוב כי אם מקצת העתים ובעת רעתם לא יעזרו בהם אך יסודר להם מהם ההפסד והרע ואולם ישראל הוא הנושע בהשם אשר לא יכזבו מימי ישועתו והוא גם כן נושע תשועת נפש ואל זה גם כן אפשר שרמז בזה המקום והוא גם כן מגן עזרך. לשמרך מהרעות הראויות לפול עליך:
@944 **ואשר חרב גאותך.** הנה ב' מלת בה' מושכת עצמה ואחרת עמה והרצון ובאשר חרב גאותך וביאור זה שרוממותך גם כן יהיה במקום שיש חרב כנגדך כי לא תירא מזה אחר שהשם יתעלה הוא מגן עזרך עד שמיראתם ממך יכחשו אויבך לך ואתה תדרוך על היותר גבוהים מהם והם המלכים כמו שמצאנו בספר יהושע שהיו ישראל משימים רגליהם על צוארי המלכים ההם ומצאנו רוממות ישראל בזולת הרב כנגד חיל רב כלם אחוזי חרב בדבר בגדעון וכן העניין בדבר יונתן שהשם יתעלה שם הרב איש באחיו:
@945 **ויעל משה מערבות מואב אל הר נבו וגו'.** זכר שהראהו השם יתעלה את כל הארץ את הגלעד עד דן וידמה מזה שידע משה בנבואה אי זה חלק יגיע לכל השבטים ולזה אמר עד דן:
@946 **ואת כל נפתלי ואת ארץ אפרים ומנשה.** רוצה לומר שבעת שראה אותו ידע כי זה יהיה מדן וזה יהיה מנפתלי וכן העניין בשאר ואם תאמר אם ידע משה למה לא הגביל הענין בתורה להגביל גורל כל אחד מהשבטים כמו שהגביל כל הארץ אמרנו לך שכבר רצה השם יתעלה שיהיה זה בגורל להסיר התרעומת והמחלוקת מישראל וכבר התבאר מזה המקום כי מהשם משפט הגורל ולזה בא הגורל אל המקום שיהיה מוגבל תחלה מהשם יתעלה מעניין ירושת הארץ כמו שנתבאר במה שיעד יעקב בענין ירושת הארץ לקצת השבטים ומה יעד משה ממנה לקצתם וכבר יורה עוד על אמתות הגורל על עכן ועל יהונתן ועל שאול:
@949 **וימת שם משה עבד ה'.** קראו עבד השם כי כל ימיו השתדל לעבודת השם יתעלה:
@950 **ויקבור אותו בגאי בארץ מואב מול בית פעור ולא ידע איש את קבורתו עד היום הזה.** זה עניין נפלא מצד כי התורה ביארה מקום הקבר לפי מה שאפשר ועם זה סבב השם יתעלה שלא יהיה מקום קבורתו נודע לאחד מהאנשים והנה עשה זה השם יתעלה כי אולי אם נודע מקום טעו יטעו הדורות הבאים ויעשו ממנו אלוה מצד מה שנתפרסם מהנפלאות שעשה הלא תראה כי גם בנחש הנחשת שעשה משה טעו בו קצת ישראל מצד מעלת מי שעשאו ולזה עשה השם יתעלה שקבר אותו על דרך מופת לא נגע בקבורתו אחד מהאנשים והנה העניין קבורתו שלא יתכן שיודע לאחד מהאנשים והנה בזה עוד מהתועלת להישיר אל שכבר הגיע משה למדרגה מהחיים הנצחיים אחר הפרדו מהגו שלא יתכן שתושג לאחד מהאנשים ולזה עשה השם יתע' שגם מקום גוו לא נודע להעיר על זה הענין:
@951 ובכלל הנה היה ענינו נפלא בחייו ובמותו על שאר האנשים כמו שזכר בזה המקום וזה שבמותו לא נשתנה גופו כלל במזגו ובריאותו כי לא כהתה עינו ולא נס לחותו הטבעי כמנהג הזקנים והיה רגע מותו כמו רגל הולדו כמו שאמר בן מאה ועשרים שנה אנכי היום וביום ההוא מת כשנשלמו לו ק"כ כאלו העיר בזה שמותו הוא כמו הולדו מפני הגיעו אז לערבות החיים הנצחיים ונעימים בתכלית מה שאפשר וכאלו נולד אז להכנס בגבול אלו החיים הנפלאים שהגיע אליהם מצד עוצם מדרגתו בחכמה אשר לא יתכן שיגיעו אליהם אחד משאר האנשים אם לא על דרך זרות:
@952 וזכר שכבר בכו ישראל את משה שלשים יום בערבות מואב במקום שהיתה שם ישיבתו ואמר שאחר שלשים יום תמו בכי אבל משה להעיר שאין ראוי להתאבל יותר מדי גם על שלם כמשה אבל בכוהו החק הנהוג כמו שבכו אהרון שלשים יום:
@953 והנה כשמת משה צמח לישראל תכף מיישיר ומנהיג ראוי כמו שבקש משה וזה כי יהושע בן נון היה מלא רוח חכמה באופן שיהיה ראוי להיות נביא כי משה סמך את ידיו עליו ולהחכימו ומסר לו סודות עמוקות מחכמת הנמצאות אשר היא כלי להגעת הנבואה והנה שמעו אליו בני ישראל כמו ששמעו אל משה וכל מה שעשה יהושע עשה אותו כאשר צוה יי' את משה כי הוא צוהו והישירו במצות התורה אל כל מה שיעשהו בירושת הארץ וכבר נתבאר שהעניין הוא כן בספר יהושע הנה אעפ"י שלא זכה משה להנחיל לישראל את הארץ הנה נעשה כל מה שעשה שם על פיו:
@954 **ולא קם נביא עוד בישראל כמשה.** ידוע כי מדברי התורה שלא קם נביא תורה ולא יקום זולת משה כי שום נביא לא יאמן לחדש בה או לגרוע באופן שישימהו תורה נוהגת לדורות כ"ש שלא יאמן לשנותה ולהמירה באחרת וזה כלו מבואר ממה שקדם ולזה לא זכר כאן זה ההבדל נפלא שיש בין נבוא' משה ובין נבואת זולתו אבל זכר מה שהובדל בו משה מכל נביא שיקום להתנבא בישראל ומזה יתבאר שהוא אפשר שיקום נביא כמהו להתנבא בישראל ובשאר האומות לאלו העניינים שזכר אחר זה ואם לא היה הענין כן היה אמרו בישראל תנאי לבטלה והנה זה הנביא שיתנבא בישראל ובשאר האומות הוא מלך המשיח כמו שזכרנו בפרשת בלעם והוא מי שאמר עליו הנביא והריחו ביראת ה' לא למראה עיניו ישפוט ולא למשמע אזניו יוכיח ועל ידי מופתיו ונפלאותיו יהפוך השם יתע' אל העמים שפה ברורה לקרוא כלם בשם ה' ולעבדו שכם אחד כמו שלקח השם יתעלה את ישראל לעבודתו במופתים ונפלאות העצומות שהראה להם במצרים ועל הים ובמדבר והנה אחשוב שהמופת היותר נפלא שיעשה הוא תחיית המתים והוא יגלה ויראה בקצות הארץ ולזה יאמינו בו כל הגוים כי השם הוא האלהים ויאמרו ששקר נחלו אבותינו ואין בה מועיל והנה ההבדלים שזכה בזה המקום בין נבואת משה ובין נבואת זולתו ממי שהם נביאים בישראל לבד הם שלש. הראשון שהשם ידעו פנים אל נפים ולזה היתה נבואתו בהקיץ כי הוא משפע השכל לשכל לבד ולזה לא הוצרך בה התבודדות לדמיון כמו שיצטרך זה לשאר הנביאים שתבא להם הנבואה במראה או בחלום וזהו אמרו אם יהיה נביאכם ה' במראה אליו אתודע בחלום ואדבר בו. והשני שלא נתפשטו אותותיהם ומופתיהם בכלל אומה גדולה במקום רחב מאד מהארץ כמו העניין באותות והמופתים שיעשו מהשם יתעלה על יד משה שנעשו לפרעה ולכל עבדיו ולכל ארצו כמו שנבתאר בספר ואלה שמות. ואולם שאר הנביאים כשנתחדש מהם מופת אחד לכלל גדל מהאומה לא היה במקום רחב מהארץ כי ענין מות סנחריב דרך משל באופן הנפלא ההוא הנזכר בספר מלכי' ובספר ישעיה היה בחלק קטן מהארץ ואולם משה הרבה אותות ומופתים אשר נתפשטו לכל העם ההוא בכל ארץ מצרים למדנו כי מצד הנביא יהיה מנא מה בגודל המופתים. והשלישי הוא שלא התמידו אותותיהם ומופתיהם לעיני כל ישראל כמו העניין במשה שהתמיד ירידת המן מ' שנה ועניין עמוד הענן ועמוד האש ודבור השם יתעלה עמו שהיה תמיד בעמוד ענן לעיני כל ישראל ובכלל רבו מלספור המופתים הנפלאי' שעשה משה לעיני כל ישראל הנה משה נבדל מאלו העניינים משאר הנביאים באיכות ובכמות ולזה אמר לכל האותות והמופתים ולכל היד החזקה ולכל המורא הגדול אשר עשה והנה אחשוב שיהיה הרצון באותות מה שהמכוון בהמצאתו הוא להאמין בדברי הנביא כמו הפכת המטה לנחש וההפך מי היאור לדם וכאשר היו עם זה חוץ מהטבע כמו העניין באלו נקראים אותות ומופתים כי מצד מה שהם לסימן הם אותות ומצד מה שהם חוץ מהטבע הם מופתים וזה כי האותות יהיו אותות אף על פי שלא יהיה בהם דבר חוץ מהטבע כמו שנתבאר מהאותות שנתן שמואל לשאול לאמת שהוא יהיה מלך על ישראל. והיד החזקה הוא מה שהראה השם יתעלה חוזק ידו לעשות אשר יחפוץ כמו הענין בקריעת ים סוף שהיתה כלי לעבור ישראל בים ואל טביעת פרעה וחילו בים ובירידת המן מ' שנה ובשאר מה שדומה לזה מהנפלאות העצומות. והמורא הגדול. הם הנפלאות שעשה הש' יתע' כדי שייראו מלפניו. ובכאן נשלם הביאור במה שצריך בזאת הפרשה

@1 ואולם התועלות המגיעות מזאת הפרשה הם י"ח:
@1 **התועלת** הראשון במדות והוא להודיע שראוי לכל אדם שיוכיח המונהגים ממנו באופן שלם בעת ראותו שהוא נפרד מהם כדי שיוריש להם מהטובות לפי מה שאפשר לו הלא תראה כי משה רבינו הוכיח את ישראל זה התוכחת הנכלל בזה הספר קודם הפרדו מהם להישירם אל הטוב לפי מה שאפשר בעוד בחיים חייתו ועודנו עמם כי קודם זה לא הוצרך לתוכחה גדולה כזאת כי הוא היה מוכן להוכיחם תמיד בעת הצרך ואולם עתה הוצרך להוכיחם בתוכחת תספיק להם תמיד אחרי מותו:
@1 **התועלת** השני הוא להודיע אופן החכמה האלהית בזאת ההשגחה שהסכים להשגיח את ישראל להנחיל להם הארץ וזה כי הוא רצה להישירם תחלה לעבודתו במה שהראה להם מהמופתים במצרים ועל הים ובמעמד הר סיני אשר רבו מלמנות כאלו נא אותם על כנפי נשרים להביא אותם אליו ולזה ארך זמנם בהר חורב שהוא הר סיני כדי שירגילו ויסתבכו הסתבכות חזק באמונת ה'שם יתעלה ובתורתו ואחר זה כשנגלה לשם יתעלה שהם בצד שראוי שתדבק בהם כמו זאת ההשגחה אמר השם יתעלה כי רב לכם שבת בהר ההוא כי כבר נתחנכו שם בשלמות לעבודת השם יתעלה כמו שאמר משה בהוציאך את העם ממצרים תעבדון את האלהים על ההר הזה ולזאת הסבה ארך להם הזמן מעת צאתם ממצרים עד בואם לדש כמו ט"ו חדש בקרוב והנה לא היה מהר חרב עד קדש כי אם מהלך י"א ימים כמו שזכר בזאת הפרשה וממצרים להר חורב היה מהלך ג' ימים כי שאמר נלכה נא דרך שלשת ימים במדבר ונזבחה ליי' אלהינו והנה היה עכובם להמתין שיהיו ראויים לזאת ההשגחה ולזאת הסבה בעינה סדרו שם שופטים רבים על העם ראויים להישירם אל הטוב כדי שימהרו להיות ראוים לזאת ההשגחה ולזה אמר יי' למשה רב לכם שבת בהר הזה כשנגלה לו שנקרבו שם לעבודתו כמו שזכרנו ולזאת הסבה בעינה אמר להם רב לכם סוב את ההר הזה כאשר תמו למות הפקודים שנמנו במדבר סיני כי המתנת מיתתם איחרה אותם במדבר זה הזמן הארוך:
@1 **התועלת** השלישי הוא להודיע שאלו התוכחות לא אמרם משה מעצמו כי אם על פי הגבורה ולזה אמר כאשר צוה יי' אותו והנה רצה השם יתעלה שיאמרו לכל ישראל לא לראשיהם לבד כדי שיקבלו בזה כולם מוסר עם שההמון היו יותר צרכים לאלו התוכחות מהראשים והנה לא רצה השם יתעלה שיאמרו כי אם בעת היותר ראוי זה המתין לומר אלו התוכחות אחר הכאת סיחון ועוג כי אם אמרם קודם זה שמא היו אומרי' מבלתי יכולת יי' להביאם שם היה זה לא מחטא דבר המרגלים ואולם עתה שנתבאר להם עוצם גבורת השם יתעלה באלו המלחמות אחרי מות הפקודים ההם שגזר להם למות במדבר נתבאר להם שהחטא היה המונע בזה לא דבר אחר זולתו:
@1 **התועלת** הרביעי להודיע שהמנהיג מספר רב מהאנשים להועיל בו להמון ראוי שישתדל בביאור סודותיו קודם מותו כדי שיגיע אל התועלת המכוון מהספר ההוא להם ולזה ספר שלפני מותו הואיל משה באר את התורה הזאת ואופן הבאור הזז היה לפי מה שאחשוב קצת דברי' נתחדשו בזה הספר במצות התוריות אשר נזכרו במה שקדם ולא נתבארה בשלמות ובסידור הדברים גם כן שהעיר בו על הענינים באופן שלם ומה שהזכיר מהמצות שלא נזכרו שיעיר גם כן על כוונת המצות ואולם רז"ל הבינו מזה שכבר באר משה התורה אז באורים לא נכתבו כמו דקדוקי המצות ופרטיהם וכלליהם והעמידה עליהם באחת מי"ג מדות שהתורה נדרשת בהם וכשיעויין בזה עיון טוב הנה הוא מסכים למה שהעירונו עליו.
@1 **התועלת** הה' הוא להודיע שהמנהיג מספר רב מהאנשים צריך לו שימנה עליהם אנשים טובים קצתם למעלה מקצת באופן שיוכלו לדקדק בהנהגתם באופן ראוי ובזולת זה לא תשלם ההנהגה למונהגים באופן ראוי ולזה ספר כי מפני שהיה מספר בני ישראל רב בקש משה מהם למנו' עליהם שרי אלפים שרי מאות שרי חמשים שרי עשרות כדי שתשלם ההנהגה באון שלם כמו שזכרנו בביאור דברי זאת הפרשה:
@1 **התועלת** הששי הוא במצות והוא להודיע שהוזהרו הדיינין שלא ייראו מפני איש בדבר המשפט והתועלת בזאת האזהרה מבואר כי בזה ימשך היושר והצדק בעסקת בני אדם קצתם עם קצת אשר בו קיום הישוב:
@1 **התועלת** השביעי להודיע כי התחלת דבר המרגלים היתה מישראל לא מהשם יתעלה אולי יחשוב חושב כי מפני שהיה גלוי לשם יתעלה מה ישיבו המרגלים שלח אותם למצא תואנה על אשר לא הביאום תכף לארץ אך בזולת זה גם כן לא היו באים שם אז ולזה ביאר בזה המקום כי מישראל היתה נסבה לשלח המרגלים:
@1 **התועלת** השמיני הוא ללמדנו כי הרעו' או מה שיביא אליהם אין ראוי שיוחסו לשם יתעלה כי ממנו לא יסודרו כי אם טובות ולזה אמר משה על דבר שלוח מרגלים וייטב הדבר בעיני להרחיק מלייחס לשם יתעלה מה שיביא מהרע ואף על פי שכבר נתבאר במה שקדם שהשם יתע' צוהו על זה לבקשת ישראל הנה לא אמר משה וייטב הדבר בעיני יי' וראוי שלא יעלם ממנו שהשם יתעלה בצוותו על זה לבקשת ישראל התחכם לשלח נכבדים שבעם והם הנשיאים כדי שיהיו יותר נשמרים מיציאת תקלה על ידם ולזה לא היתה הצואה הזאת מהשם יתעלה כי אם על הכונה השנית והוא להסיר הרע מזה הפועל לפי מה שהיה אפשר ולזה אמר איש אחד איש אחד למטה אבותיו תשלחו כל נשיא בהם כי אחר שהיה רצון יי' יתע' שלא יעלו שם אם לא אחר רגול הארץ היה יותר שיעשה זה בזה האופן עם שלא היה ראוי שימשך משלוח המרגלים רע לולי בחירת ישראל הרעה שסבה זה כמו שזכרנו בביאור דברי זאת הפרשה ולזה לא ספר משה בזה המקום מדברי המרגלים רק אמרם טובה האץ אשר יי' נותן לישראל כי לא היה ראוי לישראל שיתנו אל לבם שאר הדברים אשר ספרו להם מחוזק הארץ ואנשיה כי היה ראוי שיבטחו בש' יתע' שלא תקצר ידו מהשלמת מה שיעד להם מזה כמו שספר להם משה מה שראו בעיניהם מנפלאות יי' יתעלה ועצם גבורתו לעשות כל אשר יחפוץ:
@1 **התועלת** התשיעי הוא ללמדנו יושר משפטי יי' יתעלה ומדדו המדה כנגד מדה וזה שהם מאסו הארץ הטוב' ההיא ונענשו שלא יראו אותה וברחו מליורשה על ידי משה שהיה כחו יפה בדבר המופתים על כל הנביאים ונתגלגל הענין מזה בסיבת חטאיהם שנענשו שלא תהיה לישראל ירושת ארץ כנען על ידי משה ולזאת הסבה זכר בזה המקום אמרו גם כי התאנף יי' בגללכם וגו' וכבר בארנו זה בענין מי מריבה ובאורנו לזאת הפרשה. ואולם אשר בארו מהמרגלים בארץ הטובה הם ירשו אותה ובאו בארץ כמו שספר מענין כלב שנתן לו הארץ אשר דרך בה ויהושע זכה גם שהנחיל הארץ לישראל ונתן לו גם כן עיר אחת והיא תמנת סרח על פי יי' כמו שנזכר בספר יהושע:
@1 **התועלת** העשירי הוא להודיע כי ראוי למוכיח שיהיה נקי מהדבר שיוכיח בו זולתו כי בזולת זה יאמר הנוכח ולמה לא יוכח עצמו תחלה ולזה תמצ' כי משה מפני שהיה מוכיח ישראל ומראה להם שעונותיהם סבו אל שנתאחרו במדבר עד מותם כי נשבע ה' ית' שלא יראה איש מהם את הארץ והיה לאומר שיאמר כי גם על משה נגזר עליו זה כמו שהוא האמת ולזה אמר גם כן בפרשת ואתחנן ויתעבר יי' בי למענכם:
@1 **התועלת** האחת עשרה להודיע ההבדל הנפלא שיש בין מי שתדבק בו ההשגחה האלהית ובין מי שסרה ההשגחה ההיא כי בעת שהיו ישראל ראויים להדבק בהם ההשגחה האלהית נצחו בקלות שני מלכי האמורי ולא השאירו מהם שריד וכעת סור ההשגחה מהם רדף האמורי אחריהם ויכום ויכתום:
@1 **התועלת** השתים עשרה הוא להודיע שראוי לקבל הטוב בעת הרצון שאם לא יתרצה לקבלו אולי כאשר ירצה לא ינתן לו הלא תראה כי ישראל מנעו מהם הטוב על דבר המרגלים וכאשר נתחרטו מזה והיו רוצים לקחת הטוב ההוא לא עלה בידם:
@1 **התועלת** השלש עשרה הוא להודיע שבענין ירושת הארץ יצטרכו שנים תנאים האחד זכות ישר' והאחד רשע הגוי' ההם שיהיה בעד שיהיה שלם עונם כמו שבארנו באמרו כי לא לשם עון האמורי עד הנה וזה אמנם הוא לעת תמוט רגלם כי ה' ית' יבקש בכל הדברים הסיבות הנאותות ואע"פ שהוא שליט לעשות כל אשר יחפוץ כמו שביארנו בספר מלחמות השם ולזה תמצא שהזהיר התורה שלא יתגרו מלחמה את בני עשו ואת בני עמון ומואב כי לא יתן להם מארצם נחלה כי אף על פי שבני אלו האומות היו רשעים הנה לא שלם עונם עדין. ואולם עון האמורי שלם ולזה ירשו את סיחון ועוג. אע"פ שסיחון כבש ארץ מואב לא לקחוה ישראל מיד מואב כי אם מיד האמורי וזה לא מנע מהם השם יתעלה:
@1 **התועלת** הארבעה עשרה הוא להודיע מה שהרחיב הביאור בענין ירושת בני עשו ועמון ומואב כדי שיתבאר לישראל אי זה מהארצות הותר להם לכבוש ואיזה לא עם שבזה תועלת להודיע כי לפעמים יבואו טובות מפאת ההשגחה הכוללת מתיחסות לטובו' אשר מפאת ההשגחה הפרטית ולזה זכר כי עמן ומואב ירשו ארצם מעם גדול ורב כענקים כי ה' יתע' לא קצר מהשפעת הטובות לפי מה שאפשר ולו היה אפשר שלא יגיעו בכאן רעות לא היה מקצר הש' ית' מזה אך הכלים אשר הוכנו להגיע הטובות ולשמרם הם לפעמים סבות במקרה אל הגעת הרעות כמו שביארנו בד' ממ"י ומזה המקום יסורו מבוכות רבות במה שנמצא מהגעת הטובות וההצלחות לרשעי' כמו שביארנו שם:
@1 **התועלת** החמש עשרה להודיע שראוי לאדם לרדוף אחר השלום ולהרחיק המחלוקת והמלחמה ואע"פ שנתבאר לו שהוא ינצח הלא תראה כי ה' ית' רצה שיקדימו דברי שלום לסיחון קודם שיתגרו בו מלחמה ואע"פ שהוא הקשה רוחו ואמץ את לבבו וכן עשה לכל הגוים אשר כבש יהושע כי הש' ית' הקשה רוחם ואמץ לבבם למען תתם ביד ישראל כמו שנתבאר שם כדי שתתישב בלבנו שראוי בכל המקומות לרדוף אחר השלום לפי מה שאפשר כי אין השם יתעלה חפץ במיתתן של רשעים:
@1 **התועלת** השש עשרה הוא הודיע כי לב מלך ביד השם את כל אשר יחפוץ יטנו להביא עליו ועל עמו העונש הראוי להם מצד רשעם והנה הטותו לב המלך למה שירצה ישימהו השם יתעלה כלי להגע' העונש הראוי למלך ההוא ולעמו ולזאת הטובה הכביד השם יתעלה לב פרעה וסיחון וכל המלכים שהכה יהושע ואין בזה עול בחק השם יתעלה כמו שביארנו בפרשת וארא:
@1 **התועלת** השבע עשרה הוא להודיע מה שהרחיב בזה המקום זכרון מלחמת סיחון עם רוב גבורתם ועוצם חוזק הערים היו יושבים בהם לפרסם עצם הפלא שעשה השם יתעלה להם בזה עם שזכירת כל אלה הפרטים בהם יהיו בו תועלת להוסיף אמות בזה הספור כמו שזכרנו פעמים רבות והנה המשיך לזה זכירת נתינת הארץ אשר מעבר לירדן לראובני ולגדי ולחצי שבט המנשי לפי שהוצרך להזכיר עם זה הדבר הנפלא שהיה עוד במלחמות ההם והוא שיאיר בן מנשה אשר לא היו בניו עם רב לקחו את כל חבל ארגוב עד שסדר דברים היה נותן זה כי הוצרך להזהיר כל ישראל שלא ייראו הגוים ההם אשר ילכו להלחם עמם מפני שראו שעשה השם יתעלה לשני מלכי האמורי. ולזה היה הסדר נותן שיבאר תחלה כי הראובני והגדי וחצי שבט המנשי נקשרו עם ישראל ללכת עמם להלחם את הגוים ההם:
@1 **התועלת** השמנה עשרה הוא להודיע שראוי לאדם שלא יקצר משיגיע מהפועל האחד כל התועלות האפשריות להגיע ממנו ולזה תמצא שענין מלחמות שני מלכי האכזרי לא נסתפקה בו התורה במה שהגיע בזה מהתועלת אל שיירשו ישראל ארצם אבל השתדלה התורה להגיע מה תועלת להוכיח ישראל ולהורות להם כי לולי מרים כבר ירשו אז בשנה השנית לצאתם מארץ מצרים זאת האר הנבחרת כי עיניהם הרואות עוצם גבורת השם יתעלה להכות המלכים האלה במעט זמן עד בלתי השאיר להם שריד ולזה היו דברי התוכחות האלו אחרי הכותו את סיחון מלך חשבון ואת עוג מלך הבשן. והמשיכה התורה עוד מזה תועלת אחר לחזק לב יהושע ולב ישראל שלא ייראו מהממלכות אשר יעברו שמה ולזה אמר ואת יהושע צויתי בעת ההיא לאמ' עיניך הרואות את כל אשר עשה יי' לשני המלכים האלה וגומ':
@106 והתועלות המגיעים ממנה הם תשע עשרה:
@106 **התועלת** הראשון הוא הודיע שהמתפלל צרך שישתדל תחלה לסדר שבחי השם יתע' ולהשיג אותו כפי היכולת ואחר זה בהיותו דבק בשם יתעלה יאות לו להתפלל ולבקש ממנו מה שירצה הלא תראה כי משה רבינו עליו השלום אף על פי שהיה באופן מהשלמות שהיה תמיד עם השם יתעלה עד שכבר היה מתנבא בכל עת שירצה כאמרו. עמדו ואשמעה מה יצוה יי' לכם הנה עם כל זה כשרצה להתפלל לשם יתעלה לבקש ממנו שיעבור את הירדן ויראה את הארץ ספר תחלה שבחי הש' יתעלה במה שהורה על השגחתו יתעלה בשעור האפשרי ואחר זה בקש בקשתו ולזה תקנו רבותינו זכרונ' לברכה שיסמך אדם גאולה לתפלה כדי שתהיה ענין התפילה אחר סדור השבחים הנפלאים הנכללים בברכות ק"ש ובק"ש ולזה אמ' והתענג על יי' ויתן לך משאלות לב כי מי שישיג השם יתעלה ההשגה האפשרי' לו הוא מתענג עליו תענוג נפלא ולזה תהיה אז תפילתו נשמעת לדבקות ההשגחה האלהית בו וזה גם כן מה שאמר איוב אם על שדי יתענג יקרא אלוה בכל עת:
@106 **התועלת** השני הוא להודיע כי גודל השם יתעלה וידו החזקה הוא בלי אפשר שיושג מנו כי אם שעור מעט ביחס אל מה שהוא בעצמותו הלא תראה כי משה רבי' עליו השלום עם עלותו לזאת המעלה הנפלאה שזכר בה מן החכמה והנבואה אמר שלא השיג מזה כי אם שעור מעט ולזה אמר שהשם יתעלה התחיל להראותו זה:
@106 **התועלת** השלישי הוא להודיע כי השלמי' אינם בוחרי' אלו החיים הגופיים כי אם לתכלית שיוסיפו בשלמות הנפש ולזה נתן משה הסבה במה בקש מהשם יתעל שיתנהו לעבור את הירדן ולראות את הארץ שכבר התחיל השם יתעלה להראותו גדלו וידו החזקה ולזה בחר שיכנס לארץ שהיא נבחרת אל שישפע בה השפע האלהי כדי שיוסיף שלמות על שלמותו ויראהו השם יתעלה שם מגדלו וידו החזקה יותר מה שהראה לו מזה עד עתה ליתרון הכנת הארץ ההיא ולא בחר זה כדי לאכול מפירות הארץ כמו שחשבו הסכלים:
@106 **התועלת** הרביעי הוא להודיע שראוי לאדם שלא יתפאר בחכמתו והשגתו לומר שכבר השיג מזה שעוד רב אך ראוי שיחשוב עצמו חסר מאד כי בזה יוסיף זריזות לבקש השלמות הלא תראה כי משה רבינו עם חוזק השגתו חשב עצמו חסר מאד עד שאמ' כי הוא בתחלת דרך השגת השלמו' לשערו שכבר יתכן שיוסיף שלמות על שלמותו ולזה אמר יי' אלהים אתה החלות להראות את עבדך וגומ':
@106 **התועלת** החמישי הוא להודיע שמה שבחר השם יתע' לתת לבני ישראל את האר היה מצד יתרון הכתה אל השגת השלמות האנושי ולזה סמך משה לזכירתו טוב ארץ ישראל על שאר הארצות וטוב הר בית המקדש על כל ארץ ישראל ענין אשר התחילו להשיג גודל השם יתעלה וידו החזקה להעיר שטוב הארץ ההיא יהיה כלי לו להוסיף על זה השלמות:
@106 **התועלת** הששי הוא בדעות הוא להודיע עוצם ההבדל שיש בין השם יתעלה ובין שאר הנבדלים כי אין בהם מי שיהיה מנהיג בכללות בשמים ובארץ זולתו וזה כי הם ואם יש לאחד מהם הנהגה מה בשמי' ובארץ הנה היא חלקית והיא עלולה מהשם יתעלה ואין בהם גם כן מי שיעשה כמעשה השם יתעלה וכגבורתו כי מעשיהם חסרים מאד כמו שביארנו בחמישי מספר מלחמו' יי' כי אין התכלית מגיע מהם אלא במעשי' רבים יצטרפו אל מעשיהם ואולם מעשה השם יתעלה הם שלמי' בעצמם בתכלית מה שאשר וכן אין יחס בין הגבורו' המתחדשות מהם ובין גבורות השם יתעלה וזה שהגבורות הנפלאות ואם יקרה שיתחדשו מהם על צד ההשגחה הכוללת להביא אל שתנצח אומה אומה אחרת חזקה ממנה כמו שנזכר בבני עמון ומואב הנה זה לא יהיה רק בעת מוגבל לפי הסדור השופע מהשגחת זאת האומה בעת ההיא וזה גם כן ששזכרנו מצד מעשיה' וגבורותיהם לא שיעשו באמצעות מה שיושפע להם מהשם יתעלה כי מאתו הכל והוא עשאם ומאתו שופע תמיד מה שיסודר מהם ואולם השם יתעלה יעשה הגבורות בכל עת שימצא ראוי להם לא בעת זולת עת ולזה גם כן אמר כי מי גוי גדול אשר לו אלהים קרובים ואליו כיי' אלהינו בכל קראנו אליו כי גוים שהם תחת ממשלת הכוכבים לא ישיגו עזר מהם כי אם בעתים מיוחדי' לפי מה הוגבל להם אז אמנם השם יתעלה יגיעו ממנו עזר לנו בכל עת שנקרא אליו באופן ראוי רוצה לומר כשנישיר עצמנו אל שנהיה ראויים שתדבק השגחתו הפרטית בנו ולזאת הסבה גם כן אמר ופן תשא עיניך השמימה וראית את השמש ואת הירח וגו'. אשר חלק יי' אלהיך לכל העמים וגו'. ואתכם לקח יי' וגומ'. ביאר שענין שאר האומות הוא מסודר מהמערכת אשר לכוכבים ואמנם ישראל הם תחת השגחת השם יתעלה הפרטית:
@106 **התועלת** השביעי הוא במדות והוא להודיע שהוא ראוי למי שישיגהו עונש מהשם יתעלה על מריו שיראה שהוא מרגיש שעור מה שאבד ממנו כי בזה תועלת ללקיחת המוסר כי מי שלא ירגיש שהוכה על מריו לא יקבל מוסר כמו שאמר הנביא על מה תוכו עוד תוסיפו סרה וגומ' ולזה תמצא שמשה הראה שהוא מרגיש בשעור מה שאבד ממנו בשלא הסכים השם יתעלה שיעבור את הירדן כדי להקנותו זאת המדה החשובה:
@106 **התועלת** השמיני הוא בדעות והוא להודיע שלא זכה משה לזאת המעלה העליונה מהנבואה מצד יתרון הכנתו הטבעית לקבל שפע הנבואה שאם היה זה כן לא היה ראוי שישיב השם יתעלה למשה על בקשתו זאת רב לך כי בודאי היה מוסיף שלמות בנבואה לפי זאת ההנחה אם היה בא לארץ ישראל מני יתרון הכנתה לנבואה לזה הוא מבואר שלא השיג משה רבינו זאת המעלה הנפלאה מהנבואה מצד יתרון הכנתו על האנשים כולם כי כמו זאת ההכנה יתכן שימצא לזולתו כי זה דרך האפשר במין כמו שהתבאר בטבעיות וכבר יתבאר במה שיבא מדברי התורה הקדושה שלא יהיה שם נביא תורה זולת משה עליו השלום ולזה הוא מבואר כי עוצם מעלת נבואה משה להנתן זאת התורה האלהית על ידו היה מהשם יתעלה על צד המופת והפלא. כמו שהיה עני מעמד הר סיני על דרך הנפלאות ומפני זה ענה השם יתעלה למשה על שאלתו זאת רב לך רוצה לומר שיתרון הכנת הארץ לא יוכל להוסיף על שלמותך בנבואה כי לא היה זה השלמות לך מצד הכנתך כי אני שמתיו לך עודף על שלמות כל בעל הכנה ולזה ראוי שתדע כי מה שאמרנו בפרשת בלק שכבר יקום נביא בישראל ובשאר האומות כמשה והוא מלך המשיח אשר אנחנו מקוים אין הרצון בזה שיהיה נביא תורה כי זה בלתי אפשר ואינו דרך הנבואה במה שהיא נבואה שתודיע נימוס תוריי אלהי אם לא על דרך המופת כמו שהיה הענין בנבואת משה אך הרצון בזה שיהיה כמוהו אל למעלה ממנו בעניינים הה הנזכרים שם רוצה לומר חדוש האותות והמופתים ויתר העניינים שהמשיך למה שאמר ולא קם נביא עוד בישראל כמשה:
@106 **התועלת** התשיעי הוא במדות והוא לזרז האנשים שישתדלו לראות כל הדברים שיוכלו לראות כדי שיכירו בזה חכמת השם יתעלה שברא אלו הענינים ולזה תמצא כי משה בקש שאם לא ירצה השם יתעלה שיעבור הירדן יסכים שיראה הארץ בכללה כדי שיעמוד על סבות מעלות הארץ ההיא מצד מצבה ומצד מקומה מהיישוב ולזה יהיה רצון באמרו אעברה נא ואראה את הארץ אעברה נא או אראה וכבר יעיר שהכוונה היא כן שכבר אמר השם יתעלה למשה עלה ראש הפסגה ושא עיניך וגומ' והנה מצאנו שזאת התכונה היתה חזקה במשה ולזה אמר אסורה נא ואראה את המראה הגדול הזה מדוע לא יבער הסנה כמו שביארנו בפרשת ואלה שמות:
@106 **התועלת** העשירי הוא במדות והוא להודיע שהוא ראוי למנהיג שישתדל בהגעת הטוב האפשרי למונהגי' ממנו ולזה תמצא לפי מה שיראה מתשובת השם יתעלה למשה על זאת הבקשה שבקש שיעבור את הירדן כדי שינחיל הארץ לישראל ביותר שלם שבפנים כי במעט זמן היה מנחילה להם אם היה עובר שם לפי מה שיראה מהמלחמות שעשה משה במעט זמן ולזה ענהו השם יתעלה שיצוה את יהושע איך יתנהג בפועל הנהגת הארץ לישראל ויחזקהו ויאמצהו כי הוא ינחיל הארץ לישראל למדנו מזה כי משה היה מבקש שהוא ינחיל הארץ לישראל מצד שערו שעל ידו יהיה נעשה באופן שלם וכדי שיהיה יהושע בזה תמורת משה לפי מה שאפשר ויתפוס בזה משה לשערו שהוא ישתדל בזה האופן השלם רצה השם יתעלה שיישיר משה את יהושע בכל מה שיעשהו באופן שתשלם לו הנחלת הארץ לישראל באופן שלם:
@106 **התועלת** האחת עשרה הוא בדעות והוא להודיע שהתורה השלמה שנתנה השם יתעלה לנו על יד משה היא מישרת אל השגת החיים הנצחיים והם חיי הנפש וימשך ממנה עוד תועלת בהצלחות הגופיות מצד מה שהם הישרה ומביא להצלחת הנפש ולזה אמר ועתה ישראל שמע את החקים ואל המשפטים אשר אנכי מצוה אתכם לעשות למען תחיון ובאתם וירשתם את וגומ' והוא מבואר שאמרו למען תחיון אין הרצון בו החיים הגופיים כי לא יצטרך לומר אלא למען תבואו ותרשו את הארץ כי ידענו שלא יירשו את הארץ והם מתים אבל רצה באמרו למען תחיון החיים האמתיים הבלתי פוסקים והם חיי הנפש ויעד עם זה שכבר תהיה סבה לירושת הארץ ההיא שהיא הצלחת גופיית והיא מישרת גם כן אל ההצלחה הנפשיית כמו שזכרנו באלו התועלות ולזה גם כן כוון באמרו בפרשת אחרי מות ושמרתם את חוקותי ואת משפטי אשר יעשה אותם האד' וחי בהם רוצה לומר חיי הנפש כי הם החיים האנושיים וכבר התבאר מדברינו בתועלות המצות כי התורה היא המישרת בתכלית מה שאפשר אל אלו החיים הנצחיים שהם חיי הנפש ולזה כוון פה במה שאשמר ושמרתם את חקותי ואת משפטי אשר אנכי מצוך היום אשר ייטב לך ולבניך אחריך למען תאריך ימי' על האדמה. כיון באמרו אשר ייטב לך למה שהוא טוב אנושי והוא הטוב הנפשיי ולזה הבדיל בינו ובין הטוב הגופיי ואמר למען תאריכו ימי' על האדמה להעיר שזה התועלת אינו ממין התועלת הראשון אלא שהוא יגיע מן התורה בשנית ואולם בעצמות וראשונה יגיע ממנה הטוב האמתי שהוא הטוב הנפשיי:
@106 **התועלת** השתים עשרה במצות והוא מה שהוזהרנו שלא להוסיף על מצוות התורה ושלא לגרוע מהם באופן שימשך מזה הפסד מה בשמירת התורה והמצות והוא אמרו לא תוספיו על הדבר אשר אנכי מצוה אתכם ולא תגרעו ממנו לשמור את מצות יי' אלהיכם והתועלת באלו האזהרות מבואר כי לולי זה תפסד כוונת התורה בכללה וצוני לומר אם היה זה השער פתוח להוסיף על מצות התורה או לגרוע מהם וזה ממה שאינו צריך אל ביאור עם מה שקדם לנו מהדברים בזה הספר:
@106 **התועלת** השלש עשרה הוא להודיע עוצם השגחת השם יתעלה בישראל עד שכבר זכר שלא מת אחד מהם זולת אשר מתו על דבר פעור וכבר יה ראוי לפי המנהג הטבעי בעם גדול כזה שימותו בכל יום רבים מהם והיה זה כן כי כבר הבטיחם השם יתעלה שזה הדור יירשו הארץ וכמו שהמית במדבר הדור הקודם על מרים כן רצה להשאיר אלו כדי שיירשו כולם את הארץ ולזה זכר כי לולי עונם לא היה אחד מהם מת והעד על זה כי האנשים לבד אשר נכשלו בעון פעור מתו ולא מת זולתם כאמרו ואתם הדבקים ביי' אלהיכם חיים כלכם היום:
@106 **התועלת** הארבע עשרה הוא להעיר על עוצם החכמה והבינה שיישירו המצו' התלויו' בארץ שיחשב בתחלת העיון שאין בהם תועלת והם המצות אשר בקרבנות ובטומאות ובטהרות ומתנות כהונה ולויה ולזה אמר ראה למדתי אתכם חקים ומשפטים כאשר צוני יי' אלהי לעשות כן בקרב הארץ וגומ' כי היא חכמתכם ובינתכם לעיני הגוים וכבר ביארנו אנחנו במה שקדם אופן החכמה והבינה אשר יישירו אלו המצות ובכלל הנה תורתנו תיוחד משאר התורות והנימוסים שהיו לשאר האומות כי תורתנו אין בה דבר לא יגזרהו היושר והבינה ולזה היה זה הנימוס האלהי מושך האנשים מצד עצמותו אל שיתנהגו בו ואמנם נימוסי שאר האומות אינם כן כי הם מסודרים לפי יושר וחכמה והם נימוסי' זרים מטבעי האנשים ויתנהגו בהם האנשים על צד ההכרח מצד אימת המלכות ואימת הטלת העונש לא מצד עמצותם:
@106 **התועלת** החמש עשרה הוא מה שצונו לזכור ענין מעמד הר סיני והדברים ששמענו שם מפי הגבורה הם עשרת הדברים אשר יקיפו באופן מה שבכל המצות התוריות ועניין זה הזכרון הוא שנודיע זה לבנינו ולבני בנינו דור אחר דור למען יתפרסם זה לכולם וישמרו מצוות התורה וילמדו ליראה את השם הנכבד והנורא וידענו כי לא ראו שם כל תמונה ולזה ירחיקו התמונה מהשם יתעלה ויהיו נשמרים מעשות פסל ותמונה ומנתינת אלהות לזולת השם יתעלה כמו שביאר האזהרה בזה הדבור השני מעשרת הדברות:
@106 **התועלת** השש עשרה הוא במצות. והוא להודיע שכמו שהאדם חייב ללמוד את בנו כמו שכתוב ושננתם לבניך כן הוא חייב ללמוד את בן בנו כמו שנאמר והודעתם לבניך ולבני בניך:
@106 **התועלת** השביעי עשרה הוא להודיע שהתורה השתדלה לפי מה שאפשר לשמור את ישראל שלא יפלו ברע אשר נפלו בו מפני עבדם עבודה זרה ולזה הודיעם השם יתעלה ענין הגליות אשר יפלו בהם בהמשכם לעבודה זרה ולזה לא נמנעו ישראל עם כל זה מהמשך לעבודה זרה ונפלו ברע אשר יעדה התורה על זה לא נפל דבר:
@106 **התועלת** השמנה עשרה הוא להודיע שכבר ימשך מההשגחה הפרטית ענין דומה למה שנמשך מההשגחה הכוללת רוצה לומר שכמו שימשך לאדם מההצלחה מההשגח' הכוללת שיושגחו בה הוא וזרעו זמן ארוך מאד ג"כ יקרה זה מצד ההשגחה הפרטית כאשר היתה שלמה ולזה תמצא שספר כי מפני השגחת השם יתעלה על האבות יושגחו זרעם אחריהם תמיד בדרך שלא יכלו ומפני זאת ההשגחה השגיח השם יתעלה על ישראל בהיותם במצרים והוציאם משם באותות ומופתים נפלאים לקרבם לעבודתו כדי שיהיו ראויים לירושת הארץ ולזאת הסבה נתן להם התורה התמימה ונתנה להם בזה האופן הנפלא שהיה במעמד הר סיני להביאם על כל פנים אל שימשכו אחר תורתו השלמה כדי שיזכו שתנתן להם הארץ שנשבע השם יתע' לאבותינו לתתה לזרעם:
@106 **התועלת** התשע עשרה הוא בדעות. והוא להודיע כי מי שהוא אלהי השמים הוא אלהי הארץ אין שם שני אלוהות יהיה האחד אלהי השמים והאחד אלהי הארץ כמו שהאמינו המאמינים בשניות וזאת הידיעה קנו ישראל מענייני המופתים הנפלאים שעשה השם יתעלה שלא ימשך ענינם מצד הטבע אשר באו באלו הדברים השפלים כמו שאמר אתה הראית לדעת כי יי' הוא האלהים אין עוד מלבדו כמו שביארנו ואם אמר אומר הנה זה לא יתן האמת בזה על כל פנים כי אולי יאמר אומר כי אלהי הארץ ינהיג הארץ לפי הטבע וכשיצטרך ישנה הוא מנהג הטבע אמרנו לו כי משה לא היה מדבר לסכלים כי כבר היו זקני ישראל והוא מבואר שלא יוכלו להניח שאלהי השמים יהיה נבדל מאלהי הארץ בדרך שיהיו שנים כי הם רואים הרבה מהנהגת ענייני הארץ מסודרת מצד השמים ולזה יחוייב שיהיה מי שיכול לשנות זה הסידור אשר בארץ עליון על כל השמים ואין צריך לומר שהוא עליון על הארץ ומזה התבאר כי מעניין המופתים נעמוד על שבכאן מנהיג אחד הגלגלים בכללם:
@167 והנה התועלות המגיעות ממנה הם י"א.
@167 **התועלת** הראשון להודיע שכל מצות התורה נתנו במעמד הר סיני בזמן הר סיני אך לא נתחדש אחר זה בתורה דבר שלא נכלל במה שנזכר שם ואולם אלו הדברים ששמע אז סדר משה לבני ישראל בעבר הירדן בגאי מול בית פעור ולזה אמר וזאת התורה אשר שם משה לפני בני ישראל. אשר דבר משה אל בני ישראל בצאתם ממצרים:
@167 **התועלת** השני הוא להעיר שפנת התורה הוא להאמין בשם יתעלה ולהרחיק עובדה זרה לזה הזהיר משה על שתי אלו המצות ממה שקדם מזאת הפרשה שנכלל בה הצווי על האמונה שהשם יתעלה הוא אלהי השמים ואלהי הארץ והאזהרה מעשיית פסל ומסכה ומעבוד זולתו יתעלה וביאר העונש הנפלא שימשך בזה מענין ירושת הארץ ואחר הפסיק הענין ושב להתחיל זכרון עשרת הדברים בכללם והרבה ממצות התורה שנתנו במעמד הר סיני ואם לא נזכרו קצתם כי אם בזה המקום:
@167 **התועלת** השלישי הוא במצות והוא להודיע שכל אדם מחוייב ללמוד תורה ואף על פי שיוכל לעשות מצותיה בזולת למידת התורה בשישאל זה ליודעי התורה וזה למדנו מאמרו ולמדתם אותם ושמרתם לעשותם ולא אמר ולמדתם אותם למען תעשו אותם אך הלמידה מצוה והמעשה מצוה והיה זה כן כי הלמידה מביאה לעמוד על כוונת התורה יותר מהמעשה עם שהלמידה ימצא בה תועלת להביא אל המעשה ולזה הוא מבואר שגדול שכר תלמוד תורה משכר עשיית מצוה מהמצות:
@167 **התועלת** הרביעי הוא להודיע שלא נתנה התורה לדור ההוא לבד אך לכל הדורות הנמשכים אליהם. ולזה אמר לא את אבותינו כרת את הברית הזאת וגומ'. ואמר מי יתן והיה לבבם זה להם ליראה אותי ולשמור את כל מצותי כל הימים ואמר אשר אנכי מצוך אתה ובנך ובן בנך כל ימי חייך כי זה כולו יורה שהתורה נתנה לדורות הנמשכים לאין תכלית וזאת היא מפנות הגדולות שבפנות התורה והיא מחוייבת עוד מצד העיון כי לא יתכן שיוחס לשם יתעלה שנוי רצון כמו שיתבאר במקומותיו וכבר אמר הנביא גם כן אני יי' לא שניתי:
@167 **התועלת** החמישי הוא במצות והוא להודיע שהנשים מחוייבות לקדוש היום וזה למדנו מאמרו שמור את יום השבת לקדשו כמו שביארנו בבאורנו בזה הפסוק:
@167 **התועלת** הששי הוא להודיע שהתורה כבר תצוה במצוה אחת לתועלת יותר מאחר וזה ממה שיפתח לנו השער לעמוד על הרבה מכוונות מצות התורה כמו שיתבאר מדברינו בזה הספר וזה למדנו ממה שנתן בזה המקום הסבה במצות שבת לזכור ענין יציאת מצרים ובפרשת יתרו נתן הסבה בה לזכור דבר חודש העולם:
@167 **התועלת** השביעי הוא להודיע שלולי יראת ישראל מהדברים הנפלאים שבמעמד הר סיני כבר היו ישראל שומעים כל התורה מפי הגבורה כי הקול הנפלא ההוא לא פסק בעת שעמדו העם מרחוק ובקשו ממשה שישמע הוא הדברים ויביאם אליהם ואל ידבר עמם אלהים פן ימותו וזה ממה שיוסיף אמות להם על שהתורה בכללה הוא מה' יתעלה ואף על פי שהיה משה באופן מהמעלה שהיה ראוי שיאמינו בו ישראל הנה רצה השם יתעלה בזה לפי שזאת התורה כוון בה שתהיה נצחית ושלא יאמן נביא שיאמר דבר בסתירה ממנה ואלו לא היתה לישראל אמונה בה אם לא מפי משה לא יתכן זה כי יאמרו למה נאמין יותר במשה ממה שנאמין בזה הנביא אשר נתן לנו אותות ומופתים ואולם עתה יתכן זה כי יאמרו לא נוכל להאמין מי שיאמר דבר מכחיש מה שראינו בעינינו ולזאת הסבה גם כן רצה השם יתע' שיהיה מכתב הלוחות מעשה השם יתעלה לא במלאכה:
@167 **התועלת** השמיני הוא באזהרות והוא מה שהזהרנו שלא נתאוה..:
@167 חסר כאן ובכל העתקות שהיו לפנינו.:
@167 **התועלת** התשיעי הוא בדעות והוא להודיע כי השם יתעלה לא יגזור בענינים הבחיריים דבר על דרך החיוב אבל יניחהו אפשרים אלא אם היה זה על דרך המופת וזה יהיה בפרט מה ובעת מה לא תמיד וכבר למדנו זה ממה שאמ' מי יתן והיה לבבם זה להם ליראה אותי כמו שביארנו בביאור דברי זאת הפרשה:
@167 **התועלת** העשירי הוא ללמדנו שכבר היה מהשם יתע' שיהיה משה פורש מן האשה מצד שקדו עם השם יתעלה תמיד ודבר זה למדנו מאמרו לך אמור להם שובו לכם לאהליכם ואתה פה עמוד עמדי:
@167 **התועלת** האחת עשרה הוא להודיע כי השם יתעלה מסר המצוה וחוקיה ומשפטי' למשה ופירושיה ודקדוקיה וצוהו שילמדה בזה האופן לישראל וזה לאות כי הוא ילמד לישראל דבר לא נכתב בתורה כמו שביארנו שאם לא היה אומר לישראל זולת הכתוב בתורה לא היה אור אשר תלמדם אבל יאמר אשר תגיד להם או תאמר להם ואולם אומר אשר תלמדם כי הוא יבאר להם לשון דברי התורה באופן שיעמדו על כוונותיה:
@195 **שמע ישראל יי' אלהינו יי' אחד עד סוף הפרשה:**
@195 והתועלות הם י"ט:
@195 **התועלת** הראשון הוא במצות והוא מה שצונו להאמין שהשם יתע' הוא משגיח בו עדת ההולכים בתורתו ותועלת זאת המצוה הוא רב בדעות והוא עם זה מהגדולות שבפנו' התור' וכבר ביארנו אמות זה השרש מצד העיון והתרנו כל הספקות הנופלות בו ברביעי מספר מלחמות ה' ובביאורינו לספר איוב:
@195 **התועלת** השני במצות והוא מה שצונו להאמין כי יי' אחד אחדות אמתי לא ישתתף לו בו זולתו וכבר ביארנו אמות זה השרש ושהוא ראוי שיתואר השם יתעלה בשני אלו השמות שזכרה בה התורה בחמישי ממ"י ובביאורנו למה שאחר הטבע:
@195 **התועלת** השלישי הוא במצות והוא מה שצונו לאהבה השם יתעלה בזה האופן הנפלא שיקל לנו כבוד המות לכבודו יתעלה והתועלות בזאת המצוה מבואר כי זה ממה שיביא בתכלית מה שאפשר לקנין השלמות האנושי וההצלחה הנפשיית אשר אין הצלחה זולתה כמו שביארנו בבאור זאת הפרשה:
@195 **התועלת** הרביעי הוא במצות והוא מה שצונו ללמד אלו הדברים שהם פנות התורה כדי שיתישבו אלו הפנות והאמונות האמתיות בלבם ויגדלו עליהם וכן צוה זה בעשרת באמרו והודעתם לבניך ולבני בניך ואמר בכללות למען ילמדון ליראה וגו'. ואת בניהם ילמדון וזה מקיף בכל מצות התורה כי כבר היו שומעין אותם כולם מפי השם יתעלה לולי יראתם מהאש ולזה כשלמדו' ממשה חוייבו ללמדם לבניהם דור אחר דור:
@195 **התועלת** החמישי הוא במצות והוא מה שצונו לקרא פרשת שמע שתי פעמים ביום. ר"ל בשכבנו ובקומנו כי בה זכירת אלו המצות שזכרנו שהם פנות התורה ואמנם היתה הקריאה באלו העתים כי אלו העתים יורו על שיש לגלגלי' תנועה כשיעוין אז בכוכבי לכת ובכוכבים הקיימי' שיראו בו כוכי לכת מתרחקים מהכוכבים הקיימי' שהם קרובי' אליהם או הפך או יעויין בשמש עם הנץ החמש כי ראה שמקום זריחתו ביום האחר וזה יורה על שהשמש מתנועע לא הארץ כמו שחשבו קצת הקודמים ולזה הוא מבואר שאלו העתים יורו שיש לגלגלים תנועות מתחלפות ויצטרכו מפני זה אל מניע קודם להם וזה יביא בהכרח להאמין שיש שם אלוה אחד שיסודרו ממנו כל אלו התנועות אשר ישלם בכללם זה המציאות השפל:
@195 **התועלת** הששי במצות והוא מה שצונו להניח תפילין על הפרק שאחר הזרוע כנגד הלב והנה נכללו בהם ד' פרשיות והם קדש לי כל בכור והיה כי יביאך שהם מזכירות ענין הנפלאות שהיו ביציאת מצרים אשר יישירו לאמונת ההשגחה וייחוד השם יתעלה ולאהבתו הנכללים בפרשת שמע ואחריהם היתה פרשת והיה אם שמוע להעיר על שכבר יגמול השם יתעלה גמול טוב לאוהבי השם יתעלה ויענוש עונש נפלא לעובדי ע"ז ולזה היו אלו הפרשיות בזה הסדור והנה התועלות בזאת המצות מבואר והוא שיהיה זה לנו לאות שיהיו הדברים האלו על לבנו תמיד לא נשכחם:
@195 **התועלת** השביעי הוא במצות והוא מה שצונו לכתוב אלו הד' פרשיות הנזכרות בסדר הנזכר בתפילין של ראש בד' בתים והתועלת בזאת המצוה הוא שיהיו אלו הדברים לנו לזכרון ולזה הושמו על המוח ששם כח הזוכר והנה היו אלו הפרשיות בתפילין שן ראש בד' בים ובתפילין של יד בבית אחד לסבה שזכרנו בביאורינו לזאת הפרשה והוא כי מזה הצד נתישר אל היות השם יתעלה אחד עם הסתעף ממנו פעולות רבות:
@195 **התועלת** השמיני הוא במצות והוא מה שצונו לכתוב פרשת שמע והיה אם שמוע אצל מזוזת ביתנו כדי להעיר אותנו כי שם ה' נקרא שם ולא יתן המשחית לבא אל בתינו עם שזה יהיה סבה לזכירת אלה הפנות הגדולות אשר צריך שיתנם האדם אל לבו תמיד:
@195 **התועלת** התשיעי הוא במצות והוא מה שצונו ליראה מהשם יתעלה ותועלת זאת המצוה מבואר ממה שזכרנו בביאורנו לזאת המצוה ובכלל הנה היא מישרת להגעת אל השלמות האנושי בתכלית מה שאפשר כמו שבארנו:
@195 **התועלת** העשירי הוא במצות והוא מה שצונו לעבוד השם יתעלה והוא שנבקש מנו הצרכי ותועלת זאת המצוה מבואר כי זה יהיה סבה שנשיג משאלות לבו כי בכל קראנו אליו יענה אם נקרא לו באופן ראוי ויישירנו זה גם כן אל האמונה שכל הטובות הם שפועות מאתו יתע' שהיא מהגדולות שבפנות התוריות והעיוניות:
@195 **התועלת** האחד עשרה הוא במצות והוא מה שצונו להשבע לשמו יתעלה לעת הצורך והנה תועלת זאת המצוה להישיר אל שהשם יתע' הוא אמתי המציאות וקיים ונצחי ולזה תיהיה השבועה בו להורות על אמתת מציאות מה שעליו וקיומו:
@195 **התועלת** השתים עשרה הוא במצות והו' מה שהזהירנו מלנסות את יי' כי זה אולי יביא למעוט אמונה בו כשתקצר יד הנביא מעשות כמו זה המופת:
@195 **התועלת** השלש עשרה הוא במצות והוא מה שצונו להודיע לבנינו ענין עבודתנו במצרים ושהוציאנו משם הש' יתעלה באותות ובמופתי גדולים כשישאלו מה הסבה לאלו העדות והחקים והמשפטים אשר צוה השם יתע' לעשות בפסח או בדבר הבכורות או בשאר מה שצונו השם יתע' שהוא זכר ליציאת מצרים והנה התועלת בה מבואר כי בזה יתפרסמו לו אלו הנפלאות ויתחנך בעבודת השם יתעלה:
@195 **התועלת** הארבע עשרה הוא בדעו' והוא מה שהודיענו כי בשמירת מצות התורה נזכה להצלחה נצחית והיא הצלחת הנפש וימשך לה גם כן הצלחה גופיית והיא הצלחת הגוף וכבר העיר על זה באמרו לטוב לנו כל הימים ולחיותינו כיום הזה:
@195 **התועלת** החמש עשרה הוא במצות והוא מה שהזהירנו מחמול על אחד מז' עממין באמרו לא תכרות להם ברית ולא תחונם והתועלת בזאת האזהרה מבואר שהיא כדי שלא יחטיאו ישראל ויביאום לעבוד ע"ז:
@195 **התועלת** השש עשרה הוא במצות והוא מה שהזהירתנו מהתחתן בעובדי ע"ז ותועלת זאת האזהרה כי זה יהיה סבה אל שיהיה הזרע עובד ע"ז כמו שזכרה התורה:
@195 **התועלת** השבע עשרה הוא במצות והוא מה שצונו לעקור ע"ז מארצינו ולזה אמר מזבחותיהם תתוצון ומצבותיהם תשברון ואשיריהם תגדעון ופסיליהם תשרפון באש:
@195 **התועלת** השמונה עשרה הוא להודיע כי לא בחרבם ירשו ארץ ישראל כי הם המעט מכל העמים אך יהיה להם זה מצד אהבת השם יתעלה אותם שתדבק השגחתו בהם ומפני בריתו עם האבות שהיתה סבה אל שהביא השם יתע' ישראל לעבודתו והיתה זה סבה אל שיהיו ישראל יותר ראוים לירושת הארץ
@195 **התועלת** התשע עשרה הוא להודיע שהטובות אשר ייעד השם יתעלה לטובים ימתין להם העת אשר תהיינה בו יותר טובות ולזה יתכן שימתינם לאלף דור כדי שישים אותם הטובות באופן שלא יסורו אז ובאופן שתהיינה בתכלית מה שאפשר מהשלמו' ואין הענין כן בטובות אשר יביא על הרשעים הראויות לבא להם כי לא יאחרם אך יביאם להם תכף בא העת כדי שיאבדו ברע בבא להם אחר הגעת הטובות ההם להם והנה אמר זה לתת סבה שלהטיב ישראל המתין להם הש יתעלה הגעת הטוב שייעד לאברהם זמן ארוך עד שעדין לא הגיע אל תכליתו כאלו היה זה סבה שלא יכלו ישראל ברעות שהיו ראויות לבא עליהם בעבדם ע"ז כדי שלא תופר בריתו עם האבות ושמר השם יתעלה הגעת הטוב ההוא אל תכליתו אל העת שלא יתכן שיקרה לישראל רע אחריו כי כל האמונות ישובו אז אל האמונה האמתית כמו שאמר הנביא כי אזאהפוך אל עמים שפה ברורה לקרא כלם בשם יי' ולעבדו שכם אחד וכבר התבאר שעדין לא הגיע הטוב ההוא אל תכליתו כי כבר נשבע השם יעת' לאברהם לתת לזרעו ארץ עשר אומות ולא השתדלה התורה עתה לתת לישראל כי אם ארץ ז' אומות ועוד שכבר נאמר בתור' שכאשר ירחיב השם יתעלה את גבולנו נוסיף עוד שלש ערים על שש ערי המקלט וזה דבר לא נהיה עדין לפי מה שהועתק לנו מאלו הקורות בדברי הנביאים וזה לאות כי הרחבת הגבול ההוא יהיה בימי מלך המשיח שאנחנו מקוים יהי רצון שיבא במהרה בימינו והנה הזהירה התורה במקומות רבים מעבוד ע"ז וצותה לשמור מצות התורה למען ירשו ישראל את הארץ ולא יגלו ממנה כי כבר היה נגלת לשם יתעלה שהם ישחיתו אחרי היותם בארץ ויעדו עבודה זרה ויהיה זה סבה להביא עליהם רעות גדולות נפלאות ולזה כפלה להם אלו האזהרות והצווים פעמים רבות כדי להצילם מאלה הרעות לפי מה שאפשר:
@228 והיה עקב תשמעון וגו' עד סוף הפרשה.
@228 ואולם התועלות המגיעות ממנה הם כ"ו:
@228 **התועלת** הראשון הוא להודיע כי בשכר שמירת ישראל המצות המתין להם השם יתעלה השלמת קיום מה שנשבע לאבות אל העת היותר נאות להם כמו שביארנו בפרשת ואתחנן וזה כי ישמרם שלא יכלם בעוברם על מצות השם יתעלה כדי שלא תופר בריתו עם האמת ולזה אמר והיה עקב תשמעון את המשפטים וגומ'. ושמר ה' אלהיך לך את הברית ואת החסד אשר נשבע לאבותיך:
@228 **התועלת** השני הוא להודיע שכבר ימשכו משמירת מצות התורה וחקיה ומשפטיה טובות גופיות נפלאות לא טובות נפשיות לבד וימשכו מפני הפך זה רעות גופיות עצומות לא רעות נפשיות לבד וזה נכפל מאד בזאת הפרשה ובכל זה הספר ולזה אמר ואהבך וברכך והרבך וברך פרי בטנך וגו'. והיה אם שכוח תשכח את ה' אלהיך וגומ'. והיה אם שמוע תשמעון:
@228 **התועלת** השלישי הוא להודיע שמי שהבטיחהו השם יתעלה בנצוח איש מה על צד ההשגחה הפרטית ראוי שלא יירא שלא ינוצח מצד גבורת שכנגדו כי יד השם יתעלה לא תקצר ולזה זכר משה לישראל הנפלאות שעשה השם יתעלה לישראל אשר ראוי להם מצדם שלא ייראו מהגוים ההם אשר הם באים להלחם עמהם ואם הם יותר חזקים מעם ישראל כי יד השם יתעלה לא תקצר להפיל אותם לפניהם:
@228 **התועלת** הרביעי הוא להודיע כי אף על פי שהשם יתעלה שליט לעשו' כל מה שירצה וכל אשר יחפוץ הנה יבקש הסבות היותר נאותות שאפשר ולא יחדש מופת אלא אם יביא הצורך אל זה כי הוא אינו שונא הטבע כי הוא סדר אותו ולזה לא יחלוק עליו אלא בעת הצורך וביותר מעט שאפשר לו אז לחלוק עליו ולזה אמר ונשל ה' את הגוים האלה מפניך מעט מעט לא תוכל כלותם מהר פן תרבה עליך חית השדה ואף על פי שהיה השם יתעלה יכול לכלותם מהר ולשמור ישראל שלא תרבה עליהם חית השדה הנה לא הסכים לעשותו וזה אחר שאפשר הגעת המכוון לישראל בזולת זה:
@228 **התועלת** החמישי הוא במצת והוא מה שהזהירנו מלהנות בצפוי ע"ז וכ"ש בע"ז עצמה שנאמר לא תחמוד כסף וזהב עליהם ולקחת לך והנה התועלת בזאת האזהרה מבואר ממה שזכרנו לבאור זה הפסוק:
@228 **התועלת** הששי הוא במצו' והוא מה שהזהירנו מהביא תועבה אל ביתנו והוא ממון אנשי עיר הנדחת אעפ"י שלא היה צפוי עבודה זרה ולא עבודה זרה כי הוא חרם כמו שנזכר בפרשת עיר הנדחת וצותה התורה לשרפו אל תוך רחובה לפי שהוא חרם ובזה המקום הזהיר שלא להביא תועבה אל ביתנו ולפי שממון עיר הנדחת הוא חרם כמו שנזכר בפרשה היא למדנו מזה שאנחנו מוזהרים שלא להנות בו:
@228 **התועלת** השביעי הוא להודיע עומק מחשבות השם יתעלה שעם היות ישראל מתאחרים במדבר ארבעים שנה על צד העונש השתמש בזה לתועלת הוא לנסותם אם ישמרו מות השם יתעלה אם לא כדי לעמוד על העת שיהיו ראויי' בו לירושת הארץ ולזאת הסבה גם כן יסרם שם תכף מרותם מה שאינו ממנהג השם יתעלה כי הוא ארך אפים אבל להשגחת כל ישראל עשה זה כדי שישמרו מחטוא לה' ולזה גם כן ענם והרעיבם במדבר ארבעים שנה להראות לישראל נפלאות השם יתעלה כדי שיחזקו לשמור מצותיו:
@228 **התועלת** השמיני הוא להודיע שהפירות המיוחסים אל ארץ ישראל הם שבעה מינים לבד והם חטה ושעורה וגפן ותאנה ורמון וזתים ותמרים ומזה יתבאר אי זה מהמינים יוחסו לארץ ישראל:
@228 **התועלת** התשיעי הוא במצות והוא מה שצונו לברך השם יתע' אחר אכלנו לחם לשבוע ולתת לו תודה על הארץ הטוב' אשר נתן לנו אשר ממנה יצא לחם לט מעט ועל המזון שחנן אותנו ולפי שזאת ההנאה היא יותר שלמה מהנאת שביעת אכיל הפירות המיוחסים לארץ ישראל הנה נלמוד מזה שיהיה הדין באכילת הפירות ההם אך חכמים תקנו להם ברכה מעין שלש ברכות להמשך לכוונת התורה כי בזה תועלת להישיר אל האמונה שכל הטובות הם שפועות ממנו יתע' ומזה גם כן נתישרו לתקן שעל כל הנאה שתגיע לנו באכילת דבר או בשתייתו או בריחו נודה ונברך השם יתעלה הממציא לנו כל אלו הטובות:
@228 **התועלת** העשירי הוא להודיע שהוא מחויב שייחס האדם כל הטובות המגיעות אליו אל השם יתעלה כי מאותו הכל וכל שכן בדברים אשר לו יתכן הגעתם אם לא מצד העזר האלהי כמו הענין בנצוח ישראל אלו הגוים הגדולים והעצומים מהם שהיו בהם מבני הענק והיו בערים גדולות ובצורות בשמים ולזה אמר שאין ראוי שיאמר ישראל כחי ועוצם ידי עשה לי את החיל הה אך יזכור כי יי' אלהיו הוא הנותן לו כח לעשות חיל וידע כי הוא אשר ישמידם ויאבדם לא עוצם ישראל וכחו:
@228 **התועלת** האחת עשרה הוא מה שהודיע לישראל כי לא בצדקתם ישרשו ארץ אך ברשעת הגוים ההם מצורף עם ברית שם יתעלה תמיד עם האבות ונתן להם ראייה כי לא בצדקתם היה זה לפי שכבר היו ממרים עם השם יתעלה תמיד כמו שספר להם והיה ראוי שיעזבם השם יתעלה ולא ישתדל בהשלמתם לולי ברית השם יתעלה עם האבות ולזה הוא מבואר שלא היה זה הטוב לישראל כי אם בסבת האבות כי לא היו ראויים בהתחלה אל שישגיח השם יתעלה בהשלמתם בזה האופן הנפלא אך עכ"פ תצטרך לירושת הארץ בזה האופן צדקת ישראל כמו שזכר במקומות רבים שאם ישמרו מצות התור יבואו וירשו את הארץ ולזאת הסבה גם כן זכר שנתאחרו במדבר בסבת מרים. והנה התועלת בזה כדי לזרז ישראל שישמרו מצות השם יתעלה כמו שביארנו אצל ביאורינו אלו הדברים בזאת הפרשה:
@228 **התועלת** השתים עשרה הוא להודיע עוצם השתדלות משה להציל ישראל מהרע הנפלא שיעד לו השם יתעלה על דבר העגל עד שכבר התנפל לפני השם ית' ארבעים ים וארבעים לילה בזולת אכילה ושתייה עד שנעתר לו השם יתעלה ומחל להם כל חטאתם אשר חטאו בדבר העגל והנה הוצרך להתנפל לפני השם יתעלה כל זה הזמן הארוך לפי מה שאחשוב כי אולי בעבור כעם משה על הפלגת מרים ישראל בזה הוסר המעט מהדבקות שהיה לו עם השם יתעלה ולזה הוצרך להתמיד כל זה הזמן להשים עצמו באופן מהדבקות שהיה עם השם יתעלה עד שמפני צערו על אבדן ישר' ימלט העם בהשגיח השם יתעלה על משה להצילו מזה הצער הנפלא שהיה מצטער עליהם עם שרוב שקדו על זאת התפילה ועמדו מלאכול ולשתות הרבה צערו והיה זה סבה להשמע תפלתו:
@228 **התועלת** השלש עשרה הוא להודיע שצריך שמי שישתדל בהסרת הרע מה שישתדל בזה בהדרגה קצת אחר קצת כי אולי אם יכוין להסירו לגמרי תכף לא יוכל עליו ולזה צריך שיכוין להסיר ממנו תחלה מה שלא יכבד מאד להסירו ואחר זה יגרשהו מעט מעט בהדרגה ולזה תמצא שספר כי בראות משה אף השם יתע' וחמתו ורצותו לכלות ישראל בקש מהשם יתעלה להמתין הרע ההוא כדי שיוכל במה שהיה לו מהפנאי לנקות ישראל מהרע ההוא כי בזולת זה לא יהיה לומבא לבקש בעבורם מחילה ואח זה התנפל לפני השם יתע' זה הזמן הארך להסיר מישראל האף והחמה על כל חטאתם אך היה צריך עדין לשאול שיגיעו להם טובות מהשם יתעלה על צד ההשגחה הפרטית ואם לא הנה ישיגם הכיליון בכרח לפי הענין שהיו בו אז שהיו במדבר והוצרכו להלחם עם הגוים הוצרכו עזר מהשם יתעלה על צד ההשגחה הפרטית להיות להם ארץ ישבו בה וזהו מה ששאל משה ממנו יתעלה בארבעים יום השלישיים כמו שנתבאר בפרשת כי תשא ולזה סמך לזה הספור מה שצוה השם יתעלה למשה קום לך למסע לפני העם ויבאו ויירשו את הארץ להעיר שעד עתה לא היו נכונים לזה:
@228 **התועלת** הארבע עשרה הוא להודיע שראוי שיהיה האדם זריז שלא יסבב בשום צד להחטיא את הרבים ואף על פי שתהיה כוונתו הראשונה לשמרם מהחטא הלא תראה כי אהרן אף על פי שהיה משתדל בחכמתו להצל מן החטא כמו שבארנו בפר' כי תשא הנה מני שהיו דבריו באופן שנמשך מהם במקרה החטא לישראל כמעט שהשמידו השם יתעלה לולי תלת משה:
@228 **התועלת** החמש עשרה הוא מה שהודיע לנו בזה הספור כי בכל מקום שם או מעת נסעם ממוסרה עד קדש היה שם מים ולזה אמר מבארות בני יעקן ארץ נחלי מים כדי להודיע רוע תכונת ישראל שנתרעמו עמו תכף שהיו במקום שלא היה שם מים:
@228 **התועלת** השש עשרה הוא להודיע שאין ראוי למוכיח שיספר דבר יהיה אפשרי להית סבה אל שלא תקובל תוכחתו ולזה לא רצה משה לבאר בזה המקו' שיהיה מוכיח בו ישראל שעל דבר מי מריבה מת אהרן ונגזר מות על משה בעצמו כי החטא ההוא היה נעלם ויוכלו לומר כי לא יועיל ההשמר מהחטא כי אלו מתו בלא חטא עם גודל מעלתם ולזאת הסבה לא רצה לספר דבר קרח מפני שהיה גדול המעלה אצלם כדי שלא יהיה מקום לנטות מתוכחתו:
@228 **התועלת** השבע עשרה הוא להודיע שאין ענין התורה להעמיס עלינו דברי' זרים בלתי נאותים אך תצוה לבד על דברים מועילים מצד עצמותם בהפך הענין בשאר התורות לה אמר מה יי' אלהיך שואל מעמך כי אם ליראה וגומ' אשר אנכי מצוך היום לטוב לך:
@228 **התועלת** השמנה עשרה הוא להודיע כי כל דרכי השם יתעלה משפט לא ישא פנים ולא יקח שחד אך כקטון כגדול בהשפטם ולזה ראוי שייראו ממנו וימלו את ערלת לבבם ולא יקשו עוד ערפם כי הוא שליט להגיע להם עונש או גמול מצד השגחתו הפרטית כי הוא מושל על כל שאר הנבדלים אשר יסודר מהם פעולות מה באלו הנמצאות לפי מה שהכין להם השם יתעלה מהכח ביום הבראם ומה שיושפע ממנו לה תמיד ולזה יוכל השם יתעלה לשנות הסדורים ההם כי הוא מושל על כל מי שתהיה לו איזה ממשלה שתהיה והוא לבדו לעשות גדולות וגבורות ונוראות והם הפעולות המסודרות מהשגחה הפרטית לחלוק על המסודר מההשגחה הכוללת:
@228 **התועלת** התשע עשרה הוא להודיע שהשם יתעלה סדר המציאות באופן שאין החלושי' והשפלי' נתונים ביד מי שתקיף מהם כי גבוה מעל גבוה שומר וגבוהים עליהם ובזאת ההשגחה ינצל עני מחזק ממנו כמו שביארנו בביאורנו לספר איוב ובהיות הענין כן הנה מי שירדוף החלושי' ילך כנגד כוונת השם יתע' אשר השגיח בהם בזה האופן וישיגהו עונש נפלא מהשם יתעלה ולזה אמר ששם יתעלה עושה משפט יתום ואלמנה לזרז ישראל שישפטום בצדק כי בסוף כשלו בזאת המדה הפחותה כאמרו יתום לא ישפוטו וריב אלמנה לא יבא אליהם:
@228 **התועלת** העשרים הוא להודיע שהשם יתעלה סדר המציאות באופן שינתן לכל גויה די מחסורה כאמרו נותן לחם לכל בשר ומשביע לכל חי רצון ומזאת ההשגחה ימשך שיתן השם יתע' לגר תושב העומד בארצנו לחם ושמלה ולזה צוה לאהוב את הגר וללכת בדרכי השם יתעלה שהשגיח בו בזה האפן ובזה נקנה לעצמנו מדה חשובה:
@228 **התועלת** האחת ועשרים הוא במצות והוא מה שצונו להדבק בשכינה לפי מה שאפשר וזה יהיה בהתדבקנו לחכמים כי הם יישירונו על מה שיתכן שנגיע אליו מזה:
@228 **התועלת** השנים ועשרים הוא להודיע עוצם הפלא שעשה השם יתעלה לישראל במצרים כי במתי מעט באו שם ובזמן לא ארך שעמדו שם שמם השם יעת' בז הרבוי הנפלא עם רב השתדלות המצרים להמעיט אותם כפי יכלתם:
@228 **התועלת** השלש ועשרים הוא להודיע שתורתנו היא נצחי' לא תשתנה לעולם ולזה אמר ושמרתם את משמרתו וחקותיו ומשפטיו ומצותיו כל הימים ולזה גם כן אמר בפרשת והיה אם שמוע למען ירבו ימיכם וגומ'. כימי השמים על הארץ כי זה יורה שאם תשמרו מצותיו אשר הוא מצוה אתכם היום כמו שזכר שזאת הפרשה ירבו ימי ההולכים בדרך זה תמיד כימי השמים על הארץ וזה לאות כי כל התורה תתקיים כימי השמים על הארץ וזה ממה שלא יצטרך אל ביאור למעיין בזה הספר:
@228 **התועלת** הארבע ועשרים הוא להודיע שאלו הנפלאו' שספר משה לכל ישראל שעשה להם השם יתעלה ספרם למי שראו זה בעיניהם וידעו שהענין הוא כן כמו שספר מהם וזה ממה שיוסיף אמות בזה הספור ולזה אמר וידעתם כי לא את בניכם אשר לא ידעו ואשר לא ראו וגומ'. כי עיניכם הרואות את כל מעשה יי' וגו':
@228 **התועלת** החמש ועשרים הוא להודיע טוב ארץ ישראל גם בתועלות הגופיות כי היא תשתה מים תמיד למטר השמים ויבא בה הצריך לנתינת הצמחים פרים מרוחות וממטר על הרוב כאלו עיני השם יתעלה בה מראשית השנה ועד אחרית השנה:
@228 **התועלת** השש ועשרים הוא במצות והוא מה שצונו מפרשת והיה אם שמוע שנלמד אותה לבנינו ושנקרא זאת הפרשה בשכבינו ובקומינו ושנכתב' בתפילין של ראש ובתפילין של יד ועל מזוזות בתינו והנה התועלת באלו המצות לפי מה שהשרישה התורה מענינם הוא מה שהתבאר בפרשת ואתחנן ובפרשת בא על פרעה:
@339 **ראה אנכי נותן לפניכם היום וגו' עד כי יכרית יי' אלהיך את הגוים.**
@339 **ואולם התועלות המגיעים ממנה הם י"ו:**
@339 **התועלת** הראשון הוא במצות והוא מה שצונו אחר עברם את הירדן לתת ברכה על הר גריזים והקללה על הר עיבל כדי לזרז ישראל יותר בשמירת המצות שם כי זה עם מה שיועיל לאדם תועלת נפשיי ימשך להם מזה מהתועלת בענין ירושת הארץ כמו שקדם ויתבאר יותר בפרשת והיה כי תבא:
@339 **התועלת** השני הוא במצות והוא מה שצונו לעקור ע"ז מארצנו והנה התועלת בזאת המצוה מבואר כדי שלא ישאר זכר לע"ז ויוסר מהאנשים ההכשל בה והנה מני שאנחנו מוזהרים מעבודה זרה בכל המקומות הוא מבואר שראוי שנעשה כן בכל המקום שיהיה לנו ואולם ההבדל בזה בין ארץ ישראל וחוצה לארץ הוא שבארץ ישראל אנחנו מחוייבים לרדוף אחריה ולכלותה כדי שלא תשא ע"ז בארצנו כמו שצונו שלא ישבו בארצנו עובדי ע"ז כאמרו לא ישבו בארצך פן יחטיאו אותך לי אמנם בחוצה לארץ אין אנו מצווים שלא ישבו אתנו עובדי ע"ז וכמו זה אין אנחנו מצווים לרדוף אחר ע"ז שלהם לכלותה אך המקום שיהיה לנו בחוצה לארץ והיתה בו ע"ז הוא מבואר שאנחנו מצווים לכלותה משם:
@339 **התועלת** השלישי הוא במצות והוא מה שהוזהרנו מלנתוץ דבר דרך השחתה מהבנין שנעשה לשם יתעלה כ"ש שאנחנו מוזרים מלאבדו שנאמר ונתצתם את מזבחותם וגומ' לא תעשון כן לה אלהיכם והנה התועלת בזאת המצוה מבואר:
@339 **התועלת** הרביעי הוא במצות והוא מה שהוזהרנו מלאבד שם מהשמות הקדושים אשר לשם יתעלה והוא שנאמר ואבדתם את שמם וגומ' לא תעשון כן לה' אלהיכם והנה התועלת בזאת המצוה מבואר:
@339 **התועלת** החמישי הוא במצות והוא להודיע שלא יתכן שנעבוד השם יתעלה במקומות רבים כמו שעשו הגוים ההם לאלהיהם אך נעבדהו במקום מיוחד לבד והוא המקום אשר יבחר יי' להורות על יחוד השם יתעלה הנעבד בזאת העבוד' הנכבדת עם שמזה ימשך מהתועלת שתהיה זאת העבודה נעשית בבית הנפלא אשר בו הישרה נפלאה להעמיד על סודות המציאות ועל ידי משפחה מיוחדת נכונה לעמוד על אופן החכמה אשר בזאת העבודה מפני שקדת עליה והיותה בלתי צריכה אל אסיפת הקנינים כי לחמה נתן מימיה נאמנים והנה לא תנהג זאת המצוה כי אם אחר המצא שם מקום יבחר יי' שנאמר כי לא באתם עד עתה אל המנוחה ואל הנחלה מגיד שאחר שבאו אל המנוחה ואל הנחלה נאסרה בזה עולמית:
@339 **התועלת** הששי הוא במצות והוא מה שלמדנו מאמרו לשום את שמו שם שברכ' כהנים לא תהיה בשם המפורש אלא בבית המקדש ואף על פי שהיא תהיה בכל מקום כאמרו בכל המקום אשר אזכיר את שמי אבא איך וברכיך והנה התועלת בזאת המצוה מבואר והוא שאין ראוי לגלות ענין זה השם הנכבד רק במקום מיוחד לעבודתו כי מפני זה מצאו שם תמיד משיגים סוד זה השם לפימה שאפשר וזה ממה שישמר השומעים שלא יבאו מזה להריסה מפני השתבשם בענינו כי שם מי שישמרם מהשבוש הזה.
@339 **התועלת** השביעי הוא במצות והוא מה שצונו להביא כל הקרבנות שיש לנו איך שיהיו ברגל הראשון שנבא בו לבית הבחירה שנאמר ובאת שם והבאתם שמה עולותיכם וזבחיכם ומעשרו' וגו'. והתועלת בזאת המצות מבואר כדי שישלים חקו אשר צותה לו התורה מהם וישלם נדרם תכף שימצא לו מקום ראוי:
@339 **התועלת** השמיני הוא במצות והוא מה שהזהירתנו מהקריב קרבנות חוץ מהמקום אשר יבחר יי' והנה נתבאר תועלת זאת האזהרה ממיה שקדם:
@339 **התועלת** התשיעי הוא במצות והוא מה שצוה לפדות פסולי המוקדשים שיש בהם מום קבוע וביאר דיניהם אחר שנפדו שישאר בהם דין קצת הקדשים והתועלת בזאת המצוה הוא שלא להפסיד הקדשים אחר שאינם ראויים להקרבה ולזה צוה שיצאו לחולין בזה האופן שזכר באמרו שם תזבח ואכלת בשר:
@339 **התועלת** העשירי הוא במצות והוא שהזהרנו מאכילת מעשר דגן ומעשר תירוש ומעשר יצהר חוץ ממקום הבחירה ומאכילת בשר חטאות ואשמות חוץ למחיצתן ומאכילת בכורים קודם הנחתן בעזרה ומאכילת בשר עולה או מה שהוא ראוי למזבח או בשר קדשם קדם זריקת דמים כי עדיין לא התורה אכילתן בשום מקום והנה התועלת בזאת האזהרה הוא שלא נבלבל הסדור שסדרה התורה באלו הענינים הנפלאים כדי שנתישר אל הכונה שכונה התורה בזה:
@339 **התועלת** האחת עשרה הוא במצות והוא מה שהוזהרנו שלא נעזוב הלוי והתועלת בזאת המצוה מבואר כדי שתהיה זאת המשפחה הנכבדת מיוחדת לעבודת יי' יתע' ולא יהיה לה טרדה ובאסיפ' מזונותיה ועוד כי המעשר ראשון מפני שאין לו קדושה אלי יקלו ישראל בנתינתו ללוים אבל יפרישוהו וישאירוהו להם ולא יהיה ללוים דבר יאכלו ממנו הפך מה שכונה התורה בהם ולזה הזהיר בזה המקום שלא לעזוב את הלוי:
@339 **התועלת** השתים עשרה הוא במצות והוא מה שצונו לשחוט בהמה חיה ועוף כשנרצה לאכלם כמו שאמר וזבחת מבקרך ומצאנך וגו' כאשר צויתיך לי מה שביארנו ביאור דבר זאת הפרשה והנה התועלת בזאת המצוה הוא מצדדין רבי' האח' כי בזה האופן יתכן יותר שיצא דם הבעלי חיים בעת שחיטתו ונהיה נשמרים יותר מפני זה מאכילת הדם. והשני כי בזה האון עם שכבר ימותו בו הבעלי חיים בקלות יותר הנה אין בו מה מהקנאה לנפשותינו תכונת האכזריות כדי שיהיה זה כשאר מיני ההמתה כאלו תאמר ההכאה בקופיץ על ראש הבעי חיים ומה שידמה לזה. והשלישי הוא יותר כולל הוא כי כאשר באה המצוה איך תעשה זאת ההמתה היקרה מזה לשוחט את הבעלי חיים שהוא לא יכוין להרוג את הבעלי חיים בעשותו זה הפעל אבל יהיה לבו איך יעשה זאת המצוה באון שצוה השם יתעלה וזה ממה שיהיה בו תועלת להמשך אליו הדבקות בשם יתעלה גם בעת עשותו זה להרחיק ממנו תכונת האכזריות לפי שהוא לא יכוין להרוג אך לעשות המצוה באופן שצוהו השם יתעלה:
@339 **התועלת** השלש עשרה הוא במצות והוא מה שצונו שלא לאכול אבר מן החי והנה התועלת בזאת האזהרה עם שבו ישמרו התועלות הנזכרו' בענין השחיטה הוא להרחיק ממנו תכונת הזוללות עד שלא יסבול ההמתנה שתשחט הבהמה אך מרוב הזוללות ימהר לקחת ממנו קודם שתשחט עם שבזה מהקנאת מדת האכזריות מה שלא יעלם:
@339 **התועלת** הארבע עשרה הוא במצות והוא מה שצונו להטפל בקרבנות אשר לנו עד הבאתם שם למקום הנבחר והתועלת בזאת המצוה מבואר כי לולי זה יפסדו הקדשים בראות מי שהפריש אותם שאינם באחריותו:
@339 **התועלת** החמש עשרה הוא במצות והוא מה שלמדנו בזה שאם פקעו מעל המערכ' מקרבן העולה הקרנים או הטלפים והעצמות והגידים אינו חייב להחזירם שם כי התורה לא דקדקה בעולה כי אם בבשר ובדם כאמרו ועשית עולותיך הבשר והדם:
@339 **התועלת** השש עשרה הוא במצות והוא מה שלמדנו שכל הזבחים שנתן מדמה מתנה אחת על המזבח הנה נרצה הבשר למזבח ולאדם ואין שאר המתנות מעכבות וזה למדנו מאמרו ודם זבחיך ישפך על מזבח יי' אלהיך והבשר תאכל כמו שביארנו בביאורנו לזה הפסוק והנה היה זה גם כן כשלא נוכל להשיג הטוב והתועלת בשלמות הנה אין ראוי שנקצר מהשתדלות אל שנשיג ממנו מה שאפשר לנו ולזה הוא מבואר שאף על פי שיש תועלת נפלא בהיות אלו המתנות אל התאר שהגבילה אותו התורה כמו שביארנו בפרשת ויקרא הנה יש בקרבנות תועלות אחרות נפלאות כמו שביארנו שם ולא הסכימה התורה שיעדרו ממנו אלו התועלות מפני העדר ממנו קצת התועלות אשר ימשכו מזריקת הדם על המזבח:
@339 **כי יכרית יי' אלהיך את הגוים וגו' עד עשר תעשר:**
@339 **ואולם התועלות המגיעים ממנה הם י"ח:**
@339 **התועלת** הראשון הוא להודיע שאין ראוי שנשתדל לעבוד השם יתעלה באופן שהיו עובדים עובדי עבודה זרה אלהיהם כי בנימוס העבודה זרה ההיא היה כל דבר שהוא מתועב ומרוחק מאד לאנשים מאד כי חשבו השחיתם עצמם עבודה עם שגם בניהם ובנותיהם היו שורפין באש לאלהיהם וזה הדרך דרכו בכל עניניהם ואולם תורתינו התמימה לא העמיסה עלינו דבר מגונה ובלתי נאות אך כל מה שסדרה לנו הוא חיי הגוף וחיי הנפש מתוק לנפש ומרפא לעצם:
@339 **התועלת** השני הוא במצות והוא מה שהזהירנו שלא נוסיף על הדבר שצוה אותנו ולא נגרע ממנו מאשר צוה אותנו כי זה ממה שיביא אל הפסד התורה בכללה רוצה לומ' אם היה זה השער פתוח לנו. ולזה סמך לזה דבר הנביא אשר יצוה לעבוד עבודה זרה והמסית והמדיח כאלו רצה בזה להישירנו שמזה המקום ימשך שיעבדו עבודה זרה:
@339 **התועלת** השלישי הוא להודיע שאין משגיחים באות וכמופת שיתן הנביא או חולם החלום שוה לעבוד עבודה זרה כי זה כל כך חזק האמות לנו שהוא עון פלילי ואין ראוי לעשות כן בשום פנים מצד מה שראינו בעינינו במעמד הר סיני ומצד העיון שאין כח באות ובמופת שיביאנו להאמין הפך זה:
@339 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו מלשמוע אל דברי הנביא ההוא והתורה בזאת האזהרה מבואר כי בזה תתקיים האמונה האמתית והתורה השלמה:
@339 **התועלת** החמישי הוא במצות והוא מה שצוה להמית הנביא ההוא כדי לבער הרע מקרבנו רוצה לומר פן יפתנו בדבריו לסור מאחרי השם יתעלה:
@339 **התועלת** השישי הוא במצות והוא מה שהזהיר שלא יסית ולא ידיח איש מישר' לעבוד ע"ז מישראל איש או אנשים מישראל שנאמ' והנשארים ישמעו וייראו וגו' והנה התועלת בזאת המצוה מבואר:
@339 **התועלת** השביעי הוא במצות והוא מה שהזהיר שלא יפותה המוסת להסכים לדברי המסית שנאמ' ולא תאבה לו ולא תשמע אליו ומזה למדנו שאם אבה ושמע אף על פי שלא עבד עבודה זרה נסקל המוסת והנה התועלת בזאת האזהרה מבואר:
@339 **התועלת** השמיני הוא במצו' והוא מה שהזהירנו מלחוס על דם המסית ומלטעון עליו זכות ושלא נעמוד מלטעון עליו חובה אם ידענוהו לו שנאמר ולא תכסה עליו והתועלת באלו האזהרות מבואר כדי שיוסרו האנשים מעשות כדבר ההוא:
@339 **התועלת** התשיעי הוא במצו' והוא מה שצונו לסקול המסית שנאמר וסקלתו באבנים ומת והתועלת מבואר:
@339 **התועלת** העשירי הוא במצות והוא מה שצונו לחקור ולדרוש היטב עדות העדים וכ"ש בדיני נפשות כדי שנעמוד על בחינת מה שבעדות העדים מן האמת אל הפכו שנאמר ודרשת וחקרת ושאלת היטב וגומ'. והנה התועלת בזאת המצוה מבואר להגיע היושר והצדק במשפט:
@339 **התועלת** האחת עשרה הוא במצות והוא מה שצונו לדון במשפט עיר הנדחת לפי מה שצונו בתורה והנה היה התנאי שיהו מדיחיה מהעיר ומהשבט כי בזולת זה אפש' שבא הרע בזאת התכונ' לעיר ההיא במקרה אך כאר היה זה מבני העיר וממשפחתם מעיר על רוע תכונת אנשי המקו' ההוא ובפרט כשהודחו רוב אנשי העיר. ולפי שמרוע התכונה הזאת להם ימשך הרוע לזרעם בשכבר הוא להם קנין חזק היתה המצוה להרגם כלם טף ונשים ר"ל העובדים ע"ז מהם וצוה לשרוף העיר שלא תבנה עוד כי אולי מצד הסדורים אשר מהמערכת לכוכבים במקום ההוא ימשך ליושבי המקום ההוא זה הרצון עם שבזה תועלת ליסד הנשארים ולזאת הסבה צוה לשרוף כל שללה אל תוך רחובה ולהרוג כל בהמתה גם מהצדיקים בה כדי שישתדלו כל אחד שבעיר להוכיח החוטאים לפי כחו פן יאבדו קנייניו כלם לסבת חטאם:
@339 **התועלת** השתים עשרה הוא במצות והוא מה שהזהירנו שלא נהנה בדבר מקניני עיר הנדחת שנאמר לא ידבק בידך מאומה מן החרם והנה התועלת בזאת המצוה מבואר והוא שאם יהנה האדם בו ויצליחו קניניו אח' זה אולי יטעה ויאמר שהע"ז ההיא שהאמינו בה אנשי העיר ההיא הצליחו קנייניו ויהיה זה סבה אל שימשך לעבודה זרה:
@339 **התועלת** הי"ג הוא להודיע שהאכזריות על הרעים חמלה על הטובים כי העושה דין בעיר הנדחת משיב חרון אף ה' מעל ישראל ומביא עליהם רחמים:
@339 **התועלת** הארבע עשרה הוא במצו' והוא מה שהזהירנו שלא נסכול בעצמנו כדרך שהיו נוהגין לעשות עובדי עבודה זרה וזהו אמרו לא תתגודדו והנה התועלת בזאת המצוה הוא להרחיק מלכת בחקות עובדי ע"ז עם שזה שומר אותנו מלהשחית עצמנו ומביא אותנו להדבק בדברי התורה ולמאוס הנמוסים המגונים ההם שהיו לעובדי עבודה זרה:
@339 **התועלת** החמש עשרה הוא במצות והוא מה שהזהירנו מלשים קרחה על הראש למת כמו שהיו עושים הגוים ההם והו אמרו ולא תשימו קרחה בין עיניכם למת והתועלת בזאת המצוה היא כמו התועלת אשר במצוה שלפניה והנה המשיך לזה מה שצונו השם יתעלה לבחר בו מהמאכלים אשר הוא מבואר במעט עיון שהוא לטוב לנו כמו שביארנו בפרש' שמיני להעיר על עוצם ההבדל הנפלא שיש בין זאת התורה האלהית ובין הנמוסים המגונים שהיו לגוים ההם כי זאת התורה תשתדל ליסר לנו הנימוס המועיל לנו לגוף ולנפש בתכלית מה שאפשר ואולם הנמוסים ההם היו להשחית המתנהגים בהם הנפש וגם הבשר:
@339 **התועלת** השש עשרה הוא במצות והוא מה שהזהירתנו התורה מאכול הבהמה המתה שהיא בלתי שחוטה שנ' לא תאכלו כל נבלה והנה התועלת בזאת המצוה היא תחללה לפי שכבר יקרה על הרוב במתה שתהיה חולה ויהיה בשרה מזיק לאוכל והשני הוא לקיים מצות שחיטה אשר כבר זכרנו מה שבה מהתועלת:
@339 **התועלת** השבע עשרה הוא להודיע מה שחמלה התורה על הגר עד שכבר הקדימה נתינת הנבלה לגר על מכירתה לנכרי והתועלת בה שיהיה מזה לגר הוא לחמלה עליו כי אין לו עוזר ולזה ראוי שנחמול עליו אחר שהוא גר בינינו וקבל עליו שלא לעבוד עבודה זרה והתועלת במה שיהיה מזה לנכרי הוא ליסד בלבנו שאין ראוי שנחנהו לתת לו מתנות חנם לפי הוא עובד עבודה זרה:
@339 **התועלת** השמנה עשרה הוא במצות והוא מה שלמדנו בזה המקום מצד הסמיכות שהסבה באסור בשר בחלב הוא מצד היותו מזון בלתי נאות אל הבריאות כמו שביארנו בפרשת ואלה המשפטים:
@339 **עשר תעשר את כל תבואת זרעך עד סוף הפרשה.**
@339 **ואולם התועלות המגיעות מזאת הפרשה שהגבלנו ביאורה בזה המקום הם כ"ח:**
@339 **התועלת** הראשון הוא במצות והוא מה שצוה להפריש מעשר שני מכל התבואות והפרות אשר לנו לעלות לאכלו במקום הבחירה שנאמר עשר תעשר את כל תבואת זרעך והנה בזה תועלות רבות כמו שזכרנו אצל ביאורנו לזאת הפרשה ובכללם יגיע מהתועלת בה ללמדנו ליראה השם יתעלה כל הימים כמו שזכרה התורה וכבר ביארנו זאת אצל באורינו זאת הפרשה:
@339 **התועלת** השני הוא במצות והוא מה שצוה להפריש מעשר עני בשנה השלישית והששית מהשמטה רוצה לומר שהמעשר שני יהיה בשנים האלה לעניים והנה התועלת בזאת המצוה מבואר כי בזאת ימצא לעניים בקלות המצטרך להם ולא יכבד מאד לבעלים מה שיתנו להם מזה כי גם בשנים האחרו' לא היו משתמשים הבעלי' במעשר שני לתועלת גדול כי הם היו מצווים לאכלו במקום הבחירה בג' רגלים שיביאו שם עם שאר המעשרות שצו לאכול שם כמו מעש' בהמה ונדריהם ונדבותם כי זה יהיה סבה גם בשנים ההם שיתנו העשירים הרבה מזה המעשר:
@339 **התועלת** השלישי הוא במצות והוא מה שצונו להשמיט כספים בשנת השמיטה כי בזה תועלת להניח לעניים מהנושים בה עם ההערה שיש בכאן בענין השמיטה שנתחזק וזה מבואר ממה שזכרנו מהתועלת בדבר השמיטה בפרשת בהר סיני:
@339 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא לנגש המלוה שהוא אצל ישראל שעברה עליו שביעית שנאמר לא יגוש את רעהו:
@339 **התועלת** החמישי הוא במצות והוא מה שצונו לנגוש הנכרי כדי שלא נתן מתנות חנם לעובדי ע"ז והוא אמרו את הנכרית גוש:
@339 **התועלת** השישי הוא במצו והוא מה שצונו לעשות צדקה לעניים על מדרגותיהם רוצה לומר שהקרוב קרוב קודם והוא אמרו פתוח תפתח את ידך לאחיך לענייך ולאביונך בארצך:
@339 **התועלת** השביעי הוא במצות והוא מה שהזהירנו מלאמץ לבבנו ומלקפוץ ידינו מהעני מלהחיותו רוצה לומר מלהמציא לו די מחסורו שנאמר לא תאמץ את לבבך ולא תקפוץ את ידך מאחיך האביון וגו'. די מחסורו אשר יחסר לו:
@339 **התועלת** השמיני הוא במצות והוא מה שהזהירנו שלא נמנע מלהלוות לעני מפני קרבת שנת השמטה שנאמר השמר לך פן יהיה דבר עם לבבך בליעל לאמר קרבה שנת השבע שנת השמיטה וגומ' והתועלת בזאת הצדקה מבואר:
@339 **התועלת** התשיעי הוא במצות והוא מה שצוה להעניק לעבד עברי ולאמה העברית כפי אשר תשיג יד הבעלים שנאמר הענק תעניק לו מגרנך ומיקבך ואף לאמתך תעשה כן:
@339 **התועלת** העשירי הוא במדות והוא להודיע שאין ראוי לאדם שיעמוד בטל מפני שמרו מצות התורה ויסמך שהשם יתע' יתן לו צרכיו כי זה ממה שיביאהו אל החסרון ואולי יביא עם זה אל מעוט האמונה בשם יתעלה ולזה אמר וברכך ה' בכל אשר תעשה להעיר על שהוא צריך למתברך בשם יתעלה שלא ישב בטל אבל יעשה מעשים להביא אליו הברכה והשם יתעלה יביאה לו בכל אשר יעשה:
@339 **התועלת** האחת עשרה הוא במצות והוא מה שצוה להקדיש הבכור כשנולד ולומר שהוא בכור קדוש לש' והנה התועלת בזה הוא לפרסם מצות הבכורות שיש בהתועלת להזכיר עניין יציאת מצרים הנפלא שהוא מישיר מאד לעבודת השם יתעלה עם שבו תועלת לשמור האנשים מהכשל ליהנות בו:
@339 **התועלת** הי"ב והוא מה שהזהירתנו מלעבוד בבכור שור בין תם בין בעל מום ואף על פי שלא חסרנו דבר ממנו זולת העמל שהשיגו מזה שהוא מחוסר החום הטבעי ומלגוז בכור אף על פי שלא עמלנוהו ולא תסרנו ממנו דבר כי אם מה שהוא ממנו במדרגת המותר וכן הענין בשאר הקדשים כל שכן שהוא אסור ליהנות מהם במה שיחוסר בו דבר מגופם כמו הענין ביניקת חלב הקדשים והנה התועלת בזה הוא להעיר על שאלו הקדשים הם לה' ולזה לא הותר לנו ליהנות מהם:
@339 **התועלת** השלש עשרה הוא להודיע שהבכור תם לא נאכל כי אם במקום הבחירה. והנה הכונה בזה הוא להעיר שהוא לה' מפני מכת בכורות:
@339 **התועלת** הארבע עשרה הוא להודיע שהבכור נאכל שנה בשנה לא יגדלהו הכהן משנה לחברתה פן תקרה בזה תקלה שיהנה ממנו אם יגדל מהם הכהן עדרים:
@339 **התועלת** החמש עשרה הוא במצו' והו' להודיע שהבכור הבעל מום אינו נזבח ליי' בבית הבחיר' אבל אם היה בעל מום קבוע הוא נשחט במומו ונאכל בכל מקום בזולת קדושה שנאמר כי יהיה בו מם פסח או עור כל מום רע לא תזבחנו לה' אלהיך:
@339 **התועלת** השש עשרה הוא במצו' והוא מה שצונו להביא שלמי חגיגה עם הפסח במקום אשר יבחר יי' לפי שהפסח הוא כלו לבעלים מלבד דמו וחלבו שהוא למזבח רצה השם יתעלה שיתחברו עמו השלמים שאוכלים מהם השם יתעלה וכהניו וישראל על שלחן אחד:
@339 **התועלת** השבע עשרה הוא במצו' והוא מה שצונו שלא לזבח הפסח כי אם בבית הבחירה כי בזה תשלם יותר הכונה המכוונת בפסח לפי מה שביארנו מענינו בפרשת בא אל פרעה:
@339 **התועלת** השמנה עשרה הוא במצות והוא מה שצוונו שלא להותיר מבשר החגיגה עד הבקר כמו העניין בפסח שהיא באה עמו כדי שלא יחשוב חושב שתהיה קדושת הפסח למעלה מקדושת השלמים מפני שמעטה התורה בזמנו:
@339 **התועלת** התשע עשרה הוא במצות והוא מה שצונו לבשל ולאכל הפסח במקום אשר יבחר השם שנאמר ובשלת ואכלת במקום אשר יבחר ה' ולמדנו מזה שאם בשלו חוץ מהמקום ההוא הוא נפסל מלאכל וכבר למדנו זה בכללו' ממה שנאמר ובשר בשדה טרפה לא תאכלו כמו שביארנו בפרשת ואלה המשפטים:
@339 **התועלת** העשרים הוא במדות והוא מה שהודיענו כשנשוב מהמקום אשר יבחר ה' לא נסע כי אם בבקר אחר שנלין שם במקום הנבחר ההוא כאמרו ופנית בבקר והלכ' לאהלך וכבר זכרנו התועלות הנמשכים מזה אצל ביאורנו לזה הפסוק:
@339 **התועלת** העשרים ואחת הוא במצות והוא מה שלמדנו שהתחלת הקצירה ראוי שתהיה קצירת העומר ושהיא לא תהיה עד ליל י"ו בניסן כי מאז תתחיל הספירה וכבר ביארנו תועלת זאת המצוה במה שקדם:
@339 **התועלת** השנים ועשרים הוא במצות והוא מה שצונו לעשות שלמי חגיגה ושלמי שמחה בחג המצות ובחג השבועות ובחג הסכות והנה חוייב שתהיה החגיגה באה מן החולין כי היא העקר ועליה נקראו המועדים חגים והסכים שתהיה הנדבה ממנה באה ממעשר שני וממעשר בהמה ונדרים ונדבו' וכן הענין בשלמי שמחה כדי שלא תכבד ההוצאה לאנשים באם שם ויהיה זה סבה למעט שמחתם כי הרבה מה שיכאב לה האדם על רוב ההוצאה ובזה גם כן תשלם יותר כונת התורה שישמחו הבעלים עם האנשים הדלים כמו הגר והלוי והיתום והאלמנה ויתר העניים ולא יקשה בעיני הבעלים בתתם להם מזה אחר שאין להם דרך לאכלו חוץ ממקום הבחירה:
@339 **התועלת** השלש ועשרים הוא במצות והוא מה שצותה התורה להראות כל הזכרים את פני השם יתעלה בג' המועדים שהם פסח שבועות סכות והתועלת בזה מבואר במה שביארנו מזה בזאת הפרשה:
@339 **התועלת** הארבע ועשרי' הוא במצות והוא מה שהזהרנו לבלתי הראו' לפניו רקם כי זה ממה שיישיר האנשים כי הענינים שהם מסודרים בבית הגדול אינם ללא תועלת כי גם ראייתם לא הסכימה התורה שתהיה רקם עם שהעולה שיקריבו שם על הראיה היא מישרת בעצמותה לדברים. נפלאים כמו שבארנו אצל ביאורנו הקרבנות:
@339 **התועלת** החמש ועשרים הוא במדו' והוא להודיע שראוי לכל אדם שיצמצם לפי אשר תשיג ידו כדי שיוכל להתמיד בהוצאה זו כי בזולת וזה אולי ישחית קנינו בעת אחת וישאר אחרי כן בחוסר כל ולזה אמרה התורה מסת נדבת ידך אשר תתן כאשר יברכך יי' אלהיך ואמר איש כמתנת ידו כברכת יי' אלהיך אשר נתן לך:
@465 **שופטים ושוטרים תתן לך בכל שעריך. עד כי אתה בא אל הארץ.**
@465 **ואולם התועלות המגיעות ממנה הם כ"א:**
@465 **התועלת** הראשון הוא במצות והוא שימנה ב"ד הגדול שופטים ושטרים בכל עיר ועיר שבארץ ישראל ושפטים ושטרים לאחד אחד מהשבטים ושימנו אותם ראויים לשפוט משפט צדק והנה התועלת בזאת המצוה מבואר להישיר בתכלית מה שאפשר אל שישמרו כל ישראל דרכי התורה בכללם ולזה שם להם מוכיחים בכל שער ושער כי הם חייהם ובסבת שמירתם התורה יאריכו ימים על האדמה ולזאת הסבה יחד מצות מנוי השפטים והשטרים בכל שער ושער אל הארץ כאלו יאמר ששאר המקומות אינם מוכנים כל כך אל שיגיע בהם כונת התורה בכללה אם שבזה תועלת עוד בעניינים המדיניים שבדברי ריבות האנשים קצתם עם קצת לא יצטרכו ללכת חוץ מעירם לשפוט ביניהם ואולם בית דין הגדול נוהג בין בארץ בין בחוצה לארץ הלא תראה כי בית דינו של משה היה נוהג במדבר ובית דינו של יהושע והבאים אחריו היו נוהגים גם בשני השבטים וחצי שלקחו נחלתם מעבר הירדן מזרחה:
@465 **התועלת** השני הוא במצות והוא מה שהזהיר מלמנות דיינים בלתי ראויים לעשות משפט שנאמר לא תטה משפט ומה שהזהיר מהכיר פנים בעניין זה המנוי שנאמר לא תכיר פנים ומה שהזהיר על לקיחת שוחד על דבר זה המנוי אפילו לבחור הראוי שנא' ולא תקח שחד ומה שצוה לרדוף בו ענין הצדק והיושר כדי שיהיה המנוי יותר שלם שאפשר והנה התועלת באלו המצות כלם הוא שיהיה זה המנוי בשלם שבפנים להישיר ישראל ללכת בדרכי התורה ולהנהיגם בהנהגתם:
@465 **התועלת** השלישי הוא במצות והוא מה שהזהירנו מלנטוע שום עץ אצל מזבח ה' אלהיך שלא להתנהג במנהגי' הפחותים שהיו נוהגים עובדי ע"ז ואפילו שתהיה הכונה בו לעבודת ה' אלהיך והנה סמך זאת האזהרה לדבר אזהרת לקיחת שחד להעיר כי כמו שהשחד יטה האנשים מהדרך הנכונה אע"פ שלא יכונו לקחת אותו כי אם לעשות היושר כן נטיעת האשרה אצל מזבח ה' יביא לתכלית רע ואע"פ שיחשבו בו העבודה לש"י כי זה יביא ללכת בשאר חקות הגוי' ההם ולעשות פעולותיה' המגונות וידמה עוד שסמכו לזה להעיר שלא ימנו עם הבית דין הגדול קצת דיינים בלתי הגונים ולזה המשילו לנטיעת האשרה אצל המזבח כי אצל המזבח היה מקום ב"ד הגדול כמו שנתבאר בפר' זקן ממרא:
@465 **התועלת** הרביעי הוא במצות והוא מה שהזהירתנו מלהקים לנו מצבה ואפילו לעבודת הש' יתע' וזה כלו להרחיק ההדמות לפעולות הגוים ההם:
@465 **התועלת** החמישי הוא במצות והוא מה שהזהירתנו מלזבח לה' בהמה שיש בה מום אפילו שהוא מום עובר או שנעבדה בה עבודה זרה שנאמ' לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום כל דבר רע והנה התועלת בזאת המצוה מבואר כי אם יקריבו אלה לה' יביא זה לחשוב החסרון לה' יתעלה כי אנחנו רואים כי גם לפתחנו לא נביא משום דבר בלתי נבחר בעצמותו כל שכן לשם יתעלה:
@465 **התועלת** הששי הוא במצות והוא מה שצונו לסקול עובדי עבודה זרה אחר הדרישה והחקירה וערות השלם והתועלת בזאת המצוה מבואר:
@465 **התועלת** השביעי הוא במצו' והוא מה שהזהיר מהמית המת על פי עד אחד והתועלת בזאת האזהרה מבואר כי אולי בזה יהיה נספה בלא משפט עם שלא יתבאר שיהיה שם דרישה וחקירה:
@465 **התועלת** השמיני הוא במצות והוא מה שהקיש עדות שנים לעדו' שלשה לעניין הדרישה והחקירה ושאר הענינים והנה בזה התועלת למצוא שקר כשהעידו עליו רבים:
@465 **התועלת** התשיעי הוא במצות והוא מה שצונו לשפוט זקן ממרא על פי ב"ד הגדול בדין שהתבאר בו ורצה שיתפרסם זה לכל ישראל כדי שישמרו כלם התורה לפי מה שיורו בה בית דין הגדול שבבית הבחירה והתועלת בזאת המצוה מבואר כי היא חכמה לשמור גדרי התורה למען לא יבאו שועלים יפרצום:
@465 **התועלת** העשירי הוא במצות והוא מה שצונו לעשות בדברי התורה על פי התורה אשר יגידו בית דין הגדול שבבית הבחירה שנאמ' ועשית על פי הדבר אשר יגידו לך והתועלת בזאת המצוה מבואר ממה שקדם:
@465 **התועלת** האחת עשרה הוא במצות והוא במה שהזהירה מלסור מן הדרך אשר יגידו בית דין הגדול ימין ושמאל היה שיהיה מביאורי התורה או גזרות ותקנות שנאמ' לא תסור מן הדבר:
@465 **התועלת** השתים עשרה הוא במצות והוא מה שצונו למנות עלינו מלך אשר יבחר ה' באותם התנאי' שזכר והתועלת בזה הוא שיוציא' ויביאם ונלחם מלחמותם לעשות התורה ועובדיה:
@465 **התועלת** השלש עשרה הוא מה שהזהירה ממנות המלך מקהל גרים שמא יסור לסורו עם שלא ייראו ממנו העם מאד להיותו בלתי נכבד מאד בעיניהם ומזה המקום למדנו שאין ראוי למנות מלך פחות הצורה או בעל מום או בעל חסרונות אחרות שיבזוהו העם בעבורם ויביא זה שלא תהיה יראתו על פניהם:
@465 **התועלת** הארבע עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו סוסים יותר מהמצטרך לו למרכבתו ולמרכבת פרשיו ועבדיו כדי שלא ישיב העם מצריימה בעבור הרבות סוס עם שזה יביאו אל הגאוה וישחית המזונות ללא צורך:
@465 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו נשים כדי שלא יסור לבו מהשקידה בתורה וההמשך אליה:
@465 **התועלת** השש עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו מאד כסף וזהב על הצריך לו לפי הוצאותיו כי זה יהיה סבה אל שירום לבבו ולסור מדרכי התורה ומהשקידה עליה בעבור רוב תשוקתו לאסיפת קניינים:
@465 **התועלת** השבע עשרה הוא במצות והוא מה שצוה המלך לכתוב ספר התורה לעצמו יתר על כל אדם והוא יהיה עמו תמיד ויקרא בו כל ימי חייו להמשיכו ליראת השם יתע' ואל הנמשך למצות התורה:
@465 **התועלת** השמנה עשרה הוא במצות והוא במה שהזהירתנו מלתת לשבט לוי חלק בבזה ולא בנחלת הארץ והנה התועלת באלו האזהרות הוא כדי שיהיו פנויים לעבודת השם יתעלה ולזה לא יברחו לצאת למלחמה ולא יהיה להם עסק בעבודת האדמה בדרך שיתבלבל בעבורו עיונם בדברי התורה:
@465 **התועלת** התשע עשרה הוא במצות מה שצונו לתת מבהמות חולין לכהן הזרוע והלחיים והקבה כשנשחט אותה והנה אמרו על דרך דרש כי זה היה להם בזכות פנחס הזרוע מפני שבו לקח הרומח שהכה זמרי וכזבי. והקבה כי מפני שהכה האשה אל קבתה. והלחיים שבם הלשון כי בו התפלל בעבור ישראל שנאמר ויעמוד פנחס ויפלל. ולפי הפשט נראה לי שסמכו אל מה שאמר ה' הוא נחלתו להעיר שזה השבט הוא זרוע ישראל וכחם וכל שכן הכהנים מהם כי הוא מישיר את ישראל בלשונו אל דרכי התורה כאמרו יורו משפטיך ליעקב ותורתך לישראל והוא המכין מזון לישראל רוצה לומר שבזכותן יוכן מהם המזון מאת השם יתעלה כמו הלחיים והקבה יכינו המזון אל הכבד והלב וזה כי הלחי התחתון הוא המתנועע בעת האכילה ושם יתעכל המזון קצת עול כמו שנתבאר במקומותיו בקבה יתעכל ויוכל וזה ממה שאינו צריך אל ביאור ולזה אחשוב שנתנו לו אלו שלשה דברים:
@465 **התועלת** העשרים הוא במצות והוא מה שצונו לתת ראשית הגז לכהן והתועלת בזאת המצוה להעיר שכל הטובות באות מאתו ית' עם שבאלו המתנות ישלם לכהן השלמות בתורה ובעיון וימשך מהם שלמות לישראל לפי מה שאפשר
@465 **התועלת** האחת ועשרים הוא במצות והוא מה שלמדנו שצריך שיהיו הכהנים עובדים משמרות משמרות ואולם ברגלים יהיה רשות לכהנים הראוים לעבודה לעשות קרבנות הרגל רוצה לומר הבאים מחמת הרגל ויחלקום ביניהם חלק בחלק ומזה המקום יתבאר אל שצריך שיהיו הלוים עובדים משמרות כדי שיושמו כלם איש על עבודתו ועל משאו כמו שהתבאר בפרשת נשא והוא מבואר שבזולת זה האופן לא ישלמו אלו העבודות באופן ראוי בבית הבחירה:
@498 **כי אתה בא אל הארץ וגומ' עד יד ביד רגל ברגל.**
@498 **ואולם התועלות המגיעות ממנה הם ששה עשר:**
@498 **התועלת** הראשון הוא במצות והוא מה שהזהירנו מללמד לעשות כתועבות הגוים ההם ומההליכה בחקותיהם כי אם נקח קצת מנהגיהם יהיה זה סבה אל שנקחם כלם וימשך מזה עבודת אלהים אחרים:
@498 **התועלת** השני הוא במצו' והוא מה שהזהירנו מהעביר מזרענו באש למולך והנה התועלת בזאת האזהרה מבואר:
@498 **התועלת** השלישי הוא במצות והוא מה שהזהירנו מלקסום קסמים ולא לעונן ולנחש ולא שואל אוב וידעוני ודורש אל המתים והנה התועלת באלו האזהרות מבואר כי העניין יביא להאמין בדברי הבל ולהסיר ממנו הפתח היותר גדול שיהיה לנו לבאר שיש שם אלוה פועל כל הנמצאות ומשיג כל מה שבהם כי אנחנו נעמוד על זה בקלות ממה שנמצא משפע אלו ההודעות מהשם יתעלה לאדם בנבואה או בחלום כמו שביארנו בשני מספר מלחמות יי' ולזה אמר ישעיהו מי פעל ועשה קורא הדורות מראש כמו שביארנו שם וכשנאמין שמפאת הנחש או המתים שאין בהם רוח ואלו הפעולות המגונות תתחדשנה אלו ההודעות יסור ממנו זה התועלת הנפלא אשר אין פתח מבלעדיו לקנות שום שלמות אנושי ועוד שכבר ימשך מזה מההפסד להסיר מהאנשים התועלות המגיעות להם מההשגחה הפרטית או מההשגחה הכוללת כי יאמינו אלו הדברים ויסורו מפני זה מעשות מה שאם יעשוהו יגיעו להם תועלות עצומות או יתקרבו לעשות מה שהיה נמשך להם מאלו ההשגחות שלא לעשות וכדי לשמרם מהזק נפלא:
@498 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא יהיה בנו מכשף וחובר חבר והנה תועלת זאת המצוה מבואר כי מזה ימשך הפסד בדברים המדיניים עם שזה יביא לבטל ממנו הפתח היותר גדול שנעמוד ממנו על שיש בכאן אלוה פועל כל הנמצאות מפני מה שיחייב שיהיה כח באלו ההבלי' להמציא פעולות נפלאות יגיעו מהם במה שידמה למתחדש מהקרי וזה כי הפעולות ההם אין בעצמותם דבר שיתישר על התכלית שיגיע מהם וזה ממה שיביא לחשוב שכל הדברים מתחדשי' מהקרי ושבו די ספוק להמציא כל הנמצאות כמו שהיה רואה אפיקורוס וסיעתו:
@498 **התועלת** החמישי הוא מה שהודיע שהשם יתע' השגיח בישראל בלכתם בדרכיו שיגיעם ההודעות השלמות בדברים העתידים באמצעות הנביאים כדי שישמרו מהרע שלא יגיעם וישתדלו בטוב שיגיע באופן היותם שלם וזהו אמרו ואתה לא כן נתן לך ה' אלהיך נביא בקרבך מאחיך כמוני יקים לך ה' אלהיך וכבר השגיחה התורה עוד בזה שיגיעו לישראל העתידות על יד כהן גדול בשאלם לו למשפט האורי' כמו שביארנו במה שקדם ולולי שגרמו העונות לא נפקדו ממנו אחד משני אלו הדרכים לעמוד בהם על אמתת מה שעתיד להתחדש:
@498 **התועלת** השישי הוא במצות והוא מה שצונו לשמוע לדברי הנביא ולעשות מצותיו אפילו כנגד מצות התורה אם יצוה בהם לפי שעה זולת עבודה זרה והדומה לה שנאמר אליו תשמעון והנה התועלת בזאת המצוה מבואר כי בזה תמשך ההשגחה הפרטית לישראל תמיד והנה התועלת בה עוד במה שיצוה לעבור בקצת העתים על קצת המצות כי התורה למה שתעיין באופן כולל בהנהגה השלמה המישרת האומה אל הטוב הנה אפשר שיקרה בעאת מהעתים שיהיה יותר טוב לסור מקצת מצותיה ולפי שרצה השם יתעלה שיגיע הטוב בכללות בכל הזמן לעמו אשר לקח לו לנחלה הישיר לישראל אל מה שצריך שישתנה לפי שעה בעת ועת על יד נביאיו כי אי אפשר שיושם בתורה זה והנה זה הענין דומה לענין המופתים שיחדש השם יתעלה על יד הנביאים וזה כי הטבע הוא המסודר מהש' יתעלה בשלם שבפנים להגיע אל הטוב בדבר דבר מהדברים הטבעיים באופן כולל ולפי שבעת מהעתים יהיה יותר טוב שיסור קצת הסדור ההוא השגיח השם ית' שיעשה זה על יד נביאו בעת הצורך והנה הודיעה התורה שהעובר על דברי הנביא חייב מיתה בידי שמים כדי שיירא כל העם מעבור על מצותיו:
@498 **התועלת** השביעי הוא במצות והוא מה שצונו להמית נביא שקר והמתנבא בשם ע"ז ומה שצונו שלא נירא מהמית נביא שקר שנאמר אך הנביא אשר יזיד לדבר דבר בשמי אשר לא צויתיו ואשר ידבר בשם אלהים אחרי' וגו' לא תגור ממנו וכבר ביארנו התועלת מזה אצל באורנו לדברי זאת הפרשה:
@498 **התועלת** השמיני הוא במצות והוא מה שצוה להבדיל שלש ערים למקלט במקומו היותר נאותים מהארץ אל שישלם בהם המקלט מכל המקומות אחר הכנסם לארץ ונשלם להם הירושה והישיבה איש על מקומו לפי הגורל והתועלת בזאת המצוה הוא לנוס שם כל רוצח עד שיתבאר דינו כדי שלא יהרג על לא חמס בכפיו ולעמוד שם כל הורג נפש בשגגה עד מות הכהן הגדול להמלט נפשו מגואלי הדם ולענוש אותו על זאת השגגה שבאה על ידו ונמשך זה העונש כי אם לשגגה שאינה קרובה לאונס כמו שבארנו לפי שבדלת שלשה ערים האלה היתה לזה התכלית חייב שיבדילו אותם במקומות היותר נאותים לזה התכלית ולזה צוה לשלש גבול הארץ ולקחת גבול באמצע כל שליש מהם עיר למקלט ולזה צוה גם כן להכין הדרך תמיד אליהם בכל הצדדין אשר תשלם זאת ההבנה כמו שביארנו אצל באורינו דברי זאת הפרשה:
@498 **התועלת** התשיעי הוא במצות והוא מה שצונו להבדיל עוד ג' ערים למקלט אחר שיתן לנו השם ית' את כל הארץ אשר נשבע לאבותינו ולפי שלא ראינו במה שעבר שהיו שם נביאים הבדלת אלו הערים ידענו שהדבר הזה עתיד והרצון בו אחר כבישת ארץ השלש אומות הנשארות שנתן השם יתעלה לאברהם בברית בין הבתרים והם קני וקניזי וקדמוני וזה אמנם יהיה בימי מלך המשיח אשר אנחנו מקוים בואו:
@498 **התועלת** העשירי הוא בפנות התור' והוא מה שהודיענו כי בזכו' שמירת כל המצוה שהוא מצוה אותנו היום שתכליתה הוא לאהוב השם יתע' וללכת בדרכיו כל הימים ישלים השם יתעלה לנו נתינת כל הארץ אשר נתן לאבות ולזה באר כאן שהתורה הזאת תתקיים כל הימים לא תומר בעת מהעתים אם לא באופן שזכרנו ושאם היינו שומרי אותה בכללות כבר היה השם יתעלה מגיע לנו זה הטוב:
@498 **התועלת** האחד עשרה הוא במצו' והוא מה שצונו שלא לרחם על הרוצח להצילו מהמות והוא אמרו לא תחוס עינך והתועלת בזה מבואר כדי שיוסרו בזה האנשים משפיכות דמים:
@498 **התועלת** השנים עשר הוא במצות והוא מה שהזהיר מהשיג גבול בארץ ישראל בגלוי או בסתר שנאמר לא תשיג גבול רעך בנחלתך אשר תנחל והנה התועלת בזאת האזהרה מבואר בענינים המדיניים והיתה בזה בארץ ישראל אזהרה נוספת להודיע מעלת ארץ ישראל על שאר הארצות לזה היה החטא בה בזה הענין יותר עצום:
@498 **התועלת** השלש עשרה הוא במצות והוא לצוות שלא לחתוך הדין לכל עון ולכל חטאת על פי עד אחד כי אם על פי שני' עדים או שלשה עדים וכבר ביארנו התועלת המגיע מזאת המצוה בביאורינו לזה המאמר:
@498 **התועלת** הארבע עשרה הוא במצות והוא מה שצונו לדון בעדים זוממין על האופן שהתבאר בזאת הפרשה וכבר ביארנו התועלת המגיע מזאת המצוה בביאורינו לזאת הפרשה:
@498 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר מעשות כדבר הרע הזה שנאמר ולא יוספיו לעשות כדבר הרע הזה והוא לפי מה שאחשוב אזהרה למזימים את העדים שלא יזימום בדברי שקר ויחשבו שאין זה חטא להם כי אינם מעידים בעצת עדותם שעשו אלו העדי שום רע. אבל העידו שהם היו אז דרך משל ברומי וזה אינו חטא לעדים מצד עצמותו ולפי שלא ימשך מדבריהם הרע לעדים כי אם במקרה אולי לא יחושו אם יאמרו בזה דברי שקר כמו שלא יחוש אדם לומר שראובן אכל היום פולים ואף על פי שלא אכלם אחר שזה המאמר אינו מעלה לראובן ולא מוריד ולזה הוצרכה התורה להזהיר זאת האזהרה ולזה אמרה כדבר הרע הזה ולא אמרה הדבר הר הזכה ואולם לעדים זוממין. לא הוצרכה בכאן אזהרה שהרי אמרה תורה לא תענה ברעך עד שקר:
@498 **התועלת** השש עשרה הוא במצות והוא מה שהוזהרנו מלרחם על עדים זוממין מהביא עליהם הדין הראוי להם ומה שהזהירנו מלרחם על כל חובל בחבירו מהביא עליו הדין הראוי שנאמר לא תחוס עינך נפש בנפש עין בעין והנה התועלת באלו האזהרות מבואר:
@533 **כי תצא למלחמה על אויביך וגומ'. עד סוף הפרשה:**
@533 **ואולם התועלות המגיעות ממנה הם ז':**
@533 **התועלת** הראשון הוא במצות והוא מה שהזהיר מלירא מן האויבי' עובדי עבודה זרה כשנבא להלחם עמהם כי ראוי לנו לבטוח בהשם יתעלה שיעזרנו על זה מצד אהבתו אותנו וברשעתם והוא מבואר שלא יהיה זה כי אם בעובדי עבודה זרה לפי שהמקבלים עליהם מצות בני נח ישלימו עמנו כמו שנתבאר עם שאין ראוי שיקראו אויבים לנו כי אם אויבי השם יתעלה:
@533 **התועלת** השני הוא במצוות והוא מה שצוה לומר מהדברים לאנשי חיל על יד כהן והשוטרים ולפקוד שרי צבאות עם העם כדי שיהיה סדור הצבא באופן ראוי ישלם לו הנצוח:
@533 **התועלת** השלישי הוא במצוות והוא מה שצוה לקרא לשלום תחלה לכל עיר שנבא להלחם עמה ואפילו משבעה עממין כדי שאם ישובו לדרכם הרעה אשר בעבורו נתחייבו כלייה לא נמיתם כי השם יתעלה אינו חפץ במות הרשע ולא צוה השם יתעלה להחרים אותם אלא כדי שלא נלמוד מתועבותיהם והנה רצה התורה עם כל זה שיהיו לנו למס ועבדונו מפני היות לנו תורה יותר שלמה לאין שיעור וראוי שיהיו הבלתי שלמים השלמות האנושי עובדים השלמים כי בזה יתקרבו ללמוד מדרכיהם הלא תראה כי ישראל נותנים מתנות רבות לכהנים ללויים בעבור היותם מוכנים יותר אל השלמות:
@533 **התועלת** הרביעי הוא במצות והוא מה שצותה התורה שאם לא השלימו מצור על העיר עד רדתה בדרך שאם ירצו לברוח והמלט על נפשם יכלו לברוח ואם היה משבעה הגוים יחרימו הכל לא יחיו כל נשמה שאם יחיו מהם ילמדום לעשות כתועבותיהם ויקחו שללם ואם היו משאר אומות יהיו להם הנשים והטף ויקחו את כל אשר להם:
@533 **התועלת** החמישי הוא במצות והוא מה שהזהירנו מהשחי' כל עץ מאכל באי זה צד שיהיה כאלו ביאר בזה שאלו שצוו ישראל להחרימם לא היה ראוי שיהיה בהם שום תועלת במה שעתיד כי אם היה אפשר זה לא היה מצוה השם יתע' להחרימם כי גם בצמחים השגיח שלא נשחית העושה מהם פרי:
@533 **התועלת** הששי הוא במצות והוא מה שצונו לעשות מדבר עגלה ערופה כי ימצא חלל באדמה והנה היתה הכונה שתהיה משוללת מהתועלת וההנאה מעת הולדה וגם המקום שתערף שם לתועלת בעינו שצוה בכמו זה הענין בפרה אדומה כמו שביארנו שם:
@533 **התועלת** השביעי הוא ללמדנו שהמעשים המגונים שיעשו במקום מה הנה יש בזה חטא למי שראוי שישתדל בהנהגת בני המקום ולזה הוצרכו כל הזקנים לומר ידינו לא שפכו את הדם הזה ועינינו לא ראו ואמר גם כן שאם יעשו הישר בעיני יי' לדקדק בהנהגת העם יהיה זה סבה שלא יעשו כמו אלו הפעולות המגונות ולזה אמר ואתה תבער הדם הנקי מקרבך כי תעשה הישר בעיני יי':
@562 **כי תצא למלחמה על אויביך וגו' עד כי יקרא קן צפור לפניך.**
@562 **ואולם התועלות המגיעות ממנה הם תשעה:**
@562 **התועלת** הראשון הוא במצות והוא להתנהג ביפת תואר המנהג שהגבילה אותה התורה והנה התועלת בזאת המצוה הוא לתת מקום ליצר הרע כשיגבר על האדם שתתקרר רתיחתו ותשקוט כי אם לא היתה התורה מתרת לו זה העניין בזה האופן כבר היה נכשל בה גם כן והשתדלה התורה עם זאת למנעו מזאת התאוה לפי מה שאפשר ולזה צוה לנוולה כדי שלא יחשוק בה עוד והזהיר מלמכרה אחר ענותו אותה ומלהתעמר בה כדי שימנע מלבא עליה כדי שלא יפסיד הממשלה שיש לו בה בהשבותו אותה. והנה סמך אל הפרשה ההיא מה שיביא להתרחק מעניין נשואי יפת תואר כי לא יתכנו לו כל אלו הדינים שיוכל לקיימם באופן שהגבילה אותה התורה שלא יפול בזה אי זה נמנע להתקיימה כולם שהותר לו לבעלה ולזה ימנע בתחילה בלקיחתה וזה כי כבר ביאר אחר זה שסופה להיות שנואה לו מפני שלא חשק בה אלא מפני יפיה ואולם מעשיה יהיו מגונים מפני מה שגדלה עליו מהפעולות המגונות ולזה ראוי שתהיה שנואה לו. וסמך לזה דבר בן סורר ומורה להודיע שהזרע שיצא ממנה סופו להיות סורר ומורה וסופר להיות מגדף או עובד ע"ז ולזה סמך אליה פרשת וכי יהיה איש חטא משפט מות והומת:
@562 **התועלת** השני הוא במצות והוא מה שצוה שלא להעביר נחלה מהאחד מהאחים ולתתה לאחר ואף על פי שהיה אשר העביר הנחלה ממנו בן השנואה ואולם הוצרכה התורה להזהיר זו בשתי נשי' האחת אהובה והאחת שנואה כדי שלא יטול דין הבכורה מהבכורה בן השנואה ויתנה לבן האהובה לפי שכבר מצאנו ביעקב שעשה זה כי לאה היתה שנואה ורחל אהובה ונטל הבכורה מן ראובן ונתנה ליוסף כמו שהתבאר בספר בראשית אלא שזה היה על פי הגבורה ולא היה זה בקנינים שהיה מחזיק בהם יעקב אך בראוי להיות לזרעו ואין הבכור נוטל בראוי כבמוחזק כמו שהתבאר מדברינו:
@562 **התועלת** השלישי הוא במצות והוא מה שהגבילה התורה שתהיה נחלת הבכור פי שנים על נחלת כל אחד מהאחים לפי הוא ראשית אונו ולזאת הסבה מצאנו שיזכה בממלכה הבכור כאמרו ואת הממלכה נתן ליהורם כי הוא הבכור והיה זה כי אהבת האדם היה יותר דבקה לראשון מבניו ממה שהוא אוהב לבניו האחרים:
@562 **התועלת** הרביעי הוא במדות והוא מה שצונו לדין בבן סורר ומורה לפי מה שבארה התורה וכבר בארנו התועלת המגיע מזה כי מי שילבש זה הרועי באילו התכונות ולא יקבל מוסר לא מהוריו ולא מבית דין בעת הילדות שהוא עת המוסר הנה הוא מבואר שהוא יוסיף ברוע תמיד עד שישחית עצמו וזולתו ולזה מהרה התורה בהמתתו:
@562 **התועלת** החמישי הוא במצות והוא מה שצותה התור' לתלות המגדף ועובד עבודה זרה אחר סקילתם להוסיף יראה לאנשים מההליכה בדרכיהם:
@562 **התועלת** הששי הוא במצות והוא מה שצוה לקברם ביום ההוא ושלא להלין נבלתם על עץ כדי שלא יזכר פעולותיהם המגונות ויהיה בזה חלול השם:
@562 **התועלת** השביעי הוא במצו' והו' מה שהזהיר מהתעלם מאבדת אחיו כאשר ימצאה ומה שצוה להשי' אותה לו והנה התועלת בזאת המצוה בתיקון הקבוץ המדיני מבואר עם שיש בזה הקנאת מנהג אל היושר והחנינה:
@562 **התועלת** השמיני הוא במצו' והוא מה שהזהיר מהתעלם כשיראה איש חמור אחיו או שורו נופלים בדרך תחת משאו ומה שצוה לטעון עמו המשא על הבהמות והנה התועלת באלו המצות מבואר בתיקון הקבוץ המדיני כמו העניין כמצות הקודמות:
@562 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מהיות כלי גבר על אשה וכלי אשה על איש והנה התועלת באלו האזהרות מבואר לפי שהדברים ההם אם יעשו הנה הם מסלול ודרך אל שתמלא הארץ זמה כמו שביארנו אצל באורינו דברי זה הפסוק:
@581 **כי יקרא קן צפור לפניך וגו' עד אשר תכסה בה.**
@581 **ואולם התועלות המגיעות ממנה הם ה':**
@581 **התועלת** הראשון הוא במצות והוא מה שצונו לשלוח אם קן הצפור אם לקחנוה על הבנים ומה שהזהירנו מלקחת אותה על הבנים וכבר בארנו התועלת המגיע מזאת המצוה אצל באורנו בה:
@581 **התועלת** השני הוא במצות והוא מה שצונו להסיר המכשולות מהבית כדי שלא נשים דמים בביתינו הפך מה שהיתה הכונה בו בבניית הבית:
@581 **התועלת** השלישי הוא במצו' והוא מה שהזהיר מזריעת הכרם כלאים וכבר בארנו התועלת המגיע ממצות כלאים בפרשת קדושים תהיו ומהמקום ההוא יתבאר זה ואמנם החמירה התורה יותר בכלאי הכרם משאר כלאי זרעים לפי שהגפן היא חזקת היניקה ויקרה מזה שתמשך אליה המזון ששנה אותו הזרע האחר למשוך אותו אליו ויקרה מזה מה שידמה להרכבת אילן באילן שלוקחן האחד טבע מהאחר והפרי הוא מתיחס בצד מה לכל אחד משניהם וכמו מורכב מטבע שניהם ולפי מה שיקרה בו זה תפסק ההולדה בו כמו שהתבאר בטבעיות מנעה אותו התורה של נשתמש בטוב אשר האציל השם יתעלה בצמחים שיהיה להם כח לשנות המזון שיזונו ממנו להשחתתם והנה בענין מצות הכלאים תועלת משותף והוא כי זה יישירנו אל ההבדל שיש בין המינים וזה יעמידנו על מציאות הצורות שאין דרך מבלעדיו לקנות שום שלמות אנושי. וכבר תעמוד על זה ממה שחשבו קצת הקודמים שיהיו כל הדברים דבר אחד ואלו חשבו שלא תהיה שם צורה והכחישו מפני זה מציאו' האלוה ית' וכל חכמת הנמצאות ובכלל אם לא נעמוד על ההבדל אשר בין הדברים לא נקנה שום חכמה וזה ממה שאינו צריך אל ביאור למעיין בזה הספר. והנה זה התועלת כולל לכל מיני הכלאים הנזכרים פה כמו החרישה בשור וחמור ולבישת בגד כלאים:
@581 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא נשתף במלאכה אחת בהמה טהורה וטמאה והנה התועלת בזאת המצוה מבואר ממה שקדם ובה עוד תועלת להעמידנו על שההבדל שהבדילה התורה בין הבהמה הטהורה לטמא' הוא הבדל בעצמו' הדבר לא במקרה ובדבר שאין לו רושם במהותם. וכבר בארנו שהענין הוא כן בפרשת ויהי בים השמיני:
@581 **התועלת** החמישי הוא במצות והוא מה שהזהירתנו התורה מלבישת בגד שהוא צמר ופשתים יחדיו וכבר בארנו מה שיש מהתועלת בזאת המצוה בפרשת קדושים תהיו ובזה המקום כמו שקדם והנה סמך אליה מצות ציצית להעיר איך נסתעפו מן האחד דברים מתחלפים בצורה ובמהות כמו שביארנו ממצות ציצית בסוף פרשת שלח לך:
@581 **כי יקח איש אשה וגו'. עד לא תשיך לאחיך וגו'.**
@581 **ואלו התועלות המגיעות ממנה הם י"ג:**
@581 **התועלת** הראשון הוא במצות והוא מה שצוה מענין מוציא שם רע מה עונש לו או לה דבריו אמתיים וכבר ביארנו התועלת בזאת המצוה אצל ביאורנו זה:
@581 **התועלת** השני הוא במצות והוא מה שצוה מהעונש לשוכב עם אשה בעולת בעל ולזה והנה התועלת בזאת המצוה מבואר:
@581 **התועלת** השלישי הוא במצו' והוא מה שצוה מדין הבא על נערה מאורשה ברצון או באונס והתועלת בזא' המצוה מבואר ולמדנו ממנה שהאנוס פטור מכלום כשהרודף אחר נערה מאורסה יש רושת לרואה להושיע לה ואפילו בנפשו של רודף אם לא יוכל בצד אחר וכן הענין ברודף אח' שאר העריות או כרודף אחר חבירו להרגו ואולי סמיכות אלו הפרשיות הוא להעיר שהמוציא שם רע מפני שהולך אחר עיניו ולזה אינו חפץ באשתו ושונא אותה ומוציא עליה שם רע הנה סופו לפתות אשת איש אשר יקל בה הפתוי יותר והיא בעולה ולא יספיק לו זה אבל יפתה נערה בתולה מאורסה ואף על פי שיקשה בה הפתוי הנה לתגבורת יצרו עליו ישתדל בזה שלא יספיק לו זה אבל יאנוס אותה גם כן:
@581 **התועלת** הרביעי הוא במצות והוא מה שצוה מדין אונס נערה בתולה והתועלת בזאת המצוה כבר ביארנוהו עם ביאורינו דברי זאת הפרשה:
@581 **התועלת** החמישי הוא במצות והוא מה שצוה שלא יגלה איש ערות אביו. וביאר עם זה שאשת אביו לא יוכל איש קחת אות' לו לאשה אבל יקח הוא אנוסת אביו ומפותת אביו וזה הוא מבואר ממה שזכרנו למעלה בשרשים הכוללים וכבר ביארנו תועלת המגיע מזאת האזהרה אצל ביאורנו דבריה ולפי שכבר זכר דבר אונס נערה בתולה המאורסה השלים דיני אונס נערה בתולה ולזה זכר דיני אונס נערה בולה אשר לא אורשה והמשיך אליה האזהרה שלא יקח איש את אשת אביו לבאר כי הבן יוכל השקיט תלונת האשה אם תחפוץ בו כמו שביארנו:
@581 **התועלת** השישי הוא במצות. והוא שהזהיר מלישא בת ישראל מי שנשחת בו אי זה שיהיה מבלי ההולדה והנה התועלת בזאת המצוה הוא משני פנים האחד כי מפני שזה ענינו הוא בלתי מוליד אם הוליד הולדה חסרה הנה היה מן הראוי שלא יקח אשה ישראלית כי בעילת הבלתי מוליד הוא כמו בעילת זנות שלא יכון בה הולדה רק הנאה לבד והמוליד הולדה חסרה הוא בלתי ראוי גם כן לישראלית כי ידמה שיהיה הזווג ההוא לכונת הבעילה לבד אחר שלא יושג בה בפריה ורביה כי אם תועלת פחו' והנה התועלת השני הוא היותר שלם הוא שאם יהיה מורת לקח ישראלית היו האנשים השטופים בזמה כשישחקו באשה משחיתים כלי הולדה לאיש אחד ויתנוה לו לאשה ואחר זה יתעוללו בה והוא לא יחוש והיא לא תבוש אם תתעבר לחשבה שהיא מחזקה שיש לה בעל:
@581 **התועלת** השביעי הוא במצות והוא מה שהזהיר שלא יבא ממזר בקהל הש' עד עולם והנה התועלת בזאת המצוה לפי שאם יולד ממנו זרע יהיה נבדל מהזרוג בישראל לנצח ויהיה זה סבה גם כן אל שיהיה חטאתם בלתי נשכח וזה ממה שיוסיף זירוז על ההשמר מגלוי הערוה:
@581 **התועלת** השמיני הוא במצות והוא מה שהזהיר מבא עמוני ומואבי בקהל ה' אף אם נתגיירו עד עולם והמשיכה זאת האזהרה לאזהרת ביאת הממזר בקהל לפי שעמון ומואב היו ללוט מבנותיו ולזה היו ממזרים והנה הממזר לא ינקה ממום בכל עת. ולפי דרכנו למדנו מזה שהממזר הוא מהעריות אשר לא יתכן שיהיה לאדם אישות בהם ואפילו בברה כמו הבת שאין לאדם אישות כלל בה ואם קדשה אינה אשת איש וכן הענין בשאר העריות הדומה לה ואולם אשר יהיה לאדם בהם אישות כמו אלמנה לכהן גדול והדומים לה הנה לא יהיה מהם ממזר כי לא יהיה ממזר הנולד לאדם מאשתו והנה זכרה התורה בהרחקת עמוני ומואבי סבה תכלול הזכרים ולזה אין זאת האזהרה נוהגת כי אם בזכרים והוא מה שזכר מדוע לבבם שלא קדמו לישראל בלחם ובמים בצאתם ממצרים ושכבר השתדל למשחית ישראל ולזה הזהיר שאם נלחם עמהם לא נקרא להם בשלום:
@581 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מלהרחיק אדומי ומצרי לעולם אך הותר להם לבא בקהל הדור שלישי שיולדו להם לפי שתלה הענין בלידה צריך שתהיה האם שניה בדרך שיהיה הנולד לה שלישי והנה הרחיקה התורה המצרי והאדומי יותר מהאומות הנשארות לרוע מנהגם כמו שזכר בתורה כמעשה ארץ מצרים ועוד שאדום לא הניח את ישראל עבור בגבולו ולולי שהיה אדום אחינו והיינו גרים בארץ מצרים היינו מרחקים אותם עד עולם כמו הענין בעמון ובמואב:
@581 **התועלת** העשירי הוא במצות והוא מה שצונו להשמר במחנה מכל דבר רע בדרך שתדבק ההשגחה האלהית בנו ולהרחיק הרואה קרי מהמחנה כדי שישמור כל אדם מהרהורים הרעים המביאים לידי ראיית קרי כי ישיגהו מזה בושת נפלא גם הרחיק הצואה מהמחנה הקדוש בדרך שלא תראה ערות דבר במקום הנכבד ההוא שהשם יתעלה מתהלך בקרבו ומפני זה צוה לכסות הצואה לנקיות ולכבוד השם יתעלה ולהסיר העפוש משם:
@581 **התועלת** האחת עשרה הוא במצות והוא להודיע חבת ישוב ארץ ישראל כי גם העבד הכנעני הבורח שם להמלט מדוניו הישראלי הדר בחוצה לארץ נצטווינו שלא נסגירהו אל אדוניו אך ישלחנו חפשי מעצמו ויהיה גר צדק ורצתה התורה ישב עמנו בקרבנו לא בפני עצמו כדי שנישירהו למצות התורה וממה שרצתה התורה בזה יתבאר שאם רצה העבד לברוח מעם אדוניו ומעם השם יתעלה כאלו תאמר שרצה לשוב לדתו ולארצו הנה נסגירהו אל אדוניו כי התנאי הוא שלא ירצה להנצל כי אם מעם אדוניו ושישבת עמנו בקרבנו:
@581 **התועלת** השתים עשרה הוא במות והוא מה שאסר הקדשה מבנות ישראל לבד והקדש גם כן להרחיק הזמה מהעם הקדוש והנה סמך דבר הקדשה למה שזכר מדבר העבד כי השפחה כנענית היא כמו קדשה והתורה לעבד עברי או לעבד כנעני שלא באישות והוא מבואר עוד שהקדשה מהגוים לא הזהירה התורה עליהם כי לא אסרה תורה רק דרך חתנות שנאמר לא תתחתן בם:
@581 **התועלת** השלש עשרה הוא במצות והוא מה שהזהירה תורה מהביא אתנן זונה ומחיר כלב בית ה' אלהיך לעשות ממנו קרבן וכבר זכרנו התועלת המגיע מזאת המצוה אצל ביאורינו בה:
@624 **לא תשיך לאחיך נשך כסף עד כי יהיה ריב בין אנשים:**
@624 **ואולם** למה היו הפרשיות בזה הסדור הנה נאמר בו מה שיראה לנו ונאמר שכבר ידמה סמך ענין הנשך למצוות אתנן זונה כי כמו שהזונה תדמה למשוך אליה ממון האנשים ברצנם ותחשוב שאין לה אשם על זה ואינה יודעת כי בנפשה הוא פני מה שתעשה מהזמה בעבור חמדת הממון כן העניין בנושך שהוא חושב שאין בזה מהנטייה כי אם משיכתו אליו ממון האנשי' ולא ידע כי בנפשו הוא כי בעבור חמדת הממון ימשך לה עד שישוב הלוה עני וימיתהו הוא וביתו ברעב ובצמא ובערום ובחוסר כל ולפי שהנשך ותנן הם כמו נדרים והיה לחושב שיחשוב שהנדרים שידור אדם לתת בזולת שיגיע לה מחיר מה שהוא נותן לה הם הדברים מאסה בהם התורה והרחיקה אותם והיה אפשר שיביא זה אל שיחשוב האדם שאין ראוי שיקיים נדריו לשם יתעלה אחר שלא יקח מהשם יתע' בעבורם מה שהוא תמורתם הזהיר מעבור לקיים הנדרים שהם ליי' והנה סמך לזאת אזהרת הפועלים שלא לשים בכליהם מפירות בעלי הבית כי אולי יחשבו שאינם עול אם ישימו מהם בכליהם שיעור מה שהיה אפשר להם לאכול אחר שכבר הותר להם לאכול מהם שם וזה יביאם לגנוב מהפירות ההם ולשאת לביתם מהם הרבה כי לא יוכלו למשול בתאותם אחר שיפותו לה שלא יקחו מהם יותר מן החוק הרבה עם שכבר ישפטו בעת ועת שכבר אפש' להם שיאכלו ויביאו לביתם בזה הרבה מהפירות של בעל הבית וכן לא יחשבו לעשות אם יבטלו מלאכת בעל הבית בעבור אכילתם פירותיו. ובזה האופן יוכלו לבטל רוב היום ויקחו רוב שכרם בעול והנה סמך לזה מגרש אשתו ומחזיר' לפי שאולי יקח האדם מון מזולתו שחשק באשתו ויפותה מפני הממון לגרשה שתהיה לו לחשבו שאין בזה אש לו ולזה ולא בחושק כי בהיתר יקחיה ולחשבו שהוא לא יפסיד בה דבר כי כבר ישוב לקחתה אחר היותה לאיש ההוא כשיגרשנה ויתנה לו זה כדי שיתרצה הראשון לגרשה בבטחו שכבר תשוב אליו ולזה עשתה התורה כנגד זה הרצון כי בו תמלא הארץ זמה ולא ירגישו שיעשו בזה חטא. והנה סמך לזה הענין לוקח אשה חדשה לשמור האשה מזמה ולזה צוה לו שישמח אשתו אשר לקח כדי שלא תחשוק אחרים לשמור הארץ מזמה ואחר שהשלים מה שסמך מהמצות לעניין הנשך שב להשלים קצת מצוה בעניין ההלואה והזהיר מלקחת למשכון כלי שישתמשו בו בהכנת אוכל נפש כי זה עם שאפשר שיביא למה שהוא נשך וזה יהיה אם ישתמש המלוה בכלים ההם הנה הוא עוד כמו לוקח נפש למשכו בעבור החוב כי זה הכלי יוכן בו בעצמותו המזון שהוא שב חלק מהנזון ולזה סמך לו גונב נפש מבני ישראל ומכרו כי הוא נותן נפש בעד ממון בזה האופן המגונה ששני אלו הדברים נמשך מהם היזק מהאדם לזולתו בנפש במה שלא חשב שהזיק את הנפש וזה בקלוח כלי תיקון מזון מבואר ואולם בגונב נפש לחשבו שהוא לא הזיק לו בעצמו אל לקחו והו' רשו' עצמות תמיד גם אחר המכרו אחר שאינו נתן למכר' ויביא זה לחשו' שאין לו חטא בנפשו כלל. הנה סמך לה עניין הצרעת שאם לא יתנהג האדם בו לפי משפט התורה יגיע לאנשים היזק בנפשם ויחשוב שאין לו אשם בזה וזה יהיה אם יעלים נגעו בצד מן הצדדים באון שלא יוכרח לישב בדד חוץ למחנה ויעמוד בין האנשים ויעפשם ואחר שהשלים אלו המצות הנמשכות לאזהרות לקיחת משכון כלי האוכל נפש שב להשלים קצת מצות אחרות בענין לקיחת המשכון והזהיר המלוה מלבא אל בית הלוה לקחת המשכון על חובו לפי שבזה העניין יכאיב לבו מאד כשיוכרח לתת למשכון מה שיקשה בעיניו להוציאו מביתו ויהיה כמו חובל נפש עם שזה אולי יביא למה שידמה לרבית כי המלוה יאמר שלא יקח כי אם המשכון שיראה שחפץ בו הלווה יותר וזה יביא הלוה אל שיתן שוחד למלוה כדי שיתפייס במשכון האחר וצוה שלא יעכב אצלו מהעני כסות יום ביום וכסות לילה בלילה כי בזה גם כן יהיה כמו חובל נפש כי העני ישאר ערום אין כסות בקרה ויזוק מהקור ולזאת הסבה סמך לו שלא יאחר אדם פרעון שכר שכיר כי הא יחשוב היותו בלתי חוטא בזה אם שרצונו לפרעו ואולי ישחית בזה נפש השכיר ונפש ביתו עם שכבר יחשוב שאין בזה חטא על איחור הפרעון אחר שמנעה התורה לקיחת הרבית על ההלואה מפני איחור פרעונה והנה סמך לזה האזהרה מהמתת בנים על אבות להעיר כי הכובש שכר שכיר מפני שהוא דבה להמית אבות ובנים ברעב בסבת אחור פרעון השכירות הנה ישיבלו השם יתעלה מהעונש מדה כנגד מדה במה שאמר זה על העונש וקרא עיך אל יי' והיה כך חטא ועוד כי מפני שזכר מה שראוי בו לחמלה בזה על השפלים אע"פ שהם עשירים זכר אחר זה מה שראוי בו לחמלה בזה על החטאים וכאילו הזהיר שלא יענשו המחוייבים למות בממונם אך יהיה ממונם ליורשיהם שאם יענשו בממונם יהיה זה סבה שימותו בנים על אבות ואבות על בנים והנ' הוצרך להזהיר על זה מפני מה שמצאנו בעיר הנדחת שהיה ממונם אבד והיו מתים גם כן הבנים על האבות. ולפי שכבר התחיל להזכיר הדינים לחמלה על השפלים והעניים והחטאים שב להזכיר צדדים אחרים מהחמלה על השפלים והעניים והחטאים ולזה הזהיר תחילה מלהטות משפט גר יתום ואפילו הם עשירים מצד שפלותם ולא לקחת משכון בגד אלמנה ואפילו היא עשירה מצד שפלותה ואחר זה צוה לתת קצת מתנות לעניים לחמלה עליהם ואחר זה הזהיר מהוסיף על מספר מכות הלוקה לחמלה עליו אע"פ שהוא חוטא שלא יעבור ענשו החוק הראוי ואחר זה הזהיר מה שהוא לחמלה על הבהמות והוא דומה באופן מה למה שהזהיר מההוספ' על עונש החוטא כי די שנעמיס עליה משא העבודה שהוכן לה בטבע להיות לעבודתנו לא שנמנעה עם זה מהאכילה ממה שהיא עושה במה שימשכנה הטבע לאכול ממנו עם שבזה מהאכזריות מה שלא יעלם ואחר זה שב להשלים הדין במה שהוא לחמלה על החוטא וזה כי מפני שבארה התורה בקצת החטאים שיהיה העונש שימות ערירי עם שהוא ראוי שתהיה מיתת האדם בלא בנים בסבת חטא הנה השגיחה התורה על מי שמת בלא בנים שלא ימחה שמו מישראל כשהיתה לו אשה ולזה רצה שתתיבם לאחיו והנה זה המת אפשר גם כן שיהיה מת על יד ב"ד על חטא שקד' לו והשגיחה בו התור עם זה בזה האופן ואחר שזכרה התורה מה שראוי לחמול על החטאים בארה שלא יחמול עליהם מהמגיע להם העונש הראוי ואע"פ שיש שם סבה לחשוב שהיה ראוי לחמול עליהם וזכר דין המחזקת במבושי איש להציל את אישה מיד מכהו והזהיר מחמול עליה ועם זה דבר לזכור נקם עמלק על מה שעשה כנגדנו אפילו שחשב להציל עצמו בזה מהקללות שקלל יצחק את עשו שיהיה עבד ליעקב כי מפני זה לא היה ראוי לו להשתדל בעשיית זה הרע הנפלא ליש' שדמה בו לכלותם כמו שלא היה ראוי לאשת המוכה להשתדל בהריגת המכה אותו מפני שהכהו על דבר הריב לא להרגו והנה זכר כן שני אלו שתנהג בצדק וביושר במשקלים ובמידות לבאר שכמו שאין ראוי להוסיף עונש יותר מהחק הראוי כן אין ראוי שתגרע מחק העונש דבר ואולם התועלות המגיעות מזאת הפרשה שהגבלנו באורה פה הם שנים ועשרים:
@624 **התועלת** הראשון הוא במצות והוא מה שהזהיר מלקיחת שום רבית על ההלואה שנאמר לא תשיך לאחיך נשך כסף וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקדם:
@624 **התועלת** השני הוא במצות והוא מה שצונו להלוות לנכרי ברבית כשיצטרך לזה שנאמר לנכרי תשיך ופה התועלת בזה הוא שלא לההנות עובדי עבודה זרה להרחיקנו יותר מעבודתה עם שבזה הישירה ליסר הנכרי מעבוד עבודה זהר:
@624 **התועלת** השלישי הוא במצות והוא מה שהזהירתנו מלאחר שלום הנדרים אשר נדרנו ליי' ומה שצותנו לקיים אותם והנה התועלת המגיע בזה הוא לולי זאת האזהרה כבר היה האדם מחר הנדרים לחשבו שאינו מזיק בזה לשם יתעלה כי אין לו הנאה בקרבנות ההם ולא יחסר גם כן מהכהנים דבר ממה שהוא שלהם כי הם לא יזכו בקרבנות כי אם אחר הקרבתם לשם יתעלה ויהיה זה סבה אל שלא יתקיימו הנדרי' וזה יביא למעט האמנה בש' יתע' כמו שזכרנו במה שקדם:
@624 **התועלת** הרביעי הוא במצו' והוא מה שהזהיר הפועלי' מתת לכליהם דבר מפירות הבעלים שהם עושין בהם ואע"פ שהתיר להם לאכול מהם די שבעם כמו שהם מזות תקון אחר ומה שהזהיר הפעלים מלבטל ממלאכת הבעלי' בעבור אכילתם הפירות ההם וזה כולו על צד היושר מחובר עם החמלה שחמלה התורה על הפועלים שלא יוכרחו להמנע מהפירות שהם מתעסקים בהם כי יצר להם אם יראו בעיניהם ומשם לא יאכלו:
@624 **התועלת** החמישי הוא במצות והוא מה שצונו מדיני הגט אשר תותר בו האשה להנשא לכל מי שתרצה והתועלת בזה מבואר כדי שלא יוכרח האדם שיהיה עם אשתו כל ימיו השנואה לו ויהיה זה סבה על שימנע מפריה ורביה אם שיוליד בנים בלתתי הגונים כי לא ישלם להם המוסר מהאב והאם מצד רוע ההסכמה שביניהם עם שתמיד תהיה הקטטה בבית:
@624 **התועלת** השישי הוא במצות והוא מה שהזהיר הבעל מלהחזיר גרושתו אחר שהוטמא' לו והתועלת בזה הוא הרחקת הזימה כמו שבארנו ולזאת הסבה גם כן צוה שיהיה החתן נקי לביתו שנה אחת לא יצא לצבא ולא יעבור עליו לכל דבר כמו שבארנו במה שקדם:
@624 **התועלת** השביעי הוא במצו' והוא מה שהזהיר מלקחת למשכון כלי שעושין בו אוכל נפש והנה התועלת בזאת האזהרה מבואר בתורה ועוד הוא מבואר מדברינו במה שקדם:
@624 **התועלת** השמיני הוא במצות והוא מה שהוסיף כאן מהבאור בדיני גונב נפש שיתחייב מיתה על מה שזכר מזה בפרשת ואלה המפשטים והנה התועלת בה מבואר בנפשו כי בזה יהיה מקלקול הקבוץ המדיני מה שלא יעלם עם שיקרה מזה לעבור על דבר העריות ולא ירגיש בזה הנגנב ר"ל שכבר אפשר שיקרה אחותו או אמו או אחת מהעריות שהם קרובותיו ולא ישער בזה:
@624 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מלנטות ב"ד בדיני הצרעת מדרכי התורה כי כבר יקרה הרבה מההפסד בזה בקבוץ המדיני כמו ושזכרנו במה שקדם וכאלו הזהיר מלזון הרע במה שנזכר מה שעשה השם יתעלה למרים כמו שביארנו:
@624 **התועלת** העשירי הוא במצות והוא מה שהזהיר מלהכניס בבית הלוה לקחת המשכון על חובו וכבר נתבאר התועלת המגיע מזה מדברינו במה שקדם:
@624 **התועלת** האחת עשרה הוא במצות והוא מה שהזהיר מלעכב המלוה משכון העני אצלו בעת שהוא צריך לו והנה התועלת בזאת המצוה מבואר:
@624 **התועלת** השתים עשרה הוא במצות והוא מה שהזהיר מלאחר פרעון שכירות השכיר וכ"ש כשהיה עני כי אז יהיה החטא יותר עצום ולזה צוה לתתו ביומו אם היה שכיר לילה ובלילו אם היה שכיר יום:
@624 **התועלת** השלש עשרה הוא במצות והוא מה שהזהיר מענוש למות האבות על הבנים והבנים על האבות אך איש בחטאו ומזה נתבאר עוד כמו שבארנו שממון המומתין הוא ליורשיהם והנה התועלת בזאת האזהרה מבואר מצד היושר שהוא ראוי במשפט:
@624 **התועלת** הארבע עשרה הוא במצות והוא מה שהזהיר מהטות משפט השפלים כי אין בשער עשרתם והוא אמרו ללא תטה משפט גר יתום והנה התועלת בזה הוא להמשך אל היושר ולהרחיק ההמם:
@624 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר מלקיחת למשכון בגד אלמנה וכבר נתבאר התועלת בזאת המצוה ממה שקדם.
@624 **התועלת** השש עשרה הוא במצות והוא מה שהזהיר מלקחת שכחת הקציר ופירות האילן והכרם ומה שצוה שיהיו לעניים והנה התועלת בזאת המצוה מבואר לחונן העניים ולחיותם:
@624 **התועלת** השבע עשרה הוא במצוות והוא מה שצוה לחלקות החוטא כדי רשעתו במספר עד מ' מכות ומה שהזהיר מלהוסיף על זה המספר והנה התועלת בזאת המצוה מבוא' ליסר החוטאי' לפי מה שראוי להם לא יותר:
@624 **התועלת** הי"ח הוא במצות והוא מה שהזהיר מלמנוע הבהמה מאכילת מה שהוא עושה בו וכבר ביארנו התועלת המגיע מזה במה שקדם:
@624 **התועלת** הי"ט הוא במצו' והוא מה שצונו ליבם אשת האח שמת בלא בנים כדי שלא ימחה שמו מישר' ומה שצוה מענין החליצה אם לא חפץ ליבם מה שיש בו מהבשת והזרות ומה שיביאהו להסכים ליבם:
@624 **התועלת** העשרים הוא במצות והוא מה שצוה להציל הנרדף אפילו בנפשו של רודף מבלתי חמלה על הרודף כאמרו לא תחוס עינך עליו. והנה התועלת בזאת המצוה מבואר:
@624 **התועלת** האחת ועשרים הוא במצות והוא מה שהזהיר מהיות לנו אבן ואבן גדולה וקטנה לשקול בו איפה ואיפה גדולה וקטנה למדוד בה ומה שצוה שיהיה לנו אבן שלמה ודק ואיפה שלמה וצדק והנה התועלת בזה להמשך אל היושר ולהרחיק העול:
@624 **התועלת** השתים ועשרים הוא במצות והוא מה שצונו לזכור מה שעשה לנו עמלק ומה שהזהיר שלא נשכח זה ולמחות זכרו אחרי שיניח השם יתע' מכל אויביו מסביב לישראל והנה התועלת בזאת המצוה מבואר ממה שזכרנו:
@672 **והיה כי תבא אל הארץ וגו' עד ויצו משה את העם לאמר.**
@672 **ואולם התועלות המגיעות ממנה הם אחד עשר:**
@672 **התועלת** הראשון הוא במצות והוא מה שצונו מהבאת הבכורים ליבת הבחירה בזה האופן הנזכר פה באמרו ולקחת מראשית כל פרי האדמה. והנה התועלת המגיע מענין זאת המצוה הוא להתישר אל שכל הטובות שופעות מהשם יתעלה ושממנו סודרו אלו ההויות כי זה ממה שיעמידנו על אופן החכמה אשר בבראיתם וזה כי האומרים שאין שם פועל לא תהיה החקירה אצלם בדבר מהדברים למה היה באופן שהוא בו כי זה לא יחקור בעניינים אלא כשהסכמנו שם מפעולת פועל ולזאת הסבה היו טעונין תנופה להעיר על מציאות השם יתעלה כמו שביארנו מענין התנופה בספר ויקרא ולזאת הסבה היה מניח הטנא עם הבכורים לפני המזבח לפני ה' להעיד על מה שזכרנו ולזה היה מעלה שם שלמים בבאו שם על זה הענין כדי שיחן לבו כי לא דבר רק הוא הענין אשר נצטרך לזביחת שלמים ולקראית אלו הדברים הנזכרים פה המורים בעצמם אל שהשם יתעלה משגיח באוהביו השגחה פרטית ושהטובות כלם מאתו וזה ממה שעמוד אתו על מכוון בזאת המצוה:
@672 **התועלת** השני הוא במצות והוא מה שצוה לבער מתנות כהנים ולוים ועניים מביתנו מהקדשים אשר לנו כמו מעשר בהמה ומעשר שני ונטע רבעי ולקרות זה הודוי הנזכר פה והוא אמרו בערתי הקדש מן הבית בעת כלוי המעשרו' בשנה השלישית מהשמטה ובשנה השישית מפנה שהם שנות מעשרות עני והנה התועלת בה מבואר ממה שזכרנו במה שקדם:
@672 **התועלת** השלישי הוא במצות והוא מה שהזהיר מכח אלו הדברים שלא יאכל אונן מעשר שני ושלא יאכילהו לטמא ושלא יעשו ממנו צרכי המת והנה הסבה בזה כלו הוא שהמעשר שני מפני שבא להעיר על מציאות הנמצא העשירי שהוא קדש והוא עצם חיי כל חי הנה מפני זה הוזהרו הבעלים מלהשתמש בו בענייני המת ומזה גם כן נתבאר למה הוזהרו מלאכלו בטומאה כי הטומאה תבא מחמת או ממה שינהג מנהגו מצד סור הצורה והמהות ממנו ולזה אין ראוי שזה הענין אשר בא להעיר על הצורה היותר נכבדת לאין שעור יאכל בטומאה ולזאת הסבה גם כן אין שיעור שיאכלהו האונן כי לבו טרוד בדבר המת עם שהדאגה תהיה סבה אל שלא יעמוד על הכונה המכוונת בענין מעשר שני:
@672 **התועלת** הרביעי הוא במצות והוא מה שצוה ללכת בדרכי השם יתע' להדמות אליו כפי היכולת וזהו אמרו וללכת בדרכיו כי זה ממה שיישיר האדם אל כל המדו' החשובות בהשיבו איך מנהג השם יתעלה במה שהוא פועל מבריאותיו שהוא בתכלית מהחסד והחנינה והיושר וזה גם כן יעמידהו על השגת השם יתעלה כפי מה שאפר כי תמיד יחקור מפני זה כבדרכי השם יתעלה כדי שיקח מזה מנהג להדמות אליו לפי מה שאפשר:
@672 **התועלת** החמישי הוא להודיע כי דברי תורה הם לתכלית מה מבואר עד שמקיימיה יהיו מחוללים בגוי' על שאר הגוים ויגדל שמם עליהם ויהיו כמפוארי' עליהם לפי שדברי תורה הם בתכלית היושר ומישירי' אל היותר נפלאות שבהשגות העיוניות לפי מה שאפשר ולזה אמר כי התורה היא חכמתכם ובינתכם לעיני העמים ושכבר יאמרו הגוים רק עם חכם ונבון הגוי הגדול הזה:
@672 **התועלת** הששי הוא להודיע איך התחכמה התורה להציל ישר' מהרע שנפלו בו לפי מה שאפשר וגם אחר זה לא קצר השם יתעלה מישראל את עבדיו הנביאים לשמרם מזה הרע ולא הועיל כל זה להם מפני רוע תכונתם ולזה תמצא שהתורה השתדלה בזה המקום שיבנו מזבח בהר עיבל מדי באם שם ויכתבו על האבנים ההם את כל דברי התורה ויקריבו שם קרבנות ושם יקראו הברכות והקללות בזה האופן הנפלא כדי שיהיה זה דרך להביא ישראל אל שישמרו כל מצות התורה מפני היותם מקבלים כלם קיום התורה על אלו התנאים שאם לא יקיימום יחולו עליהם כל הקללות האלה והנזכרות פה ממה שיוסיף בזה הוא שכבר באו אלו הקללות כלם בעונותינו כמו שזכרנו אצל ביאורינו דברי הקללות וגם הברכות נתקיימו בימי שאול ודוד ושלמה וקצת המלכים ובפרט בימי החשמונים בבית שני:
@672 **התועלת** השביעי הוא מה שלמדנו בפרטי הקללות שענין גלוי העריות ואם הוא קל אצל האנשים הוא יותר קשה משפיכות דמים כמו שביארנו בבאורינו סבת פרטי הקלות:
@672 **התועלת** השמיני הוא מה שהודיענו בענין אלו הברכות והקללות שכמו שיבאו לנו הטובות מצד השגחה הפרטית כן הענין בקללות כמו שביארנו בביאורנו לאלו הדברים ולזה אמרה התורה אלהים לא ידעום ולא חלק להם וזה שאף על פי שחלק השם יתעלה לכל העמים ממשלת הכוכבים לא עשה כן לישראל ולזה אמרו אין מזל לישראל:
@672 **התועלת** התשיעי הוא מה שהודיענו שהנטייה מעוטה שייטו מדרכי התורה תביא לעוד אבוד' זרה ולזה ראוי שיזהר האדם שלא לפרוץ גדר מזאת התורה דבר וזהו אמר. לא תסור מכל הדברים אשר אנכי מצוה אתכם היום ימין ושמאל ללכת אחרי אלהים אחרים לעבדם.
@672 **התועלת** העשירי הוא מה שהודיענו כי איחור ישראל במדבר ארבעים שנה היתה הסבה בו היותם ממרים את פי השם יתעלה עם מה שראו מהמופתים הנפלאים שהוא אוי שיביאם להשיג השם יתעלה ולירא ממנו ולזה שערה החכמה האלהית שלא ישלם לישראל מה שראוי שיקנו מהשלמות כדי שיהיו נכונים לירושת הארץ עד שישלימו להם ארבעים שנה במדבר ויתמידו להם שם אלו הנפלאו' העצומות רוצה לומר ירידת המן ושמלתם לא כלתה מעליהם ולא נעליהם מעל רגליהם וזה היה סבה להשלימם עד שכמעט זמן נצחו סיחון ועוג:
@672 **התועלת** האחת עשרה הוא במצות והוא מה שצוה שישמרו בלבם דברי התורה כלם למען ישכילו וידעו כל מה שיצטרך להם לעשות:
@834 **ואולם התועלות המגיעות ממנה הם י"ח:**
@834 **התועלת** הראשון הוא להודיע שהברית ההוא והאלה שכרת יי' ית' עם ישראל לא היה להם לבדם כי אם לכל דורותיה' הבאים אחריהם וגם אל הגר הבא לחסות תחת כנפי השכינה וזה ממה שיוסיף זירוז לכל האנשים לשמור את דברי התורה:
@834 **התועלת** השני הוא להודיע שמי שירצ' להסיר מעליו עול התור' בשלא יכוין לדעת ענייניה כדי שיהיה שוגג בכל מה שיעבור עליו מדברי התורה ולא יענש על זה הנה לא תועילהו המחשבה הנפסדת הזאת מן העונש אבל יענש יותר ומחה יי' את שמו מתחת השמים כאמרו כי אז יעשן אף יי' וקנאתו באיש ההוא:
@834 **התועלת** השלישי הוא להודיע שאע"פ שיחטא שבט אחד או שבטים אל הש"י לא יגיע הש"י להם מן העונש שיחרימם אבל ימית מהם רבים וישארו מתי מעט ויגלו מעל אדמתם וזה כלו מצד השגחת הש"י באבות ולזה תמצא שאמ' שאם היה איש זה החוטא ישמידהו הש"י לגמרי ואולם אם היה שבט לא היה בו כן אך יבדילהו הש"י לרעה מכל שבטי ישראל ורבצו בהם כל האלות הנזכרים והנשארים ישליכם אל ארץ אחרת:
@834 **התועלת** הרביעי הוא לבאר איך שער' התור' בעניין ירבעם ומה שנפלו מהרע עשרת השבטים בסבתו עד שכבר נתקיים בהם מה שנזכר בזה המקום כמו שזכרנו:
@834 **התועלת** החמישי והוא מהגדולות שבפנות התורה הוא שהשם יתע' לא צוה אותנו רק לעשות את דברי התורה לפי הנגלה מהם וזה צוה שנעשהו לדורותינו כל הימים אמנם הנסתר בדברי התורה והם הכונות שכונה התורה שיישירו אליהם אלו המצות הוא דבר לא תתכן ידיעתו בשלמות כי אם לש"י לבדו וזה ממה שישמור האדם מחטא בקצת המצוה לחשבם שכבר עמדו על התכלית שכונה התורה בזאת המצוה ולזה לא יצטרכו לקיים המצוה ההיא והנה בנה בזה בנין בנין חומה בצורה לשמור התורה שלא יאמרו האומרים כי דבריה הם לפי הנסתר לא לפי הנגלה:
@834 **התועלת** השישי הוא מה שיעדה התורה ביציאתינו מזה הגלות אשר אנחנו בו במה שאמר והיה כי יבואו עליך כל הדברים האלה הברכה והקללה וגומ'. ושב וקבצך מכל העמים אשר הפיצך יי' אלהיך שמה אם יהיה נדחך בקצה השמים כי זה יורה על קבוץ גלות עשרת השבטים וגלותנו כי זה דבר לא נהיה עדין וזה כי בית שני לא נתקבצו כולם אבל נשארו רובם תחת שאשר המלכיות כמו שנכתב בספר יוסף בן גוריון.
@834 **התועלת** השביעי הוא מה שהעיר באמרו ומל יי' אלהיך את לבבך ואת לבב זרעך על מה שיתחדש אז השם יתע' מהאותות והמופתים כדי שידעו ישראל ובניהם כי הוא יי' ותתחזק יותר האמונה כלבם. ולזה יהיה הברית ההוא חזק הקיום יותר מהברית אשר כרת השם ית' את ישראל בהוציאו אותם מארץ מצרים כי אז היו נשקעים ישראל בשקוצי מצרים ולא נתחנכו בתורה עדין וכבר העירו הנביאים על אמתת זה:
@834 **התועלת** השמיני הוא מה שהעיר על קיום זאת התורה לנצח במה שאמר שבשמרם את כל מצותיו שהוא מצוה אותם היום כתובים בספר התורה הזה יגיע להם זה הטוב שאמר מענין קבוץ גליות ומירושת הארץ והתברכם שם ובזרעם ובקניניהם ולזה למדנו שלא תתחדש אז תורה אחרת:
@834 **התועלת** התשיעי הוא מה שהודיע שענין התורה אינו נתלה בנביא באמרו לא בשמי' היא ולזה לא נשמע לדברי נביא בבאורי התורה במה שיאמר בהם על דרך נבואה אבל נשמע לבד בדברי התורה בביאורם שקובל איש מפי איש עד משה עם שהו' מתחיל בדברי התורה בעצמם כמו שביאר' אנחנו בזה הספר:
@834 **התועלת** העשירי הוא להודיע שתכלית הראשון המגיע מההמשך לדברי התורה הוא השגת החיים הנצחיים וימשך מהם שטת השגת הטוב בחיי הגוף כי הם מיישירי' לחיי הנפש וזהו אמרו ראה נתתי לפניך היום את החיים ואת הטוב החיים והמות נתתי לפניך הברכה והקללה כי היא חייך ואורך ימיך:
@834 **התועלת** האחת עשרה הוא להודיע שאף על פי שכבר ימשך מהתועלת בקיום מצות התורה. השגת החיים הנצחיים והשגת הטובות שהם לחיי הגוף הנה ראוי שיבחר האדם בקיום התורה לתכלית חיי הנפש לא לתכלית שיגיעו לו הטובות המדומות שנאמר ובחרת בחיים:
@834 **התועלת** השתים עשרה הוא להודיע שכבר משה כתב ספר התורה ונתנו לכהנים כדי שלא יפול ספק בספר תורה בשום מלה ממלותיו ולא טעות כי משם ידקדקו אותו ולזה דקדק בספר שיכתוב המלך עבור עצמו שיועתק משם או יוגה משם כי בטעות שיקרה במלה אחת או באות אחת תפסד הרבה מכונות התורה או יפול בו ההשמע לפני' הפוכים:
@834 **התועלת** השלש עשרה הוא במצות והוא מה שצוה שבשנת השמטה בחג הסוכות בבא כל ישראל לראות את פני יי' יתברך יקהילו העם במקום הבחירת האנשים והנשים והטף ויקרא שם התורה באזניהם המלך או הכהן הגדול או הנשיא שבישראל כי הוא יכבדוהו העם וייראו ממנו ומדבריו עם היותו מוכן ומעותד אל הנבואה יותר מזולתו ככל ההמון והיותו הוא העבוד לפני השם יתעלה והיותו המורה התורה לישראל כמו שנאמ' יורו משפטיך ליעקב ותורתך לישראל והנה התועלת בזאת המצוה הוא כדי שישמעו וילמדו ליראה את יי' ושמרו לעשות את כל דברי התורה הזאת ויתחנכו בזה גם כן הקטנים כל אחד לפי ענינו ולפי שראינו שהמלך מצווה בו כל ימי חייו לזה התכלית בעינו הנה ידמה כי כאשר היה שם מלך הוא הקורא ועומד במקום גבוה כדי שישמעוהו העם ואולם היה זה בשנת השמטה כי היא קדש והוא בעצמו מורה על מציאות הש' יתעלה כמו שביארנו ובחג הסוכות ממנה כי בו היתה הישרה נפלאה אל השגת השם יתעלה יותר משאר המועדים עם שאז נאספו רוב הפירות ויהיה אז מפני זה ימי הבעיטה ולזה הוצרכו יותר אל מה שיישירם ליראת השם יתעלה:
@834 **התועלת** הארבע עשרה הוא מה שהפליג לחזק לב יהושע ולב העם עד שבעבור שיחזק לבו יותר באה הנבואה אז למשה לצוותו ולהבטיחו כי השם יתע' יהיה עמו כמו שביארנו והיה זה גם כן כי אף על פי שהשם יתע' יוכל לעשות על דרך המופת כל אשר חפץ הנה לא ישתדל השם יתעלה על כל פנים בעשיית המופתים אלא במקומות הראויים ולזה יבקש על הרוב הסבות הנאותות במה שיעשהו והוא ידוע' כי מורך הלב הוא מבוא גדול אל הנפילה ביד האויב כאמרו כי נפלה אמתכם עלינו וגם נמוגו כל יושבי הארץ מפנינו ואמר תפול עליהם אימתה ופחד ומפני זה הוא מבואר כי חוזק הלב הוא מבוא גדול לנצוח האויב ולזה הפליג בהזהיר יהושע והעם שיחזק לבם ולא ייראו ולא יחתו ואמר עתה ליהושע מפי הגבורה שהשם יתעלה יהיה עמו לפי מה שהודיעו עתה בפני יהושע שנכנס עמו באהל מועד וראה הראות השכינה בעמוד ענן כדי שיבטח יותר בשם יתעלה ויתחזק לבו:
@834 **התועלת** החמש עשרה הוא להודיע מין אחר מהעונש זולת המינים הקודמים והוא שיסלק השם יתעלה השגחתו מהמורדים בו ועזבוהו והפרו את בריתו ויהיו נעזבים למקרי הזן כאמרו והסתרתי פני מהם והיה לאכול והנה לנענש בזה האופן יקרו קצת הצלחות מפני ההשגחה הכוללת אך לעת תמוט רגלם יפלו נפילה עצומה ולזה תמצא למלכי ישראל קצת הצלחות עם עשותם הרע בעיני יי' אך לעת תמוט רגלם נשארו מתי מספר ולא היה נשאר מהם דבר לולי השגחת השם יתעלה על האבות:
@834 **התועלת** השש עשרה הוא במצוות והוא מה שצוה השם יתע' לישראל שיכתבו להם את השירה והנה בכלל בזה כתיבת כל התורה והשירה עמה כמו שביארנו ולפי שצוה ללמוד השיר' לכל ישר' שתהיה שגורה בפיהם למדנו שצריך שילמדוה והדברים ק"ו כמו שזכרנו והנה התועלת המגיע מזאת המצוה הוא כדי שיהנה כל אחד מישראל בתורה כאשר יצא לו כי יובן זה לו יותר מפני היות לו התורה בביתו ויהיה זה סבה אל התפשט ידיעת התורה באומה ושלא תעדר התורה מהם בעת מהעתים:
@834 **התועלת** השבע עשרה הוא להודיע כי לא יקרה בעת מהעיתים שתשכח התורה מישראל שנ' כי לא תשכח מפי זרעו וזה יורה עוד על נצחיות התורה:
@834 **התועלת** השמנה עשרה הוא להודיע איך הפליגה התורה להזהיר ישראל מעבוד ע"ז עד שכבר נכפלה ההזהרה והזירוז בה פעמים רבות כדי לשמור ישראל ממה שנפלו בו מהרע כפי היכולת כי כבר משוער אל השם ית' מצד רוע תכונת ישראל שהם מוכנים ליפול בזה הרע ולזה השתדל להצילם מזה לפי מה שאפשר:
@864 **האזינו השמים ואדברה וגו' עד סוף הפרשה:**
@864 **ביאור דברי הפרשה:**
@864 **אמר** האזינו השמים מה שאדבר ותשמע הארץ מה שאומר והנה דבר לאלו להיותם קיימים כמו שאמר ואעידה בם את השמים ואת הארץ הנה לקחי והוא ספור דברי המצוה התוריות יערוף כמטר שהוא יורד טפין טפין רחוקי' זה מזה וכבר יקחו המצוה ממה שכללו מההישרה לתקון הגוף ולתקון הנפש מדרגות רחוקות קצם מקצת אך יקחו קחצת ויניחו קצת. והמשל כי התורה צותה שיאהב האדם לרעהו כמוהו ושלא ישנא את אחיו בלבבו ומה שידמה לזה ממה שנפלה הצואה בו כי התורה נשתקה מהרבה מהתכונות המדותיות אשר יצטרכו למי שירצה להיות שלם במדות וכן הענין במה שהישירה אליו מהדעות במצו' כאלו תאמר שכבר הישירה מזה אל שהש"י הוא אחד והוא משגיח באישי המין האנושי ובכאן עניני' רבים שתקח מהם להיות בלתי ראוי בהם הצווי והאזהרה כמו שביארנו בפתיחת זה הספר ואולם אמרתי והם ספורי התורה תזל כטל אמרתי וזה שהו אינו יורד טפין אך הוא לחות מהפשט בכללות האויר ולזה יחס ירידתו להזלה והוא כמו שהטל הוא מתדבק קצתו בקצתו ואינו מניח באמצעו דבר כן אמרתי תקח מההיישרה במדות ובדעות כל המדרגו' היה שיתכן בהם צווי ואזהרה או שלא יתכן בהם זה וכבר התבאר זה מדברינו בזה הספר ביאור שלם והנה השלים החכמה במשל הזה ואמ' הנה לא תחשוב שלקחי יערוף כמטר אך לא יהיה בו תועלת אבל באמת הנה תועלתו לתת הגדול והחיות למי שיתנהג בו כמו העניין בשערים והם מפי המטר שיפלו עלי עשב כי הם יגדלו אותו וישמרוהו שלא ייבש וימות וכן אמרתי שתזל כטל הנה התועלת בה כתועלת הרביבי' שיפלו עלי דשא שיגדלו אותו ויצמיח אותו והנה הרביבים הם רסיסי לילה והנה התועלת הטל בצמחים מבואר תכלית הביאור והנה היה זה התועלת הנפלא מגיע מלקחי ומאמרי לפי שני קורא שם יי' כי הם יישירו הישרה נפלאה להשיג הש"י כמו שביארנו במה שקדם ולפי שזכר השם ית' אמר לשמים ולארץ תנו גודל לאלהינו אתם אשר ברא אתכם הש' ית' בזה האופן הנפלא אשר אתם בו והנה כולל בהם בריאות השמים והארץ הנה בורא העולם וחלקיו תמיד ימצא פעלו שלם כי כל דרכיו ומנהגיו בפעולותיו הם מסודרים לפי מה שיגזור המשפט והחכמה הוא אל אמת ולא יסודר ממנו עול ואע"פ שאנחנו רואים שהאדם יחטא מצד הכוחו' ששם לו הש"י ביצירתו הנה אין המכוון מאותם הכחו' שיובילו האדם לחטא אבל הם מכוונים בכללם להגיע האדם אל השלמות והמשל כי החושי' הושמו באדם לשמור מציאותו הזמן האפשרי והם עם זה כלי' להגיע האדם אל שלמות האנושי וכן העניין בשאר הכחות הנפשיות כמו שהתבאר בקומותיו ואם הם עם זה סבה במקר' אל החטא הנה אין זה כי אם מרוע בחירת האדם כי האד מושל בבחירתו להטותה אל אשר יחפוץ וכן הענין בכוחו' השופעו' מהככבים כי הש"י שמם כלי' להשגיח באדם ולשמרו הזמן האפשרי לו ואם הם עם זה כלים במקרה להפסדתו הנה הש"י שם הבחיר' לאדם להשתדל להשלי' לו מה שחסר מצד ההשגח' הכוללת וזה כי מצד הבחירה יתכן לו שימלט מהרעו' ההם כמו שביארנו בד' מספר מלחמות יי' והנה הש"י הוא צדיק וישר לא יענוש הנענשים כי אם בצדק וביושר ואמר זה לפי שכבר יחשב שיהיה הש"י סבה אל מה שיחטא האדם בו משני צדדים האחד מצד הטבע ששם באדם אשר הוא נפתה הרבה אל החטאים והשני מצד השפע אשר יושפע מהגרמים השמימיים שיביא לפי מה שאחשוב לתשוקות מה יביאו קצתם האדם אל שיחטא. וכבר התבאר שאין העניין כן במה שאמר שהוא אל אמונה ואין עול ר"ל שאין העול מסודר ממנו בצד מהצדדים כמו שקדם ובהיות העניין כן הוא מבואר כי הדור שהוא עקש ופתלתול לנטות מהדרכים הישרים אל הפעולות המגונות והחטאים הגדולים הוא בעצמו. שחת לו, ר"ל כי מבחירתו בא ההשחת לו וזה כי מומם ופעולותיה' המגוני' אינם בני הש' ית' ר"ל שלא חדשם ה' ולא גזר על חדושם אך מידם היתה זאת הרעה להם והנה אמ' זה לבאר שאין התנצלות לישראל על חטא שלהם כשיאמרו כי מיי' יצא הדבר הזה כי מבחירתם היה להשמר מהחטא כמו שקדם ואח' שביאר שבחירתם תסבב החטאי' לא ה' ית' בא לגנותם על עניין מה שהו' רואה שהם יטו אחרי משה לעבוד עבודה זרה ואמר מגנה אותם על זה אתם עם נבל ולא חכם שהשתמשתם בכחות שברא השם ית' בכם שיובילו במקרה לחטא בעשיית הנבלות הגדולות עד שפתותו מצדם לעבוד ע"ז ולא השתמשתם אל מה שיובילו אליו בעצם והוא השגת החכמה והשלימות האנושי אשר ירחיקו בלא ספק מעבוד ע"ז האם זה הגמול ראוי שתגמלו ולשם ית'. הלא הוא אביך קנך שהוציא אותך מבית עבדים וקנה בזה אתכם לו מצד עוצם הנפלאות שראיתם אז שהביא אתכם אליו כמו שקדם ואיך ראוי שתעזבוהו עם מה שהפליג להטיב לכם ועוד שהוא עשה אותך ויכוננך להביאך לגבול השלמות במה שהרא' לך מהכבוד ומעוצם נפלאותיו בזאת התורה האלהית במה שנתן לך זכור שלא תמרוד בשם ית' הימים הקדומים. בינו שנות דור ודור. מהדורות הקודמים שאל דבר זה אל מנהיגך והוא הנביא ויגד לך האמת. או שאל לך חכמיך ויאמרו לך האמת לפי מה שנודע אליהם מצד הנבי' הנה כשתחקור על זה בזה האופן מהדורות הקודמי' תמצא כי כאשר הנחיל השם ית' גוי' את הארץ בכללה בעת שהפריד בני אדם על דבר בנייתם המגדל אז השתדל השם יתעלה להקים גבולות עמים בהם על מספר בני ישראל אשר נחלו הארץ ההיא ר"ל ארץ שבעה עממין והנה אמ' למספר בני ישראל כי כבר היתה הארי נחלקת למספר בני ישראל אשר נמנו בערבות מואב כמו שקדם ולזה תמצא שייעד השם ית' לאברהם שיתן הארץ ההיא לזרעו ואחר זה ביאר לו שזה הזרע יצא מיצחק לבדו ואחר זה ביאר של זרע יעקב לבד יהיה זה כאלו השם יתעלה כוון בהתחלה להמציא זה הזרע אשר תהיה לו זאת הארץ הנבחרת לפי שחלק השם יתע' לכל האומות שהמציא הוא עמו ישראל ויעקב הוא החלק שהוא לנחלה אל השם יתעלה וכאלו השם יתעלה כיון ממש שיהיה זה החלק מהארץ לזה השבט וזה לזה השבט ובזה הקים גבולות שלהם למספר בני ישראל שהיו י"ב וכבר נתבאר זה ממה שנתנבא יעקב מירושת הארץ לקצת השבטים והנה מצא ישראל את השם יתעלה במדבר שהראה לו שם השם יתעלה אותותיו ומופתיו והיה רוצה להביאו תכף אל הארץ הטובה ואולם בעבור תוהו צעקתם ואנחתם במדבר על דבר המרגלים שהמסו את לבם שהיתה מזולת סבה ראויה שתביאם אל זה אחרם השם יתעלה במדבר ורצה שיסבבו את הר שעיר כל זמן הארוך אשר סבבו אותו וזה גם כן עשה הש' יתעלה להועיל לישראל להשכילם כדי שיכירו וידעו עוצם נפלאות הש' יתעלה שהחיה אותם שם מ' שנה בזולת להם ויין ומבלי בליית מלבושיהם ונעליהם כמו שקדם זה כדי שיהיו יותר ראוי' לירושת הארץ ושם במדבר נצר אותו השם יתעלה בהשגחתו הפרטית כמו שנצר אישון עינו בהשגחתו הכוללת במה שהמציא עליו מהלחויות והכתנות והעפעפים הנה כמו הנשר שמשגיח השגחה עצומה בגדול קנו ושמירתם והוא לבדו מגיעם כאשר ירצה ומביא להם הטרף וזה כי הוא יעיר קנו בבואו עם הטרף להאכילם ואחר זה ינוח על על גוזליו לחממם ולשמרם תחת כנפיו וכאשר ירצה להניעם למקום אחר הנה יפרוש כנפיו ויחק הקן על כנפיו לנשאו על אברתו לא על הנוצה הנמשכת ממנו פן יפול בהכפף הנוצה הנה כמו זה נחה אותם במדבר הש' יתעלה לבדו לתת להם לחם לאכול ובגד ללבוש ושכינתו נחה עליהם בנוחם ובנסעם הניעם השם יתע' והנחה אותם בעמוד אש וענן ואחר זה הרכיבים השם יתעלה על במותי ארץ לתת להם ארץ הגוי' האלה עם תכלית חוזק הרי הארץ ההיא וגובהם וחוזק הערים הנצחרות אשר שם ושם אכל ישראל תנובות שדי עם היותם באותם ההרים שאינם ראויי' על הרוב לנתינת פירות וזה רמז אל השלל הרב אשר מצאו שם והנה הניק אותם דבש מהמקום שהיה בלתי ראוי שיצא ממנו והוא הסלע וחשקה אותם שמן מהמקום שהיה בלתי ראוי שיצא ממנו והוא צור החלמיש ואמנם אמר זה לפי שכבר נתן להם מצד ההשגחה הכוללת והנה האכילם שם כל מיני מעדנים ונתן להם שלל רב מהגוים בכללם מן היותר חזקים עד היותר חלושים והמציא להם פירות הצמחים בתכלית החשיבות והגודל עד שעל צד הגוזמא וההפלגה המשיל גודל גרגיר החטה לגודל הכליות וספר שמן גרגיר הענבים ישתה האדם יין והנה אחר זה זכר הטוב המופלג שהטיב השם יתעלה לישראל הנה כאשר זמן בעט בה' יתעלה המשפיע לו אלו הטובות וזה דבר בתכלית הגנות כי הדבר בעינו אשר הטיב לו בו תעו ומרו בשם יתעלה הנה מפני הפלגת שמנם כאלו נסו לבם ונטשו מפני זה השם יתעלה אשר עשה אותם והביאם אל זה הטוב הנפלא שהביאם בו מצד נתינתו התורה להם ומצד תתו זאת הארץ הנבחרת להם ושמו הש' יתעלה שהוא צור ישועתם לואה מהשפעת הטובות והודעת העתידות ולזה פנו לאלהים אחרי' לחשבם שיהיה יותר טוב להם בעבדם אותם ולזה תמצא ששלח מלך ישראל לדרוש בבעל זבוב אלהי עקרון היהיה מן החולי ההוא הנה הכעיסו השם יתעלה באלהים זרים ובדברים מתועבים ונמאסים לרוב גנותם בעצמם הכעיסו השם יתעלה ולא הספיק זה עד שזבחו זבחים על צד העבודה לדבר שאין לו מציאות כלל ואינו אלוה לאומה מן האומות והוא השדים רוצה לומר הדמיונים והם אלהים שעובדיהם לא ידעום כי אינם דבר שיהיה לו מציאות הנה הם חדשים מקרוב להמציאם לפי מה שבדו מלבם והנה אבותיהם לא דמו אותם דמיונים הנפסדים או לא פחדו מהם לתת להם שום אלהות ואף על פי שאבותיהם הראשונים היו עובדים עבודה זרה הנה לא היה בהם מי שטעה בכמו זה הטעות הנה שכחת הבורא שילדך ושם אותך לו לגוי במה שנתן לך מתורתו השלמה ושכחת האל שיצרך בהתלה לעבוד לו והישירך לקבל השלמות במה שחדש מאותות ומופתים הנפלאים במצרים להודיעך כי הוא ה' והנה ראה השם יתעלה זה הרוע והגנות ומאס מרוב כעסו בניו ובנותיו כי גם הנשים היו ידיהם במעל ההוא כמו שאמר מקטרים למלאכת השמים והסך להנסכים הבלעדי אנשינו עשיו לה כונים להעציבה והסך לה נסכים ואמר השם יתעלה שיסתיר פניו מהם רוצה לומר שיסלק השגחתו מהם לפי שהוא רואה מה אחריתם כי לא יקבלו תוכחת ולזה לא יועיל להם אם יוכיחם על עונם וייסרם וזהו היותר קשה שבמיני העונש כמו שזכר במה שקדם והנה התבאר הש' ית' שלא יקבלו תוכחת לפי שהוא דור תהפוכות שאינו פונה רק לשקר ומה שהוא הפך הראוי עד שלא ימצא בם דבר אמת הם הכעיסו אותי בעבדם אחד שאינו אל מצד מהצדדי' וכעסו אותי באלו החבלים מתועבות הגוים אשר הלכו אחריהם ואני אשלם להם מדה כנגד מדה והו' שכבר אכעיסם ואביא רעות גדולות עליה' ע"י אומה פחותה שאינו ראוי להיו' עם לגנו' פעולותיה' עד שאינו ראוי שישלם בהם הקבוץ המדיני והוא מפני זה גוי בכל כי מרוב חמתי נתלהבה אש ואכלה והשחיתה ישר' עד שהובילה אותם אל חמות לא תרפה מהם והשחיתה הארץ אשר הם יושבים בה בדרך שלא נתנה פרי ולהטה ושרפה מוסדות הערי' הבצורות והחזקות שהיו נבנות בהרי' הנה מרוב כעסי עליה' אביא עליהם מיני רעות כלם וחצי הצרו' אכלה בם שלא ישאר מין אחד שלא אביאנו אליהם כדי שיכירו שזה בא להם מאתי על צד העונש להשיב להם גמול ברוע מעלליהם והנה אלו הם מיני הרעות והחצים שאביא עליהם מיני הרעב ומיני הקדחו' והדבר וחיה וארסי זוחלי העפר והחרב מבית ומחוץ להמית בחור ובתולה ויונק עם איש שיבה מזולת המלה על הבתולה ויונק ואיש השיבה והנה מיני הרעב יגיע מהם היזק שכבר ימס בהם הבשר לחסרון הבשר והם המסו' הרעות והבשרי' דמוקדחי' מאי זה שיהיה ממיני הקדחת ובפרט השורפים והחדים מהם יגיע מהם היזק כי גם בהם ימס הבשר ויובילו אל המות גם כן והדבר שיתחדש בסבת עפושי האויר ההוים מאידים עולים מן הארץ והחיות המזיקות בשניהם בזולת אדם והשרצים הארסיים הנושכים כי אלו יובילו הרבה אל המות והחרב מחוץ ומבית והוא היותר ממית והיותר קשה והנה אלו הרעות אע"פ שכלם יובילו אל המות הנה העניין בא בהם בזה המאמר בהדרגה וזה שמיני הרעב לא ימיתו כי אם באורך זמן ואפשר בקצתם שלא ימיתו אבל יגיע מהם הרזון ואולם הקדחות החדות ימיתו הממיתות מהם בקלות ובמהירות ואפשר בקצתם שיחדשו הרזון לבד ואמנם הדבר ימית תכף כל האנשים הראוים להתפעל מהעפוש ההוא הדבריי והנה אלו הם סוגי הרעות אשר אין התחלתם מזיק. אבל הם מפאת השנויי' במזג פרקי השנה וזכר אחר זה סוגי הרעו' אשר התחלתם הב"ח שהוא מתנועע ללכת ולהזיק מזולת שיהיה התחלתם שינוי המזג והתחיל מהיזק שן החיות שאינם בעלות ארס כי אינו ממית באופן ההמתה שתמשך לנשיכת הנחשי' בעלי ארס ואחר זה זכר היזק המגיע מהבעל שכל כי הוא יותר נפלא להתנועע המזיק אל הנזק בחכמה ובתחבולות ולזה הוא ראוי שימשך הרע מזה נזכר תחלה ההיזק הבא מחוץ לאשר ימצאו שם כי ההיזק ההוא יותר מעטי ועוד זכר ההיזק הבא מהם לאשר בתוך העיר והוא אמות מות אם מפני הרעב שיתחדש בעיר מפני עמדם במצור והשחתת האויב כל יבול הארץ אם מפני יראתם מהאויבי' שיכנסו בעיר להרגם וכאשר תחקור באלו הרעות שזכר נכללו כל מיני הרעות באופן מה ולזה אמר שיכלה מיני הרעות אליהם אמר השם יתעלה אמרתי בלבי לא אביא על ישר' אלו הרעות באופן הנזכר אך אפאה ישראל בכל פאה מרוב הפזור בדרך שיקל לאויבים המשתדלים להרע להם באופן הנזכר להשבית מאנוש זכרם במקום מקום שיקומו עליהם וכבר עשיתי זה לולא יראתי מכעס אויב שישחיתם עד לכלה מה שאינו מכוון מפני בריתי עם האבו' שמא ינכרו צרימו שזה הרע בא לישראל מאתי על אשר לא שמעו בקולי ויהיה זה סבה שישחיתם לגמרי לחשבם כי האמונה שנתיחדו בה ישראל היא נפסדת אך כאשר יראו שהשם יתעלה יביא עליהם תחלה אלו הרעות קודם שישתדלו האויבים להרע להם ויתפרסם להם התוכחות שיוכיחם השם יתעלה על ידי נביאיו והודיעו להם תחלה זה הרע שיפלו בו אם לא ישובו אל השם אז יתפרסם לאויב כי מאת השם היה הדבר באמרו ואמרו כל הגוים על מה עשה השם ככה לארץ הזאת ומה חרי האף הגדול הזה ואמרו על אשר עזבו את ברית השם אלהי אבותם ולזה תמצא שאמר בספר ירמיהו על נפילת ירושלים ביד מלך בבל ויקח שר הטבחים לירמיהו ויאמר ה' אלהיך דבר את הרעה הזאת אל המקום הזה ויבא ויעש יי' כאשר דבר כי חטאתם ליי' ולא שמעתם בקולו והיה לכם הדבר הזה הנה זה היה סבה אל שחמל מלך בבל על הנשאר מהם ולא המיתם כלם לפחדתו מה' ית' פן יקח נקמת עמו ולזה הפקיד עליהם גדליה בן אחיקם לתת שארית ליהודה ממנו כמו שנזכר שם פן יאמרו האויבים לא ה' פעל כל זאת אך ידינו דמה עליהם ועל אלהיהם ולזה לא יוכל לשמור את עצמו מידינו וימשך מזה החלול לשם יתע' עם שזה יהיה סבה שיכלו האויבים ישראל בנפלם בידיהם והנה הייתי מסכים להביא מהרע לישראל בהתחלה בזולת שאכלה עליהם תחלה כל מיני הרעות הנזכרות לפי שאני רואה שעם ישראל הוא באופן מהרועי שלא יקבלו מוסר כי כל עצה היא נאבדת מהם ואין בהם תבונה לחקור בסבות הדברים לפי הראוי ולזה לא יתנו אל לבם בבא הרעות שהם באו עליהם על צד העונש על אשר חטאו להשם ויהיה מפני זה השתדלותי להרע להם בזה האופן לבטלה כאמרו על מה תוכו עוד תוסיפו סרה ואמר לשוא הכתי את בניכם מוסר לא לקחו. לו חכמו ישראל ישכילו עניין זאת ההצלחה אשר אני מביא עליהם עתה בשמרם תורתי מעניין ירושת הארץ ויהיה זה סבה שיבינו לאחריתם מה יהיה אם יסורו מדרכי וזה שהם רואים שאחד מישראל ירדוף אלף מהאויבים ושנים ינוסו רבבה וחיה' להם לחשוב שאין זה מעוצם ידם כי לא יתכן שימשך ממנו אבל הסבה בזה כי צור ישראל מכר אלו הגוים ביד ישראל והסגיר אותם בידם ומזה היה ראוי שישפטו שכמו שעשה זה ה' ית' כנגד הגוי' חתם יוכל לעשות זה כנגד ישראל כמו שיעד להם שיקרה להם אם יסורו מאחריו. כי צורנו. והוא כאשר נתיחדנו אנחנו באמונתנו אשר הוא יוצר הכל הנה אין כמוהו האלוה אשר יחשבוהו צור האומות ההם ואויבינו בעצמם שופטים כן נבוכדנצר לית אלהא דיכיל לחצלא כדנא. ואמרו הפלשתים אוי לנו מי יצילנו מיד האלהים האדירים האלה וגו'. והנה שפטו זה גם כן בבא ארון ה' בשדה פלשתים כמו שנזכר בספ' שופטי' וזה כי נמוסי הגוי' ההם אשר התנהגו בהם ואמונותיהם הם יותר רעים מנימוסי סדום ועמורה וכדעותיהם אשר נתפרסם בתורה עונש שנפלו בו מפני רוע מנהגיהם. והפרי שיגיע מענין מנהגיהם הוא בתכלית המרירו' והרוע וההפסד ואפשר שישוב אמרו כי גוי אובד עיצות המה שב אל האויב ר"ל שהאויב לא תתישב עצה בלבו לעמוד על האמת מאי זה סבה נמשך זה הרע לישראל כי לו חכמו האויבים היו משכילים כי זה הענין הוא מהש"י שמכר ישראל בידם וה' הסגירם כי מזול' זה לא יתכן שיהיה מצד עוצם יד האויב ולא יתכן ג"כ שיהיה זה מצד יתרון כח אלהיהם על אלהי ישר' כי הם בעצמם שופטי' שיש הבדל נפלא בין אלהי ישראל ואלהיהם ולזה היה ראוי שיבינו לאחריתם מה יהיה אם יכעס ה' ית' עליהם בהשחיתם ישראל וייראו מפני זה מהשחתתם בנפלם בידם אלא שזה הגוי אובד עצות הם ואין בהם תבונה שיעמדו בו על אמתת זה הענין ולזה הוצרכתי להביא לישראל אלו הרעות תחלה קודם נפלם ביד אויב ואע"פ שאינם מקבלים מוסר כדי שיתפרסם לאויבי' כי מהש"י נהיה הדבר על מה שחטאו לו ישר' ויהיה זה סבה שייראו מלכלות' פן יקח השם ית' נקמת עמו מהם והביאור הראשון נראה לנו יותר ואולם הנמשך לזה באמרו כי לא כצורנו וגו' כי מגפן סדו' וגו' הוא אחד לשני הפירושים הלא זה הרוע והגנות אשר במנהגי האומות ההם הוא גנוז עמדי וחתום באוצרותי לשמרו להם אל העת הראוי לי להנקם מהרעים האלה על רוע מנהגיהם והוא הרע אשר יתכן שיקרה מצד ההשגח' הכוללת וזה הרע הוא כלי מאתי לשלם להם גמולם הראוי על זה לעת הנכון שתמוט בו רגלם באמרו וגם רשע ליום רעה וזה יהיה כאשר יקרב יום אידם כי הנקם אשר לו יחיש העתידו' למו מהרעו' להביאם קודם עתם ואמנ' יהיה אז להשגחתו על ישראל באמרו אני ה' בעתה אחישנה ר"ל שאני אחיש הרעה על האויבים אצל עתה כאשר יתקרב העת ההיא הנה כאשר ידין ה' עמו לשפטם על רוע מעלליהם אז יתנחם על עבדיו וישיב ידו מהשחיתם בעבור בריתו את האבות וזה אמנם יהיה כאשר יראה באשר אזלת יד ישראל באופן שלא נשאר להם כח ולא נשארו להם קניינים לא בבית ולא בשדה אז יסבב השם יתעלה שיכירו כי העבודה זרה אשר נטו אליה אבותיהם לא תציל אותם בעת רעתם ולזה יאמר להם השם יתעלה אז על יד עבדיו הנביאי' איה האלהות שהלכו אחריהם אבותיהם ואיה העבודה זרה שחסו בה אשר היו אוכלים ישראל מתקרובת הע"ז והיו שותים מהיין שינסכו לשמה יקומו עתה ויעזרוכם האלהות ההם או יהיה לכם למחסה ולמסתור הצור אשר חסיתם בו והיא העבודה זרה שהיא צור לפי מחשבתם וכבר מצאנו שאמר להם השם יתע' זה פעמים רבים בימי השופטים והנביאים. ראו עתה כי אני אני הוא תמיד באופן אחד בלא שנוי ולזה הקמותי את דברי כאשר גזרתי אם תעברו מצותי ותעבדו ע"ז ואין עמדי אל אחר שיעשה האחד רעות והאחד טובות כי אני אמית ואענישם ואני אחייה הנכונים למות בהיותיכם בתכלית השפלות ולזה אתם מוכנים מאד אל הכליון אשמרכם מן המות אשגיח בכם להצילכם ממנו וזהו מה שאמר ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא נעלתים לכלותם מחצתי אתכם בזה הרע הנפלא שהבאתי עליכם וידי תרפינה להשיבכם כקדם בארציכם ולזה הוא מבואר שאין מידי מציל כי אם היה שם אלוה אחר בדרך שיהיה האחד עושה הרעות והאחד עושה הטובות יכול להציל מהרע אשר יביא עושה הרעות ואולם כשנתבאר שאין שם כי אם אלוה אחד וממנו מסודר הטוב והרע נתבאר שאין מידו מציל לעשו' כל אשר יחפוץ כי אני נשבע שאם יגיע העת הראוי שאשנן בו להט חרבי בדרך שיכרות בקלו' והוא כאשר יהיה שלם עון הגוים ההם ואז ראוי שתאחז החרב במשפט לשפוט הגוים ההם על רוע מעלליהם הנה אז אשוב נקם לצדי ולמשנאי אשלם גמול כמעשה ידיהם ואז אקח נקמתי מהם גם כן על מה שהרעו לישראל ולזה ארוה אז חצי מדם האויב וחרבי תאכל בשר מפני דם החלל שהרגו מישראל ומחמס השניה ששבו מהם ומפני ראש הפרעות שפרע האויב לישראל במה שהשבית אותו מעשות המצוה כמו שמצאנו במלכות יון כשיהיה זה שיקום השם יתעלה דם עבדיו שכחו הגוים עמו ישראל כי הוא ישיב נקם לאויבי ישראל על אשר הרעו להם ויטהר טומאת אדמתו וטומאת עמו וזה יהיה בעת קבוץ גליות שיטהרו הארץ ביום בא גוג על אדמת ישראל כמו שזכר זכריה. והנה זכר שכבר בא משה ודבר את כל השירה הזאת באזני העם הוא והושע בן נון והנה היה הושע בן נון לא אז לפה ולמתורגמן כדי להשמיע זה לכל ישראל אמנם רצה השם יתעלה שישתתף יהושע בא פן מה למשה להודעת דברי השירה לישראל כדי שיתישרו יותר ישראל להאמין בדברי יהושע אחרי מות משה והנה קראו אז הושע שלא יחשוב אשר שהוא נשתתף בזאת הנבואה למשה מפני אמרו בפר' שעברה על דברי זאת השירה קרא את יהושע והתיצבו באהל מועד וגו' ולזה קראו הושע להודיע שלא היתה מדרגתו בזה כי אם כמו מדרגתו קודם של שי' ושמנה שנה שהיה שמו הושע כששלחו משה עם המרגלים או הישירה התורה בזה שכבר נתישר יהושע לזאת המדרגה מהעת הראשון שהיה שמו הושע כי הוא היה משרת משה כדי שילמד ממנו תמיד וישלים עצמו במה שלמד ממנו מסודות התורה והחכמה כי לא נתחדש בו עתה היותו נביא אם לא מפני שנתישר לזה קודם כי לא ינבא הש' יתעלה מי שהוא בלתי ראוי לנבואה וכאשר הישירה התורה בזה אל הסבה אשר בעבורה הסכים השם ית' שיזכה יהושע להנחיל את הארץ לישראל והוא מפני מה שנשתנה שמו עליו מהושע ליהושע והוא שלוח המרגלים לתור את ארץ כנען כי אז קרא משה שם להושע בן נון יהושע. ומשם זכה יהושע להנחיל לישראל את הארץ כמו שזכה כלב לרשת את הארץ אשר בא בה וכבר נתבאר זה בראש הספר והנה כאשר כלה משה לדבר את כל הדברים האלה אל כל ישראל והם דברי התורה בכללם אז אמר להם שיו לבבכם לכל הדברים אשר אנכי מעיד בכם היום את השמים ואת הארץ ממה שיקרה לכם מן הרע אם לא תשמרו את כל דברי התורה אתם וזרעכם אחרים ולזה צריך לכם שתצוו את בניכם לשמור לעשות את כל דבר התורה הזאת כדי שיגיעו לכם הברכות הנזכרות ותהיו נשמרים מהקללות וזה כי אלו המצות אשר הש"י מצוה אתכם לשמרם אינו דבר רק אלא יכוון בו תועלת אבל יגיע מהם הנבחר שבתועלות וזה כי הוא בעצמו חייכם הנצחיי' ובו גם כן מהתועל' עוד בדברים הגופים עד שבדבר הזה תאריכו ימי' על האדמה אשר אתם עוברים את הירדן שמה לרשתה שעם היות מושל בדברים בגופיים הנה בו הישרה עצומה בהצלחת נפשית בעצם היום ר"ל בעצם היום שאמר משה לישראל בן מאה ועשרים שנה אנכי היום בו אמ' כל הדברים האלה שקדם זכרם ובו אמר לו הש"י שיעלה על הר העברי' הר נבו ושם יאסף אל עמיו על דבר אשר לא קדש אותו במי מריבה כמו שנאסף אהרן אל עמיו מפני הסבה הזאת ואמר לו שמשם יראה ארץ כנען אשר ה' ית' נותן לבני ישראל אך שם לא יבא והנה רצה משה לראותם לעמוד על הסבה אשר בעבורה נבחרה הארץ הזאת על שאר הארצות הנה זה ביאור מה שצריך לבארו בזאת הפרשה:
@864 ואולם התועלות המגיעות ממנה הם י"ד:
@864 **התועלת** הראשון הוא להודיע פרי התורה ויחס התועלת המגיע מהספורים האלה התוריים אל התועלת המגיע ממצו' התורה ואולם פרי התורה בכללה עם ספוריה ביאר שהוא לתת החיים והגדול למתנהגים בה כמו הענין בשעירים שירדו עלי דשא וכרביבים עלי עשב שיגדלו אותו ויצמחוהו ויתנו לו החיים אשר חי בהם ולזה גם כן אמר כי לא דבר רק הוא מכם כי הוא חייכם ובדבר הזה תאריכו ימים יבאר שאין בתורה דבר ללא תועלת כי תתן לאדם החיים הנצחיים ובה ימשכו מהטובות הגופיות היותר מועיל שבהם להישיר אל הגעת השלמות האנושי עד תכליתו ואולם יחס תועלת המצות התוריות אל תועלת ספורי התורה הוא כיחס עריפת המטר יהיה הטיפות בו רחוקות זו מזו וכן התועלת במצות התוריות לא יקח כי אם מדרגות רחוקות ויעזוב הרבה מהמדרגות האמצעיות לפי שלא יתכן בהם מצוה ואזהרה ואולם הזלת הטל הוא מתדבקת קצתה בקצת' בכללו' האויר וכן מה שיישירו הספורי' במדו' ובדעות יקח כל המדרגות בכללם וכבר התבאר זה מדברנו במה שקדם:
@864 **התועלת** השני הוא להודיע שהמכון בדברי התורה בכללם הוא להשיג ה' ית' לפי מה שאפשר עד שיקראוהו בשם רוצה לומר שיגיע בו קצת ציור בשם יתעלה ומזה הצד יגיע התועלת בתורה כמו שאמ' כי שם ה' אקרא ריצה לומר כל זה הטוב ימשך מהתורה לפי ששם ה' נקרא בה:
@864 **התועלת** הרביעי הוא להודיע שהרע והחטא אינם עלולים מה' יתע' בעצמות וראשונה אבל הרע והחטא הם דברים מתחדשים מצרנו ואחר זה נתאונן עליה ונחשוב שה' יתע' הוא סבת נפילתם כאמרו מה יתאונן אדם חי גבר על חטאיו ולזה אמר בזה המקום שה' ית' אל אמונה ואין עול כי הוא לא יגזור ברע ובחטא אבל אנחנו סבת חדושם ולזה אמר גם כן שחת לו לא בניו מומם כמו שביארנו בביאורנו לדברי זאת הפרשה:
@864 **התועלת** החמישי הוא להודיע מה שהפליג הש' יתע' להשגיח בישראל ולהטיב להם עד שמעת דור הפלגה בהחלק הארץ השתדל השם יתעלה להיות זאת הארץ הנבחרת לישראל ולזה גם כן סבב כאב הנבחר שילך שם והודיעו כי לזרעו יתן את כל הארצות ההם כדי שיהיה הזרע יותר מוכן לירושת הארץ לפי שהש' יתע' בחר לו לעם זה הודע הנבחר מבין שאר האומו' ולזה קדש אותו מלידה ומבטן ומהריון ולזאת הסבה הרבה ג"כ אותות ונפלאו' במדבר כדי שיתקרבו לעבודתו ושם נתן להם תורתו התמימה בזה האופן הנפלא להשלימה לפי מה שאפשר ולפי שנבתאר לשם יתעלה מהתרעומת שנתרעמו על דבר המרגלים במדבר שלא היו ראויים עדיין לירושת הארץ איחר' במדבר עד מ' שנה ולהראותם עוד מעוצם נפלאותיו ולהבינם כי הוא ה' ולזאת הסבה רצה שיהיה חנותם ונסעם שם ע"פ ה' להעיר אותם כי הוא לבדו נחה אותם ונהלם בזאת ההנהגה הנפלא' עד שבזולת לח' ושמלה החי' אותם שם כל זה הזמן הארו':
@864 **התועלת** הששי הוא להודיע שמה שהיה ראוי לישראל להכניעם לעבודת השם יתעלה והוא רבוי הטובה שהשפיע להם במה שהורישם נחלת צבי צבאות גוים ורוב העושר שהגיע להם משלל הגוים ומרבוי תבואות הארץ הוא בעינו שמחו כלי למרוד בו ולעבוד ע"ז כאמרו כרוב לפריו הרבה למזבחות כטוב לארצו הטיבו מצבות ולזה זכר בזה המקום כי כאשר שמן ישראל בעט ונטש אלוה עשהו ושם לואה צור ישועתו מלעשות מה שיחפוץ ולא הספיקו להם תועבות גוים אבל עבדו לדמיונים חדשים באו מקרוב לא ידעום אחד מהקודמים.
@864 **התועלת** השביעי הוא להודיע שאע"פ שהיה ידוע אצל השם יתעלה מרוע תכונת ישראל שלא יקבלו מוסר והנה עם כל זה לא רצה להשליכם מעל פניו תכף להגלות אותם ולהפיץ אותם בארצות כי אולי יתחדש מזה הפסד נפלא לישראל כי זה יביא החושב לחשוב כי ידו הושיעה לו ולא נהיה זאת מאת ה' או אולי יחשוב שאלהיו עשו לו את החיל הזה ומזה יתחדש שיתגבר האויב בכל עוז להשחית ישראל אך בראותו לו מיני הרע שהביא עליהם השם יתעלה תחלה יתיישר לבחון כי מהשם היתה זאת ויירא פן יקרה לו גם כן כעס השם יתעלה אם ישחית בניו וזה מורה על עוצם השגחתו הנמשכת לישראל מצד בריתו עם האבות כי גם בחרות אפם בהם יתחכם שלא ישיגם הכליון למען לא תופר בריתו עם האבו' ולא רצה להביא לישראל מן הרעו' מה שיבחן בו באופן שלם שאינו דבר מגיע במקרה וזהו אמרו אספה עלימו רעות וגו' כמו שביארנו בבאורנו לזא' הפרשה:
@864 **התועלת** השמיני הוא להודיע מום ישראל וגנותם בהתפתותם לעבוד ע"ז ולעזוב עבודת השם יתעלה שהוא מקור חיים והוא שהגוים אע"פ שהם עובדים ע"ז הם כלם משערים כי אין כאלהי ישראל. רוצה לומר שהם בעצמם פלילים כי לא כצורנו צורם כאמרו כי אל כצורנו צורם ואויבינו פלילים:
@864 **התועלת** התשיעי הוא להודיע שהשם יתע' יקח נקם מהרשעים לגמרי אשר אינם כלל תחת ההשגחה הפרטית לעת תמוט רגלם מפאת ההשגחה הכוללת וזהו האופן אשר יביא השם יתעלה הרע בו לשונאי כי אין מדרכו להגיע רע בעצם אם לא מצד מה שהוא טוב כמו שביארנו בד' מספר מ"י ולפי שאין אלו באופן שיהיו ראויים שיגיע להם השם יתעלה רע על דרך התוכחות הנה יהיו נעזבים אל המקרים שיקרו מצד ההשגחה הכוללת ולזה גם כן אמר כל פעל שם למענהו וגם רשע ליום רעה:
@864 **התועלת** העשירי הוא להודיע שבעבור השגחת השם יתעלה על האבו' יסבב כאשר יקרב יום איד שונאי ישרלא למהר ולהחיש העתידות למו מן הרעות כמו שעשה לישראל בצאתם ממצרים שכאשר היה קרוב לקץ החיש השם יתעלה העתידות לבא לשונאיהם והשלים ישראל באופן אל שיהיו ראויים שימהר הקץ בעבורם וזהו אמרו כי קרוב יום אידם וחש עתידות למו ולזאת הסבה אמר אני ה' בעתה אחישנה:
@864 **התועלת** האחד עשרה הוא להודיע שהשם יתעלה לא יסכים לכלות ישראל לגמרי אבל יתנחם על עבדיו ובסוף הענין ירפא מה שמחצו ידיו וישיב נקם לצריו ואז ישבחו גוים עמו בראותם כי השם יתע' יקום דם עבדיו וכבר זכר שהשם יתע' נשבע כי כבר ישיב נקם לצריו להורות על שזה היעוד אי אפשר שלא יהיה בסוף העניין והוא מבואר שזה הדבר לא נהיה עד הנה כי לא שבו בבית שני כי אם נלו' יהודה ובנימן:
@864 **התועלת** השתים עשרה הוא להודיע שאין בכאן שני פועלים יפעל האחד הרעות והאחד הטובות כמו שחשבו קצת הקודמים אבל הכל מסודר מפועל אחד וזה מבואר באלו הרעות אשר יעד השם יתעלה על חדושם והם הבאות על צד ההשגחה ואם אלו הרעות עלולות מהשם יתעלה העושה הטובות הנה בזה יתחייב שיהיו הרעות עלולות ממנו ועוד שאנחנו רואים שהוא גם כן יעד ברעות אשר חדושם הוא מצד ההשגחה הכוללת והיודע הדבר טרם חדושו בעצמות וראשונה הוא הפועל אותו כאמרו מי פעל ועשה קורא הדורות מראש כי לא יתכן שידע זה הפועל מעצמו מה שיעשה אחר אם לא יהיה האחד תחתיו ועלול ממנו וחלה אמר ראו עתה כי אני אני הוא ואין אלהים עמדי אני אמית ואחיה מחצתי ואני ארפא כמו שביארנו בביאורנו לזה הפסוק:
@864 **התועלת** השלש עשרה הוא להודיע שהשם יתעלה אינו מקבל שנוי כלל אבל רצונו הוא תמיד בעניין אחד ולזה מצאנו שמה שיעד בימים הקודמים קיים אותו בימים האחרונים וזהו אמר ראו עתה כי אני אני הוא כמו שביארנו:
@864 **התועלת** הארבע עשרה הוא מה שרמז בזה המקום לתחיית המתים כי לא אמר אני אחייה ואמית אבל אמר אני אמית ואחיה ואמר אחר זה מחצתי ואני ארפא וזה יורה לפי השרשים הכוללים כי כמו שמחץ וידיו תרפאנה אשר מחץ גן ימית ויחיה אשר ימית וכבר נתבאר זה השרש ביאור שלם מדברי הנביאים ומצאנו גם כן באליהו ואלישע שהחיו המתים וידמה שזה המופת יהיה נעשה בעת שירצה השם יתעלה להפוך אל עמים שפה ברורה ויראה להם אז זה המופת הנפלא ע"י מלך המשיח כדי שידעו כלם כי הוא ה' ויכנעו כלם לעבודתו יתעלה:
@916 **וזאת הברכה וגו' עד סוף הספר.**
@916 **ואולם התועלות המגיעות ממנה הם י"ט:**
@916 **התועלת** הראשון הוא להודיע לישראל שמה שהוא ראוי שיתברכו בו הוא מצד התורה אשר קבלוה עליהם לירושה כשנתנה השם יתעלה לישראל בזה האופן הנפלא ולזה הקדים זכירת נתינת התורה לישראל קודם זכירתו ברכותיהם להורות שברכותיהם תהיינה להם מזה הצד לבד יזכו לכל הברכות:
@916 **התועלת** השני הוא לפרסם לישראל מה שעתיד להיות מלך בישראל כשיתקבצו כל זקני ישראל לבקש להם מלך כמו שנזכר בספר שמואל והנה סמכו לענין התורה להורות שבחירת המלך אז תהיה בזה האופן. ר"ל שכבר יזהירוהו שישמור דרכי התורה ולא יטה מהם כמו שנתבאר בתורה ונזכר שם בספר שמואל באופן מה:
@916 **התועלת** השלישי הוא לפרסם כי מצד היותו מלך בישראל יקרה בסוף אל שיגלו ישראל מעל אדמתם כי בזה היה סבה אל שיסורו בני ישראל מאחרי ה' יתעלה ולזהו הוצרך משה להתפלל שיחיה ראובן ואל ימות בעת בא אליו תוקף הצרות עד שכבר ישובו אז למתי מספר ויגלו מעל אדמתם ישגיח השם יתעלה בו ובסיעתו שלא ישיגהו הכליון וזכר תחלה ראובן כי הוא והנטפלים אליו היו ראשונים שגלו מעשרת השבטים וזכר אחרי כן ענין גלות יהודה והורה על אורך זמנו וקושי קבוצו מפני רוב פיזורו בארצות במה שבקש מהשם יתעלה שישמע קול יהודה להביאו אל עמו וכאלו העיר בכאן על החלק המלכות באופן שיהיה גלות יהודה לבדו כמו שהיה הענין בסוף והנה עניין זאת הברכה כלל בזה שני דברים האחד הוא הודעת הרע העתיד להתחדש מזה כדי שיתנו זה ישראל אל לבם ולא יפנו לשאול להם מלך או לזרז המלכים שלא יסורו מאחרי ה' ולזה ביאר כי הסבה בזה הם חטאיו כאמרו ידיו רב לו והשני הוא התפלה לשם יתעלה שלא יכלו בגלות ושישיבם לאדמתם:
@916 **התועלת** הרביעי הוא להודיע כי שבט לוי לא זכה לזאת המעלה מפני היותם מהשבט אשר היה ממנו משה על צד ההשגחה אליהם מצד הקורבה שהיתה להם עם משה אך זכו אליה מצד היותם מוכנים לזאת המעלה מלידה ומבטן ומהריון ולזה תמצא בשבט לוי שלא הסכימו עם ישראל בענין המסה והמריבה אשר רבו בני ישראל ונסו את יי' ברפידים לראות היש יי' בקרבם אם אין וכן לא חטאו במעשה העגל כמו שהעיד באמרו מי ליי' אלי ויאספו אליו כל בני לוי ולא עוד אלא שכבר הסכימו עם עצמם להתנכר לקרובים ולהרגם אם חטאו במעשה העגל וכבר התבאר שכן היה גם כן בהיותם במצרים כי שם היה אהרן מוכיח את ישראל שיוסרו מעבוד ע"ז כמו שזכר יחזקאל ובהיות הענין כן הנה לא היתה זאת המעלה להם אלא מפני היותם ראויים לה לא מפני הקורבה והאהבה שהיתה להם עם משה ולזה תמצא שלא בחר השם יתעלה להיות לנביא אחד מקרובי משה ולפי שיהושע היה היותר ראוי וכן יש לדעת שאם היה בישראל יותר ראוי משבט לוי היה בוחר אותו השם יתעלה לעבודתו:
@916 **התועלת** החמישי הוא במצות והוא להודיע שאין ראוי לקרוב שיהיה דיין כי הדיין ראוי שיהיה בלתי נוטה לדבר כי אם אל הדין ולזה חוייב בו שלא תהיה שם סבה תביאהו להטות הדין ולפי שכבר הפליג בזה המקום לשבח שבט לוי במה שאין מחק שאר האנשים לנהוג בזה המנהג והוא ההתנכר לקרוביו במשפט ידענו שאין ראוי שיהיה הדיין קרוב כי טבעו ימשכהו לאהבת קרוביו והיא משיכתו להטות הדין אם כשלא יוכל לראות לו חובה אם כשיראה לו חובה אהבתו תכסה פשעיו:
@916 **התועלת** הששי הוא מה שלמדנו מפני הסדור הנמצא במה שזכר מעניין שלמיות שבט לוי מפני שזכר תחלה תומים ואורים ואח"כ זכר הוראתם משפטי השם יתעלה ותורתו לישראל ואח"כ זכר הקטרתם הקטרת במזבח הזהב ואחר כך זכר העלאת העולה וזה כי בזה נתישר לענינים נפלאים מכוונות התורה באלו העבודות והנה הקדים תחלה זכר האורים והתומים להודיע שהתכלית הראשון בעבודה הנכבדת אשר נתנה השם יתעלה לזרע אהרן הוא הגעת הנבואה במה שיצטרך מזה לישראל בכל ענייניהם שהיו על פי השם ולזה הקדים לזכור התומים קודם האורים מה שלא עשה כן במה שקדם כי התומים הולכים מהלך השלמות מהאורים כמו שביארנו במקומו והעיר בזה שהוא מתחיל מהקודם במעלה ואם הוא מאוחר בסדר ואחר כן זכר ענין שלמותם במשפטי התורה ובתורה בכללה להורות לישראל לפי שזה התכלית הנזכר תחלה יגיע באמצעות התכלית הנזכר שנית וזה כי הנבואה לא תגיע כי אם למי שהוא ראוי לה וזה כי השלמות בתורה ובעיון יגיע להם מצד העבודה לשתי סבות האחת היא העבודה בעצמה תישירם לעמוד על סודות נפלאים מחכמת הנמצאות כמו שביארנו במה שקדם והם יעמידום על הרבה מכונות התורה והשנית היא כי מפני המתנות שזכרו בהם מפני זאת העבודה לא תהיה להם טרדה בצרכי הגוף ויהיו תמיד פנוים לעבוד השם יתעלה ולחקור בתורה ובעיון וזה ממה שישירם גם כן לעמוד על סודות החכמה והתורה ואחר כך זכר הקטרתם הקטרת במזבח הזהב להעיר כי מדרגתה מהעבודה הנעשת במזבח החצון הוא מדרגת השלמות והצורה וכבר התבאר במה שנתנו מסבות אלו הדברים ואחר זכר הכליל לבד מהדברים הנעשים במזבח החיצון כי הוא הולך מדרגת השלמות משאר הדברים הנעשים שם והוא בעצמותו מישיר להגעת הנבואה אל הראוי לה באופן נפלא כמו שהתבאר מדברינו במה שקדם:
@916 **התועלת** השביעי הוא להודיע שהוא ראוי לכל מי שיש לו חלק מהשלמות האנושי שישלים בו זולתו כי זה הוא דרך השם יתע' להשגיח בהשלמת הנמצאות בזה האופן עד שלא יקצר מהגיע להם שלמות אפשר שיקבלוהו ולזה אמר יורו משפטיך ליעקב ותורתך לישראל כאלו אמר ידעו משפטיך ותורתך להורות כי אחר שידע אותם הם מחוייבים להורות לישראל:
@916 **התועלת** השמיני הוא להודיע שכבר נתפרסם ונודע למשה בנבואה מה שהגיע לכהנים בבית שני מהמלחמות ולזה התפלל עליהם שינצחו אויביהם וכבר נתקיים זה לה אז כמו שנתפרסם מדבר מלחמות החשמונים:
@916 **התועלת** התשיעי הוא להודיע שכבר נתפרסם ונודע למשה בנבואה מה שהגיע מהארץ לשבט שבט וזה מבואר ממה שנזכר מנחלת בנימין ובני יוסף וזבולון ויששכר ודן ונפתלי ואשר ולזה יחוייב שנודה שמה שהגיע על פי הגורל לשבט שבט הוא היה הראוי לו לפי מה שגזר השם יתעלה ולזה יתבאר שמיי' כל משפט הגורל:
@916 **התועלת** העשירי הוא מה שהעיר כי כבר יהיה לגדול שבמנהיגים שיצאו מבני יוסף ההדר ואע"פ שיצאו מבניו מנהיגים ומלכים רבים הנה זה ייוחד מכלם כי הוא ינגח עמים יחדיו על קצות הארץ וזה יהיה משיח בן יוסף אשר יבא תחילה ויצליח הצלחות עצומות למען לא תגדל תפארת בית דוד ויושב ירושלם על איש יהודה כמו שנזכר בספר זכריה ואמר שאלו המנהיגים שיצאו מבני יוסף הם רבבות אפרים והם אלפי מנשה ר"ל שבזה יהיה גודל אפרים על מנשה לא במספר כי מספר בני מנשה יהיה יותר רב מכל המספרים שנמנו ותמצא גם כן בספר יהושע שאמר מטה מנשה ליהושע למה נתתי לי גודל אחד וחבל אחד ואני עם רב אשר עד כה ברכני יי' והנה כשתחקור תמצא שכבר יצאו מנהיגים רבים ומושלים משבט אפרים ומשבט מנשה אך הגדול שבמנהיגים ההם והוא הנקרא בכור שור ייוחד מהשאר שהוא ינגח יחדיו אפסי ארץ מה שלא עשה אחד מן הראשונים:
@916 **התועלת** האחת עשרה הוא להודיע שהש' יתעלה הוא המנהיג כל הגלגלים ומניע אותם בכללות ואינו אחד מהמניעים המיוחדים אשר יניעו גלגל מיוחד כמו שחשב הפילוסוף ולזה אמר אין כאל ישורון רוכב שמים באר שבזה העניין יתבאר ייחוד השם יתעלה משאר השכלים הנבדלים המניעים והנה זה כן לפי שכל אחד מהם מניע מיוחד לאחד מהגלגלים ולזה לא ידעו מנימוס הנמצאות וסדרם וישרם כי אם מעט כמו שבארנו בחמישי מספר מלחמו ואולם ה' יתע' הוא על כולם והוא יודע הכל והם לו כמו כלים ומשרתים לעשו' רצונו:
@916 **התועלת** השתי' עשרה הוא להודיע שבעניין חדוש השחקי' בעצמם כאמרו תרקיע עמו לשחקי' חזקים כראי מוצק ואל זאת ההויה רמז באמרו ובגאותו שחקים ר"ל ברוממות הש"י המציא שחקים ואל זאת ההויה רמז באמרו ויאמר אלהים יהי רקיע והשני הוא שומו אותם במדרגת המעון והנושא לאלהי קדם והם המלאכים שברא ביום ראשון שהם ברואי' קודם הרקיע וזה היה כשיתנועעו מהם מעצם ציורם וזאת ההוויה השנית רמז אליה באמרו ויקרא אלהים לרקיע שמים ר"ל ששמם מתנועעים מהמלאכ' שנבראו ביום ראשון זאת התנועה הסבובית אשר להם ולפי שזאת התנועה תחייב שיהיו שם ב' נקודות מתנועעות הם כדמיון קוטבים הנה קרא הגלגלים שמים מפני אלו התנועות שימשכו מהם ברקיע שני מקומות ידמה שירמוז אליהם ויאמר לכל אחד מהם שהו' שם מורה על המקו' ואמנם ההוייה השלישית והוא היותר נפלאה היא מה שחדש בשחקים מהמאורות הכוכבים באופן שיפע מהם כזה העולם השפל מה שיהיו בו השחקי' זרועות עולם כי עניין זה השפע הוא נעלם מאוד איך יתכן שיתחייב זה מהגרמים השמימיים מפני היותם משוללים מכל האכויות שיתחייבו מהם:
@916 **התועלת** השלש עשרה הוא להודיע שראוי לבטוח בייעודי הש"י שיבואו כי לו הגבורה והממשלה לעשות מה שירצה ולא יעצרוהו השמים לרכוב אל מה שירצה כי הוא בראם ועשאם וממנו עלול כל מה שישפע מהם ובהיות הענין כן הנה ראוי לישראל שיבטחו במה שיערם מדבר ירושת הארץ ומהשמדת הגוים ההם:
@916 **התועלת** הארבע עשרה הוא להודיע מעלת ישר' ורוממותו על שאר האומות כי אין בהם עם נושע בהשם תשועת עולמים זולתו והוא לו למגן מהרעות הראויות ליפול עליו מפני דבקות השגחתו הפרטית בו:
@916 **התועלת** החמש עשרה הוא להודיע איך נפלא דבר משה בחיים ובמותו עד שכבר מת על פי ה' בלא חולי או חלשה קדמוהו והשם ית' קבר אותו על דרך מופת באופן שלא נגעה בו יד אדם לקברו ולא נודע מקום קברו לאחד מן האנשים ושכבר מת בכמו הרגע שנולד בו עד שכבר היה במותו בן ק"כ שנה בלא פחות ובלא יתר ואמנם היה זה כן לבאר עוצם ההבדל בינו ובין שאר האנשים כי אולי יספק אחד ויאמר ולמה לא יתכן שם נביא אחר נביא תורה כמשה ואיך גזרה התורה שלא תשתנה התורה הזאת לעולם ולא תקבל תוספת ולא חסרון הנה אם כן יהיה זה כח אשר בו תהיות נביא תורה לבטלה הנה התשובה בזה כי אין שם אחר ישוה למשה בזה הענין כי נבואתו זאת התוריית היא נוהגת כמנהג הנפלאות ואין זה כה לנביא במה שהוא נביא אם לא היה זה על דרך פלא והשם יתע' ביאר שאין רצונו לעשות עוד תורה אחרת ולא להוסיף ולא לגרוע תוספת ולא גרעון נצחי ולזה יסור ממנו זה הספר והנה נתיחד בזה משה ולפי שהוא היה עבד ה' בחייו ובמותו וכל מעשיו היו על פי ה' ולזה היה תמיד עם הש' יתעלה עד שהנבואה היה מגעת לו בהקיץ. ואולם התועלות המגיעות מפני היות קבר משה בלתי נודע לאחד מהאנשים כבר זכרנוהו במה שקדם:
@916 **התועלת** השש עשרה הוא להודיע שאין ראוי להתאבל על האדם יותר מראי ואף על פי שהיה גדול המעלה בתכלית מה שאפשר הלא תראה כי משה רבינו עם גודל מעלתו בממשלה וגדולה לא הסכימה התורה שיהיה ימי בכי אבלו כי אם שלשים יום כמספר ימי בני אהרן:
@916 **התועלת** השבע עשרה הוא להודיע שמתנאי הנביא שיהיה חכם ולזה הגיד כי יהושע בן נון היה מלא רוח חכמה כי סמך משה ידיו עליו ומפני זה נתיחד אחר משה רבינו להיות לנביא מפני היותו היותר חכם שבעם והיותר ראוי לנבואה:
@916 **התועלת** השמנה עשרה הוא להודיע ההבדלים שבין משה ובין זולתו משאר הנביאים שיהיו נביאים בישראל לבד והם שלשה האחד כי השם ית' ידעו פנים אל נפים בהקיץ בזולת מראה או חלום ולזה לא יהיה צריך להתבודדות הדמיון מבין שאר כחות הנפש כי השפע שהיה מקבל משה היה משכל ואל שכל בזולת אמצעות כח דמיוני מה שאין כן בשאר הנביאים שיהיו נביאים בישראל והשני הוא כי אותותיו ומופתיו רבו מאד ונתפשטו בעם רב ובארץ רחבה מאד כי כבר נעשו לפרעה ולכל עבדיו ולכל ארצו רזה דבר לא קרה לנביא זולתו מהנביאים שהיו נביאים בישראל לבד והשלישי כי הוא התמיד להראות יד השם ית' החזקה ומוראים גדולים לעיני כל ישראל זמן ארוך אורך נפלא וזה דבר לא יקרה גם כן לזות מהנביאים עם מה שהיה בדברים ההם מהפלא העצום כמו שנתבאר בתורה:
@916 **התועלת** התשע עשרה הוא מה שהעידה התורה באמ' ולא קם נביא עוד בישראל כמשה שכבר יקום נביא אחר כמשה באלו הדברים אשר זכר אך לא יהיה נביא בישראל לבד אבל בישראל ובשאר האומות והוא יחדש' רבוי האותות והמופתים כמשה במקום רחב מאד ולעם רב ויתמיד להראות יד הש"י החזקה והמורא הגדול לעם רב ולפי שלא היה נביא כזה עדיין בשום מקום לאלו הדברים ידענו שזה יהיה משיח בן דוד אשר ירו' ונשא וגבה מאד ויתחדשו על ידו אלו המופתים הנפלאים להפוך אל עמים שפה ברורה לקרא כלם בשם יי' ולעבדו שכם אח' ואז יהיה שלו' בעולם מפני שלא תהיינה שם אמונו' מתחלפות ולזה יכתתו חרבותיהם לאתים וחניתותיהם למזמרות ולא ישאו גוי אל גוי חרב ולא ילמדו עוד מלחמה והיא האבן אשר נרמז אליה בדברי דניאל שמלאה הארץ והיא אשר אמר עליו וביומיהון די מלכייא אינון יקים אלהא שמייא מלכו די לעלמין לא תתחבל ומלכותא לעם אחרן לא תשתבק והוא אשר אמר עליו וליה יהיב שלטן ויקר ומלכו וכל אומייא עממייא ולשנייא ליה יפלחון שלטניה שלטן עלם די לא יעדי ומלכותיה די לא תתחבל. ה' ית' למען רחמיו ימהר יחישה מעשהו למען נראה אמן אמן סלה. ובכאן נשלם הביאור בדברי התורה בכללה והתועלת המגיעות מהם והתהלה לאל אשר עזרנו כרחמיו וכרוב חסדיו ומרומם על כל ברכה ותהלה אמן סלה. והיתה השלמתו בכ"ג לירח שבט של שנת צ"ח לפרט האלף הששי פה בעיר האזוב יכוננה עליון אמן:
@916 פנו מקום אל ליואי / הוא הרלב"ג פרוונצאלי / תורה פירש בלתי מדרש / אין בו דבור בלתי שכלי
@916 לכן כל איש אל יתיאש / את עצמו מן זה הכלי / אל כל שואל מי הפועל / נאמר הוא שר דניאלי
@916 פה ווינציה היפיפיה / האומרה אין לי בת גילי / על יד דופסים בעלי מעשים / ראשם קורנילייא ישראלי
@916 גם הוא סך לפרט הכללי / השיר הביא זמר לוי / השיר הביא זמר לוי / יה סוף לשמו ראשו אלי:
@916 **הגבר הוקם על המלאכה צעיר המחוקקים קור"ניליייו אדי"ל קינד לבית הלוי.**
